BEGIN TRANSACTION;

-- Alert
CREATE TABLE [Alert] (
    [id] INT IDENTITY(1,1) PRIMARY KEY,
    [topicid] INT NULL,
    [ayatcount] INT NULL,
    [ftime] NVARCHAR(200),
    [days] NVARCHAR(200),
    [status] INT NULL
);

-- AlertHistory
CREATE TABLE [AlertHistory] (
    [id] INT IDENTITY(1,1) PRIMARY KEY,
    [alertid] INT,
    [ayatid] INT,
    [date] NVARCHAR(100),
    [surahid] INT
);

-- Juz
CREATE TABLE [Juz] (
    [Juz_ID] INT,
    [Surah_ID] INT,
    [Starting_Verse_ID] INT,
    [Arbabic_Start_Word] NVARCHAR(MAX)
);

-- Quran
CREATE TABLE [Quran] (
    [ID] INT IDENTITY(1,1) PRIMARY KEY,
    [DatabaseID] SMALLINT NOT NULL,
    [SuraID] INT NOT NULL,
    [VerseID] SMALLINT NOT NULL,
    [AyahText] NVARCHAR(MAX) NOT NULL,
    [Pageno] INT
);

-- References
CREATE TABLE [References] (
    [Ref_id] INT IDENTITY(1,1) PRIMARY KEY,
    [Ref_Urdu_Text] NVARCHAR(MAX),
    [Ref_Eng_Text] NVARCHAR(MAX)
);

-- ReferencesIndexe
CREATE TABLE [ReferencesIndexe] (
    [ayah] NVARCHAR(MAX),
    [surah] INT,
    [topic] NVARCHAR(MAX),
    [Ref_id] INT
);

-- Topic
CREATE TABLE [Topic] (
    [id] INT PRIMARY KEY,
    [utext] NVARCHAR(MAX),
    [etext] NVARCHAR(MAX)
);

-- TopicAyat
CREATE TABLE [TopicAyat] (
    [id] INT IDENTITY(1,1) PRIMARY KEY,
    [topicid] INT,
    [ayatid] INT,
    [surahid] INT,
    [readcount] INT,
    [description] NVARCHAR(MAX)
);

-- Translator
CREATE TABLE [Translator] (
    [TranslatorId] INT IDENTITY(1,1) PRIMARY KEY,
    [FullName] NVARCHAR(100),
    [TranslationType] NVARCHAR(MAX)
);

-- Translation
CREATE TABLE [Translation] (
    [TranslationId] INT IDENTITY(1,1) PRIMARY KEY,
    [TranslatorRef] INT NULL,
    [EnglishText] NVARCHAR(MAX),
    [UrduText] NVARCHAR(MAX),
    [SurahRef] INT NOT NULL,
    [AyahRef] INT NOT NULL,
    FOREIGN KEY (TranslatorRef) REFERENCES [Translator](TranslatorId)
);

-- ayah_book_marks
CREATE TABLE [ayah_book_marks] (
    [SuraID] NVARCHAR(50),
    [VerseID] NVARCHAR(50),
    [ArabicName] NVARCHAR(MAX),
    [EnglishName] NVARCHAR(MAX),
    [CurrentDuration] NVARCHAR(50),
    [UrduName] NVARCHAR(MAX),
    [BookMarkName] NVARCHAR(MAX)
);

-- quran_urdu
CREATE TABLE [quran_urdu](
    [DatabaseID] INT,
    [SuraID] INT,
    [VerseID] INT,
    [AyahText] NVARCHAR(MAX)
);

-- reciter
CREATE TABLE [reciter](
    [reciter_Id] INT,
    [Audio_URL] NVARCHAR(MAX),
    [Verse_no] INT,
    [chapter_no] INT
);

-- surahs
CREATE TABLE [surahs](
    [Id] INT,
    [surah_names] NVARCHAR(MAX),
    [surah_Urdu_Names] NVARCHAR(MAX)
);

-- word_by_word
CREATE TABLE [word_by_word](
    [ID] INT,
    [address] NVARCHAR(MAX),
    [chapter] INT,
    [verse] INT,
    [word] INT,
    [arabic] NVARCHAR(MAX),
    [roman_arabic] NVARCHAR(MAX),
    [eng_translation] NVARCHAR(MAX),
    [urdu_translation] NVARCHAR(MAX)
);
