 (16614,3,'Save those who will stand on the right hand.',NULL,74,39),
 (16615,1,'In gardens, they shall ask each other',NULL,74,40),
 (16616,2,'(They will be) in Gardens (of Delight): they will question each other,',NULL,74,40),
 (16617,3,'In gardens they will ask one another',NULL,74,40),
 (16618,1,'About the guilty:',NULL,74,41),
