INSERT INTO quran_urdu (DatabaseID,SuraID,VerseID,AyahText) VALUES (93,1,1,'اللہ کے نام سے شروع جو بہت مہربان رحمت والا'),
 (93,1,2,'سب خوبیاں اللہ کو جو مالک سارے جہان والوں کا،'),
 (93,1,3,'بہت مہربان رحمت والا،'),
 (93,1,4,'روز جزا کا مالک،'),
 (93,1,5,'ہم تجھی کو پوجیں اور تجھی سے مدد چاہیں،'),
 (93,1,6,'ہم کو سیدھا راستہ چلا،'),
 (93,1,7,'راستہ ان کا جن پر تو نے احسان کیا، نہ ان کا جن پر غضب ہوا اور نہ بہکے ہوؤں کا'),
 (93,2,1,'الم (ف۲)'),
 (93,2,2,'وہ بلند رتبہ کتاب (قرآن) کوئی شک کی جگہ نہیں، (ف ۳) اس میں ہدایت ہے ڈر والوں کو (ف۴)'),
 (93,2,3,'وہ جو بے دیکھے ایمان لائیں (ف۵) اور نماز قائم رکھیں (ف۶) اور ہماری دی ہوئی روزی میں سے ہماری میں اٹھائیں- (ف۷)'),
 (93,2,4,'اور وہ کہ ایمان لائیں اس پر جو اے محبوب تمہاری طرف اترا اور جو تم سے پہلے اترا(ف۸) اور آخرت پر یقین رکھیں، (ف۹)'),
 (93,2,5,'وہی لوگ اپنے رب کی طرف سے ہدایت پر ہیں اور وہی مراد کو پہنچنے والے۔'),
 (93,2,6,'بیشک وہ جن کی قسمت میں کفر ہے (ف۱۰) ا نہیں برابر ہے، چاہے تم انہیں ڈراؤ، یا نہ ڈراؤ، وہ ایمان لانے کے نہیں۔'),
 (93,2,7,'اللہ نے ان کے دلوں پر اور کانوں پر مہر کردی اور ان کی آنکھوں پر گھٹاٹوپ ہے، (ف۱۱) اور ان کے لئے بڑا عذاب،'),
 (93,2,8,'اور کچھ لوگ کہتے ہیں (ف۱۲) کہ ہم اللہ اور پچھلے دن پر ایمان لائے اور وہ ایمان والے نہیں،'),
 (93,2,9,'فریب دیا چاہتے ہیں اللہ اور ایمان والوں کو (ف۱۳) اور حقیقت میں فریب نہیں دیتے مگر اپنی جانوں کو اور انہیں شعور نہیں۔'),
 (93,2,10,'ان کے دلوں میں بیماری ہے (ف۱۴) تو اللہ نے ان کی بیماری اور بڑھائی اور ان کے لئے دردناک عذاب ہے، بدلا ان کے جھوٹ کا -(ف۱۵)'),
 (93,2,11,'اوران سے کہا جائے زمین میں فساد نہ کرو، (ف۱۶) تو کہتے ہیں ہم تو سنوارنے والے ہیں،'),
 (93,2,12,'سنتا ہے وہی فسادی ہیں مگر انہیں شعور نہیں،'),
 (93,2,13,'اور جب ان سے کہا جائے ایمان لاؤ جیسے اور لوگ ایمان لائے(ف۱۷) تو کہیں کیا ہم احمقوں کی طرح ایمان لے آئیں (ف۱۸) سنتا ہے وہی احمق ہیں مگر جانتے نہیں - (ف۱۹)'),
 (93,2,14,'اور جب ایمان والوں سے ملیں تو کہیں ہم ایمان لائے اور جب اپنے شیطانوں کے پاس اکیلے ہوں (ف۲۰) تو کہیں ہم تمہارے ساتھ ہیں، ہم تو یونہی ہنسی کرتے ہیں- (ف۲۱)'),
 (93,2,15,'اللہ ان سے استہزاء فرماتا ہے (ف۲۲) (جیسا کہ اس کی شان کے لائق ہے) اور انہیں ڈھیل دیتا ہے کہ اپنی سرکشی میں بھٹکتے رہیں۔'),
 (93,2,16,'یہ لوگ جنہوں نے ہدایت کے بدلے گمراہی خریدی (ف۲۳) تو ان کا سودا کچھ نفع نہ لایا اور وہ سودے کی راہ جانتے ہی نہ تھے -(ف۲۴)'),
 (93,2,17,'ان کی کہاوت اس طرح ہے جس نے آگ روشن کی۔ تو جب اس سے آس پاس سب جگمگا اٹھا اللہ ان کا نور لے گیا اور انہیں اندھیریوں میں چھوڑ دیا کہ کچھ نہیں سوجھتا -(ف۲۵)'),
 (93,2,18,'بہرے، گونگے، ندھے تو وہ پھر آ نے والے نہیں،'),
 (93,2,19,'یا جیسے آسمان سے اترتا پانی کہ ان میں اندھیریاں ہیں اور گرج اور چمک (ف ۲۶) اپنے کانوں میں انگلیاں ٹھونس رہے ہیں، کڑک کے سبب، موت کے ڈر سے (ف ۲۷) اور اللہ کافروں کو، گھیرے ہوئے ہے -(ف۲۸)'),
 (93,2,20,'بجلی یوں معلوم ہوتی ہے کہ ان کی نگاہیں اچک لے جائے گی (ف۲۹) جب کچھ چمک ہوئی اس میں چلنے لگے(ف ۳۰) اور جب اندھیرا ہوا کھڑے رہ گئے اور اللہ چاہتا تو ان کے کان اور آنکھیں لے جاتا (ف۳۱) بیشک اللہ سب کچھ کرسکتا ہے -(ف۳۲)'),
 (93,2,21,'اے لوگو! (ف۳۳) اپنے رب کو پوجو جس نے تمہیں اور تم سے اگلوں کو پیدا کیا، یہ امید کرتے ہوئے، کہ تمہیں پرہیزگاری ملے -(ف۳۴)'),
 (93,2,22,'جس نے تمہارے لئے زمین کو بچھونا اور آسمان کو عمارت بنایا اور آسمان سے پانی اتارا (ف۳۵) تو اس سے کچھ پھل نکالے تمہارے کھانے کو۔ تو اللہ کے لئے جان بوجھ کر برابر والے نہ ٹھہراؤ (ف۳۶)'),
 (93,2,23,'اور اگر تمہیں کچھ شک ہو اس میں جو ہم نے اپنے (اس خاص) بندے (ف۳۷) پر اتارا تو اس جیسی ایک سورت تو لے آؤ (ف ۳۸) اور اللہ کے سوا، اپنے سب حمایتیوں کو بلالو، اگر تم سچے ہو۔'),
 (93,2,24,'پھر اگر نہ لا سکو اور ہم فرمائے دیتے ہیں کہ ہر گز نہ لا سکو گے تو ڈرو اس آگ سے، جس کا ایندھن آدمی اور پتھر ہیں (ف ۳۹) تیار رکھی ہے کافروں کے لئے -(ف۴۰)'),
 (93,2,25,'اور خوشخبری دے، انہیں جو ایمان لائے اور اچھے کام کئے، کہ ان کے لئے باغ ہیں، جن کے نیچے نہریں رواں (ف۴۱) جب انہیں ان باغوں سے کوئی پھل کھانے کو دیا جائے گا، (صورت دیکھ کر) کہیں گے، یہ تو وہی رزق ہے جو ہمیں پہلے ملا تھا (ف۴۲) اور وہ (صورت میں) ملتا جلتا انہیں دیا گیا اور ان کے لئے ان باغوں میں ستھری بیبیاں ہیں (ف۴۳) اور وہ ان میں ہمیشہ رہیں گے -(ف۴۴)'),
 (93,2,26,'بیشک اللہ اس سے حیا نہیں فرماتا کہ مثال سمجھانے کو کیسی ہی چیز کا ذکر فرمائے مچھر ہو یا اس سے بڑھ کر (ف۴۵) تو وہ جو ایمان لائے، وہ تو جانتے ہیں کہ یہ ان کے رب کی طرف سے حق ہے (ف۴۶) رہے کافر، وہ کہتے ہیں ایسی کہاوت میں اللہ کا کیا مقصُود ہے، اللہ بہتیروں کو اس سے گمراہ کرتا ہے (ف۴۷) اور بہتیروں کو ہدایت فرماتا ہے اور اس سے انہیں گمراہ کرتا ہے جو بے حکم ہیں-(ف ۴۸)'),
 (93,2,27,'وہ جو اللہ کے عہد کو توڑ دیتے ہیں (ف۴۹) پکا ہونے کے بعد، اور کاٹتے ہیں اس چیز کو جس کے جوڑنے کا خدا نے حکم دیا ہے اور زمین میں فساد پھیلاتے ہیں (ف۵۰) وہی نقصان میں ہیں۔'),
 (93,2,28,'بھلا تم کیونکر خدا کے منکر ہو گے، حالانکہ تم مردہ تھے اس نے تمہیں جِلایا پھر تمہیں مارے گا پھر تمہیں جِلائے گا پھر اسی کی طرف پلٹ کر جاؤ گے -(ف۵۰-الف)'),
 (93,2,29,'وہی ہے جس نے تمہارے لئے بنایا جو کچھ زمین میں ہے۔ (ف۵۱) پھر آسمان کی طرف استوا (قصد) فرمایا تو ٹھیک سات آسمان بنائے وہ سب کچھ جانتا ہے -(ف۵۲)'),
 (93,2,30,'اور یاد کرو جب تمہارے رب نے فرشتوں سے فرمایا، میں زمین میں اپنا نائب بنانے والا ہوں (ف۵۳) بولے کیا ایسے کو نائب کرے گا جو اس میں فساد پھیلائے گا اور خونریزیاں کرے گا (ف۵۴) اور ہم تجھے سراہتے ہوئے، تیری تسبیح کرتے اور تیری پاکی بولتے ہیں، فرمایا مجھے معلوم ہے جو تم نہیں جانتے-(ف۵۵)'),
 (93,2,31,'اور اللہ تعالیٰ نے آدم کو تمام (اشیاء کے) نام سکھائے (ف۵۶) پھر سب (اشیاء) کو ملائکہ پر پیش کرکے فرمایا سچے ہو تو ان کے نام تو بتاؤ (ف۵۷)'),
 (93,2,32,'بولے پاکی ہے تجھے ہمیں کچھ علم نہیں مگر جتنا تو نے ہمیں سکھایا بے شک تو ہی علم و حکمت والا ہے -(ف۵۸)'),
 (93,2,33,'فرمایا اے آدم بتادے انہیں سب (اشیاء کے) نام جب اس نے (یعنی آدم نے) انہیں سب کے نام بتادیئے (ف۵۹) فرمایا میں نہ کہتا تھا کہ میں جانتا ہوں آسمانوں اور زمین کی سب چھپی چیزیں اور میں جانتا ہوں جو کچھ تم ظاہر کرتے اور جو کچھ تم چھپاتے ہو -(ف۶۰)'),
 (93,2,34,'اور (یاد کرو) جب ہم نے فرشتوں کو حکم دیا کہ آدم کو سجدہ کو تو سب نے سجدہ کیا سوائے ابلیس کے کہ منکر ہوا اور غرور کیا اور کافر ہوگیا- (ف۶۱)'),
 (93,2,35,'اور ہم نے فرمایا اے آدم تو اور تیری بیوی جنت میں رہو اور کھاؤ اس میں سے بے روک ٹوک جہاں تمہارا جی چاہے مگر اس پیڑ کے پاس نہ جانا (ف۶۲) کہ حد سے بڑھنے والوں میں ہوجاؤ گے- (ف۶۳)'),
 (93,2,36,'تو شیطان نے اس سے (یعنی جنت سے) انہیں لغزش دی اور جہاں رہتے تھے وہاں سے انہیں الگ کردیا (ف۶۴) اور ہم نے فرمایا نیچے اترو (ف۶۵) آپس میں ایک تمہارا دوسرے کا دشمن اور تمہیں ایک وقت تک زمین میں ٹھہرنا اور برتنا ہے -(ف۶۶)'),
 (93,2,37,'پھر سیکھ لیے آدم نے اپنے رب سے کچھ کلمے تو اللہ نے اس کی توبہ قبول کی (ف۶۷) بیشک وہی ہے بہت توبہ قبول کرنے والا مہربان۔'),
 (93,2,38,'ہم نے فرمایا تم سب جنت سے اتر جاؤ پھر اگر تمہارے پاس میری طرف سے کوئی ہدایت آئے تو جو میری ہدایت کا پیرو ہوا اسے نہ کوئی اندیشہ نہ کچھ غم -(ف۶۸)'),
 (93,2,39,'اور وہ جو کفر کریں گے اور میری آیتیں جھٹلائیں گے وہ دوزخ والے ہیں، ان کو ہمیشہ اس میں رہنا -'),
 (93,2,40,'اے یعقوب کی اولاد (ف۶۹) یاد کرو میرا وہ احسان جو میں نے تم پر کیا (ف۷۰) اور میرا عہد پورا کرو میں تمہارا عہد پورا کروں گا (ف۷۱) اور خاص میرا ہی ڈر رکھو -(ف۷۲)'),
 (93,2,41,'اور ایمان لاؤ اس پر جو میں نے اتارا اس کی تصدیق کرتا ہوا جو تمہارے ساتھ ہے اور سب سے پہلے اس کے منکر نہ بنو (ف۷۳) اور میری آیتوں کے بدلے تھوڑے دام نہ لو (ف۷۴) اور مجھی سے ڈرو -'),
 (93,2,42,'اور حق سے باطل کو نہ ملاؤ اور دیدہ و دانستہ حق نہ چھپاؤ -'),
 (93,2,43,'اور نماز قائم رکھو اور زکوٰة دو اور رکوع کرنے والوں کے ساتھ رکوع کرو- (ف۷۵)'),
 (93,2,44,'کیا لوگوں کو بھلائی کا حکم دیتے ہو اور اپنی جانوں کو بھولتے ہو حالانکہ تم کتاب پڑھتے ہو تو کیا تمہیں عقل نہیں -(ف۷۶)'),
 (93,2,45,'اور صبر اور نماز سے مدد چاہو اور بیشک نماز ضرور بھاری ہے مگر ان پر (نہیں) جو دل سے میری طرف جھکتے ہیں -(ف۷۷)'),
 (93,2,46,'جنہیں یقین ہے کہ انہیں اپنے رب سے ملنا ہے اور اسی کی طرف پھرنا- (ف۷۸)'),
 (93,2,47,'اے اولاد یعقوب یاد کرو میرا وہ احسان جو میں نے تم پر کیا اور یہ کہ اس سارے زمانہ پر تمہیں بڑائی دی-(ف۷۹)'),
 (93,2,48,'اور ڈرو اس دن سے جس دن کوئی جان دوسرے کا بدلہ نہ ہوسکے گی (ف۸۰) اور نہ (کافر کے لئے) کوئی سفارش مانی جائے اور نہ کچھ لے کر (اس کی) جان چھوڑی جائے اور نہ ان کی مدد ہو- (ف۸۱)'),
 (93,2,49,'اور (یاد کرو) جب ہم نے تم کو فرعون والوں سے نجات بخشی (ف۸۲) کہ وہ تم پر برا عذاب کرتے تھے (ف۸۳) تمہارے بیٹوں کو ذبح کرتے اور تمہاری بیٹیوں کو زندہ رکھتے (ف۸۴) اور اس میں تمہارے رب کی طرف سے بڑی بلا تھی (یا بڑا انعام) (ف۸۵)'),
 (93,2,50,'اور جب ہم نے تمہارے لئے دریا پھاڑ دیا تو تمہیں بچالیا اور فرعون والوں کو تمہاری آنکھوں کے سامنے ڈبو دیا -(ف۸۶)'),
 (93,2,51,'اور جب ہم نے موسیٰ سے چالیس رات کا وعدہ فرمایا پھر اس کے پیچھے تم نے بچھڑے کی پوجا شروع کردی اور تم ظالم تھے -(ف۸۷)'),
 (93,2,52,'پھر اس کے بعد ہم نے تمہیں معافی دی (ف۸۸) کہ کہیں تم احسان مانو -(ف۸۹)'),
 (93,2,53,'اور جب ہم نے موسیٰ کو کتاب عطا کی اور حق و باطل میں تمیز کردینا کہ کہیں تم راہ آؤ -'),
 (93,2,54,'اور جب موسیٰ نے اپنی قوم سے کہا اے میری قوم تم نے بچھڑا بناکر اپنی جانوں پر ظلم کیا تو اپنے پیدا کرنے والے کی طرف رجوع لاؤ تو آپس میں ایک دوسرے کو قتل کردو (ف۹۰) یہ تمہارے پیدا کرنے والے کے نزدیک تمہارے لیے بہتر ہے تو اس نے تمہاری توبہ قبول کی بیشک وہی ہے بہت توبہ قبول کرنے والا مہربان -(ف ۹۱)'),
 (93,2,55,'اور جب تم نے کہا اے موسیٰ ہم ہرگز تمہارا یقین نہ لائیں گے جب تک اعلانیہ خدا کو نہ دیکھ لیں تو تمہیں کڑک نے آلیا اور تم دیکھ رہے تھے ۔'),
 (93,2,56,'پھر مرے پیچھے ہم نے تمہیں زندہ کیا کہ کہیں تم احسان مانو-'),
 (93,2,57,'اور ہم نے ابر کو تمہارا سائبان کیا (ف۹۲) اور تم پر من اور سلویٰ اتارا کھاؤ ہماری دی ہوئی ستھری چیزیں (ف۹۳) اور انہوں نے کچھ ہمارا نہ بگاڑا ہاں اپنی ہی جانوں کو بگاڑ کرتے تھے-(ف۹۴) اور جب ہم نے فرمایا اس بستی میں جاؤ -'),
 (93,2,58,'پھر اس میں جہاں چاہو بے روک ٹوک کھاؤ اور دروازہ میں سجدہ کرتے داخل ہو (ف۹۵) اور کہو ہمارے گناہ معاف ہوں ہم تمہاری خطائیں بخش دیں گے اور قریب ہے کہ نیکی والوں کو اور زیادہ دیں- (ف۹۶)'),
 (93,2,59,'تو ظالموں نے اور بات بدل دی جو فرمائی گئی تھی اس کے سوا (ف۹۷) تو ہم نے آسمان سے ان پر عذاب اتارا (ف۹۸) بدلہ ان کی بے حکمی کا۔'),
 (93,2,60,'اور جب موسیٰ نے اپنی قوم کے لئے پانی مانگا تو ہم نے فرمایا اس پتھر پر اپنا عصا مارو فوراً اس میں سے بارہ چشمے بہ نکلے (ف۹۹) ہر گروہ نے اپنا گھاٹ پہچان لیا کھاؤ اور پیؤ خدا کا دیا (ف۱۰۰) اور زمین میں فساد اٹھاتے نہ پھرو(ف۱۰۱)'),
 (93,2,61,'اور جب تم نے کہا اے موسیٰ (ف۱۰۲) ہم سے تو ایک کھانے پر (ف۱۰۳) ہرگز صبر نہ ہوگا تو آپ اپنے رب سے دعا کیجئے کہ زمین کی اگائی ہوئی چیزیں ہمارے لئے نکالے کچھ ساگ اور ککڑی اور گیہوں اور مسور اور پیاز فرمایا کیا ادنیٰ چیز کو بہتر کے بدلے مانگتے ہو (ف۱۰۴) اچھا مصر (ف۱۰۵) یا کسی شہر میں اترو وہاں تمہیں ملے گا جو تم نے مانگا (ف۱۰۶) اور ان پر مقرر کردی گئی خواری اور ناداری (ف۱۰۷) اور خدا کے غضب میں لوٹے (ف۱۰۸) یہ بدلہ تھا اس کا کہ وہ اللہ کی آیتوں کا انکار کرتے اور انبیاء کو ناحق شہید کرتے (ف۱۰۹) یہ بدلہ تھا ان کی نافرمانیوں اور حد سے بڑھنے کا-'),
 (93,2,62,'بیشک ایمان والے نیز یہودیوں اور نصرانیوں اور ستارہ پرستوں میں سے وہ کہ سچے دل سے اللہ اور پچھلے دن پر ایمان لائیں اور نیک کام کریں ان کا ثواب ان کے رب کے پاس ہے اور نہ انہیں کچھ اندیشہ ہو اور نہ کچھ غم(ف۱۱۰)'),
 (93,2,63,'اور جب ہم نے تم سے عہد لیا (ف۱۱۱) اور تم پر طور کو اونچا کیا (ف۱۱۲) لو جو کچھ ہم تم کو دیتے ہیں زور سے (ف۱۱۳) اور اس کے مضمون یاد کرو اس امید پر کہ تمہیں پرہیزگاری ملے-'),
 (93,2,64,'پھر اس کے بعد تم پھر گئے تو اگر اللہ کا فضل اور اس کی رحمت تم پر نہ ہوتی تو تم ٹوٹے والوں میں ہو جاتے -(ف۱۱۴)'),
 (93,2,65,'اور بیشک ضرور تمہیں معلوم ہے تم میں کے وہ جنہوں نے ہفتہ میں سرکشی کی (ف۱۱۵) تو ہم نے ان سے فرمایا کہ ہوجاؤ بندر دھتکارے ہوئے -'),
 (93,2,66,'تو ہم نے (اس بستی کا) یہ واقعہ اس کے آگے اور پیچھے والوں کے لیے عبرت کردیا اور پرہیزگاروں کے لیے نصیحت-'),
 (93,2,67,'اور جب موسیٰ نے اپنی قوم سے فرمایا خدا تمہیں حکم دیتا ہے کہ ایک گائے ذبح کرو (ف۱۱۶) بولے کہ آپ ہمیں مسخرہ بناتے ہیں (ف۱۱۷) فرمایا خدا کی پناہ کہ میں جاہلوں سے ہوں-(ف۱۱۸)'),
 (93,2,68,'بولے اپنے رب سے دعا کیجئے کہ وہ ہمیں بتادے گائے کیسی کہا وہ فرماتا ہے کہ وہ ایک گائے ہے نہ بوڑھی اور نہ اَدسر بلکہ ان دونوں کے بیچ میں تو کرو جس کا تمہیں حکم ہوتا ہے،'),
 (93,2,69,'بولے اپنے رب سے دعا کیجئے ہمیں بتادے اس کا رنگ کیا ہے کہا وہ فرماتا ہے وہ ایک پیلی گائے ہے جس کی رنگت ڈہڈہاتی دیکھنے والوں کو خوشی دیتی،'),
 (93,2,70,'بولے اپنے رب سے دعا کیجئے کہ ہمارے لیے صاف بیان کردے وہ گائے کیسی ہے بیشک گائیوں میں ہم کو شبہ پڑگیا اور اللہ چاہے تو ہم راہ پا جائیں گے -(ف۱۱۹)'),
 (93,2,71,'کہا وہ فرماتا ہے کہ وہ ایک گائے ہے جس سے خدمت نہیں لی جاتی کہ زمین جوتے اور نہ کھیتی کو پانی دے بے عیب ہے جس میں کوئی داغ نہیں بولے اب آپ ٹھیک بات لائے (ف ۱۲۰) تو اسے ذبح کیا اور (ذبح) کرتے معلوم نہ ہوتے تھے(ف۱۲۱)'),
 (93,2,72,'اور جب تم نے ایک خون کیا تو ایک دوسرے پر اس کی تہمت ڈالنے لگے اور اللہ کو ظاہر کرنا تھا جو تم چھپاتے تھے،'),
 (93,2,73,'تو ہم نے فرمایا اس مقتول کو اس گائے کا ایک ٹکڑا مارو (ف۱۲۲) اللہ یونہی مرُدے جلائے گا۔ اور تمہیں اپنی نشانیاں دکھاتا ہے کہ کہیں تمہیں عقل ہو(ف۱۲۳)'),
 (93,2,74,'پھر اس کے بعد تمہارے دل سخت ہوگئے (ف۱۲۴) تو وہ پتھروں کی مثل ہیں بلکہ ان سے بھی زیادہ کرّے اور پتھروں میں تو کچھ وہ ہیں جن سے ندیاں بہہ نکلتی ہیں اور کچھ وہ ہیں جو پھٹ جاتے ہیں تو ان سے پانی نکلتا ہے اور کچھ وہ ہیں جو اللہ کے ڈر سے گر پڑتے ہیں (ف۱۲۵) اور اللہ تمہارے کوتکوں سے بے خبر نہیں،'),
 (93,2,75,'تو اے مسلمانو! کیا تمہیں یہ طمع ہے کہ یہ (یہودی) تمہارا یقین لائیں گے اور ان میں کا تو ایک گروہ وه تھا کہ اللہ کا کلام سنتے پھر سمجھنے کے بعد اسے دانستہ بدل دیتے، ف۱۲۶)'),
 (93,2,76,'اور جب مسلمانوں سے ملیں تو کہیں ہم ایمان لائے (ف۱۲۷) اور جب آپس میں اکیلے ہوں تو کہیں وہ علم جو اللہ نے تم پر کھولا مسلمانوں سے بیان کیے دیتے ہو کہ اس سے تمہارے رب کے یہاں تمہیں پر حجت لائیں کیا تمہیں عقل نہیں -'),
 (93,2,77,'کیا تم نہیں جانتے کہ اللہ جانتا ہے جو کچھ وہ چھپاتے ہیں اور جو کچھ ظاہر کرتے ہیں-'),
 (93,2,78,'اور ان میں کچھ اَن پڑھ ہیں کہ جو کتاب (ف۱۲۸) کو نہیں جانتے مگر زبانی پڑھ لینا (ف۱۲۹) یا کچھ اپنی من گھڑت اور وہ نرے گمان میں ہیں -'),
 (93,2,79,'تو خرابی ہے ان کے لئے جو کتاب اپنے ہاتھ سے لکھیں پھر کہہ دیں یہ خدا کے پاس سے ہے کہ اس کے عوض تھوڑے دام حاصل کریں (ف۱۳۰) تو خرابی ہے ان کے لئے ان کے ہاتھوں کے لکھے سے اور خرابی ان کے لئے اس کمائی سے-'),
 (93,2,80,'اور بولے ہمیں تو آگ نہ چھوئے گی مگر گنتی کے دن (ف۱۳۱) تم فرمادو کیا خدا سے تم نے کوئی عہد لے رکھا ہے جب تو اللہ ہرگز اپنا عہد خلاف نہ کرے گا (ف۱۳۲) یا خدا پر وہ بات کہتے ہو جس کا تمہیں علم نہیں -'),
 (93,2,81,'ہاں کیوں نہیں جو گناہ کمائے اور اس کی خطا اسے گھیر لے (ف۱۳۳) وہ دوزخ والوں میں ہے انہیں ہمیشہ اس میں رہنا -'),
 (93,2,82,'اور جو ایمان لائے اور اچھے کام کیے وہ جنت والے ہیں انہیں ہمیشہ اس میں رہنا -'),
 (93,2,83,'اور جب ہم نے بنی اسرائیل سے عہد لیا کہ اللہ کے سوا کسی کو نہ پوجو اور ماں باپ کے ساتھ بھلائی کرو، (ف۱۳۴) اور رشتہ داروں اور یتیموں اور مسکینوں سے اور لوگوں سے اچھی بات کہو (ف۱۳۵) اور نماز قائم رکھو اور زکوٰة دو پھر تم پھِر گئے (ف۱۳۶) مگر تم میں کے تھوڑے (ف۱۳۷) اور تم رد گردان ہو-(ف۱۳۸)'),
 (93,2,84,'اور جب ہم نے تم سے عہد لیا کہ اپنوں کا خون نہ کرنا اور اپنوں کو اپنی بستیوں سے نہ نکالنا پھر تم نے اس کا اقرار کیا اور تم گواہ ہو-'),
 (93,2,85,'پھر یہ جو تم ہو اپنوں کو قتل کرنے لگے اور اپنے میں سے ایک گروہ کو ان کے وطن سے نکالتے ہو ان پر مدد دیتے ہو (ان کے مخالف کو) گناہ اور زیادتی میں اور اگر وہ قیدی ہو کر تمہارے پاس آئیں تو بدلا دے کر چھڑا لیتے ہو اور ان کا نکالنا تم پر حرام ہے (ف۱۳۹) تو کیا خدا کے کچھ حکموں پر ایمان لاتے ہو اور کچھ سے انکار کرتے ہو تو جو تم میں ایسا کرے اس کا بدلہ کیا ہے مگر یہ کہ دنیا میں رسوا ہو (ف۱۴۰) اور قیامت میں سخت تر عذاب کی طرف پھیرے جائیں گے اور اللہ تمہارے کوتکوں سے بے خبر نہیں -(ف۱۴۱)'),
 (93,2,86,'یہ ہیں وہ لوگ جنہوں نے آخرت کے بدلے دنیا کی زندگی مول لی تو نہ ان پر سے عذاب ہلکا ہو اور نہ ان کی مدد کی جائے -'),
 (93,2,87,'اور بے شک ہم نے موسیٰ کو کتاب عطا کی (ف۱۴۶) اور اس کے بعد پے در پے رسول بھیجے (ف ۱۴۳) اور ہم نے عیسیٰ بن مریم کو کھیلی نشانیاں عطا فرمائیں (ف۱۴۴) اور پاک روح سے (ف۱۴۵) اس کی مدد کی (ف۱۴۶) تو کیا جب تمہارے پاس کوئی رسول وہ لے کر آئے جو تمہارے نفس کی خواہش نہیں تکبر کرتے ہو تو ان (انبیاء) میں ایک گروہ کو تم جھٹلاتے ہو اور ایک گروہ کو شہید کرتے ہو -(ف۱۴۷)'),
 (93,2,88,'اور یہودی بولے ہمارے دلوں پر پردے پڑے ہیں (ف۱۴۸) بلکہ اللہ نے ان پر لعنت کی ان کے کفر کے سبب تو ان میں تھوڑے ایمان لاتے ہیں- (ف۱۴۹)'),
 (93,2,89,'اور جب ان کے پاس اللہ کی وہ کتاب (قرآن) آئی جو ان کے ساتھ والی کتاب (توریت) کی تصدیق فرماتی ہے (ف۱۵۰) اور اس سے پہلے وہ اسی نبی کے وسیلہ سے کافروں پر فتح مانگتے تھے (ف۱۵۱) تو جب تشریف لایا انکے پاس وہ جانا پہچانا اس سے منکر ہو بیٹھے (ف۱۵۲) تو اللہ کی لعنت منکروں پر -'),
 (93,2,90,'کس برے مولوں انہوں نے اپنی جانوں کو خریدا کہ اللہ کے اتارے سے منکر ہوں (ف۱۵۳) اس کی جلن سے کہ اللہ اپنے فضل سے اپنے جس بندے پر چاہے وحی اتارلے (ف۱۵۴) تو غضب پر غضب کے سزاوار ہوئے (ف۱۵۵) اور کافروں کے لیے ذلت کا عذاب ہے -(ف۱۵۶)'),
 (93,2,91,'اور جب ان سے کہا جائے کہ اللہ کے اتارے پر ایمان لاؤ (ف۱۵۷) تو کہتے ہیں وہ جو ہم پر اترا اس پر ایمان لاتے ہیں (ف۱۵۸) اور باقی سے منکر ہوتے ہیں حالانکہ وہ حق ہے ان کے پاس والے کی تصدیق فرماتا ہوا (ف۱۵۹) تم فرماؤ کہ پھر اگلے انبیاء کو کیوں شہید کیا اگر تمہیں اپنی کتاب پر ایمان تھا -(ف۱۶۰)'),
 (93,2,92,'اور بیشک تمہارے پاس موسیٰ کھلی نشانیاں لے کر تشریف لایا پھر تم نے اس کے بعد (ف۱۶۱) بچھڑے کو معبود بنالیا اور تم ظالم تھے-(ف۱۶۲)'),
 (93,2,93,'اور (یاد کرو) جب ہم نے تم سے پیمان لیا (ف۱۶۳) او ر کوہ ِ طور کو تمہارے سروں پر بلند کیا، لو جو ہم تمہیں دیتے ہیں زور سے اور سنو بولے ہم نے سنا اور نہ مانا اور ان کے دلوں میں بچھڑا رچ رہا تھا ان کے کفر کے سبب تم فرمادو کیا برا حکم دیتا ہے تم کو تمہارا ایمان اگر ایمان رکھتے ہو-(ف۱۶۴)'),
 (93,2,94,'تم فرماؤ اگر پچھلا گھر اللہ کے نزدیک خالص تمہارے لئے ہو، نہ اوروں کے لئے تو بھلا موت کی آرزو تو کرو اگر سچے ہو-(ف۱۶۵)'),
 (93,2,95,'اور ہرگز کبھی اس کی آرزو نہ کریں گے (ف۱۶۶) ان بداعمالیوں کے سبب جو آگے کرچکے (ف۱۶۷) اور اللہ خوب جانتا ہے ظالموں کو-'),
 (93,2,96,'اور بیشک تم ضرور انہیں پاؤ گے کہ سب لوگوں سے زیادہ جینے کی ہوس رکھتے ہیں اور مشرکوں سے ایک کو تمنا ہے کہ کہیں ہزار برس جئے (ف۱۶۸) اور وہ اسے عذاب سے دور نہ کرے گا اتنی عمر دیا جانا اور اللہ ان کے کوتک دیکھ رہا ہے،'),
 (93,2,97,'تم فرمادو جو کوئی جبریل کا دشمن ہو (ف۱۶۹) تو اس (جبریل) نے تو تمہارے دل پر اللہ کے حکم سے یہ قرآن اتارا اگلی کتابوں کی تصدیق فرماتا اور ہدایت و بشارت مسلمانوں کو-(ف۱۷۰)'),
 (93,2,98,'جو کوئی دشمن ہو اللہ اور اس کے فرشتوں اور اس کے رسولوں اور جبریل اور میکائیل کا تو اللہ دشمن ہے کافروں کا (ف۱۷۱)'),
 (93,2,99,'اور بیشک ہم نے تمہاری طرف روشن آیتیں اتاریں (ف۱۷۶) اور ان کے منکر نہ ہوں گے مگر فاسق لوگ -'),
 (93,2,100,'اور کیا جب کبھی کوئی عہد کرتے ہیں ان میں کا ایک فریق اسے پھینک دیتا ہے بلکہ ان میں بہتیروں کو ایمان نہیں -(ف۱۷۳)'),
 (93,2,101,'اور جب ان کے پاس تشریف لایا اللہ کے یہاں سے ایک رسول (ف۱۷۴) ان کی کتابوں کی تصدیق فرماتا (ف۱۷۵) تو کتاب والوں سے ایک گروہ نے اللہ کی کتاب پیٹھ پیچھے پھینک دی (ف۱۷۶) گویا وہ کچھ علم ہی نہیں رکھتے -(ف۱۷۷)'),
 (93,2,102,'اور اس کے پیرو ہوئے جو شیطان پڑھا کرتے تھے سلطنت سلیمان کے زمانہ میں (ف۱۷۸) اور سلیمان نے کفر نہ کیا (ف۱۷۹) ہاں شیطان کافر ہوئے (ف۱۸۰) لوگوں کو جادو سکھاتے ہیں اور وہ (جادو) جو بابل میں دو فرشتوں ہاروت و ماروت پر اترا اور وہ دونوں کسی کو کچھ نہ سکھاتے جب تک یہ نہ کہہ لیتے کہ ہم تو نری آزمائش ہیں تو اپنا ایمان نہ کھو (ف۱۸۱) تو ان سے سیکھتے وہ جس سے جدائی ڈالیں مرد اور اس کی عورت میں اور اس سے ضرر نہیں پہنچا سکتے کسی کو مگر خدا کے حکم سے (ف۱۸۲) اور وہ سیکھتے ہیں جو انہیں نقصان دے گا نفع نہ دے گا اور بیشک ضرور انہیں معلوم ہے کہ جس نے یہ سودا لیا آخرت میں اس کا کچھ حصہ نہیں اور بیشک کیا بری چیز ہے وہ جس کے بدلے انہوں نے اپنی جانیں بیچیں کسی طرح انہیں علم ہوتا- (ف۱۸۳)'),
 (93,2,103,'اور اگر وہ ایمان لاتے (ف۱۸۴) اور پرہیزگاری کرتے تو اللہ کے یہاں کا ثواب بہت اچھا ہے کسی طرح انہیں علم ہوتا -'),
 (93,2,104,'اے ایمان والو! (ف۱۸۵) راعنا نہ کہو اور یوں عرض کرو کہ حضور ہم پر نظر رکھیں اور پہلے ہی سے بغور سنو (ف۱۸۶) اور کافروں کے لئے دردناک عذاب ہے- (ف۱۸۷)'),
 (93,2,105,'وہ جو کافر ہیں کتابی یا مشرک (ف۱۸۸) وہ نہیں چاہتے کہ تم پر کوئی بھلائی اترے تمہارے رب کے پاس سے (ف۱۸۹) اور اللہ اپنی رحمت سے خاص کرتا ہے جسے چاہے اور اللہ بڑے فضل والا ہے -'),
 (93,2,106,'جب کوئی آیت منسوخ فرمائیں یا بھلا دیں (ف۱۹۰) تو اس سے بہتر یا اس جیسی لے آئیں گے کیا تجھے خبر نہیں کہ اللہ سب کچھ کرسکتا ہے-'),
 (93,2,107,'کیا تجھے خبر نہیں کہ اللہ ہی کے لئے ہے آسمانوں اور زمین کی بادشاہی اور اللہ کے سوا تمہارا نہ کوئی حمایتی نہ مددگار،'),
 (93,2,108,'کیا یہ چاہتے ہو کہ اپنے رسول سے ویسا سوال کرو جو موسیٰ سے پہلے ہوا تھا (ف۱۹۱) اور جو ایمان کے بدلے کفر لے (ف۱۹۲) وہ ٹھیک راستہ بہک گیا -'),
 (93,2,109,'بہت کتابیوں نے چاہا (ف۱۹۳) کاش تمہیں ایمان کے بعد کفر کی طرف پھیردیں اپنے دلوں کی جلن سے (ف۱۹۴) بعد اس کے کہ حق ان پر خوب ظاہر ہوچکا ہے تو تم چھوڑو اور درگزر کرو یہاں تک کہ اللہ اپنا حکم لائے بیشک اللہ ہر چیز پر قادر ہے -'),
 (93,2,110,'اور نماز قائم رکھو اور زکوٰة دو (ف۱۹۵) اور اپنی جانوں کے لئے جو بھلائی آگے بھیجو گے اسے اللہ کے یہاں پاؤ گے بیشک اللہ تمہارے کام دیکھ رہا ہے-'),
 (93,2,111,'اور اہل کتاب بولے، ہرگز جنت میں نہ جائے گا مگر وہ جو یہودی یا نصرانی ہو (ف۱۹۶) یہ ان کی خیال بندیاں ہیں تم فرماؤ لا ؤ اپنی دلیل (ف۱۹۷) اگر سچے ہو-'),
 (93,2,112,'ہاں کیوں نہیں جس نے اپنا منہ جھکایا اللہ کے لئے اور وہ نیکو کار ہے (ف۱۹۸) تو اس کا نیگ اس کے رب کے پاس ہے اور انہیں کچھ اندیشہ ہو اور نہ کچھ غم-(ف۱۹۹)'),
 (93,2,113,'اور یہودی بولے نصرانی کچھ نہیں اور نصرانی بولے یہودی کچھ نہیں (ف۲۰۰) حالانکہ وہ کتاب پڑھتے ہیں، (ف۲۰۱) اسی طرح جاہلوں نے ان کی سی بات کہی (ف۲۰۲) تو اللہ قیامت کے دن ان میں فیصلہ کردے گا جس بات میں جھگڑ رہے ہیں-'),
 (93,2,114,'اور اس سے بڑھ کر ظالم کون (ف۲۰۳) جو اللہ کی مسجدوں کو روکے ان میں نامِ خدا لئے جانے سے (ف۲۰۴) اور ان کی ویرانی میں کوشش کرے (ف۲۰۵) ان کو نہ پہنچتا تھا کہ مسجدوں میں جائیں مگر ڈرتے ہوئے ان کے لئے دنیا میں رسوائی ہے (ف۲۰۶) اور ان کے لئے آخرت میں بڑا عذاب - (ف۲۰۷)'),
 (93,2,115,'اور پورب و پچھم سب اللہ ہی کا ہے تو تم جدھر منہ کرو ادھر وجہ اللہ (خدا کی رحمت تمہاری طرف متوجہ) ہے بیشک اللہ وسعت والا علم والا ہے،'),
 (93,2,116,'اور بولے خدا نے اپنے لیے اولاد رکھی پاکی ہے اسے (ف۲۰۸) بلکہ اسی کی مِلک ہے جو کچھ آسمانوں اور زمین میں ہے (ف۲۰۹) سب اس کے حضور گردن ڈالے ہیں،'),
 (93,2,117,'نیا پیدا کرنے والا آسمانوں اور زمین کا (ف۲۱۰) اور جب کسی بات کا حکم فرمائے تو اس سے یہی فرماتا ہے کہ ہو جا وہ فورا ً ہوجاتی ہے-(ف۲۱۱)'),
 (93,2,118,'اور جاہل بولے (ف۲۱۲) اللہ ہم سے کیوں نہیں کلام کرتا (ف۲۱۳) یا ہمیں کوئی نشانی ملے (ف۲۱۴) ان سے اگلوں نے بھی ایسی ہی کہی ان کی سی بات اِن کے اُن کے دل ایک سے ہیں (ف۲۱۵) بیشک ہم نے نشانیاں کھول دیں یقین والوں کے لئے -(ف۲۱۶)'),
 (93,2,119,'بیشک ہم نے تمہیں حق کے ساتھ بھیجا خوشخبری دیتا اور ڈر سناتا اور تم سے دوزخ والوں کا سوال نہ ہوگا -(ف۲۱۷)'),
 (93,2,120,'اور ہرگز تم سے یہود اور نصاری ٰ راضی نہ ہوں گے جب تک تم ان کے دین کی پیروی نہ کرو (ف۲۱۸) تم فرمادو اللہ ہی کی ہدایت ہدایت ہے (ف۲۱۹) اور (اے سننے والے کسے باشد) اگر تو ان کی خواہشوں کا پیرو ہوا بعد اس کے کہ تجھے علم آچکا تو اللہ سے تیرا کوئی بچانے والا نہ ہوگا او ر نہ مددگار (ف۲۲۰)'),
 (93,2,121,'جنہیں ہم نے کتاب دی ہے وہ جیسی چاہئے اس کی تلاوت کرتے ہیں وہی اس پر ایمان رکھتے ہیں اور جو اس کے منکر ہوں تو وہی زیاں کار ہیں -(ف۲۲۱)'),
 (93,2,122,'اے اولاد یعقوب یاد کرو میرا احسان جو میں نے تم پر کیا او ر وہ جو میں نے اس زمانہ کے سب لوگوں پر تمہیں بڑائی دی -'),
 (93,2,123,'اور ڈرو اس دن سے کہ کوئی جان دوسرے کا بدلہ نہ ہوگی اور نہ اس کو کچھ لے کر چھوڑیں اور نہ کافر کو کوئی سفارش نفع دے (ف۲۲۲) اور نہ ان کی مدد ہو -'),
 (93,2,124,'اور جب (ف۲۲۳) ابراہیم کو اس کے رب نے کچھ باتوں سے آزمایا (ف۲۲۴) تو اس نے وہ پوری کر دکھائیں (ف۲۲۵) فرمایا میں تمہیں لوگوں کا پیشوا بنانے والا ہوں عرض کی اور میری اولاد سے فرمایا میرا عہد ظالموں کو نہیں پہنچتا-(ف۲۲۶)'),
 (93,2,125,'اور (یاد کرو) جب ہم نے اس گھر کو (ف۲۲۷) لوگوں کے لئے مرجع اور امان بنایا (ف۲۲۸) اور ابراہیم کے کھڑے ہونے کی جگہ کو نماز کا مقام بناؤ (ف۲۲۹) اور ہم نے تاکید فرمائی ابراہیم و اسماعیل ؑ کو کہ میرا گھر خوب ستھرا کرو طواف کرنے والوں اور اعتکاف والوں اور رکوع و سجود والوں کے لئے -'),
 (93,2,126,'اور جب عرض کی ابراہیم ؑ نے کہ اے میرے رب اس شہر کو امان والا کردے اور اس کے رہنے والوں کو طرح طرح کے پھلوں سے روزی دے جو ان میں سے اللہ اور پچھلے دن پر ایمان لائیں (ف۲۳۰) فرمایا اور جو کافر ہوا تھوڑا برتنے کو اسے بھی دوں گا پھر اسے عذاب ِ دوزخ کی طرف مجبور کردوں گا اور بہت بری جگہ ہے پلٹنے کی-'),
 (93,2,127,'اور جب اٹھاتا تھا ابراہیم ؑ اس گھر کی نیویں اور اسمٰعیل ؑ یہ کہتے ہوئے اے رب ہمارے ہم سے قبول فرما (ف۲۳۱) بیشک تو ہی ہے سنتا جانتا،'),
 (93,2,128,'اے رب ہمارے اور کر ہمیں تیرے حضور گردن رکھنے والا (ف۲۳۲) اور ہماری اولاد میں سے ایک امت تیری فرمانبردار اور ہمیں ہماری عبادت کے قاعدے بتا اور ہم پر اپنی رحمت کے ساتھ رجوع فرما (ف۲۳۳) بیشک تو ہی ہے بہت توبہ قبول کرنے والا مہربان۔'),
 (93,2,129,'اے رب ہمارے اور بھیج ان میں (ف۲۳۴) ایک رسول انہیں میں سے کہ ان پر تیری آیتیں تلاوت فرمائے اور انہیں تیری کتاب (ف۲۳۵) اور پختہ علم سکھائے (ف۲۳۶) اور انہیں خوب ستھرا فرمادے (ف۲۳۷) بیشک تو ہی ہے غالب حکمت والا-'),
 (93,2,130,'اور ابراہیم کے دین سے کون منہ پھیرے (ف۲۳۸) سوا اس کے جو دل کا احمق ہے اور بیشک ضرور ہم نے دنیا میں اسے چن لیا (ف۲۳۹) اور بیشک وہ آخرت میں ہمارے خاص قرب کی قابلیت والوں میں ہے -(ف۲۴۰)'),
 (93,2,131,'جبکہ اس سے اس کے رب نے فرمایا گردن رکھ عرض کی میں نے گردن رکھی اس کے لئے جو رب ہے سارے جہان کا-'),
 (93,2,132,'اور اسی دین کی وصیت کی ابراہیم ؑ نے اپنے بیٹوں کو اور یعقوب نے کہ اے میرے بیٹو! بیشک اللہ نے یہ دین تمہارے لئے چن لیا تو نہ مرنا مگر مسلمان -'),
 (93,2,133,'بلکہ تم میں کے خود موجود تھے (ف۲۴۱) جب یعقوب ؑ کو موت آئی جبکہ اس نے اپنے بیٹوں سے فرمایا میرے بعد کس کی پوجا کروگے بولے ہم پوجیں گے اسے جو خدا ہے آپ کا اور آپ کے آباء ابراہیم ؑ و اسمٰعیل ؑ (ف۲۴۲) و اسحاقؑ کا ایک خدا اور ہم اس کے حضور گردن رکھے ہیں،'),
 (93,2,134,'یہ (ف۲۴۳) ایک امت ہے کہ گزرچکی (ف۲۴۴) ان کے لیے ہے جو انہوں نے کمایا اور تمہارے لئے ہے جو تم کماؤ اور ان کے کاموں کی تم سے پرسش نہ ہوگی-'),
 (93,2,135,'اور کتابی بولے (ف۲۴۵) یہودی یا نصرانی ہوجاؤ راہ پاؤگے تم فرماؤ بلکہ ہم تو ابراہیم ؑ کا دین لیتے ہیں جو ہر باطل سے جدا تھے اور مشرکوں سے نہ تھے -(ف۲۴۶)'),
 (93,2,136,'یوں کہو کہ ہم ایمان لائے اللہ پر اس پر جو ہماری طرف اترا اور جو اتارا گیا ابراہیم ؑ و اسمٰعیل ؑ و اسحاقؑ و یعقوبؑ اور ان کی اولاد پر اور جو عطا کئے گئے موسیٰ ؑ و عیسیٰ ؑ اور جو عطا کئے گئے باقی انبیاء اپنے رب کے پاس سے ہم ان پر ایمان میں فرق نہیں کرتے اور ہم اللہ کے حضور گردن رکھے ہیں-'),
 (93,2,137,'پھر اگر وہ بھی یونہی ایمان لائے جیسا تم لائے جب تو وہ ہدایت پاگئے اور اگر منہ پھیریں تو وہ نری ضد میں ہیں (ف۲۴۷) تو اے محبوب! عنقریب اللہ ان کی طرف سے تمہیں کفایت کرے گا اور وہی ہے سنتا جانتا -(ف۲۴۸)'),
 (93,2,138,'ہم نے اللہ کی رینی (رنگائی) لی (ف۲۴۹) اور اللہ سے بہتر کس کی رینی؟ (رنگائی) اور ہم اسی کو پوجتے ہیں،'),
 (93,2,139,'تم فرماؤ اللہ کے بارے میں جھگڑتے ہو (ف۲۵۰) حالانکہ وہ ہمارا بھی مالک ہے اور تمہارا بھی (ف۲۵۱) اور ہماری کرنی (ہمارے اعمال) ہمارے ساتھ اور تمہاری کرنی (تمہارے اعمال) تمہارے ساتھ اور ہم نِرے اسی کے ہیں- (ف۲۵۲)'),
 (93,2,140,'بلکہ تم یوں کہتے ہو کہ ابراہیم ؑ و اسمٰعیل ؑ و اسحاقؑ و یعقوب ؑ اور ان کے بیٹے یہودی یا نصرانی تھے، تم فرماؤ کیا تمہیں علم زیادہ ہے یا اللہ کو (ف۲۵۳) اور اس سے بڑھ کر ظالم کون جس کے پاس اللہ کی طرف کی گواہی ہو اور وہ اسے چھپائے (ف ۲۵۴) اور خدا تمہارے کوتکوں (برے اعمال) سے بے خبر نہیں-'),
 (93,2,141,'وہ ایک گروہ ہے کہ گزر گیا ان کے لئے ان کی کمائی اور تمہارے لئے تمہاری کمائی اور ان کے کاموں کی تم سے پرسش نہ ہوگی۔'),
 (93,2,142,'اب کہیں گے (ف ۲۵۵) بیوقوف لوگ، کس نے پھیردیامسلمانوں کو، ان کے اس قبلہ سے، جس پر تھے (ف۲۵۶) تم فرمادو کہ پورب پچھم (مشرق مغرب) سب اللہ ہی کا ہے (ف۲۵۷) جسے چاہے سیدھی راہ چلاتا ہے۔'),
 (93,2,143,'اور بات یوں ہی ہے کہ ہم نے تمہیں کیا سب امتوں میں افضل، کہ تم لوگوں پر گواہ ہو (ف۲۵۸) اور یہ رسول تمہارے نگہبان و گواہ (ف۲۵۹) اور اے محبوب!تم پہلے جس قبلہ پر تھے ہم نے وہ اسی لئے مقرر کیا تھا کہ دیکھیں کون رسول کی پیروی کرتا ہے اور کون الٹے پاؤں پھر جاتا ہے۔ (ف۲۶۰) اور بیشک یہ بھاری تھی مگر ان پر، جنہیں اللہ نے ہدایت کی اور اللہ کی شان نہیں کہ تمہارا ایمان اکارت کرے (ف۲۶۱) بیشک اللہ آدمیوں پر بہت مہربان، رحم والا ہے۔'),
 (93,2,144,'ہم دیکھ رہے ہیں بار بار تمہارا آسمان کی طرف منہ کرنا (ف ۲۶۲) تو ضرور ہم تمہیں پھیردیں گے اس قبلہ کی طرف جس میں تمہاری خوشی ہے ابھی اپنا منہ پھیر دو مسجد حرام کی طرف اور اے مسلمانو! تم جہاں کہیں ہو اپنا منہ اسی کی طرف کرو (ف۲۶۳) اور وہ جنہیں کتاب ملی ہے ضرور جانتے کہ یہ انکے رب کی طرف سے حق ہے (ف۲۶۴) اور اللہ ان کے کوتکوں (اعمال) سے بے خبر نہیں-'),
 (93,2,145,'اور اگر تم ان کتابیوں کے پاس ہر نشانی لے کر آ ؤ وہ تمہارے قبلہ کی پیروی نہ کریں گے (ف۲۶۵) اور نہ تم ان کے قبلہ کی پیروی کرو (ف ۲۶۶) اور وہ آپس میں بھی ایک دوسرے کے قبلہ کے تابع نہیں (ف۲۶۷) اور (اے سننے والے کسے باشد) اگر تو ان کی خواہشوں پر چلا بعد اس کے کہ تجھے علم مل چکا تو اس وقت تو ضرور ستم گر ہوگا۔'),
 (93,2,146,'جنہیں ہم نے کتاب عطا فرمائی (ف۲۶۸) وہ اس نبی کو ایسا پہچانتے ہیں جیسے آدمی اپنے بیٹوں کو پہچانتا ہے (ف۲۶۹) اور بیشک ان میں ایک گروہ جان بوجھ کر حق چھپاتے ہیں -(ف۲۷۰)'),
 (93,2,147,'(اے سننے والو) یہ حق ہے تیرے رب کی طرف سے (یا حق وہی ہے جو تیرے رب کی طرف سے ہو) تو خبردار توشک نہ کرنا -'),
 (93,2,148,'اور ہر ایک کے لئے توجہ ایک سمعت ہے کہ وہ اسی طرف منہ کرتا ہے تو یہ چاہو کہ نیکیوں میں اوروں سے آگے نکل جائیں تو کہیں ہو اللہ تم سب کو اکٹھا لے آئے گا (ف ۲۷۱) بیشک اللہ جو چاہے کرے-'),
 (93,2,149,'اور جہاں سے ا ٓ ؤ (ف۲۷۲) اپنا منہ مسجد حرام کی طرف کرو اور وہ ضرور تمہارے رب کی طرف سے حق ہے اور اللہ تمہارے کاموں سے غافل نہیں-'),
 (93,2,150,'اور اے محبوب تم جہاں سے آ ؤ اپنا منہ مسجد حرام کی طرف کرو اور اے مسلمانو! تم جہاں کہیں ہو اپنا منہ اسی کی طرف کرو کہ لوگوں کو تم پر کوئی حجت نہ رہے (ف۲۷۳) مگر جو ان میں ناانصافی کریں (ف۲۷۴) تو ان سے نہ ڈرو اور مجھ سے ڈرو اور یہ اس لئے ہے کہ میں اپنی نعمت تم پر پوری کروں اور کسی طرح تم ہدایت پاؤ،'),
 (93,2,151,'جیسا کہ ہم نے تم میں بھیجا ایک رسول تم میں سے (ف۲۷۵) کہ تم پر ہماری آیتیں تلاوت فرماتا ہے اور تمہیں پاک کرتا (ف۲۷۴) اور کتاب اور پختہ علم سکھاتا ہے (ف۲۷۷) اور تمہیں وہ تعلیم فرماتا ہے جس کا تمہیں علم نہ تھا،'),
 (93,2,152,'تو میری یاد کرو میں تمہارا چرچا کروں گا (ف۲۷۸) اور میرا حق مانو اور میری ناشکری نہ کرو-'),
 (93,2,153,'اے ایمان والو! صبر اور نماز سے مدد چاہو (ف۲۷۹) بیشک اللہ صابروں کے ساتھ ہے -'),
 (93,2,154,'اور جو خدا کی راہ میں مارے جائیں انہیں مردہ نہ کہو (ف۲۸۰) بلکہ وہ زندہ ہیں ہاں تمہیں خبرنہیں-(ف۲۸۱)'),
 (93,2,155,'اور ضرور ہم تمہیں آزمائیں گے کچھ ڈر اور بھوک سے (ف۲۸۲) اور کچھ مالوں اور جانوں اور پھلوں کی کمی سے (ف۲۸۳) اور خوشخبری سنا ان صبر والوں کو -'),
 (93,2,156,'کہ جب ان پر کوئی مصیبت پڑے تو کہیں ہم اللہ کے مال ہیں اور ہم کو اسی کی طرف پھرنا-(ف۲۸۴)'),
 (93,2,157,'یہ لوگ ہیں جن پر ان کے رب کی دروُ دیں ہیں اوررحمت اور یہی لوگ راہ پر ہیں،'),
 (93,2,158,'بیشک صفا اور مروہ (ف۲۸۵) اللہ کے نشانوں سے ہیں (ف۲۸۶) تو جو اس گھر کا حج یا عمرہ کرے اس پر کچھ گناہ نہیں کہ ان دونوں کے پھیرے کرے (ف۲۸۷) اور جو کوئی بھلی بات اپنی طرف سے کرے تو اللہ نیکی کا صلہ دینے خبردار ہے-'),
 (93,2,159,'بیشک وہ جو ہماری اتاری ہوئی روشن باتوں اور ہدایت کو چھپاتے ہیں (ف۲۸۸) بعد اس کے کہ لوگوں کے لئے ہم اسے کتاب میں واضح فرماچکے ہیں ان پر اللہ کی لعنت ہے اور لعنت کرنے والوں کی لعنت -(ف۲۸۹)'),
 (93,2,160,'مگر وہ جو توبہ کریں اور سنواریں اور ظاہر کریں تو میں ان کی توبہ قبول فرماؤں گا اور میں ہی ہوں بڑا توبہ قبول فرمانے والا مہربان،'),
 (93,2,161,'بیشک وہ جنہوں نے کفر کیا اور کافر ہی مرے ان پر لعنت ہے اللہ اور فرشتوں اور آدمیوں سب کی، (ف۲۹۰)'),
 (93,2,162,'ہمیشہ رہیں گے اس میں نہ ان پر سے عذاب ہلکا ہو اور نہ انہیں مہلت دی جائے،'),
 (93,2,163,'اور تمہارا معبود ایک معبود ہے (ف۲۹۱) اس کے سوا کوئی معبود نہیں مگر وہی بڑی رحمت والا مہربان'),
 (93,2,164,'بیشک آسمانوں (ف۲۹۲) اور زمین کی پیدائش اور رات و دن کا بدلتے آنا اور کشتی کہ دریا میں لوگوں کے فائدے لے کر چلتی ہے اور وہ جو اللہ نے آسمان سے پانی اتار کر مردہ زمین کو اس سے جِلا دیا اور زمین میں ہر قسم کے جانور پھیلائے اور ہواؤں کی گردش اور وہ بادل کہ آسمان و زمین کے بیچ میں حکم کا باندھا ہے ان سب میں عقلمندوں کے لئے ضرور نشانیاں ہیں،'),
 (93,2,165,'اور کچھ لوگ اللہ کے سوا اور معبود بنالیتے ہیں کہ انہیں اللہ کی طرح محبوب رکھتے ہیں اور ایمان والوں کو اللہ کے برابر کسی کی محبت نہیں اور کیسے ہو اگر دیکھیں ظالم وہ وقت جب کہ عذاب ان کی آنکھوں کے سامنے آئے گا اس لئے کہ سارا زور خدا کو ہے اور اس لئے کہ اللہ کا عذاب بہت سخت ہے،'),
 (93,2,166,'جب بیزار ہوں گے پیشوا اپنے پیروؤں سے (ف۲۹۳) اور دیکھیں گے عذاب اور کٹ جائیں گی ان کی سب ڈوریں (ف۲۹۴)'),
 (93,2,167,'اور کہیں گے پیرو کاش ہمیں لوٹ کر جانا ہوتا (دنیا میں) تو ہم ان سے توڑ دیتے جیسے انہوں نے ہم سے توڑ دی، یونہی اللہ انہیں دکھائے گا ان کے کام ان پر حسرتیں ہوکر (ف۲۹۵) اور وہ دوزخ سے نکلنے والے نہیں'),
 (93,2,168,'اے لوگوں کھاؤ جو کچھ زمین میں (ف۲۹۶) حلال پاکیزہ ہے اور شیطان کے قدم پر قدم نہ رکھو، بیشک وہ تمہارا کھلا دشمن ہے،'),
 (93,2,169,'وہ تو تمہیں یہی حکم دے گا بدی اور بے حیائی کا اور یہ کہ اللہ پر وہ بات جوڑو جس کی تمہیں خبر نہیں،'),
 (93,2,170,'اور جب ان سے کہا جائے اللہ کے اتارے پر چلو (ف۲۹۷) تو کہیں بلکہ ہم تو اس پر چلیں گے جس پر اپنے باپ دادا کو پایا کیا اگرچہ ان کے باپ دادا نہ کچھ عقل رکھتے ہوں نہ ہدایت (ف۲۹۸)'),
 (93,2,171,'اور کافروں کی کہاوت اس کی سی ہے جو پکارے ایسے کو کہ خالی چیخ و پکار کے سوا کچھ نہ سنے (ف۲۹۹) بہرے، گونگے، اندھے تو انہیں سمجھ نہیں (ف۳۰۰)'),
 (93,2,172,'اے ایمان والو! کھاؤ ہماری دی ہوئی ستھری چیزیں اور اللہ کا احسان مانو اگر تم اسی کو پوجتے ہو (ف۳۰۱)'),
 (93,2,173,'اس نے یہی تم پر حرام کئے ہیں مردار (ف۳۰۲) اور خون (ف۳۰۳) اور سُور کا گوشت (ف۳۰۴) اور وہ جانور جو غیر خدان کا نام لے کر ذبح کیا گیا (ف۳۰۵) تو جو نا چار ہو (ف۳۰۶) نہ یوں کہ خواہش سے کھائے اور نہ یوں کہ ضرورت سے آگے بڑھے تو اس پر گناہ نہیں، بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,2,174,'وہ جو چھپاتے ہیں (ف۳۰۸) اللہ کی کتاب اور اسکے بدلے ذلیل قیمت لیتےہیں وہ اپنے پیٹ میں آگ ہی بھرتے ہیں (ف۳۰۹) اور اللہ قیامت کے دن ان سے بات نہ کرے گا اور نہ انہیں ستھرا کرے، اور ان کے لئے دردناک عذاب ہے،'),
 (93,2,175,'وہ لوگ ہیں جنہوں نے ہدایت کے بدلے گمراہی مول لی اور بخشش کے بدلے عذاب، تو کس درجہ انہیں آگ کی سہار (برداشت) ہے'),
 (93,2,176,'یہ اس لئے کہ اللہ نے کتاب حق کے ساتھ اتاری، اور بے شک جو لوگ کتاب میں اختلاف ڈالنے لگے (ف۳۱۰) وہ ضرور پرلے سرے کے جھگڑالو ہیں،'),
 (93,2,177,'کچھ اصل نیکی یہ نہیں کہ منہ مشرق یا مغرب کی طرف کرو (ف۳۱۱) ہاں اصلی نیکی یہ کہ ایمان لائے اللہ اور قیامت اور فرشتوں اور کتاب اور پیغمبروں پر (ف۳۱۲) اور اللہ کی محبت میں اپنا عزیز مال دے رشتہ داروں اور یتیموں اور مسکینوں اور راہ گیر اور سائلوں کو اور گردنیں چھوڑانے میں (ف ۳۱۳) اور نماز قائم رکھے اور زکوٰة دے اور اپنا قول پورا کرنے والے جب عہد کریں اور صبر والے مصیبت اور سختی میں اور جہاد کے وقت یہی ہیں جنہوں نے اپنی بات سچی کی اور یہی پرہیزگار ہیں،'),
 (93,2,178,'اے ایمان والوں تم پر فرض ہے (ف۳۴۱) کہ جو ناحق مارے جائیں ان کے خون کا بدلہ لو (ف۳۱۵) آزاد کے بدلے آزاد اور غلام کے بدلے غلام اور عورت کے بدلے عورت (ف۳۱۶) تو جس کے لئے اس کے بھائی کی طرف سے کچھ معافی ہوئی۔ (ف۳۱۷) تو بھلائی سے تقا ضا ہو اور اچھی طرح ادا، یہ تمہارے رب کی طرف سے تمہارا بوجھ پر ہلکا کرنا ہے اور تم پر رحمت تو اس کے بعد جو زیادتی کرے (ف۳۱۸) اس کے لئے دردناک عذاب ہے'),
 (93,2,179,'اور خون کا بدلہ لینے میں تمہاری زندگی ہے اے عقل مندو (ف۳۱۹) کہ تم کہیں بچو،'),
 (93,2,180,'تم پر فرض ہوا کہ جب تم میں کسی کو موت آئے اگر کچھ مال چھوڑے تو وصیت کرجائے اپنے ماں باپ اور قریب کے رشتہ داروں کے لئے موافق دستور (ف۳۲۰) یہ واجب ہے پرہیزگاروں پر،'),
 (93,2,181,'تو جو وصیت کو سن سنا کر بدل دے (ف۳۲۱) اس کا گناہ انہیں بدلنے والوں پر ہے (ف۳۲۲) بیشک اللہ سنتا جانتا ہے،'),
 (93,2,182,'پھر جسے اندیشہ ہوا کہ وصیت کرنے والے نے کچھ بے انصافی یا گناہ کیا تو اس نے ان میں صلح کرادی اس پر کچھ گناہ نہیں (ف۳۲۳) بیشک اللہ بخشنے والا مہربان ہے'),
 (93,2,183,'اے ایمان والو! (ف۳۲۴) تم پر روزے فرض کیے گئے جیسے اگلوں پر فرض ہوئے تھے کہ کہیں تمہیں پرہیزگاری ملے، ف۳۲۵)'),
 (93,2,184,'گنتی کے دن ہیں (ف۳۲۶) تو تم میں جو کوئی بیمار یا سفر میں ہو (ف۳۲۷) تو اتنے روزے اور دنوں میں اور جنہیں اس کی طاقت نہ ہو وہ بدلہ دیں ایک مسکین کا کھانا (ف۳۲۸) پھر جو اپنی طرف سے نیکی زیادہ کرے (ف۳۲۹) تو وہ اس کے لئے بہتر ہے اور روزہ رکھنا تمہارے لئے زیادہ بھلا ہے اگر تم جانو (ف۳۳۰)'),
 (93,2,185,'رمضان کا مہینہ جس میں قرآن اترا (ف۳۳۱) لوگوں کے لئے ہدایت اور رہنمائی اور فیصلہ کی روشن باتیں تو تم میں جو کوئی یہ مہینہ پائے، ضرور اس کے روزے رکھے اور جو بیمار یا سفر میں ہو تو اتنے روزے اور دنوں میں اللہ تم پر آسانی چاہتا ہے اور تم پر دشواری نہیں چاہتا اور اس لئے کہ تم گنتی پوری کرو (ف۳۳۲) اور اللہ کی بڑائی بولو اس پر کہ اس نے تمہیں ہدایت کی اور کہیں تم حق گزار ہو،'),
 (93,2,186,'اور اے محبوب جب تم سے میرے بندے مجھے پوچھیں تو میں نزدیک ہوں (ف۳۳۳) دعا قبول کرتا ہوں پکارنے والے کی جب مجھے پکارے (ف۳۳۴) تو انہیں چاہئے میرا حکم مانیں اور مجھ پر ایمان لائیں کہ کہیں راہ پائیں،'),
 (93,2,187,'روزہ کی راتوں میں اپنی عورتوں کے پاس جانا تمہارے لئے حلال ہوا (ف۳۳۵) وہ تمہاری لباس ہیں اور تم ان کے لباس، اللہ نے جانا کہ تم اپنی جانوں کو خیانت میں ڈالتے تھے تو اس نے تمہاری توبہ قبول کی اور تمہیں معاف فرمایا (ف۳۳۶) تو اب ان سے صحبت کرو (ف۳۳۷) اور طلب کرو جو اللہ نے تمہارے نصیب میں لکھا ہو (ف۳۳۸) اور کھاؤ اور پیئو (ف۳۳۹) یہاں تک کہ تمہارے لئے ظاہر ہوجائے سفیدی کا ڈورا سیاہی کے ڈورے سے (پوپھٹ کر) (ف۳۴۰) پھر رات آنے تک روزے پورے کرو (ف۳۴۱) اور عورتوں کو ہاتھ نہ لگاؤ جب تم مسجدوں میں اعتکاف سے ہو (ف۳۴۲) یہ اللہ کی حدیں ہیں ان کے پاس نہ جاؤ اللہ یوں ہی بیان کرتا ہے لوگوں سے اپنی آیتیں کہ کہیں انہیں پرہیزگاری ملے،'),
 (93,2,188,'اور آپس میں ایک دوسرے کا مال ناحق نہ کھاؤ اور نہ حاکموں کے پاس ان کا مقدمہ اس لئے پہنچاؤ کہ لوگوں کا کچھ مال ناجائز طور پر کھاؤ (ف۳۴۳) جان بوجھ کر،'),
 (93,2,189,'تم سے نئے چاند کو پوچھتے ہیں (ف۳۴۴) تم فرمادو وہ وقت کی علامتیں ہیں لوگوں اور حج کے لئے (ف۳۴۵) اور یہ کچھ بھلائی نہیں کہ (ف۳۴۶) گھروں میں پچھیت (پچھلی دیوار) توڑ کر آ ؤ ہاں بھلائی تو پرہیزگاری ہے، اور گھروں میں دروازوں سے آ ؤ (ف۳۴۷) اور اللہ سے ڈرتے رہو اس امید پر کہ فلاح پاؤ'),
 (93,2,190,'اور اللہ کی راہ میں لڑو (ف۳۴۸) ان سے جو تم سے لڑتے ہیں (ف۳۴۹) اور حد سے نہ بڑھو (ف۳۵۰) اللہ پسند نہیں رکھتا حد سے بڑھنے والوں کو،'),
 (93,2,191,'اور کافروں کو جہاں پاؤ مارو (ف۳۵۱) اور انہیں نکال دو (ف۳۵۲) جہاں سے انہوں نے تمہیں نکا لا تھا (ف۳۵۳) اور ان کا فساد تو قتل سے بھی سخت ہے (ف۳۵۴) اور مسجد حرام کے پاس ان سے نہ لڑو جب تک وہ تم سے وہاں نہ لڑیں (ف۳۵۵) اور اگر تم سے لڑیں تو انہیں قتل کرو (ف۳۵۶) کافروں کی یہی سزا ہے،'),
 (93,2,192,'پھر اگر وہ باز رہیں (ف۳۵۷) تو بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,2,193,'اور ان سے لڑو یہاں تک کہ کوئی فتنہ نہ رہے اور ایک اللہ کی پوجا ہو پھر اگر وہ باز آئیں (ف۳۵۸) تو زیادتی نہیں مگر ظالموں پر،'),
 (93,2,194,'ماہ حرام کے بدلے ماہ حرام اور ادب کے بدلے ادب ہے (ف۳۵۹) جو تم پر زیادتی کرے اس پر زیادتی کرو اتنی ہی جتنی اس نے کی اور اللہ سے ڈرتے رہو اور جان رکھو کہ اللہ ڈر والوں کے ساتھ ہے،'),
 (93,2,195,'اور اللہ کی راہ میں خرچ کرو (ف۳۶۰) اور اپنے ہاتھوں، ہلاکت میں نہ پڑو (ف۳۶۱) اور بھلائی والے ہو جاؤ بیشک بھلائی والے اللہ کے محبوب ہیں،'),
 (93,2,196,'اور حج اور عمرہ اللہ کے لئے پورا کرو (ف۳۶۲) پھر اگر تم روکے جاؤ (ف۳۶۳) تو قربانی بھیجو جو میسر آئے (ف۳۶۴) اور اپنے سر نہ منڈاؤ جب تک قربانی اپنے ٹھکانے نہ پہنچ جائے (ف۳۶۵) پھر جو تم میں بیمار ہو یا اس کے سر میں کچھ تکلیف ہے (ف۳۶۶) تو بدلے دے روزے (ف۳۶۷) یا خیرات (ف۳۶۸) یا قربانی، پھر جب تم اطمینان سے ہو تو جو حج سے عمرہ ملانے کا فائدہ اٹھائے (ف۳۶۹) اس پر قربانی ہے جیسی میسر آئے (ف۳۷۰) پھر جسے مقدور نہ ہو تو تین روزے حج کے دنوں میں رکھے (ف۳۷۱) اور سات جب اپنے گھر پلٹ کر جاؤ یہ پورے دس ہوئے یہ حکم اس کے لئے ہے جو مکہ کا رہنے والا نہ ہو (ف۳۷۲) اور اللہ سے ڈرتے رہو اور جان رکھو کہ اللہ کا عذاب سخت ہے،'),
 (93,2,197,'حج کے کئی مہینہ ہیں جانے ہوئے (ف۳۷۳) تو جو ان میں حج کی نیت کرے (ف۳۷۴) تو نہ عورتوں کے سامنے صحبت کا تذکرہ ہو نہ کوئی گناہ، نہ کسی سے جھگڑا (ف۳۷۵) حج کے وقت تک اور تم جو بھلائی کرو اللہ اسے جانتا ہے (ف۳۷۶) اور توشہ ساتھ لو کہ سب سے بہتر توشہ پرہیزگاری ہے (ف۳۷۷) اور مجھ سے ڈرتے رہو اے عقل والو، ف۳۷۸)'),
 (93,2,198,'تم پر کچھ گناہ نہیں (ف۳۷۹) کہ اپنے رب کا فضل تلاش کرو، تو جب عرفات سے پلٹو (ف۳۸۰) تو اللہ کی یاد کرو (ف۳۸۱) مشعر حرام کے پاس (ف۳۸۲) اور اس کا ذکر کرو جیسے اس نے تمہیں ہدایت فرمائی اور بیشک اس سے پہلے تم بہکے ہوئے تھے، ف۳۸۳)'),
 (93,2,199,'پھر بات یہ ہے کہ اے قریشیو! تم بھی وہیں سے پلٹو جہاں سے لوگ پلٹتے ہیں (ف۳۸۴) اور اللہ سے معافی مانگو، بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,2,200,'پھر جب اپنے حج کے کام پورے کرچکو (ف۳۸۵) تو اللہ کا ذکر کرو جیسے اپنے باپ دادا کا ذکر کرتے تھے (ف۳۸۶) بلکہ اس سے زیادہ اور کوئی آدمی یوں کہتا ہے کہ اے رب ہمارے ہمیں دنیا میں دے اور آخرت میں اس کا کچھ حصہ نہیں،'),
 (93,2,201,'اور کوئی یوں کہتا ہے کہ اے رب ہمارے! ہمیں دنیا میں بھلائی دے اور ہمیں آخرت میں بھلائی دے اور ہمیں عذاب دوزخ سے بچا (ف۳۸۷)'),
 (93,2,202,'ایسوں کو ان کی کمائی سے بھاگ (خوش نصیبی) ہے (ف۳۸۸) اور اللہ جلد حساب کرنے والا ہے (ف۳۸۹)'),
 (93,2,203,'اور اللہ کی یاد کرو گنے ہوئے دنوں میں (ف۳۹۰) تو جلدی کرکے دو دن میں چلا جائے اس پر کچھ گنا نہیں اور جو رہ جائے تو اس پر گناہ نہیں پرہیزگار کے لئے (ف۳۹۱) اور اللہ سے ڈرتے رہو اور جان رکھو کہ تمہیں اسی کی طرف اٹھنا ہے،'),
 (93,2,204,'اور بعض آدمی وہ ہیں کہ دنیا کی زندگی میں اس کی بات تجھے بھلی لگے (ف۳۹۲) اور اپنے دل کی بات پر اللہ کو گواہ لائے اور وہ سب سے بڑا جھگڑالو ہے،'),
 (93,2,205,'اور جب پیٹھ پھیرے تو زمین میں فساد ڈالتا پھرے اور کھیتی اور جانیں تباہ کرے اور اللہ فسادسے راضی نہیں'),
 (93,2,206,'اور جب اس سے کہا جائے کہ اللہ سے ڈرو تو اسے اور ضد چڑھے گنا ہ کی (ف۳۹۳) ایسے کو دوزخ کافی ہے اور وہ ضرور بہت برا بچھونا ہے،'),
 (93,2,207,'اور کوئی آدمی اپنی جان بیچتا ہے (ف۳۹۴) اللہ کی مرضی چاہنے میں اور اللہ بندوں پر مہربان ہے،'),
 (93,2,208,'اے ایمان والو! اسلام میں پورے داخل ہو (ف۳۹۵) اور شیطان کے قدموں پر نہ چلے (ف۳۹۶) بیشک وہ تمہارا کھلا دشمن ہے،'),
 (93,2,209,'اور اگر اس کے بعد بھی بچلو کہ تمہارے پاس روشن حکم آچکے (ف۳۹۷) تو جان لو کہ اللہ زبردست حکمت والا ہے،'),
 (93,2,210,'کاہے کے انتظار میں ہیں (ف۳۹۸) مگر یہی کہ اللہ کا عذاب آئے چھائے ہوئے بادلوں میں اور فرشتے اتریں (ف۳۹۹) اور کام ہوچکے اور سب کاموں کی رجوع اللہ کی طرف ہے،'),
 (93,2,211,'بنی اسرائیل سے پوچھو ہم نے کتنی روشن نشانیاں انہیں دیں (ف۴۰۰) اور جو اللہ کی آئی ہوئی نعمت کو بدل دے (ف۴۰۱) تو بیشک اللہ کا عذاب سخت ہے،'),
 (93,2,212,'کافروں کی نگاہ میں دنیا کی زندگی آراستہ کی گئی (ف۴۰۲) اور مسلمانوں سے ہنستے ہیں (ف۴۰۳) اور ڈر والے ان سے اوپر ہوں گے قیامت کے دن (ف۴۰۴) اور خدا جسے چاہے بے گنتی دے،'),
 (93,2,213,'لوگ ایک دین پر تھے (ف۴۰۵) پھر اللہ نے انبیاء بھیجے خوشخبری دیتے (ف۴۰۶) اور ڈر سناتے (ف۴۰۷) اور ان کے ساتھ سچی کتاب اتاری (ف۴۰۸) کہ وہ لوگوں میں ان کے اختلافوں کا فیصلہ کردے اور کتاب میں اختلاف اُنہیں نے ڈالا جن کو دی گئی تھی (ف۴۰۹) بعداس کے کہ ان کے پاس روشن حکم آچکے (ف۴۱۰) آپس میں سرکشی سے تو اللہ نے ایمان والوں کو وہ حق بات سوجھا دی جس میں جھگڑ رہے تھے اپنے حکم سے، اور اللہ جسے چاہے سیدھی راہ دکھائے،'),
 (93,2,214,'کیا اس گمان میں ہو کہ جنت میں چلے جاؤ گے اور ابھی تم پر اگلوں کی سی روداد (حالت) نہ آئی (ف۴۱۱) پہنچی انہیں سختی اور شدت اور ہلا ہلا ڈالے گئے یہاں تک کہ کہہ اٹھا رسول (ف۴۱۲) اور اس کے ساتھ ایمان والے کب آئے گی اللہ کی مدد (ف۴۱۳) سن لو بیشک اللہ کی مدد قریب ہے،'),
 (93,2,215,'تم سے پوچھتے ہیں (ف۴۱۴) کیا خرچ کریں، تم فرماؤ جو کچھ مال نیکی میں خرچ کرو تو و ہ ماں باپ اور قریب کے رشتہ داروں اور یتیموں اور محتاجوں اور راہ گیر کے لئے ہے اور جو بھلائی کرو (ف۴۱۵) بیشک اللہ اسے جانتا ہے (ف۴۱۶)'),
 (93,2,216,'تم پر فرض ہوا خدا کی راہ میں لڑنا اور وہ تمہیں ناگوار ہے (ف۴۱۷) اور قریب ہے کہ کوئی بات تمہیں بری لگے اور وہ تمہارے حق میں بہتر ہو اور قریب ہے کہ کوئی بات تمہیں پسند آئے اور وہ تمہارے حق میں بری ہو اور اللہ جانتا ہے اور تم نہیں جانتے (ف۴۱۸)'),
 (93,2,217,'تم سے پوچھتے ہیں ماہ حرام میں لڑنے کا حکم (ف۴۱۹) تم فرماؤ اس میں لڑنا بڑا گناہ ہے (ف۴۲۰) اور اللہ کی راہ سے روکنا اور اس پر ایمان نہ لانا اور مسجد حرام سے روکنا، اور اس کے بسنے والوں کو نکال دینا (ف۴۲۱) اللہ کے نزدیک یہ گناہ اس سے بھی بڑے ہیں اور ان کا فساد (ف۴۲۲) قتل سے سخت تر ہے (ف۴۲۳) اور ہمیشہ تم سے لڑتے رہیں گے یہاں تک کہ تمہیں تمہارے دین سے پھیردیں اگر بن پڑے (ف۳۲۴) اور تم میں جو کوئی اپنے دین سے پھرے پھر کافر ہوکر مرے تو ان لوگوں کا کیا اکارت گیا دنیا میں اور آخرت میں (ف۴۲۵) اور وہ دوزخ والے ہیں انہیں اس میں ہمیشہ رہنا،'),
 (93,2,218,'وه جو ایمان لائے اور وہ جنہوں نے اللہ کے لئے اپنے گھر بار چھوڑے اور اللہ کی راہ میں لڑے وہ رحمت الٰہی کے امیداور ہیں، اور اللہ بخشنے والا مہربان ہے (ف۴۲۵-الف)'),
 (93,2,219,'تم سے شراب اور جوئے کا حکم پوچھتے ہیں، تم فرمادو کہ ان دونوں میں بڑا گناہ ہے اور لوگوں کے کچھ دنیوی نفع بھی اور ان کا گناہ ان کے نفع سے بڑا ہے (ف۴۲۶) تم سے پوچھتے ہیں کیا خرچ کریں (ف۳۲۷) تم فرماؤ جو فاضل بچے (ف۳۲۸) اسی طرح اللہ تم سے آیتیں بیان فرماتا ہے کہ کہیں تم دنیا،'),
 (93,2,220,'اور ا ٓ خرت کے کام سوچ کر کرو (ف۴۲۹) اور تم سے یتیموں کا مسئلہ پوچھتے ہیں (ف۴۳۰) تم فرماؤ ان کا بھلا کرنا بہتر ہے اور اگر اپنا ان کا خرچ ملالو تو وہ تمہارے بھائی ہیں اور خدا خوب جانتا ہے بگاڑنے والے کو سنوارنے والے سے، اور اللہ چاہتا ہے تو تمہیں مشقت میں ڈالتا، بیشک اللہ زبردست حکمت والا ہے،'),
 (93,2,221,'اور شرک والی عورتوں سے نکاح نہ کرو جب تک مسلمان نہ ہوجائیں (ف۴۱۳) اور بیشک مسلمان لونڈی مشرکہ سے اچھی ہے (ف۴۳۲) اگرچہ وہ تمہیں بھاتی ہو اور مشرکوں کے نکاح میں نہ دو جب تک وہ ایمان نہ لائیں (ف۴۳۳) اور بیشک مسلمان غلام مشرک سے اچھا ہے اگرچہ وہ تمہیں بھاتا ہو، وہ دوزخ کی طرف بلاتے ہیں (ف۴۳۴) اور اللہ جنت اور بخشش کی طرف بلاتا ہے اپنے حکم سے اور اپنی آیتیں لوگوں کے لئے بیان کرتا ہے کہ کہیں وہ نصیحت مانیں،'),
 (93,2,222,'اور تم سے پوچھتے ہیں حیض کا حکم (ف۴۳۵) تم فرماؤ وہ ناپاکی ہے تو عورتوں سے الگ رہو حیض کے دنوں اور ان سے نزدیکی نہ کرو جب تک پاک نہ ہولیں پھر جب پاک ہوجائیں تو ان کے پاس جاؤ جہاں سے تمہیں اللہ نے حکم دیا، بیشک اللہ پسند کرتا ہے بہت توبہ کرنے والوں کو اور پسند رکھتا ہے سھتروں کو،'),
 (93,2,223,'تمہاری عورتیں تمہارے لئے کھیتیاں ہیں، تو آؤ اپنی کھیتیوں میں جس طرح چاہو (ف۴۳۶) اور اپنے بھلے کا کام پہلے کرو (ف۴۳۷) اور اللہ سے ڈرتے رہو اور جان رکھو کہ تمہیں اس سے ملنا ہے اور اے محبوب بشارت دو ایمان والوں کو،'),
 (93,2,224,'اور اللہ کو اپنی قسموں کا نشانہ نہ بنالو (ف۴۳۸) کہ احسان اور پرہیزگاری او ر لوگوں میں صلح کرنے کی قسم کرلو، اور اللہ سنتا جانتا ہے،'),
 (93,2,225,'اور تمہیں نہیں پکڑ تا ان قسموں میں جو بے ارادہ زبان سے نکل جائے ہاں اس پر گرفت فرماتا ہے جو کام تمہارے دلوں نے کئے (ف۴۳۹) اور اللہ بخشنے والا حلم والا ہے،'),
 (93,2,226,'اور وہ جو قسم کھا بیٹھتے ہیں اپنی عورتوں کے پاس جانے کی انہیں چار مہینے کی مہلت ہے، پس اگر اس مدت میں پھر آئے تو اللہ بخشنے والا مہربان ہے'),
 (93,2,227,'اور اگر چھوڑ دینے کا ارادہ پکا کرلیا تو اللہ سنتا جانتا ہے(ف۴۴۰)'),
 (93,2,228,'اور طلاق والیاں اپنی جانوں کو روکے رہیں تین حیض تک (ف۴۴۱) اور انہیں حلال نہیں کہ چھپائیں وہ جو اللہ نے ان کے پیٹ میں پیدا کیا (ف۴۴۲) اگر اللہ اور قیامت پر ایمان رکھتی ہیں (ف۴۴۳) اور ان کے شوہروں کو اس مدت کے اندر ان کے پھیر لینے کا حق پہنچتا ہے اگر ملاپ چاہیں (ف۴۴۴) اور عورتوں کا بھی حق ایسا ہی ہے جیسا ان پر ہے شرع کے موافق (ف۴۴۵) اور مردوں کو ان پر فضیلت ہے، اور اللہ غالب حکمت والا ہے،'),
 (93,2,229,'یہ طلاق (ف۴۴۶) دو بار تک ہے پھر بھلائی کے ساتھ روک لینا ہے (ف۴۴۷) یا نکوئی (اچھے سلوک) کے ساتھ چھوڑ دینا ہے (ف۴۴۸) اور تمہیں روا نہیں کہ جو کچھ عورتوں کو دیا (ف۴۴۹) اس میں سے کچھ واپس لو (ف۴۵۰) مگر جب دونوں کو اندیشہ ہو کہ اللہ کی حدیں قائم نہ کریں گے (ف۴۵۱) پھر اگر تمہیں خوف ہو کہ وہ دونوں ٹھیک انہیں حدوں پر نہ رہیں گے تو ان پر کچھ گناہ نہیں اس میں جو بدلہ دے کر عورت چھٹی لے، (ف۴۵۲) یہ اللہ کی حدیں ہیں ان سے آگے نہ بڑھو اور جو اللہ کی حدوں سے آگے بڑھے تو وہی لوگ ظالم ہیں،'),
 (93,2,230,'پھر اگر تیسری طلاق اسے دی تو اب وہ عورت اسے حلال نہ ہوگی جب تک دوسرے خاوند کے پاس نہ رہے، (ف۴۵۳) پھر وہ دوسرا اگر اسے طلاق دے دے تو ان دونوں پر گناہ نہیں کہ پھر آپس میں مل جائیں (ف۴۵۴) اگر سمجھتے ہوں کہ اللہ کی حدیں نباہیں گے، اور یہ اللہ کی حدیں ہیں جنہیں بیان کرتا ہے دانش مندوں کے لئے،'),
 (93,2,231,'اور جب تم عورتوں کو طلاق دو اور ان کی میعاد آلگے (ف۴۵۵) تو اس وقت تک یا بھلائی کے ساتھ روک لو (ف۴۵۶) یا نکوئی (اچھے سلوک) کے ساتھ چھوڑ دو (ف۴۵۷) اور انہیں ضرر دینے کے لئے روکنا نہ ہو کہ حد سے بڑھو اور جو ایسا کرے وہ اپنا ہی نقصان کرتا ہے (ف۴۵۸) اور اللہ کی آیتوں کو ٹھٹھا نہ بنالو (ف۴۵۹) اور یاد کرو اللہ کا احسان جو تم پر ہے (ف۴۶۰) اور و ہ جو تم پر کتاب اور حکمت (ف۴۶۱) اتاری تمہیں نصیحت دینے کو اور اللہ سے ڈرتے رہو اور جان رکھو کہ اللہ سب کچھ جانتا ہے (ف۴۶۲)'),
 (93,2,232,'اور جب تم عورتوں کو طلاق دو اور ان کی میعاد پوری ہوجائے (ف۴۶۳) تو اے عورتوں کے والِیو انہیں نہ روکو اس سے کہ اپنے شوہروں سے نکاح کرلیں (ف۴۶۴) جب کہ آپس میں موافق شرع رضا مند ہوجائیں (ف۴۶۵) یہ نصیحت اسے دی جاتی ہے جو تم میں سے اللہ اور قیامت پر ایمان رکھتا ہو یہ تمہارے لئے زیادہ ستھرا اور پاکیزہ ہے اور اللہ جانتا ہے اور تم نہیں جانتے،'),
 (93,2,233,'اور مائیں دودھ پلائیں اپنے بچوں کو (ف۴۶۶) پورے دو برس اس کے لئے جو دودھ کی مدت پوری کرنی چاہئے (ف۴۶۷) اور جس کا بچہ ہے (ف۲۶۸) اس پر عورتوں کا کھانا پہننا ہے حسب دستور (ف۴۶۹) کسی جان پر بوجھ نہ رکھا جائے گا مگر اس کے مقدور بھر ماں کو ضرر نہ دیا جائے اس کے بچہ سے (ف۴۷۰) اور نہ اولاد والے کو اس کی اولاد سے (ف۴۷۱) یا ماں ضرر نہ دے اپنے بچہ کو اور نہ اولاد والا اپنی اولاد کو (ف۴۷۲) اور جو باپ کا قائم مقام ہے اس پر بھی ایسا ہی واجب ہے پھر اگر ماں باپ دونوں آپس کی رضا اور مشورے سے دودھ چھڑانا چاہیں تو ان پر گناہ نہیں اور اگر تم چاہو کہ دائیوں سے اپنے بچوں کو دودھ پلواؤ تو بھی تم پر مضائقہ نہیں جب کہ جو دینا ٹھہرا تھا بھلائی کے ساتھ انہیں ادا کردو، اور اللہ سے ڈرتے رہو اور جان رکھو کہ اللہ تمہارے کام دیکھ رہا ہے،'),
 (93,2,234,'اور تم میں جو مریں اور بیبیاں چھوڑیں وہ چار مہینے دس دن اپن ے آپ کو روکے رہیں (ف۴۷۳) تو جب ان کی عدت پوری ہوجائے تو اے والیو! تم پر مؤاخذہ نہیں اس کام میں جو عورتیں اپنے معاملہ میں موافق شرع کریں، اور اللہ کو تمہارے کاموں کی خبر ہے،'),
 (93,2,235,'اور تم پر گناہ نہیں اس بات میں جو پردہ رکھ کر تم عورتوں کے نکاح کا پیام د و یا اپنے دل میں چھپا رکھو اللہ جانتا ہے کہ اب تم ان کی یاد کرو گے (ف۴۷۵) ہاں ان سے خفیہ وعدہ نہ کر رکھو مگر یہ کہ اتنی بات کہو جو شرع میں معروف ہے، اور نکاح کی گرہ پکی نہ کرو جب تک لکھا ہوا حکم اپنی میعاد کو نہ پہنچ لے (ف۴۷۶) اور جان لو کہ اللہ تمہارے دل کی جانتا ہے تو اس سے ڈرو اور جان لو کہ اللہ بخشنے والا حلم والا ہے،'),
 (93,2,236,'تم پر کچھ مطالبہ نہیں (ف۴۷۷) تم عورتوں کو طلاق دو جب تک تم نے ان کو ہاتھ ن ہ لگایا ہو یا کوئی مہر مقرر کرلیا ہو (ف۴۷۸) اور ان کو کچھ برتنے کو دو (ف۴۷۹) مقدور والے پر اس کے لائق اور تنگدست پر اس کے لائق حسب دستور کچھ برتنے کی چیز یہ واجب ہے بھلائی والوں پر (ف۴۸۰)'),
 (93,2,237,'اور اگر تم نے عورتوں کو بے چھوئے طلاق دے دی اور ان کے لئے کچھ مہر مقرر کرچکے تھے تو جتنا ٹھہرا تھا اس کا آدھا واجب ہے مگر یہ کہ عورتیں کچھ چھوڑدیں (ف۴۸۱) یا وہ زیاد ه دے (ف۴۸۲) جس کے ہاتھ میں نکاح کی گرہ ہے (ف۴۸۳) اور اے مرَدو تمہارا زیادہ دینا پرہیزگاری سے نزدیک تر ہے اور آپس میں ایک دوسرے پر احسان کو بُھلا نہ دو بیشک اللہ تمہارے کام دیکھ رہا ہے (ف۴۸۴)'),
 (93,2,238,'نگہبانی کرو سب نمازوں کی (ف۴۸۵) اور بیچ کی نماز کی (ف۴۸۶) اور کھڑے ہو اللہ کے حضور ادب سے(ف۴۸۷)'),
 (93,2,239,'پھر اگر خوف میں ہو تو پیادہ یا سوار جیسے بن پڑے پھر جب اطمینان سے ہو تو اللہ کی یاد کرو جیسا اس نے سکھایا جو تم نہ جانتے تھے،'),
 (93,2,240,'اور جو تم میں مریں اور بیبیاں چھوڑ جائیں، وہ اپنی عورتوں کے لئے وصیت کرجائیں (ف۴۸۸) سال بھر تک نان نفقہ دینے کی بے نکالے (ف۴۸۹) پھر اگر وہ خود نکل جائیں تو تم پر اس کا مؤاخذہ نہیں جو انہوں نے اپنے معاملہ میں مناسب طور پر کیا، اور اللہ غالب حکمت والا ہے،'),
 (93,2,241,'اور طلاق والیوں کے لئے بھی مناسب طور پر نان و نفقہ ہے، یہ واجب ہے پرہیزگاروں پر،'),
 (93,2,242,'اللہ یونہی بیان کرتا ہے تمہارے لئے اپنی آیتیں کہ کہیں تمہیں سمجھ ہو،'),
 (93,2,243,'اے محبوب کیا تم نے نہ دیکھا تھا انہیں جو اپنے گھروں سے نکلے اور وہ ہزاروں تھے موت کے ڈر سے، تو اللہ نے ان سے فرمایا مرجاؤ پھر انہیں زندہ فرمادیا، بیشک اللہ لوگوں پر فضل کرنے والا ہے مگر اکثر لوگ ناشکرے ہیں (ف۴۹۰)'),
 (93,2,244,'اور لڑو اللہ کی راہ میں (ف۴۹۱) اور جان لو کہ اللہ سنتا جانتا ہے،'),
 (93,2,245,'ہے کوئی جو اللہ کو قرض حسن دے (ف۴۹۲) تو اللہ اس کے لئے بہت گنُا بڑھا دے اور اللہ تنگی اور کشائیش کرتا ہے (ف۴۹۳) اور تمہیں اسی کی طرف پھر جانا،'),
 (93,2,246,'اے محبوب !کیا تم نے نہ دیکھا بنی اسرائیل کے ایک گروہ کو جو موسیٰ کے بعد ہوا (ف۴۹۴) جب اپنے ایک پیغمبر سے بولے ہمارے لیے کھڑا کردو ایک بادشاہ کہ ہم خدا کی راہ میں لڑیں، نبی نے فرمایا کیا تمہارے انداز ایسے ہیں کہ تم پر جہاد فرض کیا جائے تو پھر نہ کرو، بولے ہمیں کیا ہوا کہ ہم اللہ کی راہ میں نہ لڑیں حالانکہ ہم نکالے گئے ہیں اپنے وطن اور اپنی اولاد سے (ف۴۹۵) تو پھر جب ان پر جہاد فرض کیا گیا منہ پھیر گئے مگر ان میں کے تھوڑے (ف۴۹۶) اور اللہ خوب جانتا ہے ظالموں کو،'),
 (93,2,247,'اور ان سے ان کے نبی نے فرمایا بیشک اللہ نے طالوت کو تمہارا بادشاہ بنا کر بھیجا ہے (ف۴۹۷) بولے اسے ہم پر بادشاہی کیونکر ہوگی (ف۴۹۸) اور ہم اس سے زیادہ سلطنت کے مستحق ہیں اور اسے مال میں بھی وسعت نہیں دی گئی (ف۴۹۹) فرمایا اسے اللہ نے تم پر چن لیا (ف۵۰۰) اور اسے علم اور جسم میں کشادگی زیادہ دی (ف۵۰۱) اور اللہ اپنا ملک جسے چاہ ے دے (ف۵۰۲) اور اللہ وسعت والا علم والا ہے (ف۵۰۳)'),
 (93,2,248,'اور ان سے ان کے نبی نے فرمایا اس کی بادشاہی کی نشانی یہ ہے کہ آئے تمہارے پاس تابوت (ف۵۰۴) جس میں تمہارے رب کی طرف سے دلوں کا چین ہے اور کچھ بچی ہوئی چیزیں معزز موسی ٰ او ر معزز ہارون کے ترکہ کی اٹھاتے لائیں گے اسے فرشتے، بیشک اس میں بڑی نشانی ہے تمہارے لئے اگر ایمان رکھتے ہو،'),
 (93,2,249,'پھر جب طالوت لشکروں کو لے کر شہر سے جدا ہوا بولا بیشک اللہ تمہیں ایک نہر سے آزمانے والا ہے تو جو اس کا پانی پئے وہ میرا نہیں اور جو نہ پیئے وہ میرا ہے مگر وہ جو ایک چلُو اپنے ہاتھ سے لے لے (ف۵۰۶) تو سب نے اس سے پیا مگر تھوڑوں نے (ف۵۰۷) پھر جب طالوت اور اس کے ساتھ کے مسلمان نہر کے پار گئے بولے ہم میں آج طاقت نہیں جالوت اور اس کے لشکروں کی بولے وہ جنہیں اللہ سے ملنے کا یقین تھا کہ بارہا کم جماعت غالب آئی ہے زیادہ گروہ پر اللہ کے حکم سے، اور اللہ صابروں کے ساتھ ہے (ف۵۰۸)'),
 (93,2,250,'پھر جب سامنے آئے جالوت اور اس کے لشکروں کے عرض کی اے رب ہمارے ہم پر صبر انڈیل اور ہمارے پاؤں جمے رکھ کافر لوگوں پرہماری مدد کر،'),
 (93,2,251,'تو انہوں نے ان کو بھگا دیا اللہ کے حکم سے، اور قتل کیا داؤد نے جالوت کو (ف۵۰۹) اور اللہ نے اسے سلطنت اور حکمت (ف۵۱۰) عطا فرمائی اور اسے جو چاہا سکھایا (ف۵۱۱) اور اگر اللہ لوگوں میں بعض سے بعض کو دفع نہ کرے (ف۵۱۲) تو ضرور زمین تباہ ہوجائے مگر اللہ سارے جہان پر فضل کرنے والا ہے،'),
 (93,2,252,'یہ اللہ کی آیتیں ہیں کہ ہم اے محبوب تم پر ٹھیک ٹھیک پڑھتے ہیں، اور تم بےشک رسولوں میں ہو۔'),
 (93,2,253,'یہ (ف۵۱۳) رسول ہیں کہ ہم نے ان میں ایک کو دوسرے پر افضل کیا (ف۵۱۴) ان میں کسی سے اللہ نے کلام فرمایا (ف۵۱۵) اور کوئی وہ ہے جسے سب پر درجوں بلند کیا (ف۵۱۶) اور ہم نے مریم کے بیٹے عیسیٰ کو کھلی نشانیاں دیں (ف۵۱۷) اور پاکیزہ روح سے اس کی مدد کی (ف۵۱۸) اور اللہ چاہتا تو ان کے بعد والے آپس میں نہ لڑتے نہ اس کے کہ ان کے پاس کھلی نشانیاں آچکیں (ف۵۱۹) لیکن وہ مختلف ہوگئے ان میں کوئی ایمان پر رہا اور کوئی کافر ہوگیا (ف۵۲۰) اور اللہ چاہتا تو وہ نہ لڑتے مگر اللہ جو چاہے کرے(ف۵۲۱)'),
 (93,2,254,'اے ایمان والو! اللہ کی راہ میں ہمارے دیئے میں سے خرچ کرو وہ دن آنے سے پہلے جس میں نہ خرید و فروخت ہے اور نہ کافروں کے لئے دوستی اور نہ شفاعت، اور کافر خود ہی ظالم ہیں (ف۵۲۲)'),
 (93,2,255,'اللہ ہے جس کے سوا کوئی معبود نہیں (ف۵۲۳) وہ آپ زندہ اور اوروں کا قائم رکھنے والا (ف۵۲۴) اسے نہ اونگھ آئے نہ نیند (ف۵۲۵) اسی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں (ف۵۲۶) وہ کون ہے جو اس کے یہاں سفارش کرے بغیر اس کے حکم کے (ف۵۲۷) جانتا ہے جو کچھ ان کے آگے ہے اور جو کچھ ان کے پیچھے (ف۵۲۹) اور وہ نہیں پاتے اس کے علم میں سے مگر جتنا وہ چاہے (ف۵۲۹) اس کی کرسی میں سمائے ہوئے آسمان اور زمین (ف۵۳۰) اور اسے بھاری نہیں ان کی نگہبانی اور وہی ہے بلند بڑائی والا (ف۵۳۱)'),
 (93,2,256,'کچھ زبردستی نہیں (ف۵۳۲) دین میں بیشک خوب جدا ہوگئی ہے نیک راہ گمراہی سے تو جو شیطان کو نہ مانے اور اللہ پر ایمان لائے (ف۵۳۳) اس نے بڑی محکم گرہ تھامی جسے کبھی کھلنا نہیں، اور اللہ سنتا جانتا ہے،'),
 (93,2,257,'اللہ والی ہے مسلمانوں کا انہیں اندھیریوں سے (ف۵۳۴) نور کی طرف نکلتا ہے، اور کافروں کے حمایتی شیطان ہیں وہ انہیں نور سے اندھیریوں کی طرف نکالتے ہیں یہی لوگ دوزخ والے ہیں انہیں ہمیشہ اس میں رہنا،'),
 (93,2,258,'اے محبوب! کیا تم نے نہ دیکھا تھا اسے جو ابراہیم سے جھگڑا اس کے رب کے بارے میں اس پر (ف۵۳۵) کہ اللہ نے اسے بادشاہی دی (ف۵۳۶) جبکہ ابراہیم نے کہا کہ میرا رب وہ ہے جو جِلاتا اور مارتا ہے (ف۵۳۷) بولا میں جِلاتا اور مارتا ہوں (ف۵۳۸) ابراہیم نے فرمایا تو اللہ سورج کو لاتا ہے پورب (مشرق) سے تو اس کو پچھم (مغرب) سے لے آ (ف۵۳۹) تو ہوش اڑ گئے کافروں کے، اور اللہ راہ نہیں دکھاتا ظالموں کو،'),
 (93,2,259,'یا اس کی طرح جو گزرا ایک بستی پر (ف۵۴۰) اور وہ ڈھئی (مسمار ہوئی) پڑی تھی اپنی چھتوں پر (ف۵۴۱) بولا اسے کیونکر جِلائے گا اللہ اس کی موت کے بعد تو اللہ نے اسے مردہ رکھا سو برس پھر زندہ کردیا، فرمایا تو یہاں کتنا ٹھہرا، عرض کی دن بھر ٹھہرا ہوں گا یا کچھ کم، فرمایا نہیں تجھے سو برس گزر گئے اور اپنے کھانے اور پانی کو دیکھ کہ اب تک بو نہ لایا اور اپنے گدھے کو دیکھ کہ جس کی ہڈیاں تک سلامت نہ رہیں اور یہ اس لئے کہ تجھے ہم لوگوں کے واسطے نشانی کریں اور ان ہڈیوں کو دیکھ کیونکر ہم انہیں اٹھان دیتے پھر انہیں گوشت پہناتے ہیں جب یہ معاملہ اس پر ظاہر ہوگیا بولا میں خوب جانتا ہوں کہ اللہ سب کچھ کرسکتا ہے،'),
 (93,2,260,'اور جب عرض کی ابراہیم نے (ف۵۴۲) اے رب میرے مجھے دکھا دے تو کیونکر مردے جِلائے گا فرمایا کیا تجھے یقین نہیں (ف۵۴۳) عرض کی یقین کیوں نہیں مگر یہ چاہتا ہوں کہ میرے دل کو قرار آجائے (ف۵۴۴) فرمایا تو اچھا، چار پرندے لے کر اپنے ساتھ ہلالے (ف۵۴۵) پھر ان کا ایک ایک ٹکڑا ہر پہاڑ پر رکھ دے پھر انہیں بلا وہ تیرے پاس چلے آئیں گے پاؤں سے دوڑتے (ف۵۴۶) اور جان رکھ کہ اللہ غالب حکمت والا ہے'),
 (93,2,261,'ان کی کہاوت جو اپنے مال اللہ کی راہ میں خرچ کرتے ہیں (ف۵۴۷) اس دانہ کی طرح جس نے اگائیں سات بالیں (ف۵۴۸) ہر بال میں سو دانے (ف۵۴۹) اور اللہ اس سے بھی زیادہ بڑھائے جس کے لئے چاہے اور اللہ وسعت والا علم والا ہے،'),
 (93,2,262,'وہ جو اپنے مال اللہ کی راہ میں خرچ کرتے ہیں (ف۵۵۰) پھر دیئے پیچھے نہ احسان رکھیں نہ تکلیف دیں (ف۵۵۱) ان کا نیگ (انعام) ان کے رب کے پاس ہے اور انہیں نہ کچھ اندیشہ ہو نہ کچھ غم،'),
 (93,2,263,'اچھی بات کہنا اور درگزر کرنا (ف۵۵۲) اس خیرات سے بہتر ہے جس کے بعد ستانا ہو (ف۵۵۳) اور اللہ بے پراہ حلم والا ہے،'),
 (93,2,264,'اے ایمان والوں اپنے صدقے باطل نہ کردو احسان رکھ کر اور ایذا دے کر (ف۵۵۴) اس کی طرح جو اپنا مال لوگوں کے دکھاوے کے لئے خرچ کرے اور اللہ اور قیامت پر ایمان نہ لائے، تو اس کی کہاوت ایسی ہے جیسے ایک چٹان کہ اس پر مٹی ہے اب اس پر زور کا پانی پڑا جس نے اسے نرا پتھر کر چھوڑا (ف۵۵۵) اپنی کمائی سے کسی چیز پر قابو نہ پائیں گے، اور اللہ کافروں کو راہ نہیں دیتا،'),
 (93,2,265,'اور ان کی کہاوت جو اپنے مال اللہ کی رضا چاہنے میں خرچ کرتے ہیں اور اپنے دل جمانے کو (ف۵۵۶) اس باغ کی سی ہے جو بھوڑ (رتیلی زمین) پر ہو اس پر زور کا پانی پڑا تو دُونے میوے لایا پھر اگر زور کا مینھ اسے نہ پہنچے تو اوس کافی ہے (ف۵۵۷) اور اللہ تمہارے کام دیکھ رہا ہے (ف۵۵۸)'),
 (93,2,266,'کیا تم میں کوئی اسے پسند رکھے گا (ف۵۵۹) کہ اس کے پاس ایک باغ ہو کھجوروں اور انگوروں کا (ف۵۶۰) جس کے نیچے ندیاں بہتیں اس کے لئے اس میں ہر قسم کے پھلوں سے ہے (ف۵۶۱) اور اسے بڑھاپا آیا (ف۵۶۲) اور اس کے ناتوان بچے ہیں (ف۵۶۳) تو آیا اس پر ایک بگولا جس میں آگ تھی تو جل گیا (ف۵۶۴) ایسا ہی بیان کرتا ہے اللہ تم سے اپنی آیتیں کہ کہیں تم دھیان لگاؤ (ف۵۶۵)'),
 (93,2,267,'اے ایمان والو! اپنی پاک کمائیوں میں سے کچھ دو (ف۵۶۶) اور اس میں سے جو ہم نے تمہارے لئے زمین سے نکالا (ف۵۶۷) اور خاص ناقص کا ارادہ نہ کرو کہ دو تو اس میں سے (ف۵۶۸) اور تمہیں ملے تو نہ لوگے جب تک اس میں چشم پوشی نہ کرو اور جان رکھو کہ اللہ بے پروانہ سراہا گیا ہے۔'),
 (93,2,268,'شیطان تمہیں اندیشہ دلاتا ہے (ف۵۶۹) محتاجی کا اور حکم دیتا ہے بے حیائی کا (ف۵۷۰) اور اللہ تم سے وعدہ فرماتا ہے بخشش اور فضل کا (ف۵۷۱) اور اللہ وسعت و الا علم والا ہے،'),
 (93,2,269,'اللہ حکمت دیتا ہے (ف۵۷۲) جسے چاہے اور جسے حکمت ملی اسے بہت بھلائی ملی، اور نصیحت نہیں مانتے مگر عقل والے،'),
 (93,2,270,'اور تم جو خرچ کرو (ف۵۷۳) یا منت مانو (ف۵۷۴) اللہ کو اس کی خبر ہے (ف۵۷۵) اور ظالموں کا کوئی مددگار نہیں،'),
 (93,2,271,'اگر خیرات اعلانیہ دو تو وہ کیا ہی اچھی بات ہے اور اگر چھپا کر فقیروں کو دو یہ تمہارے لئے سب سے بہتر ہے (ف۵۷۶) اور اسمیں تمہارے کچھ گناہ گھٹیں گے، اور اللہ کو تمہارے کاموں کی خبر ہے،'),
 (93,2,272,'انہیں راہ دینا تمہارے ذمہ لازم نہیں، (ف۵۷۷) ہاں اللہ راہ دیتا ہے جسے چاہتا ہے، اور تم جو اچھی چیز دو تو تمہارا ہی بھلا ہے (ف۵۷۸) اور تمہیں خرچ کرنا مناسب نہیں مگر اللہ کی مرضی چاہنے کے لئے، اور جو مال دو تمہیں پورا ملے گا اور نقصان نہ دیئے جاؤ گے،'),
 (93,2,273,'ان فقیروں کے لئے جو راہ خدا میں روکے گئے (ف۵۷۹) زمین میں چل نہیں سکتے (ف۵۸۰) نادان انہیں تونگر سمجھے بچنے کے سبب (ف۵۸۱) تو انہیں ان کی صورت سے پہچان لے گا (ف۵۸۲) لوگوں سے سوال نہیں کرتے کہ گڑ گڑانا پڑے اور تم جو خیرات کرو اللہ اسے جانتا ہے،'),
 (93,2,274,'وہ جو اپنے مال خیرات کرتے ہیں رات میں اور دن میں چھپے اور ظاہر (ف۵۸۳) ان کے لئے ان کا نیگ (انعام، حصہ) ہے ان کے رب کے پاس ان کو نہ کچھ اندیشہ ہو نہ کچھ غم،'),
 (93,2,275,'وہ جو سود کھاتے ہیں (ف۵۸۴) قیامت کے دن نہ کھڑے ہوں گے مگر، جیسے کھڑا ہوتا ہے وہ جسے آسیب نے چھو کر مخبوط بنادیا ہو (ف۵۸۵) اس لئے کہ انہوں نے کہا بیع بھی تو سود ہی کے مانند ہے، اور اللہ نے حلال کیا بیع کو اور حرام کیا سود، تو جسے اس کے رب کے پاس سے نصیحت آئی اور وہ باز رہا تو اسے حلال ہے جو پہلے لے چکا، (ف۵۸۶) اور اس کا کام خدا کے سپرد ہے (ف۵۸۷) اور جو اب ایسی حرکت کرے گا تو وہ دوزخی ہے وہ اس میں مدتو ں رہیں گے (ف۵۸۸)'),
 (93,2,276,'اللہ ہلاک کرتا ہے سود کو (ف۵۸۹) اور بڑھاتا ہے خیرات کو (ف۵۹۰) اور اللہ کو پسند نہیں آتا کوئی ناشکرا بڑا گنہگار،'),
 (93,2,277,'بیشک وہ جو ایمان لائے اور اچھے کام کئے اور نماز قائم کی اور زکوٰة دی ان کا نیگ (انعام) ان کے رب کے پاس ہے، اور نہ انہیں کچھ اندیشہ ہو، نہ کچھ غم،'),
 (93,2,278,'اے ایمان والو! اللہ سے ڈرو اور چھوڑ دو جو باقی رہ گیا ہے سود اگر مسلمان ہو (ف۵۹۱)'),
 (93,2,279,'پھر اگر ایسا نہ کرو تو یقین کرلو اللہ اور اللہ کے رسول سے لڑائی کا (ف۵۹۲) اور اگر تم توبہ کرو تو اپنا اصل مال لے لو نہ تم کسی کو نقصان پہچاؤ (ف۵۹۳) نہ تمہیں نقصان ہو (ف۵۹۴)'),
 (93,2,280,'اور اگر قرضدار تنگی والا ہے تو اسے مہلت دو آسانی تک، اور قرض اس پر بالکل چھوڑ دینا تمہارے لئے اور بھلا ہے اگر جانو(ف۵۹۵)'),
 (93,2,281,'اور ڈرو اس دن سے جس میں اللہ کی طرف پھرو گے، اور ہر جان کو اس کی کمائی پوری بھردی جائے گی اور ان پر ظلم نہ ہوگا (ف۵۹۶)'),
 (93,2,282,'اے ایمان والو! جب تم ایک مقرر مدت تک کسی دین کا لین دین کرو (ف۵۹۷) تو اسے لکھ لو (ف۵۹۸) اور چاہئے کہ تمہارے درمیان کوئی لکھنے والا ٹھیک ٹھیک لکھے (ف۵۹۹) اور لکھنے والا لکھنے سے انکار نہ کرے جیسا کہ اسے اللہ نے سکھایا ہے (ف۶۰۰) تو اسے لکھ دینا چاہئے اور جس بات پر حق آتا ہے وہ لکھا تا جائے اور اللہ سے ڈرے جو اس کا رب ہے اور حق میں سے کچھ رکھ نہ چھوڑے پھر جس پر حق آتا ہے اگر بے عقل یا ناتواں ہو یا لکھا نہ سکے (ف۶۰۱) تو اس کا ولی انصاف سے لکھائے، اور دو گواہ کرلو اپنے مردوں میں سے (ف۶۰۲) پھر اگر دو مرد نہ ہوں(ف۶۰۳) تو ایک مرد اور دو عورتیں ایسے گواہ جن کو پسند کرو (ف۶۰۴) کہ کہیں ان میں ایک عورت بھولے تو اس کو دوسری یاد دلادے، اور گواہ جب بلائے جائیں تو آنے سے انکار نہ کریں (ف۶۰۵) اور اسے بھاری نہ جانو کہ دین چھوٹا ہو یا بڑا اس کی میعاد تک لکھت کرلو یہ اللہ کے نزدیک زیادہ انصاف کی بات ہے اس میں گواہی خوب ٹھیک رہے گی اور یہ اس سے قریب ہے کہ تمہیں شبہ نہ پڑے مگر یہ کہ کوئی سردست کا سودا دست بدست ہو تو اس کے نہ لکھنے کا تم پر گناہ نہیں (ف۶۰۶) اور جب خرید و فروخت کرو تو گواہ کرلو (ف۶۰۷) اور نہ کسی لکھنے والے کو ضَرر دیا جائے، نہ گواہ کو (یا، نہ لکھنے والا ضَرر دے نہ گواہ) (ف۶۰۸) اور جو تم ایسا کرو تو یہ تمہارا فسق ہوگا، اور اللہ سے ڈرو اور اللہ تمہیں سکھاتا ہے، اور اللہ سب کچھ جانتا ہے،'),
 (93,2,283,'اور اگر تم سفر میں ہو (ف۶۰۹) اور لکھنے والا نہ پاؤ (ف۶۱۰) تو گِرو (رہن) ہو قبضہ میں دیا ہوا (ف۶۱۱) اور اگر تم ایک کو دوسرے پر اطمینان ہو تو وہ جسے اس نے امین سمجھا تھا (ف۶۱۲) اپنی امانت ادا کردے (ف۶۱۳) اور اللہ سے ڈرے جو اس کا رب ہے اور گواہی نہ چھپاؤ (ف۶۱۴) اور جو گواہی چھپائے گا تو اندر سے اسکا دل گنہگار ہے (ف۶۱۵) اور اللہ تمہارے کاموں کو جانتا ہے،'),
 (93,2,284,'اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے، اور اگر تم ظاہر کرو جو کچھ (ف۶۱۶) تمہارے جی میں ہے یا چھپاؤ اللہ تم سے اس کا حساب لے گا (ف۶۱۷) تو جسے چاہے گا بخشے گا (ف۶۱۸) اور جسے چاہے گا سزادے گا (ف۶۱۹) اور اللہ ہر چیز پر قادر ہے،'),
 (93,2,285,'سب نے مانا (ف۶۲۰) اللہ اور اس کے فرشتوں اور اس کی کتابوں اور اس کے رسولوں کو (ف۶۲۱) یہ کہتے ہوئے کہ ہم اس کے کسی رسول پر ایمان لانے میں فرق نہیں کرتے (ف۶۲۲) اور عرض کی کہ ہم نے سنا اور مانا (ف۶۲۳) تیری معافی ہو اے رب ہمارے! اور تیری ہی طرف پھرنا ہے،'),
 (93,2,286,'اللہ کسی جان پر بوجھ نہیں ڈالتا مگر اس کی طاقت بھر، اس کا فائدہ ہے جو اچھا کمایا اور اس کا نقصان ہے جو برائی کمائی (ف۶۲۴) اے رب ہمارے! ہمیں نہ پکڑ اگر ہم بھولیں (ف۶۲۵) یا چوُکیں اے رب ہمارے! اور ہم پر بھاری بوجھ نہ رکھ جیسا تو نے ہم سے اگلوں پر رکھا تھا، اے رب ہمارے! اور ہم پر وہ بوجھ نہ ڈال جس کی ہمیں سہار (برداشت) نہ ہو اور ہمیں معاف فرمادے اور بخش دے اور ہم پر مہر کر تو ہمارا مولیٰ ہے۔ تو کافروں پر ہمیں مدد دے۔'),
 (93,3,1,'الم،'),
 (93,3,2,'اللہ ہے جس کے سوا کسی کی پوجا نہیں (ف۲) آپ زندہ اور ونکا قائم رکھنے والا،'),
 (93,3,3,'اس نے تم پر یہ سچی کتاب اتاری اگلی کتابوں کی تصدیق فرماتی اور اس نے اس سے پہلے توریت اور انجیل اتاری،'),
 (93,3,4,'لوگوں کو راہ دکھاتی اور فیصلہ اتارا، بیشک وہ جو اللہ کی آیتوں سے منکر ہوئے (ف۳)ان کے لئے سخت عذاب ہے اور اللہ غالب بدلہ لینے والا ہے،'),
 (93,3,5,'اللہ پر کچھ چھپا ہوا نہیں زمین میں نہ آسمان میں،'),
 (93,3,6,'وہی ہے کہ تمہاری تصویر بناتا ہے ماؤں کے پیٹ میں جیسی چاہے (ف۴) اس کے سوا کسی کی عبادت نہیں عزت والا حکمت والا (ف۵)'),
 (93,3,7,'وہی ہے جس نے تم پر یہ کتاب اتاری اس کی کچھ آیتیں صاف معنی رکھتی ہیں (ف۶) وہ کتاب کی اصل ہیں (ف۷) اور دوسری وہ ہیں جن کے معنی میں اشتباہ ہے (ف۸) وہ جن کے دلوں میں کجی ہے (ف۹) وہ اشتباہ والی کے پیچھے پڑتے ہیں (ف۱۰) گمراہی چاہنے (ف۱۱) اور اس کا پہلو ڈھونڈنے کو (ف۱۲) اور اس کا ٹھیک پہلو اللہ ہی کو معلوم ہے (ف۱۳) اور پختہ علم والے (ف۱۴) کہتے ہیں ہم اس پر ایمان لائے (ف۱۵) سب ہمارے رب کے پاس سے ہے (ف۱۶) اور نصیحت نہیں مانتے مگر عقل والے (ف۱۷)'),
 (93,3,8,'اے رب ہمارے دل ٹیڑھے نہ کر بعد اس کے کہ تو نے ہمیں ہدایت دی اور ہمیں اپنے پاس سے رحمت عطا کر بیشک تو ہے بڑا دینے والا،'),
 (93,3,9,'اے رب ہمارے بیشک تو سب لوگوں کو جمع کرنے والا ہے (ف۱۸) اس دن کے لئے جس میں کوئی شبہ نہیں (ف۱۹) بیشک اللہ کا وعدہ نہیں بدلتا (ف۲۰)'),
 (93,3,10,'بیشک وہ جو کافر ہوئے (ف۲۱) ان کے مال اور ان کی اولاد اللہ سے انہیں کچھ نہ بچاسکیں گے اور وہی دوزخ کے ایندھن ہیں،'),
 (93,3,11,'جیسے فرعون والوں اور ان سے اگلوں کا طریقہ، انہوں نے ہماری آیتیں جھٹلائیں تو اللہ نے ان کے گناہوں پر ان کو پکڑا اور اللہ کا عذاب سخت،'),
 (93,3,12,'فرمادو، کافروں سے کوئی دم جاتا ہے کہ تم مغلوب ہوگے اور دوزخ کی طرف ہانکے جاؤ گے (ف۲۲) اور وہ بہت ہی برا بچھونا،'),
 (93,3,13,'بیشک تمہارے لئے نشانی تھی (ف۲۳) دو گروہوں میں جو آپس میں بھڑ پڑے (ف۲۴) ایک جتھا اللہ کی راہ میں لڑتا (ف۲۵) اور دوسرا کافر (ف۲۶) کہ انہیں آنکھوں دیکھا اپنے سے دونا سمجھیں، اور اللہ اپنی مدد سے زور دیتا ہے جسے چاہتا ہے (ف۲۷) بیشک اس میں عقلمندوں کے لئے ضرور دیکھ کر سیکھنا ہے،'),
 (93,3,14,'لوگوں کے لئے آراستہ کی گئی ان خواہشوں کی محبت (ف۲۸) عورتوں اور بیٹے اور تلے اوپر سونے چاندے کے ڈھیر اور نشان کئے ہوئے گھوڑے اور چوپائے اور کھیتی یہ جیتی دنیا کی پونجی ہے (ف۲۹) اور اللہ ہے جس کے پاس اچھا ٹھکانا (ف۳۰)'),
 (93,3,15,'تم فرماؤ کیا میں تمہیں اس سے (ف۳۱) بہتر چیز بتادوں پرہیزگاروں کے لئے ان کے رب کے پاس جنتیں ہیں جن کے نیچے نہریں رواں ہمیشہ ان میں رہیں گے اور ستھری بیبیاں (ف۳۲) اور اللہ کی خوشنودی (ف۳۳) اور اللہ بندوں کو دیکھتا ہے (ف۳۴)'),
 (93,3,16,'وہ جو کہتے ہیں ے رب ہمارے! ہم ایمان لائے تو ہمارے گناہ معاف کر اور ہمیں دوزخ کے عذاب سے بچالے،'),
 (93,3,17,'صبر والے (ف۳۵) اور سچے (ف۳۶) اور ادب والے اور راہِ خدا میں خرچنے والے اور پچھلے پہر سے معافی مانگنے والے (ف۳۷)'),
 (93,3,18,'اور اللہ نے گواہی دی کہ اس کے سوا کوئی معبود نہیں (ف۳۸) اور فرشتوں نے اور عالموں نے (ف۳۹) انصاف سے قائم ہوکر اس کے سوا کسی کی عبادت نہیں عزت والا حکمت والا،'),
 (93,3,19,'بیشک اللہ کے یہاں اسلام ہی دین ہے (ف۴۰) اور پھوٹ میں نہ پڑے کتابی (ف۴۱) مگر اس کے کہ انہیں علم آچکا (ف۴۲) اپنے دلو ں کی جلن سے (ف۴۳) اور جو اللہ کی آیتوں کا منکر ہو تو بیشک اللہ جلد حساب لینے والا ہے،'),
 (93,3,20,'پھر اے محبوب! اگر وہ تم سے حجت کریں تو فرمادو میں اپنا منہ اللہ کے حضور جھکائے ہوں اور جومیرے پیرو ہوئے (ف۴۴) اور کتابیوں اور اَن پڑھوں سے فرماؤ (ف۴۵) کیا تم نے گردن رکھی (ف۴۶) پس اگر وہ گردن رکھیں جب تو راہ پاگئے اور اگر منہ پھیریں تو تم پر تو یہی حکم پہنچادینا ہے (ف۴۷) اور اللہ بندوں کو کو دیکھ رہا ہے،'),
 (93,3,21,'وہ جو اللہ کی آیتوں سے منکر ہوتے اور پیغمبروں کو ناحق شہید کرتے (ف۴۸) اور انصاف کا حکم کرنے والوں کو قتل کرتے ہیں انہیں خوشخبری دو درناک عذاب کی،'),
 (93,3,22,'یہ ہیں وہ جنکے اعمال اکارت گئے دنیا و آخرت میں (ف۴۹) اور ان کا کوئی مددگار نہیں (ف۵۰)'),
 (93,3,23,'کیا تم نے انہیں دیکھا جنہیں کتاب کا ایک حصہ ملا (ف۵۱) کتاب اللہ کی طرف بلائے جاتے ہیں کہ وہ ان کا فیصلہ کرے پھر ان میں کا ایک گروہ اس سے روگرداں ہوکر پھر جاتا ہے (ف۵۲)'),
 (93,3,24,'یہ جرأت (ف۵۳) انہیں اس لئے ہوئی کہ وہ کہتے ہیں ہرگز ہمیں آگ نہ چھوئے گی مگر گنتی کے دنوں (ف۵۴) اور ان کے دین میں انہیں فریب دیا اس جھوٹ نے جو باندھتے تھے (ف۵۵)'),
 (93,3,25,'تو کیسی ہوگی جب ہم انہیں اکٹھا کریں گے اس دن کے لئے جس میں شک نہیں (ف۵۶) اور ہر جان کو اس کی کمائی پوری بھر (بالکل پوری) دی جائے گی اور ان پر ظلم نہ ہوگا،'),
 (93,3,26,'یوں عرض کر، اے اللہ! ملک کے مالک تو جسے چاہے سلطنت دے اور جس سے چاہے چھین لے، اور جسے چاہے عزت دے اور جسے چاہے ذلت دے، ساری بھلائی تیرے ہی ہاتھ ہے، بیشک تو سب کچھ کرسکتا ہے (ف۵۷)'),
 (93,3,27,'تو دن کا حصّہ رات میں ڈالے اور رات کا حصہ دن میں ڈالے (ف۵۸) اور مردہ سے زندہ نکالے اور زندہ سے مردہ نکالے (ف۵۹) اور جسے چاہے بے گنتی دے،'),
 (93,3,28,'مسلمان کافروں کو اپنا دوست نہ بنالیں مسلمانوں کے سوا (ف۶۰) اور جو ایسا کرے گا اسے اللہ سے کچھ علاقہ نہ رہا مگر یہ کہ تم ان سے کچھ ڈرو (ف۶۱) اور اللہ تمہیں اپنے غضب سے ڈراتا ہے اور اللہ ہی کی طرف پھرنا ہے،'),
 (93,3,29,'تم فرمادو کہ اگر تم اپنے جی کی بات چھپاؤ یا ظاہر کرو اللہ کو سب معلوم ہے، اور جانتا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے، اور ہر چیز پر اللہ کا قابو ہے،'),
 (93,3,30,'جس دن ہر جان نے جو بھلا کیا حاضر پائے گی (ف۶۲) اور جو برا کام کیا، امید کرے گی کاش مجھ میں اور اس میں دور کا فاصلہ ہوتا (ف۶۳) اور اللہ تمہیں اپنے عذاب سے ڈراتا ہے، اور اللہ بندوں پر مہربان ہے،'),
 (93,3,31,'اے محبوب! تم فرمادو کہ لوگو اگر تم اللہ کو دوست رکھتے ہو تو میرے فرمانبردار ہوجاؤ اللہ تمہیں دوست رکھے گا (ف۶۴) اور تمہارے گناہ بخش دے گا اور اللہ بخشنے والا مہربان ہے،'),
 (93,3,32,'تم فرمادو کہ حکم مانو اللہ اور رسول کا (ف۶۵) پھر اگر وہ منہ پھیریں تو اللہ کو خوش نہیں آتے کافر،'),
 (93,3,33,'بیشک اللہ نے چن لیا آدم اور نوح اور ابراہیم کی آ ل اولاد اور عمران کی آ ل کو سارے جہاں سے (ف۶۶)'),
 (93,3,34,'یہ ایک نسل ہے ایک دوسرے سے (ف۶۷) اور اللہ سنتا جانتا ہے،'),
 (93,3,35,'جب عمران کی بی بی نے عرض کی (ف۶۸) اے رب میرے! میں تیرے لئے منت مانتی ہو جو میرے پیٹ میں ہے کہ خالص تیری ہی خدمت میں رہے (ف۶۹) تو تو مجھ سے قبول کرلے بیشک تو ہی سنتا جانتا،'),
 (93,3,36,'پھر جب اسے جنا بولی، اے رب میرے! یہ تو میں نے لڑکی جنی (ف۷۰) اور اللہ جو خوب معلوم ہے جو کچھ وہ جنی، اور وہ لڑکا جو اس نے مانگا اس لڑکی سا نہیں (ف۷۱) اور میں نے اس کا نام مریم رکھا (ف۷۲) اور میں اسے اور اس کی اولاد کو تیری پناہ میں دیتی ہوں راندے ہوئے شیطان سے،'),
 (93,3,37,'تو اسے اس کے رب نے اچھی طرح قبول کیا (ف۷۳) اور اسے اچھا پروان چڑھایا (ف۷۴) اور اسے زکریا کی نگہبانی میں دیا، جب زکریا اس کے پاس اس کی نماز پڑھنے کی جگہ جاتے اس کے پاس نیا رزق پاتے (ف۷۵) کہا اے مریم! یہ تیرے پاس کہاں سے آیا، بولیں وہ اللہ کے پاس سے ہے، بیشک اللہ جسے چاہے بے گنتی دے (ف۷۶)'),
 (93,3,38,'یہاں (ف۷۷) پکارا زکریا اپنے رب کو بولا اے رب! میرے مجھے اپنے پاس سے دے ستھری اولاد، بیشک تو ہی ہے دعا سننے والا،'),
 (93,3,39,'تو فرشتوں نے اسے آواز دی اور وہ اپنی نماز کی جگہ کھڑا نماز پڑھ رہا تھا (ف۷۸) بیشک اللہ آپ کو مژدہ دیتا ہے یحییٰ کا جو اللہ کی طرف کے ایک کلمہ کی (ف۷۹) تصدیق کرے گا اور سردار (ف۸۰) اور ہمیشہ کے لیے عورتوں سے بچنے والا اور نبی ہمارے خاصوں میں سے (ف۸۱)'),
 (93,3,40,'بولا اے میرے رب میرے لڑکا کہاں سے ہوگا مجھے تو پہنچ گیا بڑھا پا (ف۸۲) اور میری عورت بانجھ (ف۸۳) فرمایا اللہ یوں ہی کرتا ہے جو چاہے (ف۸۴)'),
 (93,3,41,'عرض کی اے میرے رب میرے لئے کوئی نشانی کردے (ف۸۵) فرمایا تیری نشانی یہ ہے کہ تین دن تو لوگوں سے بات نہ کرے مگر اشارہ سے اور اپنے رب کی بہت یاد کر (ف۸۶) اور کچھ دن رہے اور تڑکے اس کی پاکی بول،'),
 (93,3,42,'اور جب فرشتوں نے کہا، اے مریم، بیشک اللہ نے تجھے چن لیا (ف۸۷) اور خوب ستھرا کیا (ف۸۸) اور آج سارے جہاں کی عورتوں سے تجھے پسند کیا (ف۸۹)'),
 (93,3,43,'اے مریم اپنے رب کے حضور ادب سے کھڑی ہو (ف۹۰) اور اس کے لئے سجدہ کر اور رکوع والوں کے ساتھ رکوع کر،'),
 (93,3,44,'یہ غیب کی خبریں ہیں کہ ہم خفیہ طور پر تمہیں بتاتے ہیں (ف۹۱) اور تم ان کے پاس نہ تھے جب وہ اپنی قلموں سے قرعہ ڈالتے تھے کہ مریم کس کی پرورش میں رہیں اور تم ان کے پاس نہ تھے جب وہ جھگڑ رہے تھے(ف۹۲)'),
 (93,3,45,'اور یاد کرو جب فرشتو ں نے مریم سے کہا، اے مریم! اللہ تجھے بشارت دیتا ہے اپنے پاس سے ایک کلمہ کی (ف۹۳) جس کا نام ہے مسیح عیسیٰ مریم کا بیٹا رُو دار (باعزت) ہوگا (ف۹۴) دنیا اور آخرت میں اور قرب والا (ف۹۵)'),
 (93,3,46,'اور لوگوں سے بات کرے گا پالنے میں (ف۹۶) اور پکی عمر میں (ف۹۷) اور خاصوں میں ہوگا، بولی اے میرے رب! میرے بچہ کہاں سے ہوگا مجھے تو کسی شخص نے ہاتھ نہ لگایا (ف۹۸)'),
 (93,3,47,'فرمایا اللہ یوں ہی پیدا کرتا ہے جو چاہے جب، کسی کام کا حکم فرمائے تو اس سے یہی کہتا ہے کہ ہوجا وہ فوراً ہوجاتا ہے،'),
 (93,3,48,'اور اللہ سکھائے گا کتاب اور حکمت اور توریت اور انجیل،'),
 (93,3,49,'اور رسول ہوگا بنی اسرائیل کی طرف، یہ فرماتا ہو کہ میں تمہارے پاس ایک نشانی لایا ہوں (ف۹۹) تمہارے رب کی طرف سے کہ میں تمہارے لئے مٹی سے پرند کی سی مور ت بناتا ہوں پھر اس میں پھونک مارتا ہوں تو وہ فوراً پرند ہوجاتی ہے اللہ کے حکم سے (ف۱۰۰) اور میں شفا دیتا ہوں مادر زاد اندھے اور سفید داغ والے کو (ف۱۰۱) اور میں مُردے جلاتا ہوں اللہ کے حکم سے (ف۱۰۲) اور تمہیں بتاتا ہوں جو تم کھاتے اور جو اپنے گھروں میں جمع کر رکھتے ہو، (ف۱۰۳) بیشک ان باتوں میں تمہارے لئے بڑی نشانی ہے اگر تم ایمان رکھتے ہو،'),
 (93,3,50,'اور تصدیق کرتا آیا ہوں اپنے سے پہلے کتاب توریت کی اور اس لئے کہ حلال کروں تمہارے لئے کچھ وہ چیزیں جو تم پر حرام تھیں (ف۱۰۴) اور میں تمہارے پاس پاس تمہارے رب کی طرف سے نشانی لایا ہوں، تو اللہ سے ڈرو اور میرا حکم مانو،'),
 (93,3,51,'بیشک میرا تمہارا سب کا رب اللہ ہے تو اسی کو پوجو (ف۱۰۵) یہ ہے سیدھا راستہ،'),
 (93,3,52,'پھر جب عیسیٰ نے ان سے کفر پایا (ف۱۰۶) بولا کون میرے مددگار ہوتے ہیں اللہ کی طرف، حواریوں نے کہا (ف۱۰۷) ہم دینِ خدا کے مددگار ہیں ہم اللہ پر ایمان لائے، اور آپ گواہ ہوجائیں کہ ہم مسلمان ہیں (ف۱۰۸)'),
 (93,3,53,'اے رب ہمارے! ہم اس پر ایمان لائے جو تو نے اتارا اور رسول کے تابع ہوئے تو ہمیں حق پر گواہی دینے والوں میں لکھ لے،'),
 (93,3,54,'اور کافروں نے مکر کیا (ف۱۰۹) اور اللہ نے ان کے ہلاک کی خفیہ تدبیر فرمائی اور اللہ سب سے بہتر چھپی تدبیر والا ہے (ف۱۱۰)'),
 (93,3,55,'یاد کرو جب اللہ نے فرمایا اے عیسیٰ میں تجھے پوری عمر تک پہنچاؤں گا (ف۱۱۱) اور تجھے اپنی طرف اٹھالوں گا (ف۱۱۲) اور تجھے کافروں سے پاک کردوں گا اور تیرے پیروؤں کو (ف۱۱۳) قیامت تک تیرے منکروں پر (ف۱۱۴) غلبہ دوں گا پھر تم سب میری طرف پلٹ کر آؤ گے تو میں تم میں فیصلہ فرمادوں گا جس بات میں جھگڑتے ہو،'),
 (93,3,56,'تو وہ جو کافر ہوئے میں انہیں دنیاو آخرت میں سخت عذاب کروں گا، اور انکا کوئی مددگار نہ ہوگا،'),
 (93,3,57,'اور وہ جو ایمان لائے اور اچھے کام کئے اللہ ان کا نیگ (انعام) انہیں بھرپور دے گا اور ظالم اللہ کو نہیں بھاتے،'),
 (93,3,58,'یہ ہم تم پر پڑھتے ہیں کچھ آیتیں اور حکمت والی نصیحت،'),
 (93,3,59,'عیسیٰ کی کہاوت اللہ کے نزدیک آدم کی طرح ہے (ف۱۱۵) اسے مٹی سے بنایا پھر فرمایا ہوجا وہ فوراً ہوجاتا ہے،'),
 (93,3,60,'اے سننے والے! یہ تیرے رب کی طرف سے حق ہے تو شک والوں میں نہ ہونا،'),
 (93,3,61,'پھر اے محبوب! جو تم سے عیسیٰ کے بارے میں حجت کریں بعد اس کے کہ تمہیں علم آچکا تو ان سے فرما دو آ ؤ ہم بلائیں اپنے بیٹے اور تمہارے بیٹے اور اپنی عورتیں اور تمہاری عورتیں اور اپنی جانیں اور تمہاری جانیں، پھر مباہلہ کریں تو جھوٹوں پر اللہ کی لعنت ڈالیں (ف۱۱۶)'),
 (93,3,62,'یہی بیشک سچا بیان ہے (ف۱۱۷) اور اللہ کے سوا کوئی معبود نہیں (ف۱۱۸) اور بیشک اللہ ہی غالب ہے حکمت والا،'),
 (93,3,63,'پھر اگر وہ منہ پھیریں تو اللہ فسادیوں کو جانتا ہے،'),
 (93,3,64,'تم فرماؤ، اے کتابیو! ایسے کلمہ کی طرف آؤ جو ہم میں تم میں یکساں ہے (ف۱۱۹) یہ کہ عبادت نہ کریں مگر خدا کی اور اس کا شریک کسی کو نہ کریں (ف۱۲۰) اور ہم میں کوئی ایک دوسرے کو رب نہ بنالے اللہ کے سوا (ف۱۲۱) پھر اگر وہ نہ مانیں تو کہہ دو تم گواہ رہو کہ ہم مسلمان ہیں،'),
 (93,3,65,'اے کتاب والو! ابراہیم کے باب میں کیوں جھگڑتے ہو توریت و انجیل تو نہ اتری مگر ان کے بعد تو کیا تمہیں عقل نہیں (ف۱۲۲)'),
 (93,3,66,'سنتے ہو یہ جو تم ہو (ف۱۲۳) اس میں جھگڑے جس کا تمہیں علم تھا (ف۱۲۴) تو اس میں (ف۱۲۵) کیوں جھگڑتے ہو جس کا تمہیں علم ہی نہیں اور اللہ جانتا ہے اور تم نہیں جانتے (ف۱۲۶)'),
 (93,3,67,'ابراہیم نہ یہودی تھے نہ نصرانی بلکہ ہر باطل سے جدا مسلمان تھے، اور مشرکوں سے نہ تھے (ف۱۲۷)'),
 (93,3,68,'بیشک سب لوگوں سے ابراہیم کے زیادہ حق دار وہ تھے جو ان کے پیرو ہوئے (ف۱۲۸) اور یہ نبی (ف۱۲۹) اور ایمان والے (ف۱۳۰) اور ایمان والوں کا ولی اللہ ہے،'),
 (93,3,69,'کتابیوں کا ایک گروہ دل سے چاہتا ہے کہ کسی طرح تمہیں گمراہ کردیں، اور وہ اپنے ہی آپ کو گمراہ کرتے ہیں اور انہیں شعور نہیں (ف۱۳۱)'),
 (93,3,70,'اے کتابیو! اللہ کی آیتوں سے کیوں کفر کرتے ہو حالانکہ تم خود گواہی ہو (ف۱۳۲)'),
 (93,3,71,'اے کتابیو! حق میں باطل کیوں ملاتے ہو (ف۱۳۳) اور حق کیوں چھپاتے ہو حالانکہ تمہیں خبر ہے،'),
 (93,3,72,'اور کتابیوں کا ایک گروہ بولا (ف۱۳۴) وہ جو ایمان والوں پر اترا (ف۱۳۵) صبح کو اس پر ایمان لاؤ اور شام کو منکر ہوجاؤ شاید وہ پھر جائیں (ف۱۳۶)'),
 (93,3,73,'اور یقین نہ لاؤ مگر اس کا جو تمہارے دین کا پیرو ہو تم فرمادو کہ اللہ ہی کی ہدایت ہدایت ہے (ف۱۳۷) (یقین کا ہے کا نہ لاؤ) اس کا کہ کسی کو ملے (ف۱۳۸) جیسا تمہیں ملا یا کوئی تم پر حجت لاسکے تمہارے رب کے پاس (ف۱۳۹) تم فرمادو کہ فضل تو اللہ ہی کے ہاتھ ہے جسے چاہے دے، اور اللہ وسعت والا علم والا ہے،'),
 (93,3,74,'اپنی رحمت سے (ف۱۴۰) خاص کرتا ہے جسے چاہے (ف۱۴۱) اور اللہ بڑے فضل والا ہے،'),
 (93,3,75,'اور کتابیوں میں کوئی وہ ہے کہ اگر تو اس کے پاس ایک ڈھیر امانت رکھے تو وہ تجھے ادا کردے گا (ف۱۴۲) اور ان میں کوئی وہ ہے کہ اگر ایک اشرفی اس کے پاس امانت رکھے تو وہ تجھے پھیر کر نہ دے گا مگر جب تک تو اس کے سر پر کھڑا رہے (ف۱۴۳) یہ اس لئے کہ وہ کہتے ہیں کہ اَن پڑھوں (ف۱۴۴) کے معاملہ میں ہم پر کوئی مؤاخذہ نہیں اور اللہ پر جان بوجھ کر جھوٹ باندھتے ہیں(ف۱۴۵)'),
 (93,3,76,'ہاں کیوں نہیں جس نے اپنا عہد پورا کیا اور پرہیزگاری کی اور بیشک پرہیزگار اللہ کو خوش آتے ہیں،'),
 (93,3,77,'جو اللہ کے عہد اور اپنی قسموں کے بدلے ذلیل دام لیتے ہیں (ف۱۴۶) آخرت میں ان کا کچھ حصہ نہیں اور اللہ نہ ان سے بات کرے نہ ان کی طرف نظر فرمائے قیامت کے دن اور نہ انہیں پاک کرے، اور ان کے لئے دردناک عذاب ہے (ف۱۴۷)'),
 (93,3,78,'اور ان میں کچھ وہ ہیں جو زبان پھیر کر کتاب میں میل (ملاوٹ) کرتے ہیں کہ تم سمجھو یہ بھی کتاب میں ہے اور وہ کتاب میں نہیں، اور وہ کہتے ہیں یہ اللہ کے پاس سے ہے اور وہ اللہ کے پاس سے نہیں، اور اللہ پر دیدہ و دانستہ جھوٹ باندھتے ہیں (ف۱۴۸)'),
 (93,3,79,'کسی آدمی کا یہ حق نہیں کہ اللہ اسے کتاب اور حکم و پیغمبری دے (ف۱۴۹) پھر وہ لوگوں سے کہے کہ اللہ کو چھوڑ کر میرے بندے ہوجاؤ (ف۱۵۰) ہاں یہ کہے گا کہ اللہ والے (ف۱۵۱) ہوجاؤ اس سبب سے کہ تم کتاب سکھاتے ہو اور اس سے کہ تم درس کرتے ہو(ف۱۵۲)'),
 (93,3,80,'اور نہ تمہیں یہ حکم دے گا (ف۱۵۳) کہ فرشتوں اور پیغمبروں کو خدا ٹھیرالو، کیا تمہیں کفر کا حکم دے گا بعد اس کے کہ تم مسلمان ہولیے (ف۱۵۴)'),
 (93,3,81,'اور یاد کرو جب اللہ نے پیغمبروں سے ان کا عہد لیا (ف۱۵۵) جو میں تم کو کتاب اور حکمت دوں پھر تشریف لائے تمہارے پاس وہ رسول (ف۱۵۶) کہ تمہاری کتابوں کی تصدیق فرمائے (ف۱۵۷) تو تم ضرور ضرور اس پر ایمان لانا اور ضرور ضرور اس کی مدد کرنا، فرمایا کیوں تم نے اقرار کیا اور اس پر میرا بھاری ذمہ لیا ؟ سب نے عرض کی، ہم نے اقرار کیا، فرمایا تو ایک دوسرے پر گواہ ہوجاؤ اور میں آپ تمہارے ساتھ گواہوں میں ہوں،'),
 (93,3,82,'تو جو کوئی اس (ف۱۵۸) کے بعد پھرے (ف۱۵۹) تو وہی لوگ فاسق ہیں (ف۱۶۰)'),
 (93,3,83,'تو کیا اللہ کے دین کے سوا اور دین چاہتے ہیں (ف۱۶۱) اور اسی کے حضور گردن رکھے ہیں جو کوئی آسمانوں اور زمین میں ہیں (ف۱۶۲) خوشی سے (ف۱۶۳) سے مجبوری سے (ف۱۶۴)'),
 (93,3,84,'اور اُسی کی طرف پھیریں گے، یوں کہو کہ ہم ایمان لائے اللہ پر اور اس پر جو ہماری طرف اترا اور جو اترا ابراہیم اور اسماعیل اور اسحاق اور یعقوب اور ان کے بیٹوں پر اور جو کچھ ملا موسیٰ اور عیسیٰ اور انبیاء کو ان کے رب سے، ہم ان میں کسی پر ایمان میں فرق نہیں کرتے (ف۱۶۵) اور ہم اسی کے حضور گردن جھکائے ہیں'),
 (93,3,85,'اور جو اسلام کے سوا کوئی دین چاہے گا وہ ہرگز اس سے قبول نہ کیا جائے گا اور وہ آخرت میں زیاں کاروں سے ہے،'),
 (93,3,86,'کیونکر اللہ ایسی قوم کی ہدایت چاہے جو ایمان لاکر کافر ہوگئے (ف۱۶۶) اور گواہی دے چکے تھے کہ رسول (ف۱۶۷) سچا ہے اور انہیں کھلی نشانیاں آچکی تھیں (ف۱۶۸) اور اللہ ظالموں کو ہدایت نہیں کرتا'),
 (93,3,87,'ان کا بدلہ یہ ہے کہ ان پر لعنت ہے اللہ اور فرشتوں اور آدمیوں کی سب کی،'),
 (93,3,88,'ہمیشہ اس میں رہیں، نہ ان پر سے عذاب ہلکا ہو اور نہ انہیں مہلت دی جائے،'),
 (93,3,89,'مگر جنہوں نے اس کے بعد توبہ کی (ف۱۶۹) اور آپا سنبھالا تو ضرور اللہ بخشنے والا مہربان ہے،'),
 (93,3,90,'بیشک وہ جو ایمان لاکر کافر ہوئے پھر اور کفر میں بڑھے (ف۱۷۰) ان کی توبہ ہرگز قبول نہ ہوگی (ف۱۷۱) اور وہی ہیں بہکے ہوئے،'),
 (93,3,91,'وہ جو کافر ہوئے اور کافر ہی مرے ان میں کسی سے زمین بھر سونا ہرگز قبول نہ کیا جائے گا اگرچہ اپنی خلاصی کو دے، ان کے لئے دردناک عذاب ہے اور ان کا کوئی یار نہیں۔'),
 (93,3,92,'تم ہرگز بھلائی کو نہ پہنچو گے جب تک راہِ خدا میں اپنی پیاری چیز نہ خرچ کرو (ف۱۷۲) اور تم جو کچھ خرچ کرو اللہ کو معلوم ہے،'),
 (93,3,93,'سب کھانے بنی اسرائیل کو حلال تھے مگر وہ جو یعقوبؑ نے اپنے اوپر حرام کرلیا تھا توریت اترنے سے پہلے تم فرماؤ توریت لاکر پڑھو اگر سچے ہو(ف۱۷۳)'),
 (93,3,94,'تو اس کے بعد جو اللہ پر جھوٹ باندھے (ف۱۷۴) تو وہی ظالم ہیں،'),
 (93,3,95,'تم فرماؤ اللہ سچا ہے، تو ابراہیم کے دین پر چلو (ف۱۷۵) جو ہر باطل سے جدا تھے اور شرک والوں میں نہ تھے،'),
 (93,3,96,'بیشک سب میں پہلا گھر جو لوگوں کی عبادت کو مقرر ہوا وہ ہے جو مکہ میں ہے برکت والا اور سارے جہان کا راہنما (ف۱۷۶)'),
 (93,3,97,'اس میں کھلی نشانیاں ہیں (ف۱۷۷) ابراہیم کے کھڑے ہونے کی جگہ (ف۱۷۸) اور جو اس میں آئے امان میں ہو (ف۱۷۹) اور اللہ کے لئے لوگوں پر اس گھر کا حج کرنا ہے جو اس تک چل سکے (ف۱۸۰) اور جو منکر ہو تو اللہ سارے جہان سے بے پرواہ ہے (ف۱۸۱)'),
 (93,3,98,'تم فرماؤ اے کتابیو! اللہ کی آیتیں کیوں نہیں مانتے (ف۱۸۲) اور تمہارے کام اللہ سامنے ہیں،'),
 (93,3,99,'تم فرماؤ اے کتابیو! کیوں اللہ کی راہ سے روکتے ہو (ف۱۸۳) اسے جو ایمان لائے اسے ٹیڑھا کیا چاہتے ہو اور تم خود اس پر گواہ ہو (ف۱۸۴) اور اللہ تمہارے کوتکوں (برے اعمال، کرتوت) سے بے خبر نہیں،'),
 (93,3,100,'اے ایمان والو! اگر تم کچھ کتابیوں کے کہے پر چلے تو وہ تمہارے ایمان کے بعد کافر کر چھوڑیں گے(ف۱۸۵)'),
 (93,3,101,'اور تم کیوں کر کفر کروگے تم پر اللہ کی آیتیں پڑھی جاتی ہیں اور تم میں اس کا رسول تشریف لایا اور جس نے اللہ کا سہارا لیا تو ضرور وہ سیدھی راہ دکھایا گیا،'),
 (93,3,102,'اے ایمان والو! اللہ سے ڈرو جیسا اس سے ڈرنے کا حق ہے اور ہرگز نہ مرنا مگر مسلمان،'),
 (93,3,103,'اور اللہ کی رسی مضبوط تھام لو (ف۱۸۶) سب مل کر اور آپس میں پھٹ نہ جانا (فرقوں میں نہ بٹ جانا) (ف۱۸۷) اور اللہ کا احسان اپنے اوپر یاد کرو جب تم میں بیر تھا اس نے تمہارے دلوں میں ملاپ کردیا تو اس کے فضل سے تم آپس میں بھائی ہوگئے (ف۱۸۸) اور تم ایک غار دوزخ کے کنارے پر تھے (ف۱۸۹) تو اس نے تمہیں اس سے بچادیا (ف۱۹۰) اللہ تم سے یوں ہی اپنی آیتیں بیان فرماتا ہے کہ کہیں تم ہدایت پاؤ،'),
 (93,3,104,'اور تم میں ایک گروہ ایسا ہونا چاہئے کہ بھلائی کی طرف بلائیں اور اچھی بات کا حکم دیں اور بری سے منع کریں (ف۱۹۱) اور یہی لوگ مراد کو پہنچے (ف۱۹۲)'),
 (93,3,105,'اور ان جیسے نہ ہونا جو آپس میں پھٹ گئے اور ان میں پھوٹ پڑگئی (ف۱۹۳) بعد اس کے کہ روشن نشانیاں انہیں آچکی تھیں (ف۱۹۴) اور ان کے لیے بڑا عذاب ہے،'),
 (93,3,106,'جس دن کچھ منہ اونجالے ہوں گے اور کچھ منہ کالے تو وہ جن کے منہ کالے ہوئے (ف۱۹۵) کیا تم ایمان لاکر کافر ہوئے (ف۱۹۶) تو اب عذاب چکھو اپنے کفر کا بدلہ،'),
 (93,3,107,'اور وہ جن کے منہ اونجالے ہوئے (ف۱۹۷) وہ اللہ کی رحمت میں ہیں وہ ہمیشہ اس میں رہیں گے،'),
 (93,3,108,'یہ اللہ کی آیتیں ہیں کہ ہم ٹھیک ٹھیک تم پر پڑھتے ہیں، اور اللہ جہاں والوں پر ظلم نہیں چاہتا(ف۱۹۸)'),
 (93,3,109,'اور اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے، اور اللہ ہی کی طرف سب کاموں کی رجوع ہے،'),
 (93,3,110,'تم بہتر ہو (ف۱۹۹) ان امتوں میں جو لوگوں میں ظاہر ہوئیں بھلائی کا حکم دیتے ہو اور برائی سے منع کرتے ہو اور اللہ پر ایمان رکھتے ہو، اور اگر کتابی ایمان لاتے (ف۲۰۰) تو ان کا بھلا تھا، ان میں کچھ مسلمان ہیں (ف۲۰۱) اور زیادہ کافر،'),
 (93,3,111,'وہ تمہارے کچھ نہ بگاڑیں گے مگر یہی ستانا (ف۲۰۲) اور اگر تم سے لڑیں تو تمہارے سامنے سے پیٹھ پھیر جائیں گے (ف۲۰۳) پھر ان کی مدد نہ ہوگی،'),
 (93,3,112,'ان پر جمادی گئی خواری جہاں ہوں امان نہ پائیں (ف۲۰۴) مگر اللہ کی ڈور (ف۲۰۵) اور آدمیوں کی ڈور سے (ف۲۰۶) اور غضب الٰہی کے سزاوار ہوئے اور ان پر جمادی گئی محتاجی (ف۲۰۷) یہ اس لئے کہ وہ اللہ کی آیتوں سے کفر کرتے اور پیغمبروں کو ناحق شہید کرتے، یہ اس لئے کہ نا فرمانبردار اور سرکش تھے،'),
 (93,3,113,'سب ایک سے نہیں کتابیوں میں کچھ وہ ہیں کہ حق پر قائم ہیں (ف۲۰۸) اللہ کی آیتیں پڑھتے ہیں رات کی گھڑیوں میں اور سجدہ کرتے ہیں (ف۲۰۹)'),
 (93,3,114,'اللہ اور پچھلے دن پر ایمان لاتے ہیں اور بھلائی کا حکم دیتے اور برائی سے منع کرتے ہیں (ف۲۱۰) اور نیک کاموں پر دوڑتے ہیں، اور یہ لوگ لائق ہیں،'),
 (93,3,115,'اور وہ جو بھلائی کریں ان کا حق نہ مارا جائے گا اور اللہ کو معلوم ہیں ڈر والے (ف۲۱۱)'),
 (93,3,116,'وہ جو کافر ہوئے ان کے مال اور اولاد (ف۲۱۲) ان کو اللہ سے کچھ نہ بچالیں گے اور وہ جہنمی ہیں ان کو ہمیشہ اس میں رہنا (ف۲۱۳)'),
 (93,3,117,'کہاوت اس کی جو اس دنیا میں زندگی میں (ف۲۱۴) خرچ کرتے ہیں اس ہوا کی سی ہے جس میں پالا ہو وہ ایک ایسی قوم کی کھیتی پر پڑی جو اپنا ہی برا کرتے تھے تو اسے بالکل مارگئی (ف۲۱۵) اور اللہ نے ان پر ظلم نہ کیا ہاں وہ خود اپنی جانوں پر ظلم کرتے ہیں،'),
 (93,3,118,'اے ایمان والو! غیروں کو اپنا راز دار نہ بناؤ (ف۲۱۶) وہ تمہاری برائی میں کمی نہیں کرتے ان کی آرزو ہے، جتنی ایذا پہنچے بیَر ان کی باتوں سے جھلک اٹھا اور وہ (ف۲۱۷) جو سینے میں چھپائے ہیں اور بڑا ہے، ہم نے نشانیاں تمہیں کھول کر سنادیں اگر تمہیں عقل ہو (ف۲۱۸)'),
 (93,3,119,'سنتے ہو یہ جو تم ہو تم تو انہیں چاہتے ہو (ف۲۱۹) اور وہ تمہیں نہیں چاہتے (ف۲۲۰) اور حال یہ کہ تم سب کتابوں پر ایمان لاتے ہو (ف۲۲۱) اور وہ جب تم سے ملتے ہیں کہتے ہیں ہم ایمان لائے (ف۲۲۲) اور اکیلے ہوں تو تم پر انگلیاں چبائیں غصہ سے تم فرمادو کہ مرجاؤ اپنی گھٹن (قلبی جلن) میں (ف۲۲۳) اللہ خوب جانتا ہے دلوں کی بات،'),
 (93,3,120,'تمہیں کوئی بھلائی پہنچے تو انہیں برا لگے (ف۲۲۴) اور تم کہ برائی پہنچے تو اس پر خوش ہوں، اور اگر تم صبر اور پرہیزگاری کیے رہو (ف۲۲۵) تو ان کا داؤ تمہارا کچھ نہ بگاڑے گا، بیشک ان کے سب کام خدا کے گھیرے میں ہیں،'),
 (93,3,121,'اور یاد کرو اے محبوب! جب تم صبح کو (ف۲۲۶) اپنے دولت خانہ سے برآمد ہوئے مسلمانوں کو لڑائی کے مور چوں پر قائم کرتے (ف۲۲۷) اور اللہ سنتا جانتا ہے،'),
 (93,3,122,'جب تم میں کے دو گروہوں کا ارادہ ہوا کہ نامردی کرجائیں (ف۲۲۸) اور اللہ ان کا سنبھالنے والا ہے اور مسلمانوں کو اللہ ہی پر بھروسہ چاہئے،'),
 (93,3,123,'اور بیشک اللہ نے بدر میں تمہاری مدد کی جب تم بالکل بے سر و سامان تھے (ف۲۲۹) تو اللہ سے ڈرو کہیں تم شکر گزار ہو،'),
 (93,3,124,'جب اے محبوب تم مسلمانوں سے فرماتے تھے کیا تمہیں یہ کافی نہیں کہ تمہارا رب تمہاری مدد کرے تین ہزار فرشتہ اتار کر،'),
 (93,3,125,'ہا ں کیوں نہیں اگر تم صبرو تقویٰ کرو اور کافر اسی دم تم پر آپڑیں تو تمہارا رب تمہاری مدد کو پانچ ہزار فرشتے نشان والے بھیجے گا (ف۲۳۰)'),
 (93,3,126,'اور یہ فتح اللہ نے نہ کی مگر تمہاری خوشی کے لئے اور اسی لئے کہ اس سے تمہارے دلوں کو چین ملے (ف۲۳۱) اور مدد نہیں مگر اللہ غالب حکمت والے کے پاس سے (ف۲۳۲)'),
 (93,3,127,'اس لئے کہ کافروں کا ایک حصہ کاٹ دے (ف۲۳۳) یا انہیں ذلیل کرے کہ نامراد پھر جائیں،'),
 (93,3,128,'یہ بات تمہارے ہاتھ نہیں یا انہیں توبہ کی توفیق دے یا ان پر عذاب کرے کہ وہ ظالم ہیں،'),
 (93,3,129,'اور اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے جسے چاہے بخشے اور جسے چاہے عذاب کرے، اور اللہ بخشنے والا مہربان،'),
 (93,3,130,'اے ایمان والوں سود دونا دون نہ کھاؤ (ف۲۳۴) اللہ سے ڈرو اس امید پر کہ تمہیں فلاح ملے،'),
 (93,3,131,'اور اس آگ سے بچو جو کافروں کے لئے تیار رکھی ہے (ف۲۳۵)'),
 (93,3,132,'اور اللہ و رسول کے فرمانبردار رہو (ف۲۳۶) اس امید پر کہ تم رحم کیے جاؤ،'),
 (93,3,133,'اور دوڑو (ف۲۳۷) اپنے رب کی بخشش اور ایسی جنت کی طرف جس کی چوڑان میں سب آسمان و زمین پرہیزگاروں کے لئے تیار کر رکھی ہے'),
 (93,3,134,'(ف۲۳۹) وہ جو اللہ کے راہ میں خرچ کرتے ہیں خوشی میں اور رنج میں (ف۲۴۰) اور غصہ پینے والے اور لوگوں سے درگزر کرنے والے، اور نیک لوگ اللہ کے محبوب ہیں،'),
 (93,3,135,'اور وہ کہ جب کوئی بے حیائی یا اپنی جانوں پر ظلم کریں (ف۲۴۱) اللہ کو یاد کرکے اپنے گناہوں کی معافی چاہیں (ف۲۴۲) اور گناہ کون بخشے سوا اللہ کے، اور اپنے کیے پر جان بوجھ کر اڑ نہ جائیں،'),
 (93,3,136,'ایسوں کو بدلہ ان کے رب کی بخشش اور جنتیں ہیں (ف۲۴۳) جن کے نیچے نہریں رواں ہمیشہ ان میں رہیں اور کامیوں (نیک لوگوں) کا اچھا نیگ (انعام، حصہ) ہے (ف۲۴۴)'),
 (93,3,137,'تم سے پہلے کچھ طریقے برتاؤ میں آچکے ہیں (ف۲۴۵) تو زمین میں چل کر دیکھو کیسا انجام ہوا جھٹلانے والوں کا (ف۲۴۶)'),
 (93,3,138,'یہ لوگوں کو بتانا اور راہ دکھانا اور پرہیزگاروں کو نصیحت ہے،'),
 (93,3,139,'اور نہ سستی کرو اور نہ غم کھاؤ (ف۲۴۷) تم ہی غالب آؤ گے اگر ایمان رکھتے ہو،'),
 (93,3,140,'اگر تمہیں (ف۲۴۸) کوئی تکلیف پہنچی تو وہ لوگ بھی ویسی ہی تکلیف پاچکے ہیں (ف۲۴۹) اور یہ دن ہیں جن میں ہم نے لوگوں کے لیے باریاں رکھی ہیں (ف۲۵۰) اور اس لئے کہ اللہ پہچان کرادے ایمان والوں کی (ف۲۵۱) اور تم میں سے کچھ لوگوں کو شہادت کا مرتبہ دے اور اللہ دوست نہیں رکھتا ظالموں کو،'),
 (93,3,141,'اور اس لئے کہ اللہ مسلمانوں کا نکھار کردے (ف۲۵۲) اور کافروں کو مٹادے (ف۲۵۳)'),
 (93,3,142,'کیا اس گمان میں ہو کہ جنت میں چلے جاؤ گے اور ابھی اللہ نے تمہارے غازیوں کا امتحان نہ لیا اور نہ صبر والوں آزمائش کی(ف۲۵۴)'),
 (93,3,143,'اور تم تو موت کی تمنا کیا کرتے تھے اس کے ملنے سے پہلے (ف۲۵۵) تو اب وہ تمہیں نظر آئی آنکھوں کے سامنے،'),
 (93,3,144,'اور محمد تو ایک رسول (ف۲۵۶) ان سے پہلے اور رسول ہوچکے (ف۲۵۷) تو کیا اگر وہ انتقال فرمائیں یا شہید ہوں تو تم الٹے پاؤں پھر جاؤں گے اور جو الٹے پاؤں پھرے گا اللہ کا کچھ نقصان نہ کرے گا، اور عنقریب اللہ شکر والوں کو صلہ دے گا،'),
 (93,3,145,'اور کوئی جان بے حکم خدا مر نہیں سکتی (ف۲۵۹) سب کا وقت لکھا رکھا ہے (ف۲۶۰) اور دنیا کا انعام چاہے ۰ف۲۶۱) ہم اس میں سے اسے دیں اور جو آخرت کا انعام چاہے ہم اس میں سے اسے دیں (ف۲۶۲) اور قریب ہے کہ ہم شکر والوں کو صلہ عطا کریں،'),
 (93,3,146,'اور کتنے ہی انبیاء نے جہاد کیا ان کے ساتھ بہت خدا والے تھے، تو نہ سست پڑے ان مصیبتوں سے جو اللہ کی راہ میں انہیں پہنچیں اور نہ کمزور ہوئے اور نہ دبے (ف۲۶۳) اور صبر والے اللہ کو محبوب ہیں،'),
 (93,3,147,'اور وہ کچھ بھی نہ کہتے تھے سوا اس دعا کے (ف۲۶۴) کہ اے ہمارے رب بخش دے ہمارے گناہ اور جو زیادتیاں ہم نے اپنے کام کیں (ف۲۶۵) اور ہمارے قدم جما دے اور ہمیں ان کافر لوگوں پر مدد دے(ف۲۶۶)'),
 (93,3,148,'تو اللہ نے انہیں دنیا کا انعام دیا (ف۲۶۷) اور آخرت کے ثواب کی خوبی (ف۲۶۸) اور نیکی والے اللہ کو پیارے ہیں،'),
 (93,3,149,'اے ایمان والو! اگر تم کافروں کے کہے پر چلے (ف۲۶۹) تو وہ تمہیں الٹے پاؤں لوٹادیں گے (ف۲۷۰) پھر ٹوٹا کھا کے پلٹ جاؤ گے (ف۲۷۱)'),
 (93,3,150,'بلکہ اللہ تمہارا مولا ہے اور وہ سب سے بہتر مددگار،'),
 (93,3,151,'کوئی دم جاتا ہے کہ ہم کافروں کے دلوں میں رعب ڈالیں گے (ف۲۷۲) کہ انہوں نے اللہ کا شریک ٹھہرایا جس پر اس نے کوئی سمجھ نہ اتاری اور ان کا ٹھکانا دوزخ ہے، اور کیا برا ٹھکانا ناانصافوں کا،'),
 (93,3,152,'اور بیشک اللہ نے تمہیں سچ کر دکھایا اپنا وعدہ جب کہ تم اس کے حکم سے کافروں کو قتل کرتے تھے (ف۲۷۳) یہاں تک کہ جب تم نے بزدلی کی اور حکم میں جھگڑا ڈالا (ف۲۷۴) اور نافرمانی کی (ف۲۷۵) بعد اس کے کہ اللہ تمہیں دکھا چکا تمہاری خوشی کی بات (ف۲۷۶) تم میں کوئی دنیا چاہتا تھا (ف۲۷۷) اور تم میں کوئی آخرت چاہتا تھا (ف۲۷۸) پھر تمہارا منہ ان سے پھیردیا کہ تمہیں آزمائے (ف۲۷۹) اور بیشک اس نے تمہیں معاف کردیا، اور اللہ مسلمانوں پر فضل کرتا ہے،'),
 (93,3,153,'جب تم منہ اٹھائے چلے جاتے تھے اور پیٹھ پھیر کر کسی کو نہ دیکھتے اور دوسری جماعت میں ہمارے رسول تمہیں پکار رہے تھے (ف۲۸۰) تو تمہیں غم کا بدلہ غم دیا (ف۲۸۱) اور معافی اس لئے سنائی کہ جو ہاتھ سے گیا اور جو افتاد پڑی اس کا رنج نہ کرو اور اللہ کوتمہارے کاموں کی خبر ہے،'),
 (93,3,154,'پھر تم پر غم کے بعد چین کی نیند اتاری (ف۲۸۲) کہ تمہاری ایک جماعت کو گھیرے تھی (ف۲۸۳) اور ایک گروہ کو (ف۲۸۴) اپنی جان کی پڑی تھی (ف۲۸۵) اللہ پر بے جا گمان کرتے تھے (ف۲۸۶) جاہلیت کے سے گمان، کہتے کیا اس کام میں کچھ ہمارا بھی اختیار ہے تم فرمادو کہ اختیار تو سارا اللہ کا ہے (ف۲۸۷) اپنے دلوں میں چھپاتے ہیں (ف۲۸۸) جو تم پر ظاہر نہیں کرتے کہتے ہیں، ہمارا کچھ بس ہوتا (ف۲۸۹) تو ہم یہاں نہ مارے جاتے، تم فرمادو کہ اگر تم اپنے گھروں میں ہوتے جب بھی جن کا مارا جانا لکھا جاچکا تھا اپنی قتل گاہوں تک نکل آتے (ف۲۹۰) اور اس لئے کہ اللہ تمہارے سینوں کی بات آزمائے اور جو کچھ تمہارے دلو ں میں ہے (ف۲۹۱) اسے کھول دے اور اللہ دلوں کی بات جانتا ہے(ف۲۹۲)'),
 (93,3,155,'بیشک وہ جو تم میں سے پھرگئے (ف۲۹۳) جس دن دونوں فوجیں ملی تھیں انہیں شیطان ہی نے لغزش دی ان کے بعض اعمال کے باعث (ف۲۹۴) اور بیشک اللہ نے انہیں معاف فرمادیا، بیشک اللہ بخشنے والا حلم والا ہے،'),
 (93,3,156,'اے ایمان والو! ان کافروں (ف۲۹۵) کی طرح نہ ہونا جنہوں نے اپنے بھائیوں کی نسبت کہا کہ جب وہ سفر یا جہاد کو گئے (ف۲۹۶) کہ ہمارے پاس ہوتے تو نہ مرتے اور نہ مارے اتے اس لئے اللہ ان کے دلوں میں اس کا افسوس رکھے، اور اللہ جِلاتا اور مارتا ہے (ف۲۹۷) اور اللہ تمہارے کام دیکھ رہا ہے،'),
 (93,3,157,'اور بیشک اگر تم اللہ کی راہ میں مارے جاؤ یا مرجاؤ تو اللہ کی بخشش اور رحمت (ف۲۹۹) ان کے سارے دھن دولت سے بہتر ہے،'),
 (93,3,158,'اور اگر تم مرو یا مارے جاؤ تو اللہ کی طرف اٹھنا ہے (ف۳۰۰)'),
 (93,3,159,'تو کیسی کچھ اللہ کی مہربانی ہے کہ اے محبوب! تم ان کے لئے نرم دل ہوئے (ف۳۰۱) اور اگر تند مزاج سخت دل ہوتے (ف۳۰۲) تو وہ ضرور تمہارے گرد سے پریشان ہوجاتے تو تم انہیں معاف فرماؤ او ر ان کی شفاعت کرو (ف۳۰۳) اور کاموں میں ان سے مشورہ لو (ف۳۰۴) اور جو کسی بات کا ارادہ پکا کرلو تو اللہ پر بھروسہ کرو (ف۳۰۵) بیشک توکل والے اللہ کو پیارے ہیں،'),
 (93,3,160,'اگر اللہ تمہاری مدد کرے تو کوئی تم پر غالب نہیں آسکتا (ف۳۰۶) اور اگر وہ تمہیں چھوڑ دے تو ایسا کون ہے جو پھر تمہاری مدد کرے اور مسلمانوں کو اللہ ہی پر بھروسہ چاہئے،'),
 (93,3,161,'اور کسی نبی پر یہ گمان نہیں ہوسکتا کہ وہ کچھ چھپا رکھے (ف۳۰۷) اور جو چھپا رکھے وہ قیامت کے دن اپنی چھپائی چیز لے کر آئے گا پھر ہر جان کو ان کی کمائی بھرپور دی جائے گی اور ان پر ظلم نہ ہوگا،'),
 (93,3,162,'تو کیا جو اللہ کی مرضی پر چلا (ف۳۰۸) وہ اس جیسا ہوگا جس نے اللہ کا غضب اوڑھا (ف۳۰۹) اور اس کا ٹھکانا جہنم ہے، اور کیا بری جگہ پلٹنے کی،'),
 (93,3,163,'وہ اللہ کے یہاں درجہ درجہ ہیں (ف۳۱۰) اور اللہ ان کے کام دیکھتا ہے،'),
 (93,3,164,'بیشک اللہ کا بڑا احسان ہوا (ف۳۱۱) مسلمانوں پر کہ ان میں انہیں میں سے (ف۳۱۲) ایک رسول (ف۳۱۳) بھیجا جو ان پر اس کی آیتیں پڑھتا ہے (ف۳۱۴) اور انہیں پاک کرتا ہے (ف۳۱۵) اور انہیں کتاب و حکمت سکھاتا ہے (ف۳۱۶) اور وہ ضرور اس سے پہلے کھلی گمراہی میں تھے(ف۳۱۷)'),
 (93,3,165,'کیا جب تمہیں کوئی مصیبت پہنچے (ف۳۱۸) کہ اس سے دونی تم پہنچا چکے ہو (ف۳۱۹) تو کہنے لگو کہ یہ کہاں سے آئی (ف۳۲۰) تم فرمادو کہ وہ تمہاری ہی طرف سے آئی (ف۳۲۱) بیشک اللہ سب کچھ کرسکتا ہے،'),
 (93,3,166,'اور وہ مصیبت جو تم پر آئی (ف۳۲۲) جس دن دونوں فوجیں (ف۳۲۳) ملی تھیں وہ اللہ کے حکم سے تھی اور اس لئے کہ پہچان کرادے ایمان والوں کی،'),
 (93,3,167,'اور اس لئے کہ پہچان کرادے، ان کی جو منافق ہوئے (ف۳۲۴) اور ان سے کہا گیا کہ ا ٓؤ (ف۳۲۶) اللہ کی راہ میں لڑو یا دشمن کو ہٹاؤ (ف۳۲۷) بولے اگر ہم لڑائی ہوتی جانتے تو ضرو ر تمہارا ساتھ دیتے، اور اس دن ظاہری ایمان کی بہ نسبت کھلے کفر سے زیادہ قریب ہیں، اپنے منہ سے کہتے ہیں جو ان کے دل میں نہیں اور اللہ کو معلوم ہے جو چھپارہے ہیں (ف۳۲۸)'),
 (93,3,168,'وہ جنہوں نے اپنے بھائیوں کے بارے میں (ف۳۲۹) کہا اور آپ بیٹھ رہے کہ وہ ہمارا کہا مانتے (ف۳۳۰) تو نہ مارے جاتے تم فرمادو تو اپنی ہی موت ٹال دو اگر سچے ہو(ف۳۳۱)'),
 (93,3,169,'اور جو اللہ کی راہ میں مارے گئے (ف۳۳۲) ہر گز انہیں مردہ نہ خیال کرنا، بلکہ وہ اپنے رب کے پاس زندہ ہیں روزی پاتے ہیں (ف۳۳۳)'),
 (93,3,170,'شاد ہیں اس پر جو اللہ نے انہیں اپنے فضل سے دیا (ف۳۳۴) اور خوشیاں منارہے ہیں اپنے پچھلوں کی جو ابھی ان سے نہ ملے (ف۳۳۵) کہ ان پر نہ کچھ اندیشہ ہے اور نہ کچھ غم،'),
 (93,3,171,'خوشیاں مناتے ہیں اللہ کی نعمت اور فضل کی اور یہ کہ اللہ ضائع نہیں کرتا اجر مسلمانوں کا(ف۳۳۶)'),
 (93,3,172,'وہ جو اللہ و رسول کے بلانے پر حاضر ہوئے بعد اس کے کہ انہیں زخم پہنچ چکا تھا (ف۳۳۷) ان کے نکوکاروں اور پرہیزگاروں کے لئے بڑا ثواب ہے،'),
 (93,3,173,'وہ جن سے لوگوں نے کہا (ف۳۳۸) کہ لوگوں نے (ف۳۳۹) تمہارے لئے جتھا جوڑا تو ان س ے ڈرو تو ان کا ایمان اور زائد ہوا اور بولے اللہ ہم کو بس ہے اور کیا اچھا کارساز (ف۳۴۰)'),
 (93,3,174,'تو پلٹے اللہ کے احسان اور فضل سے (ف۳۴۱) کہ انہیں کوئی برائی نہ پہنچی اور اللہ کی خوشی پر چلے (ف۳۴۲) اور اللہ بڑے فضل والا ہے (ف۳۴۳)'),
 (93,3,175,'وہ تو شیطان ہی ہے کہ اپنے دوستوں سے دھمکاتا ہے (ف۳۴۴) تو ان سے نہ ڈرو (ف۳۴۵) اور مجھ سے ڈرو اگر ایمان رکھتے ہو (ف ۳۴۶)'),
 (93,3,176,'اور اے محبوب! تم ان کا کچھ غم نہ کرو جو کفر پر دوڑتے ہیں (ف۳۴۷) وہ اللہ کا کچھ بگاڑیں گے اور اللہ چاہتا ہے کہ آخرت میں ان کا کوئی حصہ نہ رکھے (ف۳۴۸) اور ان کے لئے بڑا عذاب ہے،'),
 (93,3,177,'وہ جنہوں نے ایمان کے بدلے کفر مول لیا (ف۳۴۹) اللہ کا کچھ نہ بگاڑیں گے اور ان کے لئے دردناک عذاب ہے،'),
 (93,3,178,'اور ہرگز کافر اس گمان میں نہ رہیں کہ وہ جو ہم انہیں ڈھیل دیتے ہیں کچھ ان کے لئے بھلا ہے، ہم تو اسی لئے انہیں ڈھیل دیتے ہیں کہ اور گناہ میں بڑھیں (ف۳۵۰) اور ان کے لئے ذلت کا عذاب ہے،'),
 (93,3,179,'اللہ مسلمانوں کو اس حال پر چھوڑنے کا نہیں جس پر تم ہو (ف۳۵۱) جب تک جدا نہ کردے گندے کو (ف۳۵۲) ستھرے سے (ف۳۵۳) اور اللہ کی شان یہ نہیں کہ اے عام لوگو! تمہیں غیب کا علم دے دے ہاں اللہ چن لیتا ہے اپنے رسولوں سے جسے چاہے (ف۳۵۴) تو ایمان لاؤ اللہ اور اس کے رسولوں پر اور اگر ایمان لاؤ (ف۳۵۵) اور پرہیزگاری کرو تو تمہارے لئے بڑا ثواب ہے،'),
 (93,3,180,'اور جو بخل کرتے ہیں (ف۳۵۶) اس چیز میں جو اللہ نے انہیں اپنے فضل سے دی ہرگز اسے اپنے لئے اچھا نہ سمجھیں بلکہ وہ ان کے لئے برا ہے، عنقریب وہ جس میں بخل کیا تھا قیامت کے دن ان کے گلے کا طوق ہوگا (ف۳۵۷) اور اللہ ہی وارث ہے آسمانوں اور زمین کا (ف۳۵۸) اور اللہ تمہارے کاموں سے خبردار ہے،'),
 (93,3,181,'بیشک اللہ نے سنا جنہوں نے کہا کہ اللہ محتاج ہے اور ہم غنی (ف۳۵۹) اور ہم غنی (ف۳۵۹) اب ہم لکھ رکھیں گے ان کا کہا (ف۳۶۰) اور انبیاء کو ان کا ناحق شہید کرنا (ف۳۶۱) اور فرمائیں گے کہ چکھو آگ کا عذاب،'),
 (93,3,182,'یہ بدلا ہے اس کا جو تمہارے ہاتھوں نے آگے بھیجا اور اللہ بندوں پر ظلم نہیں کرتا،'),
 (93,3,183,'وہ جو کہتے ہیں اللہ نے ہم سے اقرار کر لیا ہے کہ ہم کسی رسول پر ایمان نہ لائیں جب تک ایسی قربانی کا حکم نہ لائے جس آ گ کھائے (ف۳۶۲) تم فرمادو مجھ سے پہلے بہت رسول تمہارے پاس کھلی نشانیاں اور یہ حکم لے کر آئے جو تم کہتے ہو پھر تم نے انہیں کیوں شہید کیا اگر سچے ہو(ف۳۶۳)'),
 (93,3,184,'تو اے محبوب! اگر وہ تمہاری تکذیب کرتے ہیں تو تم سے اگلے رسولوں کی بھی تکذیب کی گئی ہے جو صاف نشانیاں (ف۳۶۴) اور صحیفے اور چمکتی کتاب (ف۳۶۵) لے کر آئے تھے'),
 (93,3,185,'ہر جان کو موت چکھنی ہے، اور تمہارے بدلے تو قیامت ہی کو پورے ملیں گے، جو آگ سے بچا کر جنت میں داخل کیا گیا وہ مراد کو پہنچا، اور دنیا کی زندگی تو یہی دھوکے کا مال ہے(ف۳۶۶)'),
 (93,3,186,'بیشک ضرور تمہاری آزمائش ہوگی تمہارے مال اور تمہاری جانوں میں (ف۳۶۷) اور بیشک ضرور تم اگلے کتاب والوں (ف۳۶۸) اور مشرکوں سے بہت کچھ برا سنو گے اور اگر تم صبر کرو اور بچتے رہو (ف۳۶۹) تو یہ بڑی ہمت کا کام ہے،'),
 (93,3,187,'اور یاد کرو جب اللہ نے عہد لیا ان سے جنہیں کتاب عطا فرمائی کہ تم ضرور اسے لوگوں سے بیان کردینا اور نہ چھپانا (ف۳۷۰) تو انہوں نے اسے اپنی پیٹھ کے پیچھے پھینک دیا اور اس کے بدلے ذلیل دام حاصل کیے (ف۳۷۱) تو کتنی بری خریداری ہے (ف۳۷۲)'),
 (93,3,188,'ہر گز نہ سمجھنا انہیں جو خوش ہوتے ہیں اپنے کیے پر اور چاہتے ہیں کہ بے کیے ان کی تعریف ہو (ف۳۷۳) ایسوں کو ہرگز عذاب سے دور نہ جاننا اور ان کے لیے دردناک عذاب ہے'),
 (93,3,189,'اور اللہ ہی کے لئے ہے آسمانوں اور زمین کی بادشاہی (ف۳۷۴) اور اللہ ہر چیز پر قادر ہے،'),
 (93,3,190,'بیشک آسمانوں اور زمین کی پیدائش اور رات اور دن کی باہم بدلیوں میں نشانیاں ہیں (ف۳۷۵) عقلمندوں کے لئے (ف۳۷۶)'),
 (93,3,191,'جو اللہ کی یاد کرت ہیں کھڑے اور بیٹھے اور کروٹ پر لیٹے (ف۳۷۷) اور آسمانوں اور زمین کی پیدائش میں غور کرتے ہیں (ف۳۷۸) اے رب ہمارے! تو نے یہ بیکار نہ بنایا (ف۳۷۹) پاکی ہے تجھے تو ہمیں دوزخ کے عذاب سے بچالے،'),
 (93,3,192,'اے رب ہمارے! بیشک جسے تو دوزخ میں لے جائے اسے ضرور تو نے رسوائی دی اور ظالموں کا کوئی مددگار نہیں،'),
 (93,3,193,'اے رب ہمارے ہم نے ایک منادی کو سنا (ف۳۸۰) کہ ایمان کے لئے ندا فرماتا ہے کہ اپنے رب پر ایمان لاؤ تو ہم ایمان لائے اے رب ہمارے تو ہمارے گنا بخش دے اور ہماری برائیاں محو فرمادے اور ہماری موت اچھوں کے ساتھ کر (ف۳۸۱)'),
 (93,3,194,'اے رب ہمارے! اور ہمیں دے وہ (ف۳۸۲) جس کا تو نے ہم سے وعدہ کیا ہے اپنے رسولوں کی معرفت اور ہمیں قیامت کے دن رسوانہ کر، بیشک تو وعدہ خلاف نہیں کرتا،'),
 (93,3,195,'تو ان کی دعا سن لی ان کے رب نے کہ میں تم میں کام والے کی محنت اکارت نہیں کرتا مرد ہو یا عورت تم آپس میں ایک ہو (ف۳۸۳) تو وہ جنہوں نے ہجرت کی اور اپنے گھروں سے نکالے گئے اور میری راہ میں ستائے گئے اور لڑے اور مارے گء ے میں ضرور ان کے سب گناہ اتار دوں گا اور ضرور انہیں باغوں میں لے جاؤں گا جن کے نیچے نہریں رواں (ف۳۸۴) اللہ کے پاس کا ثواب، اور اللہ ہی کے پاس اچھا ثواب ہے،'),
 (93,3,196,'اے سننے والے! کافروں کا شہروں میں اہلے گہلے پھرنا ہرگز تجھے دھوکا نہ دے (ف۳۱۵)'),
 (93,3,197,'تھوڑا برتنا، ان کا ٹھکانا دوزخ ہے، اور کیا ہی برا بچھونا،'),
 (93,3,198,'لیکن وہ جو اپنے رب سے ڈرتے ہیں ان کے لئے جنتیں ہیں جن کے نیچے نہریں بہیں ہمیشہ ان میں رہیں اللہ کی طرف کی، مہمانی اور جو اللہ پاس ہے وہ نیکوں کے لئے سب سے بھلا (ف۳۸۶)'),
 (93,3,199,'اور بیشک کچھ کتابیں ایسے ہیں کہ اللہ پر ایمان لاتے ہیں اور اس پر جو تمہاری طرف اترا اور جو ان کی طرف اترا (ف۳۸۷) ان کے دل اللہ کے حضور جھکے ہوئے (ف۳۸۸) اللہ کی آیتوں کے بدلے ذلیل دام نہیں لیتے (ف۳۸۹) یہ وہ ہیں، جن کا ثواب ان کے رب کے پاس ہے اور اللہ جلد حساب کرنے والا ہے،'),
 (93,3,200,'اے ایمان والو! صبر کرو (ف۳۹۰) اور صبر میں دشمنوں سے آگے رہو اور سرحد پر اسلامی ملک کی نگہبانی کرو اور اللہ سے ڈرتے رہو اس امید پر کہ کامیاب ہو،'),
 (93,4,1,'اے لوگو ! (ف۲) اپنے رب سے ڈرو جس نے تمہیں ایک جان سے پیدا کیا (ف۳) اور اسی میں سے اس کا جوڑا بنایا اور ان دونوں سے بہت سے مرد و عورت پھیلا دیئے اور اللہ سے ڈرو جس کے نام پر مانگتے ہو اور رشتوں کا لحاظ رکھو (ف۴) بیشک اللہ ہر وقت تمہیں دیکھ رہا ہے،'),
 (93,4,2,'اور یتیموں کو ان کے مال دو (ف۵) اور ستھرے (ف۶) کے بدلے گندا نہ لو (ف۷) اور ان کے مال اپنے مالوں میں ملاکر نہ کھا جاؤ، بیشک یہ بڑا گناہ ہے'),
 (93,4,3,'ا ور اگر تمہیں اندیشہ ہو کہ یتیم لڑکیوں میں انصاف نہ کرو گے (ف۸) تو نکاح میں لاؤ جو عورتیں تمہیں خوش آئیں دو دو اور تین تین او ر چار چار (ف۹) پھر اگر ڈرو کہ دو بیبیوں کو برابر نہ رکھ سکو گے تو ایک ہی کرو یا کنیزیں جن کے تم مالک ہو یہ اس سے زیادہ قریب ہے کہ تم سے ظلم نہ ہو (ف۱۰)'),
 (93,4,4,'اور عورتوں کو ان کے مہر خوشی سے دو (ف۱۱) پھر اگر وہ اپنے دل کی خوشی سے مہر میں سے تمہیں کچھ دے دیں تو اسے کھاؤ رچتا پچتا (ف۱۲)'),
 (93,4,5,'اور بے عقلوں کو (ف۱۳) ان کے مال نہ دو جو تمہارے پاس ہیں جن کو اللہ نے تمہاری بسر اوقات کیا ہے اور انہیں اس میں سے کھلاؤ اور پہناؤ اور ان سے اچھی بات کہو (ف۱۴)'),
 (93,4,6,'اور یتیموں کو آزماتے رہو (ف۱۵) یہاں تک کہ جب وہ نکاح کے قابل ہوں تو اگر تم ان کی سمجھ ٹھیک دیکھو تو ان کے مال انہیں سپرد کردو اور انہیں نہ کھاؤ حد سے بڑھ کر اور اس جلدی میں کہ کہیں بڑے نہ ہوجائیں اور جسے حاجت نہ ہو وہ بچتا رہے (ف۱۶) اور جو حاجت مند ہو وہ بقدر مناسب کھائے، پھر جب تم ان کے مال انہیں سپرد کرو تو ان پر گواہ کرلو، اور اللہ کافی ہے حساب لینے کو،'),
 (93,4,7,'مردوں کے لئے حصہ ہے اس میں سے جو چھوڑ گئے ماں باپ اور قرابت والے اور عورتوں کے لئے حصہ ہے اس میں سے جو چھوڑ گئے ماں باپ اور قرابت والے ترکہ تھوڑا ہو یا بہت، حصہ ہے اندازہ باندھا ہوا (ف۱۷)'),
 (93,4,8,'پھر بانٹتے وقت اگر رشتہ دار اور یتیم اور مسکین (ف۱۸) آجائیں تو اس میں سے انہیں بھی کچھ دو (ف۱۹) اور ان سے اچھی بات کہو (ف۲۰)'),
 (93,4,9,'اور ڈریں (ف۲۱) وہ لوگ اگر اپنے بعد ناتواں اولاد چھوڑتے تو ان کا کیسا انہیں خطرہ ہوتا تو چاہئے کہ اللہ سے ڈریں (ف۲۲) اور سیدھی بات کریں (ف۲۳)'),
 (93,4,10,'وہ جو یتیموں کا مال ناحق کھاتے ہیں وہ تو اپنے پیٹ میں نری آ گ بھرتے ہیں (ف۲۴) اور کوئی دم جاتا ہے کہ بھڑتے دھڑے (آتش کدے) میں جائیں گے،'),
 (93,4,11,'اللہ تمہیں حکم دیتا ہے (ف۲۵) تمہاری اولاد کے بارے میں (ف۲۶) بیٹے کا حصہ دو بیٹیوں برابر ہے (ف۲۷) پھر اگر نری لڑکیاں ہوں اگرچہ دو سے اوپر (ف۲۸) تو ان کو ترکہ کی دو تہائی اور اگر ایک لڑکی ہو تو اس کا آدھا (ف۲۹) اور میت کے ماں باپ کو ہر ایک کو اس کے ترکہ سے چھٹا اگر میت کے اولاد ہو (ف۳۰) پھر اگر اس کی اولاد نہ ہو اور ماں باپ چھوڑے (ف۳۱) تو ماں کا تہا ئی پھر اگر اس کے کئی بہن بھا ئی ہو ں (ف۳۲) تو ماں کا چھٹا (ف۳۳) بعد اس و صیت کے جو کر گیا اور دین کے (ف۳۴) تمہارے باپ اور تمہارے بیٹے تم کیا جانو کہ ان میں کون تمہارے زیادہ کام آئے گا (ف۳۵) یہ حصہ باندھا ہوا ہے اللہ کی طرف سے بیشک اللہ علم والا حکمت والا ہے،'),
 (93,4,12,'اور تمہاری بیبیاں جو چھوڑ جائیں اس میں سے تمہیں آدھا ہے اگر ان کی اولاد نہ ہو، پھر اگر ان کی اولاد ہو تو ان کے ترکہ میں سے تمہیں چوتھائی ہے جو وصیت وہ کر گئیں اور دَین نکال کر اور تمہارے ترکہ میں عورتوں کا چوتھائی ہے (ف۳۶) اگر تمہارے اولاد نہ ہو پھر اگر تمہارے اولاد ہو تو ان کا تمہارے ترکہ میں سے آٹھواں (ف۳۷) جو وصیت تم کر جاؤ اور دین نکال کر، اور اگر کسی ایسے مرد یا عورت کا ترکہ بٹنا ہو جس نے ماں باپ اولاد کچھ نہ چھوڑے اور ماں کی طرف سے اس کا بھائی یا بہن ہے تو ان میں سے ہر ایک کو چھٹا پھر اگر وہ بہن بھائی ایک سے زیادہ ہوں تو سب تہائی میں شریک ہیں (ف۳۸) میت کی وصیت اور دین نکال کر جس میں اس نے نقصان نہ پہنچایا ہو (ف۳۹) یہ اللہ کا ارشاد ہے اور اللہ علم والا حلم والا ہے،'),
 (93,4,13,'یہ اللہ کی حدیں ہیں اور جو حکم مانے اللہ اور اللہ کے رسول کا اللہ اسے باغوں میں لے جائے گا جن کے نیچے نہریں رواں ہمیشہ ان میں رہیں گے، اور یہی ہے بڑی کامیابی،'),
 (93,4,14,'اور جو اللہ اور اس کے رسول کی نافرمانی کرے اور اس کی کل حدوں سے بڑھ جائے اللہ اسے آگ میں داخل کرے گا جس میں ہمیشہ رہے گا اور اس کے لئے خواری کا عذاب ہے (ف۴۰)'),
 (93,4,15,'اور تمہاری عورتوں میں جو بدکاری کریں ان پر خاص اپنے میں کے (ف۴۱) چار مردوں کی گواہی لو پھر اگر وہ گواہی دے دیں تو ان عورتوں کو گھر میں بند رکھو (ف۴۲) یہاں تک کہ انہیں موت اٹھالے یا اللہ ان کی کچھ راہ نکالے (ف۴۳)'),
 (93,4,16,'اور تم میں جو مرد عورت ایسا کریں ان کو ایذا دو (ف۴۴) پھر اگر وہ توبہ کرلیں اور نیک ہوجائیں تو ان کا پیچھا چھوڑ دو، بیشک اللہ بڑا توبہ قبول کرنے والا مہربان ہے (ف۴۵)'),
 (93,4,17,'وہ توبہ جس کا قبول کرنا اللہ نے اپنے فضل سے لازم کرلیا ہے وہ انہیں کی ہے جو نادانی سے برائی کر بیٹھیں پھر تھوڑی دیر میں توبہ کرلیں (ف۴۶) ایسوں پر اللہ اپنی رحمت سے رجوع کرتا ہے، اور اللہ علم و حکمت والا ہے،'),
 (93,4,18,'اور وہ توبہ ان کی نہیں جو گناہوں میں لگے رہتے ہیں، (ف۴۷) یہاں تک کہ جب ان میں کسی کو موت آئے تو کہے اب م یں نے توبہ کی (ف۴۸) اور نہ ان کی جو کافر مریں ان کے لئے ہم نے دردناک عذاب تیار رکھا ہے (ف۴۹)'),
 (93,4,19,'اے ایمان والو! تمہیں حلال نہیں کہ عورتوں کے وارث بن جاؤ زبردستی (ف۵۰) اور عورتوں کو روکو نہیں اس نیت سے کہ جو مہر ان کو دیا تھا اس میں سے کچھ لے لو (ف۵۱) مگر اس صورت میں کہ صریح بے حیا ئی کا کام کریں (ف۵۲) اور ان سے اچھا برتاؤ کرو (ف۵۳) پھر اگر وہ تمہیں پسند نہ آئیں (ف۵۴) تو قریب ہے کہ کوئی چیز تمہیں ناپسند ہو اور اللہ اس میں بہت بھلائی رکھے(ف۵۵)'),
 (93,4,20,'اور اگر تم ایک بی بی کے بدلے دوسری بدلنا چاہو (ف۵۶) اور اسے ڈھیروں مال دے چکے ہو (ف۵۷) تو اس میں سے کچھ واپس نہ لو (ف۵۸) کیا اسے واپس لو گے جھوٹ باندھ کر اور کھلے گناہ سے (ف۵۹)'),
 (93,4,21,'اور کیونکر اسے واپس لوگے حالانکہ تم میں ایک دوسرے کے سامنے بے پردہ ہولیا اور وہ تم سے گاڑھا عہد لے چکیں(ف۶۰)'),
 (93,4,22,'اور باپ دادا کی منکوحہ سے نکاح نہ کرو (ف۶۱) مگر جو ہو گزرا وہ بیشک بے حیائی (ف۶۲) اور غضب کا کام ہے، اور بہت بری راہ(ف۶۳)'),
 (93,4,23,'حرام ہوئیں تم پر تمہاری مائیں (ف۶۴) اور بیٹیاں (ف۶۵) اور بہنیں اور پھوپھیاں اور خالائیں اور بھتیجیاں اور بھانجیاں (ف۶۶) اور تمہاری مائیں جنہوں نے دودھ پلایا (ف۶۷) اور دودھ کی بہنیں اور عورتوں کی مائیں (ف۶۸) اور ان کی بیٹیاں جو تمہاری گود میں ہیں (ف۶۹) ان بیبیوں سے جن سے تم صحبت کرچکے ہو تو پھر اگر تم نے ان سے صحبت نہ کی ہو تو ان کی بیٹیوں سے حرج نہیں (ف۷۰) اور تمہاری نسلی بیٹوں کی بیبیں (ف۷۱) اور دو بہنیں اکٹھی کرنا (ف۷۲) مگر جو ہو گزرا بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,4,24,'اور حرام ہیں شوہر دار عورتیں مگر کافروں کی عورتیں جو تمہاری ملک میں آجائیں (ف۷۳) یہ اللہ کا نوشتہ ہے تم پر اور ان (ف۷۴) کے سوا جو رہیں وہ تمہیں حلال ہیں کہ اپنے مالوں کے عوض تلاش کرو قید لاتے (ف۷۵) نہ پانی گراتے (ف۷۶) تو جن عورتوں کو نکاح میں لانا چاہو ان کے بندھے ہوئے مہر انہیں دو، اور قرار داد کے بعد اگر تمہارے آپس میں کچھ رضامندی ہوجاوے تو اس میں گناہ نہیں (ف۷۷) بیشک اللہ علم و حکمت والا ہے،'),
 (93,4,25,'اور تم میں بے مقدوری کے باعث جن کے نکاح میں آزاد عورتیں ایمان والیاں نہ ہوں تو ان سے نکاح کرے جو تمہارے ہاتھ کی مِلک ہیں ایمان والی کنیزیں (ف۷۸) اور اللہ تمہارے ایمان کو خوب جانتا ہے، تم میں ایک دوسرے سے ہے تو ان سے نکاح کرو ان کے مالکوں کی اجازت سے (ف۸۰) اور حسب دستور ان کے مہر انہیں دو (ف۸۱) قید میں آتیاں نہ مستی نکالتی اور نہ یار بناتی (ف۸۲) جب وہ قید میں آجائیں (ف۸۳) پھر برا کام کریں تو ان پر اس سزا کی آدھی ہے جو آزاد عورتوں پر ہے (ف۸۴) یہ (ف۸۵) اس کے لئے جسے تم میں سے زنا کا اندیشہ ہے، اور صبر کرنا تمہارے لئے بہتر ہے (ف۸۶) اور اللہ بخشنے والا مہربان ہے،'),
 (93,4,26,'اللہ چاہتا ہے کہ اپنے احکام تمہارے لئے بیان کردے اور تمہیں اگلوں کی روشیں بتادے (ف۸۷) اور تم پر اپنی رحمت سے رجوع فرمائے اور اللہ علم و حکمت والا ہے،'),
 (93,4,27,'اور اللہ تم پر اپنی رحمت سے رجوع فرمانا چاہتا ہے، اور جو اپنے مزوں کے پیچھے پڑے ہیں وہ چاہتے ہیں کہ تم سیدھی راہ سے بہت الگ ہوجاؤ (ف۸۸)'),
 (93,4,28,'اللہ چاہتا ہے کہ تم پر تخفیف کرے (ف۸۹) اور آدمی کمزور بنایا گیا (ف۹۰)'),
 (93,4,29,'اے ایمان والو! آپس میں ایک دوسرے کے مال ناحق نہ کھاؤ (ف۹۱) مگر یہ کہ کوئی سودا تمہاری باہمی رضامندی کا ہو (ف۹۲) اور اپنی جانیں قتل نہ کرو (ف۹۳) بیشک اللہ تم پر مہربان ہے'),
 (93,4,30,'اور جو ظلم و زیادتی سے ایسا کرے گا تو عنقریب ہم اسے آگ میں داخل کریں گے اور یہ اللہ کو آسان ہے،'),
 (93,4,31,'اگر بچتے رہو کبیرہ گناہوں سے جن کی تمہیں ممانعت ہے (ف۹۴) تو تمہارے اور گناہ (ف۹۵) ہم بخش دیں گے اور تمہیں عزت کی جگہ داخل کریں گے،'),
 (93,4,32,'اور ا س کی آرزو نہ کرو جس سے اللہ نے تم میں ایک کو دوسرے پر بڑائی دی (ف۹۶) مردوں کے لئے ان کی کمائی سے حصہ ہے، اور عورتوں کے لئے ان کی کمائی سے حصہ (ف۹۷) اور اللہ سے اس کا فضل مانگو، بیشک اللہ سب کچھ جانتا ہے،'),
 (93,4,33,'اور ہم نے سب کے لئے مال کے مستحق بنادیے ہیں جو کچھ چھوڑ جائیں ماں باپ اور قرابت والے اور وہ جن سے تمہارا حلف بندھ چکا (ف۹۸) انہیں ان کا حصہ دو، بیشک ہر چیز اللہ کے سامنے ہے،'),
 (93,4,34,'مرد افسر ہیں عورتوں پر (ف۹۹) اس لیے کہ اللہ نے ان میں ایک کو دوسرے پر فضیلت دی(ف۱۰۰) اور اس لئے کہ مردوں نے ان پر اپنے مال خرچ کیے (ف۱۰۱) تو نیک بخت عورتیں ادب والیاں ہیں خاوند کے پیچھے حفاظت رکھتی ہیں (ف۱۰۲) جس طرح اللہ نے حفاظت کا حکم دیا اور جن عورتوں کی نافرمانی کا تمہیں اندیشہ ہو (ف۱۰۳) تو انہیں سمجھاؤ اور ان سے الگ سوؤ اور انہیں مارو پھر اگر وہ تمہارے حکم میں آجائیں تو ان پر زیادتی کی کوئی راہ نہ چاہو بیشک اللہ بلند بڑا ہے(ف۱۰۵)'),
 (93,4,35,'اور اگر تم کو میاں بی بی کے جھگڑے کا خوف ہو (ف۱۰۶) تو ایک پنچ مرد والوں کی طرف سے بھیجو اور ایک پنچ عورت والوں کی طرف سے (ف۱۰۷) یہ دونوں اگر صلح کرانا چاہیں گے تو اللہ ان میں میل کردے گا، بیشک اللہ جاننے والا خبردار ہے (ف۱۰۸)'),
 (93,4,36,'اور اللہ کی بندگی کرو اور اس کا شریک کسی کو نہ ٹھہراؤ (ف۱۰۹) اور ماں باپ سے بھلائی کرو (ف۱۱۰) اور رشتہ داروں (ف۱۱۱) اور یتیموں اور محتاجوں (ف۱۱۲) اور پاس کے ہمسائے اور دور کے ہمسائے (ف۱۱۳) اور کروٹ کے ساتھی (ف۱۱۴) اور راہ گیر (ف۱۱۵) اور اپنی باندی غلام سے (ف۱۱۶) بیشک اللہ کو خوش نہیں آتا کوئی اترانے والے بڑائی مارنے والا (ف۱۱۷)'),
 (93,4,37,'جو آپ بخل کریں اور اوروں سے بخل کے لئے کہیں (ف۱۱۸) اور اللہ نے جو انہیں اپنے فضل سے دیا ہے اسے چھپائيں (ف۱۱۹) اور کافروں کے لئے ہم نے ذلت کا عذاب تیار کر رکھا ہے،'),
 (93,4,38,'اور وہ جو اپنے مال لوگوں کے دکھاوے کو خرچ کرتے ہیں (ف۱۲۰) اور ایمان نہیں لاتے اللہ اور نہ قیامت پر، اور جس کا مصاحب شیطان ہوا، (ف۱۲۱) تو کتنا برا مصاحب ہے،'),
 (93,4,39,'اور ان کا کیا نقصان تھا اگر ایمان لاتے اللہ اور قیامت پر اور اللہ کے دیے میں سے اس کی راہ میں خرچ کرتے (ف۱۲۲) اور اللہ ان کو جانتا ہے،'),
 (93,4,40,'اللہ ایک ذرہ بھر ظلم نہیں فرماتا اور اگر کوئی نیکی ہو تو اسے دونی کرتا اور اپنے پاس سے بڑا ثواب دیتا ہے،'),
 (93,4,41,'تو کیسی ہوگی جب ہم ہر امت سے ایک گواہ لائیں (ف۱۲۳) اور اے محبوب! تمہیں ان سب پر گواہ اور نگہبان بناکر لائیں (ف۱۲۴)'),
 (93,4,42,'اس دن تمنا کریں گے وہ جنہوں نے کفر کیا اور رسول کی نافرمانی کی کاش انہیں مٹی میں دبا کر زمین برابر کردی جائے، اور کوئی بات اللہ سے نہ چھپاسکیں گے (ف۱۲۵)'),
 (93,4,43,'اے ایمان والو! نشہ کی حالت میں نماز کے پاس نہ جاؤ (ف۱۲۶) جب تک اتنا ہوش نہ ہو کہ جو کہو اسے سمجھو اور نہ ناپاکی کی حالت میں بے نہائے مگر مسافری میں (ف۱۲۷) اور اگر تم بیمار ہو (ف۱۲۸) یا سفر میں یا تم میں سے کوئی قضائے حاجت سے آیا ہو (ف۱۲۹) یا تم نے عورتو ں کو چھوا (ف۱۳۰) اور پانی نہ پایا (ف۱۳۱) تو پاک مٹی سے تیمم کرو (ف۱۳۲) تو اپنے منہ اور ہاتھوں کا مسح کرو (ف۱۳۳) بیشک اللہ معاف کرنے والا بخشنے والا ہے،'),
 (93,4,44,'کیا تم نے انہیں نہ دیکھا جن کو کتاب سے ایک حصہ ملا (ف۱۳۴) گمراہی مول لیتے ہیں (ف۱۳۵) اور چاہتے ہیں (ف۱۳۶) کہ تم بھی راہ سے بہک جاؤ،'),
 (93,4,45,'اور اللہ خوب جانتا ہے تمہارے دشمنوں کو (ف۱۳۷) اور اللہ کافی ہے والی (ف۱۳۸) اور اللہ کافی ہے مددگار،'),
 (93,4,46,'کچھ یہودی کلاموں کو ان کی جگہ سے پھیرتے ہیں (ف۱۳۹) اور (ف۱۴۰) کہتے ہیں ہم نے سنا اور نہ مانا اور (ف۱۴۱) سنیئے آپ سنائے نہ جائیں (ف۱۴۲) اور راعنا کہتے ہیں (ف۱۴۳) زبانیں پھیر کر (ف۱۴۴) اور دین میں طعنہ کے لئے (ف۱۴۵) اور اگر وہ (ف۱۴۶) کہتے کہ ہم نے سنا اور مانا اور حضور ہماری بات سنیں اور حضور ہم پر نظر فرمائیں تو ان کے لئے بھلائی اور راستی میں زیادہ ہوتا لیکن ان پر تو اللہ نے لعنت کی ان کے کفر کے سبب تو یقین نہیں رکھتے مگر تھوڑا (ف۱۴۷)'),
 (93,4,47,'اے کتاب والو! ایمان لاؤ اس پر جو ہم نے اتارا تمہارے ساتھ والی کتاب (ف۱۴۸) کی تصدیق فرماتا قبل اس کے کہ ہم بگاڑ دیں کچھ مونہوں کو (ف۱۴۹) تو انہیں پھیر دیں ان کی پیٹھ کی طرف یا انہیں لعنت کریں جیسی لعنت کی ہفتہ والوں پر (ف۱۵۰) اور خدا کا حکم ہوکر رہے،'),
 (93,4,48,'بیشک اللہ اسے نہیں بخشتا کہ اس کے ساتھ کفر کیا جائے اور کفر سے نیچے جو کچھ ہے جسے چاہے معاف فرمادیتا ہے (ف۱۵۱) اور جس نے خدا کا شریک ٹھہرایا اس نے بڑا گناہ کا طوفان باندھا،'),
 (93,4,49,'کیا تم نے انہیں نہ دیکھا جو خود اپنی ستھرائی بیان کرتے ہیں (ف۱۵۲) بلکہ اللہ جسے چاہے ستھرا کرے اور ان پر ظلم نہ ہوگا دانہ خرما کے ڈورے برابر (ف۱۵۳)'),
 (93,4,50,'دیکھو کیسا اللہ پر جھوٹ باندھا رہے ہیں (ف۱۵۴) اور یہ کافی ہے صریح گناہ،'),
 (93,4,51,'کیا تم نے، وہ نہ دیکھے جنہیں کتاب کا ایک حصہ ملا ایمان لاتے ہیں بت اور شیطان پر اور کافروں کو کہتے ہیں کہ یہ مسلمانوں سے زیادہ راہ پر ہیں،'),
 (93,4,52,'یہ ہیں جن پر اللہ نے لعنت کی اور جسے خدا لعنت کرے تو ہر گز اسکا کوئی یار نہ پائے گا (ف۱۵۵)'),
 (93,4,53,'کیا ملک میں ان کا کچھ حصہ ہے (ف۱۵۶) ایسا ہو تو لوگوں کو تِل بھر نہ دیں،'),
 (93,4,54,'یا لوگوں سے حسد کرتے ہیں (ف۱۵۷) اس پر جو اللہ نے انہیں اپنے فضل سے دیا (ف۱۵۸) تو ہم نے تو ابراہیم کی اولاد کو کتاب اور حکمت عطا فرمائی اور انہیں بڑا ملک دیا (ف۱۵۹)'),
 (93,4,55,'تو ان میں کوئی اس پر ایمان لایا (ف۱۶۰) اور کسی نے اس سے منہ پھیرا (ف۱۶۱) اور دوزخ کافی ہے بھڑکتی آگ(ف۱۶۲)'),
 (93,4,56,'جنہوں نے ہماری آیتوں کا انکار کیا عنقریب ہم ان کو آگ میں داخل کریں گے، جب کبھی ان کی کھالیں پک جائیں گی ہم ان کے سوا اور کھالیں انہیں بدل دیں گے کہ عذاب کا مزہ لیں، بیشک اللہ غالب حکمت والا ہے،'),
 (93,4,57,'اور جو لوگ ایمان لائے اور اچھے کام کیے عنقریب ہم انہیں باغوں میں لے جائیں گے جن کے نیچے نہریں رواں ان میں ہمیشہ رہیں گے، ان کے لیے وہاں ستھری بیبیاں ہیں (ف۱۶۳) اور ہم انہیں وہاں داخل کریں گے جہاں سایہ ہی سایہ ہوگا (ف۱۶۴)'),
 (93,4,58,'بیشک اللہ تمہیں حکم دیتا ہے کہ امانتیں جن کی ہیں انہیں سپرد کرو (ف۱۶۵) اور یہ کہ جب تم لوگوں میں فیصلہ کرو تو انصاف کے ساتھ فیصلہ کرو (ف۱۶۶) بیشک اللہ تمہیں کیا ہی خوب نصیحت فرماتا ہے، بیشک اللہ سنتا دیکھتا ہے،'),
 (93,4,59,'اے ایمان والو! حکم مانو اللہ کا اور حکم مانو رسول کا (ف۱۶۷) اور ان کا جو تم میں حکومت والے ہیں (ف۱۶۸) پھر اگر تم میں کسی بات کا جھگڑا اٹھے تو اسے اللہ اور رسول کے حضور رجوع کرو اگر اللہ اور قیامت پر ایمان رکھتے ہو (ف۱۶۹) یہ بہتر ہے اور اس کا انجام سب سے اچھا،'),
 (93,4,60,'کیا تم نے انہیں نہ دیکھا جن کا دعویٰ ہے کہ وہ ایمان لائے اس پر جو تمہاری طرف اترا اور اس پر جو تم سے پہلے اترا پھر چاہتے ہیں کہ شیطان کو اپنا پنچ بنائیں اور ان کو تو حکم یہ تھا کہ اسے اصلاً نہ مانیں اور ابلیس یہ چاہتا ہے کہ انہیں دور بہکاوے (ف۱۷۰)'),
 (93,4,61,'اور جب ان سے کہا جائے کہ اللہ کی اتاری ہوئی کتاب اور رسول کی طرف آؤ تو تم دیکھو گے کہ منافق تم سے منہ موڑ کر پھر جاتے ہیں،'),
 (93,4,62,'کیسی ہوگی جب ان پر کوئی افتاد پڑے (ف۱۷۱) بدلہ اسکا جو انکے ہاتھوں نے آگے بھیجا (ف۱۷۲) پھر اے محبوب! تمہارے حضور حاضر ہوں، اللہ کی قسم کھاتے کہ ہمارا مقصود تو بھلائی اور میل ہی تھا(ف۱۷۳)'),
 (93,4,63,'ان کے دلوں کی تو بات اللہ جانتا ہے تو تم ان سے چشم پوشی کرو اور انہیں سمجھا دو اور ان کے معاملہ میں ان سے رسا بات کہو (ف۱۷۴)'),
 (93,4,64,'اور ہم نے کوئی رسول نہ بھیجا مگر اس لئے کہ اللہ کے حکم سے اس کی اطاعت کی جائے (ف۱۷۵) اور اگر جب وہ اپنی جانوں پر ظلم کریں (ف۱۷۶) تو اے محبوب! تمہارے حضور حاضر ہوں اور پھر اللہ سے معافی چاہیں اور رسول ان کی شفاعت فرمائے تو ضرور اللہ کو بہت توبہ قبول کرنے والا مہربان پائیں(ف۱۷۷)'),
 (93,4,65,'تو اے محبوب! تمہارے رب کی قسم وہ مسلمان نہ ہوں گے جب تک اپنے آپس کے جھگڑے میں تمہیں حاکم نہ بنائئیں پھر جو کچھ تم حکم فرما دو اپنے دلوں میں اس سے رکاوٹ نہ پائیں اور جی سے مان لیں (ف۱۷۸)'),
 (93,4,66,'اور اگر ہم ان پر فرض کرتے کہ اپنے آپ کو قتل کردو یا اپنے گھر بار چھوڑ کر نکل جاؤ (ف۱۷۹) تو ان میں تھوڑے ہی ایسا کرتے، اور اگر وہ کرتے جس بات کی انہیں نصیحت دی جاتی ہے (ف۱۸۰) تو اس میں ان کا بھلا تھا اور ایمان پر خوب جمنا'),
 (93,4,67,'اور ایسا ہوتا تو ضرور ہم انہیں اپنے پاس سے بڑا ثواب دیتے'),
 (93,4,68,'اور ضرور ان کو سیدھی راہ کی ہدایت کرتے،'),
 (93,4,69,'اور جو اللہ اور اس کے رسول کا حکم مانے تو اُسے ان کا ساتھ ملے گا جن پر اللہ نے فضل کیا یعنی انبیاء (ف۱۸۱) اور صدیق (ف۱۸۲) اور شہید (ف۱۸۳) اور نیک لوگ (ف۱۸۴) یہ کیا ہی اچھے ساتھی ہیں،'),
 (93,4,70,'یہ اللہ کا فضل ہے، اور اللہ کافی ہے جاننے والا،'),
 (93,4,71,'اے ایمان والو! ہوشیاری سے کام لو (ف۱۸۵) پھر دشمن کی طرف تھوڑے تھوڑے ہوکر نکلو یا اکٹھے چلو'),
 (93,4,72,'اور تم میں کوئی وہ ہے کہ ضرور دیر لگائے گا (ف۱۸۶) پھر اگر تم پر کوئی افتاد پڑے تو کہے خدا کا مجھ پر احسان تھا کہ میں ان کے ساتھ حاضر نہ تھا،'),
 (93,4,73,'اور اگر تمہیں اللہ کا فضل ملے (ف۱۸۷) تو ضرو ر کہے گویا تم اس میں کوئی دوستی نہ تھی اے کاش میں ان کے ساتھ ہوتا تو بڑی مراد پاتا،'),
 (93,4,74,'تو انہیں اللہ کی راہ میں لڑنا چاہئے جو دنیا کی زندگی بیچ کر آخرت لیتے ہیں اور جو اللہ کی راہ میں لڑے پھر مارا جائے یا غالب آئے تو عنقریب ہم اسے بڑا ثواب دیں گے،'),
 (93,4,75,'اور تمہیں کیا ہوا کہ نہ لڑو اللہ کی راہ میں (ف۱۸۹) اور کمزور مردوں اور عورتوں اور بچوں کے واسطے یہ دعا کررہے ہیں کہ اے ہمارے رب ہمیں اس بستی سے نکال جس کے لوگ ظالم ہیں اور ہمیں اپنے پاس سے کوئی حمایتی دے دے اور ہمیں اپنے پاس سے کوئی مددگار دے دے،'),
 (93,4,76,'ایمان والے اللہ کی راہ میں لڑتے ہیں (ف۱۹۰) اور کفار شیطان کی راہ میں لڑتے ہیں تو شیطان کے دوستوں سے (ف۱۹۱) لڑو بیشک شیطان کا داؤ کمزور ہے (ف۱۹۲)'),
 (93,4,77,'کیا تم نے انہیں نہ دیکھا جن سے کہا گیا اپنے ہاتھ روک لو (ف۱۹۳) اور نماز قائم رکھو اور زکوٰة دو پھر جب ان پر جہاد فرض کیا گیا (ف۱۹۴) تو ان میں بعضے لوگوں سے ایسا ڈرنے لگے جیسے اللہ سے ڈرے یا اس سے بھی زائد (ف۱۹۵) اور بولے اے رب ہمارے! تو نے ہم پر جہاد کیوں فرض کردیا (ف۱۹۶) تھوڑی مدت تک ہمیں اور جینے دیا ہوتا، تم فرما دو کہ دنیا کا برتنا تھوڑا ہے (ف۱۹۷) اور ڈر والوں کے لئے آخرت اچھی اور تم پر تاگے برابر ظلم نہ ہوگا (ف۱۹۸)'),
 (93,4,78,'تم جہاں کہیں ہو موت تمہیں آلے گی (ف۱۹۹) اگرچہ مضبوط قلعوں میں ہو اور اُنہیں کوئی بھلائی پہنچے (ف۲۰۰) تو کہیں یہ اللہ کی طرف سے ہے اور انہیں کوئی برائی پہنچے (ف۲۰۱) تو کہیں یہ حضور کی طرف آئی (ف۲۰۲) تم فرمادو سب اللہ کی طرف سے ہے (ف۲۰۳) تو ان لوگوں کو کیا ہوا کوئی بات سمجھتے معلوم ہی نہیں ہوتے،'),
 (93,4,79,'اے سننے والے تجھے جو بھلائی پہنچے وہ اللہ کی طرف سے ہے (ف۲۰۴) اور جو برائی پہنچے وہ تیری اپنی طرف سے ہے (ف۲۰۵) اور اے محبوب ہم نے تمہیں سب لوگوں کے لئے رسول بھیجا (ف۲۰۶) اور اللہ کافی ہے گواہ (ف۲۰۷)'),
 (93,4,80,'جس نے رسول کا حکم مانا بیشک اس نے اللہ کا حکم مانا (ف۲۰۸) اور جس نے منہ پھیرا (ف۲۰۹) تو ہم نے تمہیں ان کے بچانے کو نہ بھیجا'),
 (93,4,81,'اور کہتے ہیں ہم نے حکم مانا (ف۲۱۰) پھر جب تمہارے پاس سے نکل کر جاتے ہیں تو ان میں ایک گروہ جو کہہ گیا تھا اس کے خلاف رات کو منصوبے گانٹھتا ہے اور اللہ لکھ رکھتا ہے ان کے رات کے منصوبے (ف۲۱۱) تو اے محبوب تم ان سے چشم پوشی کرو اور اللہ پر بھروسہ رکھو اور اللہ کافی ہے کام بنانے کو،'),
 (93,4,82,'تو کیا غور نہیں کرتے قرآن میں (ف۲۱۲) اور اگر وہ غیر خدا کے پاس سے ہوتا تو ضرور اس میں بہت اختلاف پاتے (ف۲۱۳)'),
 (93,4,83,'اور جب ان کے پاس کوئی بات اطمینان (ف۲۱۴) یا ڈر (ف۲۱۵) کی آتی ہے اس کا چرچا کر بیٹھتے ہیں (ف۲۱۶) اور اگر اس میں رسول اور اپنے ذی اختیار لوگوں (ف۲۱۷) کی طرف رجوع لاتے (ف۲۱۸) تو ضرور اُن سے اُ س کی حقیقت جان لیتے یہ جو بعد میں کاوش کرتے ہیں (ف۲۱۹) اور اگر تم پر اللہ کا فضل (ف۲۲۰) اور اس کی رحمت (ف۲۲۱) نہ ہوتی تو ضرور تم شیطان کے پیچھے لگ جاتے (ف۲۲۲) مگر تھوڑے (ف۲۲۳)'),
 (93,4,84,'تو اے محبوب اللہ کی راہ میں لڑو (ف۲۲۴) تم تکلیف نہ دیئے جاؤ گے مگر اپنے دم کی (ف۲۲۵) اور مسلمانوں کو آمادہ کرو (ف۲۲۶) قریب ہے کہ اللہ کافروں کی سختی روک دے (ف۲۲۷) اور اللہ کی آنچ (جنگی طاقت) سب سے سخت تر ہے اور اس کا عذاب سب سے کڑا (زبردست)'),
 (93,4,85,'جو اچھی سفارش کرے (ف۲۲۸) اس کے لئے اس میں سے حصہ ہے (ف۲۲۹) اور جو بری سفارش کرے اس کے لئے اس میں سے حصہ ہے (ف۲۳۰) اور اللہ ہر چیز پر قادر ہے،'),
 (93,4,86,'اور جب تمہیں کوئی کسی لفظ سے سلام کرے تو اس سے بہتر لفظ جواب میں کہو یا یا وہی کہہ دو، بیشک اللہ ہر چیز پر حساب لینے والا ہے (ف۲۳۱)'),
 (93,4,87,'ا لله کہ اس کے سوا کسی کی بندگی نہیں اور وہ ضرور تمہیں اکٹھا کرے گا قیامت کے دن جس میں کچھ شک نہیں اور اللہ سے زیادہ کس کی بات سچی (ف۲۳۲)'),
 (93,4,88,'تو تمہیں کیا ہوا کہ منافقوں کے بارے میں دو فریق ہوگئے (ف۲۳۳) اور اللہ نے انہیں اوندھا کردیا (ف۲۳۴) ان کے کوتکوں (کرتوتوں) کے سبب (ف۲۳۵) کیا یہ چاہتے ہیں کہ اسے راہ دکھاؤ جسے اللہ نے گمراہ کیا اور جسے اللہ گمراہ کرے تو ہرگز اس کے لئے راہ نہ پائے گا،'),
 (93,4,89,'وہ تو یہ چاہتے ہیں کہ کہیں تم بھی کافر ہوجاؤ جیسے وہ کافر ہوئے تو تم سب ایک سے ہو جاؤ ان میں کسی کو اپنا دوست نہ بناؤ (ف۲۳۶) جب تک اللہ کی راہ میں گھر بار نہ چھوڑیں (ف۲۳۷) پھر اگر وہ منہ پھیریں (ف۲۳۸) تو انہیں پکڑو اور جہاں پاؤ قتل کرو، اور ان میں کسی کو نہ دوست ٹھہراؤ نہ مددگار (ف۲۳۹)'),
 (93,4,90,'مگر جو ایسی قوم سے علاقے رکھتے ہیں کہ تم میں ان میں معاہدہ ہے (ف۲۴۰) یا تمہارے پاس یوں آئے کہ ان کے دلوں میں سکت نہ رہی کہ تم سے لڑیں (ف۲۴۱) یا اپنی قوم سے لڑیں (ف۲۴۲) اور اللہ چاہتا تو ضرور انہیں تم پر قابو دیتا تو وہ بے شک تم سے لڑتے (ف۲۴۳) پھر اگر وہ تم سے کنارہ کریں اور نہ لڑیں اور صلح کا پیام ڈالیں تو اللہ نے تمہیں ان پر کوئی راہ نہ رکھی (ف۲۴۴)'),
 (93,4,91,'اب کچھ اور تم ایسے پاؤ گے جو یہ چاہتے ہیں کہ تم سے بھی امان میں رہیں اور اپنی قوم سے بھی امان میں رہیں (ف۲۴۵) جب کبھی انکی قوم انہیں فساد (ف۲۴۶) کی طرف پھیرے تو اس پر اوندھے گرتے ہیں پھر اگر وہ تم سے کنارہ نہ کریں اور (ف۲۴۷) صلح کی گردن نہ ڈالیں اور اپنے ہاتھ سے نہ روکیں تو انہیں پکڑو اور جہاں پاؤ قتل کرو، اور یہ ہیں جن پر ہم نے تمہیں صریح اختیار دیا(ف۲۴۸)'),
 (93,4,92,'اور مسلمانوں کو نہیں پہنچتا کہ مسلمان کا خون کرے مگر ہاتھ بہک کر (ف۲۴۹) اور جو کسی مسلمان کو نادانستہ قتل کرے تو اس پر ایک مملوک مسلمان کا آزاد کرنا ہے اور خون بہا کر مقتول کے لوگوں کو سپرد کی جائے (ف۲۵۰) مگر یہ کہ وہ معاف کردیں پھر اگر وہ (ف۲۵۱) اس قوم سے ہو جو تمہاری دشمن ہے (ف۲۵۲) اور خود مسلمان ہے تو صرف ایک مملوک مسلمان کا آزاد کرنا (ف۲۵۳) اور اگر وہ اس قوم میں ہو کہ تم میں ان میں معاہدہ ہے تو اس کے لوگوں کو خوں بہا سپرد کیا جائے اور ایک مسلمان مملوک آزاد کرنا (ف۲۵۴) تو جس کا ہاتھ نہ پہنچے (ف۲۵۵) وہ لگاتار دو مہینے کے روزے (ف۲۵۶) یہ اللہ کے یہاں اس کی توبہ ہے اور اللہ جاننے والا حکمت والا ہے،'),
 (93,4,93,'اور جو کوئی مسلمان کو جان بوجھ کر قتل کرے تو اس کا بدلہ جہنم ہے کہ مدتوں اس میں رہے (ف۲۵۷) اور اللہ نے اس پر غضب کیا اور اس پر لعنت کی اور اس کے لئے تیار رکھا بڑا عذاب،'),
 (93,4,94,'اے ایمان والو! جب تم جہاد کو چلو تو تحقیق کرلو اور جو تمہیں سلام کرے اس سے یہ نہ کہو کہ تو مسلمان نہیں (ف۲۵۷) تم جیتی دنیا کا اسباب چاہتے ہو تو اللہ کے پاس بہتری غنیمتیں ہیں پہلے تم بھی ایسے ہی تھے (ف۲۵۹) پھر اللہ نے تم پر احسان کیا (ف۲۶۰) تو تم پر تحقیق کرنا لازم ہے (ف۲۶۱) بیشک اللہ کو تمہارے کاموں کی خبر ہے،'),
 (93,4,95,'برابر نہیں وہ مسلمان کہ بے عذر جہاد سے بیٹھ رہیں اور وہ کہ راہ خدا میں اپنے مالوں اور جانوں سے جہاد کرتے ہیں (ف۲۶۲) اللہ نے اپنے مالوں اور جانوں کے ساتھ جہاد کرنے والوں کا درجہ بیٹھنے والوں سے بڑا کیا (ف۲۶۳) اور اللہ نے سب سےبھلائی کا وعدہ فرمایا (ف۲۶۴) اور اللہ نے جہاد والوں کو (ف۲۶۵) بیٹھنے والوں پر بڑے ثواب سے فضیلت دی ہے،'),
 (93,4,96,'اُس کی طرف سے درجے اور بخشش اور رحمت (ف۲۶۶) اور اللہ بخشنے والا مہربان ہے،'),
 (93,4,97,'وہ لوگ جنکی جان فرشتے نکالتے ہیں اس حال میں کہ وہ اپنے اوپر ظلم کرتے تھے انسے فرشتے کہتے ہیں تم کاہے میں تھے کہتے ہیں کہ ہم زمین میں کمزور تھے (ف۲۶۷) کہتے ہیں کیا اللہ کی زمین کشادہ نہ تھی کہ تم اسمیں ہجرت کرتے، تو ایسوں کا ٹھکانا جہنم ہے، اور بہت بری جگہ پلٹنے کی(ف۲۶۸)'),
 (93,4,98,'مگر وہ جو دبالیے گئے مرد اور عورتیں اور بچے جنہیں نہ کوئی تدبیر بن پڑے (ف۲۶۹) نہ راستہ جانیں،'),
 (93,4,99,'تو قریب ہے اللہ ایسوں کو معاف فرمائے (ف۲۷۰) اور اللہ معاف فرمانے والا بخشنے والا ہے،'),
 (93,4,100,'اور جو اللہ کی راہ میں گھر بار چھوڑ کر نکلے گا وہ زمین میں بہت جگہ اور گنجائش پائے گا، اور جو اپنے گھر سے نکلا (ف۲۷۱) اللہ و رسول کی طرف ہجرت کرتا پھر اسے موت نے آلیا تو اس کا ثواب اللہ کے ذمہ پر ہوگیا (ف۲۷۲) اور اللہ بخشنے والا مہربان ہے'),
 (93,4,101,'اور جب تم زمین میں سفر کرو تو تم پر گناہ نہیں کہ بعض نمازیں قصر سے پڑھو (ف۲۷۳) اگر تمہیں اندیشہ ہو کہ کافر تمہیں ایذا دیں گے (ف۲۷۴) بیشک کفار تمہارے کھلے دشمن ہیں،'),
 (93,4,102,'اور اے محبوب! جب تم ان میں تشریف فرما ہو (ف۲۷۵) پھر نماز میں ان کی امامت کرو (ف۲۷۶) تو چاہئے کہ ان میں ایک جماعت تمہارے ساتھ ہو (ف۲۷۷) اور وہ اپنے ہتھیار لیے رہیں (ف۲۷۸) پھر جب وہ سجدہ کرلیں (ف۲۷۹) تو ہٹ کر تم سے پیچھے ہوجائیں (ف۲۸۰) اور اب دوسری جماعت آئے جو اس وقت تک نماز میں شریک نہ تھی (ف۲۸۱) اب وہ تمہارے مقتدی ہوں اور چاہئے کہ اپنی پناہ اور اپنے ہتھیار لیے رہیں (ف۲۸۲) کافروں کی تمنا ہے کہ کہیں تم اپنے ہتھیاروں اور اپنے اسباب سے غافل ہو جاؤ تو ایک دفعہ تم پر جھک پڑیں (ف۲۸۳) اور تم پر مضائقہ نہیں اگر تمہیں مینھ کے سبب تکلیف ہو یا بیمار ہو کہ اپنے ہتھیار کھول رکھو اور اپنی پناہ لیے رہو (ف۲۸۴) بیشک اللہ نے کافروں کے لئے خواری کا عذاب تیار کر رکھا ہے،'),
 (93,4,103,'پھر جب تم نماز پڑھ چکو تو اللہ کی یاد کرو کھڑے اور بیٹھے اور کروٹوں پر لیٹے (ف۲۸۵) پھر جب مطمئن ہو جاؤ تو حسب دستور نماز قائم کرو بیشک نماز مسلمانوں پر وقت باندھا ہوا فرض ہے(ف۲۸۶)'),
 (93,4,104,'اور کافروں کی تلاش میں سستی نہ کرو اگر تمہیں دکھ پہنچتا ہے تو انہیں بھی دکھ پہنچتا ہے جیسا تمہیں پہنچتا ہے، اورتم اللہ سے وہ امید رکھتےہو جو وہ نہیں رکھتے، ور اللہ جاننے والا حکمت والا ہے (ف۲۸۷)'),
 (93,4,105,'اے محبوب! بیشک ہم نے تمہاری طرف سچی کتاب اتاری کہ تم لوگوں میں فیصلہ کرو (ف۲۸۸) جس طرح تمہیں اللہ دکھائے (ف۲۸۹) اور دغا والوں کی طرف سے نہ جھگڑو'),
 (93,4,106,'اور اللہ سے معافی چاہو بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,4,107,'اور ان کی طرف سے نہ جھگڑو جو اپنی جانوں کو خیانت میں ڈالتے ہیں (ف۲۹۰) بیشک اللہ نہیں چاہتا کسی بڑے دغا باز گنہگار کو'),
 (93,4,108,'آدمیوں سے چھپتے ہیں اور اللہ نہیں چھپتے(ف۲۹۱) اور ا لله ان کے پاس ہے (ف۲۹۲) جب دل میں وہ بات تجویز کرتے ہیں جو اللہ کو ناپسند ہے (ف۲۹۳) اور اللہ ان کے کاموں کو گھیرے ہوئے ہے،'),
 (93,4,109,'سنتے ہو یہ جو تم ہو (ف۲۹۴) دنیا کی زندگی میں تو ان کی طرف سے جھگڑے تو ان کی طرف سے کون جھگڑے گا اللہ سے قیامت کے دن یا کون ان کا وکیل ہوگا،'),
 (93,4,110,'اور جو کوئی برائی یا اپنی جان پر ظلم کرے پھر اللہ سے بخشش چاہے تو اللہ کو بخشنے والا مہربان پائے گا،'),
 (93,4,111,'اور جو گناہ کمائے تو ا س کی کمائی اسی کی جان پر پڑے اور اللہ علم و حکمت والا ہے (ف۲۹۵)'),
 (93,4,112,'اور جو کوئی خطا یا گناہ کمائے (ف۲۹۶) پھر اسے کسی بے گناہ پر تھوپ دے اس نے ضرور بہتان اور کھلا گناہ اٹھایا،'),
 (93,4,113,'اور اے محبوب! اگر اللہ کا فضل و رحمت تم پر نہ ہوتا (ف۲۹۷) تو ان میں کے کچھ لوگ یہ چاہتے کہ تمہیں دھوکا دے دیں اور وہ اپنے ہی آپ کو بہکا رہے ہیں (ف۲۹۸) اور تمہارا کچھ نہ بگاڑیں گے (ف۲۹۹) اور اللہ نے تم پر کتاب (ف۳۰۰) اور حکمت اتاری اور تمہیں سکھا دیا جو کچھ تم نہ جانتے تھے (ف۳۰۱) اور اللہ کا تم پر بڑا فضل ہے (ف۳۰۲)'),
 (93,4,114,'ان کے اکثر مشوروں میں کچھ بھلائی نہیں (ف۳۰۳) مگر جو حکم دے خیرات یا اچھی بات یا لوگوں میں صلح کرنے کا اور جو اللہ کی رضا چاہنے کو ایسا کرے اسے عنقریب ہم بڑا ثواب دیں گے،'),
 (93,4,115,'اور جو رسول کا خلاف کرے بعد اس کے کہ حق راستہ اس پر کھل چکا اور مسلمانوں کی راہ سے جدا راہ چلے ہم اُسے اُس کے حال پر چھوڑ دیں گے اور اسے دوزخ میں داخل کریں گے اور کیا ہی بری جگہ پلٹنے کی (ف۳۰۴)'),
 (93,4,116,'اللہ اسے نہیں بخشتا کہ اس کا کوئی شریک ٹھہرایا جائے اور اس سے نیچے جو کچھ ہے جسے چاہے معاف فرما دیتا ہے (ف۳۰۵) اور جو اللہ کا شریک ٹھہرائے وہ دور کی گمراہی میں پڑا،'),
 (93,4,117,'یہ شرک والے اللہ سوا نہیں پوجتے مگر کچھ عورتوں کو (ف۳۰۶) اور نہیں پوجتے مگر سرکش شیطان کو(ف۳۰۷)'),
 (93,4,118,'جس پر اللہ نے لعنت کی اور بولا (ف۳۰۸) قسم ہے میں ضرور تیرے بندوں میں سے کچھ ٹھہرایا ہوا حصہ لوں گا (ف۳۰۹)'),
 (93,4,119,'قسم ہے میں ضرور بہکادوں گا اور ضرور انہیں آرزوئیں دلاؤں گا (ف۳۱۰) اور ضرور انہیں کہوں گا کہ وہ چوپایوں کے کان چیریں گے (ف۳۱۱) اور ضرور انہیں کہوں گا کہ وہ اللہ کی پیدا کی ہوئی چیزیں بدل دیں گے، اور جو اللہ کو چھوڑ کر شیطان کو دوست بنائے وہ صریح ٹوٹے میں پڑا'),
 (93,4,120,'شیطان انہیں وعدے دیتا ہے اور آرزوئیں دلاتا ہے (ف۳۱۳) اور شیطان انہیں وعدے نہیں دیتا مگر فریب کے (ف۳۱۴)'),
 (93,4,121,'اُن کا ٹھکانا دوزخ ہے اس سے بچنے کی جگہ نہ پائیں گے،'),
 (93,4,122,'اور جو ایمان لائے اور اچھے کام کیے کچھ دیر جاتی ہے کہ ہم انہیں باغوں میں لے جائیں گے جن کے نیچے نہریں بہیں ہمیشہ ہمیشہ ان میں رہیں اللہ کا سچا وعدہ اور اللہ سے زیادہ کس کی بات سچی،'),
 (93,4,123,'کام نہ کچھ تمہارے خیالوں پر ہے (ف۳۱۵) اور نہ کتاب والوں کی ہوس پر (ف۳۱۶) جو برائی کرے گا (ف۳۱۷) اس کا بدلہ پائے گا اور اللہ کے سوا نہ کوئی اپنا حمایتی پائے گا نہ مددگار (ف۳۱۸)'),
 (93,4,124,'اور جو کچھ بھلے کام کرے گا مرد ہو یا عورت اور ہو مسلمان (ف۳۱۹) تو وہ جنت میں داخل کیے جائیں گے اور انہیں تِل بھر نقصان نہ دیا جائے گا'),
 (93,4,125,'اور اس سے بہتر کس کا دین جس نے اپنا منہ اللہ کے لئے جھکا دیا (ف۳۲۰) اور وہ نیکی والا ہے اور ابراہیم کے دین پر (ف۳۲۱) جو ہر باطل سے جدا تھا اور اللہ نے ابراہیم کو اپنا گہرا دوست بنایا (ف۳۲۲)'),
 (93,4,126,'اور اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں، اور ہر چیز پر اللہ کا قابو ہے (ف۳۲۳)'),
 (93,4,127,'اور تم سے عورتوں کے بارے میں فتویٰ پوچھتے ہیں (ف۳۲۴) تم فرمادو کہ اللہ تمہیں ان کا فتویٰ دیتا ہے اور وہ جو تم پر قرآن میں پڑھا جاتا ہے ان یتیم لڑکیوں کے بارے میں تم انہیں نہیں دیتے جو ان کا مقرر ہے (ف۳۲۵) اور انہیں نکاح میں بھی لانے سے منہ پھیرتے ہو اور کمزور (ف۳۲۶) بچوں کے بارے میں اور یہ کہ یتیموں کے حق میں انصاف پر قائم رہو (ف۳۲۷) اور تم جو بھلائی کرو تو اللہ کو اس کی خبر ہے،'),
 (93,4,128,'اور اگر کوئی عورت اپنے شوہر کی زیادتی یا بے رغبتی کا اندیشہ کرے (ف۳۲۸) تو ان پر گناہ نہیں کہ آپس میں صلح کرلیں (ف۳۲۹) اور صلح خوب ہے (ف۳۳۰) اور دل لالچ کے پھندے میں ہیں (ف۳۳۱) اور اگر تم نیکی اور پرہیزگاری کرو (ف۳۳۲) تو اللہ کو تمہارے کاموں کی خبر ہے(ف۳۳۳)'),
 (93,4,129,'اور تم سے ہرگز نہ ہوسکے گا کہ عورتوں کو برابر رکھو اور چاہے کتنی ہی حرص کرو (ف۳۳۴) تو یہ تو نہ ہو کہ ایک طرف پورا جھک جاؤ کہ دوسری کو ادھر میں لٹکتی چھوڑ دو (ف۳۳۵) اور اگر تم نیکی اور پرہیزگاری کرو تو بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,4,130,'اور اگر وہ دونوں (ف۳۳۶) جدا ہوجائیں تو اللہ اپنی کشائش سے تم میں ہر ایک کو دوسرے سے بے نیاز کردے گا (ف۳۳۷) اور اللہ کشائش والا حکمت والا ہے،'),
 (93,4,131,'اور اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں، اور بیشک تاکید فرمادی ہے ہم نے ان سے جو تم سے پہلے کتاب دیئے گئے اور تم کو کہ اللہ سے ڈرتے رہو (ف۳۳۸) اور اگر کفر کرو تو بیشک اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں (ف۳۳۹) اور اللہ بے نیاز ہے (ف۳۴۰) سب خوبیوں سراہا،'),
 (93,4,132,'اور اللہ کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں، اور اللہ کافی ہے کارساز،'),
 (93,4,133,'اے لوگوں وہ چاہے تو تمہیں لے جائے (ف۳۴۱) اور اوروں کو لے آئے اور اللہ کو اس کی قدرت ہے،'),
 (93,4,134,'جو دنیا کا انعام چاہے تو اللہ ہی کے پاس دنیا و آخرت دونوں کا انعام ہے (ف۳۴۲) اور اللہ ہی سنتا دیکھتا ہے،'),
 (93,4,135,'اے ایمان والو! انصاف پر خوب قائم ہوجاؤ اللہ کے لئے گواہی دیتے چاہے اس میں تمہارا اپنا نقصان ہو یا ماں باپ کا یا رشتہ داروں کا جس پر گواہی دو وہ غنی ہو یا فقیر ہو (ف۳۴۳) بہرحال اللہ کو اس کا سب سے زیادہ اختیار ہے تو خواہش کے پیچھے نہ جاؤ کہ حق سے الگ پڑو اگر تم ہیر پھیر کرو (ف۳۴۴) یا منہ پھیرو (ف۳۴۵) تو اللہ کو تمہارے کاموں کی خبر ہے (ف۳۴۶)'),
 (93,4,136,'اے ایمان والو ایمان رکھو اللہ اور اللہ کے رسول پر (ف۳۴۷) اور اس کتاب پر جو اپنے ان رسول پر اتاری اور اس کتاب پر جو پہلے اتاردی (ف۳۴۸) اور جو نہ مانے اللہ اور اس کے فرشتوں اور کتابوں اور رسولوں اور قیامت کو (ف۳۴۹) تو وہ ضرور دور کی گمراہی میں پڑا،'),
 (93,4,137,'بیشک وہ لوگ جو ایمان لائے پھر کافر ہوئے پھر ایمان لائے پھر کافر ہوئے پھر اور کفر میں بڑھے (ف۳۵۰) اللہ ہرگز نہ انہیں بخشے (ف۳۵۱) نہ انہیں راہ دکھائے،'),
 (93,4,138,'خوشخبری دو منافقوں کو کہ ان کے لئے دردناک عذاب ہے'),
 (93,4,139,'وہ جو مسلمانوں کو چھوڑ کر کافروں کو دوست بناتے ہیں (ف۳۵۲) کیا ان کے پاس عزت ڈھونڈتے ہیں تو عزت تو ساری اللہ کے لیے ہے(ف۳۵۳)'),
 (93,4,140,'اور بیشک اللہ تم پر کتاب (ف۳۵۴) میں اتار چکا کہ جب تم اللہ کی آیتوں کو سنو کہ ان کا انکار کیا جاتا اور ان کی ہنسی بنائی جاتی ہے تو ان لوگوں کے ساتھ نہ بیٹھو جب تک وہ اور بات میں مشغول نہ ہوں (ف۳۵۵) ورنہ تم بھی انہیں جیسے ہو (ف۳۵۶) بیشک اللہ منافقوں اور کافروں سب کو جہنم میں اکٹھا کرے گا'),
 (93,4,141,'وہ جو تمہاری حالت تکا کرتے ہیں تو اگر اللہ کی طرف سے تم کو فتح ملے کہیں کیا ہم تمہارے ساتھ نہ تھے (ف۳۵۷) اور اگر کافروں کا حصہ ہو تو ان سے کہیں کیا ہمیں تم پر قابو نہ تھا (ف۳۵۸) اور ہم نے تمہیں مسلمانوں سے بچایا (ف۳۵۹) تو اللہ تم سب میں (ف۳۶۰) قیامت کے دن فیصلہ کردے گا (ف۳۶۱) اور اللہ کافروں کو مسلمان پر کوئی راہ نہ دے گا (ف۳۶۲)'),
 (93,4,142,'بیشک منافق لوگ اپنے گمان میں اللہ کو فریب دیا چاہتے ہیں (ف۳۶۳) اور وہی انہیں غافل کرکے مارے گا اور جب نماز کو کھڑے ہوں (ف۳۶۴) تو ہارے جی سے (ف۳۶۵) لوگوں کو دکھاوا کرتے ہیں اور اللہ کو یاد نہیں کرتے مگر تھوڑا (ف۳۶۶)'),
 (93,4,143,'بیچ میں ڈگمگا رہے ہیں (ف۳۶۷) نہ اِدھر کے نہ اُدھر کے (ف۳۶۸) اور جسے اللہ گمراہ کرے تو اس کے لئے کوئی راہ نہ پائے گا،'),
 (93,4,144,'اے ایمان والو! کافروں کو دوست نہ بناؤ مسلمانوں کے سوا (ف۳۶۹) کیا یہ چاہتے ہو کہ اپنے اوپر اللہ کے لئے صریح حجت کرلو (ف۳۷۰)'),
 (93,4,145,'بیشک منافق دوزخ کے سب سے نیچے طبقہ میں ہیں (ف۳۷۱) اور تو ہرگز ان کا کوئی مددگار نہ پائے گا'),
 (93,4,146,'مگر وہ جنہوں نے توبہ کی (ف۳۷۲) اور سنورے اور اللہ کی رسی مضبوط تھامی اور اپنا دین خالص اللہ کے لئے کرلیا تو یہ مسلمانوں کے ساتھ ہیں (ف۳۷۳) اور عنقریب اللہ مسلمانوں کو بڑا ثواب دے گا،'),
 (93,4,147,'اور اللہ تمہیں عذاب دے کر کیا کرے گا اگر تم حق مانو، اور ایمان لاؤ اور اللہ ہے صلہ دینے والا جاننے والا،'),
 (93,4,148,'اللہ پسند نہیں کرتا بری بات کا اعلان کرنا (ف۳۷۴) مگر مظلوم سے (ف۳۷۵) اور اللہ سنتا جانتا ہے،'),
 (93,4,149,'اگر تم کوئی بھلائی اعلانیہ کرو یا چھپ کر یا کسی کی برائی سے درگزرو تو بیشک اللہ معاف کرنے والا قدرت والا ہے (ف۳۷۶)'),
 (93,4,150,'وہ جو اللہ اور اس کے رسولوں کو نہیں مانتے اور چاہتے ہیں کہ اللہ سے اس کے رسولوں کو جدا کردیں (ف۳۷۷) اور کہتے ہیں ہم کسی پر ایمان لائے اور کسی کے منکر ہوئے (ف۳۷۸) اور چاہتے ہیں کہ ایمان و کفر کے بیچ میں کوئی راہ نکال لیں'),
 (93,4,151,'یہی ہیں ٹھیک ٹھیک کافر (ف۳۷۹) اور ہم نے کافروں کے لئے ذلت کا عذاب تیار کر رکھا ہے،'),
 (93,4,152,'اور وہ جو اللہ اور اس کے سب رسولوں پر ایمان لائے اور ان میں سے کسی پر ایمان میں فرق نہ کیا انہیں عنقریب اللہ ان کے ثواب دے گا (ف۳۸۰) اور اللہ بخشنے والا مہربان ہے (ف۳۸۱)'),
 (93,4,153,'اے محبوب! اہل کتاب (ف۳۸۲) تم سے سوال کرتے ہیں کہ ان پر آسمان سے ایک کتاب اتاردو (ف۳۸۳) تو وہ تو موسیٰ سے اس سے بھی بڑا سوال کرچکے (ف۳۸۴) کہ بولے ہمیں ا لله کو اعلانیہ دکھادو تو انہیں کڑک نے آ لیا ان کے گناہوں پر پھر بچھڑا لے بیٹھے (ف۳۸۵) بعداس کے لئے روشن آیتیں (ف۳۸۶) ان کے پاس آچکیں تو ہم نے یہ معاف فرمادیا (ف۳۸۷) اور ہم نے موسیٰ کو روشن غلبہ دیا (ف۳۸۸)'),
 (93,4,154,'پھر ہم نے ان پر طور کو اونچا کیا ان سے عہد لینے کو اور ان سے فرمایا کہ دروازے میں سجدہ کرتے داخل ہو اور ان سے فرمایا کہ ہفتہ میں حد سے نہ بڑھو (ف۳۸۹) اور ہم نے ان سے گاڑھا عہد لیا(ف۳۹۰)'),
 (93,4,155,'تو ان کی کیسی بدعہدیوں کے سبب ہم نے ان پر لعنت کی اور اس لئے کہ وہ آیات الٰہی کے منکر ہوئے (ف۳۹۱) اور انبیاء کو ناحق شہید کرتے (ف۳۹۲) اور ان کے اس کہنے پر کہ ہمارے دلوں پر غلاف ہیں (ف۳۹۳) بلکہ اللہ نے ان کے کفر کے سبب ان کے دلوں پر مہر لگادی ہے تو ایمان نہیں لاتے مگر تھوڑے،'),
 (93,4,156,'اور اس لئے کہ انہوں نے کفر کیا (ف۳۹۴) اور مریم پر بڑا بہتان اٹھایا،'),
 (93,4,157,'اور ان کے اس کہنے پر کہ ہم نے مسیح عیسیٰ بن مریم اللہ کے رسول کو شہید کیا (ف۳۹۵) اور ہے یہ کہ انہوں نے نہ اسے قتل کیا اور نہ اسے سولی دی بلکہ ان کے لئے ان کی شبیہ کا ایک بنادیا گیا (ف۳۹۶) اور وہ جو اس کے بارہ میں اختلاف کررہے ہیں ضرور اس کی طرف سے شبہ میں پڑے ہوئے ہیں (ف۳۹۷) انہیں اس کی کچھ بھی خبر نہیں (ف۳۹۸) مگر یہی گمان کی پیروی (ف۳۹۹) اور بیشک انہوں نے اس کو قتل نہیں کیا (ف۴۰۰)'),
 (93,4,158,'بلکہ اللہ نے اسے اپنی طرف اٹھالیا (ف۴۰۱) اور اللہ غالب حکمت والا ہے،'),
 (93,4,159,'کوئی کتابی ایسا نہیں جو اس کی موت سے پہلے اس پر ایمان نہ لائے (ف۴۰۲) اور قیامت کے دن وہ ان پر گواہ ہوگا (ف۴۰۳)'),
 (93,4,160,'تو یہودیوں کے بڑے ظلم کے (ف۴۰۴) سبب ہم نے وہ بعض ستھری چیزیں کہ ان کے لئے حلال تھیں (ف۴۰۵) ان پر حرام فرمادیں اور اس لئے کہ انہوں نے بہتوں کو اللہ کی راہ سے روکا،'),
 (93,4,161,'اور اس لئے کہ وہ سود لیتے حالانکہ وہ اس سے منع کیے گئے تھے اور لوگوں کا مال ناحق کھا جاتے (ف۴۰۶) اور ان میں جو کافر ہوئے ہم نے ان کے لئے دردناک عذاب تیار کر رکھا ہے،'),
 (93,4,162,'ہاں جو اُن میں علم کے پکے (ف۴۰۷) اور ایمان والے ہیں وہ ایمان لاتے ہیں اس پر جو اے محبوب تمہاری طرف اُترا اور جو تم سے پہلے اُترا (ف۴۰۸) اور نماز قائم رکھنے والے اور زکوٰة دینے والے اور اللہ اور قیامت پر ایمان لانے والے ایسوں کو عنقریب ہم بڑا ثواب دیں گے،'),
 (93,4,163,'بیشک اے محبوب! ہم نے تمہاری طرف وحی بھیجی جیسے دحی نوح اور اس کے بعد پیغمبروں کو بھیجی (ف۴۰۹) اور ہم نے ابراہیم اور اسمٰعیل اور اسحاق اور یعقوب اور ان کے بیٹوں اور عیسیٰ اور ایوب اور یونس اور ہارون اور سلیمان کو وحی کی اور ہم نے داؤد کو زبور عطا فرمائی'),
 (93,4,164,'اور رسولوں کو جن کا ذکر آگے ہم تم سے (ف۴۱۰) فرماچکے اور ان رسولوں کو جن کا ذکر تم سے نہ فرمایا (ف۴۱۱) اور اللہ نے موسیٰ سے حقیقتاً کلام فرمایا (ف۴۱۲)'),
 (93,4,165,'رسول خوشخبری دیتے (ف۴۱۳) اور ڈر سناتے (ف۴۱۴) کہ رسولوں کے بعد اللہ کے یہاں لوگوں کو کوئی عذر نہ رہے (ف۴۱۵) اور اللہ غالب حکمت والا ہے،'),
 (93,4,166,'لیکن اے محبوب! اللہ اس کا گواہ ہے جو اس نے تمہاری طرف اتارا وہ اس نے اپنے علم سے اتارا ہے اور فرشتے گواہ ہیں اور اللہ کی گواہی کافی،'),
 (93,4,167,'وہ جنہوں نے کفر کیا (ف۴۱۶) اور اللہ کی راہ سے روکا (ف۴۱۷) بیشک وہ دور کی گمراہی میں پڑے،'),
 (93,4,168,'بیشک جنہوں نے کفر کیا (ف۳۱۸) اور حد سے بڑھے (ف۴۱۹) اللہ ہرگز انہیں نہ بخشے گا(ف۴۲۰) اور نہ انہیں کوئی راہ دکھائے،'),
 (93,4,169,'مگر جہنم کا راستہ کہ اس میں ہمیشہ ہمیشہ رہیتں گے اور یہ اللہ کو آسان ہے،'),
 (93,4,170,'اے لوگو! تمہارے پاس یہ رسول (ف۴۲۱) حق کے ساتھ تمہارے رب کی طرف سے تشریف لائے تو ایمان لاؤ اپنے بھلے کو اور اگر تم کفر کرو (ف۴۲۲) تو بیشک اللہ ہی کا ہے جو کچھ آسمانوں اور زمین میں ہے، اور اللہ علم و حکمت والا ہے،'),
 (93,4,171,'اے کتاب والو! اپنے دین میں زیادتی نہ کرو (ف۴۲۳) اور اللہ پر نہ کہو مگر سچ (ف۴۲۴) مسیح عیسیٰ مریم کا بیٹا (ف۴۲۵) ا لله کا رسول ہی ہے اور اس کا ایک کلمہ (ف۴۲۶) کہ مریم کی طرف بھیجا اور اس کے یہاں کی ایک روح تو اللہ اور اس کے رسولوں پر ایمان لاؤ (ف۴۲۷) اور تین نہ کہو (ف۴۲۸) باز رہو اپنے بھلے کو اللہ تو ایک ہی خدا ہے (ف۴۲۹) پاکی اُسے اس سے کہ اس کے کوئی بچہ ہو اسی کا مال ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے (ف۴۳۰) اور اللہ کافی کارساز،'),
 (93,4,172,'مسیح اللہ کا بندہ بننے سے کچھ نفرت نہیں کرتا (ف۴۳۱) اور نہ مقرب فرشتے اور جو اللہ کی بندگی سے نفرت اور تکبر کرے تو کوئی دم جاتا ہے کہ وہ ان سب کو اپنی طرف ہانکے گا (ف۴۳۲)'),
 (93,4,173,'تو وہ جو ایمان لائے اور اچھے کام کیے ان کی مزدوری انہیں بھرپور دے کر اپنے فضل سے انہیں اور زیادہ دے گا اور وہ جنہوں نے (ف۴۳۳) نفرت اور تکبر کیا تھا انہیں دردناک سزا دے گا اور اللہ کے سوا نہ اپنا کوئی حمایتی پائیں گے نہ مددگار،'),
 (93,4,174,'اے لوگو! بیشک تمہارے پاس اللہ کی طرف سے واضح دلیل آئی (ف۴۳۴) اور ہم نے تمہاری طرف روشن نور اتارا (ف۴۳۵)'),
 (93,4,175,'تو وہ جو اللہ پر ایمان لائے اور اس کی رسی مضبوط تھامی تو عنقریب اللہ انہیں اپنی رحمت اور اپنے فضل میں داخل کرے گا (ف۴۳۶) اور انہیں اپنی طرف سیدھی راہ دکھائے گا،'),
 (93,4,176,'اے محبوب! تم سے فتویٰ پوچھتے ہیں تم فرمادو کہ اللہ تمہیں کلالہ (ف۴۳۷) میں فتویٰ دیتا ہے، اگر کسی مرد کا انتقال ہو جو بے اولاد ہے (ف۴۳۸) اور اس کی ایک بہن ہو تو ترکہ میں اس کی بہن کا آدھا ہے (ف۴۳۹) اور مرد اپنی بہن کا وارث ہوگا اگر بہن کی اولاد نہ ہو (ف۴۴۰) پھر اگر دو بہنیں ہوں ترکہ میں ان کا دو تہائی اور اگر بھائی بہن ہوں مرد بھی اور عورتیں بھی تو مرد کا حصہ دو عورتوں کے برابر، ا لله تمہارے لئے صاف بیان فرماتا ہے کہ کہیں بہک نہ جاؤ، اور اللہ ہرچیز جانتا ہے،'),
 (93,5,1,'اے ایمان والو! اپنے قول پورے کرو (ف۲) تمہارے لئے حلال ہوئے بے زبان مویشی مگر وہ جو آگے سنایا جائے گا تم کو (ف۳) لیکن شکار حلال نہ سمجھو جب تم احرام میں ہو (ف۴) بیشک اللہ حکم فرماتا ہے جو چاہے،'),
 (93,5,2,'اے ایمان والو! حلال نہ ٹھہرالو اللہ کے نشان (ف۵) اور نہ ادب والے مہینے (ف۶) اور نہ حرم کو بھیجی ہوئی قربانیاں اور نہ (ف۷) جن کے گلے میں علامتیں آویزاں (ف۸) اور نہ ان کا مال و آبرو جو عزت والے گھر کا قصد کرکے آئیں (ف۹) اپنے رب کا فضل اوراس کی خوشی چاہتے اور جب احرام سے نکلو تو شکار کرسکتے ہو (ف۱۰) اور تمہیں کسی قوم کی عداوت کہ انہوں نے تم کو مسجد حرام سے روکا تھا، زیادتی کرنے پر نہ ابھارے (ف۱۱) اور نیکی اور پرہیزگاری پر ایک دوسرے کی مدد کرو اور گناہ اور زیادتی پر باہم مدد نہ دو (ف۱۲) اور اللہ سے ڈرتے رہو بیشک اللہ کا عذاب سخت ہے،'),
 (93,5,3,'تم پر حرام ہے (ف۱۳) مُردار اور خون اور سور کا گوشت اور وہ جس کے ذبح میں غیر خدا کا نام پکارا گیا اور جو گلا گھونٹنے سے مرے اور بے دھار کی چیز سے مارا ہوا اور جو گر کر مرا اور جسے کسی جانور نے سینگ مارا اور جسے کوئی درندہ کھا گیا مگر جنہیں تم ذبح کرلو، اور جو کسی تھان پر ذبح کیا گیا اور پانسے ڈال کر بانٹا کرنا یہ گناہ کا کا م ہے، آج تمہارے دین کی طرف سے کافروں کی آس نوٹ گئی (ف۱۴) تو اُن سے نہ ڈرو اور مجھ سے ڈرو آج میں نے تمہارے لئے دین کامل کردیا (ف۱۵) اور تم پر اپنی نعمت پوری کردی (ف۱۶) اور تمہارے لئے اسلام کو دین پسند کیا (ف۱۷) تو جو بھوک پیاس کی شدت میں ناچار ہو یوں کہ گناہ کی طرف نہ جھکے (ف۱۸) تو بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,5,4,'اے محبوب! تم سے پوچھتے ہیں کہ اُن کے لئے کیا حلال ہوا تم فرمادو کہ حلال کی گئیں تمہارے لئے پاک چیزیں (ف۱۹) اور جو شکاری جانور تم نے سدھالیے (ف۲۰) انہیں شکار پر دوڑاتے جو علم تمہیں خدا نے دیا اس سے انہیں سکھاتے تو کھاؤ اس میں سے جو وہ مار کر تمہارے لیے رہنے دیں (ف۲۱) اور اس پر اللہ کا نام لو (ف۲۲) اور اللہ سے ڈرتے رہو بیشک اللہ کو حساب کرتے دیر نہیں لگتی،'),
 (93,5,5,'آج تمہارے لئے پاک چیزیں حلال ہوئیں، اور کتابیوں کا کھانا (ف۲۳) تمہارے لیے حلال ہوا، اور تمہارا کھانا ان کے لئے حلال ہے، اور پارسا عورتیں مسلمان (ف۲۴) اور پارسا عورتیں ان میں سے جن کو تم سے پہلے کتاب ملی جب تم انہیں ان کے مہر دو قید میں لاتے ہوئے (ف۲۵) نہ مستی نکالتے اور نہ ناآشنا بناتے (ف۲۶) اور جو مسلمان سے کافر ہو اس کا کیا دھرا سب اکارت گیا اور وہ آخرت میں زیاں کار ہے(ف۲۷)'),
 (93,5,6,'اے ایمان والو جب نماز کو کھڑے ہونا چاہو (ف۲۸) تو اپنا منہ دھوؤ اور کہنیوں تک ہاتھ (ف۲۹) اور سروں کا مسح کرو (ف۳۰) اور گٹوں تک پاؤ ں دھوؤ (ف۳۱) اور اگر تمہیں نہانے کی حاجت ہو تو خوب ستھرے ہولو (ف۳۲) اور اگر تم بیمار ہو یا سفر میں ہو یا تم میں سے کوئی قضائے حاجت سے آیا یا تم نے عورتوں سے صحبت کی اور ان صورتوں میں پانی نہ پایا مٹی سے تیمم کرو تو اپنے منہ اور ہاتھوں کا اس سے مسح کرو، اللہ نہیں چاہتا کہ تم پر کچھ تنگی رکھے ہاں یہ چاہتا ہے کہ تمہیں خوب ستھرا کردے اور اپنی نعمت تم پر پوری کردے کہ کہیں تم احسان مانو،'),
 (93,5,7,'اور یاد کرو اللہ کا احسان اپنے اوپر (ف۳۳) اور وہ عہد جو اس نے تم سے لیا (ف۳۴) جبکہ تم نے کہا ہم نے سنا اور مانا اور اللہ سے ڈرو بیشک اللہ دلوں کی بات جانتا ہے،'),
 (93,5,8,'اے ایمان والوں اللہ کے حکم پر خوب قائم ہوجاؤ انصاف کے ساتھ گواہی دیتے (ف۳۶) اور تم کو کسی قوم کی عداوت اس پر نہ اُبھارے کہ انصاف نہ کرو، انصاف کرو، وہ پرہیزگاری سے زیادہ قریب ہے، اور اللہ سے ڈرو، بیشک اللہ کو تمہارے کامو ں کی خبر ہے،'),
 (93,5,9,'ایمان والے نیکو کاروں سے اللہ کا وعدہ ہے کہ ان کے لئے بخشش اور بڑا ثواب ہے،'),
 (93,5,10,'اور وہ جنہوں نے کفر کیا اور ہماری آیتیں جھٹلائیں وحی دوزخ والے ہیں(ف۳۷)'),
 (93,5,11,'اے ایمان والو! اللہ کا احسان اپنے اوپر یاد کرو جب ایک قوم نے چاہا کہ تم پر دست درازی کریں تو اس نے ان کے ہاتھ تم پر سے روک دیئے (ف۳۸) اور اللہ سے ڈرو اور مسلمانوں کو اللہ ہی پر بھروسہ چاہئے،'),
 (93,5,12,'اور بیشک اللہ نے بنی اسرائیل سے عہد کیا (ف۳۹) اور ہم نے ان میں بارہ سردار قائم کیے (ف۴۰) اور اللہ نے فرمایا بیشک میں (ف۴۱) تمہارے ساتھ ہوں ضرور اگر تم نماز قائم رکھو اور زکوٰة دو اور میرے سوالوں پر ایمان لاؤ اور ان کی تعظیم کرو اور اللہ کو قرض حسن دو (ف۴۲) بیشک میں تمہارے گناہ اتار دوں گا اور ضرور تمہیں باغوں میں لے جاؤں گا جن کے نیچے نہریں رواں، پھر اس کے بعد جو تم میں سے کفر کرے وہ ضرور سیدھی راہ سے بہکا (ف۴۳)'),
 (93,5,13,'تو ان کی کیسی بد عہدیوں (ف۴۴) پر ہم نے انہیں لعنت کی اور ان کے دل سخت کردیئے اللہ کی باتوں کو (ف۴۵) ان کے ٹھکانوں سے بدلتے ہیں اور بُھلا بیٹھے بڑا حصہ ان نصیحتوں کا جو انہیں دی گئیں (ف۴۶) اور تم ہمیشہ ان کی ایک نہ ایک دغا پر مطلع ہوتے رہو گے (ف۴۷) سوا تھوڑوں کے (ف۴۸) تو انہیں معاف کردو اور ان سے درگزرو (ف۴۹) بیشک احسان والے ا لله کو محبوب ہیں،'),
 (93,5,14,'اور وہ جنہوں نے دعویٰ کیا کہ ہم نصاریٰ ہیں ہم نے ان سے عہد لیا (ف۵۰) تو وہ بھلا بیٹھے بڑا حصہ ان نصیحتوں کا جو انہیں دی گئیں (ف۵۱) تو ہم نے ان کے آپس میں قیامت کے دن تک بَیر اور بغض ڈال دیا (ف۵۲) اور عنقریب اللہ انہیں بتادے گا جو کچھ کرتے تھے (ف۵۳)'),
 (93,5,15,'اے کتاب والو (ف۵۴) بیشک تمہارے پاس ہمارے یہ رسول (ف۵۵) تشریف لائے کہ تم پر ظاہر فرماتے ہیں بہت سی وہ چیزیں جو تم نے کتاب میں چھپا ڈالی تھیں (ف۵۶) اور بہت سی معاف فرماتے ہیں (ف۵۷) بیشک تمہارے پاس اللہ کی طرف سے ایک نور آیا (ف۵۸) اور روشن کتاب(ف۵۹)'),
 (93,5,16,'اللہ اس سے ہدایت دیتا ہے اسے جو اللہ کی مرضی پر چلا سلامتی کے ساتھ اور انہیں اندھیریوں سے روشنی کی طرف لے جاتا ہے اپنے حکم سے اور انہیں سیدھی راہ دکھاتا ہے،'),
 (93,5,17,'بیشک کافر ہوئے وہ جنہوں نے کہا کہ اللہ مسیح بن مریم ہی ہے (ف۶۰) تم فرما دو پھر اللہ کا کوئی کیا کرسکتا ہے اگر وہ چاہے کہ ہلاک کردے مسیح بن مریم اور اس کی ماں اور تمام زمین والوں کو (ف۶۱) اور اللہ ہی کے لیے ہے سلطنت آسمانوں اور زمین اور ان کے درمیان کی جو چاہے پیدا کرتا ہے، اور اللہ سب کچھ کرسکتا ہے،'),
 (93,5,18,'اور یہودی اور نصرانی بولے کہ ہم اللہ کے بیٹے اور اس کے پیارے ہیں (ف۶۲) تم فرما دو پھر تمہیں کیوں تمہارے گناہوں پر عذاب فرماتا ہے (ف۶۳) بلکہ تم آدمی ہو اس کی مخلوقات سے جسے چاہے بخشتا ہے اور جسے چاہے سزا دیتا ہے، اور اللہ ہی کے لئے ہے سلطنت آسمانوں اور زمین اور اس کے درمیان کی، اور اسی کی طرف پھرنا ہے،'),
 (93,5,19,'اے کتاب والو! بیشک تمہارے پاس ہمارے یہ رسول (ف۶۴) تشریف لائے کہ تم پر ہمارے احکام ظاہر فرماتے ہیں بعد اس کے کہ رسولوں کا آنا مدتوں بند رہا تھا (ف۶۵) کہ کبھی کہو کہ ہمارے پاس کوئی خوشی اور ڈر سنانے والا نہ آیا تو یہ خوشی اور ڈر سنانے والے تمہارے پاس تشریف لائے ہیں، اور اللہ کو سب قدرت ہے،'),
 (93,5,20,'اور جب موسیٰ نے کہا اپنی قوم سے اے میری قوم اللہ کا احسان اپنے اوپر یاد کرو کہ تم میں سے پیغمبر کیے اور تمہیں بادشاہ کیا (ف۶۷) اور تمہیں وہ دیا جو آج سارے جہان میں کسی کو نہ دیا (ف۶۸)'),
 (93,5,21,'اے قوم اس پاک زمین میں داخل ہو جو اللہ نے تمہارے لیے لکھی ہے اور پیچھے نہ پلٹو (ف۶۹) کہ نقصان پر پلٹو گے،'),
 (93,5,22,'بولے اے موسیٰ اس میں تو بڑے زبردست لوگ ہیں، اور ہم اس میں ہرگز داخل نہ ہوں گے جب تک وہ وہاں سے نکل نہ جائیں ہاں وہ وہاں سے نکل جائیں تو ہم وہاں جائیں،'),
 (93,5,23,'دو مرد کہ اللہ سے ڈرنے والوں میں سے تھے (ف۷۰) ا لله نے انہیں نوازا (ف۷۱) بولے کہ زبردستی دروازے میں (ف۷۲) ان پر داخل ہو اگر تم دروازے میں داخل ہوگئے تو تمہارا ہی غلبہ ہے (ف۷۳) اور اللہ ہی پر بھروسہ کرو اگر تمہیں ایمان ہے،'),
 (93,5,24,'بولے (ف۷۴) اے موسیٰ ہم تو وہاں (ف۷۵) کبھی نہ جائیں گے جب تک وہ وہاں ہیں تو آپ جائیے اور آپ کا رب تم دونوں لڑو ہم یہاں بیٹھے ہیں،'),
 (93,5,25,'موسیٰ نے عرض کی کہ اے رب! میرے مجھے اختیار نہیں مگر اپنا اور اپنے بھائی کا تو تو ہم کو ان بے حکموں سے جدا رکھ (ف۷۶)'),
 (93,5,26,'فرمایا تو وہ زمین ان پر حرام ہے (ف۷۷) چالیس برس تک بھٹکتے پھریں زمین میں (ف۷۸) تو تم ان بے حکموں کا افسوس نہ کھاؤ،'),
 (93,5,27,'اور انہیں پڑھ کر سناؤ آدم کے دو بیٹوں کی سچی خبر (ف۷۹) جب دونوں نے ایک ایک نیاز پیش کی تو ایک کی قبول ہوئی اور دوسرے کی نہ قبول ہوئی بولا قسم ہے میں تجھے قتل کردوں گا (ف۸۰) کہا اللہ اسی سے قبول کرتا ہے، سے ڈر ہے (ف۸۱)'),
 (93,5,28,'بیشک اگر تو اپنا ہاتھ مجھ پر بڑھائے گا کہ مجھے قتل کرے تو میں اپنا ہاتھ تجھ پر نہ بڑھاؤں گا کہ تجھے قتل کروں (ف۸۲) میں اللہ سے ڈرتا ہوں جو مالک ہے سارے جہاں کا،'),
 (93,5,29,'میں تو یہ چاہتا ہوں کہ میرا (ف۷۳) اور تیرا گناہ (ف۸۴) دونوں تیرے ہی پلہ پڑے تو تو دوز خی ہوجائے، اور بے انصافوں کی یہی سزا ہے،'),
 (93,5,30,'تو اسکے نفس نے اسے بھائی کے قتل کا چاؤ دلایا تو اسے قتل کردیا تو رہ گیا نقصان میں(ف۸۵)'),
 (93,5,31,'تو اللہ نے ایک کوا بھیجا زمین کریدتا کہ اسے دکھائے کیونکر اپنے بھائی کی لاش چھپائے (ف۸۶) بولا ہائے خرابی میں اس کوے جیسا بھی نہ ہوسکا کہ میں اپنے بھائی کی لاش چھپاتا تو پچتاتا رہ گیا(ف۸۷)'),
 (93,5,32,'اس سبب سے ہم نے بنی اسرائیل پر لکھ دیا کہ جس نے کوئی جان قتل کی بغیر جان کے بدلے یا زمین میں فساد کیے (ف۸۸) تو گویا اس نے سب لوگوں کو قتل کیا (ف۸۹) اور جس نے ایک جان کو جِلا لیا (ف۹۰) اس نے گویا سب لوگوں کو جلالیا، اور بیشک ان کے (ف۹۱) پاس ہمارے رسول روشن دلیلوں کے ساتھ آئے (ف۹۲) پھر بیشک ان میں بہت اس کے بعد زمین میں زیادتی کرنے والے ہیں(ف۹۳)'),
 (93,5,33,'وہ کہ اللہ اور اس کے رسول سے لڑتے (ف۹۴) اور ملک میں فساد کرتے پھرتے ہیں ان کا بدلہ یہی ہے کہ گن گن کر قتل کیے جائیں یا سولی دیے جائیں یا ان کے ایک طرف کے ہاتھ اور دوسری طرف کے پاؤں کاٹے جائیں یا زمین سے دور کردیے جائیں، یہ دنیا میں ان کی رسوائی ہے، اور آخرت میں ان کے لیے بڑا غداب،'),
 (93,5,34,'مگر وہ جنہوں نے توبہ کرلی اس سے پہلے کہ تم ان پر قابو پاؤ (ف۹۵) تو جان لو کہ اللہ بخشنے والا مہربان ہے،'),
 (93,5,35,'اے ایمان والو! اللہ سے ڈرو اور اس کی طرف وسیلہ ڈھونڈو (ف۶۶) اور اس کی راہ میں جہاد کرو اس امید پر کہ فلاح پاؤ،'),
 (93,5,36,'بیشک وہ جو کافر ہوئے جو کچھ زمین میں ہے سب اور اس کی برابر اور اگر ان کی ملک ہو کہ اسے دے کر قیامت کے عذاب سے اپنی جان چھڑائیں تو ان سے نہ لیا جائے گا اور ان کے لئے دکھ کا عذاب ہے(ف۹۷)'),
 (93,5,37,'دوزخ سے نکلنا چاہیں گے اور وہ اس سے نہ نکلیں گے اور ان کو دوامی سزا ہے،'),
 (93,5,38,'اور جو مرد یا عورت چور ہو (ف۹۸) تو ان کا ہاتھ کاٹو (ف۹۹) ان کے کیے کا بدلہ اللہ کی طرف سے سزا، اور اللہ غالب حکمت والا ہے،'),
 (93,5,39,'تو جو اپنے ظلم کے بعد توبہ کرے اور سنور جائے تو اللہ اپنی مہر سے اس پر رجوع فرمائے گا (ف۱۰۰) بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,5,40,'کیا تجھے معلوم نہیں کہ اللہ کے لئے ہے آسمانوں اور زمین کی بادشاہی، سزا دیتا ہے جسے چاہے اور بخشتا ہے جسے چاہے، اور اللہ سب کچھ کرسکتا ہے، (ف۱۰۱)'),
 (93,5,41,'اے رسول! تمہیں غمگین نہ کریں وہ جو کفر پڑ دوڑتے ہیں (ف۱۰۲) جو کچھ وہ اپنے منہ سے کہتے ہیں ہم ایمان لائے اور ان کے دل مسلمان نہیں (ف۱۰۳) اور کچھ یہودی جھوٹ خوب سنتے ہیں (ف۱۰۴) اور لوگوں کی خوب سنتے ہیں (ف۱۰۵) جو تمہارے پاس حاضر نہ ہوئے اللہ کی باتوں کو ان کے ٹھکانوں کے بعد بدل دیتے ہیں، کہتے ہیں یہ حکم تمہیں ملے تو مانو اور یہ نہ ملے تو بچو (ف۱۰۶) اور جسے اللہ گمراہ کرنا چاہے تو ہرگز تو اللہ سے اس کا کچھ بنا نہ سکے گا، وہ ہیں کہ اللہ نے ان کا دل پاک کرنا نہ چاہا، انہیں دنیا میں رسوائی ہے، اور انہیں آخرت میں بڑا عذاب،'),
 (93,5,42,'بڑے جھوٹ سننے والے بڑے حرام خور (ف۱۰۷) تو اگر تمہارے حضور حاضر ہوں (ف۱۰۸) تو ان میں فیصلہ فرماؤ یا ان سے منہ پھیرلو (ف۱۰۹) اور اگر تم ان سے منہ پھیرلو گے تو وہ تمہارا کچھ نہ بگاڑیں گے (ف۱۱۰) اور اگر ان میں فیصلہ فرماؤ تو انصاف سے فیصلہ کرو، بیشک انصاف والے اللہ کو پسند ہیں،'),
 (93,5,43,'اور وہ تم سے کیونکر فیصلہ چاہیں گے، حالانکہ ان کے پاس توریت ہے جس میں اللہ کا حکم موجود ہے (ف۱۱۱) بایں ہمہ اسی سے منہ پھیرتے ہیں (ف۱۱۲) اور وہ ایمان لانے والے نہیں،'),
 (93,5,44,'بیشک ہم نے توریت اتاری اس میں ہدایت اور نور ہے، اس کے مطابق یہود کو حکم دیتے تھے ہمارے فرمانبردار نبی اور عالم اور فقیہہ کہ ان سے کتاب اللہ کی حفاظت چاہی گئی تھی (ف۱۱۳) اور وہ اس پر گواہ تھے تو (ف۱۱۴) لوگوں سے خوف نہ کرو اور مجھ سے ڈرو اور میری آیتوں کے بدلے ذلیل قیمت نہ لو (ف۱۱۵) اور جو اللہ کے اتارے پر حکم نہ کرے (ف۱۱۶) وہی لوگ کافر ہیں،'),
 (93,5,45,'اور ہم نے توریت میں ان پر واجب کیا (ف۱۱۷) کہ جان کے بدلے جان (ف۱۱۸) اور آنکھ کے بدلے آنکھ اور ناک کے بدلے ناک اور کان کے بدلے کان اور دانت کے بدلے دانت اور زخموں میں بدلہ ہے (ف۱۱۹) پھر جو دل کی خوشی سے بدلہ کراوے تو وہ اس کا گناہ اتار دے گا (ف۱۲۰) اور جو اللہ کے اتارے پر حکم نہ کرے تو وہی لوگ ظالم ہیں،'),
 (93,5,46,'اور ہم ان نبیوں کے پیچھے ان کے نشانِ قدم پر عیسیٰ بن مریم کو لائے تصدیق کرتا ہوا توریت کی جو اس سے پہلے تھی (ف۱۲۱) اور ہم نے اسے انجیل عطا کی جس میں ہدایت اور نور ہے اور تصدیق فرماتی ہے توریت کی کہ اس سے پہلی تھی اور ہدایت (ف۱۲۲) اور نصیحت پرہیزگاروں کو،'),
 (93,5,47,'اور چاہئے کہ انجیل والے حکم کریں اس پر جو اللہ نے اس میں اتارا (ف۱۲۳) اور جو اللہ کے اتارے پر حکم نہ کریں تو وہی لوگ فاسق ہیں،'),
 (93,5,48,'اور اے محبوب ہم نے تمہاری طرف سچی کتاب اتاری اگلی کتابوں کی تصدیق فرماتی (ف۱۲۴) اور ان پر محافظ و گواہ تو ان میں فیصلہ کرو اللہ کے اتارے سے (ف۱۲۵) اور اسے سننے والے ان کی خواہشوں کی پیروی نہ کرنا اپنے پاس آیا ہوا حق چھوڑ کر، ہم نے تم سب کے لیے ایک ایک شریعت اور راستہ رکھا (ف۱۲۶) اور اللہ چاہتا تو تم سب کو ایک ہی امت کردیتا مگر منظور یہ ہے کہ جو کچھ تمہیں دیا اس میں تمہیں آزمائے (ف۱۲۷) تو بھلائیوں کی طرف سبقت چاہو، تم سب کا پھرنا اللہ ہی کی طرف ہے تو وہ تمہیں بتادے گا جس بات میں تم جھگڑتے تھے'),
 (93,5,49,'اور یہ کہ اے مسلمان! اللہ کے اتارے پر حکم کر اور ان کی خواہشوں پر نہ چل اور ان سے بچتا رہ کہ کہیں تجھے لغزش نہ دے دیں کسی حکم میں جو تیری طرف اترا پھر اگر وہ منہ پھیریں (ف۱۲۸) تو جان لو کہ اللہ ان کے بعض گناہوں کی (ف۱۲۹) سزا ان کو پہنچایا چاہتا ہے (ف۱۳۰) اور بیشک بہت آدمی بے حکم ہیں،'),
 (93,5,50,'تو کیا جاہلیت کا حکم چاہتے ہیں (ف۱۳۱) اور اللہ سے بہتر کس کا حکم یقین والوں کے لیے،'),
 (93,5,51,'اے ایمان والو! یہود و نصاریٰ کو دوست نہ بناؤ (ف۱۳۲) وہ آپس میں ایک دوسرے کے دوست ہیں (ف۱۳۳) اور تم میں جو کوئی ان سے دوستی رکھے گا تو وہ انہیں میں سے ہے (ف۱۳۴) بیشک اللہ بے انصافوں کو راہ نہیں دیتا (ف۱۳۵)'),
 (93,5,52,'اب تم انہیں دیکھو گے جن کے دلوں میں آزار ہے (ف۱۳۶) کہ یہود و نصاریٰ کی طرف دوڑتے ہیں کہتے ہیں ہم ڈرتے ہیں کہ ہم پر کوئی گردش آجائے (ف۱۳۷) تو نزدیک ہے کہ اللہ فتح لائے (ف۱۳۸) یا اپنی طرف سے کوئی حکم (ف۱۳۹) پھر اس پر جو اپنے دلوں میں چھپایا تھا (ف۱۴۰) پچھتائے رہ جائیں'),
 (93,5,53,'اور (ف۱۴۱) ایمان والے کہتے ہیں کیا یہی ہیں جنہوں نے اللہ کی قسم کھائی تھی اپنے حلف میں پوری کوشش سے کہ وہ تمہارے ساتھ ہیں ان کا کیا دھرا سب اکارت گیا تو رہ گئے نقصان میں (ف۱۴۲)'),
 (93,5,54,'اے ایمان والو! تم میں جو کوئی اپنے دین سے پھرے گا (ف۱۴۳) تو عنقریب اللہ ایسے لوگ لائے گا کہ وہ اللہ کے پیارے اور اللہ ان کا پیارا مسلمانوں پر نرم اور کافروں پر سخت اللہ کی راہ میں لڑیں گے اور کسی ملامت کرنے والے کی ملامت کا اندیشہ نہ کریں گے (ف۱۴۴) یہ اللہ کا فضل ہے جسے چاہے دے، اور اللہ وسعت والا علم والا ہے،'),
 (93,5,55,'تمہارے دوست نہیں مگر اللہ اور اس کا رسول اور ایمان والے (ف۱۴۵) کہ نماز قائم کرتے ہیں اور زکوٰة دیتے ہیں اور اللہ کے حضور جھکے ہوئے ہیں (ف۱۴۶)'),
 (93,5,56,'اور جو اللہ اور اس کے رسول اور مسلمانوں کو اپنا دوست بنائے تو بیشک اللہ ہی کا گروہ غالب ہے،'),
 (93,5,57,'اے ایمان والو! جنہوں نے تمہارے دین کو ہنسی کھیل بنالیا ہے (ف۱۴۷) وہ جو تم سے پہلے کتاب دیے گئے اور کافر (ف۱۴۸) ان میں کسی کو اپنا دوست نہ بناؤ اور اللہ سے ڈرتے رہو اگر ایمان رکھتے ہو(ف۱۴۹)'),
 (93,5,58,'اور جب تم نماز کے لئے اذان دو تو اسے ہنسی کھیل بناتے ہیں (ف۱۵۰) یہ اس لئے کہ وہ نرے بے عقل لوگ ہیں (ف۱۵۱)'),
 (93,5,59,'تم فرماؤ اے کتابیوں تمہیں ہمارا کیا برا لگا یہی نہ کہ ہم ایمان لائے اللہ پر اور اس پر جو ہماری طرف اترا اور اس پر جو پہلے اترا (ف۱۵۲) اور یہ کہ تم میں اکثر بے حکم ہیں،'),
 (93,5,60,'تم فرماؤ کیا میں بتادوں جو اللہ کے یہاں اس سے بدتر درجہ میں ہیں (ف۱۵۳) وہ جن پر اللہ نے لعنت کی اور ان پر غضب فرمایا اور ان میں سے کردیے بندر اور سور (ف۱۵۴) اور شیطان کے پجاری ان کا ٹھکانا زیادہ برا ہے (ف۱۵۵) اور یہ سیدھی راہ سے زیادہ بہکے،'),
 (93,5,61,'اور جب تمہارے پاس آئیں (ف۱۵۶) ہم مسلمان ہیں اور وہ آتے وقت بھی کافر تھے اور جاتے وقت بھی کافر، اور اللہ خوب جانتا ہے جو چھپا رہے ہیں'),
 (93,5,62,'اور ان (ف۱۵۷) میں تم بہتوں کو دیکھو گے کہ گناہ اور زیادتی اور حرام خوری پر دوڑتے ہیں (ف۱۵۸) بیشک بہت ہی برے کام کرتے ہیں،'),
 (93,5,63,'انہیں کیوں نہیں منع کرتے ان کے پادری اور درویش گناہ کی بات کہنے اور حرام کھانے سے، بیشک بہت ہی برے کام کررہے ہیں (ف۱۵۹)'),
 (93,5,64,'اور یہودی بولے اللہ کا ہاتھ بندھا ہوا ہے (ف۱۶۰) ان کے ہاتھ باندھے جائیں (ف۱۶۱) اور ان پر اس کہنے سے لعنت ہے بلکہ اس کے ہاتھ کشادہ ہیں (ف۱۶۲) عطا فرماتا ہے جیسے چاہے (ف۱۶۳) اور اے محبوب! یہ (ف۱۶۴) جو تمہاری طرف تمہارے رب کے پاس سے اترا اس سے ان میں بہتوں کو شرارت اور کفر میں ترقی ہوگی (ف۱۶۵) اور ان میں ہم نے قیامت تک آپس میں دشمنی اور بیر ڈال دیا (ف۱۶۶) جب کبھی لڑائی کی آگ بھڑکاتے ہیں اللہ اسے بجھا دیتا ہے (ف۱۶۷) اور زمین میں فساد کے لیے دوڑتے پھرتے ہیں، اور اللہ فسادیوں کو نہیں چاہتا،'),
 (93,5,65,'اور اگر کتاب والے ایمان لاتے اور پرہیزگاری کرتے تو ضرور ہم ان کے گناہ اتار دیتے اور ضرور انہیں چین کے باغوں میں لے جاتے'),
 (93,5,66,'اور اگر وہ قائم رکھتے توریت اور انجیل (ف۱۶۸) اور جو کچھ ان کی طرف ان کے رب کی طرف سے اترا (ف۱۶۹) تو انہیں رزق ملتا اوپر سے اور ان کے پاؤں کے نیچے سے (ف۱۷۰) ان میں کوئی گروہ اگر اعتدال پر ہے (ف۱۷۱) اور ان میں اکثر بہت ہی برے کام کررہے ہیں(ف۱۷۲)'),
 (93,5,67,'اے رسول پہنچا دو جو کچھ اترا تمہیں تمہارے رب کی طرف سے (ف۱۷۳) اور ایسا نہ ہو تو تم نے اس کا کوئی پیام نہ پہنچایا اور اللہ تمہاری نگہبانی کرے گا لوگوں سے (ف۱۷۴) بیشک اللہ کافروں کو راہ نہیں دیتا،'),
 (93,5,68,'تم فرمادو، اے کتابیو! تم کچھ بھی نہیں ہو (ف۱۷۵) جب تک نہ قائم کرو توریت اور انجیل اور جو کچھ تمہاری طرف تمہارے رب کے پاس سے اترا (ف۱۷۶) اور بیشک اے محبوب! وہ جو تمہاری طرف تمہارے رب کے پاس سے اترا اس میں بہتوں کو شرارت اور کفر کی اور ترقی ہوگی (ف۱۷۷) تو تم کافروں کا کچھ غم نہ کھاؤ،'),
 (93,5,69,'بیشک وہ جو اپنے آپ کو مسلمان کہتے ہیں (ف۱۷۸) اور اسی طرح یہودی اور ستارہ پرت اور نصرانی ان میں جو کوئی سچے دل سے اللہ اور قیامت پر ایمان لائے اور اچھے کام کرے توان پر نہ کچھ اندیشہ ہے اور نہ کچھ غم،'),
 (93,5,70,'بیشک ہم نے بنی اسرائیل سے عہد لیا (ف۱۷۹) اور ان کی طرف رسول بھیجے، جب کبھی ان کے پاس کوئی رسول وہ بات لے کر آیا جو ان کے نفس کی خواہش نہ تھی (ف۱۸۰) ایک گروہ کو جھٹلایا اور ایک گروہ کو شہید کرتے ہیں(ف۱۸۱)'),
 (93,5,71,'اور اس گمان میں ہیں کہ کوئی سزا نہ ہوگی (ف۱۸۲) تو اندھے اور بہرے ہوگئے (ف۱۸۳) پھر اللہ نے ان کی توبہ قبول کی (ف۱۸۴) پھر ان میں بہتیرے اندھے اور بہرے ہوگئے اور اللہ ان کے کام دیکھ رہا ہے،'),
 (93,5,72,'بیشک کافر ہیں وہ جو کہتے ہیں کہ اللہ وہی مسیح مریم کا بیٹا ہے (ف۱۸۵) اور مسیح نے تو یہ کہا تھا، اے بنی اسرائیل اللہ کی بندگی کرو جو میرا رب (ف۱۸۶) اور تمہارا رب، بیشک جو اللہ کا شریک ٹھہرائے تو اللہ نے اس پر جنت حرام کردی اور اس کا ٹھکانا دوزخ ہے اور ظالموں کا کوئی مددگار نہیں،'),
 (93,5,73,'بیشک کافر ہیں وہ جو کہتے ہیں اللہ تین خداؤں میں کا تیسرا ہے (ف۱۸۷) اور خدا تو نہیں مگر ایک خدا (ف۱۸۸) اور اگر اپنی بات سے باز نہ آئے (ف۱۸۹) تو جو ان میں کافر مریں گے ان کو ضرور دردناک عذاب پہنچے گا،'),
 (93,5,74,'تو کیوں نہیں رجوع کرتے اللہ کی طرف اور اس سے بخشش مانگتے، اور اللہ بخشنے والا مہربان،'),
 (93,5,75,'مسیح بن مریم نہیں مگر ایک رسول (ف۱۹۰) اس سے پہلے بہت رسول ہو گزرے (ف۱۹۱) اور اس کی ماں صدیقہ ہے (ف۱۹۲) دونوں کھانا کھاتے تھے (ف۱۹۳) دیکھو تو ہم کیسی صاف نشانیاں ان کے لئے بیان کرتے ہیں پھر دیکھو وہ کیسے اوندھے جاتے ہیں،'),
 (93,5,76,'تم فرماؤ کیا اللہ کے سوا ایسے کو پوجتے ہو جو تمہارے نقصان کا مالک نہ نفع کا (ف۱۹۴) اور اللہ ہی سنتا جانتا ہے،'),
 (93,5,77,'تم فرماؤ اے کتاب والو! اپنے دین میں ناحق زیادتی نہ کرو (ف۱۹۵) اور ایسے لوگوں کی خواہش پر نہ چلو (ف۱۹۶) جو پہلے گمراہ ہوچکے اور بہتوں کو گمراہ کیا اور سیدھی راہ سے بہک گئے'),
 (93,5,78,'لعنت کیے گئے وہ جنہوں نے کفر کیا بنی اسرائیل میں داؤد اور عیسیٰ بن مریم کی زبان پر (ف۱۹۷)یہ بدلہ ان کی نافرمانی اور سرکشی کا،'),
 (93,5,79,'جو بری بات کرتے آپس میں ایک دوسرے کو نہ روکتے ضرور بہت ہی برے کام کرتے تھے(ف۱۹۹)'),
 (93,5,80,'ان میں تم بہت کو دیکھو گے کہ کافروں سے دوستی کرتے ہیں، کیا ہی بری چیز اپنے لیے خود آگے بھیجی یہ کہ اللہ کا ان پر غضب ہوا اور وہ عذاب میں ہمیشہ رہیں گے (ف۲۰۰)'),
 (93,5,81,'اور اگر وہ ایمان لاتے (ف۲۰۱) اللہ اور ان نبی پر اور اس پر جو ان کی طرف اترا تو کافروں سے دوستی نہ کرتے (ف۲۰۲) مگر ان میں تو بہتیرے فاسق ہیں،'),
 (93,5,82,'ضرور تم مسلمانوں کا سب سے بڑھ کر دشمن یہودیوں اور مشرکوں کو پاؤ گے اور ضرور تم مسلمانوں کی دوستی میں سب سے زیادہ قریب ان کو پاؤ گے جو کہتے تھے ہم نصاریٰ ہیں (ف۲۰۳) یہ اس لئے کہ ان میں عالم اور درویش ہیں اور یہ غرور نہیں کرتے -(ف۲۰۴)'),
 (93,5,83,'اور جب سنتے ہیں وہ جو رسول کی طرف اترا (ف۲۰۵) تو ان کی آنکھیں دیکھو کہ آنسوؤں سے ابل رہی ہیں (ف۲۰۶) اس لیے کہ وہ حق کو پہچان گئے، کہتے ہیں اے رب ہمارے! ہم ایمان لائے (ف۲۰۷) تو ہمیں حق کے گواہوں میں لکھ لے (ف۲۰۸)'),
 (93,5,84,'اور ہمیں کیا ہوا کہ ہم ایمان نہ لائیں اللہ پر اور اس حق پر کہ ہمارے پاس آیا اور ہم طمع کرتے ہیں کہ ہمیں ہمارا رب نیک لوگوں کے ساتھ داخل کرے(ف۲۰۹)'),
 (93,5,85,'تو اللہ نے ان کے اس کہنے کے بدلے انہیں باغ دیے جن کے نیچے نہریں رواں ہمیشہ ان میں رہیں گے، یہ بدلہ ہے نیکوں کا (ف ۲۱۰)'),
 (93,5,86,'اور وہ جنہوں کفر کیا اور ہماری آیتیں جھٹلائیں وہ ہیں دوزخ والے،'),
 (93,5,87,'اے ایمان والو! (ف۲۱۱) حرام نہ ٹھہراؤ وہ ستھری چیزیں کہ اللہ نے تمہارے لیے حلال کیں (ف۲۱۲) اور حد سے نہ بڑھو، بیشک حد سے بڑھنے والے اللہ کو ناپسند ہیں،'),
 (93,5,88,'اور کھاؤ جو کچھ تمہیں اللہ نے روزی دی حلال پاکیزہ او ر ڈرو اللہ سے جس پر تمہیں ایمان ہے،'),
 (93,5,89,'اللہ تمہیں نہیں پکڑتا تمہاری غلط فہمی کی قسموں پر (ف۲۱۳) ہاں ان قسموں پر گرفت فرماتے ہے جنہیں تم نے مضبوط کیا (ف۲۱۴) تو ایسی قسم کا بدلہ دس مسکینوں کو کھانا دینا (ف۲۱۵) اپنے گھر والوں کو جو کھلاتے ہو اس کے اوسط میں سے (ف۲۱۶) یا انہیں کپڑے دینا (ف۲۱۷) یا ایک بردہ آزاد کرنا تو جو ان میں سے کچھ نہ پائے تو تین دن کے روزے (ف۲۱۸) یہ بدلہ ہے تمہاری قسموں کا، جب قسم کھاؤ (ف۲۱۹) اور اپنی قسموں کی حفاظت کرو (ف۲۲۰) اسی طرح اللہ تم سے اپنی آیتیں بیان فرماتا ہے کہ کہیں تم احسان مانو،'),
 (93,5,90,'اے ایمان والو! شراب اور جوا اور بت اور پانسے ناپاک ہی ہیں شیطانی کام تو ان سے بچتے رہنا کہ تم فلاح پاؤ،'),
 (93,5,91,'شیطان یہی چاہتا ہے کہ تم میں بَیر اور دشمنی ڈلوا دے شراب اور جوئے میں اور تمہیں اللہ کی یاد اور نماز سے روکے (ف۲۲۱) تو کیا تم باز آئے،'),
 (93,5,92,'اور حکم مانو اللہ کا اور حکم مانو رسول کا اور ہوشیار رہو، پھر اگر تم پھر جاؤ (ف۲۲۲) تو جان لو کہ ہمارے رسول کا ذمہ صرف واضح طور پر حکم پہنچادینا ہے (ف۲۲۳)'),
 (93,5,93,'جو ایمان لائے اور نیک کام کیے ان پر کچھ گناہ نہیں (ف۲۲۴) جو کچھ انہوں نے چکھا جب کہ ڈریں اور ایمان رکھیں اور نیکیاں کریں پھر ڈریں اور ایمان رکھیں پھر ڈریں اور نیک رہیں، اور اللہ نیکوں کو دوست رکھتا ہے (ف۲۲۵)'),
 (93,5,94,'اے ایمان والوں ضرور اللہ تمہیں آزمائے گا ایسے بعض شکار سے جس تک تمہارا ہاتھ اور نیزے پہنچیں (ف۲۲۶) کہ اللہ پہچان کرادے ان کی جو اس سے بن دیکھے ڈرتے ہیں، پھر اس کے بعد جو حد سے بڑھے (ف۲۲۷) اس کے لئے دردناک عذاب ہے،'),
 (93,5,95,'اے ایمان والو! شکار نہ مارو جب تم احرام میں ہو (ف۲۲۸) اور تم میں جو اسے قصداً قتل کرے (ف۲۲۹) تو اس کا بدلہ یہ ہے کہ ویسا ہی جانور مویشی سے دے (ف۲۳۰) تم میں کہ دو ثقہ آدمی اس کا حکم کریں (ف۲۳۱) یہ قربانی ہو کہ کعبہ کو پہنچتی (ف۲۳۲) یا کفار ہ دے چند مسکینوں کا کھانا (ف۲۳۳) یا اس کے برابر روزے کہ اپنے کام کا وبال چکھے اللہ نے معاف کیا جو ہو گزرا (ف۲۳۴) اور جو اب کرے گا اس سے بدلہ لے گا، اور اللہ غالب ہے بدلہ لینے والا،'),
 (93,5,96,'حلال ہے تمہارے لیے دریا کا شکار اور اس کا کھانا تمہارے اور مسافروں کے فائدے کو اور تم پرحرام ہے خشکی کا شکار (ف۲۳۵) جب تک تم احرام میں ہو اور اللہ سے ڈرو جس کی طرف تمہیں اٹھنا ہے،'),
 (93,5,97,'اللہ نے ادب والے گھر کعبہ کو لوگوں کے قیام کا باعث کیا (ف۲۳۶) اور حرمت والے مہینہ (ف۲۳۷) اور حرم کی قربانی اور گلے میں علامت آویزاں جانوروں کو (ف۲۳۸) یہ اس لیے کہ تم یقین کرو کہ اللہ جانتا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں اور یہ کہ اللہ سب کچھ جانتا ہے،'),
 (93,5,98,'جان رکھو کہ اللہ کا عذاب سخت ہے (ف۲۳۹) اور اللہ بخشنے والا مہربان،'),
 (93,5,99,'رسول پر نہیں مگر حکم پہنچانا (ف۲۴۰) اور اللہ جانتا ہے جو تم ظاہر کرتے اور جو تم چھپاتے ہو(ف۲۴۱)'),
 (93,5,100,'تم فرمادو کہ گندہ اور ستھرا برابر نہیں (ف۲۴۲) اگرچہ تجھے گندے کی کثرت بھائے، تو اللہ سے ڈرتے رہو اے عقل والو! کہ تم فلاح پاؤ،'),
 (93,5,101,'اے ایمان والو! ایسی باتیں نہ پوچھو جو تم پر ظاہر کی جائیں تو تمہیں بری لگیں (ف۲۴۳) اور اگر انہیں اس وقت پوچھو گے کہ قرآن اتر رہا ہے تو تم پر ظاہر کردی جائیں گی، اللہ انہیں معاف کرچکا ہے (ف۲۴۴) اور اللہ بخشنے والا حلم والا ہے،'),
 (93,5,102,'تم سے اگلی ایک قوم نے انہیں پوچھا (ف ۲۴۵) پھر ان سے منکر ہو بیٹھے،'),
 (93,5,103,'اللہ نے مقرر نہیں کیا ہے کان چِرا ہوا اور نہ بجار اور نہ وصیلہ اور نہ حامی (ف۲۴۶) ہاں کافر لوگ اللہ پر جھوٹا افترا باندھتے ہیں (ف۲۴۷) اور ان میں اکثر نرے بے عقل ہیں(ف۲۴۸)'),
 (93,5,104,'اور جب ان سے کہا جائے آؤ اس طرف جو اللہ نے اُتارا اور رسول کی طرف (ف۲۴۹) کہیں ہمیں وہ بہت ہے جس پر ہم نے اپنے باپ دادا کو پایا، کیا اگرچہ ان کے باپ دادا نہ کچھ جانیں نہ راہ پر ہوں (ف۲۵۰)'),
 (93,5,105,'اے ایمان والو! تم اپنی فکر رکھو تمہارا کچھ نہ بگاڑے گا جو گمراہ ہوا جب کہ تم راہ پر ہو (ف۲۵۱) تم سب کی رجوع اللہ ہی کی طرف ہے پھر وہ تمہیں بتا دے گا جو تم کرتے تھے،'),
 (93,5,106,'اے ایمان والوں (ف۲۵۲) تمہاری آپس کی گواہی جب تم میں کسی کو موت آئے (ف۲۵۳) وصیت کرتے وقت تم میں کے دو معتبر شخص ہیں یا غیروں میں کے دو جب تم ملک میں سفر کو جاؤ پھر تمہیں موت کا حادثہ پہنچے، ان دونوں کو نماز کے بعد روکو (ف۲۵۴) وہ اللہ کی قسم کھائیں اگر تمہیں کچھ شک پڑے (ف۲۵۵) ہم حلف کے بدلے کچھ مال نہ خریدیں گے (ف۲۵۶) اگرچہ قریب کا رشتہ دار ہو اور اللہ کی گواہی نہ چھپائیں گے ایسا کریں تو ہم ضرور گنہگاروں میں ہیں،'),
 (93,5,107,'پھر اگر پتہ چلے کہ وہ کسی گناہ کے سزاوار ہوئے (ف۲۵۷) تو ان کی جگہ دو اور کھڑے ہوں ان میں سے کہ اس گناہ یعنی جھوٹی گواہی نے ان کا حق لے کر ان کو نقصان پہنچایا (ف۲۵۸) جو میت سے زیادہ قریب ہوں تو اللہ کی قسم کھائیں کہ ہماری گواہی زیادہ ٹھیک ہے ان دو کی گواہی سے اور ہم حد سے نہ بڑھے (ف۲۵۹) ایسا ہو تو ہم ظالموں میں ہوں،'),
 (93,5,108,'یہ قریب تر ہے اس سے کہ گواہی جیسی چاہیے ادا کریں یا ڈریں کہ کچھ قسمیں رد کردی جائیں ان کی قسموں کے بعد (ف۲۶۰) اور اللہ سے ڈرو اور حکم سنو، اور اللہ بے حکموں کو راہ نہیں دیتا،'),
 (93,5,109,'جس دن اللہ جمع فرمائے گا رسولوں کو (ف۲۶۱) پھر فرمائے گا تمہیں کیا جواب ملا (ف۲۶۲) عرض کریں گے ہمیں کچھ علم نہیں، بیشک تو ہی ہے سب غیبوں کا جاننے والا(ف۲۶۳)'),
 (93,5,110,'جب اللہ فرمائے گا اے مریم کے بیٹے عیسیٰ! یاد کر میرا احسان اپنے اوپر اور اپنی ماں پر (ف۲۶۴) جب میں نے پاک روح سے تیری مدد کی (ف۲۶۵) تو لوگوں سے باتیں کرتا پالنے میں (ف۲۶۶) اور پکی عمر ہوکر (ف۲۶۷) اور جب میں نے تجھے سکھائی کتاب اور حکمت (ف۲۶۸) اور توریت اور انجیل اور جب تو مٹی سے پرند کی سی مورت میرے حکم سے بناتا پھر اس میں پھونک مارتا تو وہ میرے حکم سے اڑنے لگتی (ف۲۶۹) اور تو مادر زاد اندھے اور سفید داغ والے کو میرے حکم سے شفا دیتا اور جب تو مُردوں کو میرے حکم سے زندہ نکالتا (ف۲۷۰) اور جب میں نے بنی اسرائیل کو تجھ سے روکا (ف۲۷۱) جب تو ان کے پاس روشن نشانیاں لے کر آیا تو ان میں کے کافر بولے کہ یہ (ف۲۷۲) تو نہیں مگر کھلا جادو،'),
 (93,5,111,'اور جب میں نے حواریوں (ف۲۷۳) کے دل میں ڈالا کہ مجھ پر اور میرے رسول پر (ف۲۷۴) ایمان لاؤ بولے ہم ایمان لائے اور گواہ رہ کہ ہم مسلمان ہیں(ف۲۷۵)'),
 (93,5,112,'جب حواریوں نے کہا اے عیسیٰ بن مریم! کیا آپ کا رب ایسا کرے گا کہ ہم پر آسمان سے ایک خوان اُتارے (ف۲۷۶) کہا اللہ سے ڈرو ! اگر ایمان رکھتے ہو(ف۲۷۷)'),
 (93,5,113,'بولے ہم چاہتے ہیں (ف۲۷۸) کہ اس میں سے کھائیں اور ہمارے دل ٹھہریں (ف۲۷۹) اور ہم آنکھوں دیکھ لیں کہ آپ نے ہم سے سچ فرمایا (ف۲۸۰) اور ہم اس پر گواہ ہوجائیں(ف۲۸۱)'),
 (93,5,114,'عیسیٰ بن مریم نے عرض کی، اے اللہ! اے رب ہمارے! ہم پر آسمان سے ایک خوان اُتار کہ وہ ہمارے لیے عید ہو (ف۲۸۲) ہمارے اگلے پچھلوں کی (ف۲۸۳) اور تیری طرف سے نشانی (ف۲۸۴) اور ہمیں رزق دے اور تو سب سے بہتر روزی دینے والا ہے،'),
 (93,5,115,'اللہ نے فرمایا کہ میں اسے تم پر اُتارتا ہوں، پھر اب جو تم میں کفر کرے گا (ف۲۸۵) تو بیشک میں اسے وہ عذاب دوں گا کہ سارے جہان میں کسی پر نہ کروں گا(ف۲۸۶)'),
 (93,5,116,'اور جب اللہ فرمائے گا (ف۲۸۷) اے مریم کے بیٹے عیسیٰ! کیا تو نے لوگوں سے کہہ دیا تھا کہ مجھے اور میری ماں کو دو خدا بنالو اللہ کے سوا (ف۲۸۸) عرض کرے گا، پاکی ہے تجھے (ف۲۸۹) مجھے روا نہیں کہ وہ بات کہوں جو مجھے نہیں پہنچتی (ف۲۹۰) اگر میں نے ایسا کہا ہو تو ضرور تجھے معلوم ہوگا تو جانتا ہے جو میرے جی میں ہے اور میں نہیں جانتا جو تیرے علم میں ہے، بیشک تو ہی ہے سب غیبوں کا خوب جاننے والا (ف۲۹۱)'),
 (93,5,117,'میں نے تو ان سے نہ کہا مگر وہی جو تو نے مجھے حکم دیا تھا کہ ا لله کو پوجو جو میرا بھی رب اور تمھا ر ا بھی رب اور میں ان پر مطلع تھا جب تک ان میں رہا، پھر جب تو نے مجھے اٹھالیا (ف۲۹۲) تو تُو ہی ان پر نگاہ رکھتا تھا، اور ہر چیز تیرے سامنے حاضر ہے(ف۲۹۳)'),
 (93,5,118,'اگر تو انہیں عذاب کرے تو وہ تیرے بندے ہیں، اور اگر تو انہیں بخش دے تو بیشک تو ہی ہے غالب حکمت والا (ف۲۹۴)'),
 (93,5,119,'اللہ نے فرمایا کہ یہ (ف۲۹۵) ہے وہ دن جس میں سچوں کو (ف۲۹۶) ان کا سچ کام آئے گا، ان کے لئے باغ ہیں جن کے نیچے نہریں رواں ہمیشہ ہمیشہ رہیں گے، اللہ ان سے راضی اور وہ اللہ سے راضی، یہ ہے بڑی کامیابی،'),
 (93,5,120,'اللہ ہی کے لئے ہے آسمانوں اور زمین اور جو کچھ ان میں ہے سب کی سلطنت، اور وہ ہر چیز پر قادر ہے(ف۲۹۷)'),
 (93,6,1,'سب خوبیاں اللہ کو جس نے آسمان اور زمین بنائے (ف۲) اور اندھیریاں اور روشنی پیدا کی (ف۳) اس پر (ف۴) کافر لوگ اپنے رب کے برابر ٹھہراتے ہیں(ف۵)'),
 (93,6,2,'وہی ہے جس نے تمہیں (ف۶) مٹی سے پیدا کیا پھر ایک میعاد کا حکم رکھا (ف۷) اور ایک مقررہ وعدہ اس کے یہاں ہے (ف۸) پھر تم لوگ شک کرتے ہو،'),
 (93,6,3,'اور وہی اللہ ہے آسمانوں اور زمین کا (ف۹) اسے تمہارا چھپا اور ظاہر سب معلوم ہے اور تمہارے کام جانتا ہے،'),
 (93,6,4,'اور ان کے پاس کوئی بھی نشانی اپنے رب کی نشانیوں سے نہیں آتی مگر اس سے منہ پھیرلیتے ہیں،'),
 (93,6,5,'تو بیشک انہوں نے حق کو جھٹلایا (ف۱۰) جب ان کے پاس آیا، تو اب انہیں خبر ہوا چاہتی ہے اس چیز کی جس پر ہنس رہے تھے (ف۱۱)'),
 (93,6,6,'کیا انہوں نے نہ د یکھا کہ ہم نے ان سے پہلے (ف۱۲) کتنی سنگتیں کھپا دیں انہیں ہم نے زمین میں وہ جماؤ دیا (ف۱۳) جو تم کو نہ دیا اور ان پر موسلا دھار پانی بھیجا (ف۱۴) اور ان کے نیچے نہریں بہائیں (ف۱۵) تو انہیں ہم نے ان کے گناہوں کے سبب ہلاک کیا (ف۱۶) اور ان کے بعد اور سنگت اٹھائی (ف۱۷)'),
 (93,6,7,'اور اگر ہم تم پر کاغذ میں کچھ لکھا ہوا اتارتے (ف۱۸) کہ وہ اسے اپنے ہاتھوں سے چھوتے جب بھی کافر کہتے کہ یہ نہیں مگر کھلا جادو،'),
 (93,6,8,'اور بولے (ف۱۹) ان پر (ف۲۰) کوئی فرشتہ کیوں نہ اتارا گیا، اور اگر ہم فرشتہ اتارتے (ف۲۱) تو کام تمام ہوگیا ہوتا (ف۲۲) پھر انہیں مہلت نہ دی جاتی (ف۲۳)'),
 (93,6,9,'اور اگر ہم نبی کو فرشتہ کرتے (ف۲۴) جب بھی اسے مرد ہی بناتے (ف۲۵) اور ان پر وہی شبہ رکھتے جس میں اب پڑے ہیں،'),
 (93,6,10,'اور ضرور اے محبوب تم سے پہلے رسولوں کے ساتھ بھی ٹھٹھا کیا گیا تو وہ جو ان سے ہنستے تھے ان کی ہنسی انہیں کو لے بیٹھی (ف۲۶)'),
 (93,6,11,'تم فرمادو (ف۲۷) زمین میں سیر کرو پھر دیکھو کہ جھٹلانے والوں کا کیسا انجام ہوا(ف۲۸)'),
 (93,6,12,'تم فرماؤ کس کا ہے جو کچھ آسمانوں اور زمین میں (ف۲۹) تم فرماؤ اللہ کا ہے (ف۳۰) اس نے اپنے کرم کے ذمہ پر رحمت لکھ لی ہے (ف ۳۱) بیشک ضرور تمہیں قیامت کے دن جمع کرے گا (ف۳۲) اس میں کچھ شک نہیں، وہ جنہوں نے اپنی جان نقصان میں ڈالی (ف۳۳) ایمان نہیں لاتے،'),
 (93,6,13,'اور اسی کا ہے جو بستا ہے رات اور دن میں (ف۳۴) اور وہی ہے سنتا جانتا(ف۳۵)'),
 (93,6,14,'تم فرماؤ کیا اللہ کے سوا کسی اور کو والی بناؤں (ف۳۶) وہ اللہ جس نے آسمان اور زمین پیدا کیے اور وہ کھلاتا ہے اور کھانے سے پاک ہے (ف۳۷) تم فرماؤ مجھے حکم ہوا ہے کہ سب سے پہلے گردن رکھوں (ف۳۸) اور ہرگز شرک والوں میں سے نہ ہونا،'),
 (93,6,15,'تم فرماؤ اگر میں اپنے رب کی نافرمانی کروں تو مجھے بڑے دن (ف۳۹) کے عذاب کا ڈر ہے،'),
 (93,6,16,'اس دن جس سے عذاب پھیر دیا جائے (ف۴۰) ضرور اس پر اللہ کی مہر ہوئی، اور یہی کھلی کامیابی ہے،'),
 (93,6,17,'اور اگر تجھے اللہ کوئی برائی (ف۴۱) پہنچائے تو اس کے سوا اس کا کوئی دور کرنے والا نہیں، اور اگر تجھے بھلائی پہنچائے (ف۴۲) تو وہ سب کچھ کرسکتا ہے(ف۴۳)'),
 (93,6,18,'اور وہی غالب ہے اپنے بندوں پر، اور وہی ہے حکمت والا خبردار،'),
 (93,6,19,'تم فرماؤ سب سے بڑی گواہی کس کی (ف۴۴) تم فرماؤ کہ اللہ گواہ ہے مجھ میں اور تم میں (ف۴۵) اور میر ی طر ف اس قر آ ن کی وحی ہوئی ہے کہ میں اس سے تمھیں ڈراؤ ں (ف۴۶) اورجن جن کو پہنچے (ف۴۷) تو کیا تم (ف۴۸)یہ گواہی دیتے ہو کہ اللہ کے ساتھ اور خدا ہیں، تم فرماؤ (ف۴۹) کہ میں یہ گواہی نہیں دیتا (ف۵۰) تم فرماؤ کہ وہ تو ایک ہی معبود ہے (ف۵۱) اور میں بیزار ہوں ان سے جن کو تم شریک ٹھہراتے ہو(ف۵۲)'),
 (93,6,20,'جن کو ہم نے کتاب دی (ف۵۳) اس نبی کو پہچانتے ہیں (ف۵۴) جیسا اپنے بیٹے کو پہچانتے ہیں (ف۵۵) جنہوں نے اپنی جان نقصان میں ڈالی وہ ایمان نہیں لاتے،'),
 (93,6,21,'اور اس سے بڑھ کر ظالم کون جو اللہ پر جھوٹ باندھے (ف۵۶) یا اس کی آیتیں جھٹلائے، بیشک ظالم فلاح نہ پائیں گے،'),
 (93,6,22,'اور جس دن ہم سب کو اٹھائیں گے پھر مشرکوں سے فرمائیں گے کہاں ہیں تمہارے وہ شریک جن کا تم دعویٰ کرتے تھے،'),
 (93,6,23,'پھر ان کی کچھ بناوٹ نہ رہی (ف۵۷) مگر یہ کہ بولے ہمیں اپنے رب اللہ کی قسم کہ ہم مشرک نہ تھے،'),
 (93,6,24,'دیکھو کیسا جھوٹ باندھا خود اپنے اوپر (ف۵۸) اور گم گئیں ان سے جو باتیں بناتے تھے،'),
 (93,6,25,'اور ان میں کوئی وہ ہے جو تمہاری طرف کان لگاتا ہے (ف۵۹) اور ہم نے ان کے دلوں پر غلاف کردیے ہیں کہ اسے نہ سمجھیں اور ان کے کانٹ میں ٹینٹ (روئی) اور اگر ساری نشانیاں دیکھیں تو ان پر ایمان نہ لائیں گے یہاں تک کہ جب تمہارے حضور تم سے جھگڑتے حاضر ہوں تو کافر کہیں یہ تو نہیں مگر اگلوں کی داستانیں (ف۶۰)'),
 (93,6,26,'اور وہ اس سے روکتے (ف۶۱) اور اس سے دور بھاگتے ہیں اور بلاک نہیں کرتے مگر اپنی جانیں (ف۶۲) اور انہیں شعور نہیں،'),
 (93,6,27,'اور کبھی تم دیکھو جب وہ آگ پر کھڑے کئے جائیں گے تو کہیں گے کاش کسی طرح ہم واپس بھیجے جائیں (ف۶۳) اور اپنے رب کی آیتیں نہ جھٹلائیں اور مسلمان ہوجائیں،'),
 (93,6,28,'بلکہ ان پر کھل گیا جو پہلے چھپاتے تھے (ف۶۴) اور اگر واپس بھیجے جائیں تو پھر وہی کریں جس سے منع کیے گئے تھے اور بیشک وہ ضرور جھوٹے ہیں،'),
 (93,6,29,'اور بولے (ف۶۵) وہ تو یہی ہماری دنیا کی زندگی ہے اور ہمیں اٹھنا نہیں(ف۶۶)'),
 (93,6,30,'اور کبھی تم دیکھو جب اپنے رب کے حضور کھڑے کیے جائیں گے، فرمائے گا کیا یہ حق نہیں (ف۶۷) کہیں گے کیوں نہیں، ہمیں اپنے رب کی قسم، فرمائے گا تو اب عذاب چکھو بدلہ اپنے کفر کا،'),
 (93,6,31,'بیشک ہار میں رہے وہ جنہوں نے اپنے رب سے ملنے کا انکار کیا، یہاں تک کہ جب ان پر قیامت اچانک آگئی بولے ہائے افسوس ہمارا اس پر کہ اس کے ماننے میں ہم نے تقصیر کی، اور وہ اپنے (ف۶۸) بوجھ اپنی پیٹھ پر لادے ہوئے ہیں ارے کتنا برُا بوجھ اٹھائے ہوئے ہیں (ف۶۹)'),
 (93,6,32,'اور دنیا کی زندگی نہیں مگر کھیل کود (ف۷۰) اور بیشک پچھلا گھر بھلا ان کے لئے جو ڈرتے ہیں (ف۷۱) تو کیا تمہیں سمجھ نہیں،'),
 (93,6,33,'ہمیں معلوم ہے کہ تمہیں رنج دیتی ہے وہ بات جو یہ کہہ رہے ہیں (ف۷۲) تو وہ تمہیں نہیں جھٹلاتے (ف۷۳) بلکہ ظالم اللہ کی آیتوں سے انکار کرتے ہیں (ف۷۴)'),
 (93,6,34,'اور تم سے پہلے رسول جھٹلائے گئے تو انہوں نے صبر کیا اس جھٹلانے اور ایذائیں پانے پر یہاں تک کہ انہیں ہماری مدد آئی (ف۷۵) اور اللہ کی باتیں بدلنے والا کوئی نہیں (ف۷۶) اور تمہارے پاس رسولوں کی خبریں آ ہی چکیں ہیں(ف۷۷)'),
 (93,6,35,'اور اگر ان کا منہ پھیرنا تم پر شاق گزرا ہے (ف۷۸) تو اگر تم سے ہوسکے تو زمین میں کوئی سرنگ تلاش کرلو یا آسمان میں زینہ پھر ان کے لیے نشانی لے آؤ (ف۷۹) اور اللہ چاہتا تو انہیں ہدایت پر اکٹھا کردیتا تو اے سننے والے تو ہرگز نادان نہ بن،'),
 (93,6,36,'مانتے تو وہی ہیں جو سنتے ہیں (ف۸۰) اور ان مردہ دلوں (ف۸۱) کو اللہ اٹھائے گا(ف۸۲) پھر اس کی طرف ہانکے جائیں گے(ف۸۳)'),
 (93,6,37,'اور بولے (ف۸۴) ان پر کوئی نشانی کیوں نہ اتری ان کے رب کی طرف سے (ف۸۵) تم فرماؤ کہ اللہ قادر ہے کہ کوئی نشانی اتارے لیکن ان میں بہت نرے (بالکل) جاہل ہیں(ف۸۶)'),
 (93,6,38,'اور نہیں کوئی زمین میں چلنے والا اور نہ کوئی پرند کہ اپنے پروں پر اڑتا ہے مگر تم جیسی اُمتیں (ف۸۷) ہم نے اس کتاب میں کچھ اٹھا نہ رکھا (ف۸۸) پھر اپنے رب کی طرف اٹھائے جائیں گے (ف۸۹)'),
 (93,6,39,'اور جنہوں نے ہماری آیتیں جھٹلائیں بہرے اور گونگے ہیں (ف۹۰) اندھیروں میں (ف۹۱) اللہ جسے چاہے گمراہ کرے اور جسے چاہے سیدھے راستہ ڈال دے(ف۹۲)'),
 (93,6,40,'تم فرماؤ بھلا بتاؤ تو اگر تم پر اللہ کا عذاب آئے یا قیامت قائم ہو کیا اللہ کے سوا کسی اور کو پکارو گے (ف۹۳) اگر سچے ہو (ف۹۴)'),
 (93,6,41,'بلکہ اسی کو پکارو گے تو وہ اگر چاہے (ف۹۵) جس پر اسے پکارتے ہو اسے اٹھالے اور شریکوں کو بھول جاؤ گے (ف۹۶)'),
 (93,6,42,'اور بیشک ہم نے تم سے پہلی اُمتوں کی طرف رسول بھیجے تو انہیں سختی اور تکلیف سے پکڑا (ف۹۷) کہ وہ کسی طرح گڑگڑائیں(ف۹۸)'),
 (93,6,43,'تو کیوں نہ ہوا کہ جب ان پر ہمارا عذاب آیا تو گڑگڑائے ہوتے لیکن ان کے دل تو سخت ہوگئے (ف۹۹) اور شیطان نے ان کے کام ان کی نگاہ میں بھلے کر دکھائے،'),
 (93,6,44,'پھر جب انہوں نے بھلا دیا جو نصیحتیں ان کو کی گئیں تھیں (ف۱۰۰) ہم نے ان پر ہر چیز کے دروازے کھول دیے (ف۱۰۱) یہاں تک کہ جب خوش ہوئے اس پر جو انہیں ملا (ف۱۰۲) تو ہم نے اچانک انہیں پکڑلیا (ف۱۰۳) اب وہ آس ٹوٹے رہ گئے،'),
 (93,6,45,'تو جڑ کاٹ دی گئی ظالموں کی (ف۱۰۴) اور سب خوبیاں سراہا اللہ رب سارے جہاں کا(ف۱۰۵)'),
 (93,6,46,'تم فرماؤ بھلا بتاؤ تو اگر اللہ تمہارے کان آنکھ لے لے اور تمہارے دلوں پر مہر کردے (ف۱۰۶) تو اللہ سوا کون خدا ہے کہ تمہیں یہ چیزیں لادے (ف۱۰۷) دیکھو ہم کس کس رنگ سے آیتیں بیان کرتے ہیں پھر وہ منہ پھیر لیتے ہیں،'),
 (93,6,47,'تم فرماؤ بھلا بتاؤ تو اگر تم پر اللہ کا عذاب آئے اچانک (ف۱۰۸) یا کھلم کھلا (ف۱۰۹) تو کون تباہ ہوگا سوا ظالموں کے (ف۱۱۰)'),
 (93,6,48,'اور ہم نہیں بھیجتے رسولوں کو مگر خوشی اور ڈر سناتے (ف۱۱۱) تو جو ایمان لائے اور سنورے (ف۱۱۲) ان کو نہ کچھ اندیشہ نہ کچھ غم،'),
 (93,6,49,'اور جنہوں نے ہماری آیتیں جھٹلائیں انہیں عذاب پہنچے گا بدلہ ان کی بے حکمی کا،'),
 (93,6,50,'تم فرمادو میں تم سے نہیں کہتا میرے پاس اللہ کے خزانے ہیں اور نہ یہ کہوں کہ میں آپ غیب جان لیتا ہوں اور نہ تم سے یہ کہوں کہ میں فرشتہ ہوں (ف۱۱۳) میں تو اسی کا تا بع ہوں جو مجھے وحی آتی ہے (ف۱۱۴) تم فر ماؤ کیا برابر ہو جائیں گے اندھے اور انکھیا رے (ف۱۱۵) تو کیا تم غور نہیں کرتے،'),
 (93,6,51,'اور اس قرآن سے انہیں ڈراؤ جنہیں خوف ہو کہ اپنے رب کی طرف یوں اٹھائے جائیں کہ اللہ کے سوا نہ ان کا کوئی حمایتی ہو نہ کوئی سفارشی اس امید پر کہ وہ پرہیزگار ہوجائیں'),
 (93,6,52,'اور دور نہ کرو انہیں جو اپنے رب کو پکارتے ہیں صبح اور شام اس کی رضا چاہتے (ف۱۱۶) تم پر ان کے حساب سے کچھ نہیں اور ان پر تمہارے حساب سے کچھ نہیں (ف۱۱۷) پھر انہیں تم دور کرو تو یہ کام انصاف سے بعید ہے'),
 (93,6,53,'اور یونہی ہم نے ان میں ایک دوسرے کے لئے فتنہ بنایا کہ مالدار کافر محتاج مسلمانوں کو دیکھ کر (ف۱۱۸) کہیں کیا یہ ہیں جن پر اللہ نے احسان کیا ہم میں سے (ف۱۱۹)کیا اللہ خوب نہیں جانتا حق ماننے والوں کو،'),
 (93,6,54,'اور جب تمہارے حضور وہ حاضر ہوں جو ہماری آیتوں پر ایمان لاتے ہیں تو ان سے فرماؤ تم پر سلام تمہارے رب نے اپنے ذمہ کرم پر رحمت لازم کرلی ہے (ف۱۲۰) کہ تم میں جو کوئی نادانی سے کچھ برائی کر بیٹھے پھر اس کے بعد توبہ کرے اور سنور جائے تو بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,6,55,'اور اسی طرح ہم آیتوں کو مفصل بیان فرماتے ہیں (ف۱۲۱) اور اس لیے کہ مجرموں کا راستہ ظاہر ہوجائے (ف۱۲۲)'),
 (93,6,56,'تم فرماؤ مجھے منع کیا گیا ہے کہ انہیں پوجوں جن کو تم اللہ کے سوا پوجتے ہو (ف۱۲۳) تم فرماؤ میں تمہاری خواہشوں پر نہیں چلتا (ف۱۲۴) یوں ہو تو میں بہک جاؤں اور راہ پر نہ رہوں،'),
 (93,6,57,'تم فرماؤ میں تو اپنے رب کی طرف سے روشن دلیل پر ہوں (ف۱۲۵) اور تم اسے جھٹلاتے ہو میرے پاس نہیں جس کی تم جلدی مچارہے ہو (ف۱۲۶) حکم نہیں مگر اللہ کا وہ حق فرماتا ہے اور وہ سب سے بہتر فیصلہ کرنے والا،'),
 (93,6,58,'تم فرماؤ اگر میرے پاس ہوتی وہ چیز جس کی تم جلدی کررہے ہو (ف۱۲۷) تو مجھ میں تم میں کام ختم ہوچکا ہوتا (ف۱۲۸) اور اللہ خوب جانتا ہے ستمگاروں کو،'),
 (93,6,59,'اور اسی کے پاس ہیں کنجیاں غیب کی انہیں وہی جانتا ہے (ف۱۲۹) اور جانتا ہے جو کچھ خشکی اور تری میں ہے، اور جو پتّا گرتا ہے وہ اسے جانتا ہے اور کوئی دانہ نہیں زمین کی اندھیریوں میں اور نہ کوئی تر اور نہ خشک جو ایک روشن کتاب میں لکھا نہ ہو(ف۱۳۰)'),
 (93,6,60,'اور وہی ہے جو رات کو تمہاری روحیں قبض کرتا ہے (ف۱۳۱) اور جانتا ہے جو کچھ دن میں کماؤ پھر تمہیں دن میں اٹھاتا ہے کہ ٹھہرائی ہوئی میعاد پوری ہو (ف۱۳۲) پھر اسی کی طرف پھرنا ہے (ف۱۳۳) پھر وہ بتادے گا جو کچھ تم کرتے تھے،'),
 (93,6,61,'اور وہی غالب ہے اپنے بندوں پر اور تم پر نگہبان بھیجتا ہے (ف۱۳۴) یہاں تک کہ جب تم میں کسی کو موت آتی ہے ہمارے فرشتے اس کی روح قبض کرتے ہیں (ف۱۳۵) اور وہ قصور نہیں کرتے(ف۱۳۶)'),
 (93,6,62,'پھر پھیرے جاتے ہیں اپنے سچے مولیٰ اللہ کی طرف سنتا ہے اسی کا حکم (ف۱۳۷) اور وہ سب سے جلد حساب کرنے والا (ف۱۳۸)'),
 (93,6,63,'تم فرماؤ وہ کون ہے جو تمہیں نجات دیتا ہے جنگل اور دریا کی آفتوں سے جسے پکارتے ہو گِڑ گِڑا کر اور آہستہ کہ اگر وہ ہمیں اس سے بچاوے تو ہم ضرور احسان مانیں گے(ف۱۳۹)'),
 (93,6,64,'تم فرماؤ اللہ تمہیں نجات دیتا ہے اس سے اور ہر بے چینی سے پھر تم شریک ٹھہراتے ہو(ف۱۴۰)'),
 (93,6,65,'تم فرماؤ وہ قادر ہے کہ تم پر عذاب بھیجے تمہارے اوپر سے یا تمہارے پاؤں کے تلے (نیچے) سے یا تمہیں بھڑا دے مختلف گروہ کرکے اور ایک کو دوسرے کی سختی چکھائے، دیکھو ہم کیونکر طرح طرح سے آیتیں بیان کرتے ہیں کہ کہیں ان کو سمجھ ہو(ف۱۴۱)'),
 (93,6,66,'اور اسے (ف۱۴۲) جھٹلایا تمہاری قوم نے اور یہی حق ہے، تم فرماؤ میں تم پر کچھ کڑوڑا (حاکمِ اعلیٰ) نہیں (ف۱۴۳)'),
 (93,6,67,'ہر چیز کا ایک وقت مقرر ہے (ف۱۴۴) اور عنقریب جان جاؤ گے'),
 (93,6,68,'اور اے سننے والے! جب تو انہیں دیکھے جو ہماری آیتوں میں پڑتے ہیں (ف۱۴۵) تو ان سے منہ پھیر لے (ف۱۴۶) جب تک اور بات میں پڑیں، اور جو کہیں تجھے شیطان بھلاوے تو یاد آئے پر ظالموں کے پاس نہ بیٹھ،'),
 (93,6,69,'اور پرہیز گاروں پر ان کے حساب سے کچھ نہیں (ف۱۴۷) ہاں نصیحت دینا شاید وہ باز آئیں (ف۱۴۸)'),
 (93,6,70,'اور چھوڑ دے ان کو جنہوں نے اپنا دین ہنسی کھیل بنا لیا اور انہیں دنیا کی زندگانی نے فریب دیا اور قرآن سے نصیحت دو (ف۱۴۹) کہ کہیں کوئی جان اپنے کئے پر پکڑی نہ جائے اللہ کے سوا نہ اس کا کوئی حمایتی ہو نہ سفارشی اور اگر اپنے عوض سارے بدلے دے تو اس سے نہ لیے جائیں یہ ہیں (ف۱۵۱) وہ جو اپنے کیے پر پکڑے گئے انہیں پینے کا کھولتا پانی اور درد ناک عذاب بدلہ ان کے کفر کا،'),
 (93,6,71,'تم فرماؤ (ف۱۵۲) کیا ہم اللہ کے سوا اس کو پوجیں جو ہمارا نہ بھلا کرے نہ برُا (ف۱۵۳) اور الٹے پاؤں پلٹا دیے جائیں بعد اس کے کہ اللہ نے ہمیں راہ دکھائی (ف۱۵۴) اس کی طرح جسے شیطان نے زمین میں راہ بھلادی (ف۱۵۵) حیران ہے اس کے رفیق اسے راہ کی طرف بلا رہے ہیں کہ ادھر آ، تم فرماؤ کہ اللہ ہی کی ہدایت ہدایت ہے (ف۱۵۶) اور ہمیں حکم ہے کہ ہم اس کے لیے گردن رکھ دیں (ف۱۵۷) جو رب ہے سارے جہان'),
 (93,6,72,'اور یہ کہ نماز قائم رکھو اور اس سے ڈرو، اور وہی ہے جس کی طرف اٹھنا ہے،'),
 (93,6,73,'اور وہی ہے جس نے آسمان و زمین ٹھیک بنائے (ف۱۵۸) اور جس دن فنا ہوئی ہر چیز کو کہے گا ہو جا وہ فوراً ہوجائے گی، اس کی بات سچی ہے، اور اسی کی سلطنت ہے جس دن صور پھونکا جائے گا (ف۱۵۹) ہر چھپے اور ظاہر کو جاننے والا، اور وہی حکمت والا خبردار،'),
 (93,6,74,'اور یاد کرو جب ابراہیم نے اپنے باپ (ف۱۶۰) آزر سے کہا، کیا تم بتوں کو خدا بناتے ہو، بیشک میں تمہیں اور تمہاری قوم کو کھلی گمراہی میں پاتا ہوں(ف۱۶۱)'),
 (93,6,75,'اور اسی طرح ہم ابراہیم کو دکھاتے ہیں ساری بادشاہی آسمانوں اور زمین کی (ف۱۶۲) اور اس لیے کہ وہ عین الیقین والوں میں ہوجائے (ف۱۶۳)'),
 (93,6,76,'پھر جب ان پر رات کا اندھیرا آیا ایک تارا دیکھا (ف۱۶۴) بولے اسے میرا رب ٹھہراتے ہو پھر جب وہ ڈوب گیا بولے مجھے خوش نہیں آتے ڈوبنے والے،'),
 (93,6,77,'پھر جب چاند چمکتا دیکھا بولے اسے میرا رب بتاتے ہو پھر جب وہ ڈوب گیا کہا اگر مجھے میرا رب ہدایت نہ کرتا تو میں بھی انہیں گمراہوں میں ہوتا(ف۱۶۵)'),
 (93,6,78,'پھر جب سورج جگمگاتا دیکھا بولے اسے میرا رب کہتے ہو (ف۱۶۶) یہ تو ان سب سے بڑا ہے، پھر جب وہ ڈوب گیا کہا اے قوم میں بیزار ہوں ان چیزوں سے جنہیں تم شریک ٹھہراتے ہو (ف۱۶۷)'),
 (93,6,79,'میں نے اپنا منہ اس کی طرف کیا جس نے آسمان اور زمین بنائے ایک اسی کا ہوکر (ف۱۶۸) اور میں مشرکین میں نہیں،'),
 (93,6,80,'اور ان کی قوم ان سے جھگڑے لگی کہا کیا اللہ کے بارے میں مجھ سے جھگڑتے ہو تو وہ مجھے راہ بتا چکا (ف۱۶۹) اور مجھے ان کا ڈر نہیں جنہیں تم شریک بتاتے ہو (ف۱۷۰) ہاں جو میرا ہی رب کوئی بات چاہے (ف۱۷۱) میرے رب کا علم ہر چیز کو محیط ہے، تو کیا تم نصیحت نہیں مانتے'),
 (93,6,81,'اور میں تمہارے شریکوں سے کیونکر ڈروں (ف۱۷۲) اور تم نہیں ڈرتے کہ تم نے اللہ کا شریک اس کو ٹھہرایا جس کی تم پر اس نے کوئی سند نہ اتاری، تو دونوں گروہوں میں امان کا زیادہ سزا وار کون ہے (ف۱۷۳) اگر تم جانتے ہو،'),
 (93,6,82,'وہ جو ایمان لائے اور اپنے ایمان میں کسی ناحق کی آمیزش نہ کی انہیں کے لیے امان ہے اور وہی راہ پر ہیں،'),
 (93,6,83,'اور یہ ہماری دلیل ہے کہ ہم نے ابراہیم کو اس کی قوم پر عطا فرمائی، ہم جسے چاہیں درجوں بلند کریں (ف۱۷۴) بیشک تمہارا رب علم و حکمت والا ہے'),
 (93,6,84,'اور ہم نے انہیں اسحاق اور یعقوب عطا کیے، ان سب کو ہم نے راہ دکھائی اور ان سے پہلے نوح کو راہ دکھائی اور میں اس کی اولاد میں سے داؤد اور سلیمان اور ایوب اور یوسف اور موسیٰ اور ہارون کو، اور ہم ایسا ہی بدلہ دیتے ہیں نیکوکاروں کو،'),
 (93,6,85,'اور زکریا اور یحییٰ اور عیسیٰ اور الیاس کو یہ سب ہمارے قرب کے لائق ہیں'),
 (93,6,86,'اور اسماعیل اور یسع اور یونس اور لوط کو، اور ہم نے ہر ایک کو اس کے وقت میں سب پر فضیلت دی (ف۱۷۵)'),
 (93,6,87,'اور کچھ ان کے باپ دادا اور اولاد اور بھائیوں میں سے بعض کو (ف۱۷۶) اور ہم نے انہیں چن لیا اور سیدھی راہ دکھائی،'),
 (93,6,88,'یہ اللہ کی ہدایت ہے کہ اپنے بندوں میں جسے چاہے دے، اور اگر وہ شرک کرتے تو ضرور ان کا کیا اکارت جاتا،'),
 (93,6,89,'یہ ہیں جن کو ہم نے کتاب اور حکم اور نبوت عطا کی تو اگر یہ لوگ (ف۱۷۷) اس سے منکر ہوں تو ہم نے اس کیلئے ایک ایسی قوم لگا رکھی ہے جو انکار والی نہیں(ف۱۷۸)'),
 (93,6,90,'یہ ہیں جن کو اللہ نے ہدایت کی تو تم انہیں کی راہ چلو (ف۱۷۹) تم فرماؤ میں قرآن پر تم سے کوئی اجرت نہیں مانگتا وہ تو نہیں مگر نصیحت سارے جہان کو(ف۱۸۰)'),
 (93,6,91,'اور یہود نے اللہ کی قدر نہ جانی جیسی چاہیے تھی (ف۱۸۱) جب بولے ا لله نے کسی آدمی پر کچھ نہیں اتارا، تم فرماؤ کس نے اُتاری وہ کتاب جو موسیٰ لائے تھے روشنی اور لوگوں کے لیے ہدایت جس کے تم نے الگ الگ کاغذ بنالیے ظاہر کرتے ہو (ف۱۸۲) اور بہت سے چھپالیتے ہو (ف۱۸۳) اور تمہیں وہ سکھایا جاتا ہے (ف۱۸۴) جو نہ تم کو معلوم تھا نہ تمہارے باپ دادا کو، اللہ کہو (ف۱۸۵) پھر انہیں چھوڑ دو ان کی بیہودگی میں انہیں کھیلتا(ف۱۸۶)'),
 (93,6,92,'اور یہ ہے برکت والی کتاب کہ ہم نے اُتاری (ف۱۸۷) تصدیق فرماتی ان کتابوں کی جو آگے تھیں اور اس لیے کہ تم ڈر سناؤ سب بستیوں کے سردار کو (ف۱۸۸) اور جو کوئی سارے جہاں میں اس کے گرد ہیں اور جو آخرت پر ایمان لاتے ہیں (ف۱۸۹) اس کتاب پر ایمان لاتے ہیں اور اپنی نماز کی حفاظت کرتے ہیں،'),
 (93,6,93,'اور اس سے بڑھ کر ظالم کون جو اللہ پر جھوٹ باندھے (ف۱۹۰) یا کہے مجھے وحی ہوئی اور اسے کچھ وحی نہ ہوئی (ف۱۹۱) اور جو کہے ابھی میں اُتارتا ہوں ایسا جیسا اللہ نے اُتارا (ف۱۹۲) اور کبھی تم دیکھوں جس وقت ظالم موت کی سختیوں میں ہیں اور فرشتے ہاتھ پھیلاتے ہوئے ہیں (ف۱۹۳) کہ نکالو اپنی جانیں، آج تمہیں خواری کا عذاب دیا جائے گا بدلہ اس کا کہ اللہ پر جھوٹ لگاتے تھے (ف۱۹۴) اور اس کی آیتوں سے تکبر کرتے،'),
 (93,6,94,'اور بیشک تم ہمارے پاس اکیلے آئے جیسا ہم نے تمہیں پہلی بار پیدا کیا تھا (ف۱۹۵) اور پیٹھ پیچھے چھوڑ آئے جو مال و متاع ہم نے تمہیں دیا تھا اور ہم تمہارے ساتھ تمہارے ان سفارشیوں کو نہیں دیکھتے جن کا تم اپنے میں ساجھا بتاتے تھے (ف۱۹۶) بیشک تمہارے آپس کی ڈور کٹ گئی (ف۱۹۷) اور تم سے گئے جو دعوے کرتے تھے (ف۱۹۸)'),
 (93,6,95,'بیشک اللہ دانے اور گٹھلی کو چیر نے والا ہے (ف۱۹۹) زندہ کو مردہ سے نکالنے (ف۲۰۰) اور مردہ کو زندہ سے نکالنے والا (ف۲۰۱) یہ ہے اللہ تم کہاں اوندھے جاتے ہو (ف۲۰۲)'),
 (93,6,96,'تاریکی چاک کرکے صبح نکالنے والا اور اس نے رات کو چین بنایا (ف۲۰۳) اور سورج اور چاند کو حساب (ف۲۰۴) یہ سادھا (سدھایا ہوا) ہے زبردست جاننے والے کا،'),
 (93,6,97,'اور وہی ہے جس نے تمہارے لیے تارے بنائے کہ ان سے راہ پاؤ خشکی اور تری کے اندھیروں میں، ہم نے نشانیاں مفصل بیان کردیں علم والوں کے لیے،'),
 (93,6,98,'اور وہی ہے جس نے تم کو ایک جان سے پیدا کیا (ف۲۰۵) پھر کہیں تمہیں ٹھہرنا ہے (ف۲۰۶) اور کہیں امانت رہنا (ف۲۰۷) بیشک ہم نے مفصل آیتیں بیان کردیں سمجھ والوں کے لیے،'),
 (93,6,99,'اور وہی ہے جس نے آسمان سے پانی اُتارا، تو ہم نے اس سے ہر اُگنے والی چیز نکالی (ف۲۰۸) تو ہم نے اس سے نکالی سبزی جس میں سے دانے نکالتے ہیں ایک دوسرے پر چڑھے ہوئے اور کھجور کے گابھے سے پاس پاس گچھے اور انگور کے باغ اور زیتون اور انار کسی بات میں ملتے اور کسی بات میں الگ، اس کا پھل دیکھو جب پھلے اور اس کا پکنا بیشک اس میں نشانیاں ہیں ایمان والوں کے لیے،'),
 (93,6,100,'اور (ف۲۰۹) اللہ کا شریک ٹھہرایا جنوں کو (ف۲۱۰) حالانکہ اسی نے ان کو بنایا اور اس کے لیے بیٹے اور بیٹیاں گڑھ لیں جہالت سے، پاکی اور برتری ہے اس کو ان کی باتوں سے،'),
 (93,6,101,'بے کسی نمو نہ کے آسمانوں اور زمین کا بنانے والا، اسکے بچہ کہاں سے ہو حالانکہ اس کی عورت نہیں (ف۲۱۱) اور اس نے ہر چیز پیدا کی (ف۲۱۲) اور وہ سب کچھ جانتا ہے،'),
 (93,6,102,'یہ ہے اللہ تمہارا رب (ف۲۱۳) اور اس کے سوا کسی کی بندگی نہیں ہر چیز کا بنانے والا تو اسے پوجو وہ ہر چیز پر نگہبان ہے(ف۲۱۴)'),
 (93,6,103,'آنکھیں اسے احاطہ نہیں کرتیں (ف۲۱۵) اور سب آنکھیں اس کے احاطہ میں ہیں اور وہی ہے پورا باطن پورا خبردار،'),
 (93,6,104,'تمہارے پاس آنکھیں کھولنے والی دلیلیں آئیں تمہارے رب کی طرف سے تو جس نے دیکھا تو اپنے بھلے کو اور جو اندھا ہوا اپنے برُے کو، اور میں تم پر نگہبان نہیں،'),
 (93,6,105,'اور ہم اسی طرح آیتیں طرح طرح سے بیان کرتے (ف۲۱۶) اور اس لیے کہ کافر بول اٹھیں کہ تم تو پڑھے ہو اور اس لیے کہ اسے علم والوں پر واضح کردیں،'),
 (93,6,106,'اس پر چلو جو تمہیں تمہارے رب کی طرف سے وحی ہوتی ہے (ف۲۱۷) اس کے سوا کوئی معبود نہیں اور مشرکوں سے منہ پھیر لو'),
 (93,6,107,'اور اللہ چاہتا تو وہ شرک نہیں کرتے، اور ہم نے تمہیں ان پر نگہبان نہیں کیا اور تم ان پر کڑوڑے (حاکمِ اعلیٰ) نہیں،'),
 (93,6,108,'اور انہیں گالی نہ دو وہ جن کو وہ اللہ کے سوا پوجتے ہیں کہ وہ اللہ کی شان میں بے ادبی کریں گے زیادتی اور جہالت سے (ف۲۱۸) یونہی ہم نے ہر اُمت کی نگاہ میں اس کے عمل بھلے کردیے ہیں پھر انہیں اپنے رب کی طرف پھرنا ہے اور وہ انہیں بتادے گا جو کرتے تھے،'),
 (93,6,109,'اور انہوں نے اللہ کی قسم کھائی اپنے حلف میں پوری کوشش سے کہ اگر ان کے پاس کوئی نشانی آئی تو ضرور اس پر ایمان لائیں گے، م فرما دو کہ نشانیاں تو اللہ کے پاس ہیں (ف۲۱۹) اور تمہیں (ف۲۲۰) کیا خبر کہ جب وہ آئیں تو یہ ایمان نہ لائینگے'),
 (93,6,110,'اور ہم پھیردیتے ہیں ان کے دلوں اور آنکھوں کو (ف۲۲۱) جیسا وہ پہلی بار ایمان نہ لائے تھے (ف۲۲۲) اور انہیں چھوڑ دیتے ہیں کہ اپنی سرکشی میں بھٹکا کریں،'),
 (93,6,111,'اور اگر ہم ان کی طرف فرشتے اُتارتے (ف۲۲۳) اور ان سے مردے باتیں کرتے اور ہم ہر چیز ان کے سامنے اٹھا لاتے جب بھی وہ ایمان لانے والے نہ تھے (ف۲۲۴) مگر یہ کہ خدا چاہتا (ف۲۲۵) و لیکن ان میں بہت نرے جاہل ہیں (ف۲۲۶)'),
 (93,6,112,'اور اسی طرح ہم نے ہر نبی کے دشمن کیے ہیں آدمیوں اور جنوں میں کے شیطان کہ ان میں ایک دوسرے پر خفیہ ڈالتا ہے بناوٹ کی بات (ف۲۲۷) دھوکے کو، اور تمہارا رب چاہتا تو وہ ایسا نہ کرتے (ف۲۲۸) تو انہیں ان کی بناوٹوں پر چھوڑ دو (ف۲۲۹)'),
 (93,6,113,'اور اس لیے کہ اس (ف۲۳۰) کی طرف ان کے دل جھکیں جنہیں آخرت پر ایمان نہیں اور اسے پسند کریں اور گناہ کمائیں جو انہیں کمانا ہے،'),
 (93,6,114,'تو کیا اللہ کے سوا میں کسی اور کا فیصلہ چاہوں اور وہی ہے جس نے تمہاری طرف مفصل کتاب اُتاری (ف۲۳۱) اور جنکو ہم نے کتاب دی وہ جانتے ہیں کہ یہ تیرے رب کی طرف سے سچ اترا ہے (ف۲۳۲) تو اے سننے والے تو ہر گز شک والوں میں نہ ہو،'),
 (93,6,115,'اور پوری ہے تیرے رب کی بات سچ اور انصاف میں اس کی باتوں کا کوئی بدلنے والا نہیں (ف۲۳۳) اور وہی ہے سنتا جانتا،'),
 (93,6,116,'اور اے سننے والے زمین میں اکثر وہ ہیں کہ تو ان کے کہے پر چلے تو تجھے اللہ کی راہ سے بہکا دیں، وہ صرف گمان کے پیچھے ہیں (ف۲۳۴) اور نری اٹکلیں (فضول اندازے) دوڑاتے ہیں (ف۲۳۵)'),
 (93,6,117,'تیرا رب خوب جانتا ہے کہ کون بہکا اس کی راہ سے اور وہ خوب جانتا ہے ہدایت والوں کو،'),
 (93,6,118,'تو کھاؤ اسمیں سے جس پر اللہ کا نام لیا گیا (ف۲۳۶) اگر تم اسکی آیتیں مانتے ہو،'),
 (93,6,119,'اور تمہیں کیا ہوا کہ اس میں سے نہ کھاؤ جس (ف۲۳۷) پر اللہ کا نام لیا گیا وہ تم سے مفصل بیان کرچکا جو کچھ تم پر حرام ہوا (ف۲۳۸) مگر جب تمہیں اس سے مجبوری ہو (ف۲۳۹) اور بیشک بہتیرے اپنی خواہشوں سے گمراہ کرتے ہیں بے جانے بیشک تیرا رب حد سے بڑھنے والوں کو خوب جانتا ہے،'),
 (93,6,120,'اور چھوڑ دو کھلا اور چھپا گناہ، وہ جو گناہ کماتے ہیں عنقریب اپنی کمائی کی سزا پائیں گے،'),
 (93,6,121,'اور اُسے نہ کھاؤ جس پر اللہ کا نام نہ لیا گیا (ف۲۴۰) اور وہ بیشک حکم عدولی ہے، اور بیشک شیطان اپنے دوستوں کے دلوں میں ڈالتے ہیں کہ تم سے جھگڑیں اور اگر تم ان کا کہنا مانو (ف۲۴۱) تو اس وقت تم مشرک ہو (ف۲۴۲)'),
 (93,6,122,'اور کیا وہ کہ مردہ تھا تو ہم نے اسے زندہ کیا (ف۲۴۳) اور اس کے لیے ایک نور کردیا (ف۲۴۴) جس سے لوگوں میں چلتا ہے (ف۲۴۵) وہ اس جیسا ہوجائے گا جو اندھیریوں میں ہے (ف۲۴۶) ان سے نکلنے والا نہیں، یونہی کافروں کی آنکھ میں ان کے اعمال بھلے کردیے گئے ہیں،'),
 (93,6,123,'اور اسی طرح ہم نے ہر بستی میں اس کے مجرموں کے سرغنہ کیے کہ اس میں داؤ کھیلیں (ف۲۴۷) اور داؤں نہیں کھیلتے مگر اپنی جانوں پر اور انہیں شعورنہیں(ف۲۴۸)'),
 (93,6,124,'اور جب ان کے پاس کوئی نشانی آئے تو کہتے ہی ہم ہر گز ایمان نہ لائیں گے جب تک ہمیں بھی ویسا ہی نہ ملے جیسا اللہ کے رسولوں کو ملا (ف۲۴۹) اللہ خوب جانتا ہے جہاں اپنی رسالت رکھے (ف۲۵۰) عنقریب مجرموں کو اللہ کے یہاں ذلت پہنچے گی اور سخت عذاب بدلہ ان کے مکر کا،'),
 (93,6,125,'اور جسے اللہ راہ دکھانا چاہے اس کا سینہ اسلام کے لیے کھول دیتا ہے (ف۲۵۱) اور جسے گمراہ کرنا چاہے اس کا سینہ تنگ خوب رکا ہوا کر دیتا ہے (ف۲۵۲) گویا کسی کی زبردستی سے آسمان پر چڑھ رہا ہے، اللہ یونہی عذاب ڈالتا ہے ایمان نہ لانے والوں کو،'),
 (93,6,126,'اور یہ (ف۲۵۳) تمہارے رب کی سیدھی راہ ہے ہم نے آیتیں مفصل بیان کردیں نصیحت ماننے والوں کے لیے،'),
 (93,6,127,'ان کے لیے سلامتی کا گھر ہے اپنے رب کے یہاں اور وہ ان کا مولیٰ ہے یہ ان کے کاموں کا پھل ہے،'),
 (93,6,128,'اور جس دن اُن سب کو اٹھانے گا اور فرمائے گا، اے جن کے گروہ! تم نے بہت آدمی گھیرلیے (ف۲۵۴) اور ان کے دوست آدمی عرض کریں گے اے ہمارے رب! ہم میں ایک نے دوسرے سے فائدہ اٹھایا (ف۲۵۵) اور ہم اپنی اس میعاد کو پہنچ گئے جو تو نے ہمارے لیے مقرر فرمائی تھی (ف۲۵۶) فرمائے گا آگ تمہارا ٹھکانا ہے ہمیشہ اس میں رہو مگر جسے خدا چاہے (ف۲۵۷) اے محبوب! بیشک تمہارا رب حکمت والا علم والا ہے،'),
 (93,6,129,'اور یونہی ہم ظالموں میں ایک کو دوسرے پر مسلط کرتے ہیں بدلہ ان کے کیے کا(ف۲۵۸)'),
 (93,6,130,'اے جنوں اور آدمیوں کے گروہ! کیا تمہارے پاس تم میں کے رسول نہ آئے تھے تم پر میری آیتیں پڑھتے اور تمہیں یہ دن (ف۲۵۹) دیکھنے سے ڈراتے (ف۲۶۰) کہیں گے ہم نے اپنی جانوں پر گواہی دی (ف۲۶۱) اور انہیں دنیا کی زندگی نے فریب دیا اور خود اپنی جانوں پر گواہی دیں گے کہ وہ کافر تھے(ف۲۶۲)'),
 (93,6,131,'یہ (ف۲۶۳) اس لیے کہ تیرا رب بستیوں کو (ف۲۶۴) ظلم سے تباہ نہیں کرتا کہ ان کے لوگ بے خبر ہوں(ف۲۶۵)'),
 (93,6,132,'اور ہر ایک کے لیے (ف۲۶۶) ان کے کاموں سے درجے ہیں اور تیرا رب ان کے اعمال سے بے خبر نہیں،'),
 (93,6,133,'اور اے محبوب! تمہارا رب بے پروا ہے رحمت والا، اے لوگو! وہ چاہے تو تمہیں لے جائے (ف۲۶۷) اور جسے چاہے تمہاری جگہ لادے جیسے تمہیں اوروں کی اولاد سے پیدا کیا(ف۲۶۸)'),
 (93,6,134,'بیشک جس کا تمہیں وعدہ دیا جاتا ہے (ف۲۶۹) ضرور آنے والی ہے اور تم تھکا نہیں سکتے،'),
 (93,6,135,'تم فرماؤ اے میری قوم! تم اپنی جگہ پر کام کیے جاؤ میں اپنا کام کرتا ہوں تو اب جاننا چاہتے ہو کس کا رہتا ہے آحرت کا گھر، بیشک ظالم فلاح نہیں پاتے،'),
 (93,6,136,'اور (ف۲۷۰) اللہ نے جو کھیتی اور مویشی پیدا کیے ان میں اسے ایک حصہ دار ٹھہرایا تو بولے یہ اللہ کا ہے ان کے خیال میں اور یہ ہمارے شریکوں کا (ف۲۷۱) تو وہ جو ان کے شریکوں کا ہے وہ تو خدا کو نہیں پہنچتا، اور جو خدا کا ہے وہ ان کے شریکوں کو پہنچتا ہے، کیا ہی برا حکم لگاتے ہیں (ف۲۷۲)'),
 (93,6,137,'اور یوں ہی بہت مشرکوں کی نگاہ میں ان کے شریکوں نے اولاد کا قتل بھلا کر دکھایا ہے (ف۲۷۳) کہ انہیں ہلاک کریں اور ان کا دین اُن پر مشتبہ کردیں (ف۲۷۴) اور اللہ چاہتا تو ایسا نہ کرتے تو تم انہیں چھوڑ دو وہ ہیں اور ان کے افتراء،'),
 (93,6,138,'اور بولے (ف۲۷۵) یہ مویشی اور کھیتی روکی ہوئی (ف۲۷۶) ہے اسے وہی کھائے جسے ہم چاہیں اپنے جھوٹے خیال سے (ف۲۷۷) اور کچھ مویشی ہیں جن پر چڑھنا حرام ٹھہرایا (ف۲۷۸) اور کچھ مویشی کے ذبح پر اللہ کا نام نہیں لیتے (ف۲۷۹) یہ سب اللہ پر جھوٹ باندھنا ہے، عنقریب وہ انہیں بدلے دے گا ان کے افتراؤں کا،'),
 (93,6,139,'اور بولے جو ان مویشیوں کے پیٹ میں ہے وہ نرا (خالص) ہمارے مردوں کا ہے (ف۲۸۰) اور ہماری عورتوں پر حرام ہے، اور مرا ہوا نکلے تو وہ سب (ف۲۸۱) اس میں شریک ہیں، قریب ہے کہ اللہ انہیں اِن کی اُن باتوں کا بدلہ دے گا، بیشک وہ حکمت و علم والا ہے،'),
 (93,6,140,'بیشک تباہ ہوئے وہ جو اپنی اولاد کو قتل کرتے ہیں احمقانہ جہالت سے (ف۲۸۲) اور حرام ٹھہراتے ہیں وہ جو اللہ نے انہیں روزی دی (ف۲۸۳) اللہ پر جھوٹ باندھنے کو (ف۲۸۴) بیشک وہ بہکے اور راہ نہ پائی (ف۲۸۵)'),
 (93,6,141,'اور وہی ہے جس نے پیدا کیے باغ کچھ زمین پر چھئے (چھائے) ہوئے (ف۲۸۶) اور کچھ بے چھئے (پھیلے) اور کھجور اور کھیتی جس میں رنگ رنگ کے کھانے (ف۲۸۷) اور زیتون اور انار کسی بات میں ملتے (ف۲۸۸) اور کسی میں الگ (ف۲۸۹) کھاؤ اس کا پھل جب پھل لائے اور اس کا حق دو جس دن کٹے (ف۲۹۰) اور بے جا نہ خرچو (ف۲۹۱) بیشک بے جا خرچنے والے اسے پسند نہیں،'),
 (93,6,142,'اور مویشی میں سے کچھ بوجھ اٹھانے والے اور کچھ زمین پر بچھے (ف۲۹۲) کھاؤ اس میں سے جو اللہ نے تمہیں روزی دی اور شیطان کے قدموں پر نہ چلو، بیشک وہ تمہارا صریح دشمن ہے،'),
 (93,6,143,'آٹھ نر و مادہ ایک جوڑا بھیڑ کا اور ایک جوڑا بکری کا، تم فرماؤ کیا اس نے دونوں نر حرام کیے یا دونوں مادہ یا وہ جسے دنوں مادہ پیٹ میں لیے ہیں (ف۲۹۳) کسی علم سے بتاؤ اگر تم سچے ہو'),
 (93,6,144,'اور ایک جوڑا اونٹ کا اور ایک جوڑا گائے کا، تم فرماؤ کیا اس نے دونوں نر حرام کیے یا دونوں مادہ یا وہ جسے دونوں مادہ پیٹ میں لیے ہیں (ف۲۹۴) کیا تم موجود تھے جب اللہ نے تمہیں یہ حکم دیا (ف۲۹۵) تو اس سے بڑھ کر ظالم کون جو اللہ پر جھوٹ باندھے کہ لوگوں کو اپنی جہالت سے گمراہ کرے، بیشک اللہ ظالموں کو راہ نہیں دکھاتا،'),
 (93,6,145,'تم فرماؤ (ف۲۹۶) میں نہیں پاتا اس میں جو میری طرف وحی ہوئی کسی کھانے والے پر کوئی کھانا حرام (ف۲۹۷) مگر یہ کہ مردار ہو یا رگوں کا بہتا خون (ف۲۹۸) یا بد جانور کا گوشت وہ نجاست ہے یا وہ بے حکمی کا جانور جس کے ذبح میں غیر خدا کا نام پکارا گیا تو جو ناچار ہوا (ف۲۹۹) نہ یوں کہ آپ خواہش کرے اور نہ یوں کہ ضرورت سے بڑھے تو بے شیک اللہ بخشنے والا مہربان ہے (ف۳۰۰)'),
 (93,6,146,'اور یہودیوں پر ہم نے حرام کیا ہر ناخن والا جانور (ف۳۰۱) اور گائے اور بکری کی چربی ان پر حرام کی مگر جو ان کی پیٹھ میں لگی ہو یا آنت یا ہڈی سے ملی ہو، ہم نے یہ ان کی سرکشی کا بدلہ دیا (ف۳۰۲) اور بیشک ہم ضرور سچے ہیں،'),
 (93,6,147,'پھر اگر وہ تمہیں جھٹلائیں تو تم فرماؤ کہ تمہارا رب وسیع رحمت والا ہے (ف۳۰۳) اور اس کا عذاب مجرموں پر سے نہیں ٹالا جاتا (ف۳۰۴)'),
 (93,6,148,'اب کہیں گے مشرک کہ (ف۳۰۵) اللہ چاہتا تو نہ ہم شرک کرتے نہ ہمارے باپ دادا نہ ہم کچھ حرام ٹھہراتے (ف۳۰۶) ایسا ہی ان کے اگلوں نے جھٹلایا تھا یہاں تک کہ ہمارا عذاب چکھا (ف۳۰۷) تم فرماؤ کیا تمہارے پاس کوئی علم ہے کہ اسے ہمارے لیے نکالو، تم تو نرے گمان (خام خیال)کے پیچھے ہو اور تم یونہی تخمینے کرتے ہو (ف۳۰۸)'),
 (93,6,149,'تم فرماؤ تو اللہ ہی کی حجت پوری ہے (ف۳۰۹) تو وہ چاہتا تو سب کی ہدایت فرماتا،'),
 (93,6,150,'تم فرماؤ لاؤ اپنے وہ گواہ جو گواہی دیں کہ اللہ نے اسے حرام کیا (ف۳۱۰) پھر اگر وہ گواہی دے بیٹھیں (ف۳۱۱) تو تُو اے سننے والے! ان کے ساتھ گواہی نہ دینا اور ان کی خواہشوں کے پیچھے نہ چلنا جو ہماری آیتیں جھٹلاتے ہیں اور جو آخرت پر ایمان نہیں لاتے اور اپنے رب کا برابر والا ٹھہراتے ہیں(ف۳۱۲)'),
 (93,6,151,'تم فرماؤ آؤ میں تمہیں پڑھ کر سناؤں جو تم پر تمہارے رب نے حرام کیا (ف۳۱۳) یہ کہ اس کا کوئی شریک نہ کرو اور ماں باپ کے ساتھ بھلائی کرو (ف۳۱۴) اور اپنی اولاد قتل نہ کرو مفلسی کے باعث، ہم تمہیں اور انہیں سب کو رزق دیں گے (ف۲۱۵) اور بے حیائیوں کے پاس نہ جاؤ جو ان میں کھلی ہیں اور جو چھپی (ف۳۱۶) اور جس جان کی اللہ نے حرمت رکھی اسے ناحق نہ مارو (ف۳۱۷) یہ تمہیں حکم فرمایا ہے کہ تمہیں عقل ہو'),
 (93,6,152,'اور یتیموں کے مال کے پاس نہ جاؤ مگر بہت اچھے طریقہ سے (ف۳۱۸) جب تک وہ اپنی جوانی کو پہنچے (ف۳۱۹) اور ناپ اور تول انصاف کے ساتھ پوری کرو، ہم کسی جان پر بوجھ نہیں ڈالتے مگر اس کے مقدور بھر، اور جب بات کہو تو انصاف کی کہو اگرچہ تمہارے رشتہ دار کا معاملہ ہو اور اللہ ہی کا عہد پورا کرو، یہ تمہیں تاکید فرمائی کہ کہیں تم نصیحت مانو،'),
 (93,6,153,'اور یہ کہ (ف۳۲۰) یہ ہے میرا سیدھا راستہ تو اس پر چلو اور اور راہیں نہ چلو (ف۳۲۱) کہ تمہیں اس کی راہ سے جدا کردیں گی، یہ تمہیں حکم فرمایا کہ کہیں تمہیں پرہیزگاری ملے،'),
 (93,6,154,'پھر ہم نے موسیٰ کو کتاب عطا فرمائی (ف۳۲۲) پورا احسان کرنے کو اس پر جو نیکوکار ہے اور ہر چیز کی تفصیل اور ہدایت اور رحمت کہ کہیں وہ (ف۳۲۳) اپنے رب سے ملنے پر ایمان لائیں(ف۳۲۴)'),
 (93,6,155,'اور یہ برکت والی کتاب (ف۳۲۵) ہم نے اُتاری تو اس کی پیروی کرو اور پرہیزگاری کرو کہ تم پر رحم ہو،'),
 (93,6,156,'کبھی کہو کہ کتاب تو ہم سے پہلے دو گروہوں پر اُتری تھی (ف۳۲۶) اور ہمیں ان کے پڑھنے پڑھانے کی کچھ خبر نہ تھی(ف۳۲۷)'),
 (93,6,157,'یا کہو کہ اگر ہم پر کتاب اُترتی تو ہم ان سے زیادہ ٹھیک راہ پر ہوتے (ف۳۲۸) تو تمہارے پاس تمہارے رب کی روشن دلیل اور ہدایت او ر رحمت آئی (ف۳۲۹) تو اس سے زیادہ ظالم کون جو اللہ کی آیتوں کو جھٹلائے اور ان سے منہ پھیرے عنقریب وہ جو ہماری آیتوں سے منہ پھیرتے ہیں ہم انہیں بڑے عذاب کی سزا دیں گے بدلہ ان کے منہ پھیرنے کا،'),
 (93,6,158,'کاہے کے انتظار میں ہیں (ف۳۳۰) مگر یہ کہ آئیں ان کے پاس فرشتے (ف۳۳۱) یا تمہارے رب کا عذاب یا تمہارے رب کی ایک نشانی آئے (ف۳۳۲) جس دن تمہارے رب کی وہ ایک نشانی آئے گی کسی جان کو ایمان لانا کام نہ دے گا جو پہلے ایمان نہ لائی تھی یا اپنے ایمان میں کوئی بھلائی نہ کمائی تھی (ف۳۳۳) تم فرماؤ رستہ دیکھو (ف۳۳۴) ہم بھی دیکھتے ہیں،'),
 (93,6,159,'وہ جنہوں نے اپنے دین میں جُدا جُدا راہیں نکالیں او رکئی گروہ ہوگئے (ف۳۳۵) اے محبوب ! تمہیں ان سے کچھ علا قہ نہیں ان کا معاملہ اللہ ہی کے حوالے ہے پھر وہ انہیں بتادے گا جو کچھ وہ کرتے تھے(ف۳۳۶)'),
 (93,6,160,'جو ایک نیکی لائے تو اس کے لیے اس جیسی دس ہیں (ف۳۳۷) اور جو برائی لائے تو اسے بدلہ نہ ملے گا مگر اس کے برابر اور ان پر ظلم نہ ہوگا،'),
 (93,6,161,'تم فرماؤ بیشک مجھے میرے رب نے سیدھی راہ دکھائی (ف۳۳۸) ٹھیک دین ابراہیم کی ملّت جو ہر باطل سے جُدا تھے، اور مشرک نہ تھے(ف۳۳۹)'),
 (93,6,162,'تم فرماؤ بیشک میری نماز اور میری قربانیاں اور میرا جینا اور میرا مرنا سب اللہ کے لیے ہے جو رب سارے جہان کا'),
 (93,6,163,'اس کا کوئی شریک نہیں، مجھے یہی حکم ہوا ہے اور میں سب سے پہلا مسلمان ہوں (ف۳۴۰)'),
 (93,6,164,'تم فرماؤ کیا اللہ کے سوا اور رب چاہوں حالانکہ وہ ہر چیز کا رب ہے (ف۳۴۱) اور جو کوئی کچھ کمائے وہ اسی کے ذمہ ہے، اور کوئی بوجھ اٹھانے والی جان دوسرے کا بوجھ نہ اٹھائے گی (ف۳۴۲) پھر تمہیں اپنے رب کی طرف پھرنا ہے (ف۳۴۳) وہ تمہیں بتادے گا جس میں اختلاف کرتے تھے،'),
 (93,6,165,'اور وہی ہے جس نے زمین میں تمہیں نائب کیا (ف۳۴۴) اور تم میں ایک کو دوسرے پر درجوں بلندی دی (ف۳۴۵) کہ تمہیں آزمائے (ف۳۴۶) اس چیز میں جو تمہیں عطا کی بیشک تمہارے رب کو عذاب کرتے دیر نہیں لگتی اور بیشک وہ ضرور بخشنے والا مہربان ہے،'),
 (93,7,1,'المص'),
 (93,7,2,'اے محبوب! ایک کتاب تمہاری طرف اُتاری گئی تو تمہارا جی اس سے نہ رُکے (ف۲) اس لیے کہ تم اس سے ڈر سناؤ اور مسلمانوں کو نصیحت،'),
 (93,7,3,'اے لوگو! اس پر چلو جو تمہاری طرف تمہارے رب کے پاس سے اُترا (ف۳) اور اسے چھوڑ کر اور حاکموں کے پیچھے نہ جاؤ، بہت ہی کم سمجھتے ہو،'),
 (93,7,4,'اور کتنی ہی بستیاں ہم نے ہلاک کیں (ف۴) تو ان پر ہمارا عذاب رات میں آیا جب وہ دوپہر کو سوتے تھے(ف۵)'),
 (93,7,5,'تو ان کے منہ سے کچھ نہ نکلا جب ہمارا عذاب ان پر آیا مگر یہی بولے کہ ہم ظالم تھے (ف۶)'),
 (93,7,6,'تو بیشک ضرور ہمیں پوچھنا ہے ان سے جن کے پاس رسول گئے (ف۷) اور بیشک ضرور ہمیں پوچھنا ہے رسولوں سے (ف۸)'),
 (93,7,7,'تو ضرور ہم ان کو بتادیں گے (ف۹) اپنے علم سے اور ہم کچھ غائب نہ تھے،'),
 (93,7,8,'اور اس دن تول ضرور ہونی ہے (ف۱۰) تو جن کے پلے بھاری ہوئے (ف۱۱) وہی مراد کو پہنچے،'),
 (93,7,9,'اور جن کے پلے ہلکے ہوئے (ف۱۲) تو وہی ہیں جنہوں نے اپنی جان گھاٹے میں ڈالی ان زیادتیوں کا بدلہ جو ہماری آیتوں پر کرتے تھے(ف۱۳)'),
 (93,7,10,'اور بیشک ہم نے تمہیں زمین میں جماؤ (ٹھکانا) دیا اور تمہارے لیے اس میں زندگی کے اسباب بنائے (ف۱۴) بہت ہی کم شکر کرتے ہو(ف۱۵)'),
 (93,7,11,'اور بیشک ہم نے تمہیں پیدا کیا پھر تمہارے نقشے بنائے پھر ہم نے ملائکہ سے فرمایا کہ آدم کو سجدہ کرو، تو وہ سب سجدے میں گرے مگر ابلیس، یہ سجدہ کرنے والوں میں نہ ہوا،'),
 (93,7,12,'فرمایا کس چیز نے تجھے روکا کہ تو نے سجدہ نہ کیا جب میں نے تجھے حکم دیا تھا (ف۱۶) بولا میں اس سے بہتر ہوں تو نے مجھے آگ سے بنایا اور اسے مٹی سے بنایا (ف۱۷)'),
 (93,7,13,'فرمایا تو یہاں سے اُ تر جا تجھے نہیں پہنچتا کہ یہاں رہ کر غرور کرے نکل (ف۱۸) تو ہے ذلت والوں میں(ف۱۹)'),
 (93,7,14,'بولا مجھے فرصت دے اس دن تک کہ لوگ اٹھائے جائیں،'),
 (93,7,15,'فرمایا تجھے مہلت ہے(ف۲۰)'),
 (93,7,16,'بولا تو قسم اس کی کہ تو نے مجھے گمراہ کیا میں ضرور تیرے سیدھے راستہ پر ان کی تاک میں بیٹھوں گا(ف۲۱)'),
 (93,7,17,'پھر ضرور میں ان کے پاس آؤں گا ان کے آگے اور ان کے پیچھے او ر ان کے دائیں اور ان کے بائیں سے (ف۲۲) اور تو ان میں سے اکثر کو شکر گزار نہ پائے گا (ف۲۳)'),
 (93,7,18,'فرمایا یہاں سے نکل جا رد کیا گیا راندہ ہوا، ضرور جو اُن میں سے تیرے کہے پر چلا میں تم سب سے جہنم بھردوں گا (ف۲۴)'),
 (93,7,19,'اور اے آدم تو اور تیرا جوڑا (ف۲۵) جنت میں رہو تو اُس سے جہاں چاہو کھاؤ اور اس پیڑ کے پاس نہ جانا کہ حد سے بڑھنے والوں میں ہو گے،'),
 (93,7,20,'پھر شیطان نے ان کے جی میں خطرہ ڈالا کہ ان پر کھول دے ان کی شرم کی چیزیں (ف۲۶) جو ان سے چھپی تھیں (ف۲۷) اور بولا تمہیں تمہارے رب نے اس پیڑ سے اسی لیے منع فرمایا ہے کہ کہیں تم دو فرشتے ہوجاؤ یا ہمیشہ جینے والے (ف ۲۸)'),
 (93,7,21,'اور ان سے قسم کھائی کہ میں تم دونوں کا خیر خواہ ہوں،'),
 (93,7,22,'تو اُتار لایا انہیں فریب سے (ف۲۹) پھر جب انہوں نے وہ پیڑ چکھا ان پر اُن کی شرم کی چیزیں کھل گئیں (ف۳۰) اور اپنے بدن پر جنت کے پتے چپٹانے لگے، اور انہیں ان کے رب نے فرمایا کیا میں نے تمہیں اس پیڑ سے منع نہ کیا اور نہ فرمایا تھا کہ شیطان تمہارا کھلا دشمن ہے،'),
 (93,7,23,'دونوں نے عرض کی، اے رب ہمارے! ہم نے اپنا آپ بُرا کیا، تو اگر تُو ہمیں نہ بخشے اور ہم پر رحم نہ کرے تو ہم ضرور نقصان والوں میں ہوئے،'),
 (93,7,24,'فرمایا اُترو (ف۳۱) تم میں ایک دوسرے کا دشمن ہے اور تمہیں زمین میں ایک وقت تک ٹھہرنا اور برتنا ہے،'),
 (93,7,25,'فرمایا اسی میں جیوگے اور اسی میں مرو گے اور اسی میں اٹھائے جاؤ گے (ف۳۲)'),
 (93,7,26,'اے آدم کی اولاد! بیشک ہم نے تمہاری طرف ایک لباس وہ اُتارا کہ تمہاری شرم کی چیزیں چھپائے اور ایک وہ کہ تمہاری آرائش ہو (ف۳۳) اور پرہیزگاری کا لباس وہ سب سے بھلا (ف۳۴) یہ اللہ کی نشانیوں میں سے ہے کہ کہیں وہ نصیحت مانیں،'),
 (93,7,27,'اے آدم کی اولاد! (ف۳۵) خبردار! تمہیں شیطان فتنہ میں نہ ڈالے جیسا تمہارے ماں باپ کو بہشت سے نکالا اتروا دیئے ان کے لباس کہ ان کی شرم کی چیزیں انہیں نظر پڑیں، بیشک وہ اور اس کا کنبہ تمہیں وہاں سے دیکھتے ہیں کہ تم انہیں نہیں دیکھتے (ف۳۶) بیشک ہم نے شیطانوں کو ان کا دوست کیا ہے جو ایمان نہیں لاتے،'),
 (93,7,28,'اور جب کوئی بے حیائی کریں (ف۳۷) تو کہتے ہیں ہم نے اس پر اپنے باپ دادا کو پایا اور اللہ نے ہمیں اس کا حکم دیا (ف۳۸) تو فرماؤ بیشک اللہ بے حیائی کا حکم نہیں دیتا، کیا اللہ پر وہ بات لگاتے ہو جس کی تمہیں خبر نہیں،'),
 (93,7,29,'تم فرماؤ میرے رب نے انصاف کا حکم دیا ہے، اور اپنے منہ سیدھے کرو ہر نماز کے وقت اور اس کی عبادت کرو نرے (خالص) اس کے بندے ہوکر، جیسے اس نے تمہارا آغاز کیا ویسے ہی پلٹو گے (ف۳۹)'),
 (93,7,30,'ایک فرقے کو راہ دکھائی (ف۴۰) اور ایک فرقے کو گمراہی ثابت ہوئی (ف۴۱) انہوں نے اللہ کو چھوڑ کر شیطانوں کو والی بنایا (ف۴۲) اور سمجھتے یہ ہیں کہ وہ راہ پر ہیں،'),
 (93,7,31,'اے آدم کی اولاد! اپنی زینت لو جب مسجد میں جاؤ (ف۴۳) اور کھاؤ اور پیو (ف۴۴) اور حد سے نہ بڑھو، بیشک حد سے بڑھنے والے اسے پسند نہیں،'),
 (93,7,32,'تم فرماؤ کس نے حرام کی اللہ کی وہ زینت جو اس نے اپنے بندو ں کے لیے نکالی (ف۴۵) اور پاک رزق (ف۴۶) تم فرماؤ کہ وہ ایمان والوں کے لیے ہے دنیا میں اور قیامت میں تو خاص انہی کی ہے، ہم یونہی مفصل آیتیں بیان کرتے ہیں (ف۴۷) علم والوں کے لیے(ف۴۸)'),
 (93,7,33,'تم فرماؤ میرے رب نے تو بے حیائیاں حرام فرمائی ہیں (ف۴۹) جو ان میں کھلی ہیں اور جو چھپی اور گناہ اور ناحق زیادتی اور یہ (ف۵۰) کہ اللہ کا شریک کرو جس کی اس نے سند نہ اتاری اور یہ (ف۵۱) کہ اللہ پر وہ بات کہو جس کا علم نہیں رکھتے،'),
 (93,7,34,'اور ہر گروہ کا ایک وعدہ ہے (ف۵۲) تو جب ان کا وعدہ آئے گا ایک گھڑی نہ پیچھے ہو نہ آگے،'),
 (93,7,35,'اے آدم کی اولاد! اگر تمہارے پاس تم میں کے رسول آئیں (ف۵۳) میری آیتیں پڑھتے تو جو پرہیزگاری کرے (ف۵۴) اور سنورے (ف۵۵) تو اس پر نہ کچھ خوف اور نہ کچھ غم،'),
 (93,7,36,'اور جنہوں نے ہماری آیتیں جھٹلائیں اور ان کے مقابل تکبر کیا وہ دوز خی ہیں انہیں اس میں ہمیشہ رہنا،'),
 (93,7,37,'تو اس سے بڑھ کر ظالم کون جس نے اللہ پر جھوٹ باندھا یا اس کی آیتیں جھٹلائیں، انہیں ان کے نصیب کا لکھا پہنچے گا (ف۵۶) یہاں تک کہ جب ان کے پاس ہمارے بھیجے ہوئے (ف۵۷) ان کی جان نکالنے آئیں تو ان سے کہتے ہیں کہاں ہیں وہ جن کو تم اللہ کے سوا پوجتے تھے، کہتے ہیں وہ ہم سے گم گئے (ف۵۸) اور اپنی جانوں پر آپ گواہی دیتے ہیں کہ وہ کافر تھے،'),
 (93,7,38,'اللہ ان سے (ف۵۹) فرماتا ہے کہ تم سے پہلے جو اور جماعتیں جن اور آدمیوں کی آگ میں گئیں، انہیں میں جاؤ جب ایک گروہ (ف۶۰) داخل ہوتا ہے دوسرے پر لعنت کرتا ہے (ف۶۱) یہاں تک کہ جب سب اس میں جا پڑے تو پچھلے پہلوں کو کہیں گے (ف۶۲) اے رب ہمارے! انہوں نے ہم کو بہکایا تھا تو انہیں آگ کا دُونا عذاب دے، فرمائے گا سب کو دُونا ہے (ف۶۳) مگر تمہیں خبر نہیں (ف۶۴)'),
 (93,7,39,'اور پہلے پچھلوں سے کہیں گے تو تم کچھ ہم سے اچھے نہ رہے (ف۶۵) تو چکھو عذاب بدلہ اپنے کیے کا(ف۶۶)'),
 (93,7,40,'وہ جنہوں نے ہماری آیتیں جھٹلائیں اور ان کے مقابل تکبر کیا ان کے لیے آسمان کے دروازے نہ کھولے جائیں گے (ف۶۷) اور نہ وہ جنت میں داخل ہوں جب تک سوئی کے ناکے اونٹ داخل نہ ہو (ف۶۸) اور مجرموں کو ہم ایسا ہی بدلہ دیتے ہیں (ف۶۹)'),
 (93,7,41,'انہیں آگ ہی بچھونا اور آگ ہی اوڑھنا (ف۷۰) اور ظالموں کو ہم ایسا ہی بدلہ دیتے ہیں،'),
 (93,7,42,'اور وہ جو ایمان لائے اور طاقت بھر اچھے کام کیے ہم کسی پر طاقت سے زیادہ بوجھ نہیں رکھتے، وہ جنت والے ہیں، انہیں اس میں ہمیشہ رہنا،'),
 (93,7,43,'اور ہم نے ان کے سینوں سے کینے کھینچ لیے (ف۷۱) ان کے نیچے نہریں بہیں گی اور کہیں گے (ف۷۲) سب خوبیاں اللہ کو جس نے ہمیں اس کی راہ دکھائی (ف۷۳) اور ہم راہ نہ پاتے اگر اللہ ہمیں راہ نہ دکھاتا، بیشک ہمارے رب کے رسول حق لائے (ف۷۴) اور ندا ہوئی کہ یہ جنت تمہیں میراث ملی (ف۷۵) صلہ تمہارے اعمال کا،'),
 (93,7,44,'اور جنت والوں نے دوزخ والوں کو پکارا کہ ہمیں تو مل گیا جو سچا وعدہ ہم سے ہمارے رب نے کیا تھا (ف۷۶) تو کیا تم نے بھی پایا جو تمہارے رب نے (ف۷۷) سچا وعدہ تمہیں دیا تھا بولے، ہاں! اور بیچ میں منادی نے پکار دیا کہ اللہ کی لعنت ظالموں پر'),
 (93,7,45,'جو اللہ کی راہ سے روکتے ہیں (ف۷۸) اور اسے کجی چاہتے ہیں (ف۷۹) اور آخرت کا انکار رکھتے ہیں،'),
 (93,7,46,'اور جنت و دوزخ کے بیچ میں ایک پردہ ہے (ف۸۰) اور اعراف پر کچھ مرد ہوں گے (ف۸۱) کہ دونوں فریق کو ان کی پیشانیوں سے پہچانیں گے (ف۸۲) اور وہ جنتیوں کو پکاریں گے کہ سلام تم پر یہ (ف۸۳) جنت میں نہ گئے اور اس کی طمع رکھتے ہیں،'),
 (93,7,47,'اور جب ان کی(ف۸۴) آنکھیں دوزخیوں کی طرف پھریں گی کہیں گے اے ہمارے رب! ظالموں کے ساتھ نہ کر،'),
 (93,7,48,'اور اعراف والے کچھ مردوں کو (ف۸۵) پکاریں گے جنہیں ان کی پیشانی سے پہچانتے ہیں کہیں گے تمہیں کیا کام آیا تمہارا جتھا اور وہ جو تم غرور کرتے تھے(ف۸۶)'),
 (93,7,49,'کیا یہ ہیں وہ لوگ (ف۸۷) جن پر تم قسمیں کھاتے تھے کہ اللہ ان پر اپنی رحمت کچھ نہ کرے گا (ف۸۸) ان سے تو کہا گیا کہ جنت میں جاؤ نہ تم کو اندیشہ نہ کچھ غم،'),
 (93,7,50,'اور دوزخی بہشتیوں کو پکاریں گے کہ ہمیں اپنے پانی کا فیض دو یا اس کھانے کا جو اللہ نے تمہیں دیا (ف۸۹) کہیں گے بیشک اللہ نے ان دونوں کو کافروں پر حرام کیا ہے'),
 (93,7,51,'جنہوں نے اپنے دین کو کھیل تماشا بنایا (ف۹۰) اور دنیا کی زیست نے انہیں فریب دیا (ف۹۱) تو آج ہم انہیں چھوڑ دیں گے جیسا انہوں نے اس دن کے ملنے کا خیال چھوڑا تھا اور جیسا ہماری آیتوں سے انکار کرتے تھے،'),
 (93,7,52,'اور بیشک ہم ان کے پاس ایک کتاب لائے (ف۹۲) جسے ہم نے ایک بڑے علم سے مفصل کیا ہدایت و رحمت ایمان والوں کے لیے،'),
 (93,7,53,'کاہے کی راہ دیکھتے ہیں مگر اس کی کہ اس کتاب کا کہا ہوا انجام سامنے آئے جس دن اس کا بتایا انجام واقع ہوگا (ف۹۳) بول اٹھیں گے وہ جو اسے پہلے سے بھلائے بیٹھے تھے (ف۹۴) کہ بیشک ہمارے رب کے رسول حق لائے تھے تو ہیں کوئی ہمارے سفارشی جو ہماری شفاعت کریں یا ہم واپس بھیجے جائیں کہ پہلے کاموں کے خلاف کام کریں (ف۹۵) بیشک انہوں نے اپنی جانیں نقصان میں ڈالیں اور ان سے کھوئے گئے جو بہتان اٹھاتے تھے (ف۹۶)'),
 (93,7,54,'بیشک تمہارا رب اللہ ہے جس نے آسمان اور زمین (ف۹۷) چھ دن میں بنائے (ف۹۸) پھر عرش پر استواء فرمایا جیسا اس کی شان کے لائق ہے (ف۹۹) رات دن کو ایک دوسرے سے ڈھانکتا ہے کہ جلد اس کے پیچھے لگا آتا ہے اور سورج اور چاند اور تاروں کو بنایا سب اس کے حکم کے دبے ہوئے، سن لو اسی کے ہاتھ ہے پیدا کرنا اور حکم دینا، بڑی برکت والا ہے اللہ رب سارے جہان کا،'),
 (93,7,55,'اپنے رب سے دعا کرو گڑگڑاتے اور آہستہ، بیشک حد سے بڑھنے والے اسے پسند نہیں، (ف۱۰۰)'),
 (93,7,56,'اور زمین میں فساد نہ پھیلاؤ (ف۱۰۱) اس کے سنورنے کے بعد (ف۱۰۲) اور اس سے دعا کرو ڈرتے اور طمع کرتے، بیشک اللہ کی رحمت نیکوں سے قریب ہے،'),
 (93,7,57,'اور وہی ہے کہ ہوائیں بھیجتا ہے اس کی رحمت کے آگے مژدہ سناتی (ف۱۰۳) یہاں تک کہ جب اٹھا لائیں بھاری بادل ہم نے اسے کسی مردہ شہر کی طرف چلایا (ف۱۰۴) پھر اس سے پانی اتارا پھر اس سے طرح طرح کے پھل نکالے اسی طرح ہم مُردوں کو نکالیں گے (ف۱۰۵) کہیں تم نصیحت مانو،'),
 (93,7,58,'اور جو اچھی زمین ہے اس کا سبزہ اللہ کے حکم سے نکلتا ہے (ف۱۰۶) اور جو خراب ہے اس میں نہیں نکلتا مگر تھوڑا بمشکل (ف۱۰۷) ہم یونہی طرح طرح سے آیتیں بیان کرتے ہیں (ف۱۰۸) ان کے لیے جو احسان مانیں،'),
 (93,7,59,'بیشک ہم نے نوح کو اس کی قوم کی طرف بھیجا (ف۱۰۹) تو اس نے کہا میری قوم اللہ کو پوجو (ف۱۱۰) اسکے سوا تمہارا کوئی معبود نہیں (ف۱۱۱) بیشک مجھے تم پر بڑے دن کے عذاب کا ڈر ہے (ف۱۱۲)'),
 (93,7,60,'اس کی قوم کے سردار بولے بیشک ہم تمہیں کھلی گمراہی میں دیکھتے ہیں،'),
 (93,7,61,'کہا اے میری قوم مجھ میں گمراہی کچھ نہیں میں تو رب العالمین کا رسول ہوں،'),
 (93,7,62,'تمہیں اپنے رب کی رسالتیں پہنچاتا اور تمہارا بھلا چاہتا اور میں اللہ کی طرف سے وہ علم رکھتا ہوں جو تم نہیں رکھتے،'),
 (93,7,63,'اور کیا تمہیں اس کا اچنبا ہوا کہ تمہارے پاس رب کی طرف سے ایک نصیحت آئی تم میں کے ایک مرد کی معرفت (ف۱۱۳) کہ وہ تمہیں ڈرائے اور تم ڈرو اور کہیں تم پر رحم ہو،'),
 (93,7,64,'تو انہوں نے اسے جھٹلایا تو ہم نے اسے اور جو (ف۱۱۵) اس کے ساتھ کشتی میں تھے نجات دی اور اپنی آیتیں جھٹلانے والوں کو ڈبو دیا، بیشک وہ اندھا گروہ تھا (ف۱۱۶)'),
 (93,7,65,'اور عاد کی طرف (ف۱۱۷) ان کی برادری سے ہود کو بھیجا (ف۱۱۸) کہا اے میری قوم اللہ کی بندگی کرو اس کے سوا تمہارا کوئی معبود نہیں، تو کیا تمہیں ڈر نہیں (ف۱۱۹)'),
 (93,7,66,'اس کی قوم کے سردار بولے بیشک ہم تمہیں بیوقوف سمجھتے ہیں اور بیشک ہم تمہیں جھوٹوں میں گمان کرتے ہیں (ف۱۲۰)'),
 (93,7,67,'کہا اے میری قوم مجھے بے وقوفی سے کیا علاقہ میں تو پروردگار عالم کا رسول ہوں،'),
 (93,7,68,'تمہیں اپنے رب کی رسالتیں پہنچاتا ہوں اور تمہارا معتمد خیرخواہ ہوں (ف۱۲۱)'),
 (93,7,69,'اور کیا تمہیں اس کا اچنبا ہوا کہ تمہارے پاس تمہارے رب کی طرف سے ایک نصیحت آئی تم میں سے ایک مرد کی معرفت کہ وہ تمہیں ڈرائے اور یاد کرو جب اس نے تمہیں قوم نوح کا جانشین کیا (ف۱۲۲) اور تمہارے بدن کا پھیلاؤ بڑھایا (ف۱۲۳) تو اللہ کی نعمتیں یاد کرو (ف۱۲۴) کہ کہیں تمہارا بھلا ہو،'),
 (93,7,70,'بولے کیا تم ہمارے پاس اس لیے آئے ہو (ف۱۲۵) کہ ہم ایک اللہ کو پوجیں اور جو (ف۱۲۶) ہمارے باپ دادا پوجتے تھے، انہیں چھوڑ دیں تو لاؤ (ف۱۲۷) جس کا ہمیں وعدہ دے رہے ہو اگر سچے ہو،'),
 (93,7,71,'کہا (ف۱۲۸) ضرور تم پر تمہارے رب کا عذاب اور غضب پڑ گیا (ف۱۲۹) کیا مجھ سے خالی ان ناموں میں جھگڑ رہے ہو جو تم نے اور تمہارے باپ دادا نے رکھ لیے (ف۱۳۰) اللہ نے ان کی کوئی سند نہ اتاری، تو راستہ دیکھو (ف۱۳۱) میں بھی تمہارے ساتھ دیکھتا ہوں،'),
 (93,7,72,'تو ہم نے اسے اور اس کے ساتھ والوں کو (ف۱۳۲) اپنی ایک بڑی رحمت فرماکر نجات دی (ف۱۳۳) اور جو ہماری آیتیں جھٹلاتے (ف۱۳۴) تھے ان کی جڑ کاٹ دی (ف۱۳۵) اور وہ ایمان والے نہ تھے،'),
 (93,7,73,'اور ثمود کی طرف (ف۱۳۶) ان کی برادری سے صالح کو بھیجا کہا اے میری قوم اللہ کو پوجو اس کے سوا تمہارا کوئی معبود نہیں، بیشک تمہارے پاس تمہارے رب کی طرف سے (ف۱۳۷) روشن دلیل آئی (ف۱۳۸) یہ اللہ کا ناقہ ہے (ف۱۳۹) تمہارے لیے نشانی، تو اسے چھوڑ دو کہ اللہ کی زمین میں کھائے اور اسے برائی سے ہاتھ نہ لگاؤ (ف۱۴۰) کہ تمہیں درد ناک عذاب آئے گا،'),
 (93,7,74,'اور یاد کرو (ف۱۴۱) جب تم کو عاد کا جانشین کیا اور ملک میں جگہ دی کہ نرم زمین میں محل بناتے ہو (ف۱۴۲) اور پہاڑوں میں مکان تراشتے ہو (ف۱۴۳) تو اللہ کی نعمتیں یاد کرو (ف۱۴۴) اور زمین میں فساد مچاتے نہ پھرو،'),
 (93,7,75,'اس کی قوم کے تکبر والے کمزور مسلمانوں سے بولے کیا تم جانتے ہو کہ صالح اپنے رب کے رسول ہیں، بولے وہ جو کچھ لے کے بھیجے گئے ہم اس پر ایمان رکھتے ہیں (ف۱۴۵)'),
 (93,7,76,'متکبر بولے جس پر تم ایمان لائے ہمیں اس سے انکار ہے،'),
 (93,7,77,'پس (ف۱۴۶) ناقہ کی کُوچیں کاٹ دیں اور اپنے رب کے حکم سے سرکشی کی اور بولے اے صالح! ہم پر لے آؤ (ف۱۴۷) جس کا تم سے وعد دے رہے ہو اگر تم رسول ہو،'),
 (93,7,78,'تو انہیں زلزلے نے ا ٓلیا تو صبح کو اپنے گھروں میں اوندھے پڑے رہ گئے،'),
 (93,7,79,'تو صالح نے ان سے منہ پھیرا (ف۱۴۸) اور کہا اے میری قوم! بیشک میں نے تمہیں اپنے رب کی رسالت پہنچادی اور تمہارا بھلا چاہا مگر تم خیر خواہوں کے غرضی (پسند کرنے والے) ہی نہیں،'),
 (93,7,80,'اور لوط کو بھیجا (ف۱۴۹) جب اس نے اپنی قوم سے کہا کیا وہ بے حیائی کرتے ہو جو تم سے پہلے جہان میں کسی نے نہ کی،'),
 (93,7,81,'تم تو مردوں کے پاس شہوت سے جاتے ہو (ف۱۵۰) عورتیں چھوڑ کر، بلکہ تم لوگ حد سے گزر گئے (ف۱۵۱)'),
 (93,7,82,'اور اس کی قوم کا کچھ جواب نہ تھا مگر یہی کہنا کہ ان (ف۱۵۲) کو اپنی بستی سے نکال دو، یہ لوگ تو پاکیزگی چاہتے ہیں (ف۱۵۳)'),
 (93,7,83,'تو ہم نے اسے (ف۱۵۴) اور اس کے گھر والوں کو نجات دی مگر اس کی عورت وہ رہ جانے والوں میں ہوئی(ف۱۵۵)'),
 (93,7,84,'اور ہم نے ان پر ایک مینھ برسایا (ف۱۵۶) تو دیکھو کیسا انجام ہوا مجرموں کا(ف۱۵۷)'),
 (93,7,85,'اور مدین کی طرف ان کی برادری سے شعیب کو بھیجا (ف۱۵۸) کہا اے میری قوم! اللہ کی عبادت کرو اس کے سوا تمہارا کوئی معبود نہیں، بے شک تمہارے پاس تمہارے رب کی طرف سے روشن دلیل آئی (ف۱۵۹) تو ناپ اور تول پوری کرو اور لوگوں کی چیزیں گھٹا کر نہ دو (ف۱۶۰) اور زمین میں انتظام کے بعد فساد نہ پھیلاؤ، یہ تمہارا بھلا ہے اگر ایمان لاؤ،'),
 (93,7,86,'اور ہر راستہ پر یوں نہ بیٹھو کہ راہگیروں کو ڈراؤ اور اللہ کی راہ سے انہیں روکو (ف۱۶۱) جو اس پر ایمان لائے اور اس میں کجی چاہو، اور یاد کرو جب تم تھوڑے تھے اس نے تمہیں بڑھادیا (ف۱۶۲) اور دیکھو (ف۱۶۳) فسادیوں کا کیسا انجام ہوا،'),
 (93,7,87,'اور اگر تم میں ایک گروہ اس پر ایمان لایا جو میں لے کر بھیجا گیا اور ایک گروہ نے نہ مانا (ف۱۶۴) تو ٹھہرے رہو یہاں تک کہ اللہ ہم میں فیصلہ کرے (ف۱۶۵) اور اللہ کا فیصلہ سب سے بہتر (ف۱۶۶)'),
 (93,7,88,'اس کی قوم کے متکبر سردار بولے، اے شعیب قسم ہے کہ ہم تمہیں اور تمہارے ساتھ والے مسلمانوں کو اپنی بستی سے نکا ل دیں گے یا تم ہمارے دین میں ا ٓجا ؤ کہا (ف۱۶۷) کیا اگرچہ ہم بیزار ہوں(ف۱۶۸)'),
 (93,7,89,'ضرور ہم اللہ پر جھوٹ باندھیں گے اگر تمہارے دین میں آجائیں بعد اس کے کہ اللہ نے ہمیں اس سے بچایا ہے (ف۱۶۹) اور ہم مسلمانوں میں کسی کا کام نہیں کہ تمہارے دین میں آئے مگر یہ کہ اللہ چاہے (ف۱۷۰) جو ہمارا رب ہے، ہمارے رب کا علم ہر چیز کو محیط ہے، اللہ ہی پر بھروسہ کیا (ف۱۷۱) اے ہمارے رب! ہم میں اور ہماری قوم میں حق فیصلہ کر (ف۱۷۲) اور تیرا فیصلہ سب سے بہتر ہے،'),
 (93,7,90,'اور اسکی قوم کے کافر سردار بولے کہ اگر تم شعیب کے تابع ہوئے تو ضرور نقصان میں رہو گے،'),
 (93,7,91,'تو انہیں زلز لہ نے ا ٓ لیا تو صبح اپنے گھروں میں اوندھے پڑے رہ گئے (ف۱۷۳)'),
 (93,7,92,'شعیب کو جھٹلانے والے گویا ان گھروں میں کبھی رہے ہی نہ تھے، شعیب کو جھٹلانے والے ہی تباہی میں پڑے،'),
 (93,7,93,'تو شعیب نے ان سے منہ پھیرا (ف۱۷۴) اور کہا اے میری قوم! میں تمہیں رب کی رسالت پہنچا چکا اور تمہارے بھلے کو نصیحت کی (ف۱۷۵) تو کیونکر غم کروں کافروں کا،'),
 (93,7,94,'اور نہ بھیجا ہم نے کسی بستی میں کوئی نبی (ف۱۷۶) مگر یہ کہ اس کے لوگوں کو سختی اور تکلیف میں پکڑا (ف۱۷۷) کہ وہ کسی طرح زاری کریں (ف۱۷۸)'),
 (93,7,95,'پھر ہم نے برائی کی جگہ بھلائی بدل دی (ف۱۷۹) یہاں تک کہ وہ بہت ہوگئے (ف۱۸۰) اور بولے بیشک ہمارے باپ دادا کو رنج و راحت پہنچے تھے (ف۱۸۱) تو ہم نے انہیں اچانک ان کی غفلت میں پکڑ لیا (ف۱۸۲)'),
 (93,7,96,'اور اگر بستیو ں والے ایمان لاتے اور ڈرتے (ف۱۸۳) تو ضرور ہم ان پر آسمان اور زمین سے برکتیں کھول دیتے (ف۱۸۴) مگر انہوں نے تو جھٹلایا (ف۱۸۵) تو ہم نے انہیں ان کے کیے پر گرفتار کیا(ف۱۸۶)'),
 (93,7,97,'کیا بستیوں والے (ف۱۸۷) نہیں ڈرتے کہ ان پر ہمارا عذاب رات کو آئے جب وہ سوتے ہوں'),
 (93,7,98,'یا بستیوں والے نہیں ڈرتے کہ ان پر ہمارا عذاب دن چڑھے آئے جب وہ کھیل رہے ہوں(ف۱۸۸)'),
 (93,7,99,'کیا اللہ کی خفی تدبیر سے بے خبر ہیں (ف۱۸۹) تو اللہ کی خفی تدبیر سے نذر نہیں ہوتے مگر تباہی والے (ف۱۹۰)'),
 (93,7,100,'اور کیا وہ جو زمین کے ما لکوں کے بعد اس کے وارث ہوئے انہیں اتنی ہدایت نہ ملی کہ ہم چاہیں تو انہیں ان کے گناہوں پر آ فت پہنچائیں (ف۱۹۱) اور ہم ان کے دلوں پر مہر کرتے ہیں کہ وہ کچھ نہیں سنتے(ف۱۹۲)'),
 (93,7,101,'یہ بستیاں ہیں (ف۱۹۳) جن کے احوال ہم تمہیں سناتے ہیں (ف۱۹۴) اور بیشک ان کے پاس ان کے رسول روشن دلیلیں (ف۱۹۵) لے کر آئے تو وہ (ف۱۹۶) اس قابل نہ ہوئے کہ وہ اس پر ایمان لاتے جسے پہلے جھٹلاچکے تھے (ف۱۹۷) اللہ یونہی چھاپ لگادیتا ہے کا فروں کے دلوں پر(ف۱۹۸)'),
 (93,7,102,'اور ان میں اکثر کو ہم نے قول کا سچا نہ پایا (ف۱۹۹) اور ضرور ان میں اکثر کو بے حکم ہی پایا،'),
 (93,7,103,'پھر ان (ف۲۰۰) کے بعد ہم نے موسیٰ کو اپنی نشانیوں (ف۲۰۱) کے ساتھ فرعون اور اس کے درباریوں کی طرف بھیجا تو انہوں نے ان نشانیوں پر زیادتی کی (ف۲۰۲) تو دیکھو کیسا انجام ہوا مفسدوں کا،'),
 (93,7,104,'اور موسیٰ نے کہا اے فرعون! میں پرور دگا ر عالم کا رسول ہوں،'),
 (93,7,105,'مجھے سزاوار ہے کہ اللہ پر نہ کہوں مگر سچی بات (ف۲۰۳) میں تم سب کے پاس تمہارے رب کی طرف سے نشانی لےکر آیا ہوں (ف۲۰۴) تو بنی اسرائیل کو میرے ساتھ چھوڑ دے(ف۲۰۵)'),
 (93,7,106,'بولا اگر تم کوئی نشانی لے کر آئے ہو تو لاؤ اگر سچے ہو،'),
 (93,7,107,'تو موسیٰ نے اپنا عصا ڈال دیا وہ فورا ً ایک ظاہر اژدہا ہوگیا (ف۲۰۶)'),
 (93,7,108,'اور اپنا ہاتھ گریبان میں ڈال کر نکا لا تو وہ دیکھنے والوں کے سامنے جگمگانے لگا (ف۲۰۷)'),
 (93,7,109,'قوم فرعون کے سردار بولے یہ تو ایک علم والا جادوگر ہے (ف۲۰۸)'),
 (93,7,110,'تمہیں تمہارے ملک (ف۲۰۹) سے نکا لا چاہتا ہے تو تمہارا کیا مشورہ ہے،'),
 (93,7,111,'بولے انہیں اور ان کے بھائی (ف۲۱۰) کو ٹھہرا اور شہروں میں لوگ جمع کرنے والے بھیج دے،'),
 (93,7,112,'کہ ہر علم والے جادوگر کو تیرے پاس لے آئیں (ف۲۱۱)'),
 (93,7,113,'اور جادوگر فرعون کے پاس آئے بولے کچھ ہمیں انعام ملے گا اگر ہم غالب آئیں،'),
 (93,7,114,'بولا ہاں اور اس وقت تم مقرب ہوجا ؤ گے،'),
 (93,7,115,'بولے اے موسیٰ یا تو (ف۲۱۲) آپ ڈالیں یا ہم ڈالنے والے ہوں(ف۲۱۳)'),
 (93,7,116,'کہا تمہیں ڈالو (ف۲۱۴) جب انہوں نے ڈالا (ف۲۱۵) لوگوں کی آنکھوں پر جادو کردیا اور انہیں ڈرایا اور بڑا جادو لائے،'),
 (93,7,117,'اور ہم نے موسیٰ کو وحی فرمائی کہ اپنا عصا ڈال تو ناگاہ ان کی بناوٹوں کو نگلنے لگا (ف۲۱۶)'),
 (93,7,118,'تو حق ثابت ہوا اور ان کا کام باطل ہوا،'),
 (93,7,119,'تو یہاں وہ مغلوب پڑے اور ذلیل ہوکر پلٹے'),
 (93,7,120,'اور جادوگر سجدے میں گرادیے گئے (ف۲۱۷)'),
 (93,7,121,'بولے ہم ایمان لائے جہان کے رب پر،'),
 (93,7,122,'جو رب ہے موسیٰ اور ہارون کا،'),
 (93,7,123,'فرعون بولا تم اس پر ایمان لے آئے قبل اس کے کہ میں تمہیں اجازت دوں، یہ تو بڑا جعل (فریب) ہے جو تم سب نے (ف۲۱۸) شہر میں پھیلایا ہے کہ شہر والوں کو اس سے نکال دو (ف۲۱۹) تو اب جان جاؤ گے (ف۲۲۰)'),
 (93,7,124,'قسم ہے کہ میں تمہارے ایک طرف کہ ہاتھ اور دوسری طرف کے پاؤں کاٹوں گا پھر تم سب کو سُو لی دوں گا (ف۲۲۱)'),
 (93,7,125,'بولے ہم اپنے رب کی طرف پھرنے والے ہیں (ف۲۲۲)'),
 (93,7,126,'اور تجھے ہمارا کیا برا لگا یہی نہ کہ ہم اپنے رب کی نشانیوں پر ایمان لائے جب وہ ہمارے پاس آئیں، اے رب ہمارے! ہم پر صبر انڈیل دے (ف۲۲۳) اور ہمیں مسلمان اٹھا (ف۲۲۴)'),
 (93,7,127,'اور قوم فرعون کے سردار بولے کیا تو موسیٰ اور اس کی قوم کو اس لیے چھوڑ تا ہے کہ وہ زمین میں فساد پھیلائیں (ف۲۲۵) اور موسیٰ تجھے اور تیرے ٹھہرائے ہوئے معبودوں کو چھوڑدے (ف۲۲۶) بولا اب ہم ان کے بیٹوں کو قتل کریں گے اور ان کی بیٹیاں زندہ رکھیں گے اور ہم بیشک ان پر غالب ہیں (ف۲۲۷)'),
 (93,7,128,'موسیٰ نے اپنی قوم سے فرمایا اللہ کی مدد چاہو (ف۲۲۸) اور صبر کرو (ف۲۲۹) بیشک زمین کا مالک اللہ ہے (ف۲۳۰) اپنے بندوں میں جسے چاہے وارث بنائے (ف۲۳۱) اور آخر میدان پرہیزگاروں کے ہاتھ ہے (ف۲۳۲)'),
 (93,7,129,'بولے ہم ستائے گئے آپ کے آنے سے پہلے (ف۲۳۳) اور آپ کے تشریف لانے کے بعد (ف۲۳۴) کہا قریب ہے کہ تمہارا رب تمہارے دشمن کو ہلاک کرے اور اس کی جگہ زمین کا مالک تمہیں بنائے پھر دیکھے کیسے کام کرتے ہو (ف۲۳۵)'),
 (93,7,130,'اور بیشک ہم نے فرعون والوں کو برسوں کے قحط اور پھلوں کے گھٹانے سے پکڑا (ف۲۳۶) کہ کہیں وہ نصیحت مانیں (ف۲۳۷)'),
 (93,7,131,'تو جب انہیں بھلائی ملتی (ف۲۳۸) کہتے یہ ہمارے لیے ہے (ف۲۳۹) اور جب برائی پہنچتی تو موسیٰ اور اس کے ساتھ والوں سے بدشگونی لیتے (ف۲۴۰) سن لو ان کے نصیبہ کی شامت تو اللہ کے یہاں ہے (ف۲۴۱) لیکن ان میں اکثر کو خبر نہیں،'),
 (93,7,132,'اور بولے تم کیسی بھی نشانی لے کر ہمارے پاس آؤ کہ ہم پر اس سے جادو کرو ہم کسی طرح تم پر ایمان لانے والے نہیں (ف۲۴۲)'),
 (93,7,133,'تو بھیجا ہم نے ان پر طوفان (ف۲۴۳) اور ٹڈی اور گھن (یا کلنی یا جوئیں) اور مینڈک اور خون جدا جدا نشانیاں (ف۲۴۴) تو انہوں نے تکبر کیا (ف۲۴۵) اور وہ مجرم قوم تھی'),
 (93,7,134,'اور جب ان پر عذاب پڑتا کہتے اے موسیٰ ہمارے لیے اپنے رب سے دعا کرو اس عہد کے سبب جو اس کا تمہارے پاس ہے (ف۲۴۶) بیشک اگر تم ہم پر عذاب اٹھادو گے تو ہم ضرور تم پر ایمان لائیں گے اور بنی اسرائیل کو تمہارے ساتھ کردیں گے،'),
 (93,7,135,'پھر جب ہم ان سے عذاب اٹھالیتے ایک مدت کے کیے جس تک انہیں پہنچنا ہے جبھی وہ پھر جاتے،'),
 (93,7,136,'تو ہم نے ان سے بدلہ لیا تو انہیں دریا میں ڈبو دیا (ف۲۴۷) اس لیے کہ ہماری آیتیں جھٹلاتے اور ان سے بے خبر تھے (ف۲۴۸)'),
 (93,7,137,'اور ہم نے اس قوم کو (ف۲۴۹) جو دبا لی گئی تھی اس زمین (ف۲۵۰) کے پورب پچھم کا وارث کیا جس میں ہم نے برکت رکھی (ف۲۵۱) اور تیرے رب کا اچھا وعدہ بنی اسرائیل پر پورا ہوا، بدلہ ان کے صبر کا، اور ہم نے برباد کردیا (ف۲۵۲) جو کچھ فرعون اور اس کی قوم بناتی اور جو چنائیاں اٹھاتے (تعمیر کرتے) تھے،'),
 (93,7,138,'اور ہم نے (ف۲۵۳) بنی اسرائیل کو دریا پار اتارا تو ان کا گزر ایک ایسی قوم پر ہوا کہ اپنے بتوں کے آگے آسن مارے (جم کر بیٹھے) تھے (ف۲۵۴) بولے اے موسیٰ! ہمیں ایک خدا بنادے جیسا ان کے لیے اتنے خدا ہیں، بولا تم ضرور جا ہل لوگ ہو، (ف۲۵۵)'),
 (93,7,139,'یہ حال تو بربادی کا ہے جس میں یہ (ف۲۵۶) لوگ ہیں اور جو کچھ کررہے ہیں نرا باطل ہے،'),
 (93,7,140,'کہا کیا اللہ کے سوا تمہارا اور کوئی خدا تلاش کروں حالانکہ اس نے تمہیں زمانے بھر پر فضیلت دی(ف۲۵۷)'),
 (93,7,141,'اور یاد کرو جب ہم نے تمہیں فرعون والوں سے نجات بحشی کہ تمہیں بری مار دیتے تمہارے بیٹے ذبح کرتے اور تمہاری بیٹیاں باقی رکھتے، اور اس میں رب کا بڑا فضل ہوا (ف۲۵۸)'),
 (93,7,142,'اور ہم نے موسیٰ سے (ف۲۵۹) تیس رات کا وعدہ فرمایا اور ان میں (ف۲۶۰) دس اور بڑھا کر پوری کیں تو اس کے رب کا وعدہ پوری چالیس رات کا ہوا (ف۲۶۱) اور موسیٰ نے (ف۲۶۲) اپنے بھائی ہارون سے کہا میری قوم پر میرے نائب رہنا اور اصلاح کرنا اور فسادیوں کی راہ کو دخل نہ دینا،'),
 (93,7,143,'اور جب موسیٰ ہمارے وعدہ پر حاضر ہوا اور اس سے اس کے رب نے کلام فرمایا (ف۲۶۳) عرض کی اے رب میرے! مجھے اپنا دیدار دکھا کہ میں تجھے دیکھوں فرمایا تو مجھے ہر گز نہ دیکھ سکے گا (ف۲۶۴) ہاں اس پہاڑ کی طرف دیکھ یہ اگر اپنی جگہ پر ٹھہرا رہا تو عنقریب تو مجھے دیکھ لے گا (ف۲۶۵) پھر جب اس کے رب نے پہاڑ پر اپنا نو ر چمکایا اسے پاش پاش کردیا اور موسیٰ گرا بیہوش پھر جب ہوش ہوا بولا پاکی ہے تجھے میں تیری طرف رجوع لایا اور میں سب سے پہلا مسلمان ہوں (ف۲۶۶)'),
 (93,7,144,'فرمایا اے موسیٰ میں نے تجھے لوگوں سے چن لیا اپنی رسالتوں اور اپنے کلام سے، تو لے جو میں نے تجھے عطا فرمایا اور شکر والوں میں ہو،'),
 (93,7,145,'اور ہم نے اس کے لیے تختیوں میں (ف۲۶۷) لکھ دی ہر چیز کی نصیحت اور ہر چیز کی تفصیل، اور فرمایا اے موسیٰ اسے مضبوطی سے لے اور اپنی قوم کو حکم دے کر اس کی اچھی باتیں اختیار کریں (ف۲۶۸) عنقریب میں تمہیں دکھاؤں گا بے حکموں کا گھر (ف۲۶۹)'),
 (93,7,146,'اور میں اپنی آیتوں سے انہیں پھیردوں گا جو زمین میں ناحق اپنی بڑا ئی چاہتے ہیں (ف۲۷۰) اور اگر سب نشانیاں دیکھیں ان پر ایمان نہ لائیں اور اگر ہدایت کی راہ دیکھیں اس میں چلنا پسند نہ کریں (ف۳۲۷۱) اور گمراہی کا راستہ نظر پڑے تو اس میں چلنے کو موجود ہوجائیں، یہ اس لیے کہ انہوں نے ہماری آیتیں جھٹلائیں اور ان سے بے خبر بنے،'),
 (93,7,147,'اور جنہوں نے ہماری آیتیں اور آخرت کے دربار کو جھٹلایا ان کا سب کیا دھرا اَکارت گیا، انہیں کیا بدلہ ملے گا مگر وہی جو کرتے تھے،'),
 (93,7,148,'اور موسیٰ کے (ف۲۷۲) بعد اس کی قوم اپنے زیوروں سے (ف۲۷۳) ایک بچھڑا بنا بیٹھی بے جان کا دھڑ (ف۲۷۴) گائے کی طرف آواز کرتا، کیا نہ دیکھا کہ وہ ان سے نہ بات کرتا ہے اور نہ انہیں کچھ راہ بتائے (ف۲۷۵) اسے لیا اور وہ ظالم تھے (ف۲۷۶)'),
 (93,7,149,'اور جب پچھتائے اور سمجھے کہ ہم بہکے بولے اگر ہمارا رب ہم پر مہر ہ کرے اور ہمیں نہ بخشے تو ہم تباہ ہوئے،'),
 (93,7,150,'اور جب موسیٰ (ف۲۷۷) اپنی قوم کی طرف پلٹا غصہ میں بھرا جھنجلایا ہوا (ف۲۷۸) کہا تم نے کیا بری میری جانشینی کی میرے بعد (ف۲۷۹) کیا تم نے اپنے رب کے حکم سے جلدی کی (ف۲۸۰) اور تختیاں ڈال دیں (ف۲۸۱) اور اپنے بھائی کے سر کے بال پکڑ کر اپنی طرف کھینچنے لگا (ف۲۸۲) کہا اے میرے ماں جائے (ف۲۸۳) قوم نے مجھے کمزور سمجھا اور قریب تھا کہ مجھے مار ڈالیں تو مجھ پر دشمنوں کو نہ ہنسا (ف۲۸۴) اور مجھے ظالموں میں نہ ملا (ف۲۸۵)'),
 (93,7,151,'عرض کی اے میرے رب! مجھے اور میرے بھائی کو بخش دے (ف۲۸۶) اور ہمیں اپنی رحمت کے اندر لے لے اور تو سب مہر والوں سے بڑھ کر مہر والا'),
 (93,7,152,'بیشک وہ جو بچھڑا لے بیٹھے عنقریب انہیں ان کے رب کا غضب اور ذلت پہنچناہے دنیا کی زندگی میں، اور ہم ایسی ہی بدلہ دیتے ہیں بہتان ہایوں (باندھنے والوں) کو،'),
 (93,7,153,'اور جنہوں نے برائیاں کیں اور ان کے بعد توبہ کی اور ایمان لائے تو اس کے بعد تمہارا رب بخشنے والا مہربان ہے (ف۲۸۷)'),
 (93,7,154,'اور جب موسیٰ کا غصہ تھما تختیاں اٹھالیں اور ان کی تحریر میں ہدایت اور رحمت ہے ان کے لیے جو اپنے رب سے ڈرتے ہیں،'),
 (93,7,155,'اور موسیٰ نے اپنی قوم سے سترّ ۷۰، مرد ہمارے وعدہ کے لیے چنے (ف۲۸۸) پھر جب انہیں زلزلہ نے لیا (ف۲۸۹) موسیٰ نے عرض کی اے رب میرے! تو چاہتا تو پہلے ہی انہیں اور مجھے ہلاک کردیتا (ف۲۹۰) کیا تو ہمیں اس کام پر ہلاک فرمائے گا جو ہمارے بے عقلوں نے کیا (ف۲۹۱) وہ نہیں مگر تیرا آزمانا، تو اس سے بہکائے جسے چاہے اور راہ دکھائے جسے چاہے تو ہمارا مولیٰ ہے تو ہمیں بخش دے اور ہم پر مہر کر اور تو سب سے بہتر بخشنے والا ہے،'),
 (93,7,156,'اور ہمارے لیے اس دنیا میں بھلائی لکھ (ف۲۹۲) اور آخرت میں بیشک ہم تیری طرف رجوع لائے، فرمایا (ف۲۹۳) میرا عذاب میں جسے چاہوں دوں (ف۲۹۴) اور میری رحمت ہر چیز کو گھیرے ہے (ف۲۹۵) تو عنقریب میں (ف۲۹۶) نعمتوں کو ان کے لیے لکھ دوں گا جو ڈرتے اور زکوٰة دیتے ہیں اور وہ ہماری آیتوں پر ایمان لاتے ہیں،'),
 (93,7,157,'وہ جو غلامی کریں گے اس رسول بے پڑھے غیب کی خبریں دینے والے کی (ف۲۹۷) جسے لکھا ہوا پائیں گے اپنے پاس توریت اور انجیل میں (ف۲۹۸) وہ انہیں بھلائی کا حکم دے گا اور برائی سے منع کرے گا اور ستھری چیزیں ان کے لیے حلال فرمائے گا اور گندی چیزیں ان پر حرام کرے گا اور ان پر سے وہ بوجھ (ف۲۹۹) اور گلے کے پھندے (ف۳۰۰) جو ان پر تھے اتا رے گا، تو وہ جو اس پر (ف۳۰۱) ایمان لائیں اور اس کی تعظیم کریں اور اسے مدد دیں اور اس نور کی پیروی کریں جو اس کے ساتھ اترا (ف۳۰۲) وہی بامراد ہوئے،'),
 (93,7,158,'تم فرماؤ اے لوگو! میں تم سب کی طرف اس اللہ کا رسول ہوں (ف۳۰۳) کہ آسمانوں اور زمین کی بادشاہی اسی کو ہے اس کے سوا کوئی معبود نہیں جلائے اور مارے تو ایمان لاؤ اللہ اور اس کے رسول بے پڑھے غیب بتانے والے پر کہ اللہ اور اس کی باتوں پر ایمان لاتے ہیں اور ان کی غلامی کرو کہ تم راہ پاؤ،'),
 (93,7,159,'اور موسیٰ کی قوم سے ایک گروہ ہے کہ حق کی راہ بتا تا اور اسی سے (ف۳۰۴) انصاف کرتا،'),
 (93,7,160,'اور ہم نے انہیں بانٹ دیا بارہ قبیلے گروہ گروہ، اور ہم نے وحی بھیجی موسیٰ کو جب اس سے اس کی قوم نے (ف۳۰۵) پانی ما نگا کہ اس پتھر پر اپنا عصا مارو تو اس میں سے بارہ چشمے پھوٹ نکلے (ف۳۰۶) ہر گروہ نے اپنا گھاٹ پہچان لیا، اور ہم نے ان پر ابر کا سائبان کیا (ف۳۰۷) اور ان پر من و سلویٰ اتارا، کھاؤ ہماری دی ہوئی پاک چیزیں اور انہوں نے (ف۳۰۸) ہمارا کچھ نقصان نہ کیا لیکن اپنی ہی جانوں کا برا کرتے ہیں،'),
 (93,7,161,'اور یاد کرو جب ان (ف۳۰۹) سے فرمایا گیا اس شہر میں بسو (ف۳۱۰) اور اس میں جو چاہو کھاؤ اور کہو گناہ اترے اور دروازے میں سجدہ کرتے داخل ہو ہم تمہارے گناہ بخش دیں گے، عنقریب نیکوں کو زیادہ عطا فرمائیں گے،'),
 (93,7,162,'تو ان میں کے ظالموں نے بات بدل دی اس کے خلاف جس کا انہیں حکم تھا (ف۳۱۱) تو ہم نے ان پر آسمان سے عذاب بھیجا بدلہ ان کے ظلم کا (ف۳۱۲)'),
 (93,7,163,'اور ان سے حال پوچھو اس بستی کا کہ دریا کنارے تھی (ف۳۱۳) جب وہ ہفتے کے بارے میں حد سے بڑھتے (ف۳۱۴) جب ہفتے کے دن ان کی مچھلیاں پانی پر تیرتی ان کے سامنے آتیں اور جو دن ہفتے کا نہ ہوتا نہ آتیں اس طرح ہم انہیں آزمانتے تھے ان کی بے حکمی کے سبب،'),
 (93,7,164,'اور جب ان میں سے ایک گروہ نے کہا کیوں نصیحت کرتے ہو ان لوگوں کو جنہیں اللہ ہلاک کرنے والا ہے یا انہیں سخت عذاب دینے والا، بولے تمہارے رب کے حضور معذرت کو (ف۳۱۵) اور شاید انہیں ڈر ہو(ف۳۱۶)'),
 (93,7,165,'پھر جب بھلا بیٹھے جو نصیحت انہیں ہوئی تھی ہم نے بچالیے وہ جو برائی سے منع کرتے تھے اور ظالموں کو برے عذاب میں پکڑا بدلہ ان کی نافرمانی کا،'),
 (93,7,166,'پھر جب انہوں نے ممانعت کے حکم سے سرکشی کی ہم نے ان سے فرمایا ہوجاؤ بند ر دھتکارے ہوئے(ف۲۱۷)'),
 (93,7,167,'اور جب تمہارے رب نے حکم سنادیا کہ ضرور قیامت کے دن تک ان (ف۳۱۸) پر ایسے کو بھیجتا رہوں گا جو انہیں بری مار چکھائے (ف۳۱۹) بیشک تمہارا رب ضرور جلد عذاب والا ہے (ف۳۲۰) اور بیشک وہ بخشنے والا مہربان ہے (ف۳۲۱)'),
 (93,7,168,'اور انہیں ہم نے زمین میں متفرق کردیا گروہ گروہ، ان میں کچھ نیک ہیں (ف۳۲۲) اور کچھ اور طرح کے (ف۳۲۳) اور ہم نے انہیں بھلائیوں اور برائیوں سے آزمایا کہ کہیں وہ رجوع لائیں (ف۳۲۴)'),
 (93,7,169,'پھر ان کی جگہ ان کے بعد وہ (ف۳۲۵) ناخلف آئے کہ کتاب کے وارث ہوئے (ف۳۲۶) اس دنیا کا مال لیتے ہیں (ف۳۲۷) اور کہتے اب ہماری بخشش ہوگی (ف۳۲۸) اور اگر ویسا ہی مال ان کے پاس اور آئے تو لے لیں (ف۳۲۹) کیا ان پر کتاب میں عہد نہ لیا گیا کہ اللہ کی طرف نسبت نہ کریں مگر حق اور انہوں نے اسے پڑھا (ف۳۳۰) اور بیشک پچھلا گھر بہتر ہے پرہیزگاروں کو (ف۳۳۱) تو کیا تمہیں عقل نہیں،'),
 (93,7,170,'اور وہ جو کتاب کو مضبوط تھامتے ہیں (ف۳۳۲) اور انہوں نے نماز قائم رکھی، ہم نیکوں کا نیگ (اجر) نہیں گنواتے،'),
 (93,7,171,'اور جب ہم نے پہاڑ ان پر اٹھایا گویا وہ سائبان ہے اور سمجھے کہ وہ ان پر گر پڑے گا (ف۳۳۳) تو جو ہم نے تمہیں دیا زور سے (ف۳۳۴) اور یاد کرو جو اس میں ہے کہ کہیں تم پرہیزگار ہو،'),
 (93,7,172,'اور اے محبوب! یاد کرو جب تمہارے رب نے اولاد آدم کی پشت سے ان کی نسل نکالی اور انہیں خود ان پر گواہ کیا، کیا میں تمہارا رب نہیں (ف۳۳۵) سب بولے کیوں نہیں ہم گواہ ہوئے (ف۳۳۶) کہ کہیں قیامت کے دن کہو کہ ہمیں اس کی خبر نہ تھی (ف۳۳۷)'),
 (93,7,173,'یا کہو کہ شرک تو پہلے ہمارے باپ دادا نے کیا اور ہم ان کے بعد بچے ہوئے (ف۳۳۸) تو کیا تو ہمیں اس پر ہلاک فرمائے گا جو اہل باطل نے کیا (ف۳۳۹)'),
 (93,7,174,'اور ہم اسی طرح آیتیں رنگ رنگ سے بیان کرتے ہیں (ف۳۴۰) اور اس لیے کہ کہیں وہ پھر آئیں(ف۳۴۱)'),
 (93,7,175,'اور اے محبوب! انہیں اس کا احوال سناؤ جسے ہم نے اپنی آیتیں دیں (ف۳۴۲) تو وہ ان سے صاف نکل گیا (ف۳۴۳) تو شیطان اس کے پیچھے لگا تو گمراہوں میں ہوگیا،'),
 (93,7,176,'اور ہم چاہتے تو آیتوں کے سبب اسے اٹھالیتے (ف۳۴۴) مگر وہ تو زمین پکڑ گیا (ف۳۴۵) اور اپنی خواہش کا تابع ہوا تو اس کا حال کتے کی طرح ہے تو اس پر حملہ کرے تو زبان نکالے اور چھوڑ دے تو زبان نکالے (ف۲۴۶) یہ حال ہے ان کا جنہوں نے ہماری آیتیں جھٹلائیں تو تم نصیحت سناؤ کہ کہیں وہ دھیان کریں،'),
 (93,7,177,'کیا بری کہاوت ہے ان کی جنہوں نے ہماری آیتیں جھٹلائیں اور اپنی ہی جان کا برا کرتے تھے،'),
 (93,7,178,'جسے اللہ راہ دکھائے تو وہی راہ پر ہے، اور جسے گمراہ کرے تو وہی نقصان میں رہے،'),
 (93,7,179,'اور بیشک ہم نے جہنم کے لیے پیدا کیے بہت جن اور آدمی (ف۳۴۷) اور دل رکھتے ہیں جن میں سمجھ نہیں (ف۳۴۸) اور وہ آنکھیں جن سے دیکھتے نہیں (ف۳۴۹) اور وہ کان جن سے سنتے نہیں (ف۳۵۰) وہ چوپایوں کی طرح ہیں (ف۳۵۱) بلکہ ان سے بڑھ کر گمراہ (ف۳۵۲) وہی غفلت میں پڑے ہیں،'),
 (93,7,180,'اور اللہ ہی کے ہیں بہت اچھے نام (ف۳۵۳) تو اسے ان سے پکارو اور انہیں چھوڑ دو جو اس کے ناموں میں حق سے نکلتے ہیں (ف۳۵۴) وہ جلد اپنا کیا پائیں گے،'),
 (93,7,181,'اور ہمارے بنائے ہوؤں میں ایک گروہ وہ ہے کہ حق بتائیں اور اس پر انصاف کریں(ف۳۵۵)'),
 (93,7,182,'اور جنہوں نے ہماری آیتیں جھٹلائیں جلد ہم انہیں آہستہ آہستہ (ف۳۵۶) عذاب کی طرف لے جائیں گے جہاں سے انہیں خبر نہ ہوگی'),
 (93,7,183,'اور میں انہیں ڈھیل دوں گا (ف۳۵۷) بیشک میری خفیہ تدبیر بہت پکی ہے(ف۳۵۸)'),
 (93,7,184,'کیا سوچتے نہیں کہ ان کے صاحب کو جنوں سے کچھ علاقہ نہیں، وہ تو صا ف ڈر سنانے والے ہیں(ف۳۵۹)'),
 (93,7,185,'کیا انہو ں نے نگاہ نہ کی آسمانوں اور زمین کی سلطنت میں اور جو جو چیز اللہ نے بنائی (ف۳۶۰) اور یہ کہ شاید ان کا وعدہ نزدیک آگیا ہو (ف۳۶۱) تو اس کے بعد اور کونسی بات پر یقین لائیں گے(ف۳۶۲)'),
 (93,7,186,'جسے اللہ گمراہ کرے اسے کوئی راہ دکھانے والا نہیں اور انہیں چھوڑتا ہے کہ اپنی سرکشی میں بھٹکا کریں،'),
 (93,7,187,'تم سے قیامت کو پوچھتے ہیں (ف۳۶۳) کہ وہ کب کو ٹھہری ہے تم فرماؤ اس کا علم تو میرے رب کے پاس ہے، اسے وہی اس کے وقت پر ظاہر کرے گا (ف۳۶۴) بھاری پڑ رہی ہے آسمانوں او رزمین میں، تم پر نہ آئے گی مگر اچانک، تم سے ایسا پوچھتے ہیں گویا تم نے اسے خوب تحقیق کر رکھا ہے، تم فرماؤ اس کا علم تو اللہ ہی کے اس ہے لیکن بہت لوگ جانتے نہیں (ف۳۶۵)'),
 (93,7,188,'تم فرماؤ میں اپنی جان کے بھلے برے کا خودمختار نہیں (ف۳۶۶) مگر جو اللہ چاہے (ف۳۶۷) اور اگر میں غیب جان لیا کرتا تو یوں ہوتا کہ میں نے بہت بھلائی جمع کرلی، اور مجھے کوئی برائی نہ پہنچی (ف۳۶۸) میں تو یہی ڈر (ف۳۶۹) اور خوشی سنانے والا ہوں انہیں جو ایمان رکھتے ہیں،'),
 (93,7,189,'وہی ہے جس نے تمہیں ایک جان سے پیدا کیا (ف۳۷۰) اور اسی میں سے اس کا جوڑا بنایا (ف۳۷۱) کہ اس سے چین پائے پھر جب مرد اس پر چھایا اسے ایک ہلکا سا پیٹ رہ گیا (ف۳۷۲) تو اسے لیے پھراکی پھر جب بوجھل پڑی دونوں نے اپنے رب سے دعا کی ضرور اگر تو ہمیں جیسا چاہیے بچہ دے گا تو بیشک ہم شکر گزار ہوں گے،'),
 (93,7,190,'پھر جب اس نے انہیں جیسا چاہیے بچہ عطا فرمایا انہوں نے اس کی عطا میں اس کے ساجھی ٹھہرائے تو اللہ کو برتری ہے ان کے شرک سے (ف۳۷۳)'),
 (93,7,191,'کیا اسے شریک کرتے ہیں جو کچھ نہ بنائے (ف۳۷۴) اور وہ خود بنائے ہوئے ہیں،'),
 (93,7,192,'اور نہ وہ ان کو کوئی مدد پہنچاسکیں اور نہ اپنی جانو ں کی مدد کریں (ف۳۷۵)'),
 (93,7,193,'اور اگر تم انہیں (ف۳۷۶) راہ کی طرف بلاؤ تو تمہارے پیچھے نہ آئیں (ف۳۷۷) تم پر ایک سا ہے چاہے انہیں پکارو یا چپ رہو(ف۳۷۸)'),
 (93,7,194,'بیشک وہ جن کو تم اللہ کے سوا پوجتے ہو تمہاری طرح بندے ہیں (ف۳۷۹) تو انہیں پکارو پھر وہ تمہیں جواب دیں اگر تم سچے ہو،'),
 (93,7,195,'کیا ان کے پاؤں ہیں جن سے چلیں یا ان کے ہاتھ ہیں جن سے گرفت کریں یا ان کے آنکھیں ہیں جن سے دیکھیں یا ان کے کان ہیں جن سے سنیں (ف۳۸۰) تم فرماؤ کہ اپنے شریکوں کو پکارو اور مجھ پر داؤ چلو اور مجھے مہلت نہ دو (ف۳۸۱)'),
 (93,7,196,'بیشک میرا والی اللہ ہے جس نے کتاب ا تاری (ف۳۸۲) اور وہ نیکوں کو دوست رکھتا ہے(ف۳۸۳)'),
 (93,7,197,'اور جنہیں اس کے سوا پوجتے ہو وہ تمہاری مدد نہیں کرسکتے، اور نہ خود اپنی مدد کریں (ف۳۸۴)'),
 (93,7,198,'اور اگر تم انہیں راہ کی طرف بلاؤ تو نہ سنیں اور تو انہیں دیکھے کہ وہ تیری طرف دیکھ رہے ہیں (ف۳۸۵) اور انہیں کچھ بھی نہیں سوجھتا،'),
 (93,7,199,'اے محبوب! معاف کرنا اختیار کرو اور بھلائی کا حکم دو اور جاہلوں سے منہ پھیرلو،'),
 (93,7,200,'اور اے سننے والے اگر شیطان تجھے کوئی کونچا دے (کسی برے کام پر اکسائے) تو اللہ کی پناہ مانگ بیشک وہی سنتا جانتا ہے،'),
 (93,7,201,'بیشک وہ جو ڈر والے ہیں جب انہیں کسی شیطانی خیال کی ٹھیس لگتی ہے ہوشیار ہوجاتے ہیں اسی وقت ان کی آنکھیں کھل جاتی ہیں(ف۳۸۷)'),
 (93,7,202,'اور وہ جو شیطانوں کے بھائی ہیں (ف۳۸۸) شیطان انہیں گمراہی میں کھینچتے ہیں پھر کمی نہیں کرتے،'),
 (93,7,203,'اور اے محبوب! جب تم ان کے پاس کوئی آیت نہ لاؤ تو کہتے ہیں تم نے دل سے کیوں نہ بنائی تم فرما ؤ میں تو اسی کی پیروی کرتا ہوں جو میری طرف میرے رب سے وحی ہوتی ہے یہ تمہارے رب کی طرف سے آنکھیں کھولنا ہے اور ہدایت اور رحمت مسلمانوں کے لیے،'),
 (93,7,204,'اور جب قرآن پڑھا جائے تو اسے کان لگا کر سنو اور خاموش رہو کہ تم پر رحم ہو(ف۳۸۹)'),
 (93,7,205,'اور اپنے رب کو اپن ے دل میں یاد کرو (ف۳۹۰) زاری اور ڈر سے اور بے آواز نکلے زبان سے صبح اور شام (ف۳۹۱) اور غافلوں میں نہ ہونا،'),
 (93,7,206,'بیشک وہ جو تیرے رب کے پاس ہیں (ف۳۹۲) اس کی عبادت سے تکبر نہیں کرتے اور اس کی پاکی بولتے اور اسی کو سجدہ کرتے ہیں (ف۳۹۳) السجدة ۔۵'),
 (93,8,1,'اے محبوب! تم سے غنیمتوں کو پوچھتے ہیں (ف۲) تم فرماؤ غنیمتوں کے مالک اللہ اور رسول ہیں (ف۳) تو اللہ ڈرو (ف۴) اور اپنے آ پس میں میل (صلح صفائی) رکھو اور اللہ اور رسول کا حکم مانو اگر ایمان رکھتے ہو،'),
 (93,8,2,'ایمان والے وہی ہیں کہ جب اللہ یاد کیا جائے (ف۵) ان کے دل ڈر جائیں اور جب ان پر اس کی آیتیں پڑھی جائیں ان کا ایمان ترقی پائے اور اپنے رب ہی پر بھروسہ کریں (ف۶)'),
 (93,8,3,'وہ جو نماز قائم رکھیں اور ہمارے دیے سے کچھ ہماری راہ میں خرچ کریں،'),
 (93,8,4,'یہی سچے مسلمان ہیں، ان کے لیے درجے ہیں ان کے رب کے پاس (ف۷) اور بخشش ہے اور عزت کی روزی (ف۸)'),
 (93,8,5,'جس طرح اے محبوب! تمہیں تمہارے رب نے تمہارے گھر سے حق کے ساتھ برآمد کیا (ف۹) اور بیشک مسلمانوں کا ایک گروہ اس پر ناخوش تھا (ف۱۰)'),
 (93,8,6,'سچی بات میں تم سے جھگڑتے تھے (ف۱۱) بعد اس کے کہ ظاہر ہوچکی (ف۱۲) گویا وہ آنکھوں دیکھی موت کی طرف ہانکے جاتے ہیں (ف۱۳)'),
 (93,8,7,'اور یاد کرو جب اللہ نے تمہیں وعدہ دیا تھا کہ ان دونوں گروہوں (ف۱۴) میں ایک تمہارے لیے ہے اور تم یہ چاہتے تھے کہ تمہیں وہ ملے جس میں کانٹے کا کھٹکا نہیں (کوئی نقصان نہ ہو) (ف۱۵) اور اللہ یہ چاہتا تھا کہ اپنے کلام سے سچ کو سچ کر دکھائے (ف۱۶) اور کافروں کی جڑ کا ٹ دے(ف۱۷)'),
 (93,8,8,'کہ سچ کو سچ کرے اور جھوٹ کو جھوٹا (ف۱۸) پڑے برا مانیں مجرم،'),
 (93,8,9,'جب تم اپنے رب سے فریا د کرتے تھے (ف۱۹) تو اس نے تمہاری سن لی کہ میں تمہیں مدد دینے والا ہوں ہزاروں فرشتوں کی قطار سے (ف۲۰)'),
 (93,8,10,'اور یہ تو اللہ نے کیا مگر تمہاری خوشی کو اور اس لیے کہ تمہارے دل چین پائیں، اور مدد نہیں مگر اللہ کی طرف سے (ف۲۱) بیشک اللہ غالب حکمت والا ہے،'),
 (93,8,11,'جب اس نے تمہیں اونگھ سے گھیر دیا تو اس کی طرف سے چین (تسکین) تھی (ف۲۲) اور آسمان سے تم پر پانی اتارا کہ تمہیں اس سے ستھرا کردے اور شیطان کی ناپاکی تم سے دور فرمادے اور تمہارے دلو ں کی ڈھارس بندھائے اور اس سے تمہارے قدم جمادے(ف۲۳)'),
 (93,8,12,'جب اے محبوب! تمہارا رب فرشتوں کو وحی بھیجتا تھا کہ میں تمہارے ساتھ ہوں تم مسلمانوں کو ثابت رکھو (ف۲۴) عنقریب میں کافروں کے دلوں میں ہیبت ڈالوں گا تو کافروں کی گردنوں سے اوپر مارو اور ان کی ایک ایک پور (جوڑ) پر ضرب لگا ؤ (ف۲۵)'),
 (93,8,13,'یہ اس لیے کہ انہوں نے اللہ اور اس کے رسول سے مخا لفت کی اور جو اللہ اور اس کے رسول سے مخالفت کرے تو بیشک اللہ کا عذاب سخت ہے،'),
 (93,8,14,'یہ تو چکھو (ف۲۶) اور اس کے ساتھ یہ ہے کہ کافروں کو آ گ کا عذاب ہے (ف۲۷)'),
 (93,8,15,'اے ایمان والو! جب کافروں کے لام (لشکر) سے تمہارا مقابلہ ہو تو انہیں پیٹھ نہ دو (ف۲۸)'),
 (93,8,16,'اور جو اس دن انہیں پیٹھ دے گا مگر لڑائی کا ہنرَ کرنے یا اپنی جماعت میں جاملنے کو، تو وہ اللہ کے غضب میں پلٹا اور اس کا ٹھکانا دوزخ ہے، اور کیا بری جگہ ہے پلٹنے کی، (ف۲۹)'),
 (93,8,17,'تو تم نے انہیں قتل نہ کیا بلکہ اللہ نے (ف۳۰) انہیں قتل کیا، اور اے محبوب! وہ خاک جو تم نے پھینکی تھی بلکہ اللہ نے پھینکی اور اس لیے کہ مسلمانوں کو اس سے اچھا انعام عطا فرمائے، بیشک اللہ سنتا جانتا ہے،'),
 (93,8,18,'یہ (ف۳۱) تو لو اور اس کے ساتھ یہ ہے کہ اللہ کافروں کا داؤ سست کرنے والا ہے،'),
 (93,8,19,'اے کافرو! اگر تم فیصلہ مانگتے ہو تو یہ فیصلہ تم پر آچکا (ف۳۲) اور اگر با ز ا ٓ ؤ (ف۳۳) تو تمہارا بھلا ہے اور اگر تم پھر شرارت کرو تو ہم پھر نہ دیں گے اور تمہارا جتھا تمہیں کچھ کام نہ دے گا چاہے کتنا ہی بہت ہو اور اس کے ساتھ یہ ہے کہ اللہ مسلمانوں کے ساتھ ہے،'),
 (93,8,20,'اے ایمان والو! اللہ اور اس کے رسول کا حکم مانو (ف۳۴) اور سن سنا کہ اسے نہ پھرو،'),
 (93,8,21,'اور ان جیسے نہ ہونا جنہوں نے کہا ہم نے سنا او ر وہ نہیں سنتے (ف۳۵)'),
 (93,8,22,'بیشک سب جانوروں میں بدتر اللہ کے نزدیک وہ ہیں جو بہرے گونگے ہیں جن کو عقل نہیں(ف۳۶)'),
 (93,8,23,'اور اگر اللہ ان میں کچھ بھلائی (ف۳۷) جانتا تو انہیں سنادیتا اور اگر (ف۳۸) سنا دیتا جب بھی انجام کا ر منہ پھیر کر پلٹ جاتے (ف۳۹)'),
 (93,8,24,'اے ایمان والو! اللہ اور اس کے رسول کے بلانے پر حاضر ہو (ف۴۰) جب رسول تمہیں اس چیز کے لیے بلائیں جو تمہیں زندگی بخشے گی (ف۴۱) اور جان لو کہ اللہ کا حکم آدمی اور اس کے دلی ارادوں میں حائل ہوجا تا ہے اور یہ کہ تمہیں اس کی طرف اٹھنا ہے،'),
 (93,8,25,'اور اس فتنہ سے ڈرتے رہو جو ہرگز تم میں خاص ظالموں کو ہی نہ پہنچے گا (ف۴۲) اور جان لو کہ اللہ کا عذاب سخت ہے،'),
 (93,8,26,'اور یاد کرو (ف۴۳) جب تم تھوڑے تھے ملک میں دبے ہوئے (ف۴۴) ڈرتے تھے کہ کہیں لوگ تمہیں اچک نہ لے جائیں تو اس نے تمہیں (ف۴۵) جگہ دی اور اپنی مدد سے زور دیا اور ستھری چیزیں تمہیں روزی دیں (ف۴۶) کہ کہیں تم احسان مانو،'),
 (93,8,27,'اے ایمان والو! اللہ اور رسول سے دغا نہ کرو (ف۴۷) اور نہ اپنی امانتوں میں دانستہ خیانت،'),
 (93,8,28,'اور جان رکھو کہ تمہارے مال اور تمہاری اولاد سب فتنہ ہے (ف۴۸) اور اللہ کے پاس بڑا ثواب ہے(ف۴۹)'),
 (93,8,29,'اے ایمان والو! اگر اللہ سے ڈرو گے (ف۵۰) تو تمہیں وہ دیگا جس سے حق کو باطل سے جدا کرلو اور تمہاری برائیاں اتار دے گا اور تمہیں بخش دے گا اور اللہ بڑے فضل والا ہے،'),
 (93,8,30,'اور اے محبوب یاد کرو جب کافر تمہارے ساتھ مکر کرتے تھے کہ تمہیں بند کرلیں یا شہید کردیں یا نکا ل دیں (ف۱۵۱) اپنا سا مکر کرتے تھے اور اللہ اپنی خفیہ تدبیر فرماتا تھا اور اللہ کی خفیہ تدبیر سب سے بہتر،'),
 (93,8,31,'اور جب ان پر ہماری آیتیں پڑھی جائیں تو کہتے ہیں ہاں ہم نے سنا ہم چاہتے تو ایسی ہم بھی کہہ دیتے یہ تو نہیں مگر اگلوں کے قصے (ف۵۲)'),
 (93,8,32,'اور جب بولے (ف۵۳) کہ اے اللہ اگر یہی (قرآن) تیری طرف سے حق ہے تو ہم پر آسمان سے پتھر برسا یا کوئی دردناک عذاب ہم پر لا،'),
 (93,8,33,'اور اللہ کا کام نہیں کہ انہیں عذاب کرے جب تک اے محبوب! تم ان میں تشریف فرما ہو (ف۵۴) اور اللہ انہیں عذاب کرنے والا نہیں جب تک وہ بخشش مانگ رہے ہیں (ف۵۵)'),
 (93,8,34,'اور انہیں کیا ہے کہ اللہ انہیں عذاب نہ کرے وہ تو مسجد حرام سے روک رہے ہیں (ف۵۶) اور وہ اس کے اہل نہیں (ف۵۷) اس کے اولیاء تو پرہیزگار ہی ہیں مگر ان میں اکثر کو علم نہیں،'),
 (93,8,35,'اور کعبہ کے پاس ان کی نماز نہیں مگر سیٹی اور تالی (ف۵۸) تو اب عذاب چکھو (ف۵۹) بدلہ اپنے کفر کا،'),
 (93,8,36,'بیشک کافر اپنے مال خرچ کرتے ہیں کہ اللہ کی راہ سے روکیں (ف۶۰) تو اب انہیں خرچ کریں گے پھر وہ ان پر پچھتاوا ہوں گے (ف۶۱) پھر مغلوب کردیے جائیں گے اور کافروں کا حشر جہنم کی طرف ہوگا،'),
 (93,8,37,'اس لیے کہ اللہ گندے کو ستھرے سے جدا فرمادے (ف۶۲) اور نجاستوں کو تلے اوپر رکھ کر سب ایک ڈھیر بناکر جہنم میں ڈال دے وہی نقصان پانے والے ہیں (ف۶۳)'),
 (93,8,38,'تم کافروں سے فرماؤ اگر وہ باز رہے تو جو ہو گزرا وہ انہیں معاف فرمادیا جائے گا (ف۶۴) اور اگر پھر وہی کریں تو اگلوں کا دستور گزر چکا ہے (ف۶۵)'),
 (93,8,39,'اور اگر ان سے لڑو یہاں تک کہ کوئی فساد (ف۶۶) باقی نہ رہے اور سارا دین اللہ ہی کا ہوجائے، اگر پھر وہ باز رہیں تو اللہ ان کے کام دیکھ رہا ہے،'),
 (93,8,40,'اور اگر وہ پھریں (ف۲۷) تو جان لو کہ اللہ تمہارا مولیٰ ہے (ف۶۸) تو کیا ہی اچھا مولیٰ اور کیا ہی اچھا مددگار،'),
 (93,8,41,'اور جان لو کہ جو کچھ غنیمت لو (ف۶۹) تو اس کا پانچواں حصہ خاص اللہ اور رسول و قرابت داروں اور یتیموں اور محتاجوں اور مسافروں کا ہے (ف۷۰) اگر تم ایمان لائے ہو اللہ پر اور اس پر جو ہم نے اپنے بندے پر فیصلہ کے دن اتارا جس دن دونوں فوجیں ملیں تھیں (ف۷۱) اور اللہ سب کچھ کرسکتا ہے،'),
 (93,8,42,'جب تم نالے کے کنا رے تھے (ف۷۲) اور کافر پرلے کنا رے اور قا فلہ (ف۷۳) تم سے ترائی میں (ف۷۴) اور اگر تم آپس میں کوئی وعدہ کرتے تو ضرور وقت پر برابر نہ پہنچتے (ف۷۵) لیکن یہ اس لیے کہ اللہ پورا کرے جو کام ہونا ہے (ف۷۶) کہ جو ہلاک ہو دلیل سے ہلاک ہو (ف۷۷) اور جو جئے دلیل سے جئے (ف۷۸) اور بیشک اللہ ضرور سنتا جانتا ہے،'),
 (93,8,43,'جب کہ اے محبوب! اللہ ٹمہیں کافروں کو تمہاری خواب میں تھو ڑا دکھاتا تھا (ف۷۹) اور اے مسلمانو! اگر وہ تمہیں بہت کرکے دکھاتا تو ضرور تم بزدلی کرتے اور معاملہ میں جھگڑا ڈالتے (ف۸۰) مگر اللہ نے بچا لیا (ف۸۱) بیشک وہ دلوں کی بات جانتا ہے،'),
 (93,8,44,'او ر جب لڑتے وقت (ف۸۲) تمہیں کا فر تھو ڑے کرکے دکھائے (ف۸۳) اور تمہیں ان کی نگاہوں میں تھو ڑا کیا (ف۷۴) کہ اللہ پو را کرے جو کام ہونا ہے (ف۸۵) اور اللہ کی طرف سب کاموں کی رجوع ہے،'),
 (93,8,45,'اے ایمان والو! جب کسی فوج سے تمہارا مقابلہ ہو تو ثابت قدم رہو اور اللہ کی یاد بہت کرو (ف۸۶) کہ تم مراد کو پہنچو،'),
 (93,8,46,'اور اللہ اور اس کے رسول کا حکم مانو اور آپس میں جھگڑ و نہیں کہ پھر بز د لی کرو گے اور تمہاری بندھی ہوئی ہوا جاتی رہے گی (ف۸۷) اور صبر کرو، بیشک اللہ صبر والوں کے ساتھ ہے (ف۸۸)'),
 (93,8,47,'اور ان جیسے نہ ہوتا جو اپنے گھر سے نکلے اتراتے اور لوگوں کے دکھانے کو اور اللہ کی راہ سے روکتے (ف۸۹) اور ان کے سب کام اللہ کے قابو میں ہیں،'),
 (93,8,48,'اور جبکہ شیطان نے ان کی نگاہ میں ان کے کام بھلے کر دکھائے (ف۹۰) اور بولا آج تم پر کوئی شخص غالب آنے والا نہیں اور تم میری پناہ میں ہو تو جب دونوں لشکر آمنے سامنے ہوئے الٹے پاؤں بھاگا اور بولا میں تم سے الگ ہوں (ف۹۱) میں وہ دیکھتا ہوں جو تمہیں نظر نہیں آتا (ف۹۲) میں اللہ سے ڈرتا ہوں (ف۹۳) اور اللہ کا عذاب سخت ہے،'),
 (93,8,49,'جب کہتے تھے منافق (ف۹۴) اور وہ جن کے دلوں میں ا ٓزا ر ہے (ف۹۵) کہ یہ مسلمان اپنے دین پر مغرور ہیں (ف۹۶) اور جو اللہ پر بھروسہ کرے (ف۹۷) تو بیشک اللہ (ف۹۸) غالب حکمت والا ہے،'),
 (93,8,50,'اور کبھی تو دیکھے جب فرشتے کافروں کی جان نکالتے ہیں مار رہے ہیں ان کے منہ پر او ر ان کی پیٹھ پر (ف۹۹) اور چکھو آ گ کا عذاب،'),
 (93,8,51,'یہ (ف۱۰۰) بدلہ ہے اس کا جو تمہارے ہاتھوں نے آگے بھیجا (ف۱۰۱) اور اللہ بندوں پر ظلم نہیں کرتا (ف۱۰۲)'),
 (93,8,52,'جیسے فرعون والوں اور ان سے اگلوں کا دستور (ف۱۰۳) وہ اللہ کی آیتوں کے منکر ہوئے تو اللہ نے انہیں ان کے گناہوں پر پکڑا بیشک اللہ قوت والا سخت عذاب و ا لا ہے،'),
 (93,8,53,'یہ اس لیے کہ اللہ کسی قوم سے جو نعمت انہیں دی تھی بدلتا نہیں جب تک وہ خود نہ بدل جائیں (ف۱۰۴) اور بیشک اللہ سنتا جانتا ہے'),
 (93,8,54,'جیسے فرعون والوں اور ان سے اگلوں کا دستور، انہوں نے اپنے رب کی آیتیں جھٹلائیں تو ہم نے ان کو ان کے گناہوں کے سبب ہلاک کیا اور ہم نے فرعون والوں کو ڈبو دیا (ف۱۰۵) اور وہ سب ظالم تھے،'),
 (93,8,55,'بیشک سب جانوروں (کا فر و ں) میں بدتر اللہ کے نزدیک وہ ہیں جنہوں نے کفر کیا اور ایمان نہیں لاتے،'),
 (93,8,56,'وہ جن سے تم نے معاہدہ کیا تھا پھر ہر با ر اپنا عہد توڑ دیتے ہیں (ف۱۰۶) اور ڈرتے نہیں (ف۱۰۷)'),
 (93,8,57,'تو اگر تم انہیں کہیں لڑائی میں پا ؤ تو انہیں ایسا قتل کرو جس سے ان کے پس ماندوں کو بھگاؤ (ف۱۰۸) اس امید پر کہ شاید انہیں عبرت ہو (ف۱۰۹)'),
 (93,8,58,'اور اگر تم کسی قوم سے دغا کا اندیشہ کرو (ف۱۱۰) تو ان کا عہد ان کی طرف پھینک دو برابری پر (ف۱۱۱) بیشک دغا والے اللہ کو پسند نہیں،'),
 (93,8,59,'اور ہرگز کا فر اس گھمنڈ میں نہ رہیں کہ وہ (ف۱۱۲) ہاتھ سے نکل گئے بیشک وہ عاجز نہیں کرتے (ف۱۱۳)'),
 (93,8,60,'اور ان کے لیے تیار رکھو جو قوت تمہیں بن پڑے (ف۱۱۴) اور جتنے گھوڑے باندھ سکو کہ ان سے ان کے دلوں میں دھاک بٹھاؤ جو اللہ کے دشمن ہیں (ف۱۱۵) اور ان کے سوا کچھ اوروں کے دلوں میں جنہیں تم نہیں جانتے (ف۱۱۶) اللہ انہیں جانتا ہے اور اللہ کی راہ میں جو کچھ خرچ کرو گے تمہیں پورا دیا جائے گا (ف۱۱۷) اور کسی طرح گھاٹے میں نہ رہو گے،'),
 (93,8,61,'اور اگر وہ صلح کی طرف جھکیں تو تم بھی جھکو (ف۱۱۸) اور اللہ پر بھروسہ رکھو، بیشک وہی ہے سنتا جانتا،'),
 (93,8,62,'اور اگر وہ تمہیں فریب دیا چاہیں (ف۱۱۹) تو بیشک اللہ تمہیں کافی ہے، وہی ہے جس نے تمہیں زور دیا اپنی مدد کا اور مسلمانوں کا،'),
 (93,8,63,'اور ان کے دلوں میں میل کردیا (ف۱۲۰) اگر تم زمین میں جو کچھ ہے سب خرچ کردیتے ان کے دل نہ ملا سکتے (ف۱۲۱) لیکن اللہ نے ان کے دل ملادیئے، بیشک وہی ہے غالب حکمت والا،'),
 (93,8,64,'اے غیب کی خبریں بتانے والے (نبی) اللہ تمہیں کافی ہے اور یہ جتنے مسلمان تمہارے پیرو ہوئے، (ف۱۲۲)'),
 (93,8,65,'اے غیب کی خبریں بتانے والے! مسلمانوں کو جہاد کی ترغیب دو اگر تم میں کے بیس صبر والے ہوں گے دو سو پر غالب ہوں گے اور اگر تم میں کے سو ہوں تو کافروں کے ہزا ر پر غالب آئیں گے اس لیے کہ وہ سمجھ نہیں رکھتے، (ف۱۲۳)'),
 (93,8,66,'اب اللہ نے تم پر سے تخفیف فرمائی اور اسے علم کہ تم کمزو ر ہو تو اگر تم میں سو صبر والے ہوں د و سو پر غالب آئیں گے اور اگر تم میں کے ہزار ہوں تو دو ہزار پر غالب ہوں گے اللہ کے حکم سے اور اللہ صبر والوں کے ساتھ ہے،'),
 (93,8,67,'کسی نبی کو لائئق نہیں کہ کافروں کو زندہ قید کرلے جب تک زمین میں ان کا خون خوب نہ بہائے (ف۱۲۴) تم لوگ دنیا کا مال چا ہتے ہو (ف۱۲۵) او ر اللہ آخرت چاہتا ہے (ف۱۲۶) اور اللہ غالب حکمت والا ہے'),
 (93,8,68,'اگراللہ پہلے ایک بات لکھ نہ چکا ہوتا (ف۱۲۷) تو اے مسلمانو! تم نے جو کافروں سے بدلے کا مال لے لیا اس میں تم پر بڑا عذاب آتا،'),
 (93,8,69,'تو کھاؤ جو غنیمت تمہیں ملی حلال پاکیزہ (ف۱۲۸) اور اللہ سے ڈرتے رہو بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,8,70,'اے غیب کی خبریں بتانے والے جو قیدی تمہارے ہاتھ میں ہیں ان سے فرماؤ (ف۱۲۹) اگر اللہ نے تمہارے دل میں بھلائی جانی (ف۱۳۰) تو جو تم سے لیا گیا (ف۱۳۱) اس سے بہتر تمہیں عطا فرمائے گا اور تمہیں بخش دے گا اور اللہ بخشنے والا مہربان ہے (ف۱۳۲)'),
 (93,8,71,'اور اے محبوب اگر وہ (ف۱۳۳) تم سے دغا چاہیں گے (ف۱۳۴) تو اس سے پہلے اللہ ہی کی خیانت کرچکے ہیں جس پر اس نے اتنے تمہارے قابو میں دے دیے (ف۱۳۵) اور اللہ جاننے والا حکمت والا ہے،'),
 (93,8,72,'بیشک جو ایمان لائے اور اللہ کے لیے (ف۱۳۶) گھر بار چھوڑے اور اللہ کی راہ میں اپنے مالوں اور جانوں سے لڑے (ف۱۳۷) اور وہ جنہوں نے جگہ دی اور مدد کی (ف۱۳۸) وہ ایک دوسرے کے وارث ہیں (ف۱۳۹) اور وہ جو ایمان لائے (ف۱۴۰) اور ہجرت نہ کی انہیں ان کا ترکہ کچھ نہیں پہنچتا جب تک ہجرت نہ کریں اور اگر وہ دین میں تم سے مدد چاہیں تو تم پر مدد دینا واجب ہے مگر ایسی قوم پر کہ تم میں ان میں معاہدہ ہے، اور اللہ تمہارے کام دیکھ رہا ہے،'),
 (93,8,73,'اور کافر ا ٓ پس میں ایک دوسرے کے وارث ہیں (ف۱۴۱) ایسا نہ کرو گے تو زمین میں فتنہ اور بڑا فساد ہوگا (ف۱۴۲)'),
 (93,8,74,'اور وہ جو ایمان لائے اور ہجرت کی اور اللہ کی راہ میں لڑے اور جنہوں نے جگہ دی اور مدد کی وہی سچے ایمان والے ہیں، ان کے لیے بخشش ہے اور عزت کی روزی (ف۱۴۳)'),
 (93,8,75,'اور جو بعد کو ایمان لائے اور ہجرت کی اور تمہارے ساتھ جہاد کیا وہ بھی تمہیں میں سے ہیں (ف۴۴) اور رشتہ والے ایک دوسرے سے زیادہ نزدیک ہیں اللہ کی کتاب میں (ف۱۴۵) بیشک اللہ سب کچھ جانتا ہے،'),
 (93,9,1,'بیزاری کا حکم سنانا ہے اللہ اور اس کے رسول کی طرف سے ان مشرکوں کو جن سے تمہارا معاہدہ تھا اور وہ قائم نہ رہے (ف۲)'),
 (93,9,2,'تو چا ر مہینے زمین پر چلو پھرو اور جان رکھو کہ تم اللہ کو تھکا نہیں سکتے (ف۳) اور یہ کہ اللہ کافروں کو رسوا کرنے والا ہے (ف۴)'),
 (93,9,3,'اور منادی پکار دیتا اللہ اور اس کے رسول کی طرف سے سب لوگوں میں بڑے حج کے دن (ف۵) کہ اللہ بیزار ہے، مشرکوں سے اور اس کا رسول تو اگر تم توبہ کرو (ف۶) تو تمہا را بھلا ہے اور اگر منہ پھیرو (ف۷) تو جان لو کہ اللہ کو نہ تھکا سکو گے (ف۸) اور کافروں کو خوشخبری سناؤ دردناک عذاب کی،'),
 (93,9,4,'مگر وہ مشرک جن سے تمہارہ معاہدہ تھا پھر انہوں نے تمہارے عہد میں کچھ کمی نہیں کی (ف۹) اور تمہارے مقابل کسی کو مدد نہ دی تو ان کا عہد ٹھہری ہوئی مدت تک پورا کرو، بیشک اللہ پرہیزگاروں کو دوست رکھتا ہے،'),
 (93,9,5,'پھر جب حرمت والے مہینے نکل جائیں تو مشرکوں کو مارو (ف۱۰) جہاں پا ؤ (ف۱۱) اور انہیں پکڑو اور قید کرو اور ہر جگہ ان کی تاک میں بیٹھو پھر اگر وہ توبہ کریں (ف۱۲) اور نماز قائم رکھیں اور زکوٰة دیں تو ان کی راہ چھوڑ دو (ف۱۳) بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,9,6,'اور اے محبوب اگر کوئی مشرک تم سے پناہ مانگے (ف۱۴) تو اسے پناہ دو کہ وہ اللہ کا کلام سنے پھر اسے اس کی امن کی جگہ پہنچا دو (ف۱۵) یہ اس لیے کہ وہ نادان لوگ ہیں (ف۱۶)'),
 (93,9,7,'مشرکوں کے لیے اللہ اور اس کے رسول کے پاس کوئی عہد کیونکر ہوگا (ف۱۷) مگر وہ جن سے تمہارا معاہدہ مسجد حرام کے پاس ہوا (ف۱۸) تو جب تک وہ تمہارے لیے عہد پر قائم رہیں تم ان کے لیے قائم رہو، بیشک پرہیزگار اللہ کو خوش آتے ہیں،'),
 (93,9,8,'بھلا کیونکر (ف۱۹) ان کا حال تو یہ ہے کہ تم پر قابو پائیں تو نہ قرابت کا لحاظ کریں نہ عہد کا، اپنے منہ سے تمہیں راضی کرتے ہیں (ف۲۰) اور ان کے دلوں میں انکار ہے اور ان میں اکثر بے حکم ہیں (ف۲۱)'),
 (93,9,9,'اللہ کی آیتوں کے بدلے تھو ڑے دام مول لیے (ف۲۲) تو اس کی راہ سے روکا (ف۲۳) بیشک وہ بہت ہی بڑے کام کرتے ہیں،'),
 (93,9,10,'کسی مسلمان میں نہ قراب کا لحاظ کریں نہ عہد کا (ف۲۴) اور وہی سرکش ہیں،'),
 (93,9,11,'پھر اگر وہ (ف۲۵) توبہ کریں اور نماز قائم رکھیں اور زکوٰة دیں تو وہ تمہارے دینی بھائی ہیں (ف۲۶) اور ہم آیتیں مفصل بیان کرتے ہیں جاننے والوں کے لیے (ف۲۷)'),
 (93,9,12,'اور اگر عہد کرکے اپنی قسمیں توڑیں اور تمہارے دین پر منہ آئیں تو کفر کے سرغنوں سے لڑو (ف۲۸) بیشک ان کی قسمیں کچھ نہیں اس امید پر کہ شاید وہ باز آئیں (ف۲۹)'),
 (93,9,13,'کیا اس قوم سے نہ لڑو گے جنہوں نے اپنی قسمیں توڑیں (ف۳۰) اور رسول کے نکالنے کا ارادہ کیا (ف۳۱) حالانکہ انہیں کی طرف سے پہلی ہوتی ہے، کیا ان سے ڈرتے ہو تو اللہ کا زیادہ مستحق ہے کہ اس سے ڈرو اگر ایمان رکھتے ہو،'),
 (93,9,14,'تو ان سے لڑو اللہ انہیں عذاب دیگا تمہارے ہاتھوں اور انہیں رسوا کرے گا (ف۳۲) اور تمہیں ان پر مدد دے گا (ف۳۳) اور ایمان والوں کا جی ٹھنڈا کرے گا،'),
 (93,9,15,'اور ان کے دلوں کی گھٹن دور فرمائے گا (ف۳۴) اور اللہ جس کی چاہے تو یہ قبول فرمائے (ف۳۵) اور اللہ علم و حکمت والا ہے،'),
 (93,9,16,'کیا اس گمان میں ہو کہ یونہی چھوڑ دیئے جاؤ گے اور ابھی اللہ نے پہچان نہ کرائی ان کی جو تم میں سے جہاد کریں گے (ف۳۶) اور اللہ اور اس کے رسول اور مسلمانوں کے سوا کسی کو اپنا محرم راز نہ بنائیں گے (ف۳۷) اور اللہ تمہارے کاموں سے خبردار ہے،'),
 (93,9,17,'مشرکوں کو نہیں پہنچتا کہ اللہ کی مسجدیں آباد کریں (ف۳۸) خود اپنے کفر کی گواہی دے کر (ف۳۹) ان کا تو سب کیا دھرا اِکا رت ہے اور وہ ہمیشہ آگ میں رہیں گے (ف۴۰)'),
 (93,9,18,'اللہ کی مسجدیں وہی آباد کرتے ہیں جو اللہ اور قیامت پر ایمان لاتے اور نما ز قائم کرتے ہیں اور زکوٰة دیتے ہیں (ف۴۱) اور اللہ کے سوا کسی سے نہیں ڈرتے (ف۴۲) تو قریب ہے کہ یہ لوگ ہدایت والوں میں ہوں،'),
 (93,9,19,'تو کیا تم نے حا جیوں کی سبیل اور مسجد حرام کی خدمت اس کے برابر ٹھہرا لی جو اللہ اور قیامت پر ایمان لایا اور اللہ کی راہ میں جہاد کیا، وہ اللہ کے نزدیک برابر نہیں، اور اللہ ظالموں کو راہ نہیں دیتا (ف۴۳)'),
 (93,9,20,'وہ جو ایمان لائے اور ہجرت کی اور اپنے مال و جان سے اللہ کی راہ میں لڑے، اللہ کے یہاں ان کا درجہ بڑا ہے (ف۴۴) اور وہی مراد کو پہنچے (ف۴۵)'),
 (93,9,21,'ان کا رب انہیں خوشی سنا تا ہے اپنی رحمت اور اپنی رضا کی (ف۴۶) اور ان باغوں کی جن میں انہیں دائمی نعمت ہے'),
 (93,9,22,'ہمیشہ ہمیشہ ان میں رہیں گے، بیشک اللہ کے پاس بڑا ثواب ہے،'),
 (93,9,23,'اے ایمان والو! اپنے باپ اور اپنے بھائیوں کو دوست نہ سمجھو اگر وہ ایمان پر کفر پسند کریں، اور تم میں جو کوئی ان سے دوستی کرے گا تو وہی ظالم ہیں (ف۴۷)'),
 (93,9,24,'تم فرماؤ اگر تمہارے باپ اور تمہارے بیٹے اور تمہارے بھائی اور تمہاری عورتیں اور تمہارا کنبہ اور تمہاری کمائی کے مال او ر وہ سودا جس کے نقصان کا تمہیں ڈر ہے اور تمہارے پسند کا مکان یہ چیزیں اللہ اور اس کے رسول اور اس کی راہ میں لڑے سے زیاد ہ پیاری ہوں تو راستہ دیکھو یہاں تک کہ اللہ اپنا حکم لائے (ف۴۸) اور اللہ فاسقوں کو راہ نہیں دیتا،'),
 (93,9,25,'بیشک اللہ نے بہت جگہ تمہاری مدد کی (ف۴۹) اور حنین کے دن جب تم اپنی کثرت پر اترا گئے تھے تو وہ تمہارے کچھ کام نہ ا ٓئی (ف۵۰) اور زمین اتنی وسیع ہوکر تم پر تنگ ہوگئی (ف۵۱) پھر تم پیٹھ دے کر پھرگئے،'),
 (93,9,26,'پھر اللہ نے اپنی تسکین اتا ری اپنے رسول پر (ف۵۲) اور مسلمانوں پر (ف۵۳) اور وہ لشکر اتارے جو تم نے نہ دیکھے (ف۵۴) اور کافروں کو عذاب دیا (ف۵۵) اور منکروں کی یہی سزا ہے،'),
 (93,9,27,'پھر اس کے بعد اللہ جسے چاہے گا توبہ دے گا (ف۵۶) اور اللہ بخشنے والا مہربان ہے،'),
 (93,9,28,'اے ایمان والو! مشرک نرے ناپاک ہیں (ف۵۷) تو اس برس کے بعد وہ مسجد حرام کے پاس نہ آنے پائیں (ف۵۸) اور اگر تمہاری محتاجی کا ڈر ہے (ف۵۹) تو عنقریب اللہ تمہیں دولت مند کردے گا اپنے فضل سے اگر چاہے (ف۶۰) بیشک اللہ علم و حکمت والا ہے،'),
 (93,9,29,'لڑو ان سے جو ایمان نہیں لاتے اللہ پر اور قیامت پر (ف۶۱) اور حرام نہیں مانتے اس چیز کو جس کو حرام کیا اللہ اور اس کے رسول نے (ف۶۲) اور سچے دین (ف۶۳) کے تابع نہیں ہوتے یعنی وہ جو کتاب دیے گئے جب تک اپنے ہاتھ سے جزیہ نہ دیں ذلیل ہوکر (ف۶۴)'),
 (93,9,30,'اور یہودی بولے عزیر اللہ کا بیٹا ہے (ف۶۵) اور نصرانی بولے مسیح اللہ کا بیٹا ہے، یہ باتیں وہ اپنے منہ سے بکتے ہیں (ف۶۶) اگلے کافرو ں کی سی بات بناتے ہیں، اللہ انہیں مارے، کہاں اوندھے جاتے ہیں (ف۶۷)'),
 (93,9,31,'انہوں نے اپنے پادریوں اور جوگیوں کو اللہ کے سوا خدا بنالیا (ف۶۸) اور مسیح بن مریم کو (ف۶۹) اور انہیں حکم نہ تھا (ف۷۰) مگر یہ کہ ایک اللہ کو پوجیں اس کے سوا کسی کی بندگی نہیں، اسے پاکی ہے ان کے شرک سے،'),
 (93,9,32,'چاہتے ہیں کہ اللہ کا نور (ف۷۱) اپنے منہ سے بُجھا دیں اور اللہ نہ مانے گا مگر اپنے نور کا پورا کرنا (ف۷۲) پڑے برا مانیں کافر،'),
 (93,9,33,'وہی ہے جس نے اپنا رسول (ف۷۳) ہدایت اور سچے دین کے ساتھ بھیجا کہ اسے سب دینوں پر غالب کرے (ف۷۴) پڑے برا مانیں مشرک،'),
 (93,9,34,'اے ایمان والو! بیشک بہت پادری اور جوگی لوگوں کا مال ناحق کھا جاتے ہیں (ف۷۵) اور اللہ کی راہ سے (ف۷۶) روکتے ہیں، اور وہ کہ جوڑ کر رکھتے ہیں سونا اور چاندی اور اسے اللہ کی راہ میں خرچ نہیں کرتے (ف۷۷) انہیں خوشخبری سناؤ دردناک عذاب کی،'),
 (93,9,35,'جس دن تپایا جائے گا جہنم کی آ گ میں (ف۷۸) پھر اس سے داغیں گے ان کی پیشانیاں اور کروٹیں اور پیٹھیں (ف۷۹) یہ ہے وہ جو تم نے اپنے لیے جوڑ کر رکھا تھا اب چکھو مزا اس جوڑنے کا،'),
 (93,9,36,'بیشک مہینوں کی گنتی اللہ کے نزدیک بارہ مہینے ہے (ف۸۰) اللہ کی کتاب میں (ف۸۱) جب سے اس نے آسمان اور زمین بنائے ان میں سے چار حرمت والے ہیں (ف۸۲) یہ سیدھا دین ہے، تو ان مہینوں میں (ف۸۳) اپنی جان پر ظلم نہ کرو اور مشرکوں سے ہر وقت لڑو جیسا وہ تم سے ہر وقت لڑتے ہیں، اور جان لو کہ اللہ پرہیزگاروں کے ساتھ ہے (ف۸۴)'),
 (93,9,37,'ان کا مہینے پیچھے ہٹانا نہیں مگر اور کفر میں بڑھنا (ف۸۵) اس سے کافر بہکائے جاتے ہیں ایک برس اسے حلال (ف۸۶) ٹھہراتے ہیں اور دوسرے برس اسے حرام مانتے ہیں کہ اس گنتی کے برابر ہوجائیں جو اللہ نے حرام فرمائی (ف۸۷) اور اللہ کے حرام کیے ہوئے حلال کرلیں، ان کے برے کا م ان کی آنکھوں میں بھلے لگتے ہیں، اور اللہ کافروں کو راہ نہیں دیتا،'),
 (93,9,38,'اے ایمان والو! تمہیں کیا ہوا جب تم سے کہا جائے کہ خدا کی راہ میں کوچ کرو تو بوجھ کے مارے زمین پر بیٹھ جاتے ہو (ف۸۸) کیا تم نے دنیا کی زندگی آخرت کے بدلے پسند کرلی اور جیتی دنیا کا اسباب آخرت کے سامنے نہیں مگر تھوڑا (ف۸۹)'),
 (93,9,39,'اگر نہ کوچ کرو گے (ف۹۰) انہیں سخت سزا دے گا اور تمہاری جگہ اور تمہاری جگہ اور لوگ لے آئے گا (ف۹۱) اور تم اس کا کچھ نہ بگا ڑ سکوگے، اور اللہ سب کچھ کرسکتا ہے،'),
 (93,9,40,'اگر تم محبوب کی مدد نہ کرو تو بیشک اللہ نے ان کی مدد فرمائی جب کافروں کی شرارت سے انہیں باہر تشریف لے جانا ہوا (ف۹۲) صرف دو جان سے جب وہ دونوں (ف۹۳) غار میں تھے جب اپنے یار سے (ف۹۴) فرماتے تھے غم نہ کھا بیشک اللہ ہمارے ساتھ ہے تو اللہ نے اس پر اپنا سکینہ اتارا (ف۹۵) اور ان فوجوں سے اس کی مدد کی جو تم نے نہ دیکھیں (ف۹۶) اور کافروں کی بات نیچے ڈالی (ف۹۷) اللہ ہی کا بول بالا ہے اور اللہ غالب حکمت والا ہے،'),
 (93,9,41,'کوچ کرو ہلکی جان سے چاہے بھاری دل سے (ف۹۸) اور اللہ کی راہ میں لڑو اپنے مال اور جان سے، یہ تمہارے لیے بہتر ہے اگر جانو (ف۹۹)'),
 (93,9,42,'اگر کوئی قریب مال یا متوسط سفر ہوتا (ف۱۰۰) تو ضرور تمہارے ساتھ جاتے (ف۱۰۱) مگر ان پر تو مشقت کا راستہ دور پڑ گیا، اور اب اللہ کی قسم کھائیں گے (ف۱۰۲) کہ ہم سے بن پڑتا تو ضرور تمہارے ساتھ چلتے (ف۱۰۳) اپنی جانو کو ہلاک کرتے ہیں (ف۱۰۴) اور اللہ جانتا ہے کہ وہ بیشک ضرور جھوٹے ہیں،'),
 (93,9,43,'اللہ تمہیں معاف کرے (ف۱۰۵) تم نے انہیں کیوں اِذن دے دیا جب تک نہ کھلے تھے تم پر سچے اور ظاہر نہ ہوئے تھے جھوٹے،'),
 (93,9,44,'اور وہ جو اللہ اور قیامت پر ایمان رکھتے ہیں تم سے چھٹی نہ مانگیں گے اس سے کہ اپنے مال اور جان سے جہاد کریں، اور اللہ خوب جا نتا ہے پرہیزگا روں کو،'),
 (93,9,45,'تم سے یہ چھٹی وہی مانگتے ہیں جو اللہ اور قیامت پر ایمان نہیں رکھتے (ف۱۰۶) اور ان کے دل شک میں پڑے ہیں تو وہ اپنے شک میں ڈانواں ڈول ہیں (ف۱۰۷)'),
 (93,9,46,'انہیں نکلنا منظور ہوتا (ف۱۰۸) تو اس کا سامان کرتے مگر خدا ہی کو ان کا اٹھنا پسند ہوا تو ان میں کاہلی بھردی اور (ف۱۰۹) فرمایا گیا کہ بیٹھ رہو بیٹھ رہنے والے کے ساتھ (ف۱۱۰)'),
 (93,9,47,'اگر وہ تم میں نکلتے تو ان سے سوا نقصان کے تمہیں کچھ نہ بڑھتنا اور تم میں فتنہ ڈالنے کو تمہارے بیچ یں غرابیں دوڑاتے (فساد ڈالتے) (ف۱۱۱) اور تم میں ان کے جاسوس موجود ہیں (ف۱۱۲) اور اللہ خوب جانتا ہے ظالموں کو،'),
 (93,9,48,'بیشک انہوں نے پہلے ہی فتنہ چا ہا تھا (ف۱۱۳) اور اے محبوب! تمہارے لیے تدبیریں الٹی پلٹیں (ف۱۱۴) یہاں تک کہ حق آیا (ف۱۱۵) اور اللہ کا حکم ظاہر ہوا (ف۱۱۶) اور انہیں ناگوار تھا،'),
 (93,9,49,'اور ان میں کوئی تم سے یوں عرض کرتا ہے کہ مجھے رخصت دیجیے اور فتنہ میں نہ ڈالیے (ف۱۱۷) سن لو وہ فتنہ ہی میں پڑے (ف۱۱۸) اور بیشک جہنم گھیرے ہوئے ہے کافروں کو،'),
 (93,9,50,'اگر تمہیں بھلائی پہنچے (ف۱۱۹) تو انہیں برا لگے اور اگر تمہیں کوئی مصیبت پہنچے (ف۱۲۰) تو کہیں (ف۱۲۱) ہم نے اپنا کام پہلے ہی ٹھیک کرلیا تھا اور خوشیاں مناتے پھر جائیں،'),
 (93,9,51,'تم فرماؤ ہمیں نہ پہنچے گا مگر جو اللہ نے ہمارے لیے لکھ دیا وہ ہمارا مولیٰ ہے اور مسلمانوں کو اللہ ہی پر بھروسہ چاہیے،'),
 (93,9,52,'تم فرماؤ تم ہم پر کس چیز کا انتظار کرتے ہو مگر دو خوبیوں میں سے ایک کا (ف۱۲۲) اور ہم تم پر اس انتظار میں ہیں کہ اللہ تم پر عذاب ڈالے اپنے پاس سے (ف۱۲۳) یا ہمارے ہاتھوں (ف۱۲۴) تو اب راہ دیکھو ہم بھی تمہارے ساتھ راہ دیکھ رہے ہیں (ف۱۲۵)'),
 (93,9,53,'تم فرماؤ کہ دل سے خرچ کرو یا ناگواری سے تم سے ہر گز قبول نہ ہوگا (ف۱۲۶) بیشک تم بے حکم لوگ ہو،'),
 (93,9,54,'اور وہ جو خرچ کرتے ہیں اس کا قبول ہونا بند نہ ہوا مگر اسی لیے کہ وہ اللہ اور رسول سے منکر ہوئے اور نماز کو نہیں آتے مگر جی ہارے اور خرچ نہیں کرتے مگر ناگواری سے (ف۱۲۷)'),
 (93,9,55,'تو تمہیں ان کے مال اور ان کی اولاد کا تعجب نہ آئے، اللہ ہی چاہتا ہے کہ دنیا کی زندگی میں ان چیزوں سے ان پر وبال ڈالے اور اگر کفر ہی پر ان کا دم نکل جائے (ف۱۲۸)'),
 (93,9,56,'اور اللہ کی قسمیں کھاتے ہیں (ف۱۲۹) کہ وہ تم میں سے ہیں (ف۱۳۰) اور تم میں سے ہیں نہیں (ف۱۳۱) ہاں وہ لوگ ڈرتے ہیں (ف۱۳۲)'),
 (93,9,57,'اگر پائیں کوئی پناہ یا غار یا سما جانے کی جگہ تو رسیاں تڑاتے ادھر پھر جائیں گے (ف۱۳۳)'),
 (93,9,58,'اور ان میں کوئی وہ ہے کہ صدقے بانٹنے میں تم پر طعن کرتا ہے (ف۱۳۴) تو اگر ان (ف۱۳۵) میں سے کچھ ملے تو راضی ہوجائیں اور نہ ملے تو جبھی وہ ناراض ہیں،'),
 (93,9,59,'اور کیا اچھا ہوتا اگر وہ اس پر راضی ہوتے جو اللہ و رسول نے ان کو دیا اور کہتے ہمیں اللہ کافی ہے اب دیتا ہے ہمیں اللہ اپنے فضل سے اور اللہ کا رسول، ہمیں اللہ ہی کی طرف رغبت ہے (ف۱۳۶)'),
 (93,9,60,'زکوٰة تو انہیں لوگوں کے لیے ہے (ف۱۳۷) محتاج اور نرے نادار اور جو اسے تحصیل کرکے لائیں اور جن کے دلوں کو اسلام سے الفت دی جائے اور گردنیں چھڑانے میں اور قرضداروں کو اور اللہ کی راہ میں اور مسافر کو، یہ ٹھہرایا ہوا ہے اللہ کا، اور اللہ علم و حکمت والا ہے'),
 (93,9,61,'اور ان میں کوئی وہ ہیں کہ ان غیب کی خبریں دینے والے کو ستاتے ہیں (ف۱۳۸) اور کہتے ہیں وہ تو کان ہیں، تم فرماؤ تمہارے بھلے کے لیے کا ن ہیں اللہ پر ایمان لاتے ہیں اور مسلمانوں کی بات پر یقین کرتے ہیں (ف۱۳۹) اور جو تم میں مسلمان ہیں ان کے واسطے رحمت ہیں، اور جو رسول اللہ کو ایذا دیتے ہیں ان کے لیے دردناک عذاب ہے،'),
 (93,9,62,'تمہارے سامنے اللہ کی قسم کھاتے ہیں (ف۱۴۰) کہ تمہیں راضی کرلیں (ف۱۴۱) اور اللہ و رسول کا حق زائد تھا کہ اسے راضی کرتے اگر ایمان رکھتے تھے،'),
 (93,9,63,'کیا انہیں خبر نہیں کہ جو خلاف کرے اللہ اور اس کے رسول کا تو اس کے لیے جہنم کی آ گ ہے کہ ہمیشہ اس میں رہے گا، یہی بڑی رسوائی ہے،'),
 (93,9,64,'منافق ڈرتے ہیں کہ ان (ف۱۴۲) پر کوئی سورة ایسی اترے جو ان (ف۱۴۳) کے دلوں کی چھپی (ف۱۴۴) جتادے تم فرماؤ ہنسے جاؤ اللہ کو ضرور ظاہر کرنا ہے جس کا تمہیں ڈر ہے،'),
 (93,9,65,'اور اے محبوب اگر تم ان سے پوچھو تو کہیں گے کہ ہم تو یونہی ہنسی کھیل میں تھے (ف۱۴۵) تم فرماؤ کیا اللہ اور اس کی آیتوں اور اس کے رسول سے ہنستے ہو،'),
 (93,9,66,'بہانے نہ بنا ؤ تم کافر ہوچکے مسلمان ہوکر (ف۱۴۶) اگر ہم تم میں سے کسی کو معاف کریں (ف۱۴۵)تو اوروں کو عذاب دیں گے اس لیے کہ وہ مجرم تھے (ف۱۴۸)'),
 (93,9,67,'منافق مرد اور منافق عورتیں ایک تھیلی کے چٹے بٹے ہیں (ف۱۴۹) برائی کا حکم دیں (ف۱۵۰) اور بھلائی سے منع کریں (ف۱۵۱) اور اپنی مٹھی بند رکھیں (ف۱۵۲) وہ اللہ کو چھوڑ بیٹھے (ف۱۵۳) تو اللہ نے انہیں چھوڑدیا (ف۱۵۴) بیشک منافق وہی پکے بے حکم ہیں،'),
 (93,9,68,'اللہ نے منافق مردوں اور منافق عورتوں اور کافروں کو جہنم کی آگ کا وعدہ دیا ہے جس میں ہمیشہ رہیں گے، وہ انہیں بس ہے اور اللہ کی ان پر لعنت ہے اور ان کے لیے قائم رہنے والا عذاب ہے'),
 (93,9,69,'جیسے وہ جو تم سے پہلے تھے تم سے زور میں بڑھ کر تھے اور ان کے مال اور اولاد سے زیادہ، تو وہ اپنا حصہ (ف۱۵۵) برت گئے تو تم نے اپنا حصہ برتا جیسے اگلے اپنا حصہ برت گئے اور تم بیہودگی میں پڑے جیسے وہ پڑے تھے (ف۱۵۶) ان کے عمل اکارت گئے دنیا اور آخرت میں اور وہی لوگ گھاٹے میں ہیں (ف۱۵۷)'),
 (93,9,70,'کیا انہیں (ف۱۵۸) اپنے سے اگلوں کی خبر نہ آئی (ف۱۵۹) نوح کی قوم (ف۱۶۰) اور عاد (ف۱۶۱) اور ثمود (ف۱۶۲) اور ابراہیم کی قوم (ف۱۶۳) اور مدین والے (ف۱۶۴) اور وہ بستیاں کہ الٹ دی گئیں (ف۱۶۵) ان کے رسول روشن دلیلیں ان کے پاس لائے تھے (ف۱۶۶) تو اللہ کی شان نہ تھی کہ ان پر ظلم کرتا (ف۱۶۷) بلکہ وہ خود ہی اپنی جانوں پر ظالم تھے (ف۱۶۸)'),
 (93,9,71,'اور مسلمان مرد اور مسلمان عورتیں ایک دوسرے کے رفیق ہیں (ف۱۶۹) بھلائی کا حکم دیں (ف۱۷۰) اور برائی سے منع کریں اور نماز قائم رکھیں اور زکوٰة دیں اور اللہ و رسول کا حکم مانیں، یہ ہیں جن پر عنقریب اللہ رحم کرے گا، بیشک اللہ غالب حکمت والا ہے،'),
 (93,9,72,'اللہ نے مسلمان مردوں اور مسلمان عورتوں کو باغوں کا وعدہ دیا ہے جن کے نیچے نہریں رواں ان میں ہمیشہ رہیں گے اور پاکیزہ مکانوں کا (ف۱۷۱) بسنے کے باغوں میں، اور اللہ کی رضا سب سے بڑی (ف۱۷۲) یہی ہے بڑی مراد پانی،'),
 (93,9,73,'اے غیب کی خبریں دینے والے (نبی) جہاد فرماؤ کافروں اور منافقوں پر (ف۱۷۳) اور ان پر سختی کرو، اور ان کا ٹھکانا دوزخ ہے، اور کیا ہی بری جگہ پلٹنے کی،'),
 (93,9,74,'اللہ کی قسم کھاتے ہیں کہ انہوں نے نہ کہا (ف۱۷۴) اور بیشک ضرور انہوں نے کفر کی بات کہی اور اسلام میں آکر کافر ہوگئے اور وہ چاہا تھا جو انہیں نہ ملا (ف۱۷۵) اور انہیں کیا برا لگا یہی نہ کہ اللہ و رسول نے انہیں اپنے فضل سے غنی کردیا (ف۱۷۶) تو اگر وہ توبہ کریں تو ان کا بھلا ہے، اور اگر منہ پھیریں (ف۱۷۷) تو اللہ انہیں سخت عذاب کرے گا دنیا اور آخرت میں، اور زمین میں کوئی نہ ان کا حمایتی ہوگا اور نہ مددگار (ف۱۷۸)'),
 (93,9,75,'اور ان میں کوئی وہ ہیں جنہوں نے اللہ سے عہد کیا تھا کہ اگر ہمیں اپنے فضل سے دے تو ہم ضرور خیرات کریں گے اور ہم ضرور بھلے آدمی ہوجائیں گے (ف۱۷۹)'),
 (93,9,76,'تو جب اللہ نے انہیں اپنے فضل سے دیا اس میں بخل کرنے لگے اور منہ پھیر کر پلٹ گئے،'),
 (93,9,77,'تو اس کے پیچھے اللہ نے ان کے دلوں میں نفاق رکھ دیا اس دن تک کہ اس سے ملیں گے بدلہ اس کا کہ انہوں نے اللہ سے وعدہ جھوٹا کیا اور بدلہ اس کا کہ جھوٹ بولتے تھے (ف۱۸۰)'),
 (93,9,78,'کیا انہیں خبر نہیں کہ اللہ ان کے دل کی چھپی اور ان کی سرگوشی کو جانتا ہے اور یہ کہ اللہ سب غیبوں کا بہت جاننے والا ہے (ف۱۸۱)'),
 (93,9,79,'اور جو عیب لگاتے ہیں ان مسلمانوں کو کہ دل سے خیرات کرتے ہیں (ف۱۸۲) اور ان کو جو نہیں پاتے مگر اپنی محنت سے (ف۱۸۳) تو ان سے ہنستے ہیں (ف۱۸۴) اللہ ان کی ہنسی کی سزا دے گا، اور ان کے لیے دردناک عذاب ہے،'),
 (93,9,80,'تم ان کی معافی چاہو یا نہ چاہو، اگر تم ستر بار ان کی معافی چاہو گے تو اللہ ہرگز انھیں نہیں بخشے گا (ف۱۸۵) یہ اس لیے کہ وہ اللہ اور اس کے رسول سے منکر ہوئے، اور اللہ فاسقوں کو راہ نہیں دیتا (ف۱۸۶)'),
 (93,9,81,'پیچھے رہ جانے والے اس پر خوش ہوئے کہ وہ رسول کے پیچھے بیٹھ رہے (ف۱۸۷) اور انہیں گوارا نہ ہوا کہ اپنے مال اور جان سے اللہ کی راہ میں لڑیں اور بولے اس گرمی میں نہ نکلو، تم فرماؤ جہنم کی آگ سب سے سخت گرم ہے، کسی طرح انہیں سمجھ ہو تی (ف۱۸۸)'),
 (93,9,82,'تو انہیں چاہیے تھوڑا ہنسیں اور بہت روئیں (ف۱۸۹) بدلہ اس کا جو کماتے تھے (ف۱۹۰)'),
 (93,9,83,'پھر اے محبوب! (ف۱۹۱) اگر اللہ تمہیں ان (ف۱۹۲) میں سے کسی گروہ کی طرف واپس لے جائے اور وہ (ف۱۹۳) تم سے جہاد کو نکلنے کی اجازت مانگے تو تم فرمانا کہ تم کبھی میرے ساتھ نہ چلو اور ہرگز میرے ساتھ کسی دشمن سے نہ لڑو، تم نے پہلی دفعہ بیٹھ رہنا پسند کیا تو بیٹھ رہو پیچھے رہ جانے والوں کے ساتھ (ف۱۹۴)'),
 (93,9,84,'اور ان میں سے کسی کی میت پر کبھی نماز نہ پڑھنا اور نہ اس کی قبر پر کھڑے ہونا، بیشک اللہ اور رسول سے منکر ہوئے اور فسق ہی میں مر گئے (ف۱۹۵)'),
 (93,9,85,'اور ان کے مال یا اولاد پر تعجب نہ کرنا، اللہ یہی چاہتا ہے کہ اسے دنیا م یں ان پر وبال کرے اور کفر ہی پر ان کا دم نکل جائے،'),
 (93,9,86,'اور جب کوئی سورت اترے کہ اللہ پر ایمان لاؤ اور اس کے رسول کے ہمراہ جہاد کرو تو ان کے مقدور والے تم سے رخصت مانگتے ہیں اور کہتے ہیں ہمیں چھوڑ دیجیے کہ بیٹھ رہنے والوں کے ساتھ ہولیں،'),
 (93,9,87,'انہیں پسند آیا کہ پیچھے رہنے والی عورتوں کے ساتھ ہوجائیں اور ان کے دلوں پر مہُر کردی گئیں (ف۱۹۶) تو وہ کچھ نہیں سمجھتے (ف۱۹۷)'),
 (93,9,88,'لیکن رسول اور جو ان کے ساتھ ایمان لائے انہوں نے اپنے مالوں جانوں سے جہاد کیا، اور انہیں کے لیے بھلائیاں ہیں (ف۱۹۸) اور یہی مراد کو پہنچے،'),
 (93,9,89,'اللہ نے ان کے لیے تیار کر رکھی ہیں بہشتیں جن کے نیچے نہریں رواں ہمیشہ ان میں رہیں گے، یہی بڑی مراد ملنی ہے،'),
 (93,9,90,'اور بہانے بنانے والے گنوار آئے (ف۱۹۹) کہ انہیں رخصت دی جائے اور بیٹھ رہے وہ جنہوں نے اللہ و رسول سے جھوٹ بولا تھا (ف۲۰۰) جلد ان میں کے کافروں کو دردناک عذاب پہنچے گا (ف۲۰۱)'),
 (93,9,91,'ضعیفوں پر کچھ حرج نہیں (ف۲۰۲) اور نہ بیماروں پر (ف۲۰۳) اور نہ ان پر جنہیں خرچ کا مقدور نہ ہو (ف۲۰۴) جب کہ اللہ اور رسول کے خیر خواہ رہیں (ف۲۰۵) نیکی والوں پر کوئی راہ نہیں (ف۲۰۶) اور اللہ بخشنے والا مہربان ہے،'),
 (93,9,92,'اور نہ ان پر جو تمہارے حضور حاضر ہوں کہ تم انہیں سواری عطا فرماؤ (ف۲۰۷) تم سے یہ جواب پائیں کہ میرے پاس کوئی چیز نہیں جس پر تمہیں سوار کروں اس پر یوں واپس جائیں کہ ان کی آنکھوں سے آنسو ابلتے ہوں اس غم سے کہ خرچ کا مقدور نہ پایا،'),
 (93,9,93,'مؤاخذہ تو ان سے ہے جو تم سے رخصت مانگتے ہیں اور وہ دولت مند ہیں (ف۲۰۸) انہیں پسند آیا کہ عورتوں کے ساتھ پیچھے بیٹھ رہیں اور اللہ نے ان کے دلوں پر مہر کردی تو وہ کچھ نہیں جانتے (ف۲۰۹)'),
 (93,9,94,'تم سے بہانے بنائیں گے (ف۲۱۰) جب تم ان کی طرف لوٹ کر جاؤ گے تم فرمانا، بہانے نہ بناؤ ہم ہرگز تمہارا یقین نہ کریں گے اللہ نے ہمیں تمہاری خبریں دے دی ہیں، اور اب اللہ و رسول تمہارے کام دیکھیں گے (ف۲۱۱) پھر اس کی طرف پلٹ کر جاؤ گے جو چھپے اور ظاہر سب کو جانتا ہے وہ تمہیں جتادے گا جو کچھ تم کرتے تھے،'),
 (93,9,95,'اب تمہارے آگے اللہ کی قسمیں کھائیں گے جب (ف۲۱۲) تم ان کی طرف پلٹ کر جاؤ گے اس لیے کہ تم ان کے خیال میں نہ پڑو (ف۲۱۳) تو ہاں تم ان کا خیال چھوڑو (ف۲۱۴) وہ تو نرے پلید ہیں (ف۲۱۵) اور ان کا ٹھکانا جہنم ہے بدلہ اس کا جو کماتے تھے (ف۲۱۶)'),
 (93,9,96,'تمہارے آگے قسمیں کھاتے ہیں کہ تم ان سے راضی ہوجاؤ تو اگر تم ان سے راضی ہوجاؤ (ف۲۱۷) تو بیشک اللہ تو فاسق لوگوں سے راضی نہ ہوگا (ف۲۱۸)'),
 (93,9,97,'گنوار (ف۲۱۹) کفر اور نفاق میں زیادہ سخت ہیں (ف۲۲۰) اور اسی قابل ہیں کہ اللہ نے جو حکم اپنے رسول پر اتارے اس سے جاہل رہیں، اور اللہ علم و حکمت والا ہے،'),
 (93,9,98,'اور کچھ گنوار وہ ہیں کہ جو اللہ کی راہ میں خرچ کریں تو اسے تاوان سمجھیں (ف۲۲۱) اور تم پر گردشیں آنے کے انتظار میں رہیں (ف۲۲۲) انہیں پر ہے بری گردش (ف۲۲۳) اور اللہ سنتا جانتا ہے،'),
 (93,9,99,'اور کچھ گاؤں والے وہ ہیں جو اللہ اور قیامت پر ایمان رکھتے ہیں (ف۲۲۴) اور جو خرچ کریں اسے اللہ کی نزدیکیوں اور رسول سے دعائیں لینے کا ذریعہ سمجھیں (ف۲۲۵) ہاں ہاں وہ ان کے لیے باعث قرب ہے اللہ جلد انہیں اپنی رحمت میں داخل کرے گا، بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,9,100,'اور سب میں اگلے پہلے مہاجر (ف۲۲۶) اور انصار (ف۲۲۷) اور جو بھلائی کے ساتھ ان کے پیرو ہوئے (ف۲۲۸) اللہ ان سے راضی (ف۲۲۹) اور وہ اللہ سے راضی اور ان کے لیے تیار کر رکھے ہیں باغ جن کے نیچے نہریں بہیں ہمیشہ ہمیشہ ان میں رہیں، یہی بڑی کامیابی ہے،'),
 (93,9,101,'اور تمہارے آس پاس (ف۲۳۱) کے کچھ گنوار منافق ہیں، اور کچھ مدینہ والے، ان کی خو ہوگئی ہے نفاق، تم انہیں نہیں جانتے، ہم انھیں جانتے ہیں (ف۲۳۲) جلد ہم انہیں دوبارہ (ف۲۳۳) عذاب کریں گے پھر بڑے عذاب کی طرف پھیرے جائیں گے (ف۲۳۴)'),
 (93,9,102,'اور کچھ اور ہیں جو اپنے گناہوں کے مقر ہوئے (ف۲۳۵) اور ملایا ایک کام اچھا (ف۲۳۶) اور دوسرا بڑا (ف۲۳۷) قریب ہے کہ اللہ ان کی توبہ قبول کرے، بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,9,103,'اے محبوب! ان کے مال میں سے زکوٰة تحصیل کرو جس سے تم انھیں ستھرا اور پاکیزہ کردو اور ان کے حق میں دعائے خیر کرو (ف۲۳۸) بیشک تمہاری دعا ان کے دلوں کا چین ہے، اور اللہ سنتا جانتا ہے،'),
 (93,9,104,'کیا انہیں خبر نہیں کہ اللہ ہی اپنے بندوں کی توبہ قبول کرتا اور صدقے خود اپنی دست قدرت میں لیتا ہے اور یہ کہ اللہ ہی توبہ قبول کرنے والا مہربان ہے (ف۲۳۹)'),
 (93,9,105,'اور تم فرما ؤ کام کرو اب تمہارے کام دیکھے گا اللہ اور اس کے رسول اور مسلمان، اور جلد اس کی طرف پلٹوگے جو چھپا اور کھلا سب جانتا ہے تو وہ تمہارے کام تمہیں جتاوے گا،'),
 (93,9,106,'اور کچھ (ف۲۴۰) موقوف رکھے گئے اللہ کے حکم پر، یا ان پر عذاب کرے یا ان کی توبہ قبول کرے (ف۲۴۱) اور اللہ علم و حکمت والا ہے،'),
 (93,9,107,'اور وہ جنہوں نے مسجد بنائی (ف۲۴۲) نقصان پہنچانے کو (ف۲۴۳) اور کفر کے سبب (ف۲۴۴) اور مسلمانوں میں تفرقہ ڈالنے کو (ف۲۴۵) اور اس کے انتظار میں جو پہلے سے اللہ اور اس کے رسول کا مخالف ہے (ف۲۴۶) اور وہ ضرور قسمیں کھائیں گے ہم نے تو بھلائی چاہی، اور اللہ گواہ ہے کہ وہ بیشک جھوٹے ہیں،'),
 (93,9,108,'اس مسجد میں تم کبھی کھڑے نہ ہونا، (ف۲۴۷) بیشک وہ مسجد کہ پہلے ہی دن سے جس کی بنیاد پرہیزگاری پر رکھی گئی ہے (ف۲۴۸) وہ اس قابل ہے کہ تم اس میں کھڑے ہو، اس میں وہ لوگ ہیں کہ خوب ستھرا ہونا چاہتے ہیں (ف۲۴۹) اور ستھرے اللہ کو پیارے ہیں،'),
 (93,9,109,'تو کیا جس نے اپنی بنیاد رکھی اللہ سے ڈر اور اس کی رضا پر (ف۲۵۰) وہ بھلا یا وہ جس نے اپنی نیو چنی ایک گراؤ (ٹوٹے ہوئے کناروں والے) گڑھے کے کنارے (ف۲۵۱) تو وہ اسے لے کر جہنم کی آ گ میں ڈھے پڑا (ف۲۵۲) اور اللہ ظالموں کو راہ نہیں دیتا،'),
 (93,9,110,'وہ تعمیر جو چنی (کی) ہمیشہ ان کے دلوں میں کھٹکتی رہے گی (ف۲۵۳) مگر یہ کہ ان کے دل ٹکڑے ٹکڑے ہوجائیں (ف۲۵۴) اور اللہ علم و حکمت والا ہے،'),
 (93,9,111,'بیشک اللہ نے مسلمانوں سے ان کے مال اور جان خریدلیے ہیں اس بدلے پر کہ ان کے لیے جنت ہے (ف۲۵۵) اللہ کی راہ میں لڑیں تو ماریں (ف۲۵۶) اور مریں (ف۲۵۷) اس کے ذمہ کرم پر سچا وعدہ توریت اور انجیل اور قرآن میں (ف۲۵۸) اور اللہ سے زیادہ قول کا پورا کون تو خوشیاں مناؤ اپنے سودے کی جو تم نے اس سے کیا ہے، اور یہی بڑی کامیابی ہے،'),
 (93,9,112,'توبہ والے (ف۲۵۹) عبادت والے (ف۲۶۰) سراہنے والے (ف۲۶۱) روزے والے رکوع والے سجدہ والے (ف۲۶۲) بھلائی کے بتانے والے اور برائی سے روکنے والے اور اللہ کی حدیں نگاہ رکھنے والے (ف۲۶۳) اور خوشی سناؤ مسلمانوں (ف۲۶۴)'),
 (93,9,113,'نبی اور ایمان والوں کو لائق نہیں کہ مشرکوں کی بخشش چاہیں اگرچہ وہ رشتہ دار ہوں (ف۲۶۵) جبکہ انہیں کھل چکا کہ وہ دوزخی ہیں (ف۲۶۶)'),
 (93,9,114,'اور ابراہیم کا اپنے باپ (ف۲۶۷) کی بخشش چاہنا وہ تو نہ تھا مگر ایک وعدے کے سبب جو اس سے کرچکا تھا (ف۲۶۸) پھر جب ابراہیم کو کھل گیا کہ وہ اللہ کا دشمن ہے اس سے تنکا توڑ دیا (لاتعلق ہوگیا) (ف۲۶۹) بیشک ابراہیم بہت آہیں کرنے والا (ف۲۷۰) متحمل ہے،'),
 (93,9,115,'اور اللہ کی شان نہیں کہ کسی قوم کو ہدایت کرکے گمراہ فرمائے (ف۲۷۱) جب تک انہیں صاف نہ بتادے کہ کسی چیز سے انہیں بچنا ہے (ف۲۷۲) بیشک اللہ سب کچھ جانتا ہے،'),
 (93,9,116,'بیشک اللہ ہی کے لیے ہے آسمانوں اور زمین کی سلطنت، جِلاتا ہے اور مارتا ہے، اور اللہ کے سوا نہ تمہارا کوئی والی اور نہ مددگار،'),
 (93,9,117,'بیشک اللہ کی رحمتیں متوجہ ہوئیں ان غیب کی خبریں بتانے والے اور ان مہاجرین اور انصار پر جنہوں نے مشکل کی گھڑی میں ان کا ساتھ دیا (ف۲۷۳) بعد اس کے کہ قریب تھا کہ ان میں کچھ لوگوں کے دل پھر جائیں (ف۲۷۴) پھر ان پر رحمت سے متوجہ ہوا (ف۲۷۵) بیشک وہ ان پر نہایت مہربان رحم والا ہے'),
 (93,9,118,'اور ان تین پر جو موقوف رکھے گئے تھے (ف۲۷۶) یہاں تک کہ جب زمین اتنی وسیع ہوکر ان پر تنگ ہوگئی (ف۲۷۷) اور ہو اپنی جان سے تنگ آئے (ف۲۷۸) اور انہیں یقین ہوا کہ اللہ سے پناہ نہیں مگر اسی کے پاس، پھر (ف۲۷۹) ان کی توبہ قبول کی کہ تائب رہیں، بیشک اللہ ہی توبہ قبول کرنے والا مہربان ہے،'),
 (93,9,119,'اے ایمان والو! اللہ سے ڈرو (ف۲۸۰) اور سچوں کے ساتھ ہو (ف۲۸۱)'),
 (93,9,120,'مدینہ والوں (ف۲۸۲) اور ان کے گرد دیہات والوں کو لائق نہ تھا کہ رسول اللہ سے پیچھے بیٹھ رہیں (ف۲۸۳) اور نہ یہ کہ ان کی جان سے اپنی جان پیاری سمجھیں (ف۲۸۴) یہ اس لیے کہ انہیں جو پیاس یا تکلیف یا بھوک اللہ کی راہ میں پہنچتی ہے اور جہاں ایسی جگہ قدم رکھتے ہیں (ف۲۸۵) جس سے کافروں کو غیظ آئے اور جو کچھ کسی دشمن کا بگاڑتے ہیں (ف۲۸۶) اس سب کے بدلے ان کے لیے نیک عمل لکھا جاتا ہے (ف۲۸۷) بیشک اللہ نیکوں کا نیگ (اجر) ضائع نہیں کرتا،'),
 (93,9,121,'اور جو کچھ خرچ کرتے ہیں چھوٹا (ف۲۸۸) یا بڑا (ف۲۸۹) اور جو نالا طے کرتے ہیں سب ان کے لیے لکھا جاتا ہے تاکہ اللہ ان کے سب سے بہتر کاموں کا انہیں صلہ دے (ف۲۹۰)'),
 (93,9,122,'اور مسلمانوں سے یہ تو ہو نہیں سکتا کہ سب کے سب نکلیں (ف۲۹۱) تو کیوں نہ ہو کہ ان کے ہر گروہ میں سے (ف۲۹۲) ایک جماعت نکلے کہ دین کی سمجھ حاصل کریں اور واپس آکر اپنی قوم کو ڈر سنائیں (ف۲۹۳) اس امید پر کہ وہ بچیں (ف۲۹۴)'),
 (93,9,123,'اے ايما ن والوں جہاد کرو ان کافروں سے جو تمہارے قريب ہيں(ف۲۹۵) اور چاہیئے کہ وہ تم میں سختی پائیں، اور جان رکھو کہ اللہ پرہیزگاروں کے ساتھ ہے (ف۲۹۶)'),
 (93,9,124,'اور جب کوئی سورت اترتی ہے تو ان میں کوئی کہنے لگتا ہے کہ اس نے تم میں کس کے ایمان کو ترقی دی (ف۲۹۷) تو وہ جو ایمان والے ہیں ان کے ایمان کو ترقی دی اور وہ خوشیاں منارہے ہیں،'),
 (93,9,125,'اور جن کے دلوں میں آزار ہے (ف۲۹۸) انہیں اور پلیدی پر پلیدی بڑھائی (ف۲۹۹) اور وہ کفر ہی پر مر گئے،'),
 (93,9,126,'کیا انہیں (ف۳۰۰) نہیں سوجھتا ک ہ ہر سال ایک یا دو بار آزمائے جاتے ہیں (ف۳۰۱) پھر نہ تو توبہ کرتے ہیں نہ نصیحت مانتے ہیں،'),
 (93,9,127,'اور جب کوئی سورت اترتی ہے ان میں ایک دوسرے کو دیکھنے لگتا ہے (ف۳۰۲) کہ کوئی تمہیں دیکھتا تو نہیں (ف۳۰۳) پھر پلٹ جاتے ہیں (ف۳۰۴) اللہ نے ان کے دل پلٹ دیئے ہیں(ف۳۰۵) کہ وہ ناسمجھ لوگ ہیں (ف۳۰۶)'),
 (93,9,128,'بیشک تمہارے پاس تشریف لائے تم میں سے وہ رسول (ف۳۹۷) جن پر تمہارا مشقت میں پڑنا گِراں ہے تمہاری بھلائی کے نہایت چاہنے والے مسلمانوں پر کمال مہربان مہربان (ف۳۰۸)'),
 (93,9,129,'پھر اگر وہ منہ پھیریں (ف۳۰۹) تو تم فرمادو کہ مجھے اللہ کافی ہے اس کے سوا کسی کی بندگی نہیں، میں نے اسی پر بھروسہ کیا اور وہ بڑے عرش کا مالک ہے (ف۳۱۰)'),
 (93,10,1,'یہ حکمت والی کتاب کی آیتیں ہیں،'),
 (93,10,2,'کیا لوگوں کو اس کا اچنبا ہوا کہ ہم نے ان میں سے ایک مرد کو وحی بھیجی کہ لوگوں کو ڈر سناؤ (ف۲) اور ایمان والوں کو خوشخبری دو کہ ان کے لیے ان کے رب کے پاس سچ کا مقام ہے، کافر بولے بیشک یہ تو کھلا جادوگر ہے (ف۳)'),
 (93,10,3,'بیشک تمہارا رب اللہ ہے جس نے آسمان اور زمین چھ دن میں بنائے پھر عرش پر استوا فرمایا جیسا اس کی شان کے لائق ہے کام کی تدبیر فرما تا ہے (ف۴) کوئی سفارشی نہیں مگر اس کی اجازت کے بعد (ف۵) یہ ہے اللہ تمہارا رب (ف۶) تو اس کی بندگی کرو تو کیا تم دھیان نہیں کرتے،'),
 (93,10,4,'اسی کی طرف تم سب کو پھرنا ہے (ف۷) اللہ کا سچا وعدہ بیشک وہ پہلی بار بناتا ہے پھر فنا کے بعد دوبارہ بنائے گا کہ ان کو جو ایمان لائے اور اچھے کام کیے انصاف کا صلہ دے (ف۸) اور کافروں کے لیے پینے کو کھولتا پانی اور دردناک عذاب بدلہ ان کے کفر کا،'),
 (93,10,5,'وہی ہے جس نے سورج کو جگمگاتا بنا یا اور چاند چمکتا اور اس کے لیے منزلیں ٹھہرائیں (ف۹) کہ تم برسوں کی گنتی اور (ف۱۰) حساب جانو، اللہ نے اسے نہ بنایا مگر حق (ف۱۱) نشانیاں مفصل بیان فرماتا ہے علم والوں کے لیے (ف۱۲)'),
 (93,10,6,'بیشک رات اور دن کا بدلتا آنا اور جو کچھ اللہ نے آسمانوں اور زمین میں پیدا کیا ان میں نشانیاں ہیں ڈر والوں کے لیے،'),
 (93,10,7,'بیشک وہ جو ہمارے ملنے کی امید نہیں رکھتے (ف۱۳) اور دنیا کی زندگی پسند کر بیٹھے اور اس پر مطمئن ہوگئے (ف۱۴) اور وہ جو ہماری آیتوں سے غفلت کرتے ہیں (ف۱۵)'),
 (93,10,8,'ان لوگوں کا ٹھکانا دوزخ ہے بدلہ ان کی کمائی کا،'),
 (93,10,9,'بیشک جو ایمان لائے اور اچھے کام کیے ان کا رب ان کے ایمان کے سبب انھیں راہ دے گا (ف۱۶) ان کے نیچے نہریں بہتی ہوں گی نعمت کے باغوں میں،'),
 (93,10,10,'ان کی دعا اس میں یہ ہوگی کہ اللہ تجھے پاکی ہے (ف۱۷) اور ان کے ملتے وقت خوشی کا پہلا بول سلام ہے (ف۱۸) اور ان کی دعا کا خاتمہ یہ ہے کہ سب خوبیوں کو سراہا اللہ جو رب ہے سارے جہان کا (ف۱۹)'),
 (93,10,11,'اور اگر اللہ لوگوں پر برائی ایسی جلدبھیجتا جیسی وہ بھلائی کی جلدی کرتے ہیں تو ان کا وعدہ پورا ہوچکا ہوتا (ف۲۰) تو ہم چھوڑتے انہیں جو ہم سے ملنے کی امید نہیں رکھتے کہ اپنی سرکشی میں بھٹکا کریں (ف۲۱)'),
 (93,10,12,'اور جب آدمی کو (ف۲۲) تکلیف پہنچتی ہے ہمیں پکارتا ہے لیٹے اور بیٹھے اور کھڑے (ف۲۳) پھر جب ہم اس کی تکلیف دور کردیتے ہیں چل دیتا ہے (ف۲۴) گویا کبھی کسی تکلیف کے پہنچنے پر ہمیں پکارا ہی نہ تھا یونہی بھلے کر دکھائے ہیں حد سے بڑھنے والے کو (ف۲۵) ان کے کام (ف۲۶)'),
 (93,10,13,'اور بیشک ہم نے تم سے پہلی سنگتیں (قومیں) (ف۲۷) ہلاک فرمادیں جب وہ حد سے بڑھے (ف۲۸) اور ان کے رسول ان کے پاس روشن دلیلیں لے کر آئے (ف۲۹) اور وہ ایسے تھے ہی نہیں کہ ایمان لاتے، ہم یونہی بدلہ دیتے ہیں مجرموں کو،'),
 (93,10,14,'پھر ہم نے ان کے بعد تمہیں زمین میں جانشین کیا کہ دیکھیں تم کیسے کام کرتے ہو (ف۳۰)'),
 (93,10,15,'اور جب ان پر ہماری روشن آیتیں (ف۳۱) پڑھی جاتی ہیں تو وہ کہنے لگتے ہیں جنہیں ہم سے ملنے کی امید نہیں (ف۳۲) کہ اس کے سوا اور قرآن لے آیئے (ف۳۳) یا اسی کو بدل دیجیے (ف۳۴) تم فرماؤ مجھے نہیں پہنچتا کہ میں اسے اپنی طرف سے بدل دوں میں تو اسی کا تابع ہوں جو میری طرف وحی ہوتی ہے (ف۳۵) میں اگر اپنے رب کی نافرمانی کروں (ف۳۶) تو مجھے بڑے دن کے عذاب کا ڈر ہے (ف۳۷)'),
 (93,10,16,'تم فرماؤ اگر اللہ چاہتا تو میں اسے تم پر نہ پڑھتا نہ وہ تم کو اس سے خبردار کرتا (ف۳۸) تو میں اس سے پہلے تم میں اپنی ایک عمر گزار چکا ہوں (ف۳۹) تو کیا تمہیں عقل نہیں (ف۴۰)'),
 (93,10,17,'تو اس سے بڑھ کر ظالم کون جو اللہ پر جھوٹ باندھے (ف۴۱) یا اس کی آیتیں جھٹلائے، بیشک مجرموں کا بھلا نہ ہوگا،'),
 (93,10,18,'اور اللہ کے سوا ایسی چیز (ف۴۲) کو پوجتے ہیں جو ان کا کچھ بھلا نہ کرے اور کہتے ہیں کہ یہ اللہ کے یہاں ہمارے سفارشی ہیں (ف۴۳) تم فرماؤ کیا اللہ کو وہ بات بتاتے ہو جو اس کے علم میں نہ آسمانوں میں ہے نہ زمین میں (ف۴۴) اسے پاکی اور برتری ہے ان کے شرک سے،'),
 (93,10,19,'اور لوگ ایک ہی امت تھے (ف۴۵) پھر مختلف ہوئے، اور اگر تیرے رب کی طرف سے ایک بات پہلے نہ ہوچکی ہوتی (ف۴۶) تو یہیں ان کے اختلافوں کا ان پر فیصلہ ہوگیا ہوتا (ف۴۷)'),
 (93,10,20,'اور کہتے ہیں ان پر ان کے رب کی طرف سے کوئی نشانی کیوں نہیں اتری (ف۴۸) تم فرماؤ غیب تو اللہ کے لیے ہے اب راستہ دیکھو میں بھی تمہارے ساتھ راہ دیکھ رہا ہوں،'),
 (93,10,21,'اور جب کہ ہمارے آدمیوں کو رحمت کا مزہ دیتے ہیں کسی تکلیف کے بعد جو انہیں پہنچی تھی جبھی وہ ہماری آیتوں کے ساتھ داؤں چلتے ہیں (ف۴۹) تم فرمادو اللہ کی خفیہ تدبیر سب سے جلد ہوجاتی ہے (ف۵۰) بیشک ہمارے فرشتے تمہارے مکر لکھ رہے ہیں (ف۵۱)'),
 (93,10,22,'وہی ہے کہ تمہیں خشکی اور تری میں چلاتا ہے (ف۵۲) یہاں تک کہ جب تم کشتی میں ہو اور وہ (ف۵۳) اچھی ہوا سے انھیں لے کر چلیں اور اس پر خوش ہوئے (ف۵۴) ان پر آندھی کا جھونکا آیا اور ہر طرف لہروں نے انہیں آلیا اور سمجھ لے کہ ہم گِھر گئے اس وقت اللہ کو پکارتے ہیں نرے اس کے بندے ہوکر، کہ اگر تو اس سے ہمیں بچالے گا تو ہم ضرور شکر گزار ہوں گے (ف۵۵)'),
 (93,10,23,'پھر اللہ جب انہیں بچا لیتا ہے جبھی وہ زمین میں ناحق زیادتی کرنے لگتے ہیں (ف۵۶) اے لوگو! تمہاری زیادتی تمہارے ہی جانوں کا وبال ہے دنیا کے جیتے جی برت لو (فائد اٹھالو)، پھر تمہیں ہماری طرف پھرنا ہے اس وقت ہم تمہیں جتادیں گے جو تمہارے کوتک تھے (ف۵۷)'),
 (93,10,24,'دنیا کی زندگی کی کہا وت تو ایسی ہی ہے جیسے وہ پانی کہ ہم نے آسمان سے اتارا تو اس کے سبب زمین سے اگنے والی چیزیں سب گھنی ہوکر نکلیں جو کچھ آدمی اور چوپائے کھاتے ہیں (ف۵۸) یہاں تک کہ جب زمین میں اپنا سنگھار لے لیا (ف۵۹) اور خوب آراستہ ہوگئی اور اس کے مالک سمجھے کہ یہ ہمارے بس میں آگئی (ف۶۰) ہمارا حکم اس پر آیا رات میں یا دن میں (ف۶۱) تو ہم نے اسے کردیا کاٹی ہوئی گویا کل تھی ہی نہیں (ف۶۲) ہم یونہی آیتیں مفصل بیان کرتے ہیں غور کرنے والوں کے لیے (ف۶۳)'),
 (93,10,25,'اور اللہ سلامتی کے گھر کی طرف پکارتا ہے (ف۶۴) اور جسے چاہے سیدھی راہ چلاتا ہے (ف۶۵)'),
 (93,10,26,'بھلائی والوں کے لیے بھلائی ہے اور اس سے بھی زائد (ف۶۶) اور ان کے منہ پر نہ چڑھے گی سیاہی اور نہ خواری (ف۶۷) وہی جنت والے ہیں وہ اس میں ہمیشہ رہیں گے،'),
 (93,10,27,'اور جنہوں نے برائیاں کمائیں (ف۶۸) تو برائی کا بدلہ اسی جیسا (ف۶۹) اور ان پر ذلت چڑھے گی، انہیں اللہ سے بچانے والا کوئی نہ ہوگا، گویا ان کے چہروں پر اندھیری رات کے ٹکڑے چڑھا دیئے ہیں (ف۷۰) وہی دوزخ والے ہیں، وہ اس میں ہمیشہ رہیں گے،'),
 (93,10,28,'اور جس دن ہم ان سب کو اٹھائیں گے (ف۷۱) پھر مشرکوں سے فرمائیں گے اپنی جگہ رہو تم اور تمہارے شریک (ف۷۲) تو ہم انہیں مسلمانوں سے جدا کردیں گے اور ان کے شریک ان سے کہیں گے تم ہمیں کب پوجتے تھے (ف۷۳)'),
 (93,10,29,'تو اللہ گواہ کافی ہے ہم میں اور تم میں کہ ہمیں تمہارے پوجنے کی خبر بھی نہ تھی،'),
 (93,10,30,'یہاں ہر جان جا نچ لے گی جو آگے بھیجا (ف۷۴) اور اللہ کی طرف پھیرے جائیں گے جو ان کا سچا مولیٰ ہے اور ان کی ساری بناوٹیں (ف۷۵) ان سے گم ہوجائیں گی (ف۷۶)'),
 (93,10,31,'تم فرماؤ تمہیں کون روزی دیتا ہے آسمان اور زمین سے (ف۷۷) یا کون مالک ہے کان اور آنکھوں کا (ف۷۸) اور کون نکالتا ہے زندہ کو مردے سے اور نکالتا ہے مردہ کو زندہ سے (ف۷۹) اور کون تمام کاموں کی تدبیر کرتا ہے تو اب کہیں گے کہ اللہ (ف۸۰) تو تم فرماؤ تو کیوں نہیں ڈرتے (ف۸۱)'),
 (93,10,32,'تو یہ اللہ ہے تمہارا سچا رب (ف۸۲) پھر حق کے بعد کیا ہے مگر گمراہی (ف۸۳) پھر کہاں پھرے جاتے ہو،'),
 (93,10,33,'یونہی ثابت ہوچکی ہے تیرے رب کی بات فاسقوں پر (ف۸۴) تو وہ ایمان نہیں لائیں گے،'),
 (93,10,34,'تم فرماؤ تمہارے شریکوں میں (ف۸۵) کوئی ایسا ہے کہ اول بنائے پھر فنا کے بعد دوبارہ بنائے (ف۸۶) تم فرماؤ اللہ اوّل بناتا ہے پھر فنا کے بعد دوبارہ بنائے گا تو کہاں اوندھے جاتے ہو (ف۸۷)'),
 (93,10,35,'تم فرماؤ تمہارے شریکوں میں کوئی ایسا ہے کہ حق کی راہ دکھائے (ف۸۸) تم فرماؤ کہ اللہ حق کی راہ دکھاتا ہے، تو کیا جو حق کی راہ دکھائے اس کے حکم پر چلنا چاہیے یا اس کے جو خود ہی راہ نہ پائے جب تک راہ نہ دکھایا جائے (ف۸۹) تو تمہیں کیا ہوا کیسا حکم لگاتے ہو،'),
 (93,10,36,'اور ان (ف۹۰) میں اکثر تو نہیں چلتے مگر گمان پر (ف۹۱) بیشک گمان حق کا کچھ کام نہیں دیتا، بیشک اللہ ان کاموں کو جانتا ہے،'),
 (93,10,37,'اور اس قرآن کی یہ شان نہیں کہ کوئی اپنی طرف سے بنالے بے اللہ کے اتارے (ف۹۲) ہاں وہ اگلی کتابوں کی تصدیق ہے (ف۹۳) اور لوح میں جو کچھ لکھا ہے سب کی تفصیل ہے اس میں کچھ شک نہیں ہے پروردگار عالم کی طرف سے ہے،'),
 (93,10,38,'کیا یہ کہتے ہیں (ف۹۴) کہ انہوں نے اسے بنالیا ہے تم فرماؤ (ف۹۵) تو اس جیسی کوئی ایک سورة لے آؤ اور اللہ کو چھوڑ کر جو مل سکیں سب کو بلا لاؤ (ف۹۶) اگر تم سچے ہو،'),
 (93,10,39,'بلکہ اسے جھٹلایا جس کے علم پر قابو نہ پایا (ف۹۷) اور ابھی انہوں نے اس کا انجام نہیں دیکھا (ف۹۸) ایسے ہی ان سے اگلوں نے جھٹلایا تھا (ف۹۹) تو دیکھو ظالموں کیسا انجام ہوا (ف۱۰۰)'),
 (93,10,40,'اور ان (ف۱۰۱) میں کوئی اس (ف۱۰۲) پر ایمان لاتا ہے اور ان میں کوئی اس پر ایمان نہیں لاتا ہے، اور تمہارا رب مفسدوں کو خوب جانتا ہے (ف۱۰۳)'),
 (93,10,41,'اور اگر وہ تمہیں جھٹلائیں (ف۱۰۴) تو فرمادو کہ میرے لیے میری کرنی اور تمہارے لیے تمہاری کرنی (اعمال) (ف۱۰۵) تمہیں میرے کام سے علاقہ نہیں اور مجھے تمہارے کام سے لاتعلق نہیں (ف۱۰۶)'),
 (93,10,42,'اور ان میں کوئی وہ ہیں جو تمہاری طرف کان لگاتے ہیں (ف۱۰۷) تو کیا تم بہروں کو سنا دو گے اگرچہ انہیں عقل نہ ہو (ف۱۰۸)'),
 (93,10,43,'اور ان میں کوئی تمہاری طرف تکتا ہے (ف۱۰۹) کیا تم اندھوں کو راہ دکھا دو گے اگرچہ وہ نہ سوجھیں،'),
 (93,10,44,'بیشک اللہ لوگوں پر کچھ ظلم نہیں کرتا (ف۱۰۰) ہاں لوگ ہی اپنی جانوں پر ظلم کرتے ہیں (ف۱۱۱)'),
 (93,10,45,'اور جس دن انہیں اٹھائے گا (ف۱۱۲) گویا دنیا میں نہ رہے تھے مگر اس دن کی ایک گھڑی (ف۱۱۳) آپس میں پہچان کریں گے (ف۱۱۴) کہ پورے گھاٹے میں رہے وہ جنہوں نے اللہ سے ملنے کو جھٹلایا اور ہدایت پر نہ تھے (ف۱۱۵)'),
 (93,10,46,'اور اگر ہم تمہیں دکھا دیں کچھ (ف۱۱۶) اس میں سے جو انہیں وعدہ دے رہے ہیں (ف۱۱۷) یا تمہیں پہلے ہی اپنے پاس بلالیں (ف۱۱۸) بہرحال انہیں ہماری طرف پلٹ کر آنا ہے پھر اللہ گواہ ہے (ف۱۱۹) ان کے کاموں پر،'),
 (93,10,47,'اور ہر امت میں ایک رسول ہوا (ف۱۲۰) جب ان کا رسول ان کے پاس آتا (ف۱۲۱) ان پر انصاف کا فیصلہ کردیا جاتا (ف۱۲۲) اور ان پر ظلم نہیں ہوتا،'),
 (93,10,48,'اور کہتے ہیں یہ وعدہ کب آئے گا اگر تم سچے ہو (ف۱۲۳)'),
 (93,10,49,'تم فرماؤ میں اپنی جان کے برے بھلے کا (ذاتی) اختیار نہیں رکھتا مگر جو اللہ چاہے (ف۱۲۴) ہر گروہ کا ایک وعدہ ہے (ف۱۲۵) جب ان کا وعدہ آئے گا تو ایک گھڑی نہ پیچھے ہٹیں نہ آگے بڑھیں،'),
 (93,10,50,'تم فرماؤ بھلا بتاؤ تو اگر اس کا عذاب (ف۱۲۶) تم پر رات کو آئے (ف۱۲۷) یا دن کو (ف۱۲۸) تو اس میں وہ کونسی چیز ہے کہ مجرموں کو جس کی جلدی ہے،'),
 (93,10,51,'تو کیا جب (ف۱۲۹) ہو پڑے گا اس وقت اس کا یقین کرو گے (ف۱۳۰) کیا اب مانتے ہو پہلے تو (ف۱۳۱) اس کی جلدی مچارہے تھے،'),
 (93,10,52,'پھر ظالموں سے کہا جائے گا ہمیشہ کا عذاب چکھو تمہیں کچھ اور بدلہ نہ ملے گا مگر وہی جو کماتے تھے (ف۱۳۲)'),
 (93,10,53,'اور تم سے پوچھتے ہیں کیا وہ (ف۱۳۳) حق ہے، تم فرماؤ، ہاں! میرے رب کی قسم بیشک وہ ضرور حق ہے، اور تم کچھ تھکا نہ سکو گے (ف۱۳۴)'),
 (93,10,54,'اور اگر ہر ظالم جان، زمین میں جو کچھ ہے (ف۱۳۵) سب کی مالک ہوتی، ضرور اپنی جان چھڑانے میں دیتی (ف۱۳۶) اور دل میں چپکے چپکے پشیمان ہوئے جب عذاب دیکھا اور ان میں انصاف سے فیصلہ کردیا گیا اور ان پر ظلم نہ ہوگا،'),
 (93,10,55,'سن لو بیشک اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور زمین میں (ف۱۳۷) سن لو بیشک اللہ کا وعدہ سچا ہے مگر ان میں اکثر کو خبر نہیں،'),
 (93,10,56,'وہ جِلاتا اور مارتا ہے اور اسی کی طرف پھرو گے،'),
 (93,10,57,'اے لوگو! تمہارے پاس تمہارے رب کی طرف سے نصیحت آئی (ف۱۳۸) اور دلوں کی صحت اور ہدایت اور رحمت ایمان والوں کے لیے،'),
 (93,10,58,'تم فرماؤ اللہ ہی کے فضل اور اسی کی رحمت اور اسی پر چاہیے کہ خوشی کریں (ف۱۳۹) وہ ان کے سب دھن دولت سے بہتر ہے،'),
 (93,10,59,'تم فرماؤ بھلا بتاؤ تو وہ جو اللہ نے تمہارے لیے رزق اتارا اس میں تم نے اپنی طرف سے حرام و حلال ٹھہرالیا (ف۱۴۰) تم فرماؤ کیا اللہ نے اس کی تمہیں اجازت دی یا اللہ پر جھوٹ باندھتے ہو (ف۱۴۱)'),
 (93,10,60,'اور کیا گمان ہے ان کا، جو اللہ پر جھوٹ باندھتے ہیں کہ قیامت میں ان کا کیا حال ہوگا، بیشک اللہ لوگوں پر فضل کرتا ہے (ف۱۴۲) مگر اکثر لوگ شکر نہیں کرتے،'),
 (93,10,61,'اور تم کسی کام میں ہو (ف۱۴۳) اور اس کی طرف سے کچھ قرآن پڑھو اور تم لوگ (ف۱۴۴) کوئی کام کرو ہم تم پر گواہ ہوتے ہیں جب تم اس کو شروع کرتے ہو، اور تمہارے رب سے ذرہ بھر کوئی چیز غائب نہیں زمین میں نہ آسمان میں اور نہ اس سے چھوٹی اور نہ اس سے بڑی کوئی چیز نہیں جو ایک روشن کتاب میں نہ ہو (ف۱۴۵)'),
 (93,10,62,'سن لو بیشک اللہ کے ولیوں پر نہ کچھ خو ف ہے نہ کچھ غم (ف۱۴۶)'),
 (93,10,63,'وہ جو ایمان لائے اور پرہیزگاری کرتے ہیں،'),
 (93,10,64,'انہیں خوشخبری ہے دنیا کی زندگی میں (ف۱۴۷) اور آخرت میں، اللہ کی باتیں بدل نہیں سکتیں (ف۱۴۸) یہی بڑی کامیابی ہے،'),
 (93,10,65,'اور تم ان کی باتو ں کا غم نہ کرو (ف۱۴۹) بیشک عزت ساری اللہ کے لیے ہے (ف۱۵۰) وہی سنتا جانتا ہے،'),
 (93,10,66,'سن لو بیشک اللہ ہی کے مِلک ہیں جتنے آسمانوں میں ہیں اور جتنے زمینوں میں (ف۱۵۱) اور کاہے کے پیچھے جارہے ہیں (ف۱۵۲) وہ جو اللہ کے سوا شریک پکار رہے ہیں، وہ تو پیچھے نہیں جاتے مگر گمان کے اور وہ تو نہیں مگر اٹکلیں دوڑاتے (ف۱۵۳)'),
 (93,10,67,'وہی ہے جس نے تمہارے لیے رات بنائی کہ اس میں چین پاؤ (ف۱۵۴) اور دن بنایا تمہاری آنکھوں کھولتا (ف۱۵۵) بیشک اس میں نشانیاں ہیں سننے والوں کے لیے (ف۱۵۶)'),
 (93,10,68,'بولے اللہ نے اپنے لیے اولاد بنائی (ف۱۵۷) پاکی اس کو، وہی بے نیاز ہے، اسی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں (ف۱۵۸) تمہارے پاس اس کی کوئی بھی سند نہیں، کیا اللہ پر وہ بات بتاتے ہو جس کا تمہیں علم نہیں،'),
 (93,10,69,'تم فرماؤ وہ جو اللہ پر جھوٹ باندھتے ہیں ان کا بھلا نہ ہوگا،'),
 (93,10,70,'دنیا میں کچھ برت لینا (فائدہ اٹھانا) ہے پھر انہیں ہماری طرف واپس آنا پھر ہم انہیں سخت عذاب چکھائیں گے بدلہ ان کے کفر کا،'),
 (93,10,71,'اور انہیں نوح کی خبر پڑھ کر سناؤ جب اس نے اپنی قوم سے کہا اے میری قوم اگر تم پر شاق گزرا ہے میرا کھڑا ہونا (ف۱۵۹) اور اللہ کی نشانیاں یاد دلانا (ف۱۶۰) تو میں نے اللہ ہی پر بھروسہ کیا (ف۱۶۱) تو مِل کر کام کرو اور اپنے جھوٹے معبودوں سمیت اپنا کام پکا کرلو تمہارے کام میں تم پر کچھ گنجلک (الجھن) نہ رہے پھر جو ہو سکے میرا کرلو اور مجھے مہلت نہ دو (ف۱۶۲)'),
 (93,10,72,'پھر اگر تم منہ پھیرو (ف۱۶۳) تو میں تم سے کچھ اجرت نہیں مانگتا (ف۱۶۴) میرا اجر تو نہیں مگر اللہ پر (ف۱۶۵) اور مجھے حکم ہے کہ میں مسلمانوں سے ہوں،'),
 (93,10,73,'تو انہوں نے اسے (ف۱۶۶) جھٹلایا تو ہم نے اسے اور جو اس کے ساتھ کشتی میں تھے ان کو نجات دی اور انہیں ہم نے نائب کیا (ف۱۶۷) اور جنہوں نے ہماری آیتیں جھٹلائیں ان کو ہم نے ڈبو دیا تو دیکھو ڈرائے ہوؤں کا انجام کیسا ہوا،'),
 (93,10,74,'پھر اس کے بعد اور رسول (ف۱۶۸) ہم نے ان کی قوموں کی طرف بھیجے تو وہ ان کے پاس روشن دلیلیں لائے تو وہ ایسے نہ تھے کہ ایمان لاتے اس پر جسے پہلے جھٹلا چکے تھے، ہم یونہی مہر لگادیتے ہیں سرکشوں کے دلوں پر،'),
 (93,10,75,'پھر ان کے بعد ہم نے موسٰی اور ہارون کو فرعون اور اس کے درباریوں کی طرف اپنی نشانیاں دے کر بھیجا تو انہوں نے تکبر کیا اور وہ مجرم لوگ تھے،'),
 (93,10,76,'تو جب ان کے پاس ہماری طرف سے حق آیا (ف۱۶۹) بولے یہ تو ضرور کھلا جادو ہے،'),
 (93,10,77,'موسیٰ نے کہا کیا حق کی نسبت ایسا کہتے ہو جب وہ تمہارے پاس آیا کیا یہ جادو ہے (ف۱۷۰) اور جادوگر مراد کو نہیں پہنچتے،'),
 (93,10,78,'بولے (ف۱۷۱) کیا تم ہمارے پاس اس لیے آئے ہو کہ ہمیں اس (ف۱۷۲) سے پھیردو جس پر ہم نے اپنے باپ دادا کو پایا اور زمین میں تمہیں دونوں کی بڑائی رہے، اور ہم تم پر ایمان لانے کے نہیں،'),
 (93,10,79,'اور فرعون (ف۱۷۳) بولا ہر جادوگر علم والے کو میرے پاس لے آؤ،'),
 (93,10,80,'پھر جب جادوگر آئے ان سے موسیٰ نے کہا ڈالو جو تمہیں ڈالنا ہے (ف۱۷۴)'),
 (93,10,81,'پھر جب انہوں نے ڈالا موسیٰ نے کہا یہ جو تم لائے یہ جادو ہے (ف۱۷۵) اب اللہ اسے باطل کردے گا، اللہ مفسدوں کا کام نہیں بناتا،'),
 (93,10,82,'اور اللہ اپنی باتوں سے (ف۱۷۶) حق کو حق کر دکھاتا ہے پڑے برا مانیں مجرم،'),
 (93,10,83,'تو موسیٰ پر ایمان نہ لائے مگر اس کی قوم کی اولاد سے کچھ لوگ (ف۱۷۷) فرعون اور اس کے درباریوں سے ڈرتے ہوئے کہ کہیں انہیں (ف۱۷۸) ہٹنے پر مجبور نہ کردیں اور بیشک فرعون زمین پر سر اٹھانے والا تھا، اور بیشک وہ حد سے گزر گیا (ف۱۷۹)'),
 (93,10,84,'اور موسیٰ نے کہا اے میری قوم اگر تم اللہ پر ایمان لائے تو اسی پر بھروسہ کرو (ف۱۸۰) اگر تم اسلام رکھتے ہو،'),
 (93,10,85,'بولے ہم نے اللہ پر بھروسہ کیا الہٰی ہم کو ظالم لوگوں کے لیے آزمائش نہ بنا (ف۱۸۱)'),
 (93,10,86,'اور اپنی رحمت فرماکر ہمیں کافروں سے نجات دے (ف۱۸۲)'),
 (93,10,87,'اور ہم نے موسیٰ اور اس کے بھائی کو وحی بھیجی کہ مصر میں اپنی قوم کے لیے مکانات بناؤ اور اپنے گھروں کو نماز کی جگہ کرو (ف۱۸۳) اور نماز قائم رکھو، اور مسلمانوں کو خوشخبری سناؤ (ف۱۸۴)'),
 (93,10,88,'اور موسیٰ نے عرض کی اے رب ہمارے تو نے فرعون اور اس کے سرداروں کو آرائش (ف۱۸۵) اور مال دنیا کی زندگی میں دیے، اے رب ہمارے! اس لیے کہ تیری راہ سے بہکادیں، اے رب ہمارے! ان کے مال برباد کردے (ف۱۸۶) اور ان کے دل سخت کردے کہ ایمان نہ لائیں جب تک دردناک عذاب نہ دیکھ لیں (ف۱۸۷)'),
 (93,10,89,'فرمایا تم دونوں کی دعا قبول ہوئی (ف۱۸۸) تو ثابت قدم رہو اور (ف۱۸۹) نادانوں کی راہ نہ چلو (ف۱۹۰)'),
 (93,10,90,'اور ہم بنی اسرائیل کو دریا پار لے گئے تو فرعون اور اس کے لشکروں نے ان کا پیچھا کیا سرکشی اور ظلم سے یہاں تک کہ جب اسے ڈوبنے نے ا ٓ لیا (ف۱۹۱) بولا میں ایمان لایا کہ کوئی سچا معبود نہیں سوا اس کے جس پر بنی اسرائیل ایمان لائے اور میں مسلمان ہوں (ف۱۹۲)'),
 (93,10,91,'کیا اب (ف۱۹۳) اور پہلے سے نافرمان رہا اور تو فسادی تھا (ف۱۹۴)'),
 (93,10,92,'آج ہم تیری لاش کو اوترا دیں (باقی رکھیں) گے تو اپنے پچھلوں کے لیے نشانی ہو (ف۱۹۵) اور بیشک لوگ ہما ری آ یتو ں سے غافل ہیں،'),
 (93,10,93,'اور بیشک ہم نے بنی اسرائیل کو عزت کی جگہ دی (ف۱۹۶) اور انہیں ستھری روزی عطا کی تو اختلاف میں نہ پڑے (ف۱۹۷) مگر علم آنے کے بعد (ف۱۹۸) بیشک تمہارا رب قیامت کے دن ان میں فیصلہ کردے گا جس بات میں جھگڑتے تھے (ف۱۹۹)'),
 (93,10,94,'اور اے سننے والے! اگر تجھے کچھ شبہ ہو اس میں جو ہم نے تیری طرف اتارا (ف۲۰۰) تو ان سے پوچھ دیکھ جو تجھ سے پہلے کتاب پڑھنے والے ہیں (ف۲۰۱) بیشک تیرے پاس تیرے رب کی طرف سے حق آیا (ف۲۰۲) تو تُو ہر گز شک والوں میں نہ ہو،'),
 (93,10,95,'اور ہرگز ان میں نہ ہونا جنہوں نے اللہ کی آیتیں جھٹلائیں کہ تو خسارے والوں میں ہوجائے گا،'),
 (93,10,96,'بیشک وہ جن پر تیرے رب کی بات ٹھیک پڑچکی ہے (ف۲۰۳) ایمان نہ لائیں گے،'),
 (93,10,97,'اگرچہ سب نشانیاں ان کے پاس آئیں جب تک دردناک عذاب نہ دیکھ لیں (ف۲۰۴)'),
 (93,10,98,'تو ہوئی ہوتی نہ کوئی بستی (ف۲۰۵) کہ ایمان لاتی (ف۲۰۶) تو اس کا ایمان کام آتا ہاں یونس کی قوم، جب ایمان لائے ہم نے ان سے رسوائی کا عذاب دنیا کی زندگی میں ہٹادیا اور ایک وقت تک انہیں برتنے دیا (ف۲۰۷)'),
 (93,10,99,'اور اگر تمہارا رب چاہتا زمین میں جتنے ہیں سب کے سب ایمان لے آتے (ف۲۰۸) تو کیا تم لوگوں کو زبردستی کرو گے یہاں تک کہ مسلمان ہوجائیں (ف۲۰۹)'),
 (93,10,100,'اور کسی جان کی قدرت نہیں کہ ایمان لے آئے مگر اللہ کے حکم سے (ف۲۱۰) اور عذاب ان پر ڈالنا ہے جنہیں عقل نہیں،'),
 (93,10,101,'تم فرماؤ دیکھو (ف۲۱۱) آسمانوں اور زمین میں کیا ہے (ف۲۱۲) اور آیتیں اور رسول انہیں کچھ نہیں دیتے جن کے نصیب میں ایمان نہیں،'),
 (93,10,102,'تو انہیں کاہے کا انتظار ہے مگر انہیں لوگوں کے سے دنوں کا جو ان سے پہلے ہو گزرے (ف۲۱۳) تم فرماؤ تو انتظار کرو میں بھی تمہارے ساتھ انتظار میں ہوں (ف۲۱۴)'),
 (93,10,103,'پھر ہم اپنے رسولوں اور ایمان والوں کو نجات دیں گے بات یہی ہے ہمارے ذمہ کرم پر حق ہے مسلمانوں کو نجات دینا،'),
 (93,10,104,'تم فرماؤ، اے لوگو! اگر تم میرے دین کی طرف سے کسی شبہ میں ہو تو میں تو اسے نہ پوجوں کا جسے تم اللہ کے سوا پوجتے ہو (ف۲۱۵) ہاں اس اللہ کو پوجتا ہوں جو تمہاری جان نکالے گا (ف۲۱۶) اور مجھے حکم ہے کہ ایمان والوں میں ہوں،'),
 (93,10,105,'اور یہ کہ اپنا منہ دین کے لیے سیدھا رکھ سب سے الگ ہوکر (ف۲۱۷) اور ہرگز شرک والوں میں نہ ہونا،'),
 (93,10,106,'اور اللہ کے سوا اس کی بندگی نہ کر جو نہ تیرا بھلا کرسکے نہ برا، پھر اگر ایسا کرے تو اس وقت تو ظالموں سے ہوگا،'),
 (93,10,107,'اور اگر تجھے اللہ کوئی تکلیف پہنچائے تو اس کا کوئی ٹالنے والا نہیں اس کے سوا، اور اگر تیرا بھلا چاہے تو اس کے فضل کے رد کرنے والا کوئی نہیں (ف۲۱۸) اسے پہنچا تا ہے اپنے بندوں میں جسے چاہے، اور وہی بخشنے والا مہربان ہے،'),
 (93,10,108,'تم فرماؤ اے لوگو! تمہارے پاس تمہارے رب کی طرف سے حق آیا (ف۲۱۹) تو جو راہ پر آیا وہ اپنے بھلے کو راہ پر آیا (ف۲۲۰) اور جو بہکا وہ اپنے برے کو بہکا (ف۲۲۱) اور کچھ میں کڑوڑا (حاکمِ اعلیٰ) نہیں (ف۲۲۲)'),
 (93,10,109,'اور اس پر چلو جو تم پر وحی ہوتی ہے اور صبر کرو (ف۲۲۳) یہاں تک کہ اللہ حکم فرمائے (ف۲۲۴) اور وہ سب سے بہتر حکم فرمانے والا ہے (ف۲۲۵)'),
 (93,11,1,'یہ ایک کتاب ہے جس کی آیتیں حکمت بھری ہیں (ف۲) پھر تفصیل کی گئیں (ف۳) حکمت والے خبردار کی طرف سے،'),
 (93,11,2,'کہ بندگی نہ کرو مگر اللہ کی بیشک میں تمہارے لیے اس کی طرف سے ڈر اور خوشی سنانے والا ہوں'),
 (93,11,3,'اور یہ کہ اپنے رب سے معافی مانگو پھر اس کی طرف توبہ کرو تمہیں بہت اچھا برتنا (فائدہ اٹھانا) دے گا (ف۴) ایک ٹھہرائے وعدہ تک اور ہر فضیلت والے (ف۵) کو اس کا فضل پہنچائے گا (ف۶) اور اگر منہ پھیرو تو میں تم پر بڑے دن (ف۷) کے عذاب کا خوف کرتا ہوں،'),
 (93,11,4,'تمہیں اللہ ہی کی طرف پھرنا ہے (ف۸) اور وہ ہر شے پر قادر (ف۹)'),
 (93,11,5,'سنو وہ اپنے سینے دوہرے کرتے (منہ چھپاتے) ہیں کہ اللہ سے پردہ کریں (ف۱۰) سنو جس وقت وہ اپنے کپڑوں سے سارا بدن ڈھانپ لیتے ہیں اس وقت بھی اللہ ان کا چھپا اور ظاہر سب کچھ جانتا ہے بیشک وہ دلوں کی بات جاننے والا ہے،'),
 (93,11,6,'اور زمین پر چلنے والا کوئی (ف۱۱) ایسا نہیں جس کا رزق اللہ کے ذمہٴ کرم پر نہ ہو (ف۱۲) اور جانتا ہے کہ کہاں ٹھہرے گا (ف۱۳) اور کہاں سپرد ہوگا (ف۱۴) سب کچھ ایک صاف بیان کرنے والی کتاب (ف۱۵) میں ہے،'),
 (93,11,7,'اور وہی ہے جس نے آسمانوں اور زمین کو چھ دن میں بنایا اور اس کا عرش پانی پر تھا (ف۱۶) کہ تمہیں آزمائے(ف۱۷) تم میں کس کا کام اچھا ہے، اور اگر تم فرماؤ کہ بیشک تم مرنے کے بعد اٹھائے جاؤ گے تو کافر ضرور کہیں گے کہ یہ (ف۱۸) تو نہیں مگر کھلا جادو (ف۱۹)'),
 (93,11,8,'اور اگر ہم ان سے عذاب (ف۲۰) کچھ گنتی کی مدت تک ہٹادیں تو ضرور کہیں گے کس چیز نے روکا ہے (ف۲۱) سن لو جس دن ان پر آئے گا ان سے پھیرا نہ جائے گا، اور انہیں گھیرے گا وہی عذاب جس کی ہنسی اڑاتے تھے'),
 (93,11,9,'اور اگر ہم آدمی کو اپنی کسی رحمت کا مزہ دیں (ف۲۲) پھر اسے اس سے چھین لیں ضرور وہ بڑا ناامید ناشکرا ہے (ف۲۳)'),
 (93,11,10,'اور اگر ہم اسے نعمت کا مزہ دیں اس مصیبت کے بعد جس اسے پہنچی تو ضرور کہے گا کہ برائیاں مجھ سے دور ہوئیں بیشک وہ خوش ہونے والا بڑائی مارنے والا ہے (ف۲۴)'),
 (93,11,11,'مگر جنہوں نے صبر کیا اور اچھے کام کیے (ف۲۵) ان کے لیے بخشش اور بڑا ثواب ہے،'),
 (93,11,12,'تو کیا جو وحی تمہاری طرف ہوتی ہے اس میں سے کچھ تم چھوڑ دو گے اور اس پر دل تنگ ہوگے (ف۲۶) اس بناء پر کہ وہ کہتے ہیں ان کے ساتھ کوئی خزانہ کیوں نہ اترا ان کے ساتھ کوئی فرشتہ آتا، تم تو ڈر سنانے والے ہو (ف۲۷) اور اللہ ہر چیز پر محافظ ہے،'),
 (93,11,13,'کیا (ف۲۸) یہ کہتے ہیں کہ انھوں نے اسے جی سے بنالیا، تم فرماؤ کہ تم ایسی بنائی ہوئی دس سورتیں لے آؤ (ف۲۹) اور اللہ کے سوا جو مل سکیں (ف۳۰) سب کو بلالو اگر تم سچے ہو (ف۳۱)'),
 (93,11,14,'تو اے مسلمانو اگر وہ تمہاری اس بات کا جواب نہ دے سکیں تو سمجھ لو کہ وہ اللہکے علم ہی سے اترا ہے اور یہ کہ اس کے سوا کوئی سچا معبود نہیں تو کیا اب تم مانو گے (ف۳۲)'),
 (93,11,15,'جو دنیا کی زندگی اور آرائش چاہتا ہو (ف۳۳) ہم اس میں ان کا پورا پھل دے دیں گے (ف۳۴) اور اس میں کمی نہ دیں گے،'),
 (93,11,16,'یہ ہیں وہ جن کے لیے آخرت میں کچھ نہیں مگر آ گ اور اکارت گیا جو کچھ وہاں کرتے تھے اور نابود ہوئے جو ان کے عمل تھے (ف۳۵)'),
 (93,11,17,'تو کیا وہ جو اپنے رب کی طرف سے روشن دلیل پر ہو (ف۳۶) اور اس پر اللہ کی طرف سے گواہ آئے (ف۳۷) اور اس سے پہلے موسیٰ کی کتاب (ف۳۸) پیشوا اور رحمت وہ اس پر (ف۳۹) ایمان لاتے ہیں، اور جو اس کا منکر ہو سارے گروہوں میں (ف۴۰) تو آگ اس کا وعدہ ہے تو اے سننے والے! تجھے کچھ اس میں شک نہ ہو، بیشک وہ حق ہے تیرے رب کی طرف سے لیکن بہت آدمی ایمان نہیں رکھتے،'),
 (93,11,18,'اور اس سے بڑھ کر ظالم کون جو اللہ پر جھوٹ باندھے (ف۴۱) اور اپنے رب کے حضور پیش کیے جائیں گے (ف۴۲) اور گواہ کہیں گے یہ ہیں جنہوں نے اپنے رب پر جھوٹ بولا تھا، ارے ظا لموں پر خدا کی لعنت (ف۴۳)'),
 (93,11,19,'جو اللہ کی راہ سے روکتے ہیں اور اس میں کجی چاہتے ہیں، اور وہی آخرت کے منکر ہیں،'),
 (93,11,20,'وہ تھکانے والے نہیں زمین میں (ف۴۴) اور نہ اللہ سے جدا ان کے کوئی حمایتی (ف۴۵) انہیں عذاب پر عذاب ہوگا (ف۴۶) وہ نہ سن سکتے تھے اور نہ دیکھتے (ف۴۷)'),
 (93,11,21,'وہی ہیں جنہوں نے اپنی جانیں گھاٹے میں ڈالیں اور ان سے کھوئی گئیں جو باتیں جوڑتے تھے خواہ نخواہ'),
 (93,11,22,'(ضرور) وہی آخرت میں سب سے زیادہ نقصان میں ہیں (ف۴۸)'),
 (93,11,23,'بیشک جو ایمان لائے اور اچھے کام کیے اور اپنے رب کی طرف رجوع لائے وہ جنت والے ہیں، وہ اس میں ہمیشہ رہیں گے،'),
 (93,11,24,'دونوں فریق (ف۴۹) کا حال ایسا ہے جیسے ایک اندھا اور بہرا اور دوسرا دیکھتا اور سنتا (ف۵۰)کيا ان دونوں حال کا ايک سا ہے (ف۱۵) تو کياتم دہيان نہيں کرتے'),
 (93,11,25,'اور بے شک ہم نے نوح کو اس کی قوم کی طرف بھيجا (ف۵۲) کہ میں تمہارے لیے صریح ڈر سنانے والا ہوں'),
 (93,11,26,'کہ اللہ کے سوا کسی کو نہ پوجو، بیشک میں تم پر ایک مصیبت والے دن کے عذاب سے ڈرتا ہوں (ف۵۳)'),
 (93,11,27,'تو اس کی قوم کے سردار جو کافر ہوئے تھے بولے ہم تو تمہیں اپنے ہی جیسا آدمی دیکھتے ہیں (ف۵۴) اور ہم نہیں دیکھتے کہ تمہاری پیروی کسی نے کی ہو مگر ہمارے کمینوں نے (ف۵۵) سرسری نظر سے (ف۵۶) اور ہم تم میں اپنے اوپر کوئی بڑائی نہیں پاتے (ف۵۷) بلکہ ہم تمہیں (ف۵۸) جھوٹا خیال کرتے ہیں،'),
 (93,11,28,'بولا اے میری قوم! بھلا بتاؤ تو اگر میں اپنے رب کی طرف سے دلیل پر ہوں (ف۵۹) اور اس نے مجھے اپنے پاس سے رحمت بخشی (ف۶۰) تو تم اس سے اندھے رہے، کیا ہم اسے تمہارے گلے چپیٹ (چپکا) دیں اور تم بیزار ہو (ف۶۱)'),
 (93,11,29,'اور اے قوم! میں تم سے کچھ اس پر (ف۶۲) مال نہیں مانگتا (ف۶۳) میرا اجر تو اللہ ہی پر ہے اور میں مسلمانوں کو دور کرنے والا نہیں (ف۶۴) بیشک وہ اپنے رب سے ملنے والے ہیں (ف۶۵) لیکن میں تم کو نرے جاہل لوگ پا تا ہوں (ف۶۶)'),
 (93,11,30,'اور اے قوم مجھے اللہ سے کون بچالے گا اگر میں انہیں دور کروں گا، تو کیا تمہیں دھیان نہیں،'),
 (93,11,31,'اور میں تم سے نہیں کہتا کہ میرے پاس اللہ کے خزانے ہیں اور نہ یہ کہ میں غیب جان جانتا ہوں اور نہ یہ کہتا ہوں کہ میں فرشتہ ہوں (ف۶۷) اور میں انہیں نہیں کہتا جن کو تمہاری نگاہیں حقیر سمجھتی ہیں کہ ہرگز انہیں اللہ کوئی بھلائی نہ دے گا، اللہ خوب جانتا ہے جو ان کے دلوں میں ہے (ف۶۸) ایسا کروں (ف۶۹) تو ضرور میں ظالموں میں سے ہوں (ف۷۰)'),
 (93,11,32,'بولے اے نوح تم ہم سے جھگڑے اور بہت ہی جھگڑے تو لے ا ٓ ؤ جس (ف۷۱) کا ہمیں وعدے دے رہے ہو اگر تم سچے ہو،'),
 (93,11,33,'بولا وہ تو اللہ تم پر لائے گا اگر چاہے اور تم تھکا نہ سکو گے (ف۷۲)'),
 (93,11,34,'اور تمہیں میری نصیحت نفع نہ دے گی اگر میں تمہارا بھلا چاہوں جبکہ اللہ تمہاری گمراہی چاہے، وہ تمہارا رب ہے، اور اسی کی طرف پھرو گے (ف۷۳)'),
 (93,11,35,'کیا یہ کہتے ہیں کہ انہوں نے اپنے جی سے بنالیا (ف۷۴) تم فرماؤ اگر میں نے بنالیا ہوگا تو میرا گناہ مجھ پر ہے (ف۷۵) اور میں تمہارے گناہ سے الگ ہوں،'),
 (93,11,36,'اور نوح کو وحی ہوئی تمہاری قوم سے مسلمان نہ ہوں گے مگر جتنے ایمان لاچکے تو غم نہ کھا اس پر جو وہ کرتے ہیں (ف۷۶)'),
 (93,11,37,'اور کشتی بناؤ ہمارے سامنے (ف۷۷) اور ہمارے حکم سے اور ظالموں کے بارے میں مجھ سے بات نہ کرنا (ف۷۸) وہ ضرور ڈوبائے جائیں گے (ف۷۹)'),
 (93,11,38,'اور نوح کشتی بناتا ہے اور جب اس کی قوم کے سردار اس پر گزرتے اس پر ہنستے (ف۸۰) بولا اگر تم ہم پر ہنستے ہو تو ایک وقت ہم تم پر ہنسیں گے (ف۸۱) جیسا تم ہنستے ہو (ف۸۲)'),
 (93,11,39,'تو اب جان جاؤ گے کس پر آتا ہے وہ عذاب کہ اسے رسوا کرے (ف۸۳) اور اترتا ہے وہ عذاب جو ہمیشہ رہے (ف۸۴)'),
 (93,11,40,'یہاں تک کہ کہ جب ہمارا حکم آیا (ف۸۵) اور تنور اُبلا (ف۸۶) ہم نے فرمایا کشتی میں سوار کرلے ہر جنس میں سے ایک جوڑا نر و مادہ اور جن پر بات پڑچکی ہے (ف۸۷) ان کے سوا اپنے گھر والوں اور باقی مسلمانوں کو اور اس کے ساتھ مسلمان نہ تھے مگر تھوڑے (ف۸۸)'),
 (93,11,41,'اور بولا اس میں سوار ہو (ف۸۹) اللہ کے نام پر اس کا چلنا اور اس کا ٹھہرنا (ف۹۰) بیشک میرا رب ضرور بخشنے والا مہربان ہے،'),
 (93,11,42,'اور وہی انہیں لیے جارہی ہے ایسی موجوں میں جیسے پہاڑ (ف۹۱) اور نوح نے اپنے بیٹے کو پکارا اور وہ اس سے کنارے تھا (ف۹۲) اے میرے بچے ہمارے ساتھ سوار ہوجا اور کافروں کے ساتھ نہ ہو (ف۹۳)'),
 (93,11,43,'بولا اب میں کسی پہاڑ کی پناہ لیتا ہوں وہ مجھے پانی سے بچالے گا، کہا آج اللہ کے عذاب سے کوئی بچانے والا نہیں مگر جس پر وہ رحم کرے اور ان کے بیچ میں موج آڑے آئی تو وہ ڈوبتوں میں رہ گیا (ف۹۴)'),
 (93,11,44,'اور حکم فرمایا گیا کہ اے زمین! اپنا پانی نگل لے اور اے آسمان! تھم جا اور پانی خشک کردیا گیا اور کام تمام ہوا اور کشتی (ف۹۵) کوہ ِ جودی پر ٹھہری (ف۹۶) اور فرمایا گیا کہ دور ہوں بے انصاف لوگ،'),
 (93,11,45,'اور نوح نے اپنے رب کو پکارا عرض کی اے میرے رب میرا بیٹا بھی تو میرا گھر والا ہے (ف۹۷) اور بیشک تیرا وعدہ سچا ہے اور تو سب سے بڑا حکم والا (ف۹۸)'),
 (93,11,46,'فرمایا اے نوح! وہ تیرے گھر والوں میں نہیں (ف۹۹) بیشک اس کے کام بڑے نالائق ہیں، تو مجھ سے وہ بات نہ مانگ جس کا تجھے علم نہیں (ف۱۰۰) میں تجھے نصیحت فرماتا ہوں کہ نادان نہ بن،'),
 (93,11,47,'عرض کی اے رب میرے میں تیری پناہ چاہتا ہوں کہ تجھ سے وہ چیز مانگوں جس کا مجھے علم نہیں، اور اگر تو مجھے نہ بخشے اور رحم نہ کرے تو میں زیاں کار ہوجاؤں،'),
 (93,11,48,'فرمایا گیا اے نوح! کشتی سے اتر ہماری طرف سے سلام اور برکتوں کےساتھ (ف۱۰۱) جو تجھ پر ہیں اور تیرے ساتھ کے کچھ گروہوں پر (ف۱۰۲) اور کچھ گروہ ہیں جنہیں ہم دنیا برتنے دیں گے (ف۱۰۳) پھر انہیں ہماری طرف سے دردناک عذاب پہنچے گا (ف۱۰۴)'),
 (93,11,49,'یہ غیب کی خبریں ہم تمہاری طرف وحی کرتے ہیں (ف۱۰۵) انہیں نہ تم جانتے تھے نہ تمہاری قوم اس (ف۱۰۶) سے پہلے، تو صبر کرو (ف۱۰۷) بیشک بھلا انجام پرہیزگاروں کا (ف۱۰۸)'),
 (93,11,50,'اور عاد کی طرف ان کے ہم قوم ہود کو (ف۱۰۹) کہا اے میری قوم! اللہ کو پوجو (ف۱۱۰) اس کے سوا تمہارا کوئی معبود نہیں، تم تو بڑے مفتری (بالکل جھوٹے الزام عائد کرنے والے) ہو (ف۱۱۱)'),
 (93,11,51,'اے قوم! میں اس پر تم سے کچھ اجرت نہیں مانگتا، میری مزدوری تو اسی کے ذمہ ہے جس نے مجھے پیدا کیا (ف۱۱۲) تو کیا تمہیں عقل نہیں (ف۱۱۳)'),
 (93,11,52,'اور اے میری قوم اپنے رب سے معافی چاہو (ف۱۱۴) پھر اس کی طرف رجوع لاؤ تم پر زور کا پانی بھیجے گا، اور تم میں جتنی قوت ہے اس سے زیادہ دے گا (ف۱۱۵) اور جرم کرتے ہوئے روگردانی نہ کرو (ف۱۱۶)'),
 (93,11,53,'بولے اے ہود تم کوئی دلیل لے کر ہمارے پاس نہ آئے (ف۱۱۷) اور ہم خالی تمہارے کہنے سے اپنے خداؤں کو چھوڑنے کے نہیں نہ تمہاری بات پر یقین لائیں،'),
 (93,11,54,'ہم تو یہی کہتے ہیں کہ ہمارے کسی خدا کی تمہیں بری جھپٹ (پکڑ) پہنچی (ف۱۱۸) کہا میں اللہ کو گواہ کرتا ہوں اور تم سب گواہ ہوجاؤ کہ میں بیزار ہوں ان سب سے جنہیں تم اللہ کے سوا اس کا شریک ٹھہراتے ہو،'),
 (93,11,55,'تم سب مل کر میرا برا چاہو (ف۱۱۹) پھر مجھے مہلت نہ دو (ف۱۲۰)'),
 (93,11,56,'میں نے اللہ پر بھروسہ کیا جو میرا رب ہے اور تمہارا رب، کوئی چلنے والا نہیں (ف۱۲۱) جس کی چوٹی اس کے قبضہٴ قدرت میں نہ ہو (ف۱۲۲) بیشک میرا رب سیدھے راستہ پر ملتا ہے،'),
 (93,11,57,'پھر اگر تم منہ پھیرو تو میں تمہیں پہنچا چکا جو تمہاری طرف لے کر بھیجا گیا (ف۱۲۳) اور میرا رب تمہاری جگہ اوروں کو لے آئے گا (ف۱۲۴) اور تم اس کا کچھ نہ بگاڑ سکو گے (ف۱۲۵) بیشک میرا رب ہر شے پر نگہبان ہے (ف۱۲۶)'),
 (93,11,58,'اور جب ہمارا حکم آیا ہم نے ہود اور اس کے ساتھ کے مسلمانوں کو (ف۱۲۷) اپنی رحمت فرما کر بچالیا (ف۱۲۸) اور انہیں (ف۱۲۹) سخت عذاب سے نجات دی،'),
 (93,11,59,'اور یہ عاد ہیں (ف۱۳۰) کہ اپنے رب کی آیتوں سے منکر ہوئے اور اس کے رسولوں کی نافرمانی کی اور ہر بڑے سرکش ہٹ دھرم کے کہنے پر چلے،'),
 (93,11,60,'اور ان کے پیچھے لگی اس دنیا میں لعنت اور قیامت کے دن، سن لو! بیشک عاد اپنے رب سے منکر ہوئے، ارے دور ہوں عاد ہود کی قوم،'),
 (93,11,61,'اور ثمود کی طرف ان کے ہم قوم صا لح کو (ف۱۳۱) کہا اے میری قوم اللہ کو پوجو (ف۱۳۲) اس کے سوا تمہارا کوئی معبود نہیں (ف۱۳۳) اس نے تمہیں زمین میں پیدا کیا (ف۱۳۴) اور اس میں تمہیں بسایا (ف۱۳۵) تو اس سے معافی چاہو پھر اس کی طرف رجوع لاؤ، بیشک میرا رب قریب ہے دعا سننے والا،'),
 (93,11,62,'بولے اے صا لح! اس سے پہلے تو تم ہم میں ہونہار معلوم ہوتے تھے (ف۱۳۶) کیا تم ہمیں اس سے منع کرتے ہو کہ اپنے باپ دادا کے معبودوں کو پوجیں اور بیشک جس بات کی طرف ہمیں بلاتے ہو ہم اس سے ایک بڑے دھوکا ڈالنے والے شک میں ہیں،'),
 (93,11,63,'بولا اے میری قوم! بھلا بتاؤ تو اگر میں اپنے رب کی طرف سے روشن دلیل پر ہوں اور اس نے مجھے اپنے پاس سے رحمت بخشی (ف۱۳۷) تو مجھے اس سے کون بچائے گا اگر میں اس کی نافرمانی کروں (ف۱۳۸) تو تم مجھے سوا نقصان کے کچھ نہ بڑھاؤ گے (ف۱۳۹)'),
 (93,11,64,'اور اے میری قوم! یہ اللہ کا ناقہ ہے تمہارے لیے نشانی تو اسے چھوڑ دو کہ اللہ کی زمین میں کھائے اور اسے بری طرح ہاتھ نہ لگانا کہ تم کو نزدیک عذاب پہنچے گا (ف۱۴۰)'),
 (93,11,65,'تو انہوں نے (ف۱۴۱) اس کی کونچیں کاٹیں تو صا لح نے کہا اپنے گھرو ں میں تین دن اور برت لو (فائدہ اٹھالو) (ف۱۴۲) یہ وعدہ ہے کہ جھوٹا نہ ہوگا (ف۱۴۳)'),
 (93,11,66,'پھر جب ہمارا حکم آیا ہم نے صا لح اور اس کے ساتھ کے مسلمانوں کو اپنی رحمت فرماکر (ف۱۴۴) بچالیا اور اس دن کی رسوائی سے، بیشک تمہارا رب قومی عزت والا ہے،'),
 (93,11,67,'اور ظالموں کو چنگھاڑ نے آ لیا (ف۱۴۵) تو صبح اپنے گھروں میں گھٹنوں کے بل پڑے رہ گئے،'),
 (93,11,68,'گویا کبھی یہاں بسے ہی نہ تھے، سن لو! بیشک ثمود اپنے رب سے منکر ہوئے ارے لعنت ہو ثمود پر،'),
 (93,11,69,'اور بیشک ہمارے فرشتے ابراہیم کے پاس (ف۱۴۶) مژدہ لے کر آئے بولے سلام کہا (ف۱۴۷) کہا سلام پھر کچھ دیر نہ کی کہ ایک بچھڑا بھنا لے آئے (ف۱۴۸)'),
 (93,11,70,'پھر جب دیکھا کہ ان کے ہاتھ کھانے کی طرف نہیں پہنچتے ان کو اوپری سمجھا اور جی ہی جی میں ان سے ڈرنے لگا، بولے ڈریے نہیں ہم قوم لوط کی طرف (ف۱۴۹) بھیجے گئے ہیں،'),
 (93,11,71,'اور اس کی بی بی (ف۱۵۰) کھڑی تھی وہ ہنسنے لگی تو ہم نے اسے (ف۱۵۱) اسحاق کی خوشخبری دی اور اسحاق کے پیچھے (ف۱۵۲) یعقوب کی (ف۱۵۳)'),
 (93,11,72,'بولی ہائے خرابی کیا میرے بچہ ہوگا اور میں بوڑھی ہوں (ف۱۵۴) اور یہ ہیں میرے شوہر بوڑھے (ف۱۵۵) بیشک یہ تو اچنبھے کی بات ہے،'),
 (93,11,73,'فرشتے بولے کیا اللہ کے کام کا اچنبھا کرتی ہو اللہ کی رحمت اور اس کی برکتیں تم پر اس گھر والو! بیشک (ف۱۵۶) وہی ہے سب خوبیوں والا عزت والا،'),
 (93,11,74,'پھر جب ابراہیم کا خوف زائل ہوا اور اسے خوشخبری ملی ہم سے قوم لوط کے بارے میں جھگڑنے لگا، (ف۱۵۷)'),
 (93,11,75,'بیشک ابراہیم تحمل والا بہت آہیں کرنے والا رجوع کرنے والا ہے (ف۱۵۷)'),
 (93,11,76,'اے ابراہیم اس خیال میں نہ پڑ بیشک تیرے رب کا حکم آچکا اور بیشک ان پر عذاب آنے والا ہے کہ پھیرا نہ جائے گا،'),
 (93,11,77,'اور جب لوط کے یہاں ہمارے فرشتے آئے (ف۱۵۹) اسے ان کا غم ہوا او ر ان کے سبب دل تنگ ہوا اور بولا یہ بڑی سختی کا دن ہے (ف۱۶۰)'),
 (93,11,78,'اور اس کے پاس کی قوم دوڑتی آئی، ور انہیں آگے ہی سے برے کاموں کی عادت پڑی تھی (ف۱۶۱) کہا اے قوم! یہ میری قوم کی بیٹیاں ہیں یہ تمہارے لیے ستھری ہیں تو اللہ سے ڈرو (ف۱۶۲) اور مجھے میرے مہمانوں میں رسوا نہ کرو، کیا تم میں ایک آدمی بھی نیک چلن نہیں،'),
 (93,11,79,'بولے تمہیں معلوم ہے کہ تمہاری قوم کی بیٹیوں میں ہمارا کوئی حق نہیں (ف۱۶۳) اور تم ضرور جانتے ہو جو ہماری خواہش ہے،'),
 (93,11,80,'بولے اے کاش! مجھے تمہارے مقابل زور ہوتا یا کسی مضبوط پائے کی پناہ لیتا (ف۱۶۴)'),
 (93,11,81,'فرشتے بولے اے لوط ہم تمہارے رب کے بھیجے ہوئے ہیں (ف۱۶۵) وہ تم تک نہیں پہنچ سکتے (ف۱۶۶) تو اپنے گھر والوں کو راتوں رات لے جاؤ اور تم میں کوئی پیٹھ پھیر کر نہ دیکھے (ف۱۶۷) سوائے تمہاری عورت کے اسے بھی وہی پہنچنا ہے جو انہیں پہنچے گا (ف۱۶۸) بیشک ان کا وعدہ صبح کے وقت کا ہے (ف۱۶۹) کیا صبح قریب نہیں،'),
 (93,11,82,'پھر جب ہمارا حکم آیا ہم نے اس بستی کے اوپر کو اس کا نیچا کردیا (ف۱۷۰) اور اس پر کنکر کے پتھر لگا تار برسائے،'),
 (93,11,83,'جو نشان کیے ہوئے تیرے رب کے پاس ہیں (ف۱۷۱) اور وہ پتھر کچھ ظالموں سے دور نہیں (ف۱۷۲)'),
 (93,11,84,'اور (ف۱۷۳) مدین کی طرف ان کے ہم قوم شعیب کو (ف۱۷۴) کہا اے میری قوم اللہ کو پوجو اس کے سوا کوئی معبود نہیں (ف۱۷۵) اور ناپ اور تول میں کمی نہ کرو بیشک میں تمہیں آسودہ حال دیکھتا ہوں (ف۱۷۶) اور مجھے تم پر گھیر لینے والے دن کا عذاب کا ڈر ہے (ف۱۷۷)'),
 (93,11,85,'اور اے میری قوم ناپ اور تول انصاف کے ساتھ پوری کرو اور لوگوں کو ان کی چیزیں گھٹا کر نہ دو اور زمین میں فساد مچاتے نہ پھرو،'),
 (93,11,86,'اللہ کا دیا جو بچ رہے وہ تمہارے لیے بہتر ہے اگر تمہیں یقین ہو (ف۱۷۸) اور میں کچھ تم پر نگہبان نہیں (ف۱۷۹)'),
 (93,11,87,'بولے اے شعیب!کیا تمہاری نماز تمہیں یہ حکم دیتی ہے کہ ہم اپنے باپ دادا کے خداؤں کو چھوڑ دیں (ف۱۸۰) یا اپنے مال میں جو چا ہیں نہ کریں (ف۱۸۱) ہاں جی تمہیں بڑے عقلمند نیک چلن ہو،'),
 (93,11,88,'کہا اے میری قوم بھلا بتاؤ تو اگر میں اپنے رب کی طرف سے ایک روشن دلیل پر ہوں (ف۱۸۲) او راس نے مجھے اپنے پاس سے اچھی روزی دی (ف۱۸۳) اور میں نہیں چاہتا ہوں کہ جس بات سے تمہیں منع کرتا ہوں آپ اس کے خلاف کرنے لگوں (ف۱۸۴) میں تو جہاں تک بنے سنوارنا ہی چاہتا ہوں، اور میری توفیق اللہ ہی کی طرف سے ہے، میں نے اسی پر بھروسہ کیا اور اسی کی طرف رجوع ہوتا ہوں،'),
 (93,11,89,'اور اے میری قوم تمہیں میری ضد یہ نہ کموادے کہ تم پر پڑے جو پڑا تھا نوح کی قوم یا ہود کی قوم یا صا لح کی قوم پر، اور لوط کی قوم تو کچھ تم سے دور نہیں (ف۱۸۵)'),
 (93,11,90,'اور اپنے رب سے معافی چاہو پھر اس کی طرف رجوع لاؤ، بیشک میرا رب مہربان محبت والا ہے،'),
 (93,11,91,'بولے اے شعیب! ہماری سمجھ میں نہیں آتیں تمہاری بہت سی باتیں اور بیشک ہم تمہیں اپنے میں کمزور دیکھتے ہیں (ف۱۸۶) اور اگر تمہارا کنبہ نہ ہوتا (ف۱۸۷) تو ہم نے تمہیں پتھراؤ کردیا ہوتا اور کچھ ہماری نگاہ میں تمہیں عزت نہیں،'),
 (93,11,92,'کہا اے میری قوم کیا تم پر میرے کنبہ کا دباؤ اللہ سے زیادہ ہے (ف۱۸۸) اور اسے تم نے اپنی پیٹھ کے پیچھے ڈال رکھا (ف۱۸۹) بیشک جو کچھ تم کرتے ہو سب میرے رب کے بس میں ہے،'),
 (93,11,93,'اور اے قوم تم اپنی جگہ اپنا کام کیے جا ؤ میں اپنا کام کرتا ہوں، اب جاننا چاہتے ہو کس پر آتا ہے وہ عذاب کہ اسے رسوا کرے گا اور کون جھوٹا ہے، (ف۱۹۰) اور انتظار کرو (ف۱۹۱) میں بھی تمہارے ساتھ انتظار میں ہوں،'),
 (93,11,94,'اور جب (ف۱۹۲) ہمارا حکم آیا ہم نے شعیب اور اس کے ساتھ کے مسلمانوں کو اپنی رحمت فرماکر بچالیا اور ظالموں کو چنگھاڑ نے آ لیا (ف۱۹۳) تو صبح اپنے گھروں میں گھٹنوں کے بل پڑے رہ گئے،'),
 (93,11,95,'گویا کبھی وہاں بسے ہی نہ تھے، ارے دُور ہوں مدین جیسے دور ہوئے ثمود (ف۱۹۴)'),
 (93,11,96,'اور بیشک ہم نے موسیٰ کو اپنی آیتوں (ف۱۹۵) اور صریح غلبے کے ساتھ،'),
 (93,11,97,'فرعون اور ا س کے درباریوں کی طرف بھیجا تو وہ فرعون کے کہنے پر چلے (ف۱۹۶) اور فرعون کا کام راستی کا نہ تھا (ف۱۹۷)'),
 (93,11,98,'اپنی قوم کے آگے ہوگا قیامت کے دن تو انہیں دوزخ میں لا اتارے گا (ف۱۹۸) اور و ه کیا ہی برا گھاٹ اترنے کا،'),
 (93,11,99,'اور ان کے پیچھے پڑی اس جہان میں لعنت اور قیامت کے دن (ف۱۹۹)کیا ہی برا انعام جو انہیں ملا،'),
 (93,11,100,'یہ بستیوں (ف۲۰۰) کی خبریں ہیں کہ ہم تمہیں سناتے ہیں (ف۲۰۱) ان میں کوئی کھڑی ہے (ف۲۰۲) اور کوئی کٹ گئی (ف۲۰۳)'),
 (93,11,101,'اور ہم نے ان پر ظلم نہ کیا خود انہوں نے (ف۲۰۴) اپنا برا کیا تو ان کے معبود جنہیں (ف۲۰۵) اللہ کے سوا پوجتے تھے ان کے کچھ کام نہ آئے (ف۲۰۶) جب تمہارے رب کا حکم آیا اور ان (ف۲۰۷) سے انہیں ہلاک کے سوا کچھ نہ بڑھا،'),
 (93,11,102,'اور ایسی ہی پکڑ ہے تیرے رب کی جب بستیوں کو پکڑتا ہے ان کے ظلم پر، بیشک اس کی پکڑ دردناک کرّ ی ہے (ف۲۰۸)'),
 (93,11,103,'بیشک اس میں نشانی (ف۲۰۹) ہے اس کے لیے جو آخرت کے عذاب سے ڈرے وہ دن ہے جس میں سب لوگ (ف۲۰۱) اکٹھے ہوں گے اور وہ دن حاضری کا ہے (ف۲۱۱)'),
 (93,11,104,'اور ہم اسے (ف۲۱۲) پیچھے نہیں ہٹاتے مگر ایک گنی ہوئی مدت کے لیئے (ف۲۱۳)'),
 (93,11,105,'جب وہ دن آئے گا کوئی بے حکم خدا بات نہ کرے گا (ف۲۱۴) تو ان میں کوئی بدبخت ہے اور کوئی خوش نصیب (ف۲۱۵)'),
 (93,11,106,'تو وہ جو بدبخت ہیں وہ تو دوزخ میں ہیں وہ اس گدھے کی طرح رینکیں گے'),
 (93,11,107,'وہ اس میں رہیں گے جب تک آسمان و زمین رہیں مگر جتنا تمہارے رب نے چاہا (ف۲۱۶) بیشک تمہارا رب جب جو چاہے کرے،'),
 (93,11,108,'اور وہ جو خوش نصیب ہوئے وہ جنت میں ہیں ہمیشہ اس میں رہیں گے جب تک آسمان و زمین مگر جتنا تمہارے رب نے چاہا (ف۲۱۷) یہ بخشش ہے کبھی ختم نہ ہوگی،'),
 (93,11,109,'تو اے سننے والے! دھوکا میں نہ پڑ اس سے جیسے یہ کافر پوجتے ہیں (ف۲۱۸) یہ ویسا ہی پوجتے ہیں جیسا پہلے ان کے باپ دادا پوجتے تھے (ف۲۱۹) اور بیشک ہم ان کا حصہ انہیں پورا پھیردیں گے جس میں کمی نہ ہوگی،'),
 (93,11,110,'اور بیشک ہم نے موسیٰ کو کتاب دی (ف۲۲۰) تو اس میں پھوٹ پڑگئی (ف۲۲۱) اگر تمہارے رب کی ایک بات (ف۲۲۲) پہلے نہ ہوچکی ہوتی تو جبھی ان کا فیصلہ کردیا جاتا (ف۲۲۳) اور بیشک وہ اس کی طرف سے (ف۲۲۴) دھوکا ڈالنے والے شک میں ہیں (ف۲۲۵)'),
 (93,11,111,'اور بیشک جتنے ہیں (ف۲۲۶) ایک ایک کو تمہارا رب اس کا عمل پورا بھردے گا اسے ان کے کا موں کی خبر ہے (ف۲۲۷)،'),
 (93,11,112,'تو قائم رہو (ف۲۲۸) جیسا تمہیں حکم ہے اور جو تمہارے ساتھ رجوع لایا ہے (ف۲۲۰) اور اے لوگو! سرکشی نہ کرو بیشک وہ تمہارے کام دیکھ رہا ہے،'),
 (93,11,113,'اور ظالموں کی طرف نہ جھکو کہ تمہیں آ گ چھوئے گی (ف۲۳۰) اور اللہ کے سوا تمہارا کوئی حما یتی نہیں (ف۲۳۱) پھر مدد نہ پاؤ گے،'),
 (93,11,114,'اور نماز قائم رکھو دن کے دونوں کناروں (ف۲۳۲) اور کچھ رات کے حصوں میں (ف۲۳۳) بیشک نیکیاں برائیوں کو مٹادیتی ہیں، (ف۲۳۳) یہ نصیحت ہے نصیحت ماننے والوں کو،'),
 (93,11,115,'اور صبر کرو کہ اللہ نیکوں کا نیگ (اجر) ضائع نہیں کرتا،'),
 (93,11,116,'تو کیوں نہ ہوئے تم میں سے اگلی سنگتوں (قوموں) میں (ف۲۳۵) ایسے جن میں بھلائی کا کچھ حصہ لگا رہا ہوتا کہ زمین میں فساد سے روکتے (ف۲۳۶) ہاں ان میں تھوڑے تھے وہی جن کو ہم نے نجات دی (ف۲۳۷) اور ظالم اسی عیش کے پیچھے پڑے رہے جو انہیں دیا گیا (ف۲۳۸) اور وہ گنہگار تھے،'),
 (93,11,117,'اور تمہارا رب ایسا نہیں کہ بستیوں کو بے وجہ ہلاک کردے اور ان کے لوگ اچھے ہوں،'),
 (93,11,118,'اور اگرتمہارا رب چاہتا تو سب آدمیوں کو ایک ہی امت کردیتا (ف۲۳۹) اور وہ ہمیشہ اختلاف میں رہیں گے (ف۲۴۰)'),
 (93,11,119,'مگر جن پر تمہارے رب نے رحم کیا (ف۲۴۱) اور لوگ اسی لیے بنائے ہیں (ف۲۴۲) اور تمہارے رب کی بات پوری ہوچکی کہ بیشک ضرور جہنم بھر دوں گا جنوں اور آدمیوں کو ملا کر (ف۲۴۳)'),
 (93,11,120,'اور سب کچھ ہم تمہیں رسولوں کی خبریں سناتے ہیں جس سے تمہا را دل ٹھیرائیں (ف۲۴۴) اور اس سورت میں تمہارے پاس حق آیا (ف۲۴۵) اور مسلمانوں کو پند و نصیحت (ف۲۴۶)'),
 (93,11,121,'اور کافروں سے فرماؤ تم اپنی جگہ کام کیے جاؤ (ف۲۴۷) ہم اپنا کام کرتے ہیں (ف۲۴۸)'),
 (93,11,122,'اور راہ دیکھو ہم بھی راہ دیکھتے ہیں (ف۲۴۹)'),
 (93,11,123,'اور اللہ ہی کے لیے ہیں آسمانوں اور زمین کے غیب (ف۲۵۰) اور اسی کی طرف سب کاموں کی رجوع ہے تو اس کی بندگی کرو اور اس پر بھروسہ رکھو، اور تمہارا رب تمہارے کا موں سے غافل نہیں،						'),
 (93,12,1,'یہ روشن کتاب کی آیتیں ہیں (ف۲)'),
 (93,12,2,'بیشک ہم نے اسے عربی قرآن اتارا کہ تم سمجھو،'),
 (93,12,3,'ہم تمہیں سب اچھا بیان سناتے ہیں (ف۳) اس لیے کہ ہم نے تمہاری طرف اس قرآن کی وحی بھیجی اگرچہ بیشک اس سے پہلے تمہیں خبر نہ تھی،'),
 (93,12,4,'یاد کرو جب یوسف نے اپنے با پ (ف۴) سے کہا اے میرے باپ میں نے گیارہ تارے اور سورج اور چاند دیکھے انہیں اپنے لیے سجدہ کرتے دیکھا (ف۵)'),
 (93,12,5,'کہا اے میرے بچے اپنا خواب اپنے بھائیوں سے نہ کہنا (ف۶) وہ تیرے ساتھ کوئی چا ل چلیں گے (ف۷) بیشک شیطان آدمی کا کھلا دشمن ہے (ف۸)'),
 (93,12,6,'اور اسی طرح تجھے تیرا رب چن لے گا (ف۹) اور تجھے باتوں کا انجام نکا لنا سکھائے گا (ف۱۰) اور تجھ پر اپنی نعمت پوری کرے گا اور یعقوب کے گھر والوں پر (ف۱۱) جس طرح تیرے پہلے دنوں باپ دادا ابراہیم ؑ اور اسحق ؑ پر پوری کی (ف۱۲) بیشک تیرا رب علم و حکمت والا ہے،'),
 (93,12,7,'بیشک یوسف اور اس کے بھائیوں میں (ف۱۳) پوچھنے والوں کے لیے نشانیاں ہیں (ف۱۴)'),
 (93,12,8,'جب بولے (ف۱۵) کہ ضرور یوسف اور اس کا بھائی (ف۱۶) ہمارے باپ کو ہم سے زیادہ پیارے ہیں اور ہم ایک جماعت ہیں (ف۱۷) بیشک ہمارے باپ صراحةً ان کی محبت میں ڈوبے ہوئے ہیں (ف۱۸)'),
 (93,12,9,'یوسف کو مار ڈالو یا کہیں زمین میں پھینک آؤ (ف۱۹) کہ تمہارے باپ کا منہ صرف تمہاری ہی طرف رہے (ف۲۰) اور اس کے بعد پھر نیک ہوجانا (ف۲۱)'),
 (93,12,10,'ان میں ایک کہنے والا (ف۲۲) بولا یوسف کو مارو نہیں (ف۲۳) اور اسے اندھے کنویں میں ڈال دو کہ کوئی چلتا اسے آکر لے جائے (ف۲۴) اگر تمہیں کرنا ہے (ف۲۵)'),
 (93,12,11,'بولے اے ہمارے باپ ! آپ کو کیا ہوا کہ یوسف کے معامل ہ میں ہمارا اعتبار نہیں کرتے اور ہم تو اس کے خیر خواہ ہیں،'),
 (93,12,12,'کل اسے ہمارے ساتھ بھیج دیجئے کہ میوے کھائے اور کھیلے (ف۲۶) اور بیشک ہم اس کے نگہبان ہیں (ف۲۷)'),
 (93,12,13,'بولا بیشک مجھے رنج دے گا کہ اسے لے جاؤ (ف۲۸) اور ڈرتا ہوں کہ اسے بھیڑیا کھالے (ف۲۹) اور تم اس سے بے خبر رہو (ف۳۰)'),
 (93,12,14,'بولے اگر اسے بھیڑیا کھا جائے اور ہم ایک جماعت ہیں جب تو ہم کسی مصرف کے نہیں (ف۳۱)'),
 (93,12,15,'پھر جب اسے لے گئے (ف۳۲) اور سب کی رائے یہی ٹھہری کہ اسے اندھے کنویں میں ڈال دیں (ف۳۳) اور ہم نے اسے وحی بھیجی (ف۳۴) کہ ضرور تو انہیں ان کا یہ کام جتادے گا (ف۳۵) ایسے وقت کہ وہ نہ جانتے ہوں گے (ف۳۶)'),
 (93,12,16,'اور رات ہوئے اپنے باپ کے پاس روتے ہوئے آئے (ف۳۷)'),
 (93,12,17,'بولے اے ہمارے باپ ہم دوڑ کرتے نکل گئے (ف۳۸) اور یوسف کو اپنے اسباب کے پاس چھوڑا تو اسے بھیڑیا کھا گیا اور آپ کسی طرح ہمارا یقین نہ کریں گے اگرچہ ہم سچے ہوں (ف۳۹)'),
 (93,12,18,'اور اس کے کر ُتے پر ایک جھوٹا خون لگا لائے (ف۴۰) کہا بلکہ تمہارے دلوں نے ایک بات تمہارے واسطے بنالی ہے (ف۴۱) تو صبر اچھا، اور اللہ ہی مدد چاہتا ہوں ان باتوں پر جو تم بتارہے ہو (ف۴۲)'),
 (93,12,19,'اور ایک قافلہ آیا (ف۴۳) انہوں نے اپنا پانی لانے والا بھیجا (ف۴۴) تو اس نے اپنا ڈول ڈال (ف۴۵) بولا آہا کیسی خوشی کی بات ہے یہ تو ایک لڑکا ہے اور اسے ایک پونجی بناکر چھپالیا (ف۴۶) اور اللہ جانتا ہے جو وہ کرتے ہیں،'),
 (93,12,20,'اور بھائیوں نے اسے کھوٹے داموں گنتی کے روپوں پر بیچ ڈالا (ف۴۷) اور انہیں اس میں کچھ رغبت نہ تھی (ف۴۸)'),
 (93,12,21,'اور مصر کے جس شخص نے اسے خریدا وہ اپنی عورت سے بولا (ف۴۹) انہیں عزت سے رکھو (ف۵۰) شاید ان سے ہمیں نفع پہنچے (ف۵۱) یا ان کو ہم بیٹا بنالیں (ف۵۲) اور اسی طرح ہم نے یوسف کو اس زمین میں جماؤ (رہنے کا ٹھکانا) دیا اور اس لیے کہ اسے باتوں کا انجام سکھائیں ۰ف۵۳) اور اللہ اپنے کام پر غالب ہے مگر اکثر آدمی نہیں جانتے،'),
 (93,12,22,'اور جب اپنی پوری قوت کو پہنچا (ف۵۴) ہم نے اسے حکم اور علم عطا فرمایا (ف۵۵) اور ہم ایسا ہی صلہ دیتے ہیں نیکوں کو،'),
 (93,12,23,'اور وہ جس عورت (ف۵۶) کے گھر میں تھا اس نے اسے لبھایا کہ اپنا آپا نہ روکے (ف۵۷) اور دروازے سب بند کردیے (ف۵۸) اور بولی آؤ تمہیں سے کہتی ہوں (ف۵۹) کہا اللہ کی پناہ (ف۶۰) وہ عزیز تو میرا رب یعنی پرورش کرنے والا ہے اس نے مجھے اچھی طرح رکھا (ف۶۱) بیشک ظالموں کا بھلا نہیں ہوتا،'),
 (93,12,24,'اور بیشک عورت نے اس کا ارادہ کیا اور وہ بھی عورت کا ارادہ کرتا اگر اپنے رب کی دلیل نہ دیکھ لیتا (ف۶۲) ہم نے یوں ہی کیا کہ اس سے برائی اور بے حیائی کو پھیر دیں (ف۶۳) بیشک وہ ہمارے چنے ہوئے بندوں میں سے ہے (ف۶۴)'),
 (93,12,25,'اور دونوں دروازے کی طرف دوڑے (ف۶۵) اور عورت نے اس کا کر ُتا پیچھے سے چیر لیا اور دونوں کو عورت کا میاں (ف۶۶) دروازے کے پاس ملا (ف۶۷) بولی کیا سزا ہے اس کی جس نے تیری گھر والی سے بدی چاہی (ف۶۸) مگر یہ کہ قید کیا جائے یا دکھ کی مار (ف۶۹)'),
 (93,12,26,'کہا اس نے مجھ کو لبھایا کہ میں اپنی حفاظت نہ کروں (ف۷۰) اور عورت کے گھر والوں میں سے ایک گواہ نے (ف۷۱) گواہی دی اگر ان کا کر ُتا آگے سے چرا ہے تو عورت سچی ہے اور انہوں نے غلط کہا (ف۷۲)'),
 (93,12,27,'اور اگر ان کا کر ُتا پیچھے سے چاک ہوا تو عورت جھوٹی ہے اور یہ سچے (ف۷۳)'),
 (93,12,28,'پھر جب عزیز نے اس کا کر ُتا پیچھے سے چرا دیکھا (ف۷۴) بولا بیشک یہ تم عورتوں کا چرتر (فریب) ہے بیشک تمہارا چرتر (فریب) بڑا ہے (ف۷۵)'),
 (93,12,29,'اے یوسف! تم اس کا خیال نہ کرو (ف۷۶) اور اے عورت! تو اپنے گناہ کی معافی مانگ (ف۷۷) بیشک تو خطاواروں میں ہے (ف۷۸)'),
 (93,12,30,'اور شہر میں کچھ عورتیں بولیں (ف۷۹) کہ عزیز کی بی بی اپنے نوجوان کا دل لبھاتی ہ ے بیشک ان کی محبت اس کے دل میں پَیر گئی (سماگئی) ہے ہم تو اسے صر یح خود رفتہ پاتے ہیں (ف۸۰)'),
 (93,12,31,'تو جب زلیخا نے ان کا چرچا سنا تو ان عورتوں کو بلا بھیجا (ف۸۱) اور ان کے لیے مسندیں تیار کیں (ف۸۲) اور ان میں ہر ایک کو ایک چھری دی (ف۸۳) اور یوسف (ف۸۴) سے کہا ان پر نکل آؤ (ف۸۵) جب عورتوں نے یوسف کو دیکھا اس کی بڑائی بولنے لگیں (ف۸۶) اور اپنے ہاتھ کاٹ لیے (ف۸۷) اور بولیں اللہ کو پاکی ہے یہ تو جنس بشر سے نہیں (ف۸۸) یہ تو نہیں مگر کوئی معزز فرشتہ،'),
 (93,12,32,'زلیخا نے کہا تو يہ ہیں وہ جن پر مجھے طعنہ دیتی تھیں (ف۸۹) اور بیشک میں نے ان کا جِی لبھانا چاہا تو انہوں نے اپنے آپ کو بچا یا (ف۹۰) اور بیشک اگر وہ یہ کام نہ کریں گے جو میں ان سے کہتی ہوں تو ضرور قید میں پڑیں گے اور وہ ضرور ذلت اٹھائیں گے (ف۹۱)'),
 (93,12,33,'یوسف نے عرض کی اے میرے رب! مجھے قید خانہ زیادہ پسند ہے اس کام سے جس کی طرف یہ مجھے بلاتی ہیں اور اگر تو مجھ سے ان کا مکر نہ پھیرے گا (ف۹۲) تو میں ان کی طرف مائل ہوں گا اور نادان بنوں گا،'),
 (93,12,34,'تو اس کے رب نے اس کی سن لی اور اس سے عورتوں کا مکر پھیردیا، بیشک وہی سنتا جانتا ہے (ف۹۳)'),
 (93,12,35,'پھر سب کچھ نشانیاں دیکھ دکھا کر پچھلی مت انہیں یہی آئی کہ ضرور ایک مدت تک اسے قیدخانہ میں ڈالیں (ف۹۴)'),
 (93,12,36,'اور اس کے ساتھ قیدخانہ میں دو جوان داخل ہوئے (ف۹۵) ان میں ایک (ف۹۶) بولا میں نے خواب میں دیکھا کہ (ف۹۷) شراب نچوڑتا ہوں اور دوسرا بولا (ف۹۸) میں نے خواب دیکھا کہ میرے سر پر کچھ روٹیاں ہیں جن میں سے پرند کھاتے ہیں، ہمیں اس کی تعبیر بتایے، بیشک ہم آپ کو نیکو کار دیکھتے ہیں (ف۹۹)'),
 (93,12,37,'یوسف نے کہا جو کھانا تمہیں ملا کرتا ہے وہ تمہارے پاس نہ آنے پائے گا کہ میں اس کی تعبیر اس کے آنے سے پہلے تمہیں بتادوں گا (ف۱۰۰) یہ ان علموں میں سے ہے جو مجھے میرے رب نے سکھایا ہے، بیشک میں نے ان لوگوں کا دین نہ مانا جو اللہ پر ایمان نہیں لاتے اور وہ آخرت سے منکر ہیں،'),
 (93,12,38,'اور میں نے اپنے باپ دادا ابراہیم ؑ اور اسحق ؑ اور یعقوب کا دین اختیار کیا (ف۱۰۱) ہمیں نہیں پہنچتا کہ کسی چیز کو اللہ کا شریک ٹھہرائیں، یہ (ف۱۰۲) اللہ کا ایک فضل ہے ہم پر اور لوگوں پر مگر اکثر لوگ شکر نہیں کرتے (ف۱۰۳)'),
 (93,12,39,'اے میرے قیدخانہ کے دونوں ساتھیو! کیا جدا جدا رب (ف۱۰۴) اچھے یا ایک اللہ جو سب پر غالب، (ف۱۰۵)'),
 (93,12,40,'تم اس کے سوا نہیں پوجتے مگر نرے نام (فرضی نام) جو تم نے اور تمہارے باپ دادا نے تراش لیے ہیں (ف۱۰۶) اللہ نے ان کی کوئی سند نہ اتاری، حکم نہیں مگر اللہ کا اس نے فرمایا کہ اس کے سوا کسی کو نہ پوجو (ف۱۰۷) یہ سیدھا دین ہے (ف۱۰۸) لیکن اکثر لوگ نہیں جانتے (ف۱۰۹)'),
 (93,12,41,'اے قید خانہ کے دونوں ساتھیو! تم میں ایک تو اپنے رب (بادشاہ) کو شراب پلائے گا (ف۱۱۰) رہا دوسرا (ف۱۱۱) وہ سو ُلی دیا جائے گا تو پرندے اس کا سر کھائیں گے (ف۱۱۲) حکم ہوچکا اس بات کا جس کا تم سوال کرتے تھے (ف۱۱۳)'),
 (93,12,42,'اور یوسف نے ان دونوں میں سے جسے بچتا سمجھا (ف۱۱۴) اس سے کہا اپنے رب (بادشاہ) کے پاس میرا ذکر کرنا (ف۱۱۵) تو شیطان نے اسے بھلا دیا کہ اپنے رب (بادشاہ) کے سامنے یوسف کا ذکر کرے تو یوسف کئی برس اور جیل خانہ میں رہا (ف۱۱۶)'),
 (93,12,43,'اور بادشاہ نے کہا میں نے خواب میں دیکھیں سات گائیں فربہ کہ انہیں سات دُبلی گائیں کھارہی ہیں اور سات بالیں ہری اور دوسری سات سوکھی (ف۱۱۷) اے درباریو! میرے خواب کا جواب دو اگر تمہیں خواب کی تعبیر آتی ہو،'),
 (93,12,44,'بولے پریشان خوابیں ہیں اور ہم خواب کی تعبیر نہیں جانتے،'),
 (93,12,45,'اور بولا وہ جو ان دونوں میں سے بچا تھا (ف۱۱۸) اور ایک مدت بعد اسے یاد آیا (ف۱۱۹) میں تمہیں اس کی تعبیر بتاؤں گا مجھے بھیجو (ف۱۲۰)'),
 (93,12,46,'اے یوسف! اے صدیق! ہمیں تعبیر دیجئے سات فربہ گایوں کی جنہیں سات دُبلی کھاتی ہیں اور سات ہری بالیں اور دوسری سات سوکھی (ف۱۲۱) شاید میں لوگوں کی طرف لوٹ کر جاؤں شاید وہ آگاہ ہوں (ف۱۲۲)'),
 (93,12,47,'کہا تم کھیتی کرو گے سات برس لگارتار (ف۱۲۳) تو جو کاٹو اسے اس کی بال میں رہنے دو (ف۱۲۴) مگر تھوڑا جتنا کھالو (ف۱۲۵)'),
 (93,12,48,'پھر اس کے بعد سات برس کرّے (سخت تنگی والے) آئیں گے (ف۱۲۶) کہ کھا جائیں گے جو تم نے ان کے لیے پہلے جمع کر رکھا تھا (ف۱۲۷) مگر تھوڑا جو بچالو (ف۱۲۸)'),
 (93,12,49,'پھر ان کے بعد ایک برس آئے گا جس میں لوگوں کو مینھ دیا جائے گا اور اس میں رس نچوڑیں گے (ف۱۲۹)'),
 (93,12,50,'اور بادشاہ بولا کہ انہیں میرے پاس لے آؤ تو جب اس کے پاس ایلچی آیا (ف۱۳۰) کہا اپنے رب (بادشاہ) کے پاس پلٹ جا پھر اس سے پوچھ (ف۱۳۱) کیا حال ہے اور عورتوں کا جنہوں نے اپنے ہاتھ کاٹے تھے، بیشک میرا رب ان کا فریب جانتا ہے (ف۱۳۲)'),
 (93,12,51,'بادشاہ نے کہا اے عورتو! تمہارا کیا کام تھا جب تم نے یوسف کا دل لبھانا چاہا، بولیں اللہ کو پاکی ہے ہم نے ان میں کوئی بدی نہیں پائی عزیز کی عورت (ف۱۳۳) بولی اب اصلی بات کھل گئی، میں نے ان کا جی لبھانا چاہا تھا اور وہ بیشک سچے ہیں (ف۱۳۴)'),
 (93,12,52,'یوسف نے کہا یہ میں نے اس لیے کیا کہ عزیز کو معلوم ہوجائے کہ میں نے پیٹھ پیچھے اس کی خیانت نہ کی اور اللہ دغا بازوں کا مکر نہیں چلنے دیتا،'),
 (93,12,53,'اور میں اپنے نفس کو بے قصور نہیں بتاتا (ف۱۳۵) بیشک نفس تو برائی کا بڑا حکم دینے والا ہے مگر جس پر میرا رب رحم کرے (ف۱۳۶) بیشک میرا رب بخشنے والا مہربان ہے (ف۱۳۷)'),
 (93,12,54,'اور بادشاہ بولا انہيں میرے پاس لے آؤ کہ میں انہیں اپنے لیے چن لوں (ف۱۳۸) پھر جب اس سے بات کی کہا بیشک آج آپ ہمارے یہاں معزز معتمد ہیں (ف۱۳۹)'),
 (93,12,55,'یوسف نے کہا مجھے زمین کے خزانوں پر کردے بیشک میں حفاظت والا علم والا ہوں (ف۱۴۰)'),
 (93,12,56,'اور یوں ہی ہم نے یوسف کو اس ملک پر قدرت بخشی اس میں جہاں چاہے رہے (ف۱۴۱) ہم اپنی رحمت (ف۱۴۲) جسے چاہیں پہنچائیں اور ہم نیکوں کا نیگ (اَجر) ضائع نہیں کرتے،'),
 (93,12,57,'اور بیشک آخرت کا ثواب ان کے لیے بہتر جو ایمان لائے اور پرہیزگار رہے (ف۱۴۳)'),
 (93,12,58,'اور یوسف کے بھائی آئے تو اس کے پاس حاضر ہوئے تو یوسف نے انہیں (ف۱۴۴) پہچان لیا اور وہ اس سے انجان رہے (ف۱۴۵)'),
 (93,12,59,'اور جب ان کا سامان مہیا کردیا (ف۱۴۶) کہ اپنا سوتیلا بھائی (ف۱۴۷) میرے پاس لے آؤ کیا نہیں دیکھتے کہ میں پورا ناپتا ہوں (ف۱۴۸) اور میں سب سے بہتر مہمان نواز ہوں،'),
 (93,12,60,'پھر اگر اسے لیکر میرے پاس نہ آؤ تو تمہارے لیے میرے یہاں ماپ نہیں اور میرے پاس نہ پھٹکنا،'),
 (93,12,61,'بولے ہم اس کی خواہش کریں گے اس کے باپ سے اور ہمیں یہ ضرور کرنا،'),
 (93,12,62,'اور یوسف نے اپنے غلاموں سے کہا ان کی پونجی ان کی خورجیوں میں رکھ دو (ف۱۴۹) شاید وہ اسے پہچانیں جب اپنے گھر کی طرف لوٹ کر جائیں (ف۱۵۰) شاید وہ واپس آئیں،'),
 (93,12,63,'پھر جب وہ اپنے باپ کی طرف لوٹ کر گئے (ف۱۵۱) بولے اے ہمارے باپ ہم سے غلہ روک دیا گیا ہے (ف۱۵۲) تو ہمارے بھائی کو ہمارے پاس بھیج دیجئے کہ غلہ لائیں اور ہم ضرور اس کی حفاظت کریں گے،'),
 (93,12,64,'کہا کیا اس کے بارے میں تم پر ویسا ہی اعتبار کرلوں جیسا پہلے اس کے بھائی کے بارے میں کیا تھا (ف۱۵۳) تو اللہ سب سے بہتر نگہبان اور وہ ہر مہربان سے بڑھ کر مہربان،'),
 (93,12,65,'اور جب انہوں نے اپنا اسباب کھولا اپنی پونجی پائی کہ ان کو پھیر دی گئی ہے، بولے اے ہمارے باپ اب اور کیا چاہیں، یہ ہے ہماری پونجی ہمیں واپس کردی گئی اور ہم اپنے گھر کے لیے غلہ لائیں اور اپنے بھائی کی حفاظت کریں اور ایک اونٹ کا بوجھ اور زیادہ پائیں، یہ دنیا بادشاہ کے سامنے کچھ نہیں (ف۱۵۴)'),
 (93,12,66,'کہا میں ہرگز اسے تمہارے ساتھ نہ بھیجوں گا جب تک تم مجھے کا اللہ کا یہ عہد نہ دے دو (ف۱۵۵) کہ ضرور اسے لے کر آ ؤ گے مگر یہ کہ تم گھِر جاؤ (ف۱۵۶) پھر انہوں نے یعقوب کو عہد دے دیا کہا (ف۱۵۷) اللہ کا ذمہ ہے ان باتوں پر جو کہہ رہے ہیں،'),
 (93,12,67,'اور کہا اے میرے بیٹوں! (ف۱۵۸) ایک دروازے سے نہ داخل ہونا اور جدا جدا دروا زوں سے جانا (ف۱۵۹) میں تمہیں اللہ سے بچا نہیں سکتا (ف۱۶۰) حکم تو سب اللہ ہی کا ہے، میں نے اسی پر بھروسہ کیا اور بھروسہ کرنے والوں کو اسی پر بھروسہ چاہیے،'),
 (93,12,68,'اور جب وہ داخل ہوئے جہاں سے ان کے باپ نے حکم دیا تھا (ف۱۶۱) وہ کچھ انہیں کچھ انہیں اللہ سے بچا نہ سکتا ہاں یعقوب کے جی کی ایک خواہش تھی جو اس نے پوری کرلی، اور بیشک وہ صاحب علم ہے ہمارے سکھائے سے مگر اکثر لوگ نہیں جانتے (ف۱۶۲)'),
 (93,12,69,'اور جب وہ یوسف کے پاس گئے (ف۱۶۳) اس نے اپنے بھائی کو اپنے پاس جگہ دی (ف۱۶۴) کہا یقین جان میں ہی تیرا بھائی (ف۱۶۵) ہوں تو یہ جو کچھ کرتے ہیں اس کا غم نہ کھا (ف۱۶۶)'),
 (93,12,70,'پھر جب ان کا سامان مہیا کردیا (ف۱۶۷) پیالہ اپنے بھائی کے کجاوے میں رکھ دیا (ف۱۶۸) پھر ایک منادی نے ندا کی اے قافلہ والو! بیشک تم چور ہو،'),
 (93,12,71,'بولے اور ان کی طرف متوجہ ہوئے تم کیا نہیں پاتے،'),
 (93,12,72,'بولے، بادشاہ کا پیمانہ نہیں ملتا اور جو اسے لائے گا اس کے لیے ایک اونٹ کا بوجھ ہے اور میں اس کا ضامن ہوں،'),
 (93,12,73,'بولے خدا کی قسم! تمہیں خوب معلوم ہے کہ ہم زمین میں فساد کرنے نہ آئے اور نہ ہم چور ہیں،'),
 (93,12,74,'بولے پھر کیا سزا ہے اس کی اگر تم جھوٹے ہو (ف۱۶۹)'),
 (93,12,75,'بولے اس کی سزا یہ ہے کہ جس کے اسباب میں ملے وہی اس کے بدلے میں غلام بنے (ف۱۷۰) ہمارے یہاں ظالموں کی یہی سزا ہے (ف۱۷۱)'),
 (93,12,76,'تو اول ان کی خرُجیوں سے تلاشی شروع کی اپنے بھائی (ف۱۷۲) کی خرُجی سے پہلے پھر اسے اپنے بھائی کی خرُجی سے نکال لیا (ف۱۷۳) ہم نے یوسف کو یہی تدبیر بتائی (ف۱۷۴) بادشاہی قانون میں اسے نہیں پہنچتا تھا کہ اپنے بھائی کو لے لے (ف۱۷۵) مگر یہ کہ خدا چاہے (ف۱۷۶) ہم جسے چاہیں درجوں بلند کریں (ف۱۷۷) اور ہر علم والے اوپر ایک علم والا ہے (ف۱۷۸)'),
 (93,12,77,'بھائی بولے اگر یہ چوری کرے (ف۱۷۹) تو بیشک اس سے پہلے اس کا بھائی چوری کرچکا ہے (ف۱۸۰) تو یوسف نے یہ بات اپنے دل میں رکھی اور ان پر ظاہر نہ کی، جی میں کہا تم بدتر جگہ ہو (ف۱۸۱) اور اللہ خوب جانتا ہے جو باتیں بناتے ہو،'),
 (93,12,78,'بولے اے عزیز! اس کے ایک باپ ہیں بوڑھے بڑے (ف۱۸۲) تو ہم میں اس کی جگہ کسی کو لے لو، بیشک ہم تمہارے احسان دیکھ رہے ہیں،'),
 (93,12,79,'کہا (ف۱۸۳) خدا کی پناہ کہ ہم میں مگر اسی کو جس کے پاس ہمارا مال ملا (ف۱۸۴) جب تو ہم ظالم ہوں گے،'),
 (93,12,80,'پھر جب اس سے نا امید ہوئے الگ جاکر سرگوشی کرنے لگے، ان کا بڑا بھائی بولا کیا تمہیں خبر نہیں کہ تمہارے باپ نے تم سے اللہ کا عہد لے لیا تھا اور اس سے پہلے یوسف کے حق میں تم نے کیسی تقصیر کی تو میں یہاں سے نہ ٹلوں گا یہاں تک کہ میرے باپ (ف۱۸۵) اجازت دیں یا اللہ مجھے حکم فرمائے (ف۱۸۶) اور اس کا حکم سب سے بہتر،'),
 (93,12,81,'اپنے باپ کے پاس لوٹ کر جاؤ پھر عرض کرو اے ہمارے باپ بیشک آپ کے بیٹے نے چوری کی (ف۱۸۷) اور ہم تو اتنی ہی بات کے گواہ ہوئے تھے جتنی ہمارے علم میں تھی (ف۱۸۸) اور ہم غیب کے نگہبان نہ تھے (ف۱۸۹)'),
 (93,12,82,'اور اس بستی سے پوچھ دیکھئے جس میں ہم تھے اور اس قافلہ سے جس میں ہم آئے، اور ہم بیشک سچے ہیں (ف۱۹۰)'),
 (93,12,83,'کہا (ف۱۹۱) تمہارے نفس نے تمہیں کچھ حیلہ بنادیا، تو اچھا صبر ہے، قریب ہے کہ اللہ ان سب کو مجھ سے لا، ملائے (ف۱۹۲) بیشک وہی علم و حکمت والا ہے،'),
 (93,12,84,'اور ان سے منہ پھیرا (ف۱۹۳) اور کہا ہائے افسوس! یوسف کی جدائی پر اور اس کی آنکھیں غم سے سفید ہوگئیں (ف۱۹۴) وہ غصہ کھا تا رہا،'),
 (93,12,85,'بولے (ف۱۹۵) خدا کی قسم! آپ ہمیشہ یوسف کی یاد کرتے رہیں گے یہاں تک کہ گور کنارے جا لگیں یا جان سے گزر جائیں،'),
 (93,12,86,'کہا میں تو اپنی پریشانی اور غم کی فریاد اللہ ہی سے کرتا ہوں (ف۱۹۶) اور مجھے اللہ کی وہ شانیں معلوم ہیں جو تم نہیں جانتے (ف۱۹۷)'),
 (93,12,87,'اے بیٹو! جا ؤ یوسف اور اس کے بھائی کا سراغ لگاؤ اور اللہ کی رحمت سے مایوس نہ ہو، بیشک اللہ کی رحمت سے نا امید نہیں ہوتے مگر کافر لوگ (ف۱۹۸)'),
 (93,12,88,'پھر جب وہ یوسف کے پاس پہنچے بولے اے عزیز ہمیں اور ہمارے گھر والوں کو مصیبت پہنچی (ف۱۹۹) اور ہم بے قدر پونجی لے کر آئے ہیں (ف۲۰۰) تو آپ ہمیں پورا ناپ دیجئے (ف۲۰۱) اور ہم پر خیرات کیجئے (ف۲۰۲) بیشک اللہ خیرات والوں کو صلہ دیتا ہے (ف۲۰۳)'),
 (93,12,89,'بولے کچھ خبر ہے تم نے یوسف اور اس کے بھائی کے ساتھ کیا کِیا تھا جب تم نادان تھے (ف۲۰۴)'),
 (93,12,90,'بولے کیا سچ مچ آپ ہی یوسف ہیں، کہا میں یوسف ہوں اور یہ میرا بھائی، بیشک اللہ نے ہم پر احسان کیا (ف۲۰۵) بیشک جو پرہیزگاری اور صبر کرے تو اللہ نیکوں کا نیگ (اجر) ضائع نہیں کرتا (ف۲۰۶)'),
 (93,12,91,'بولے خدا کی قسم! بیشک اللہ نے آپ کو ہم پر فضیلت دی اور بیشک ہم خطاوار تھے (ف۲۰۷)'),
 (93,12,92,'کہا آج (ف۲۰۸) تم پر کچھ ملامت نہیں، اللہ تمہیں معاف کرے، اور وہ سب مہربانوں سے بڑھ کر مہربان ہے (ف۲۰۹)'),
 (93,12,93,'میرا یہ کرتا لے جاؤ (ف۲۱۰) اسے میرے باپ کے منہ پر ڈالو ان کی آنکھیں کھل جائیں گی اور اپنے سب گھر بھر کو میرے پاس لے آ ؤ،'),
 (93,12,94,'جب قافلہ مصر سے جدا ہوا (ف۲۱۱) یہاں ان کے باپ نے (ف۲۱۲) کہا بیشک میں یوسف کی خوشبو پا تا ہوں اگر مجھے یہ نہ کہو کہ سٹھ (بہک) گیا ہے،'),
 (93,12,95,'بیٹے بولے خدا کی قسم! آپ اپنی اسی پرانی خود رفتگی میں ہیں (ف۲۱۳)'),
 (93,12,96,'پھر جب خوشی سنانے والا آیا (ف۲۱۴) اس نے وہ کرتا یعقوب کے منہ پر ڈالا اسی وقت اس کی آنکھیں پھر آئیں (دیکھنے لگیں) کہ میں نہ کہتا تھا کہ مجھے اللہ کی وہ شانیں معلوم ہیں جو تم نہیں جانتے (ف۲۱۵)'),
 (93,12,97,'بولے اے ہمارے باپ! ہمارے گناہوں کی معافی مانگئے بیشک ہم خطاوار ہیں،'),
 (93,12,98,'کہا جلد میں تمہاری بخشش اپنے رب سے چاہو ں گا، بیشک وہی بخشنے والا مہربان ہے (ف۲۱۶)'),
 (93,12,99,'پھر جب وہ سب یوسف کے پاس پہنچے اس نے اپنے ماں (ف۲۱۷) باپ کو اپنے پاس جگہ دی اور کہا مصر میں (ف۲۱۸) داخل ہو اللہ چاہے تو امان کے ساتھ (ف۲۱۹)'),
 (93,12,100,'اور اپنے ماں باپ کو تخت پر بٹھایا اور سب (ف۲۲۰) اس کے لیے سجدے میں گرے (ف۲۲۱) اور یوسف نے کہا اے میرے باپ یہ میرے پہلے خواب کی تعبیر ہے (ف۲۲۲) بیشک اسے میرے رب نے سچا کیا، اور بیشک اس نے مجھ پر احسان کیا کہ مجھے قید سے نکالا (ف۲۲۳) اور آپ سب کو گاؤں سے لے آیا بعد اس کے کہ شیطان نے مجھ میں اور میرے بھائیوں میں ناچاقی کرادی تھی، بیشک میرا رب جس بات کو چاہے آسان کردے بیشک وہی علم و حکمت والا ہے (ف۲۲۴)'),
 (93,12,101,'اے میرے رب بیشک تو نے مجھے ایک سلطنت دی اور مجھے کچھ باتوں کا انجام نکالنا سکھایا، اے آسمانوں اور زمین کے بنانے والے تو میرا کام بنانے والا ہے دنیا اور آخرت میں، مجھے مسلمان اٹھا اور ان سے مِلا جو تیرے قرب خاص کے لائق ہیں (ف۲۲۵)'),
 (93,12,102,'یہ کچھ غیب کی خبریں ہیں جو ہم تمہاری طرف وحی کرتے ہیں اور تم ان کے پاس نہ تھے (ف۲۲۶) جب انہوں نے اپنا کام پکا کیا تھا اور وہ داؤں چل رہے تھے (ف۲۲۷)'),
 (93,12,103,'اور اکثر آدمی تم کتنا ہی چاہو ایمان نہ لائیں گے،'),
 (93,12,104,'اور تم اس پر ان سے کچھ اجرت نہ مانگتے یہ (ف۲۲۸) تو نہیں مگر سارے جہان کو نصیحت،'),
 (93,12,105,'اور کتنی نشانیاں ہیں (ف۲۲۹) آسمانوں اور زمین میں کہ اکثر لوگ ان پر گزرتے ہیں (ف۲۳۰) اور ان سے بے خبر رہتے ہیں،'),
 (93,12,106,'اور ان میں اکثر وہ ہیں کہ اللہ پر یقین نہیں لاتے مگر شرک کرتے ہوئے (ف۲۳۱)'),
 (93,12,107,'کیا اس سے نڈر ہو بیٹھے کہ اللہ کا عذاب انہیں آکر گھیر لے یا قیامت ان پر اچانک آجائے اور انہیں خبر نہ ہو،'),
 (93,12,108,'تم فرماؤ (ف۲۳۲) یہ میری راہ ہے میں اللہ کی طرف بلاتا ہوں میں اور جو میرے قدموں پرچلیں دل کی آنکھیں رکھتے ہیں ۰ف۲۳۳) اور اللہ کو پاکی ہے (ف۲۳۴) اور میں شریک کرنے والا نہیں،'),
 (93,12,109,'اور ہم نے تم سے پہلے جتنے رسول بھیجے سب مرد ہی تھے (ف۲۳۵) جنہیں ہم وحی کرتے اور سب شہر کے ساکن تھے (ف۲۳۶) تو یہ لوگ زمین پرچلے نہیں تو دیکھتے ان سے پہلوں کا کیا انجام ہوا (ف۲۳۷) اور بیشک آخرت کا گھر پرہیزگاروں کے لیے بہتر تو کیا تمہیں عقل نہیں،'),
 (93,12,110,'یہاں تک جب رسولوں کو ظاہری اسباب کی امید نہ رہی (ف۲۳۸) اور لوگ سمجھے کہ رسولوں نے غلط کہا تھا (ف۲۳۹) اس وقت ہماری مدد آئی تو جسے ہم نے چاہا بچالیا گیا (ف۲۴۰) اور ہمارا عذاب مجرموں سے پھیرا نہیں جاتا،'),
 (93,12,111,'بیشک ان کی خبروں سے (ف۲۴۱) عقل مندوں کی آنکھیں کھلتی ہیں (ف۲۴۲) یہ کوئی بناوٹ کی بات نہیں (ف۲۴۳) لیکن اپنوں سے اگلے کاموں کی (ف۲۴۴) تصدیق ہے اور ہر چیز کا مفصل بیان اور مسلمانوں کے لیے ہدایت اور رحمت،						'),
 (93,13,1,'یہ کتاب کی آیتیں ہیں (ف۲) اور وہ جو تمہاری طرف تمہارے رب کے پاس سے اترا (ف۳) حق ہے (ف۴) مگر اکثر آدمی ایمان نہیں لاتے (ف۵)'),
 (93,13,2,'اللہ ہے جس نے آسمانوں کو بلند کیا بے ستونوں کے کہ تم دیکھو (ف۶) پھر عرش پر استوا فرمایا جیسا اس کی شان کے لائق ہے اور سورج اور چاند کو مسخر کیا (ف۷) ہر ایک، ایک ٹھہرائے ہوئے وعدہ تک چلتا ہے (ف۸) اللہ کام کی تدبیر فرماتا اور مفصل نشانیاں بتاتا ہے (ف۹) کہیں تم اپنے رب رب کا ملنا یقین کرو (ف۱۰)'),
 (93,13,3,'اور وہی ہے جس نے زمین کو پھیلا اور اس میں لنگر (ف۱۱) اور نہریں بنائیں، اور زمین ہر قسم کے پھل دو دو طرح کے بنائے (ف۱۲) رات سے دن کو چھپا لیتا ہے، بیشک اس میں نشانیاں ہیں دھیان کرنے والوں کو (ف۱۳)'),
 (93,13,4,'اور زمین کے مختلف قطعے ہیں اور ہیں پاس پاس (ف۱۴) اور باغ ہیں انگوروں کے اور کھیتی اور کھجور کے پیڑ ایک تھالے (تھال) سے اُگے اور الگ الگ سب کو ایک ہی پانی دیا جا تا ہے اور پھلوں میں ہم ایک کو دوسرے سے بہتر کرتے ہیں، بیشک اس میں نشانیاں ہیں عقل مندوں کے لیے (ف۱۵)'),
 (93,13,5,'اور اگر تم تعجب کرو (ف۱۶) تو اچنبھا تو ان کے اس کہنے کا ہے کہ کیا ہم مٹی ہو کر پھر نئے بنیں گے (ف۱۷) وہ ہیں جو اپنے رب سے منکر ہوئے اور وہ ہیں جن کی گردنوں میں طوق ہوں گے (ف۱۸) اور وہ دوزخ والے ہیں انھیں اسی میں رہنا،'),
 (93,13,6,'اور تم سے عذاب کی جلدی کرتے ہیں رحمت سے پہلے (ف۱۹) اور ان اگلوں کی سزائیں ہوچکیں (ف۲۰) اور بیشک تمہارا رب تو لوگوں کے ظلم پر بھی انہیں ایک طرح کی معافی دیتا ہے (ف۲۱) اور بیشک تمہارے رب کا عذاب سخت ہے (ف۲۲)'),
 (93,13,7,'اور کا فر کہتے ہیں ان پر ان کی طرف سے کوئی نشانی کیو ں نہیں اتری (ف۲۳) تم تو ڈر سنانے والے ہو اور ہر قوم کے ہادی (ف۲۴)'),
 (93,13,8,'اللہ جانتا ہے جو کچھ کسی مادہ کے پیٹ میں ہے (ف۲۵) اور پیٹ جو کچھ گھٹتے بڑھتے ہیں (ف۲۶) اور ہر چیز اس کے پاس ایک اندازے سے ہے (ف۲۵)'),
 (93,13,9,'ہر چھپے اور کھلے کا جاننے والا سب سے بڑا بلندی والا (ف۲۸)'),
 (93,13,10,'برابر ہیں جو تم میں بات آہستہ کہے اور جو آواز سے اور جو رات میں چھپا ہے اور جو دن میں راہ چلتا ہے (ف۲۹)'),
 (93,13,11,'آدمی کے لیے بدلی والے فرشتے ہیں اس کے آگے پیچھے (ف۳۰) کہ بحکم خدا اس کی حفاظت کرتے ہیں (ف۳۱) بیشک اللہ کسی قوم سے اپنی نعمت نہیں بدلتا جب تک وہ خود (ف۳۲) اپنی حالت نہ بدلیں، اور جب کسی قوم سے برائی چاہے (ف۳۳) تو وہ پھر نہیں سکتی، اور اس کے سوا ان کا کوئی حمایتی نہیں (ف۳۴)'),
 (93,13,12,'وہی ہے تمہیں بجلی دکھاتا ہے ڈر کو اور امید کو (ف۳۵) اور بھاری بدلیاں اٹھاتا ہے،'),
 (93,13,13,'اور گر ج اسے سراہتی ہوئی اس کی پاکی بولتی ہے (ف۳۶) اور فرشتے اس کے ڈر سے (ف۳۷) اور کڑک بھیجتا ہے (ف۳۸) تو اسے ڈالتا ہے جس پر چاہے اور وہ اللہ میں جھگڑتے ہوتے ہیں (ف۳۹) اور اس کی پکڑ سخت ہے،'),
 (93,13,14,'اسی کا پکارنا سچا ہے (ف۴۰) اور اُس کے سوا جن کو پکارتے ہیں (ف۴۱) وہ ان کی کچھ بھی نہیں سنتے مگر اس کی طرح جو پانی کے سامنے اپنی ہتھیلیاں پھیلائے بیٹھا ہے کہ اس کے منہ میں پہنچ جائے (ف۴۲) اور وہ ہرگز نہ پہنچے گا، اور کافروں کی ہر دعا بھٹکتی پھرتی ہے،'),
 (93,13,15,'اور اللہ ہی کو سجدہ کرتے ہیں جتنے آسمانوں اور زمین میں ہیں خوشی سے (ف۴۳) خواہ مجبوری سے (ف۴۴) اور ان کی پرچھائیاں ہر صبح و شام (ف۴۵) السجدة ۔۲'),
 (93,13,16,'تم فرماؤ کون رب ہے آسمانوں اور زمین کا، تم خود ہی فرما ؤ اللہ (ف۴۶) تم فرما ؤ تو کیا اس کے سوا تم نے وہ حمایتی بنائے ہیں جو اپنا بھلا برا نہیں کرسکتے ہیں (ف۴۷) تم فرما ؤ کیا برابر ہوجائیں گے اندھا اور انکھیارا (بینا) (ف۴۸) یا کیا برابر ہوجائیں گی اندھیریاں اور اجالا (ف۴۹) کیا اللہ کے لیے ایسے شریک ٹھہراتے ہیں جنہوں نے اللہ کی طرح کچھ بنایا تو انہیں ان کا اور اس کا بنانا ایک سا معلوم ہوا (ف۵۰) تم فرما ؤ اللہ ہر چیز کا بنانے والا ہے (ف۵۱) اور وہ اکیلا سب پر غالب ہے (ف۵۲)'),
 (93,13,17,'اس نے آسمان سے پانی اتارا تو نالے اپنے اپنے لائق بہہ نکلے تو پانی کی رو اس پر ابھرے ہوئے جھاگ اٹھا لائی، اور جس پر آگ دہکاتے ہیں (ف۵۳) گہنا یا اور اسباب (ف۵۴) بنانے کو اس سے بھی ویسے ہی جھاگ اٹھتے ہیں اللہ بتاتا ہے کہ حق و باطل کی یہی مثال ہے، تو جھاگ تو پھک (جل) کر دور ہوجاتا ہے، اور وہ جو لوگوں کے کام آئے زمین میں رہتا ہے (ف۵۵) اللہ یوں ہی مثالیں بیان فرماتا ہے،'),
 (93,13,18,'جن لوگوں نے اپنے رب کا حکم مانا انہیں کے لیے بھلائی ہے (ف۵۶) اور جنہوں نے اس کا حکم نہ مانا (ف۵۷) اگر زمین میں جو کچھ ہے وہ سب اور اس جیسا اور ان کی ملِک میں ہوتا تو اپنی جان چھڑانے کو دے دیتے یہی ہیں جن کا برُ ا حساب ہوگا (ف۵۸) اور ان کا ٹھکانا جہنم ہے، اور کیا ہی بُرا بچھونا،'),
 (93,13,19,'تو کیا وہ جانتا ہے جو کچھ تمہاری طرف تمہارے رب کے پاس سے اترا حق ہے (ف۵۹) وہ اس جیسا ہوگا جو اندھا ہے (ف۶۰) نصیحت وہی مانتے ہیں جنہیں عقل ہے،'),
 (93,13,20,'وہ جو اللہ کا عہد پورا کرتے ہیں (ف۶۱) اور قول باندھ کر پھرتے نہیں'),
 (93,13,21,'اور وہ کہ جوڑتے ہیں اسے جس کے جوڑنے کا اللہ نے حکم دیا (ف۶۲) اور اپنے رب سے ڈرتے ہیں اور حساب کی بُرائی سے اندیشہ رکھتے ہیں (ف۶۳)'),
 (93,13,22,'اور وہ جنہوں نے صبر کیا (ف۶۴) اپنے رب کی رضا چاہنے کو اور نماز قائم رکھی اور ہمارے دیئے سے ہماری راہ میں چھپے اور ظاہر کچھ خرچ کیا (ف۶۵) اور برائی کے بدلے بھلائی کرکے ٹالتے ہیں (ف۶۶) انہیں کے لیے پچھلے گھر کا نفع ہے،'),
 (93,13,23,'بسنے کے باغ جن میں وہ داخل ہوں گے اور جو لائق ہوں (ف۶۷) ان کے باپ دادا اور بیبیوں اور اولاد میں (ف۶۸) اور فرشتے (ف۶۹) ہر دروازے سے ان پر (ف۷۰) یہ کہتے آئیں گے،'),
 (93,13,24,'سلامتی ہو تم پر تمہارے صبر کا بدلہ تو پچھلا گھر کیا ہی خوب ملا،'),
 (93,13,25,'اور وہ جو اللہ کا عہد اس کے پکے ہونے (ف۷۱) کے بعد توڑتے اور جس کے جوڑنے کو اللہ نے فرمایا اسے قطع کرتے اور زمین میں فساد پھیلاتے ہیں (ف۷۲) ان کا حصہ لعنت ہی ہے اور اُن کا نصیبہ بُرا گھر (ف۷۳)'),
 (93,13,26,'اللہ جس کے لیے چاہے رزق کشادہ اور (ف۷۴) تنگ کرتا ہے، اور کا فر دنیا کی زندگی پر اترا گئے (نازاں ہوئے) (ف۷۵) اور دنیا کی زندگی آخرت کے مقابل نہیں مگر کچھ دن برت لینا،'),
 (93,13,27,'اور کافر کہتے ان پر کوئی نشانی ان کے رب کی طرف سے کیوں نہ اتری، تم فرماؤ بیشک اللہ جسے چاہے گمراہ کرتا ہے (ف۷۶) اور اپنی راہ اسے دیتا ہے جو اس کی طرف رجوع لائے،'),
 (93,13,28,'وہ جو ایمان لائے اور ان کے دل اللہ کی یاد سے چین پاتے ہیں، سن لو اللہ کی یاد ہی میں دلوں کا چین ہے (ف۷۷)'),
 (93,13,29,'وہ جو ایمان لائے اور اچھے کام کیے ان کو خوشی ہے اور اچھا انجام (ف۷۸)'),
 (93,13,30,'اسی طرح ہم نے تم کو اس امت میں بھیجا جس سے پہلے امتیں ہو گزریں (ف۷۹) کہ تم انہیں پڑھ کر سناؤ (ف۸۰) جو ہم نے تمہاری طرف وحی کی اور وہ رحمن کے منکر ہورہے ہیں (ف۸۱) تم فرماؤ وہ میرا رب ہے اس کے سوا کسی کی بندگی نہیں میں نے اسی پر بھروسہ کیا اور اسی کی طرف میری رجوع ہے،'),
 (93,13,31,'اور اگر کوئی ایسا قرآن آتا جس سے پہاڑ ٹل جاتے (ف۸۲) یا زمین پھٹ جاتی یا مردے باتیں کرتے جب بھی یہ کافر نہ مانتے (ف۸۳) بلکہ سب کام اللہ ہی کے اختیار ميں ہیں (ف۸۴) تو کیا مسلمان اس سے نا امید نہ ہوئے (ف۸۵) کہ اللہ چاہتا تو سب آدمیوں کو ہدایت کردیتا (ف۸۶) اور کافروں کو ہمیشہ کے لیے یہ سخت دھمک (ہلادینے والی مصیبت) پہنچتی رہے گی (ف۸۷) یا ان کے گھروں کے نزدیک اترے گی (ف۸۸) یہاں تک کہ اللہ کا وعدہ آئے (ف۸۹) بیشک اللہ وعدہ خلاف نہیں کرتا (ف۹۰)'),
 (93,13,32,'اور بیشک تم سے اگلے رسولوں سے بھی ہنسی کی گئی تو میں نے کافروں کو کچھ دنوں ڈھیل دی پھر انہیں پکڑا (ف۹۱) تو میرا عذاب کیسا تھا،'),
 (93,13,33,'تو کیا وہ ہر جان پر اس کے اعمال کی نگہداشت رکھتا ہے (ف۹۲) اور وہ اللہ کے شریک ٹھہراتے ہیں، تم فرماؤ ان کا نام تو لو (ف۹۳) یا اسے وہ بتاتے ہو جو اس کے علم میں ساری زمین میں نہیں (ف۹۴) یا یوں ہی اوپری بات (ف۹۵) بلکہ کافروں کی نگاہ میں ان کا فریب اچھا ٹھہرا ہے اور راہ سے روکے گئے (ف۹۶) اور جسے اللہ گمراہ کرے اسے کوئی ہدایت کرنے والا نہیں،'),
 (93,13,34,'انہیں دنیا کے جیتے عذاب ہوگا (ف۹۷) اور بیشک آخرت کا عذاب سب سے سخت اور انہیں اللہ سے بچانے والا کوئی نہیں،'),
 (93,13,35,'احوال اس جنت کا کہ ڈر والوں کے لیے جس کا وعدہ ہے، اس کے نیچے نہریں بہتی ہیں، اس کے میوے ہمیشہ اور اس کا سایہ (ف۹۸) ڈر والوں کا تو یہ انجام ہے (ف۹۹) اور کافروں کا انجام آ گ،'),
 (93,13,36,'اور جن کو ہم نے کتاب دی (ف۱۰۰) وہ اس پر خوش ہوتے جو تمہاری طرف اترا اور ان گروہوں میں (ف۱۰۱) کچھ وہ ہیں کہ اس کے بعض سے منکر ہیں، تم فرماؤ مجھے تو یہی حکم ہے کہ اللہ کی بندگی کروں اور اس کا شریک نہ ٹھہراؤں، ميں اسی کی طرف بلاتا ہوں اور اسی کی طرف مجھے پھرنا (ف۱۰۲)'),
 (93,13,37,'اور اسی طرح ہم نے اسے عربی فیصلہ اتارا (ف۱۰۳) اور اے سننے والے! اگر تو ان کی خواہشوں پر چلے گا (ف۱۰۴) بعد اس کے کہ تجھے علم آچکا تو اللہ کے آگے نہ تیرا کوئی حمایتی ہوگا نہ بچانے والا،'),
 (93,13,38,'اور بیشک ہم نے تم سے پہلے رسول بھیجے اور ان کے لیے بیبیاں (ف۱۰۵) اور بچے کیے اور کسی رسول کا کام نہیں کہ کوئی نشانی لے آئے مگر اللہ کے حکم سے، ہر وعدہ کی ایک لکھت ہے (ف۱۰۶)'),
 (93,13,39,'اللہ جو چاہے مٹاتا اور ثابت کرتا ہے (ف۱۰۷) اور اصل لکھا ہوا اسی کے پاس (ف۱۰۸)'),
 (93,13,40,'اور اگر ہمیں تمہیں دکھا د یں کوئی وعدہ (ف۱۰۹) جو انہیں دیا جاتا ہے یا پہلے ہی (ف۱۱۰) اپنے پاس بلائیں تو بہرحال تم پر تو ضرور پہنچانا ہے اور حساب لینا (ف۱۱۱) ہمارا ذمہ (ف۱۱۲)'),
 (93,13,41,'کیا انہیں نہیں سوجھتا کہ ہر طرف سے ان کی آبادی گھٹاتے آرہے ہیں (ف۱۱۳) اور اللہ حکم فرماتا ہے اس کا حکم پیچھے ڈالنے والا کوئی نہیں (ف۱۱۴) اور اسے حساب لیتے دیر نہیں لگتی،'),
 (93,13,42,'اور ان سے اگلے (ف۱۱۵) فریب کرچکے ہیں تو ساری خفیہ تدبیر کا مالک تو اللہ ہی ہے (ف۱۱۶) جانتا ہے جو کچھ کوئی جان کمائے (ف۱۱۷) اور اب جاننا چاہتے ہیں کافر، کسے ملتا ہے پچھلا گھر (ف۱۱۸)'),
 (93,13,43,'اور کافر کہتے ہی تم رسول نہیں، تم فرماؤ اللہ گواہ کافی ہے مجھ میں اور تم میں (ف۱۱۹) اور وہ جسے کتاب کا علم ہے (ف۱۲۰)				'),
 (93,14,1,'ایک کتاب ہے (ف۲) کہ ہم نے تمہاری طرف اتاری کہ تم لوگوں کو (ف۳) اندھیریوں سے (ف۴) اجالے میں لا ؤ (ف۵) ان کے رب کے حکم سے اس کی راہ (ف۶) کی طرف جو عزت والا سب خوبیوں والا ہے'),
 (93,14,2,'اللہ کہ اسی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں (ف۷) اور کافروں کی خرابی ہے ایک سخت عذاب سے'),
 (93,14,3,'جنہیں آخرت سے دنیا کی زندگی پیاری ہے اور اللہ کی راہ سے روکتے (ف۸) اور اس میں کجی چاہتے ہیں، وہ دور کی گمراہی میں ہیں (ف۹)'),
 (93,14,4,'اور ہم نے ہر رسول اس کی قوم ہی کی زبان میں بھیجا (ف۱۰) کہ وہ انہیں صاف بتائے (ف۱۱) پھراللہ گمراہ کرتا ہے جسے چاہے اور وہ راہ دکھاتا ہے جسے چاہے، اور وہی عزت و حکمت والا ہے،'),
 (93,14,5,'اور بیشک ہم نے موسیٰ کو اپنی نشانیاں (ف۱۲) دے کر بھیجا کہ اپنی قوم کو اندھیریوں سے (ف۱۳) اجالے میں لا، اور انہیں اللہ کے دن یا د دِلا (ف۱۴) بیشک اس میں نشانیاں ہیں ہر بڑے صبرے والے شکر گزار کرو،'),
 (93,14,6,'اور جب موسیٰ نے اپنی قوم سے کہا (ف۱۵) یاد کرو اپنے اوپر اللہ کا احسان جب اس نے تمہیں فرعون والوں سے نجات دی جو تم کو بری مار دیتے تھے اور تمہارے بیٹوں کو ذبح کرتے اور تمہاری بیٹیاں زندہ رکھتے، اور اس میں (ف۱۶) تمہارے رب کا بڑا فضل ہوا،'),
 (93,14,7,'اور یاد کرو جب تمہارے رب نے سنادیا کہ اگر احسان مانو گے تو میں تمہیں اور دونگا (ف۱۷) اور اگر ناشکری کرو تو میرا عذاب سخت ہے،'),
 (93,14,8,'اور موسیٰ نے کہا اگر تم اور زمین میں جتنے ہیں سب کا فر ہوجاؤ (ف۱۸) تو بیشک اللہ بے پروہ سب خوبیوں والا ہے،'),
 (93,14,9,'کیا تمہیں ان کی خبریں نہ آئیں جو تم سے پہلے تھی نوح کی قوم اور عاد اور ثمود اور جو ان کے بعد ہوئے، انہیں اللہ ہی جانے (ف۱۹) ان کے پاس ان کے رسول روشن دلیلیں لے کر آئے (ف۲۰) تو وہ اپنے ہاتھ (ف۲۱) اپنے منہ کی طرف لے گئے (ف۲۲) اور بولے ہم منکر ہیں اس کے جو تمہارے ہاتھ بھیجا گیا اور جس راہ (ف۲۳) کی طرف ہمیں بلاتے ہو اس میں ہمیں وہ شک ہے کہ بات کھلنے نہیں دیتا،'),
 (93,14,10,'ان کے رسولوں نے کہا کیا اللہ میں شک ہے (ف۲۴) آسمان اور زمین کا بنانے والا، تمہیں بلاتا ہے (ف۲۵) کہ تمہارے کچھ گناہ بخشے (ف۲۶) اور موت کے مقرر وقت تک تمہاری زندگی بے عذاب کاٹ دے، بولے تم تو ہمیں جیسے آدمی ہو (ف۲۷) تم چاہتے ہو کہ ہمیں اس سے باز رکھو جو ہمارے باپ دادا پوجتے تھے (ف۲۸) اب کوئی روشن سند ہمارے پاس لے آؤ (ف۲۹)'),
 (93,14,11,'ان کے رسولوں نے ان سے کہا (ف۳۰) ہم ہیں تو تمہاری طرح انسان مگر اللہ اپنے بندوں میں جس پر چاہے احسان فرماتا ہے (ف۳۱) اور ہمارا کام نہیں کہ ہم تمہارے پاس کچھ سند لے آئیں مگر اللہ کے حکم سے، اور مسلمانوں کو اللہ ہی پر بھروسہ چاہیے (ف۳۲)'),
 (93,14,12,'اور ہمیں کیا ہوا کہ اللہ پر بھروسہ نہ کریں (ف۳۳) اس نے تو ہماری راہیں ہمیں دکھادیں (ف۳۴) اور تم جو ہمیں ستا رہے ہو ہم ضرور اس پر صبر کریں گے، اور بھروسہ کرنے والوں کو اللہ ہی پر بھروسہ چاہیے،'),
 (93,14,13,'اور کافروں نے اپنے رسولوں سے کہا ہم ضرور تمہیں اپنی زمین (ف۳۵) سے نکال دیں گے یا تم ہمارے دین پر کچھ ہوجاؤ، تو انہیں ان کے رب نے وحی بھیجی کہ ہم ضرور ظالموں کو ہلاک کریں گے'),
 (93,14,14,'اور ضرور ہم تم کو ان کے بعد زمین میں بسائیں گے (ف۳۶) یہ اس لیے ہے جو (ف۳۷) میرے حضو ر کھڑے ہونے سے ڈرے اور میں نے جو عذاب کا حکم سنایا ہے، اس سے خوف کرے،'),
 (93,14,15,'اور انہوں نے (ف۳۸) فیصلہ مانگا اور ہر سرکش ہٹ دھرم نا مُراد ہوا (ف۳۹)'),
 (93,14,16,'جہنم اس کے پیچھے لگی اور اسے پیپ کا پانی پلایا جائے گا،'),
 (93,14,17,'بہ مشکل اس کا تھوڑا تھوڑا گھونٹ لے گا اور گلے سے نیچے اتارنے کی امید نہ ہوگی (ف۴۰) اور اسے ہر طرف سے موت آئے گی اور مرے گا نہیں، اور اس کے پیچھے ایک گاڑھا عذاب (ف۴۱)'),
 (93,14,18,'اپنے رب سے منکروں کا حال ایسا ہے کہ ان کے کام ہیں (ف ۴۲) جیسے راکھ کہ اس پر ہوا کا سخت جھونکا آیا آندھی کے دن میں (ف۴۳) ساری کمائی میں سے کچھ ہاتھ نہ لگا، یہی ہے دور کی گمراہی،'),
 (93,14,19,'کیا تو نے نہ دیکھا کہ اللہ نے آسمان اور زمین حق کے ساتھ بنائے (ف۴۴) اگر چاہے تو تمہیں لے جائے (ف۴۵) اور ایک نئی مخلوق لے آئے (ف۴۶)'),
 (93,14,20,'اور یہ (ف۴۷) اللہ پر کچھ دشوار نہیں،'),
 (93,14,21,'اور سب اللہ کے حضور (ف۴۸) اعلانیہ حاضر ہوں گے تو جو کمزور تھے (ف۴۹) بڑائی والوں سے کہیں گے (ف۵۰) ہم تمہارے تابع تھے کیا تم سے ہوسکتا ہے کہ اللہ کے عذاب میں سے کچھ ہم پر سے ٹال دو (ف۵۱) کہیں گے اللہ ہمیں ہدایت کرتا تو ہم تمہیں کرتے (ف۴۲) ہم پر ایک سا ہے چاہے بے قراری کریں یا صبر سے رہیں ہمیں کہیں پناہ نہیں،'),
 (93,14,22,'اور شیطان کہے گا جب فیصلہ ہوچکے گا (ف۵۳) بیشک اللہ نے تم کو سچا وعدہ دیا تھا (ف۵۴) اور میں نے جو تم کو وعدہ دیا تھا (ف۵۵) وہ میں نے تم سے جھوٹا کیا اور میرا تم پر کچھ قابو نہ تھا (ف۵۶) مگر یہی کہ میں نے تم کو (ف۵۷) بلایا تم نے میری مان لی (ف۵۸) تو اب مجھ پر الزام نہ رکھو (ف۵۹) خود اپنے اوپر الزام رکھو نہ میں تمہاری فریاد کو پہنچ سکوں نہ تم میری فریاد کو پہنچ سکو، وہ جو پہلے تم نے مجھے شریک ٹھہرایا تھا (ف۶۰) میں اس سے سخت بیزار ہوں، بیشک ظالموں کے لیے دردناک عذاب ہے،'),
 (93,14,23,'اور وہ جو ایمان لائے اور اچھے کام کیے وہ باغوں میں داخل کیے جائیں گے جن کے نیچے نہریں رواں ہمیشہ ان میں رہیں اپنے رب کے حکم سے، اس میں ان کے ملتے وقت کا اکرام سلام ہے (ف۶۱)'),
 (93,14,24,'کیا تم نے نہ دیکھا اللہ نے کیسی مثال بیان فرمائی پاکیزہ بات کی (ف۶۲) جیسے پاکیزہ درخت جس کی جڑ قائم اور شاخیں آسمان میں،'),
 (93,14,25,'ہر وقت پھل دیتا ہے اپنے رب کے حکم سے (ف۶۳) اور اللہ لوگوں کے لیے مثالیں بیان فرماتا ہے کہ کہیں وہ سمجھیں (ف۶۴)'),
 (93,14,26,'اور گندی بات (ف۶۵) کی مثال جیسے ایک گندہ پیڑ (ف۶۶) کہ زمین کے اوپر سے کاٹ دیا گیا اب اسے کوئی قیام نہیں (ف۶۷)'),
 (93,14,27,'اللہ ثابت رکھتا ہے ایمان والوں کو حق بات (ف۶۸) پر دنیا کی زندگی میں (ف۶۹) اور آخرت میں (ف۷۰) اور اللہ ظالموں کو گمراہ کرتا ہے (ف۷۱) اور اللہ جو چاہے کرے،'),
 (93,14,28,'کیا تم نے انہیں نہ دیکھا جنہوں نے اللہ کی نعمت ناشکری سے بدل دی (ف۷۲) اور اپنی قوم کو تباہی کے گھر لا اتار،'),
 (93,14,29,'وہ جو دوزخ ہے اس کے اندر جائیں گے، اور کیا ہی بری ٹھہرنے کی جگہ،'),
 (93,14,30,'اور اللہ کے لیے برابر والے ٹھہراے (ف۷۳) کہ اس کی راہ سے بہکاویں تم فرماؤ (ف۷۴) کچھ برت لو کہ تمہارا انجام آگ ہے (ف۷۵)'),
 (93,14,31,'میرے ان بندوں سے فرماؤ جو ایمان لائے کہ نماز قائم رکھیں اور ہمارے دیے میں سے کچھ ہماری راہ میں چھپے اور ظاہر خرچ کریں اس دن کے آنے سے پہلے جس میں نہ سوداگری ہوگی (ف۷۶) نہ یارانہ (ف۷۷)'),
 (93,14,32,'اللہ ہے جس نے آسمان اور زمین بنائے اور آسمان سے پانی اتارا تو اس سے کچھ پھل تمہارے کھانے کو پیدا کیے اور تمہارے لیے کشتی کو مسخر کیا کہ اس کے حکم سے دریا میں چلے (ف۷۸) اور تمہارے لیے ندیاں مسخر کیں، (ف۷۹)'),
 (93,14,33,'اور تمہارے لیے سورج اور چاند مسخر کیے جو برابر چل رہے ہیں (ف۸۰) اور تمہارے لیے رات اور دن مسخر کیے (ف۸۱)'),
 (93,14,34,'اور تمہیں بہت کچھ منہ مانگا دیا، اور اگر اللہ کی نعمتیں گنو تو شمار نہ کرسکو گے، بیشک آدمی بڑا ظالم ناشکرا ہے (ف۸۲)'),
 (93,14,35,'اور یاد کرو جب ابراہیم نے عرض کی اے میرے رب اس شہر (ف۸۳) کو امان والا کردے (ف۸۴) اور مجھے اور میرے بیٹوں کو بتوں کے پوجنے سے بچا (ف۸۵)'),
 (93,14,36,'اے میرے رب بیشک بتوں نے بہت لوگ بہکائے دیے (ف۸۶) تو جس نے میرا ساتھ دیا (ف۸۷) وہ تو میرا ہے اور جس نے میرا کہا نہ مانا تو بیشک تو بخشنے والا مہربان ہے (ف۸۸)'),
 (93,14,37,'اے میرے رب میں نے اپنی کچھ اولاد ایک نالے میں بسائی جس میں کھیتی نہیں ہوتی تیرے حرمت والے گھر کے پاس (ف۸۹) اے میرے رب اس لیے کہ وہ (ف۹۰) نماز قائم رکھیں تو تو لوگوں کے کچھ دل ان کی طرف مائل کردے (ف۹۱) اور انہیں کچھ پھل کھانے کو دے (ف۹۲) شاید وہ احسان مانیں،'),
 (93,14,38,'اے ہمارے رب تو جانتا ہے جو ہم چھپاتے ہیں اور ظاہر کرتے اور اللہ پر کچھ چھپا نہیں زمین میں اور نہ آسمان میں (ف۹۳)'),
 (93,14,39,'سب خوبیاں اللہ کو جس نے مجھے بڑھاپے میں اسماعیل و اسحاق دیئے بیشک میرا رب دعا سننے والا ہے،'),
 (93,14,40,'اے میرے رب! مجھے نماز قائم کرنے والا رکھ اور کچھ میری اولاد کو (ف۹۴) اے ہمارے رب اور ہماری دعا سن لے،'),
 (93,14,41,'اے ہمارے رب مجھے بخش دے اور میرے ماں باپ کو (ف۹۵) اور سب مسلمانوں کو جس دن حساب قائم ہوگا،'),
 (93,14,42,'اور ہرگز اللہ کو بےخبر نہ جاننا ظالموں کے کام سے (ف۹۶) انہیں ڈھیل نہیں دے رہا ہے مگر ایسے دن کے لیے جس میں (ف۹۷)'),
 (93,14,43,'آنکھیں کھلی کی کھلی رہ جائیں گی بے تحاشا دوڑے نکلیں گے (ف۹۸) اپنے سر اٹھائے ہوئے کہ ان کی پلک ان کی طرف لوٹتی نہیں (ف۹۹) اور ان کے دلوں میں کچھ سکت نہ ہوگی (ف۱۰۰)'),
 (93,14,44,'اور لوگوں کو اس دن سے ڈراؤ (ف۱۰۱) جب ان پر عذاب آئے گا تو ظالم (ف۱۰۲) کہیں گے اے ہمارے رب! تھوڑی دیر ہمیں (ف۱۰۳) مہلت دے کہ ہم تیرا بلانا مانیں (ف۱۰۴) اور رسولوں کی غلامی کریں (ف۱۰۵) تو کیا تم پہلے (ف۱۰۶) قسم نہ کھاچکے تھے کہ ہمیں دنیا سے کہیں ہٹ کر جانا نہیں (ف۱۰۷)'),
 (93,14,45,'اور تم ان کے گھروں میں بسے جنہوں نے اپنا برا کیا تھا (ف۱۰۸) اور تم پر خوب کھل گیا ہم نے ان کے ساتھ کیسا کیا (ف۱۰۹) اور ہم نے تمہیں مثالیں دے کر بتادیا (ف۱۱۰)'),
 (93,14,46,'اور بیشک وہ (ف۱۱۱) اپنا سا داؤں (فریب) چلے (ف۱۱۲) اور ان کا داؤں اللہ کے قابو میں ہے، اور ان کا داؤں کچھ ایسانہ تھا جس سے یہ پہاڑ ٹل جائیں (ف۱۱۳)'),
 (93,14,47,'تو ہر گز خیال نہ کرنا کہ اللہ اپنے رسولوں سے وعدہ خلاف کرے گا (ف۱۱۴) بیشک اللہ غالب ہے بدلہ لینے والا،'),
 (93,14,48,'جس دن (ف۱۱۵) بدل دی جائے گی زمین اس زمین کے سوا اور آسمان (ف۱۱۶) اور لوگ سب نکل کھڑے ہوں گے (ف۱۱۷) ایک اللہکے سامنے جو سب پر غالب ہے'),
 (93,14,49,'اور اس دن تم مجرموں (ف۱۱۸) کو دیکھو گے کہ بیڑیوں میں ایک دوسرے سے جڑے ہوں گے (ف۱۱۹)'),
 (93,14,50,'ان کے کرُتے رال ہوں گے (ف۱۲۰) اور ان کے چہرے آ گ ڈھانپ لے گی'),
 (93,14,51,'اس لیے کہ اللہ ہر جان کو اس کی کمائی کا بدلہ دے، بیشک اللہ کو حساب کرتے کچھ دیر نہیں لگتی،'),
 (93,14,52,'یہ (ف۱۲۱) لوگوں کو حکم پہنچانا ہے اور اس لیے کہ وہ اس سے ڈرائے جائیں اور اس لیے کہ وہ جان لیں کہ وہ ایک ہی معبود ہے (ف۱۲۲) اور اس لیے کہ عقل والے نصیحت مانیں،						'),
 (93,15,1,'یہ آیتیں ہیں کتاب اور روشن قرآن کی-'),
 (93,15,2,'بہت آرزوئیں کریں گے کافر (ف۲) کاش مسلمان ہوتے،'),
 (93,15,3,'انہیں چھوڑو (ف۳) کہ کھائیں اور برتیں (ف۴) اور امید (ف۵) انہیں کھیل میں ڈالے تو اب جانا چاہتے ہیں (ف۶)'),
 (93,15,4,'اور جو بستی ہم نے ہلاک کی اس کا ایک جانا ہوا نوشتہ تھا (ف۷)'),
 (93,15,5,'کو ئی گروہ اپنے وعدہ سے آگے نہ بڑھے نہ پیچھے ہٹے،'),
 (93,15,6,'اور بولے (ف۸) کہ اے وہ جن پر قرآن اترا بیشک مجنون ہو (ف۹)'),
 (93,15,7,'ہمارے پاس فرشتے کیوں نہیں لاتے (ف۱۰) اگر تم سچے ہو (ف۱۱)'),
 (93,15,8,'ہم فرشتے بیکار نہیں اتارتے اور وہ اتریں تو انہیں مہلت نہ ملے (ف۱۲)'),
 (93,15,9,'بیشک ہم نے اتارا ہے یہ قرآن اور بیشک ہم خود اس کے نگہبان ہیں (ف۱۳)'),
 (93,15,10,'اور بیشک ہم نے تم سے پہلے اگلی امتوں میں رسول بھیجے،'),
 (93,15,11,'اور ان کے پاس کوئی رسول نہیں آتا مگر اس سے ہنسی کرتے ہیں (ف۱۴)'),
 (93,15,12,'ایسے ہی ہم اس ہنسی کو ان مجرموں (ف۱۵) کے دلوں میں راہ دیتے ہیں،'),
 (93,15,13,'وہ اس پر (ف۱۶) ایمان نہیں لاتے اور اگلوں کی راہ پڑچکی ہے (ف۱۷)'),
 (93,15,14,'اور اگر ہم ان کے لیے آسمان میں کوئی دروازہ کھول دیں کہ دن کو اس میں چڑھتے،'),
 (93,15,15,'جب بھی یہی کہتے کہ ہماری نگاہ باندھ دی گئی ہے بلکہ ہم پر جادو ہوا ہے (ف۱۸)'),
 (93,15,16,'اور بیشک ہم نے آسمان میں برج بنائے (ف۱۹) اور اسے دیکھنے والو ں کے لیے آراستہ کیا (ف۲۰)'),
 (93,15,17,'اور اسے ہم نے ہر شیطان مردود سے محفوظ رکھا (ف۲۱)'),
 (93,15,18,'مگر جو چوری چھپے سننے جائے تو اس کے پیچھے پڑتا ہے روشن شعلہ (ف۲۲)'),
 (93,15,19,'اور ہم نے زمین پھیلائی اور اس میں لنگر ڈالے (ف۲۳) اور اس میں ہر چیز اندازے سے اگائی،'),
 (93,15,20,'اور تمہارے لیے اس میں روزیاں کردیں (ف۲۴) اور وہ کردیے جنہیں تم رزق نہیں دیتے (ف۲۵)'),
 (93,15,21,'اور کوئی چیز نہیں جس کے ہمارے پاس خزانے نہ ہوں (ف۲۶) اور ہم اسے نہیں اتارتے مگر ایک معلوم انداز سے،'),
 (93,15,22,'اور ہم نے ہوائیں بھیجیں بادلوں کو با رور کرنے والیاں (ف۲۷) تو ہم نے آسمان سے پانی اتارا پھر وہ تمہیں پینے کو دیا اور تم کچھ اس کے خزانچی نہیں (ف۲۸)'),
 (93,15,23,'اور بیشک ہم ہی جِلائیں اور ہم ہی ماریں اور ہم ہی وارث ہیں (ف۲۹)'),
 (93,15,24,'اور بیشک ہمیں معلوم ہیں جو تم میں آگے بڑھے اور بیشک ہمیں معلوم ہیں جو تم میں پیچھے رہے، (ف۳۰)'),
 (93,15,25,'اور بیشک تمہارا رب ہی تمہیں قیامت میں اٹھائے گا (ف۳۱) بیشک وہی علم و حکمت والا ہے،'),
 (93,15,26,'اور بیشک ہم نے آدمی کو (ف۳۲) بجتی ہوئی مٹی سے بنایا جو اصل میں ایک سیاہ بودار گارا تھی، ف۳۳)'),
 (93,15,27,'اور جِن کو اس سے پہلے بنایا بے دھوئیں کی آگ سے، (ف۳۴)'),
 (93,15,28,'اور یاد کرو جب تمہارے رب نے فرشتوں سے فرمایا کہ میں آدمی کو بنانے والا ہوں بجتی مٹی سے جو بدبودار سیاہ گارے سے ہے،'),
 (93,15,29,'تو جب میں اسے ٹھیک کرلوں اور اور میں اپنی طرف کی خاص معز ز ر وح پھونک دوں (ف۳۵) تو اس (ف۳۶) کے لیے سجدے میں گر پڑنا،'),
 (93,15,30,'تو جتنے فرشتے تھے سب کے سب سجدے میں گرے،'),
 (93,15,31,'سوا ابلیس کے، اس نے سجدہ والوں کا ساتھ نہ مانا (ف۳۷)'),
 (93,15,32,'فرمایا اے ابلیس تجھے کیا ہوا کہ سجدہ کرنے والوں سے الگ رہا،'),
 (93,15,33,'بولا مجھے زیبا نہیں کہ بشر کو سجدہ کروں جسے تو نے بجتی مٹی سے بنایا جو سیاہ بودار گارے سے تھی،'),
 (93,15,34,'فرمایا تو جنت سے نکل جا کہ تو مردود ہے،'),
 (93,15,35,'اور بیشک قیامت تک تجھ پر لعنت ہے (ف۳۸)'),
 (93,15,36,'بولا اے میرے رب تو مجھے مہلت دے اس دن تک کہ وہ اٹھائے جائیں (ف۳۹)'),
 (93,15,37,'فرمایا تو ان میں سے ہے جن کو اس معلوم،'),
 (93,15,38,'وقت کے دن تک مہلت ہے، (ف۴۰)'),
 (93,15,39,'بولا اے رب میرے! قسم اس کی کہ تو نے مجھے گمراہ کیا میں انہیں زمین میں بھلاوے دوں گا (ف۴۱) اور ضرور میں ان سب کو (ف۴۲) بے راہ کروں گا'),
 (93,15,40,'مگر جو ان میں تیرے چنے ہوئے بندے ہیں، (ف۴۳)'),
 (93,15,41,'فرمایا یہ راستہ سیدھا میری طرف آتا ہے،'),
 (93,15,42,'بیشک میرے (ف۴۴) بندوں پر تیرا کچھ قابو نہیں سوا ان گمراہوں کے جو تیرا ساتھ دیں، (ف۴۵)'),
 (93,15,43,'اور بیشک جہنم ان سب کا وعدہ ہے، (ف۴۶)'),
 (93,15,44,'اس کے سات دروازے ہیں، (ف۴۷) ہر دروازے کے لیے ان میں سے ایک حصہ بٹا ہوا ہے، (ف۴۸)'),
 (93,15,45,'بیشک ڈر والے باغوں اور چشموں میں ہیں (ف۴۹)'),
 (93,15,46,'ان میں داخل ہو سلامتی کے ساتھ امان میں، (ف۵۰)'),
 (93,15,47,'اور ہم نے ان کے سینوں میں جو کچھ (ف۵۱) کینے تھے سب کھینچ لیے (ف۵۲) آپس میں بھائی ہیں (ف۵۳) تختوں پر روبرو بیٹھے،'),
 (93,15,48,'نہ انہیں اس میں کچھ تکلیف پہنچے نہ وہ اس میں سے نکالے جائیں،'),
 (93,15,49,'خبردو (۵۴) میرے بندوں کو کہ بیشک میں ہی ہوں بخشے والا مہربان،'),
 (93,15,50,'اور میرا ہی عذاب دردناک عذاب ہے،'),
 (93,15,51,'اور انہیں احوال سناؤ ابراہیم کے مہمانوں کا، (ف۵۵)'),
 (93,15,52,'جب وہ اس کے پاس آئے تو بولے سلام (ف۵۶) کہا ہمیں تم سے ڈر معلوم ہوتا ہے، (ف۵۷)'),
 (93,15,53,'انہوں نے کہا ڈریے نہیں ہم آپ کو ایک علم والے لڑکے کی بشارت دیتے ہیں، (ف۵۸)'),
 (93,15,54,'کہا کیا اس پر مجھے بشارت دیتے ہو کہ مجھے بڑھاپا پہنچ گیا اب کاہے پر بشارت دیتے ہو، (ف۵۹)'),
 (93,15,55,'کہا ہم نے آپ کو سچی بشارت دی ہے (ف۶۰) آپ ناامید نہ ہوں،'),
 (93,15,56,'کہا اپنے رب کی رحمت سے کون ناامید ہو مگر وہی جو گمراہ ہوئے، ف۶۱)'),
 (93,15,57,'کہا پھر تمہارا کیا کام ہے اے فرشتو! (ف۶۲)'),
 (93,15,58,'بولے ہم ایک مجرم قوم کی طرف بھیجے گئے ہیں، (ف۶۳)'),
 (93,15,59,'مگر لوط کے گھر والے، ان سب کو ہم بچالیں گے، (ف۶۴)'),
 (93,15,60,'مگر اس کی عورت ہم ٹھہراچکے ہیں کہ وہ پیچھے رہ جانے والوں میں ہے، ف۶۵)'),
 (93,15,61,'تو جب لوط کے گھر فرشتے آئے، ۶۶)'),
 (93,15,62,'کہا تم تو کچھ بیگانہ لوگ ہو، ف۶۷)'),
 (93,15,63,'کہا بلکہ ہم تو آپ کے پاس وہ (ف۶۸) لائے ہیں جس میں یہ لوگ شک کرتے تھے، (ف۶۹)'),
 (93,15,64,'اور ہم آپ کے پاس سچا حکم لائے ہیں اور ہم بیشک سچے ہیں،'),
 (93,15,65,'تو اپنے گھر والوں کو کچھ رات رہے لے کر باہر جایے اور آپ ان کے پیچھے چلئے اور تم میں کوئی پیچھے پھر کر نہ دیکھے (ف۷۰) اور جہاں کو حکم ہے سیدھے چلے جایئے، (ف۷۱)'),
 (93,15,66,'اور ہم نے اسے اس حکم کا فیصلہ سنادیا کہ صبح ہوتے ان کافروں کی جڑ کٹ جائے گی،'),
 (93,15,67,'اور شہر والے (ف۷۳) خوشیاں مناتے آئے،'),
 (93,15,68,'لوط نے کہا یہ میرے مہمان ہیں (ف۷۴) مجھے فضیحت (رُسوا) نہ کرو، ف۷۵)'),
 (93,15,69,'اور اللہ سے ڈرو اور مجھے رسوا نہ کرو، (ف۷۶)'),
 (93,15,70,'بولے کیا ہم نے تمہیں منع نہ کیا تھا کہ اوروں کے معاملہ میں دخل نہ دو،'),
 (93,15,71,'کہا یہ قوم کی عورتیں میری بیٹیاں ہیں اگر تمہیں کرنا ہے، (ف۷۷)'),
 (93,15,72,'اے محبوب تمہاری جان کی قسم (ف۷۸) بیشک وہ اپنے نشہ میں بھٹک رہے ہیں،'),
 (93,15,73,'تو دن نکلتے انہیں چنگھاڑ نے آلیا (ف۷۹)'),
 (93,15,74,'تو ہم نے اس بستی کا اوپر کا حصہ اس نے نیچے کا حصہ کردیا (ف۸۰) اور ان پر کنکر کے پتھر برسائے،'),
 (93,15,75,'بیشک اس میں نشانیاں ہیں فراست والوں کے لیے،'),
 (93,15,76,'اور بیشک وہ بستی اس راہ پر ہے جو اب تک چلتی ہے، (ف۸۱)'),
 (93,15,77,'بیشک اس میں نشانیاں ہیں ایمان والوں کو،'),
 (93,15,78,'اور بیشک جھاڑی والے ضرور ظالم تھے، ف۸۲)'),
 (93,15,79,'تو ہم نے ان سے بدلہ لیا (ف۸۳) اور بیشک دونوں بستیاں (ف۸۴) کھلے راستہ پر پڑتی ہیں، (ف۸۵)'),
 (93,15,80,'اور بیشک حجر والو ں نے رسولوں کو جھٹلایا (ف۸۶)'),
 (93,15,81,'اور ہم نے ان کو اپنی نشانیاں دیں (ف۸۷) تو وہ ان سے منہ پھیرے رہے، (ف۸۸)'),
 (93,15,82,'اور وہ پہاڑوں میں گھر تراشتے تھے بے خوف (ف۸۹)'),
 (93,15,83,'تو انہیں صبح ہوتے چنگھاڑ نے آلیا (ف۹۰)'),
 (93,15,84,'تو ان کی کمائی کچھ ان کے کام نہ آئی (ف۹۱)'),
 (93,15,85,'اور ہم نے آسمان اور زمین اور جو کچھ ان کے درمیان ہے عبث نہ بنایا، اور بیشک قیامت آنے والی ہے (ف۹۲) تو تم اچھی طرح درگزر کرو، ف۹۳)'),
 (93,15,86,'بیشک تمہارا رب ہی بہت پیدا کرنے والا جاننے والا ہے (ف۹۴)'),
 (93,15,87,'اور بیشک ہم نے تم کو سات آیتیں دیں جو دہرائی جاتی ہیں (ف۹۵) اور عظمت والا قرآن،'),
 (93,15,88,'اپنی آنکھ اٹھاکر اس چیز کو نہ دیکھو جو ہم نے ان کے جوڑوں کو برتنے کو دی (ف۹۶) اور ان کا کچھ غم نہ کھاؤ (ف۹۷) اور مسلمانوں کو اپنی رحمت کے پروں میں لے لو، (ف۹۸)'),
 (93,15,89,'اور فرماؤ کہ میں ہی ہوں صاف ڈر سنانے والا (اس عذاب سے)،'),
 (93,15,90,'جیسا ہم نے بانٹنے والوں پر اتارا،'),
 (93,15,91,'جنہوں نے کلامِ الٰہی کو تکے بوٹی کرلیا، ف۹۹)'),
 (93,15,92,'تو تمہارے رب کی قسم ہم ضرور ان سب سے پوچھیں گے، (ف۱۰۰)'),
 (93,15,93,'جو کچھ وہ کرتے تھے، (ف۱۰۱)'),
 (93,15,94,'تو اعلانیہ کہہ دو جس بات کا تمہیں حکم ہے (ف۱۰۲) اور مشرکوں سے منہ پھیر لو، ف۱۰۳)'),
 (93,15,95,'بیشک ان ہنسنے والوں پر ہم تمہیں کفا یت کرتے ہیں (ف۱۰۴)'),
 (93,15,96,'جو ا لله کے ساتھ دوسرا معبود ٹھہراتے ہیں تو اب جان جائیں گے، (ف۱۰۵)'),
 (93,15,97,'اور بیشک ہمیں معلوم ہے کہ ان کی باتوں سے تم دل تنگ ہوتے ہو، (ف۱۰۶)'),
 (93,15,98,'تو اپنے رب کو سراہتے ہوئے اس کی پاکی بولو اور سجدہ والوں میں ہو، (ف۱۰۷)'),
 (93,15,99,'اور مرتے دم تک اپنے رب کی عبادت میں رہو،'),
 (93,16,1,'اب آتا ہے اللہ کا حکم تو اس کی جلدی نہ کرو (ف۲) پاکی اور برتری ہے اسے ان شریکوں سے، (ف۳)'),
 (93,16,2,'ملائکہ کو ایمان کی جان یعنی وحی لے کر اپنے جن بندوں پر چاہے اتارتا ہے (ف ۴) کہ ڈر سناؤ کہ میرے سوا کسی کی بندگی نہیں تو مجھ سے ڈرو (ف۵)'),
 (93,16,3,'اس نے آسمان اور زمین بجا بنائے (ف۶) وہ ان کے شرک سے برتر ہے،'),
 (93,16,4,'(اس نے) آدمی کو ایک نِتھری بوند سے بنایا (ف۷) تو جبھی کھلا جھگڑالو ہے،'),
 (93,16,5,'اور چوپائے پیدا کیے ان میں تمہارے لیے گرم لباس اور منفعتیں ہیں (ف۸) اور ان میں سے کھاتے ہو،'),
 (93,16,6,'اور تمہارا ان میں تجمل ہے جب انہیں شام کو واپس لاتے ہو اور جب چرنے کو چھوڑتے ہو،'),
 (93,16,7,'اور وہ تمہارے بوجھ اٹھا کر لے جاتے ہیں ایسے شہر کی طرف کہ اس تک نہ پہنچتے مگر ادھ مرے ہوکر، بیشک تمہارا رب نہایت مہربان رحم والا ہے (ف۹)'),
 (93,16,8,'اور گھوڑے اور خچر اور گدھے کہ ان پر سوار ہو اور زینت کے لیے، اور وہ پیدا کرے گا (ف۱۰) جس کی تمہیں خبر نہیں، (ف۱۱)'),
 (93,16,9,'اور بیچ کی راہ (ف۱۲) ٹھیک اللہ تک ہے اور کوئی راہ ٹیڑھی ہے (ف۱۳) اور چاہتا تو تم سب کو راہ پر لاتا، (ف۱۴)'),
 (93,16,10,'وہی ہے جس نے آسمان سے پانی اتارا اس سے تمہارا پینا ہے اور اس سے درخت ہیں جن سے چَراتے ہو (ف۱۵)'),
 (93,16,11,'اس پانی سے تمہارے لیے کھیتی اگاتا ہے اور زیتون اور کھجور اور انگور اور ہر قسم کے پھل (ف۱۶) بیشک اس میں نشانی ہے (ف۱۷) دھیان کرنے والوں کو،'),
 (93,16,12,'اور اس نے تمہارے لیے مسخر کیے رات اور دن اور سورج اور چاند، اور ستارے اس کے حکم کے باندھے ہیں بیشک اس آیت میں نشانیاں ہیں عقل مندوں کو (ف۱۸)'),
 (93,16,13,'اور وہ جو تمہارے لیے زمین میں پیدا کیا رنگ برنگ (ف۱۹) بیشک اس میں نشانی ہے یاد کرنے والوں کو'),
 (93,16,14,'اور وہی ہے جس نے تمہارے لیے دریا مسخر کیا (ف۲۰) کہ اس میں سے تازہ گوشت کھاتے ہو (ف۲۱) اور اس میں سے گہنا (زیور) نکالتے ہو جسے پہنتے ہو (ف۲۲) اور تو اس میں کشتیاں دیکھے کہ پانی چیر کر چلتی ہیں اور اس لیے کہ تم اس کا فضل تلاش کرو اور کہیں احسان مانو،'),
 (93,16,15,'اور اس نے زمین میں لنگر ڈالے (ف۲۳) کہ کہیں تمہیں لے کر نہ کانپے اور ندیاں اور رستے کہ تم راہ پاؤ (ف۲۴)'),
 (93,16,16,'اور علامتیں (ف۲۵) اور ستارے سے وہ راہ پاتے ہیں (ف۲۶)'),
 (93,16,17,'تو کیا جو بنائے (ف۲۷) وہ ایسا ہوجائے گا جو نہ بنائے (ف۲۸) تو کیا تم نصیحت نہیں مانتے،'),
 (93,16,18,'اور اگر اللہ کی نعمتیں گنو تو انہیں شمار نہ کرسکو گے (ف۲۹) بیشک اللہ بخشنے والا مہربان ہے (ف۳۰)'),
 (93,16,19,'اور اللہ جانتا ہے (ف۳۱) جو چھپاتے اور ظاہر کرتے ہو،'),
 (93,16,20,'اور اللہ کے سوا جن کو پوجتے ہو ہیں (۳۲) وہ کچھ بھی نہیں بناتے اور (ف۳۳) وہ خود بنائے ہوئے ہیں (ف۳۴)'),
 (93,16,21,'مُردے ہیں (ف۳۵) زندہ نہیں اور انہیں خبر نہیں لوگ کب اٹھائے جایں گے (ف۳۶)'),
 (93,16,22,'تمہارا معبوثد ایک معبود ہے (ف۳۷) تو وہ جو آخرت پر ایمان نہیں لاتے ان کے دل منکر ہیں (ف۳۸) اور وہ مغرور ہیں (ف۳۹)'),
 (93,16,23,'فی الحقیقت اللہ جانتا ہے جو چھپاتے اور جو ظاہر کرتے ہیں، بیشک وہ مغروروں کو پسند نہیں فرماتا،'),
 (93,16,24,'اور جب ان سے کہا جائے (ف۴۰) تمہارے رب نے کیا اتارا (ف۴۱) کہیں اگلوں کی کہانیاں ہیں (ف۴۲)'),
 (93,16,25,'کہ قیامت کے دن اپنے (ف۴۳) بوجھ پورے اٹھائیں اور کچھ بوجھ ان کے جنہیں اپنی جہالت سے گمراہ کرتے ہیں، سن لو کیا ہی برا بوجھ اٹھاتے ہیں،'),
 (93,16,26,'بیشک ان سے اگلوں نے (ف۴۴) فریب کیا تھا تو اللہ نے ان کی چنائی کو نیو سے (تعمیر کو بنیاد) سے لیا تو اوپر سے ان پر چھت گر پڑی اور عذاب ان پر وہاں سے آیا جہاں کی انہیں خبر نہ تھی (ف۴۵)'),
 (93,16,27,'پھر قیامت کے دن انہیں رسوا کرے گا اور فرمائے گا کہاں ہیں میرے وہ شریک (ف۴۶) جن میں تم جھگڑتے تھے (ف۴۷) علم والے (ف۴۸) کہیں گے آج ساری رسوائی اور برائی (ف۴۹) کافروں پر ہے'),
 (93,16,28,'وہ کہ فرشتے ان کی جان نکالتے ہیں اس حال پر کیا وہ اپنا برا کررہے تھے (ف۵۰) اب صلح ڈالیں گے (ف۵۱) کہ ہم تو کچھ برائی نہ کرتے تھے (ف۵۲) ہاں کیوں نہیں، بیشک اللہ خوب جانتا ہے جو تمہارے کوتک (برے اعمال) تھے (ف۵۳)'),
 (93,16,29,'اب جہنم کے دروازوں میں جاؤ کہ ہمیشہ اس میں رہو، تو کیا ہی برا ٹھکانا مغروروں کا،'),
 (93,16,30,'اور ڈر والوں (ف۵۴) سے کہا گیا تمہارے رب رب نے کیا اتارا، بولے خوبی (ف۵۵) جنہوں نے اس دنیا میں بھلائی کی (ف۵۶) ان کے لیے بھلائی ہے (ف۵۷) اور بیشک پچھلا گھر سب سے بہتر، اور ضرور (ف۵۸) کیا ہی اچھا گھر پرہیزگاروں کا'),
 (93,16,31,'بسنے کے باغ جن میں جائیں گے ان کے نیچے نہریں رواں انہیں وہاں ملے گا جو چاہیں (ف۵۹) اللہ ایسا ہی صلہ دیتا ہے پرہیزگاروں کو'),
 (93,16,32,'وہ جن کی جان نکالتے ہیں فرشتے ستھرے پن میں (ف۶۰) یہ کہتے ہوئے کہ سلامتی ہو تم پر (ف۶۱) جنت میں جاؤ بدلہ اپنے کیے کا،'),
 (93,16,33,'کاہے کے انتظار میں ہیں (ف۶۲) مگر اس کے کہ فرشتے ان پر آئیں (ف۶۳) یا تمہارے رب کا عذاب آئے (ف۶۴) ان سے اگلوں نے ایسا ہی کیا (ف۶۵) اور اللہ نے ان پر کچھ ظلم نہ کیا، ہاں وہ خود ہی (ف۶۶) اپنی جانوں پر ظلم کرتے تھے،'),
 (93,16,34,'تو ان کی بری کمائیاں ان پر پڑیں (ف۶۷) اور انہیں گھیرلیا اس (ف۶۸) نے جس پر ہنستے تھے،'),
 (93,16,35,'اور مشرک بولے اللہ چاہتا تو اس کے سوا کچھ نہ پوجنے نہ ہم اور نہ ہمارے باپ دادا اور نہ اس سے جدا ہو کر ہم کوئی چیز حرام ٹھہراتے (ف۶۹) جیسا ہی ان سے اگلوں نے کیا (ف۷۰) تو رسولوں پر کیا ہے مگر صاف پہنچا دینا، (ف۷۱)'),
 (93,16,36,'اور بیشک ہر امت میں ہم نے ایک رسول بھیجا (ف۷۲) کہ اللہ کو پوجو اور شیطان سے بچو تو ان (ف۷۳) میں کسی کو اللہ نے راہ دکھائی (ف۷۴) اور کسی پر گمراہی ٹھیک اتری (ف۷۵) تو زمین میں چل پھر کر دیکھو کیسا انجام ہوا جھٹلانے والوں کا (ف۷۶)'),
 (93,16,37,'اگر تم ان کی ہدایت کی حرص کرو (ف ۷۷) تو بیشک اللہ ہدایت نہیں دیتا جسے گمراہ کرے اور ان کا کوئی مددگار نہیں،'),
 (93,16,38,'اور انہوں نے اللہ کی قسم کھائی اپنے حلف میں حد کی کوشش سے کہ اللہ مُردے نہ اٹھائے گا (ف۷۸) ہاں کیوں نہیں (۷۹) سچا وعدہ اس کے ذمہ پر لیکن اکثر لوگ نہیں جانتے (ف۸۰)'),
 (93,16,39,'اس لیے کہ انہیں صاف بتادے جس بات میں جھگڑتے تھے (ف۸۱) اور اس لیے کہ کافر جان لیں کہ وہ جھوٹے تھے (ف۸۲)'),
 (93,16,40,'جو چیز ہم چاہیں اس سے ہمارا فرمانا یہی ہوتا ہے کہ ہم کہیں ہوجا وہ فوراً ہوجاتی ہے، (ف۸۳)'),
 (93,16,41,'اور جنہوں نے اللہ کی راہ مں ی (ف۸۴) اپنے گھر بار چھوڑے مظلوم ہوکر ضرور ہم انہیں دنیا میں اچھی جگہ دیں گے (ف۸۵) اور بیشک آخرت کا ثواب بہت بڑا ہے کسی طرح لوگ جانتے، ف۸۶)'),
 (93,16,42,'وہ جنہوں نے صبر کیا (ف۸۷) اور اپنے رب ہی پر بھروسہ کرتے ہیں (ف۸۸)'),
 (93,16,43,'اور ہم نے تم سے پہلے نہ بھیجے مگر مرد (ف۸۹) جن کی طرف ہم وحی کرتے، تو اے لوگو! علم والوں سے پوچھو اگر تمہیں علم نہیں، ف۹۰)'),
 (93,16,44,'روشن دلیلیں اور کتابیں لے کر (ف۹۱) اور اے محبوب ہم نے تمہاری ہی طرف یہ یاد گار اتاری (ف۹۲) کہ تم لوگوں سے بیان کردو جو (ف۹۳) ان کی طرف اترا اور کہیں وہ دھیان کریں،'),
 (93,16,45,'تو کیا جو لوگ بڑے مکر کرتے ہیں (ف۹۴) اس سے نہیں ڈرتے کہ اللہ انہیں زمین میں دھنسادے (ف۹۵) یا انہیں وہاں سے عذاب آئے جہاں سے انہیں خبر نہ ہو، (ف۹۶)'),
 (93,16,46,'یا انہیں چلتے پھرتے (ف۹۷) پکڑ لے کہ وہ تھکا نہیں سکتے، ف۹۸)'),
 (93,16,47,'یا انہیں نقصان دیتے دیتے گرفتار کرلے کہ بیشک تمہارا رب نہایت مہربان رحم والا ہے، (ف۹۹)'),
 (93,16,48,'اور کیا انہوں نے نہ دیکھا کہ جو (ف۱۰۰) چیز اللہ نے بنائی ہے اس کی پرچھائیاں دائیں اور بائیں جھکتی ہیں (ف۱۰۱) اللہ کو سجدہ کرتی اور وہ اس کے حضور ذلیل ہیں (ف۱۰۲)'),
 (93,16,49,'اور اللہ ہی کو سجدہ کرتے ہیں جو کچھ آسمانوں میں ہیں اور جو کچھ زمین میں چلنے والا ہے (ف۱۰۳) اور فرشتے اور وہ غرور نہیں کرتے،'),
 (93,16,50,'اپنے اوپر اپنے رب کا خوف کرتے ہیں اور وہی کرتے ہیں جو انہیں حکم ہو، (ف۱۰۴)'),
 (93,16,51,'اور اللہ نے فرمادیا دو خدا نہ ٹھہراؤ (ف۱۰۵) وہ تو ایک ہی معبود ہے تو مجھ ہی سے ڈرو، ف۱۰۶)'),
 (93,16,52,'اور اسی کا ہے جو کچھ آسمانوں اور زمین میں ہے اور اسی کی فرمانبرداری لازم ہے، تو اللہ کے سوا کسی دوسرے سے ڈرو گے، (ف۱۰۷)'),
 (93,16,53,'اور تمہارے پاس جو نعمت ہے سب اللہ کی طرف سے ہے پھر جب تمہیں تکلیف پہنچتی ہے (ف۱۰۸) تو اسی کی طرف پناہ لے جاتے ہو، ف۱۰۹)'),
 (93,16,54,'پھر جب وہ تم سے برائی ٹال دیتا ہے تو تم میں ایک گروہ اپنے رب کا شریک ٹھہرانے لگتا ہے، ف۱۱۰)'),
 (93,16,55,'کہ ہماری دی ہوئی نعمتوں کی ناشکری کریں، تو کچھ برت لو (۱۱۱) کہ عنقریب جان جاؤ گے، (ف۱۱۲)'),
 (93,16,56,'اور انجانی چیزوں کے لیے (ف۱۱۳) ہماری دی ہوئی روزی میں سے (ف۱۱۴) حصہ مقرر کرتے ہیں خدا کی قسم تم سے ضرور سوال ہونا ہے جو کچھ جھوٹ باندھتے تھے (ف۱۱۵)'),
 (93,16,57,'اور اللہ کے لیے بیٹیاں ٹھہراتے ہیں (ف۱۱۶) پاکی ہے اس کو (ف۱۱۷) اور اپنے لیے جو اپنا جی چاہتا ہے، (ف۱۱۸)'),
 (93,16,58,'اور جب ان میں کسی کو بیٹی ہونے کی خوشخبری دی جاتی ہے تو دن بھر اس کا منہ (ف۱۱۹) کالا رہتا ہے اور وہ غصہ کھا تا ہے،'),
 (93,16,59,'لوگوں سے (ف۱۲۰) چھپا پھرتا ہے اس بشارت کی برائی کے سبب، کیا اسے ذلت کے ساتھ رکھے گا یا اسے مٹی میں دبادے گا (ف۱۲۱) ارے بہت ہی برا حکم لگاتے ہیں، (ف۱۲۲)'),
 (93,16,60,'جو آخرت پر ایمان نہیں لاتے انہیں کا بر ا حال ہے، اور اللہ کی شان سب سے بلند، (ف۱۲۳) اور وہی عزت و حکمت والا ہے،'),
 (93,16,61,'اور اگر اللہ لوگوں کو ان کے ظلم پر گرفت کرتا (ف۱۲۴) تو زمین پر کوئی چلنے والا نہیں چھوڑتا (ف۱۲۵) لیکن انہیں ایک ٹھہرائے وعدے تک مہلت دیتا ہے (ف۱۲۶) پھر جب ان کا وعدہ آئے گا نہ ایک گھڑی پیچھے ہٹیں نہ آگے بڑھیں،'),
 (93,16,62,'اور اللہ کے لیے وہ ٹھہراتے ہیں جو اپنے لیے ناگوار ہے (ف۱۲۷) اور ان کی زبانیں جھوٹ کہتی ہیں کہ ان کے لیے بھلائی ہے (ف۱۲۸) تو آپ ہی ہوا کہ ان کے لیے آگ ہے اور وہ حد سے گزارے ہوئے ہیں، (ف۱۲۹)'),
 (93,16,63,'خدا کی قسم ہم نے تم سے پہلے کتنی امتوں کی طرف رسول بھیجے تو شیطان نے ان کے کوتک (برُے اعمال) ان کی آنکھوں میں بھلے کر دکھائے (ف۱۳۰) تو آج وہی ان کا رفیق ہے (ف۱۳۱) اور ان کے لیے دردناک عذاب ہے، (ف۱۳۲)'),
 (93,16,64,'اور ہم نے تم پر یہ کتاب نہ اتاری (ف۱۳۳) مگر اس لیے کہ تم لوگوں پر روشن کردو جس بات میں اختلاف کریں (ف۱۳۴) اور ہدایت اور رحمت ایمان والوں کے لیے،'),
 (93,16,65,'اور اللہ نے آسمان سے پانی اتارا تو اس سے زمین کو (ف۱۳۵) زندہ کردیا اس کے مرے پیچھے (ف۱۳۶) بیشک اس میں نشانی ہے ان کو جو کان رکھتے ہیں، (ف۱۳۷)'),
 (93,16,66,'اور بیشک تمہارے لیے چوپایوں میں نگاہ حاصل ہونے کی جگہ ہے (ف۱۳۸) ہم تمہیں پلاتے ہیں اس چیز میں سے جو ان کے پیٹ میں ہے، گوبر اور خون کے بیچ میں سے خالص دودھ گلے سے سہل اترتا پینے والوں کے لیے، (ف۱۳۹)'),
 (93,16,67,'اور کھجور اور انگور کے پھلوں میں سے (ف۱۴۰) کہ اس سے نبیذ بناتے ہو اور اچھا رزق (ف۱۴۱) بیشک اس میں نشانی ہے عقل والوں کو،'),
 (93,16,68,'اور تمہارے رب نے شہد کی مکھی کو الہام کیا کہ پہاڑوں میں گھر بنا اور درختوں میں اور چھتوں میں،'),
 (93,16,69,'پھر ہر قسم کے پھل میں سے کھا اور (ف۱۴۲) اپنے رب کی راہیں چل کر تیرے لیے نرم و آسان ہیں، (ف۱۴۳) اس کے پیٹ سے ایک پینے کی چیز رنگ برنگ نکلتی ہے، جس میں لوگوں کی تندرستی ہے، بیشک اس میں نشانی ہے (ف۱۴۷) دھیان کرنے والوں کو، (ف۱۴۸)'),
 (93,16,70,'اور اللہ نے تمہیں پیدا کیا (ف۱۴۹) پھر تمہاری جان قبض کرے گا (ف۱۵۰) اور تم میں کوئی سب سے ناقض عمر کی طرف پھیرا جاتا ہے (ف۱۵۱) کہ جاننے کے بعد کچھ نہ جانے (ف۱۵۲) بیشک اللہ کچھ جانتا ہے سب کچھ کرسکتا ہے،'),
 (93,16,71,'اور اللہ نے تم میں ایک دوسرے پر رزق میں بڑائی دی (ف۱۵۳) تو جنہیں بڑائی دی ہے وہ اپنا رزق اپنے باندی غلاموں کو نہ پھیر دیں گے کہ وہ سب اس میں برابر ہوجائیں (ف۱۵۴) تو کیا اللہ کی نعمت سے مکرتے ہیں، (ف۱۵۵)'),
 (93,16,72,'اور اللہ نے تمہارے لیے تمہاری جنس سے عورتیں بنائیں اور تمہارے لیے تمہاری عورتوں سے بیٹے اور پوتے نواسے پیدا کیے اور تمہیں ستھری چیزوں سے روز ی دی (ف۱۵۶) تو کیا جھوٹی بات (ف۱۵۷) پر یقین لاتے ہیں اور اللہ کے فضل (ف۱۵۸) سے منکر ہوتے ہیں،'),
 (93,16,73,'اور اللہ کے سوا ایسوں کو پوجتے ہیں (ف۱۵۹) جو انہیں آسمان اور زمین سے کچھ بھی روزی دینے کا اختیار نہیں رکھتے نہ کچھ کرسکتے ہیں،'),
 (93,16,74,'تو اللہ کے لیے مانند نہ ٹھہراؤ (ف۱۶۰) بیشک اللہ جانتا ہے اور تم نہیں جانتے،'),
 (93,16,75,'اللہ نے ایک کہاوت بیان فرمائی (ف۱۶۱) ایک بندہ ہے دوسرے کی ملک آپ کچھ مقدور نہیں رکھتا اور ایک جسے ہم نے اپنی طرف سے اچھی روزی عطا فرمائی تو وہ اس میں سے خرچ کرتا ہے چھپے اور ظاہر (ف۱۶۲) کیا وہ برابر ہوجائیں گے (ف۱۶۳) سب خوبیاں اللہ کو ہیں بلکہ ان میں اکثر کو خبر نہیں (ف۱۶۴)'),
 (93,16,76,'اور اللہ نے کہاوت بیان فرمائی دو مرد ایک گونگا جو کچھ کام نہیں کرسکتا (ف۱۶۵) اور وہ اپنے آقا پر بوجھ ہے جدھر بھیجے کچھ بھلائی نہ لائے (ف۱۶۶) کیا برابر ہوجائے گا ہ اور وہ جو انصاف کا حکم کرتا ہے اور وہ سیدھی راہ پر ہے، ف۱۶۷)'),
 (93,16,77,'اور اللہ ہی کے لیے ہیں آسمانوں اور زمین کی چھپی چیزیں (ف۱۶۸) اور قیامت کا معاملہ نہیں مگر جیسے ایک پلک کا مارنا بلکہ اس سے بھی قریب (ف۱۶۹) بیشک اللہ سب کچھ کرسکتا ہے،'),
 (93,16,78,'اور اللہ نے تمہیں تمہاری ماؤوں کے پیٹ سے پیدا کیا کہ کچھ نہ جانتے تھے (ف۱۷۰) اور تمہیں کان اور آنکھ اور دل دیئے (ف۱۷۱) کہ تم احسان مانو، ف۱۷۲)'),
 (93,16,79,'کیا انہوں نے پرندے نے پرندے نہ دیکھے حکم کے باندھے آسمان کی فضا میں، انہیں کوئی نہیں روکتا (ف۱۷۳) سوا اللہ کے بیشک اس میں نشانیاں ہیں ایمان والوں کو، ف۱۷۴)'),
 (93,16,80,'اور اللہ نے تمہیں گھر دیئے بسنے کو (ف۱۷۵) اور تمہارے لیے چوپایوں کی کھالوں سے کچھ گھر بناےٴ جو تمھیں ہلکے پڑتے ہیں تمھارے سفر کے دن اور منزلوں پرٹھہر نے کے دن، اور ان کی اون اور ببری (رونگٹوں) اور بالوں سے کچھ گرہستی (خانگی ضروریات) کا سامان (ف۱۷۷) اور برتنے کی چیزیں ایک وقت تک،'),
 (93,16,81,'اور اللہ نے تمہیں اپنی بنائی ہوئی چیزوں (ف۱۷۸) سے سائے دیئے (ف۱۷۹) اور تمہارے لیے پہاڑوں میں چھپنے کی جگہ بنائی (ف۱۸۰) اور تمہارے لیے کچھ پہنادے بنائے کہ تمہیں گرمی سے بچائیں اور کچھ پہناوے (ف۱۸۱) کہ لڑائیں میں تمہاری حفاظت کریں (ف۱۸۲) یونہی اپنی نعمت تم پر پوری کرتا ہے (ف۱۸۳) کہ تم فرمان مانو (ف۱۸۴)'),
 (93,16,82,'پھر اگر وہ منہ پھیریں (ف۱۸۵) تو اے محبوب! تم پر نہیں مگر صاف پہنچا دینا، (ف۱۸۶)'),
 (93,16,83,'اللہ کی نعمت پہنچانتے ہیں (ف۱۸۷) پھر اس سے منکر ہوتے ہیں (ف۱۸۸) اور ان میں اکثر کافر ہیں، (ف۱۸۹)'),
 (93,16,84,'اور جس دن (ف۱۹۰) ہم اٹھائیں گے ہر امت میں سے ایک گواہ (ف۱۹۱) پھر کافروں کو نہ اجازت ہو (ف۱۹۲) نہ وہ منائے جائیں، ف۱۹۳)'),
 (93,16,85,'اور ظلم کرنے والے (ف۱۹۴) جب عذاب دیکھیں گے اسی وقت سے نہ وہ ان پر سے ہلکا ہو نہ انہیں مہلت ملے،'),
 (93,16,86,'اور شرک کرنے والے جب اپنے شریکوں کو دیکھیں گے (ف۱۹۵) کہیں گے اے ہمارے رب! یہ ہیں ہمارے شریک کہ ہم تیرے سوا پوجتے تھے، تو وہ ان پر بات پھینکیں گے کہ تم بیشک جھوٹے ہو، (ف۱۹۶)'),
 (93,16,87,'اور اس دن (ف۱۹۷) اللہ کی طرف عاجزی سے گریں گے (ف۱۹۸) اور ان سے گم ہوجائیں گی جو بناوٹیں کرتے تھے، ف۱۹۹)'),
 (93,16,88,'جنہوں نے کفر کیا اور اللہ کی راہ سے روکا ہم نے عذاب پر عذاب بڑھایا (ف۲۰۰) بدلہ ان کے فساد کا،'),
 (93,16,89,'اور جس دن ہم ہر گروہ میں ایک گواہ انہیں میں سے اٹھائیں گے کہ ان پر گواہی دے (ف۲۰۱) اور اے محبوب! تمہیں ان سب پر (ف۲۰۲) شاہد بناکر لائیں گے، اور ہم نے تم پر یہ قرآن اتارا کہ ہر چیز کا روشن بیان ہے (ف۲۰۳) اور ہدایت اور رحمت اور بشارت مسلمانوں کو،'),
 (93,16,90,'بیشک اللہ حکم فرماتا ہے انصاف اور نیکی (ف۲۰۴) اور رشتہ داروں کے دینے کا (ف۲۰۵) اور منع فرماتا بے حیائی (ف۲۰۶) اور برُی بات (ف۲۰۷) اور سرکشی سے (ف۲۰۸) تمہیں نصیحت فرماتا ہے کہ تم دھیان کرو،'),
 (93,16,91,'اور اللہ کا عہد پورا کرو (ف۲۰۹) جب قول باندھو اور قسمیں مضبوط کرکے نہ توڑو اور تم اللہ کو (ف۲۱۰) اپنے اوپر ضامن کرچکے ہو، بیشک تمہارے کام جانتا ہے،'),
 (93,16,92,'اور (ف۲۱۱) اس عورت کی طرح نہ ہو جس نے اپنا سُوت مضبوطی کے بعد ریزہ ریزہ کرکے توڑ دیا (ف۲۱۲) اپنی قسمیں آپس میں ایک بے اصل بہانہ بناتے ہو کہ کہیں ایک گروہ دوسرے گروہ سے زیادہ نہ ہو (ف۲۱۳) اللہ تو اس سے تمہیں آزماتا ہے (ف۲۱۴) اور ضرور تم پر صاف ظاہر کردے گا قیامت کے دن (ف۲۱۹) جس بات میں جھگڑتے تھے، (ف۲۱۶)'),
 (93,16,93,'اور اللہ چاہتا تو تم کو ایک ہی امت کرتا (ف۲۱۷) لیکن اللہ گمراہ کرتا ہے (ف۲۱۸) جسے چاہے، اور راہ دیتا ہے (ف۲۱۹) جسے چاہے، اور ضرور تم سے (ف۲۲۰) تمہارے کام پوچھے جائیں گے، (ف۲۲۱)'),
 (93,16,94,'اور اپنی قسمیں آپس میں بے اصل بہانہ نہ بنالو کہ کہیں کوئی پاؤں (ف۲۲۲) جمنے کے بعد لغزش نہ کرے اور تمہیں برائی چکھنی ہو (ف۲۲۳) بدلہ اس کا کہ اللہ کی راہ سے روکتے تھے اور تمہیں بڑا عذاب ہو (ف۲۲۴)'),
 (93,16,95,'اور اللہ کے عہد پر تھوڑے دام مول نہ لو (ف۲۲۵) بیشک وہ (ف۲۲۶) جو اللہ کے پاس ہے تمہارے لیے بہتر ہے اگر تم جانتے ہو،'),
 (93,16,96,'جو تمہارے پاس ہے (ف۲۲۷) ہوچکے گا اور جو اللہ کے پاس ہے (ف۲۲۸) ہمیشہ رہنے والا، اور ضرور ہم صبر کرنے والوں کو ان کا وہ صلہ دیں گے جو ان کے سب سے اچھے کام کے قابل ہو، (ف۲۲۹)'),
 (93,16,97,'جو اچھا کام کرے مرد ہو یا عورت اور ہو مسلمان (ف۲۳۰) تو ضرور ہم اسے اچھی زندگی جِلائیں گے (ف۲۳۱) اور ضرور انہیں ان کا نیگ (اجر) دیں گے جو ان کے سب سے بہتر کام کے لائق ہوں،'),
 (93,16,98,'تو جب تم قرآن پڑھو تو اللہ کی پناہ مانگو شیطان مردود سے، (ف۲۳۲)،'),
 (93,16,99,'بیشک اس کا کوئی قابو ان پر نہیں جو ایمان لائے اور اپنے رب ہی پر بھروسہ رکھتے ہیں (ف۲۳۳)'),
 (93,16,100,'اس کا قابو تو انہیں پر ہے جو اس سے دوستی کرتے ہیں اور اسے شریک ٹھہراتے ہیں،'),
 (93,16,101,'اور جب ہم ایک آیت کی جگہ دوسری آیت بدلیں (ف۲۳۴) اور اللہ خوب جانتا ہے جو اتارتا ہے (ف۲۳۵) کافر کہیں تم تو دل سے بنا لاتے ہو (ف۲۳۶) بلکہ ان میں اکثر کو علم نہیں، (ف۲۳۷)'),
 (93,16,102,'تم فرماؤ اسے پاکیزگی کی روح (ف۲۳۸) نے اتارا تمہارے رب کی طرف سے ٹھیک ٹھیک کہ اس سے ایمان والوں کو ثابت قدم کرے اور ہدایت اور بشارت مسلمانوں کو،'),
 (93,16,103,'اور بیشک ہم جانتے ہیں کہ وہ کہتے ہیں، یہ تو کوئی آدمی سکھاتا ہے، جس کی طرف ڈھالتے ہیں اس کی زبان عجمی ہے اور یہ روشن عربی زبان (ف۲۳۹)'),
 (93,16,104,'بیشک وہ جو اللہ کی آیتوں پر ایمان نہیں لاتے اللہ انھیں راہ نهیں دیتا اور ان کے لے درد ناک عذاب ہے، (ف۲۴۸)'),
 (93,16,105,'جھوٹ بہتان دہی باندھتے ہین جو اللہ کی آیتوں پر ایمان نہیں رکھتے اور دہی جھوٹے ہیں،'),
 (93,16,106,'جو ایمان لا کر اللہ کا منکر ہو سوا اس کے مجبور کیا جا ےٴ اور اس کا دل ایمان پر جما ہوا ہو، ہاں وہ جو دل کھول کر کافر ہو ان پر اللہ کا غضب ہے اور ان کو بڑاعذاب ہے،'),
 (93,16,107,'یہ اس لےٴ کہ انھوں نے دنیا کی زندگی آخرت سے پیاری جانی، اور اس لےٴ کہ اللہ (ایسے) کافروں کو راہ نہیں دیتا،'),
 (93,16,108,'یہ ہیں وه جن کے دل اور کان اور آنکھو ں پر اللہ نے مہر کر دی ہے اور وہی غفلت مین پڑے ہیں،'),
 (93,16,109,'آپ ہی ہوا کہ آخرت میں وہی خراب (ف۲۴۹)'),
 (93,16,110,'پھر بیشک تمہارا رب ان کے لیے جنہوں نے اپنے گھر چھوڑے (ف۲۵۰) بعد اس کے کہ ستائے گئے (ف۲۵۱) پھر انہوں نے (ف۲۵۲) جہاد کیا اور صابر رہے بیشک تمہارا رب اس (ف۲۵۳) کے بعد ضرور بخشنے والا ہے مہربان،'),
 (93,16,111,'جس دن ہر جان اپنی ہی طرف جھگڑتی آئے گی (ف۲۵۴) اور ہر جان کو اس کا کیا پورا بھردیا جائے گا اور ان پر ظلم نہ ہوگا (ف۲۵۵)'),
 (93,16,112,'اور اللہ نے کہاوت بیان فرمائی (ف۲۵۶) ایک بستی (ف۲۵۷) کہ امان و اطمینان سے تھی (ف۲۵۸) ہر طرف سے اس کی روزی کثرت سے آتی تو وہ اللہ کی نعمتوں کی ناشکری کرنے لگی (ف۲۵۹) تو اللہ نے اسے یہ سزا چکھائی کہ اسے بھوک اور ڈر کا پہناوا پہنایا (ف۲۶۰) بدلہ ان کے کیے کا،'),
 (93,16,113,'اور بیشک ن کے پاس انہیں میں سے ایک رسول تشریف لایا (ف۲۶۱) تو انہوں نے اسے جھٹلایا تو انہیں عذاب نے پکڑا (ف۲۶۲) اور وہ بے انصاف تھے،'),
 (93,16,114,'تو اللہ کی دی ہوئی روزی (ف۲۶۳) حلال پاکیزہ کھاؤ (ف۲۶۴) اور اللہ کی نعمت کا شکر کرو اگر تم اسے پوجتے ہو،'),
 (93,16,115,'تم پر تو یہی حرام کیا ہے مُردار اور خون اور سور کا گوشت اور وہ جس کے ذبح کرتے وقت غیر خدا کا نام پکارا گیا (ف۲۶۵) پھر جو لاچار ہو (ف۲۶۶) نہ خواہش کرتا اور نہ حد سے بڑھتا (ف۲۶۷) تو بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,16,116,'اور نہ کہو اسے جو تمہاری زبانیں جھوٹ بیان کرتی ہیں یہ حلال ہے اور یہ حرام ہے کہ اللہ پر جھوٹ باندھو (ف۲۶۸) بیشک جو اللہ پر جھوٹ باندھتے ہیں ان کا بھلا نہ ہوگا،'),
 (93,16,117,'تھوڑا برتنا ہے (ف۲۶۹) اور ان کے لیے دردناک عذاب (ف۲۷۰)'),
 (93,16,118,'اور خاص یہودیوں پر ہم نے حرام فرمائیں وہ چیزیں جو پہلے تمہیں ہم نے سنائیں (ف۲۷۱) اور ہم نے ان پر ظلم نہ کیا ہاں وہی اپنی جانوں پر ظلم کرتے تھے، (ف۲۷۲)'),
 (93,16,119,'پھر بیشک تمہارا رب ان کے لیے جو نادانی سے (ف۲۷۳) برائی کر بیٹھیں پھر اس کے بعد توبہ کریں اور سنور جائیں بیشک تمہارا رب اس کے بعد (ف۲۷۴) ضرور بخشنے والا مہربان ہے،'),
 (93,16,120,'بیشک ابراہیم ایک امام تھا (ف۳۷۵) اللہ کا فرمانبردار اور سب سے جدا (ف۲۷۶) اور مشرک نہ تھا، (ف۲۷۷)'),
 (93,16,121,'اس کے احسانوں پر شکر کرنے والا، اللہ نے اسے چن لیا (ف۲۷۸) اور اسے سیدھی راہ دکھائی،'),
 (93,16,122,'اور ہم نے اسے دنیا میں بھلائی دی (ف۲۷۹) اور بیشک وہ آخرت میں شایان قرب ہے،'),
 (93,16,123,'پھر ہم نے تمہیں وحی بھیجی کہ دین ابراہیم کی پیروی کرو جو ہر باطل سے الگ تھا اور مشرک نہ تھا، (ف۲۸۰)'),
 (93,16,124,'ہفتہ تو انہیں پر رکھا گیا تھا جو اس میں مختلف ہوگئے (ف۲۸۱) اور بیشک تمہارا رب قیا مت کے دن ان میں فیصلہ کردے گا جس بات میں اختلاف کرتے تھے، (ف۲۸۲)'),
 (93,16,125,'اپنے رب کی راہ کی طرف بلاؤ (ف۲۸۳) پکی تدبیر اور اچھی نصیحت سے (ف۲۸۴) اور ان سے اس طریقہ پر بحث کرو جو سب سے بہتر ہو (ف۲۸۵) بیشک تمہارا رب خوب جانتا ہے جو اس کی راہ سے بہکا اور وہ خوب جانتا ہے راہ والوں کو،'),
 (93,16,126,'اور اگر تم سزا دو تو ایسی ہی سزا دو جیسی تمہیں تکلیف پہونچائی تھی (ف۲۸۶) اور اگر تم صبر کرو (ف۲۸۷) تو بیشک صبر والوں کو صبر سب سے اچھا،'),
 (93,16,127,'اور اے محبوب! تم صبر کرو اور تمہارا صبر اللہ ہی کی توفیق سے ہے اور ان کا غم نہ کھاؤ (ف۲۸۸) اور ان کے فریبوں سے دل تنگ نہ ہو، ف۲۸۹)'),
 (93,16,128,'بیشک اللہ ان کے ساتھ ہے جو ڈرتے ہیں اور جو نیکیاں کرتے ہیں،'),
 (93,17,1,'پاکی ہے اسے (ف۲) جو اپنے بندے (ف۳) کو، راتوں رات لے گیا (ف۴) مسجد حرام سے مسجد اقصیٰ تک (ف۵) جس کے گرداگرد ہم نے برکت رکھی (ف۶) کہ ہم اسے اپنی عظیم نشانیاں دکھائیں، بیشک وہ سنتا دیکھتا ہے،'),
 (93,17,2,'اور ہم نے موسیٰ کو کتاب (ف۷) عطا فرمائی اور اسے بنی اسرائیل کے لیے ہدایت کیا کہ میرے سوا کسی کو کارسام نہ ٹھہراؤ،'),
 (93,17,3,'اے ان کی اولاد! جن کو ہم نے نوح کے ساتھ (ف۸) سوار کیا بیشک وہ بڑا شکرا گزار بندہ تھا (ف۹)'),
 (93,17,4,'اور ہم نے بنی اسرائیل کو کتاب (ف۱۰) میں وحی بھیجی کہ ضرور تم زمین میں دوبارہ فساد مچاؤ گے (ف۱۱) اور ضرور بڑا غرور کرو گے (ف۱۲)'),
 (93,17,5,'پھر جب ان میں پہلی بار (ف۱۳) کا وعدہ آیا (ف۱۴) ہم نے تم پر اپنے بندے بھیجے سخت لڑائی والے (ف۱۵) تو وہ شہروں کے اندر تمہاری تلاش کو گھسے (ف۱۶) اور یہ ایک وعدہ تھا (ف۱۷) جسے پورا ہونا تھا،'),
 (93,17,6,'پھر ہم نے ان پر اُلٹ کر تمہارا حملہ کردیا (ف۱۸) اور تم کو مالوں اور بیٹوں سے مدد دی اور تمہارا جتھا بڑھا دیا،'),
 (93,17,7,'اگر تم بھلائی کرو گے اپنا بھلا کرو گے (ف۱۹) اور اگر بُرا کرو گے تو اپنا، پھر جب دوسری بار کا وعدہ آیا (ف۲۰) کہ دشمن تمہارا منہ بگاڑ دیں (ف۲۱) اور مسجد میں داخل ہوں (ف۲۲) جیسے پہلی بار داخل ہوئے تھے (ف۲۳) اور جس چیز پر قابو پائیں (ف۲۴) تباہ کرکے برباد کردیں،'),
 (93,17,8,'قریب ہے کہ تمہارا رب تم پر رحم کرے (ف۲۵) اور اگر تم پھر شرارت کرو (ف۲۶) تو ہم پھر عذاب کریں گے (ف۲۷) اور ہم نے جہنم کو کافروں کا قید خانہ بنایا ہے،'),
 (93,17,9,'بیشک یہ قرآن وہ راہ دکھاتا ہے جو سب سے سیدھی ہے (ف۲۸) اور خوشی سناتا ہے ایمان والوں کو جو اچھے کام کریں کہ ان کے لیے بڑا ثواب ہے'),
 (93,17,10,'اور یہ کہ جو آخرت پر ایمان نہیں لاتے ہم نے ان کے لیے دردناک عذاب تیار کر رکھا ہے،'),
 (93,17,11,'اور آدمی برائی کی دعا کرتا ہے (ف۲۹) جیسے بھلائی مانگتا ہے (ف۳۰) اور آدمی بڑا جلد باز ہے (ف۳۱)'),
 (93,17,12,'اور ہم نے رات اور دن کو دو نشانیاں بنایا (ف۳۲) تو رات کی نشانی مٹی ہوئی رکھی (ف۳۳) اور دن کی نشانیاں دکھانے والی (ف۳۴) کہ اپنے کا فضل تلاش کرو (ف۳۵) اور (ف۳۶) برسوں کی گنتی اور حساب جانو (ف۳۷) اور ہم نے ہر چیز خوب جدا جدا ظاہر فرمادی (ف۳۸)'),
 (93,17,13,'اور ہر انسان کی قسمت ہم نے اس کے گلے سے لگادی (ف۳۹) اور اس کے لیے قیامت کے دن ایک نوشتہ نکالیں گے جسے کھلا ہوا پائے گا (ف۴۰)'),
 (93,17,14,'فرمایا جائے گا کہ اپنا نامہ (نامہٴ اعمال) پڑھ آج تو خود ہی اپنا حساب کرنے کو بہت ہے،'),
 (93,17,15,'جو راہ پر آیا وہ اپنے ہی بھلے کو راہ پر آیا (ف۴۱) اور جو بہکا تو اپنے ہی برے کو بہکا (ف۴۲) اور کوئی بوجھ اٹھانے والی جان دوسرے کا بوجھ نہ اٹھائے گی (ف۴۳) اور ہم عذاب کرنے والے نہیں جب تک رسول نہ بھیج لیں (ف۴۴)'),
 (93,17,16,'اور جب ہم کسی بستی کو ہلاک کرنا چاہتے ہیں اس کے خوشحالوں (ف۴۵) پر احکام بھیجتے ہیں پھر وہ اس میں بے حکمی کرتے ہیں تو اس پر بات پوری ہوجاتی ہے تو ہم اسے تباہ کرکے برباد کردیتے ہیں،'),
 (93,17,17,'اور ہم نے کتنی ہی سنگتیں (قومیں) (ف۴۶) نوح کے بعد ہلاک کردیں (ف۴۷) اور تمہارا رب کافی ہے اپنے بندوں کے گناہوں سے خبردار دیکھنے والا (ف۴۸)'),
 (93,17,18,'جو یہ جلدی والی چاہے (ف۴۹) ہم اسے اس میں جلد دے دیں جو چاہیں جسے چاہیں (ف۵۰) پھر اس کے لیے جہنم کردیں کہ اس میں جائے مذمت کیا ہوا دھکے کھاتا،'),
 (93,17,19,'اور جو آخرت چاہے اور اس کی سی کوشش کرے (ف۵۱) اور ہو ایمان والا تو انہیں کی کوشش ٹھکانے لگی، (ف۵۲)'),
 (93,17,20,'ہم سب کو مدد دیتے ہیں اُن کو بھی (ف۵۳) اور اُن کو بھی، تمہارے رب کی عطا سے (ف۵۵) اور تمہارے رب کی عطا پر روک نہیں، (ف۵۶)'),
 (93,17,21,'دیکھو ہم نے ان میں ایک کو ایک پر کیسی بڑائی دی (ف۵۷) اور بیشک آخرت درجوں میں سب سے بڑی اور فضل میں سب سے اعلیٰ ہے،'),
 (93,17,22,'اے سننے والے اللہ کے ساتھ دوسرا خدا نہ ٹھہرا کہ تُو بیٹھ رہے گا مذمت کیا جاتا بیکس (ف۵۸)'),
 (93,17,23,'اور تمہارے رب نے حکم فرمایا کہ اس کے سوا کسی کو نہ پُوجو اور ماں باپ کے ساتھ اچھا سلوک کرو، اگر تیرے سامنے ان میں ایک یا دونوں بڑھاپے کو پہنچ جائیں (ف۵۹) تو ان سے ہُوں، نہ کہنا (ف۶۰) اور انہیں نہ جھڑکنا اور ان سے تعظیم کی بات کہنا (ف۶۱)'),
 (93,17,24,'اور ان کے لیے عاجزی کا بازو بچھا (ف۶۲) نرم دلی سے اور عرض کر کہ اے میرے رب تو ان دونوں پر رحم کر جیسا کہ ان دنوں نے مجھے چھٹپن (بچپن) میں پالا (ف۶۳)'),
 (93,17,25,'تمہارا رب خوب جانتا ہے جو تمہارے دلوں میں ہے (ف۶۴) اگر تم لائق ہوئے (ف۶۵) تو بیشک وہ توبہ کرنے والوں کو بخشنے والا ہے،'),
 (93,17,26,'اور رشتہ داروں کو ان کا حق دے (ف۶۶) اور مسکین اور مسافر کو (ف۶۷) اور فضول نہ اڑا (ف۶۸)'),
 (93,17,27,'بیشک اڑانے والے شیطانوں کے بھائی ہیں (ف۶۹) اور شیطان اپنے رب کا بڑا ناشکرا ہے (ف۷۰)'),
 (93,17,28,'اور اگر تو ان سے (ف۷۱) منہ پھیرے اپنے رب کی رحمت کے انتظار میں جس کی تجھے امید ہے تو ان سے آسان بات کہہ (ف۷۲)'),
 (93,17,29,'اور اپنا ہاتھ اپنی گردن سے بندھا ہوا نہ رکھ اور نہ پورا کھول دے کہ تو بیٹھ رہے ملامت کیا ہوا تھکا ہوا (ف۷۳)'),
 (93,17,30,'بیشک تمہارا رب جسے چاہے رزق کشادہ دیتا اور (ف۷۴) کستا ہے (تنگی دیتا ہے) بیشک وہ اپنے بندوں کو خوب جانتا (ف۷۵) دیکھتا ہے،'),
 (93,17,31,'اور اپنی اولاد کو قتل نہ کرو مفلسی کے ڈر سے (ف۷۶) ہم انہیں بھی رزق دیں گے اور تمہیں بھی، بیشک ان کا قتل بڑی خطا ہے،'),
 (93,17,32,'اور بدکاری کے پاس نہ جاؤ بیشک وہ بے حیائی ہے، اور بہت ہی بری راہ،'),
 (93,17,33,'اور کوئی جان جس کی حرمت اللہ نے رکھی ہے ناحق نہ مارو، اور جو ناحق نہ مارا جائے تو بیشک ہم نے اس کے وارث کو قابو دیا (ف۷۷) تو وہ قتل میں حد سے نہ بڑھے (ف۷۸) ضرور اس کی مدد ہونی ہے (ف۷۹)'),
 (93,17,34,'اور یتیم کے مال کے پاس تو جاؤ مگر اس راہ سے جو سب سے بھلی ہے (ف۸۰) یہاں تک کہ وہ اپنی جوانی کو پہنچے (ف۸۱) اور عہد پورا کرو (ف۸۲) بیشک عہد سے سوال ہونا ہے،'),
 (93,17,35,'اور ماپو تو پورا ماپو اور برابر ترازو سے تولو، یہ بہتر ہے اور اس کا انجام اچھا،'),
 (93,17,36,'اور اس بات کے پیچھے نہ پڑ جس کا تجھے علم نہیں (ف۷۳) بیشک کان اور آنکھ اور دل ان سب سے سوال ہونا ہے (ف۸۴)'),
 (93,17,37,'اور زمین میں اتراتا نہ چل (ف۸۵) بیشک ہر گز زمین نہ چیر ڈالے گا، اور ہرگز بلندی میں پہاڑوں کو نہ پہنچے گا (ف۸۶)'),
 (93,17,38,'یہ جو کچھ گزرا ان میں کی بُری بات تیرے رب کو ناپسند ہے،'),
 (93,17,39,'یہ ان وحیوں میں سے ہے جو تمہارے رب نے تمہاری طرف بھیجی حکمت کی باتیں (ف۸۷) اور اے سننے والے اللہ ساتھ دوسرا خدا نہ ٹھہرا کہ تو جہنم میں پھینکا جائے گا طعنہ پاتا دھکے کھاتا،'),
 (93,17,40,'کیا تمہارے رب نے تم کو بیٹے چن دیے اور اپنے لیے فرشتوں سے بیٹیاں بنائیں (ف۸۸) بیشک تم بڑا بول بولتے ہو (ف۸۹)'),
 (93,17,41,'اور بیشک ہم نے اس قرآن میں طرح طرح سے بیان فرمایا (ف۹۰) کہ وہ سمجھیں (ف۹۱) اور اس سے انھیں نہیں بڑھتی مگر نفرت (ف۹۲)'),
 (93,17,42,'تم فرماؤ اگر اس کے ساتھ اور خدا ہوتے جیسا یہ بکتے ہیں جب تو وہ عرش کے مالک کی طرف کوئی راہ ڈھونڈ نکالتے (ف۹۳)'),
 (93,17,43,'اسے پاکی اور برتری ان کی باتوں سے بڑی برتری،'),
 (93,17,44,'اس کی پاکی بولتے ہیں ساتوں آسمان اور زمین اور جو کوئی ان میں ہیں (ف۹۴) اور کوئی چیز نہیں (ف۹۵) جو اسے سراہتی ہوتی اس کی پاکی نہ بولے (ف۹۶) ہاں تم ان کی تسبیح نہیں سمجھتے (ف۹۷) بیشک وہ حلم والا بخشنے والا ہے (ف۹۸)'),
 (93,17,45,'اور اے محبوب! تم نے قرآن پڑھا ہم نے تم پر اور ان میں کہ آخرت پر ایمان ہیں لاتے ایک چھپا ہوا پردہ کردیا (ف۹۹)'),
 (93,17,46,'اور ہم نے ان کے دلوں پر غلاف ڈال دیے ہیں کہ اسے نہ سمجھیں اور ان کے کانوں میں ٹینٹ (روئی) (ف۱۰۰) اور جب تم قرآن میں اپنے اکیلے رب کی یاد کرتے ہو وہ پیٹھ پھیر کر بھاگتے ہیں نفرت کرتے،'),
 (93,17,47,'ہم خوب جانتے ہیں جس لیے وہ سنتے ہیں (ف۱۰۱) جب تمہاری طرف کان لگاتے ہیں اور جب آپس میں مشورہ کرتے ہیں جبکہ ظالم کہتے ہیں تم پیچھے نہیں چلے مگر ایک ایسے مرد کے جس پر جادو ہوا (ف۱۰۲)'),
 (93,17,48,'دیکھو انہوں نے تمہیں کیسی تشبیہیں دیں تو گمراہ ہوئے کہ راہ نہیں پاسکتے،'),
 (93,17,49,'اور بولے کیا جب ہم ہڈیاں اور ریزہ ریزہ ہوجائیں گے کیا سچ مچ نئے بن کر اٹھیں گے (ف۱۰۳)'),
 (93,17,50,'تم فرماؤ کہ پتھر یا لوہا ہوجاؤ،'),
 (93,17,51,'یا اور کوئی مخلوق جو تمہارے خیال میں بڑی ہو (۱۰۴) تو اب کہیں گے ہمیں کون پھر پیدا کرتے گا، تم فرماؤ وہی جس نے تمہیں پہلی بار پیدا کیا، تو اب تمہاری طرف مسخرگی سے سر ہِلا کر کہیں گے یہ کب ہے (ف۱۰۵) تم فرماؤ شاید نزدیک ہی ہو،'),
 (93,17,52,'جس دن وہ تمہیں بُلائے گا (ف۱۰۶) تو تم اس کی حمد کرتے چلے آؤ گے اور (ف۱۰۷) سمجھو گے کہ نہ رہے (۱۰۸) تھے مگر تھوڑا،'),
 (93,17,53,'اور میرے (ف۱۰۹) بندوں سے فرماؤ (ف۱۱۰) وہ بات کہیں جو سب سے اچھی ہو (ف۱۱۱) بیشک شیطان ان کے آپس میں فساد ڈالتا ہے، بیشک شیطان آدمی کا کھلا دشمن ہے،'),
 (93,17,54,'تمہارا رب تمہیں خوب جانتا ہے، وہ چاہے تو تم پر رحم کرے (ف۱۱۲) چاہے تو تمہیں عذاب کرے، اور ہم نے تم کو ان پر کڑوڑا (حاکمِ اعلیٰ) بناکر نہ بھیجا (ف۱۱۳)'),
 (93,17,55,'اور تمہارا رب خوب جانتا ہے جو کوئی آسمانوں اور زمین میں ہیں (ف۱۱۴) اور بیشک ہم نے نبیوں میں ایک کو ایک پر بڑائی دی (ف۱۱۵) اور داؤد کو زبور عطا فرمائی (ف۱۱۶)'),
 (93,17,56,'تم فرماؤ پکارو انہیں جن کو اللہ کے سوا گمان کرتے ہو تو وہ اختیار نہیں رکھتے تم سے تکلیف دو کرنے اور نہ پھیر دینے کا (ف۱۱۷)'),
 (93,17,57,'وہ مقبول بندے جنہیں یہ کافر پوجتے ہیں (ف۱۱۸) وہ آپ ہی اپنے رب کی طرف وسیلہ ڈھونڈتے ہیں کہ ان میں کون زیادہ مقرب ہے (ف۱۱۹) اس کی رحمت کی امید رکھتے اور اس کے عذاب سے ڈرتے ہیں (ف۱۲۰) بیشک تمہارے رب کا عذاب ڈر کی چیز ہے،'),
 (93,17,58,'اور کوئی بستی نہیں مگر یہ کہ ہم اسے روزِ قیامت سے پہلے نیست کردیں گے یا اسے سخت عذاب دیں گے (ف۱۲۱) یہ کتاب میں (ف۱۲۲) لکھا ہوا ہے،'),
 (93,17,59,'اور ہم ایسی نشانیاں بھیجنے سے یوں ہی باز رہے کہ انہیں اگلوں نے جھٹلایا (ف۱۲۳) اور ہم نے ثمود کو (ف۱۲۴) ناقہ دیا آنکھیں کھولنے کو (ف۱۲۵) تو انہوں نے اس پر ظلم کیا (ف۱۲۶) اور ہم ایسی نشانیاں نہیں بھیجتے مگر ڈرانے کو (ف۱۲۷)'),
 (93,17,60,'اور جب ہم نے تم سے فرمایا کہ سب لوگ تمہارے رب کے قابو میں ہیں (ف۱۲۸) اور ہم نے نہ کیا وہ دکھاوا (ف۱۲۹) جو تمہیں دکھایا تھا (ف۱۳۰) مگر لوگوں کی آزمائش کو (ف۱۳۱) اور وہ پیڑ جس پر قرآن میں لعنت ہے (ف۱۳۲) اور ہم انہیں ڈراتے ہیں (ف۱۳۳) تو انھیں نہیں بڑھتی مگر بڑی سرکشی،'),
 (93,17,61,'اور یاد کرو جب ہم نے فرشتوں کو حکم دیا کہ آدم کو سجدہ کرو (ف۱۳۴) تو ان سب نے سجدہ کیا سوا ابلیس کے، بولا کیا میں اسے سجدہ کروں جسے تو نے مٹی سے بنایا'),
 (93,17,62,'بولا (ف۱۳۵) دیکھ تو جو یہ تو نے مجھ سے معزز رکھا (ف۱۳۶) اگر تو نے مجھے قیامت تک مہلت دی تو ضرور میں اس کی اولاد کو پیس ڈالوں گا (ف۱۳۷) مگر تھوڑا (ف۱۳۸)'),
 (93,17,63,'فرمایا، دور ہو (ف۱۳۹) تو ان میں جو تیری پیروی کرے گا تو بیشک سب کا بدلہ جہنم ہے بھرپور سزا،'),
 (93,17,64,'اور ڈگا دے (بہکادے) ان میں سے جس پر قدرت پائے اپنی آواز سے (ف۱۴۰) اور ان پر لام باندھ (فوج چڑھا) لا اپنے سواروں اور اپنے پیادوں کا (ف۱۴۱) اور ان کا ساجھی ہو مالوں اور بچو ں میں (ف۱۴۲) اور انہیں وعدہ دے (ف۱۴۳) اور شیطان انہیں وعدہ نہیں دیتا مگر فریب سے،'),
 (93,17,65,'بیشک جو میرے بندے ہیں (ف۱۴۴) ان پر تیرا کچھ قابو نہیں، اور تیرا رب کافی ہے کام بنانے کو (ف۱۴۵)'),
 (93,17,66,'تمہارا رب وہ ہے کہ تمہارے لیے دریا میں کشتی رواں کرتا ہے کہ (ف۱۴۶) تم اس کا فضل تلاش کرو، بیشک وہ تم پر مہربان ہے،'),
 (93,17,67,'اور جب تمہیں دریا میں مصیبت پہنچتی ہے (ف۱۴۷) تو اس کے سوا جنہیں پوجتے ہیں سب گم ہوجاتے ہیں (ف۱۴۸) پھر جب تمہیں خشکی کی طرف نجات دیتا ہے تو منہ پھیر لیتے ہیں (ف۱۴۹) اور انسان بڑا ناشکرا ہے،'),
 (93,17,68,'کیا تم (ف۱۵۰) اس سے نڈر ہوئے کہ وہ خشکی ہی کا کوئی کنارہ تمہارے ساتھ دھنسادے (ف۱۵۱) یا تم پر پتھراؤ بھیجے (ف۱۵۲) پھر اپنا کوئی حمایتی نہ پاؤ (ف۱۵۳)'),
 (93,17,69,'یا اس سے نڈر ہوئے کہ تمہیں دوبارہ دریا میں لے جائے پھر تم پر جہاز توڑنے والی آندھی بھیجے تو تم کو تمہارے کفر کے سبب ڈبو دے پھر اپنے لیے کوئی ایسا نہ پاؤ کہ اس پر ہمارا پیچھا کرے (ف۱۵۴)'),
 (93,17,70,'اور بیشک ہم نے اولادِ آدم کو عزت دی (ف۱۵۵) اور ان کی خشکی اور تری میں (ف۱۵۶) سوار کیا اور ان کو ستھری چیزیں روزی دیں (ف۱۵۷) اور ان کو اپنی بہت مخلوق سے افضل کیا (ف۱۵۸)'),
 (93,17,71,'جس دن ہم ہر جماعت کو اس کے امام کے ساتھ بلائیں گے (ف۱۵۹) تو جو اپنا نامہ داہنے ہاتھ میں دیا گیا یہ لوگ اپنا نامہ پڑھیں گے (ف۱۶۰) اور تاگے بھر ان کا حق نہ دبایا جائے گا (ف۱۶۱)'),
 (93,17,72,'اور جو اس زندگی میں (ف۱۶۲) اندھا ہو وہ آخرت میں اندھا ہے (ف۱۶۳) اور اوربھی زیادہ گمراہ،'),
 (93,17,73,'اور وہ تو قریب تھا کہ تمہیں کچھ لغزش دیتے ہماری وحی سے جو ہم نے تم کو بھیجی کہ تم ہماری طرف کچھ اور نسبت کردو، اور ایسا ہوتا تو وہ تم کو اپنا گہرا دو ست بنالیتے (ف۱۶۴)'),
 (93,17,74,'اور اگر ہم تمہیں (ف۱۶۵) ثابت قدم نہ رکھتے تو قریب تھا کہ تم ان کی طرف کچھ تھوڑا سا جھکتے'),
 (93,17,75,'اور ایسا ہوتا تو ہم تم کو دُونی عمر اور دو چند موت (ف۱۶۶) کا مزہ دیتے پھر تم ہمارے مقابل اپنا کوئی مددگار نہ پاتے،'),
 (93,17,76,'اور بیشک قریب تھا کہ وہ تمہیں اس زمین سے (ف۱۶۷) ڈگا دیں (کھسکادیں) کہ تمہیں اس سے باہر کردیں اور ایسا ہوتا تو وہ تمہارے پیچھے نہ ٹھہرتے مگر تھوڑا (ف۱۶۸)'),
 (93,17,77,'دستور ان کا جو ہم نے تم سے پہلے رسول بھیجے (ف۱۶۹) اور تم ہمارا قانون بدلتا نہ پاؤ گے،'),
 (93,17,78,'نماز قائم رکھو سورج ڈھلنے سے رات کی اندھیری تک (ف۱۷۰) اور صبح کا قرآن (ف۱۷۱) بیشک صبح کے قرآن میں فرشتے حاضر ہوتے ہیں (ف۱۷۲)'),
 (93,17,79,'اور رات کے کچھ حصہ میں تہجد کرو یہ خاص تمہارے لیے زیادہ ہے (ف۱۷۳) قریب ہے کہ تمہیں تمہارا رب ایسی جگہ کھڑا کرے جہاں سب تمہاری حمد کریں (ف۱۷۴)'),
 (93,17,80,'اور یوں عرض کرو کہ اے میرے رب مجھے سچی طرح داخل کر اور سچی طرح باہر لے جا (ف۱۷۵) اور مجھے اپنی طرف سے مددگار غلبہ دے (ف۱۷۶)'),
 (93,17,81,'اور فرماؤ کہ حق آیا اور باطل مٹ گیا (ف۱۷۷) بیشک باطل کو مٹنا ہی تھا (ف۱۷۸)'),
 (93,17,82,'اور ہم قرآن میں اتارتے ہیں وہ چیز (۱۷۹) جو ایمان والوں کے لیے شفا اور رحمت ہے (ف۱۸۰) اور اس سے ظالموں کو (ف۱۸۱) نقصان ہی بڑھتا ہے،'),
 (93,17,83,'اور جب ہم آدمی پر احسان کرتے ہیں (ف۱۸۲) منہ پھیرلیتا ہے اور اپنی طرف دور ہٹ جاتا ہے (ف۱۸۳) اور جب اسے برائی پہنچے (ف۱۸۴) تو ناامید ہوجاتا ہے (ف۱۸۵)'),
 (93,17,84,'تم فرماؤ سب اپنے کینڈے (انداز) پر کام کرتے ہیں (ف۱۸۶) تو تمہارا رب خوب جانتا ہے کون زیادہ راہ پر ہے،'),
 (93,17,85,'اور تم سے روح کو پوچھتے ہیں ہیں، تم فرماؤ روح میرے رب کے حکم سے ایک چیز ہے اور تمہیں علم نہ ملا مگر تھوڑا (ف۱۸۷)'),
 (93,17,86,'اور اگر ہم چاہتے تو یہ وحی جو ہم نے تمہاری طرف کی اسے لے جاتے (ف۱۸۸) پھر تم کوئی نہ پاتے کہ تمہارے لیے ہمارے حضور اس پر وکالت کرتا'),
 (93,17,87,'مگر تمہارے رب کی رحمت (ف۱۸۹) بیشک تم پر اس کا بڑا فضل ہے (ف۱۹۰)'),
 (93,17,88,'تم فرماؤ اگر آدمی اور جن سب اس بات پر متفق ہوجائیں کہ (ف۱۹۱) اس قرآن کی مانند لے آئیں تو اس کا مثل نہ لاسکیں گے اگرچہ ان میں ایک دوسرے کا مددگار ہو (ف۱۹۲)'),
 (93,17,89,'اور بیشک ہم نے لوگوں کے لیے اس قرآن میں ہم قسم کی مثل طرح طرح بیان فرمائی تو اکثر آدمیوں نے نہ مانا مگر ناشکری کرنا (ف۱۹۳)'),
 (93,17,90,'اور بولے کہ ہم تم پر ہرگز ایمان نہ لائیں گے یہاں تک کہ تم ہمارے لیے زمین سے کوئی چشمہ بہا دو (ف۱۹۴)'),
 (93,17,91,'یا تمہارے لیے کھجوروں اور انگوروں کا کوئی باغ ہو پھر تم اس کے لیے اندر بہتی نہریں رواں کرو'),
 (93,17,92,'یا تم ہم پر آسمان گرا دو جیسا تم نے کہا ہے ٹکڑے ٹکڑے یااللہ اور فرشتوں کو ضامن لے آؤ (ف۱۹۵)'),
 (93,17,93,'یا تمہارے لیے طلائی گھر ہو یا تم آسمان پر چڑھ جاؤ اور ہم تمہارے چڑھ جانے پر بھی ہرگز ایمان نہ لائیں گے جب تک ہم پر ایک کتاب نہ اتارو جو ہم پڑھیں، تم فرماؤ پاکی ہے میرے رب کو میں کون ہوں مگر آدمی اللہ کا بھیجا ہوا (ف۱۹۶)'),
 (93,17,94,'اور کس بات نے لوگوں کو ایمان لانے سے روکا جب ان کے پاس ہدایت آئی مگر اسی نے کہ بولے کیا اللہ نے آدمی اللہ کا بھیجا ہوا (ف۱۹۶) اور کس بات نے لوگوں کو ایمان لانے سے روکا جب ان کے پاس ہدایت آئی مگر اسی نے کہ بولے کیا اللہ نے آدمی کو رسول بناکر بھیجا (ف۱۹۷)'),
 (93,17,95,'تم فرماؤ اگر زمین میں فرشتے ہوتے (ف۱۹۸) چین سے چلتے تو ان پر ہم رسول بھی فرشتہ اتارتے (ف۱۹۹)'),
 (93,17,96,'تم فرماؤ اللہ بس ہے گواہ میرے تمہارے درمیان (۲۰۰) بیشک وہ اپنے بندوں کو جانتا دیکھتا ہے،'),
 (93,17,97,'اور جسے اللہ راہ دے وہی راہ پر ہے اور جسے گمراہ کرے (ف۲۰۱) تو ان کے لیے اس کے سوا کوئی حمایت والے نہ پاؤ گے (ف۲۰۲) اور ہم انہیں قیامت کے دن ان کے منہ کے بل (ف۲۰۳) اٹھائیں گے اندھے اور گونگے اور بہرے (ف۲۰۴) ان کا ٹھکانا جہنم ہے جب کبھی بجھنے پر آئے گی ہم اسے اور بھڑکادیں گے،'),
 (93,17,98,'یہ ان کی سزا ہے اس پر کہ انہوں نے ہماری آیتوں سے انکار کیا اور بولے کیا جب ہم ہڈیاں اور ریزہ ریزہ ہوجائیں گے تو کیا سچ مچ ہم نئے بن کر اٹھائے جائیں گے،'),
 (93,17,99,'اور کیا وہ نہیں دیکھتے کہ وہ اللہ جس نے آسمان اور زمین بنائے (ف۲۰۵) ان لوگوں کی مثل بناسکتا ہے (ف۲۰۶) اور اس نے ان کے لیے (ف۲۰۷) ایک میعاد ٹھہرا رکھی ہے جس میں کچھ شبہ نہیں تو ظالم نہیں مانتے بے ناشکری کیے (ف۲۰۸)'),
 (93,17,100,'تم فرماؤ اگر تم لوگ میرے رب کی رحمت کے خزانوں کے مالک ہوتے (ف۲۰۹) تو انہیں بھی روک رکھتے اس ڈر سے کہ خرچ نہ ہوجائیں، اور آدمی بڑا کنجوس ہے،'),
 (93,17,101,'اور بیشک ہم نے موسیٰ کو نو روشن نشانیاں دیں (ف۲۱۰) تو بنی اسرائیل سے پوچھو جب وہ (ف۲۱۱) ان کے پاس آیا تو اس سے فرعون نے کہا، اے موسیٰ! میرے خیال میں تو تم پر جادو ہوا (ف۲۱۲)'),
 (93,17,102,'کہا یقیناً تو خوب جانتا ہے (ف۲۱۳) کہ انہیں نہ اتارا مگر آسمانوں اور زمین کے مالک نے دل کی آنکھیں کھولنے والیاں (ف۲۱۴) اور میرے گمان میں تو اے فرعون! تو ضرور ہلاک ہونے والا ہے (ف۲۱۵)'),
 (93,17,103,'تو اس نے چاہا کہ ان کو (ف۲۱۶) زمین سے نکال دے تو ہم نے اسے اور اس کے ساتھیوں کو سب کو ڈبو دیا (ف۲۱۷)'),
 (93,17,104,'اور اس کے بعد ہم نے بنی اسرائیل سے فرمایا اس زمین میں بسو (ف۲۱۸) پھر جب آخرت کا وعدہ آئے گا (ف۲۱۹) ہم تم سب کو گھال میل (لپیٹ کر) لے آئیں گے (ف۲۲۰)'),
 (93,17,105,'اور ہم نے قرآن کو حق ہی کے ساتھ اتارا اور حق وہی کے لیے اترا (ف۲۲۱) اور ہم نے تمہیں نہ بھیجا مگر خوشی اور ڈر سناتا،'),
 (93,17,106,'اور قرآن ہم نے جدا جدا کرکے (ف۲۲۲) اتارا کہ تم اسے لوگوں پر ٹھہر ٹھہر کر پڑھو (ف۲۲۳) اور ہم نے اسے بتدریج رہ رہ کر اتارا (ف۲۲۴)'),
 (93,17,107,'تم فرماؤ کہ تم لوگ اس پر ایمان لاؤ یا نہ لاؤ (ف۲۲۵) بیشک وہ جنہیں اس کے اترنے سے پہلے علم ملا (ف۲۲۶) اب ان پر پڑھا جاتا ہے، ٹھوڑی کے بل سجدہ میں گر پڑتے ہیں،'),
 (93,17,108,'اور کہتے ہیں پاکی ہے ہمارے رب کو بیشک ہمارے اب کا وعدہ پورا ہوتا تھا (ف۲۲۷)'),
 (93,17,109,'اور تھوڑی کے بل گرتے ہیں (ف۲۲۸) روتے ہوئے اور یہ قرآن ان کے دل کا جھکنا بڑھاتا ہے، (ف۲۲۹) (السجدة) ۴'),
 (93,17,110,'تم فرماؤ اللہ کہہ کر پکارو رحمان کہہ کر، جو کہہ کر پکارو سب اسی کے اچھے نام ہیں (ف۲۳۰) اور اپنی نماز نہ بہت آواز سے پڑھو نہ بالکل آہستہ اور ان دنوں کے بیچ میں راستہ چاہو (ف۲۳۱)'),
 (93,17,111,'اور یوں کہو سب خوبیاں اللہ کو جس نے اپنے لیے بچہ اختیار نہ فرمایا (ف۲۳۲) اور بادشاہی میں کوئی اس کا شریک نہیں (ف۲۳۳) اور کمزوری سے کوئی اس کا حمایتی نہیں (ف۲۳۴) اور اس کی بڑائی بولنے کو تکبیر کہو (ف۲۳۵)'),
 (93,18,1,'سب خوبیاں اللہ کو جس نے اپنے بندے (ف۲) پر کتاب اتاری (ف۳) اور اس میں اصلاً (بالکل، ذرا بھی) کجی نہ رکھی، (ف۴)'),
 (93,18,2,'عدل والی کتاب کہ (ف۵) اللہ کے سخت عذاب سے ڈرائے اور ایمان والوں کو جو نیک کام کریں بشارت دے کہ ان کے لیے اچھا ثواب ہے،'),
 (93,18,3,'جس میں ہمیشہ رہیں گے،'),
 (93,18,4,'اور ان (ف۶) کو ڈرائے جو کہتے ہیں کہ اللہ نے اپنا کوئی بچہ بنایا،'),
 (93,18,5,'اس بارے میں نہ وہ کچھ علم رکھتے ہیں نہ ان کے باپ دادا (ف۷) کتنا بڑا بول ہے کہ ان کے منہ سے نکلتا ہے، نِرا جھوٹ کہہ رہے ہیں،'),
 (93,18,6,'تو کہیں تم اپنی جان پر کھیل جاؤ گے ان کے پیچھے اگر وہ اس بات پر (ف۸) ایمان نہ لائیں غم سے (ف۹)'),
 (93,18,7,'بیشک ہم نے زمین کا سنگھار کیا جو کچھ اس پر ہے (ف۱۰) کہ انہیں آزمائیں ان میں کس کے کام بہتر ہیں (ف۱۱)'),
 (93,18,8,'اور بیشک جو کچھ اس پر ہے ایک دن ہم اسے پٹ پر میدان (سفید زمین) کو چھوڑیں گے (ف۱۲)'),
 (93,18,9,'کیا تمہیں معلوم ہوا کہ پہاڑ کی کھوہ اور جنگل کے کنارے والے (ف۱۳) ہماری ایک عجیب نشانی تھے،'),
 (93,18,10,'جب ان نوجوانوں نے (ف۱۴) غار میں پناہ لی پھر بولے اے ہمارے رب ہمیں اپنے پاس سے رحمت دے (ف۱۵) اور ہمارے کام میں ہمارے لیے راہ یابی کے سامان کر،'),
 (93,18,11,'تو ہم نے اس غار میں ان کے کے کانوں پر گنتی کے کئی برس تھپکا (ف۱۶)'),
 (93,18,12,'پھر ہم نے انھیں جگایا کہ دیکھیں (ف۱۷) دو گروہوں میں کون ان کے ٹھہرنے کی مدت زیادہ ٹھیک بتاتا ہے،'),
 (93,18,13,'ہم ان کا ٹھیک ٹھیک حال تمہیں سنائیں، وہ کچھ جوان تھے کہ اپنے رب پر ایمان لائے اور ہم نے ان کو ہدایت بڑھائی،'),
 (93,18,14,'اور ہم نے ان کی ڈھارس بندھائی جب (ف۱۸) کھڑے ہوکر بولے کہ ہمارا رب وہ ہے جو آسمان اور زمین کا رب ہے ہم اس کے سوا کسی معبود کو نہ پوجیں گے ایسا ہو تو ہم نے ضرور حد سے گزری ہوئی بات کہی،'),
 (93,18,15,'یہ جو ہماری قوم ہے اس نے اللہ کے سوا خدا بنا رکھے ہیں، کیوں نہیں لاتے ان پر کوئی روشن سند، تو اس سے بڑھ کر ظالم کون جو اللہ پر جھوٹ باندھے (ف۱۹)'),
 (93,18,16,'اور جب تم ان سے اور جو کچھ وہ اللہ سوا پوجتے ہیں سب سے الگ ہوجاؤ تو غار میں پناہ لو تمہارا رب تمہارے لیے اپنی رحمت پھیلادے گا اور تمہارے کام میں آسانی کے سامان بنادے گا،'),
 (93,18,17,'اور اے محبوب! تم سورج کو دیکھو گے کہ جب نکلتا ہے تو ان کے غار سے داہنی طرف بچ جاتا ہے اور جب ڈوبتا ہے تو ان سے بائیں طرف کترا جاتا ہے (ف۲۰) حالانکہ وہ اس غار کے کھلے میدان میں میں ہیں (ف۲۱) یہ اللہ کی نشانیوں میں سے ہے جسے اللہ راہ دے تو وہی راہ پر ہے، اور جسے گمراہ کرے تو ہرگز اس کا کوئی حمایتی راہ دکھانے والا نہ پاؤ گے،'),
 (93,18,18,'اور تم انھیں جاگتا سمجھو (ف۲۲) اور وہ سوتے ہیں اور ہم ان کی داہنی بائیں کروٹیں بدلتے ہیں (ف۲۳) اور ان کا کتا اپنی کلائیاں پھیلائے ہوئے ہے غار کی چوکھٹ پر (ف۲۴) اے سننے! والے اگر تو انہیں جھانک کر دیکھے تو ان سے پیٹھ پھیر کر بھاگے اور ان سے ہیبت میں بھر جائے (ف۲۵)'),
 (93,18,19,'اور یوں ہی ہم نے ان کو جگایا (ف۲۶) کہ آپس میں ایک دوسرے سے احوال پوچھیں (ف۲۷) ان میں ایک کہنے والا بولا (ف۲۸) تم یہاں کتنی دیر رہے، کچھ بولے کہ ایک دن رہے یا دن سے کم (ف۲۹) دوسرے بولے تمہارا رب خوب جانتا ہے جتنا تم ٹھہرے (ف۳۰) تو اپنے میں ایک کو یہ چاندی لے کر (ف۳۱) شہر میں بھیجو پھر وہ غور کرے کہ وہاں کون سا کھانا زیادہ ستھرا ہے (ف۳۲) کہ تمہارے لیے اس میں سے کھانے کو لائے اور چاہیے کہ نرمی کرے اور ہرگز کسی کو تمہاری اطلاع نہ دے،'),
 (93,18,20,'بیشک اگر وہ تمہیں جان لیں گے تو تمہیں پتھراؤ کریں گے (ف۳۳) یا اپنے دین (ف۳۴) میں پھیر لیں گے اور ایسا ہوا تو تمہارا کبھی بھلا نہ ہوگا،'),
 (93,18,21,'اور اسی طرح ہم نے ان کی اطلاع کردی (ف۳۵) کہ لوگ جان لیں (ف۳۶) کہ اللہ کا وعدہ سچا ہے اور قیامت میں کچھ شبہ نہیں، جب وہ لوگ ان کے معاملہ میں باہم جھگڑنے لگے (ف۳۷) تو بولے ان کے غار پر کوئی عمارت بناؤ، ان کا رب انہیں خوب جانتا ہے، وہ بولے جو اس کام میں غالب رہے تھے (ف۳۸) قسم ہے کہ ہم تو ان پر مسجد بنائیں گے (ف۳۹)'),
 (93,18,22,'اب کہیں گے (ف۴۰) کہ وہ تین ہیں چوتھا ان کا کتا اور کچھ کہیں گے پانچ ہیں، چھٹا ان کا کتا بے دیکھے الاؤتکا (تیر تکا) بات (ف۴۱) اور کچھ کہیں گے سات ہیں (ف۴۲) اور آٹھواں ان کا کتا تم فرماؤ میرا رب ان کی گنتی خوب جانتا ہے (ف۴۳) انہیں نہیں جانتے مگر تھوڑے (ف۴۴) تو ان کے بارے میں (ف۴۵) بحث نہ کرو مگر اتنی ہی بحث جو ظاہر ہوچکی (ف۴۶)'),
 (93,18,23,'اور ان کے (ف ۴۷) بارے میں کسی کتابی سے کچھ نہ پوچھو، اور ہر گز کسی بات کو نہ کہنا میں کل یہ کردوں گا،'),
 (93,18,24,'مگر یہ کہ اللہ چاہے (ف۴۸) اور اپنے رب کی یاد کر جب تو بھول جائے (ف۴۹) اور یوں کہو کہ قریب ہے میرا رب مجھے اس (ف۵۰) سے نزدیک تو راستی کی راہ دکھائے، (ف۵۱)'),
 (93,18,25,'اور وہ اپنے غار میں تین سو برس ٹھہرے نو اوپر، ف۵۲)'),
 (93,18,26,'تم فرماؤ اللہ خوب جانتا ہے وہ جتنا ٹھہرے (ف۵۳) اسی کے لیے ہیں آسمانوں اور زمینوں کے سب غیب، وہ کیا ہی دیکھتا اور کیا ہی سنتا ہے (ف۵۴) اس کے سوا ان کا (ف۵۵) کوئی والی نہیں، اور وہ اپنے حکم میں کسی کو شریک نہیں کرتا،'),
 (93,18,27,'اور تلاوت کرو جو تمہارے رب کی کتاب (ف۵۶) تمہیں وحی ہوئی اس کی باتوں کا کوئی بدلنے والا نہیں (ف۵۷) اور ہرگز تم اس کے سوا پناہ نہ پاؤ گے،'),
 (93,18,28,'اور اپنی جان ان سے مانوس رکھو جو صبح و شام اپنے رب کو پکارتے ہیں اس کی رضا چاہتے ہیں (ف۵۸) اور تمہاری آنکھیں انہیں چھوڑ کر اور پر نہ پڑیں کیا تم دنیا کی زندگانی کا سنگھار چاہو گے، اور اس کا کہا نہ مانو جس کا دل ہم نے اپنی یاد سے غافل کردیا اور وہ اپنی خواہش کے پیچھے چلا اور اس کا کام حد سے گزر گیا،'),
 (93,18,29,'اور فرما دو کہ حق تمہارے رب کی طرف سے ہے (ف۵۹) تو جو چاہے ایمان لائے اور جو چاہے کفر کرے (ف۶۰) بیشک ہم نے ظالموں (ف۶۱) کے لیے وہ آگ تیار کر رکھی ہے جس کی دیواریں انہیں گھیر لیں گی، اور اگر (ف۶۲) پانی کے لیے فریاد کریں تو ان کی فریاد رسی ہوگی اس پانی سے کہ چرخ دے (کھولتے ہوئے) دھات کی طرح ہے کہ ان کے منہ بھون دے گا کیا ہی برا پینا ہے (ف۶۳) اور دوزخ کیا ہی بری ٹھہرنے کی جگہ،'),
 (93,18,30,'بیشک جو ایمان لائے اور نیک کام کیے ہم ان کے نیگ (اجر) ضائع نہیں کرتے جن کے کام اچھے ہوں، (ف۶۴)'),
 (93,18,31,'ان کے لیے بسنے کے باغ ہیں ان کے نیچے ندیاں بہیں وہ اس میں سونے کے کنگن بہنائے جایں گے (ف۶۵) اور سبز کپڑے کریب اور قناویز کے پہنیں گے وہاں تختوں پر تکیہ لگائے (ف۶۶) کیا ہی اچھا ثواب اور جنت کی کیا ہی اچھی آرام کی جگہ،'),
 (93,18,32,'اور ان کے سامنے دو مردوں کا حال بیان کرو (ف۶۷) کہ ان میں ایک کو (ف۶۸) ہم نے انگوروں کے دو باغ دیے اور ان کو کھجوروں سے ڈھانپ لیا اور ان کے بیچ میں کھیتی رکھی (ف۶۹)'),
 (93,18,33,'دونوں باغ اپنے پھل لائے اور اس میں کچھ کمی نہ دی (ف۷۰) اور دونوں کے بیچ میں ہم نے نہر بہائی'),
 (93,18,34,'اور وہ (ف۷۱) پھل رکھتا تھا (ف۷۲) تو اپنے ساتھی (ف۷۳) سے بولا اور وہ اس سے رد و بدل کرتا تھا (ف۷۴) میں تجھ سے مال میں زیادہ ہوں اور آدمیوں کا زیادہ زور رکھتا ہوں (ف۷۵)'),
 (93,18,35,'اپنے باغ میں گیا (ف۷۶) اور اپنی جان پر ظلم کرتا ہوا (ف۷۷) بولا مجھے گمان نہیں کہ یہ کبھی فنا ہو،'),
 (93,18,36,'اور میں گمان نہیں کرتا کہ قیامت قائم ہو اور اگر میں (ف۷۸) اپنے رب کی طرف پھر گیا بھی تو ضرور اس باغ سے بہتر پلٹنے کی جگہ پاؤں گا (ف۷۹)'),
 (93,18,37,'اس کے ساتھی (ف۸۰) نے اس سے اُلٹ پھیر کرتے ہوئے جواب دیا کیا تو اس کے ساتھ کفر کرتا ہے جس نے تجھے مٹی سے بنایا پھر نطفہ سے پھر تجھے ٹھیک مرد کیا (ف۸۱)'),
 (93,18,38,'لیکن میں تو یہی کہتا ہوں کہ وہ اللہ ہی میرا رب ہے او ر میں کسی کو اپنے رب کا شریک نہیں کرتا ہوں،'),
 (93,18,39,'اور کیوں نہ ہوا کہ جب تو اپنے باغ میں گیا تو کہا ہوتا جو چاہے اللہ، ہمیں کچھ زور نہیں مگر اللہ کی مدد کا (ف۸۲) اگر تو مجھے اپنے سے مال و اولاد میں کم دیکھتا تھا (ف۸۳)'),
 (93,18,40,'تو قریب ہے کہ میرا رب مجھے تیرے باغ سے اچھا دے (ف۸۴) اور تیرے باغ پر آسمان سے بجلیاں اتارے تو وہ پٹ پر میدان (سفید زمین) ہوکر رہ جائے (ف۸۵)'),
 (93,18,41,'یا اس کا پانی زمین میں دھنس جائے (ف۸۶) پھر تو اسے ہرگز تلاش نہ کرسکے (ف۸۷)'),
 (93,18,42,'اور اس کے پھل گھیر لیے گئے (ف۸۸) تو اپنے ہاتھ ملتا رہ گیا (ف۸۹) اس لاگت پر جو اس باغ میں خرچ کی تھی اور وہ اپنی ٹیٹوں پر (اوندھے منہ) گرا ہوا تھا (ف۹۰) اور کہہ رہا ہے، اے کاش! میں نے اپنے رب کا کسی کو شریک نہ کیا ہوتا،'),
 (93,18,43,'اور اس کے پاس کوئی جماعت نہ تھی کہ اللہ کے سامنے اس کی مدد کرتی نہ وہ بدلہ لینے کے قابل تھا (ف۹۱)'),
 (93,18,44,'یہاں کھلتا ہے (ف۹۲) کہ اختیار سچے اللہ کا ہے، اس کا ثواب سب سے بہتر اور اسے ماننے کا انجام سب سے بھلا،'),
 (93,18,45,'اور ان کے سامنے (ف۹۳) زندگانی دنیا کی کہاوت بیان کرو (ف۹۴) جیسے ایک پانی ہم نے آسمان اتارا تو اس کے سبب زمین کا سبزہ گھنا ہوکر نکلا (ف۹۵) کہ سوکھی گھاس ہوگیا جسے ہوائیں اڑائیں (ف۹۶) اور اللہ ہر چیز پر قابو والا ہے (ف۹۷)'),
 (93,18,46,'مال اور بیٹے یہ جیتی دنیا کا سنگھار ہے (ف۹۸) اور باقی رہنے والی اچھی باتیں (ف۹۹) ان کا ثواب تمہارے رب کے یہاں بہتر اور وہ امید میں سب سے بھلی،'),
 (93,18,47,'اور جس دن ہم پہاڑوں کو چلائیں گے (ف۱۰۰) اور تم زمین کو صاف کھلی ہوئی دیکھو گے (ف۱۰۱) اور ہم انہیں اٹھائیں گے (ف۱۰۲) تو ان میں سے کسی کو نہ چھوڑیں گے،'),
 (93,18,48,'اور سب تمہارے رب کے حضور پرا باندھے پیش ہوں گے (ف۱۰۳) بیشک تم ہمارے پاس ویسے ہی آئےجیسا ہم نے تمہیں پہلی بار بنایا تھا (ف۱۰۴) بلکہ تمہارا گمان تھا کہ ہم ہر گز تمہارے لیے کوئی وعدہ کا وقت نہ رکھیں گے، (ف۱۰۵)'),
 (93,18,49,'اور نامہٴ اعمال رکھا جائے گا (ف۱۰۶) تو تم مجرموں کو دیکھو گے کہ اس کے لکھے سے ڈرتے ہوں گے اور (ف۱۰۷) کہیں گے ہائے خرابی ہماری اس نوشتہ کو کیا ہوا نہ اس نے کوئی چھوٹا گناہ چھوڑا نہ بڑا جسے گھیر لیا ہو اور اپنا سب کیا انہوں نے سامنے پایا، اور تمہارا رب کسی پر ظلم نہیں کرتا (ف۱۰۸)'),
 (93,18,50,'اور یاد کرو جب ہم نے فرشتوں کو فرمایا کہ آدم کو سجدہ کرو (ف۱۰۹) تو سب نے سجدہ کیا سوا ابلیس کے، قومِ جن سے تھا تو اپنے رب کے حکم سے نکل گیا (ف۱۱۰) بھلا کیا اسے اور اس کی اولاد و میرے سوا دوست بناتے ہو (ف۱۱۱) اور وہ ہمارے دشمن ہیں ظالموں کو کیا ہی برا بدل (بدلہ) ملا، (ف۱۱۲)'),
 (93,18,51,'نہ میں نے آسمانوں اور زمین کو بناتے وقت انہیں سامنے بٹھالیا تھا، نہ خود ان کے بناتے وقت اور نہ میری شان، کہ گمراہ کرنے والوں کو بازوں بناؤں (ف۱۱۳)'),
 (93,18,52,'اور جس دن فرمائے گا (ف۱۱۴) کہ پکارو میرے شریکوں کو جو تم گمان کرتے تھے تو انہیں پکاریں گے وہ انہیں جواب نہ دیں گے اور ہم ان کے (ف۱۱۵) درمیان ایک ہلاکت کا میدان کردیں گے(ف۱۱۶)'),
 (93,18,53,'اور مجرم دوزخ کو دیکھیں گے تو یقین کریں گا کہ انہیں اس میں گرنا ہے اور اس سے پھرنے کی کوئی جگہ نہ پائیں گے،'),
 (93,18,54,'اور بیشک ہم نے لوگوں کے لیے اس قرآن میں ہر قسم کی مثل طرح طرح بیان فرمائی (ف۱۱۷) اور آدمی ہر چیز سے بڑھ کر جھگڑالو ہے (ف۱۱۸)'),
 (93,18,55,'اور آدمیوں کو کسی چیز نے اس سے روکا کہ ایمان لاتے جب ہدایت (ف۱۱۹) ان کے پاس آئی اور اپنے رب سے معافی مانگتے (ف۱۱۳) مگر یہ کہ ان پر اگلوں کا دستور آئے (ف۱۲۱) یا ان پر قسم قسم کا عذاب آئے،'),
 (93,18,56,'اور ہم رسولوں کو نہیں بھیجتے مگر (ف۱۲۲) خوشی (ف۱۲۳) ڈر سنانے والے اور جو کافر ہیں وہ باطل کے ساتھ جھگڑتے ہیں (ف۱۲۴) کہ اس سے حق کو ہٹادیں اور انہوں نے میری آیتوں کی اور جو ڈر انہیں سناتے گئے تھے، (ف۱۲۵)'),
 (93,18,57,'ان کی ہنسی بنالی اور اس سے بڑھ کر ظالم کون جسے اس کے رب کی آیتیں یاد دلائی جائیں تو وہ ان سے منہ پھیرلے (ف۱۲۶) اور اس کے ہاتھ جو آگے بھیج چکے (ف۱۲۷) اسے بھول جائے ہم نے ان کے دلوں پر غلاف کردیے ہیں کہ قرآن نہ سمجھیں اور ان کے کانوں میں گرانی (ف۱۲۸) اور اگر تم انہیں ہدایت کی طرف بلاؤ تو جب بھی ہرگز کبھی راہ نہ پائیں گے (ف۱۲۹)'),
 (93,18,58,'اور تمہارا رب بخشنے والا مہر وا لا ہے، اگر وہ انہیں (ف۱۳۰) ان کے کیے پر پکڑتا تو جلد ان پر عذاب بھیجتا (ف۱۳۱) بلکہ ان کے لیے ایک وعدہ کا وقت ہے (ف۱۳۲) جس کے سامنے کوئی پناہ نہ پائیں گے،'),
 (93,18,59,'اور یہ بستیاں ہم نے تباہ کردیں (ف۱۳۳) جب انہوں نے ظلم کیا (ف۱۳۴) اور ہم نے ان کی بربادی کا ایک وعدہ رکھا تھا،'),
 (93,18,60,'اور یاد کرو جب موسیٰ (ف۱۳۵) نے اپنے خادم سے کہا (ف۱۳۶) میں باز نہ رہوں گا جب تک وہاں نہ پہنچوں جہاں دو سمندر ملے ہیں (ف۱۳۷) یا قرنوں (مدتوں تک) چلا جاؤں (ف۱۳۸)'),
 (93,18,61,'پھر جب وہ دونوں ان دریاؤں کے ملنے کی جگہ پہنچے (ف۱۳۹) اپنی مچھلی بھول گئے اور اس نے سمندر میں اپنی راہ لی سرنگ بناتی،'),
 (93,18,62,'پھر جبب وہاں سے گزر گئے (ف۱۴۰) موسیٰ نے خادم سے کہا ہمارا صبح کا کھانا لاؤ بیشک ہمیں اپنے اس سفر میں بڑی مشقت کا سامنا ہوا، (ف۱۴۱)'),
 (93,18,63,'بولا بھلا دیکھئے تو جب ہم نے اس چٹان کے پاس جگہ لی تھی تو بیشک میں مچھلی کو بھول گیا، اور مجھے شیطان ہی نے بھلا دیا کہ میں اس کا مذکور کروں اور اس نے (ف۱۴۲) تو سمندر میں اپنی راہ لی، اچنبھا ہے،'),
 (93,18,64,'موسیٰ نے کہا یہی تو ہم چاہتے تھے (ف۱۴۳) تو پیچھے پلٹے اپنے قدموں کے نشان دیکھتے،'),
 (93,18,65,'تو ہمارے بندوں میں سے ایک بندہ پایا (ف۱۴۴) جسے ہم نے اپنے پاس سے رحمت دی (ف۱۴۵) اور اسے اپنا علم لدنی عطا کیا (ف۱۴۶)'),
 (93,18,66,'اس سے موسیٰ نے کہا کیا میں تمہارے ساتھ رہوں اس شرط پر کہ تم مجھے سکھادو گے نیک بات جو تمہیں تعلیم ہوئی (ف۱۴۷)'),
 (93,18,67,'کہا آپ میرے ساتھ ہرگز نہ ٹھہر سکیں گے (ف۱۴۸)'),
 (93,18,68,'اور اس بات پر کیونکر صبر کریں گے جسے آپ کا علم محیط نہیں (ف۱۴۹)'),
 (93,18,69,'کہا عنقریب اللہ چاہے تو تم مجھے صابر پاؤ گے اور میں تمہارے کسی حکم کے خلاف نہ کروں گا،'),
 (93,18,70,'کہا تو اگر آپ میرے ساتھ رہنے ہیں تو مجھ سے کسی بات کو نہ پوچھنا جب تک میں خود اس کا ذکر نہ کروں (ف۱۵۰)'),
 (93,18,71,'اب دونوں چلے یہاں تک کہ جب کشتی میں سوار ہوئے (ف۱۵۱) اس بندہ نے اسے چیر ڈالا (ف۱۵۲) موسیٰ نے کہا کیا تم نے اسے اس لیے چیرا کہ اس کے سواروں کو ڈبا دو بیشک یہ تم نے بری بات کی، (ف۱۵۳)'),
 (93,18,72,'کہا میں نہ کہتا تھا کہ آپ میرے ساتھ ہرگز نہ ٹھہر سکیں گے (ف۱۵۴)'),
 (93,18,73,'کہا مجھ سے میری بھول پر گرفت نہ کرو (ف۱۵۵) اور مجھ پر میرے کام میں مشکل نہ ڈالو،'),
 (93,18,74,'پھر دونوں چلے (ف۱۵۶) یہاں تک کہ جب ایک لڑکا ملا (ف۱۵۷) اس بندہ نے اسے قتل کردیا، موسیٰ نے کہا کیا تم نے ایک ستھری جان (ف۱۵۸) بے کسی جان کے بدلے قتل کردی، بیشک تم نے بہت بری بات کی،'),
 (93,18,75,'کہا (ف۱۵۹) میں نے آپ سے نہ کہا تھا کہ آپ ہرگز میرے ساتھ نہ ٹھہرسکیں گے (ف۱۶۰)'),
 (93,18,76,'کہا اس کے بعد میں تم سے کچھ پوچھوں تو پھر میرے ساتھ نہ رہنا، بیشک میری طرف سے تمہارا عذر پورا ہوچکا،'),
 (93,18,77,'پھر دونوں چلے یہاں تک کہ جب ایک گاؤں والوں کے پاس آئے (ف۱۶۱) ان دہقانوں سے کھانا مانگا انہوں نے انہیں دعوت دینی قبول نہ کی (ف۱۶۲) پھر دونوں نے اس گاؤں میں ایک دیوار پا ئی کہ گرا چاہتی ہے اس بندہ نے (ف۱۶۳) اسے سیدھا کردیا، موسیٰ نے کہا تم چاہتے تو اس پر کچھ مزدوری لے لیتے (ف۱۶۴)'),
 (93,18,78,'کہا یہ (ف۱۶۵) میری اور آپ کی جدائی ہے اب میں آپ کو ان باتوں کا پھیر (بھید) بتاؤں گا جن پر آپ سے صبر نہ ہوسکا (ف۱۶۶)'),
 (93,18,79,'وہ جو کشتی تھی وہ کچھ محتاجوں کی تھی (ف۱۶۷) کہ دریا میں کام کرتے تھے، تو میں نے چاہا کہ اسے عیب دار کردوں اور ان کے پیچھے ایک بادشاہ تھا (ف۱۶۸) کہ ہر ثابت کشتی زبردستی چھین لیتا (ف۱۶۹)'),
 (93,18,80,'اور وہ جو لڑکا تھا اس کے ماں باپ مسلمان تھے تو ہمیں ڈر ہوا کہ وہ ان کو سرکشی اور کفر پر چڑھاوے (ف۱۷۰)'),
 (93,18,81,'تو ہم نے چاہا کہ ان دونوں کا رب اس سے بہتر (ف۱۷۱) ستھرا اور اس سے زیادہ مہربانی میں قریب عطا کرے (ف۱۷۲)'),
 (93,18,82,'رہی وہ دیوار وہ شہر کے دو یتیم لڑکوں کی تھی (ف۱۷۳) اور اس کے نیچے ان کا خزانہ تھا (ف۱۷۴) اور ان کا باپ نیک آدمی تھا (ف۱۷۵) تو آپ کے رب نے چاہا کہ وہ دونوں اپنی جوانی کو پہنچیں (ف۱۷۶) اور اپنا خزانہ نکالیں، آپ کے رب کی رحمت سے اور یہ کچھ میں نے اپنے حکم سے نہ کیا (ف۱۷۷) یہ پھیر ہے ان باتوں کا جس پر آپ سے صبر نہ ہوسکا (ف۱۷۸)'),
 (93,18,83,'اور تم سے (ف۱۷۹) ذوالقرنین کو پوچھتے ہیں (ف۱۸۰) تم فرماؤ میں تمہیں اس کا مذکور پڑھ کر سناتا ہوں،'),
 (93,18,84,'بیشک ہم نے اسے زمین میں قابو دیا اور ہر چیز کا ایک سامان عطا فرمایا (ف۱۸۱)'),
 (93,18,85,'تو وہ ایک سامان کے پیچھے چلا (ف۱۸۲)'),
 (93,18,86,'یہاں تک کہ جب سورج ڈوبنے کی جگہ پہنچا اسے ایک سیاہ کیچڑ کے چشمے میں ڈوبتا پایا (ف۱۸۳) اور وہاں (ف۱۸۴) ایک قوم ملی (ف۱۸۵) ہم نے فرمایا اے ذوالقرنین یا تو تُو انہیں عذاب دے (ف۱۸۶) یا ان کے ساتھ بھلائی اختیار کرے (ف۱۸۷)'),
 (93,18,87,'عرض کی کہ وہ جس نے ظلم کیا (ف۱۸۸) اسے تو ہم عنقریب سزادیں گے (ف۱۸۹) پھر اپنے رب کی طرف پھیرا جائے گا (ف۱۹۰) وہ اسے بری مار دے گا،'),
 (93,18,88,'اور جو ایمان لایا اور نیک کام کیا تو اس کا بدلہ بھلائی ہے (ف۱۹۱) اور عنقریب ہم اسے آسان کام کہیں گے (ف۱۹۲)'),
 (93,18,89,'پھر ایک سامان کے پیچھے چلا (ف۱۹۳)'),
 (93,18,90,'یہاں تک کہ جب سورج نکلنے کی جگہ پہنچا، اسے ایسی قوم پر نکلتا پایا جن کے لیے ہم نے سورج سے کوئی آڑ نہیں رکھی (ف۱۹۴)'),
 (93,18,91,'بات یہی ہے، اور جو کچھ اس کے پاس تھا (ف۱۹۵) سب کو ہمارا علم محیط ہے (ف۱۹۶)'),
 (93,18,92,'پھر ایک ساما ن کے پیچھے چلا (ف۱۹۷)'),
 (93,18,93,'یہاں تک کہ جب دو پہاڑوں کے بیچ پہنچا ان سے ادھر کچھ ایسے لوگ پائے کہ کوئی بات سمجھتے معلوم نہ ہوتے تھے (ف۱۹۸)'),
 (93,18,94,'انھوں نے کہا، اے ذوالقرنین! بیشک یاجوج ماجوج (ف۱۹۹) زمین میں فساد مچاتے ہیں تو کیا ہم آپ کے لیے کچھ مال مقرر کردیں اس پر کہ آپ ہم میں اور ان میں ایک دیوار بنادیں (ف۲۰۰)'),
 (93,18,95,'کہا وہ جس پر مجھے میرے رب نے قابو دیا ہے بہتر ہے (ف۲۰۱) تو میری مدد طاقت سے کرو (ف۲۰۲) میں تم میں اور ان میں ایک مضبوط آڑ بنادوں (ف۲۰۳)'),
 (93,18,96,'میرے پاس لوہے کے تختے لاؤ (ف۲۰۴) یہاں تک کہ وہ جب دیوار دونوں پہاڑوں کے کناروں سے برابر کردی، کہا دھونکو، یہاں تک کہ جب اُسے آگ کردیا کہا لاؤ، میں اس پر گلا ہوا تانبہ اُنڈیل دوں،'),
 (93,18,97,'تو یاجوج و ماجوج اس پر نہ چڑھ سکے اور نہ اس میں سوراخ کرسکے،'),
 (93,18,98,'کہا (ف۲۰۵) یہ میرے رب کی رحمت ہے، پھر جب میرے رب کا وعدہ آئے گا (ف۲۰۶) اسے پاش پاش کردے گا اور میرے رب کا وعدہ سچا ہے (ف۲۰۷)'),
 (93,18,99,'اور اس دن ہم انہیں چھوڑ دیں گے کہ ان کا ایک گروہ دوسرے پر ریلا (سیلاب کی طرح) آوے گا اور صُور پھونکا جائے گا (ف۲۰۸) تو ہم سب کو (ف۲۰۹) اکٹھا کر لائیں گے'),
 (93,18,100,'اور ہم اس دن جہنم کافروں کے سامنے لائیں گے (ف۲۱۰)'),
 (93,18,101,'وہ جن کی آنکھوں پر میری یاد سے پردہ پڑا تھا (ف۲۱۱) اور حق بات سن نہ سکتے تھے (ف۲۱۲)'),
 (93,18,102,'تو کیا کافر یہ سمجھتے ہیں کہ میرے بندوں کو (ف۲۱۳) میرے سوا حمایتی بنالیں گے (ف۲۱۴) بیشک ہم نے کافروں کی مہمانی کو جہنم تیار کر رکھی ہے،'),
 (93,18,103,'تم فرماؤ کیا ہم تمہیں بتادیں کہ سب سے بڑھ کر ناقص عمل کن کے ہیں (ف۲۱۵)'),
 (93,18,104,'ان کے جن کی ساری کوشش دنیا کی زندگی میں گم گئی (ف۲۱۶) اور وہ اس خیال میں ہیں کہ اچھا کام کررہے ہیں،'),
 (93,18,105,'یہ لوگ جنہوں نے اپنے رب کی آیتیں اور اس کا ملنا نہ مانا (ف۲۱۷) تو ان کا کیا دھرا سب اکارت ہے تو ہم ان کے لیے قیامت کے دن کوئی تول نہ قائم کریں گے (ف۲۱۸)'),
 (93,18,106,'یہ ان کا بدلہ ہے جہنم، اس پر کہ انہوں نے کفر کیا اور میری آیتوں اور میرے رسولوں کی ہنسی بنائی،'),
 (93,18,107,'بیشک جو ایمان لائے اور اچھے کام کیے فردوس کے باغ ان کی مہمانی ہے (ف۲۱۹)'),
 (93,18,108,'وہ ہمیشہ ان ہی میں رہیں گے ان سے جگہ بدلنا نہ چاہیں گے (ف۲۲۰)'),
 (93,18,109,'تم فرمادو اگر سمندر میرے رب کی باتوں کے لیے، سیاہی ہو تو ضرور سمندر ختم ہوجائے گا اور میرے رب کی باتیں ختم نہ ہوں گی اگرچہ ہم ویسا ہی اور اس کی مدد کو لے آئیں (ف۲۲۱)'),
 (93,18,110,'تو فرماؤ ظاہر صورت بشری میں تو میں تم جیسا ہوں (ف۲۲۲) مجھے وحی آتی ہے کہ تمہارا معبود ایک ہی معبود ہے (ف۲۲۳) تو جسے اپنے رب سے ملنے کی امید ہو اسے چاہیے کہ نیک کام کرے اور اپنے رب کی بندگی میں کسی کو شریک نہ کرے (ف۲۲۴)'),
 (93,19,1,'کھیٰعص'),
 (93,19,2,'یہ مذکور ہے تیرے رب کی اس رحمت کا جو اس نے اپنے بندہ زکریا پر کی،'),
 (93,19,3,'جب اس نے اپنے رب کو آہستہ پکارا (ف۲)'),
 (93,19,4,'عرض کی اے میرے رب میری ہڈی کمزور ہوگئی (ف۳) اور سرے سے بڑھاپے کا بھبھوکا پھوٹا (شعلہ چمکا) (ف۴) اور اے میرے رب میں تجھے پکار کر کبھی نامراد نہ رہا (ف۵)'),
 (93,19,5,'اور مجھے اپنے بعد اپنے قرابت والوں کا ڈر ہے (ف۶) اور میری عورت بانجھ ہے تو مجھے اپنے پاس سے کوئی ایسا دے ڈال جو میرا کام اٹھائے (ف۷)'),
 (93,19,6,'وہ میرا جانشین ہو اور اولاد یعقوب کا وارث ہو، اور اے میرے رب! اسے پسندیدہ کر (ف۸)'),
 (93,19,7,'اے زکریا ہم تجھے خوشی سناتے ہیں ایک لڑکے کی جن کا نام یحییٰ ہے اس کے پہلے ہم نے اس نام کا کوئی نہ کیا،'),
 (93,19,8,'عرض کی اے میرے رب! میرے لڑکا کہاں سے ہوگا میری عورت تو بانجھ ہے اور میں بڑھاپے سے سوکھ جانے کی حالت کو پہنچ گیا (ف۹)'),
 (93,19,9,'فرمایا ایسا ہی ہے (ف۱۰) تیرے رب نے فرمایا وہ مجھے آسان ہے اور میں نے تو اس سے پہلے تجھے اس وقت بنایا جب تک کچھ بھی نہ تھا (ف۱۱)'),
 (93,19,10,'عرض کی اے میرے رب! مجھے کوئی نشانی دے دے (ف۱۲) فرمایا تیری نشانی یہ ہے کہ تو تین رات دن لوگوں سے کلام نہ کرے بھلا چنگا ہوکر (ف۱۳)'),
 (93,19,11,'تو اپنی قوم پر مسجد سے باہر آیا (ف۱۴) تو انہیں اشارہ سے کہا کہ صبح و شام تسبیح کرتے رہو،'),
 (93,19,12,'اے یحییٰ کتاب (ف۱۶) مضبوط تھام، اور ہم نے اسے بچپن ہی میں نبوت دی (ف۱۷)'),
 (93,19,13,'اور اپنی طرف سے مہربانی (ف۱۸) اور ستھرائی (ف۱۹) اور کمال ڈر والا تھا (ف۲۰)'),
 (93,19,14,'اور اپنے ماں باپ سے اچھا سلوک کرنے والا تھا زبردست و نافرمان نہ تھا (ف۲۱)'),
 (93,19,15,'اور سلامتی ہے اس پر جس دن پیدا ہوا اور جس دن مرے گا اورجس دن مردہ اٹھایا جائے گا (ف۲۲)'),
 (93,19,16,'اور کتاب میں مریم کو یاد کرو (ف۲۳) جب اپنے گھر والوں سے پورب کی طرف ایک جگہ الگ گئی (ف۲۴)'),
 (93,19,17,'تو ان سے ادھر (ف۲۵) ایک پردہ کرلیا، تو اس کی طرف ہم نے اپنا روحانی (روح الامین) بھیجا (ف۲۶) وہ اس کے سامنے ایک تندرست آدمی کے روپ میں ظاہر ہوا،'),
 (93,19,18,'بولی میں تجھ سے رحمان کی پناہ مانگتی ہوں اگر تجھے خدا کا ڈر ہے،'),
 (93,19,19,'بولا میں تیرے رب کا بھیجا ہوا ہوں، کہ میں تجھے ایک ستھرا بیٹا دوں،'),
 (93,19,20,'بولی میرے لڑکا کہاں سے ہوگا مجھے تو کسی آدمی نے ہاتھ نہ لگایا نہ میں بدکار ہوں،'),
 (93,19,21,'کہا یونہی ہے (ف۲۷) تیرے رب نے فرمایا ہے کہ یہ (ف۲۸) مجھے آسان ہے، اور اس لیے کہ ہم اسے لوگوں کے واسطے نشانی (ف۲۹) کریں اور اپنی طرف سے ایک رحمت (ف۳۰) اور یہ کام ٹھہرچکا ہے (ف۳۱)'),
 (93,19,22,'اب مریم نے اسے پیٹ میں لیا پھر اسے لیے ہوئے ایک دور جگہ چلی گئی (ف۳۲)'),
 (93,19,23,'پھر اسے جننے کا درد ایک کھجور کی جڑ میں لے آیا (ف۳۳) بولی ہائے کسی طرح میں اس سے پہلے مرگئی ہوتی اور بھولی بسری ہوجاتی،'),
 (93,19,24,'تو اسے (ف۳۴) اس کے تلے سے پکارا کہ غم نہ کھا (ف۳۵) بیشک تیرے رب نے نیچے ایک نہر بہادی ہے (ف۳۶)'),
 (93,19,25,'اور کھجور کی جڑ پکڑ کر اپنی طرف ہلا تجھ پر تازی پکی کھجوریں گریں گی (ف۳۷)'),
 (93,19,26,'تو کھا اور پی اور آنکھ ٹھنڈی رکھ (ف۳۸) پھر اگر تو کسی آدمی کو دیکھے (ف۳۹) تو کہہ دینا میں نے آج رحمان کا روزہ مانا ہے تو آج ہرگز کسی آدمی سے بات نہ کرو ں گی (ف۴۰)'),
 (93,19,27,'تو اسے گود میں لے اپنی قوم کے پاس آئی (ف۴۱) بولے اے مریم! بیشک تو نے بہت بری بات کی،'),
 (93,19,28,'اے ہارون کی بہن (ف۴۲) تیرا باپ (ف۴۳) برا آدمی نہ تھا اور نہ تیری ماں (ف۴۴) بدکار،'),
 (93,19,29,'اس پر مریم نے بچے کی طرف اشارہ کیا (ف۴۵) وہ بولے ہم کیسے بات کریں اس سے جو پالنے میں بچہ ہے (ف۴۶)'),
 (93,19,30,'بچہ نے فرمایا میں اللہ کا بندہ (ف۴۷) اس نے مجھے کتاب دی اور مجھے غیب کی خبریں بتانے والا (نبی) کیا (ف۴۸)'),
 (93,19,31,'اور اس نے مجھے مبارک کیا (ف۴۹) میں کہیں ہوں اور مجھے نماز و زکوٰة کی تاکید فرمائی جب تک جیوں،'),
 (93,19,32,'اور اپنی ماں سے اچھا سلوک کرنے والا (ف۵۰) اور مجھے زبردست بدبخت نہ کیا،'),
 (93,19,33,'اور وہی سلامتی مجھ پر (ف۵۱) جس دن میں پیدا ہوا اور جس دن مروں اور جس دن زندہ اٹھایا جاؤں (ف۵۲)'),
 (93,19,34,'یہ ہے عیسیٰ مریم کا بیٹا سچی بات جس میں شک کرتے ہیں (ف۵۳)'),
 (93,19,35,'اللہ کو لائق نہیں کہ کسی کو اپنا بچہ ٹھہرائے پاکی ہے اس کو (ف۵۴) جب کسی کام کا حکم فرماتا ہے تو یونہی کہ اس سے فرماتا ہے ہوجاؤ وہ فوراًٰ ہوجاتا ہے،'),
 (93,19,36,'اور عیسیٰ نے کہا بیشک اللہ رب ہے میرا اور تمہارا (ف۵۵) تو اس کی بندگی کرو، یہ راہ سیدھی ہے،'),
 (93,19,37,'پھر جماعتیں آپس میں مختلف ہوگئیں (ف۵۶) تو خرابی ہے، کافروں کے لیے ایک بڑے دن کی حاضری سے (ف۵۷)'),
 (93,19,38,'کتنا سنیں گے اور کتنا دیکھیں گے جس دن ہمارے پاس حاضر ہونگے (ف۵۸) مگر آج ظالم کھلی گمراہی میں ہیں (ف۵۹)'),
 (93,19,39,'اور انہیں ڈر سناؤ پچھتاوے کے دن کا (ف۶۰) جب کام ہوچکے گا (ف۶۱) اور وہ غفلت میں ہیں (ف۶۲) اور نہیں مانتے،'),
 (93,19,40,'بیشک زمین اور جو کچھ اس پر ہے سب کے وارث ہم ہوں گے (ف۶۳) اور وہ ہماری ہی طرف پھریں گے (ف۶۴)'),
 (93,19,41,'اور کتاب میں (ف۶۵) ابراہیم کو یاد کرو بیشک وہ صدیق (ف۶۶) تھا (نبی) غیب کی خبریں بتاتا،'),
 (93,19,42,'جب اپنے باپ سے بولا (ف۶۷) اے میرے باپ کیوں ایسے کو پوجتا ہے جو نہ سنے نہ دیکھے اور نہ کچھ تیرے کام آئے (ف۶۸)'),
 (93,19,43,'اے میرے باپ بیشک میرے پاس (ف۶۹) وہ علم آیا جو تجھے نہ آیا تو تُو میرے پیچھے چلا آ (ف۷۰) میں تجھے سیدھی راہ دکھاؤں (ف۷۱)'),
 (93,19,44,'اے میرے باپ شیطان کا بندہ نہ بن (ف۷۲) بیشک شیطان رحمان کا نافرمان ہے،'),
 (93,19,45,'اے میرے باپ میں ڈرتا ہوں کہ تجھے رحمن کا کوئی عذاب پہنچے تو تُو شیطان کا رفیق ہوجائے (ف۷۳)'),
 (93,19,46,'بولا کیا تو میرے خداؤں سے منہ پھیرتا ہے، اے ابراہیم بیشک اگر تو (ف۷۴) باز نہ آیا تو میں تجھے پتھراؤ کروں گا اور مجھ سے زمانہ دراز تک بے علاقہ ہوجا (ف۷۵)'),
 (93,19,47,'کہا بس تجھے سلام ہے (ف۷۶) قریب ہے کہ میں تیرے لیے اپنے رب سے معافی مانگوں گا (ف۷۷) بیشک وہ مجھ مہربان ہے،'),
 (93,19,48,'اور میں ایک کنارے ہوجاؤں گا (ف۷۸) تم سے اور ان سب سے جن کو اللہ کے سوا پوجتے ہو اور اپنے رب کو پوجوں گا (ف۷۹) قریب ہے کہ میں اپنے رب کی بندگی سے بدبخت نہ ہوں (ف۸۰)'),
 (93,19,49,'پھر جب ان سے اور اللہ کے سوا ان کے معبودوں سے کنارہ کر گیا (ف۸۱) ہم نے اسے اسحاق (ف۸۲) اور یعقوب (ف۸۳) عطا کیے، اور ہر ایک کو غیب کی خبریں بتانے والا کیا،'),
 (93,19,50,'اور ہم نے انہیں اپنی رحمت عطا کی (ف۸۴) اور ان کے لیے سچی بلند ناموری رکھی (ف۸۵)'),
 (93,19,51,'اور کتاب میں موسیٰ کو یاد کرو، بیشک وہ چنا ہوا تھا اور رسول تھا غیب کی خبریں بتانے والا،'),
 (93,19,52,'اور اسے ہم نے طور کی داہنی جانب سے ندا فرمائی (ف۸۶) اور اسے اپنا راز کہنے کو قریب کیا (ف۸۷)'),
 (93,19,53,'اور اپنی رحمت سے اس کا بھائی ہارون عطا کیا (غیب کی خبریں بتانے والا نبی) (ف۸۸)'),
 (93,19,54,'اور کتاب میں اسماعیل کو یاد کرو (ف۸۹) بیشک وہ وعدے کا سچا تھا (ف۹۰) اور رسول تھا غیب کی خبریں بتاتا،'),
 (93,19,55,'اور اپنے گھر والوں کو (ف۹۱) نماز اور زکوٰة کا حکم دیتا اور اپنے رب کو پسند تھا (ف۹۲)'),
 (93,19,56,'اور کتاب میں ادریس کو یاد کرو (ف۹۳) بیشک وہ صدیق تھا غیب کی خبریں دیتا،'),
 (93,19,57,'اور ہم نے اسے بلند مکان پر اٹھالیا (ف۹۴)'),
 (93,19,58,'یہ ہیں جن پر ا لله نے احسان کیا غیب کی خبریں بتانے میں سے آدم کی اولاد سے (ف۹۵) اور ان میں جن کو ہم نے نوح کے ساتھ سوار کیا تھا (ف۹۶) اور ابراہیم (ف۹۷) اور یعقوب کی اولاد سے (ف۹۸) اور ان میں سے جنہیں ہم نے راہ دکھائی اور چن لیا (ف۹۹) جب ان پر رحمن کی آیتیں پڑھی جاتیں گر پڑتے سجدہ کرتے اور روتے (ف۱۰۰) (السجدة) ۵'),
 (93,19,59,'تو ان کے بعد ان کی جگہ وہ ناخلف آئے (ف۱۰۱) جنہوں نے نمازیں گنوائیں اور اپنی خواہشوں کے پیچھے ہوئے (ف۱۰۲) تو عنقریب وہ دوزخ میں غی کا جنگل پائیں گے (ف۱۰۳)'),
 (93,19,60,'مگر جو تائب ہوئے اور ایمان لائے اور اچھے کام کیے تو یہ لوگ جنت میں جائیں گے اور انہیں کچھ نقصان نہ دیا جائے گا (ف۱۰۴)'),
 (93,19,61,'بسنے کے باغ جن کا وعدہ رحمن نے اپنے (ف۱۰۵) بندوں سے غیب میں کیا (ف۱۰۶) بیشک اس کا وعدہ آنے والا ہے،'),
 (93,19,62,'وہ اس میں کوئی بیکار بات نہ سنیں گے مگر سلام (ف۱۰۷) اور انہیں اس میں ان کا رزق ہے صبح و شام (ف۱۰۸)'),
 (93,19,63,'یہ وہ باغ ہے جس کا وارث ہم اپنے بندوں میں سے اسے کریں گے جو پرہیزگار ہے،'),
 (93,19,64,'(اور جبریل نے محبوب سے عرض کی (ٖف ۱۰۹) ہم فرشتے نہیں اترتے مگر حضور کے رب کے حکم سے اسی کا ہے جو ہمارے آگے ہے اور جو ہمارے پیچھے اور جو اس کے درمیان ہے (ف۱۱۰) اور حضور کا رب بھولنے والا نہیں (ف۱۱۱)'),
 (93,19,65,'آسمانوں اور زمین اور جو کچھ ان کے بیچ میں ہے سب کا مالک تو اے پوجو اور اس کی بندگی پر ثابت رہو، کیا اس کے نام کا دوسرا جانتے ہو (ف۱۱۲)'),
 (93,19,66,'اور آدمی کہتا ہے کیا جب میں مرجاؤں گا تو ضرور عنقریب جِلا کر نکالا جاؤں گا (ف۱۱۳)'),
 (93,19,67,'اور کیا آدمی کو یاد نہیں کہ ہم نے اس سے پہلے اسے بنایا اور وہ کچھ نہ تھا (ف۱۱۴)'),
 (93,19,68,'تو تمہارے رب کی قسم ہم انہیں (ف۱۱۵) اور شیطانوں سب کو گھیر لائیں گے (ف۱۱۶) اور انہیں دوزخ کے آس پاس حاضر کریں گے گھٹنوں کے بل گرے،'),
 (93,19,69,'پھر ہم (ف۱۱۷) ہر گروہ سے نکالیں گے جو ان میں رحمن پر سب سے زیادہ بے باک ہوگا (ف۱۱۸)'),
 (93,19,70,'پھر ہم خوب جانتے ہیں جو اس آگ میں بھوننے کے زیادہ لائق ہیں،'),
 (93,19,71,'اور تم میں کوئی ایسا نہیں جس کا گزر دوزخ پر نہ ہو (ف۱۱۹) تمہارے رب کے ذمہ پر یہ ضرور ٹھہری ہوئی بات ہے (ف۱۲۰)'),
 (93,19,72,'پھر ہم ڈر والوں کو بچالیں گے (ف۱۲۱) اور ظالموں کو اس میں چھوڑ دیں گے گھٹنوں کے بل گرے،'),
 (93,19,73,'اور جب ان پر ہماری روشن آیتیں پڑھی جاتی ہیں (ف۱۲۲) کافر مسلمانوں سے کہتے ہیں کون سے گروہ کا مکان اچھا اورمجلس بہتر ہے (ف۱۲۳)'),
 (93,19,74,'اور ہم نے ان سے پہلے کتنی سنگتیں کھپادیں (قومیں ہلاک کردیں) (ف۱۲۴) کہ وہ ان سے بھی سامان اور نمود میں بہتر تھے،'),
 (93,19,75,'تم فرماؤ جو گمراہی میں ہو تو اسے رحمن خوب ڈھیل دے (ف۱۲۵) یہاں تک کہ جب وہ دیکھیں وہ چیز جس کا انہیں وعدہ دیا جاتا ہے یا تو عذاب (ف۱۲۶) یا قیامت (ف۱۲۷) تو اب جان لیں گے کہ کس کا برا درجہ ہے اور کس کی فوج کمزور (ف۱۲۸)'),
 (93,19,76,'او رجنہوں نے ہدایت پائی (ف۱۲۹) اللہ انھیں اور ہدایت بڑھائے گا (ف۱۳۰) اور باقی رہنے والی نیک باتوں کا (ف۱۳۱) تیرے رب کے یہاں سب سے بہتر ثواب اور سب سے بھلا انجام (ف۱۳۲)'),
 (93,19,77,'تو کیا تم نے اسے دیکھا جو ہماری آیتوں سے منکر ہوا اور کہتا ہے مجھے ضرو ر مال و اولاد ملیں گے (ف۱۳۳)'),
 (93,19,78,'کیا غیب کو جھانک آیا ہے (ف۱۳۴) یا رحمن کے پاس کوئی قرار رکھا ہے،'),
 (93,19,79,'ہرگز نہیں (ف۱۳۵) اب ہم لکھ رکھیں گے جو وہ کہتا ہے اور اسے خوب لمبا عذاب دیں گے،'),
 (93,19,80,'اور جو چیزیں کہہ رہا ہے (ف۱۳۶) ان کے ہمیں وارث ہوں گے اور ہمارے پاس اکیلا آئے گا (ف۱۳۷)'),
 (93,19,81,'اور اللہ کے سوا اور خدا بنالیے (ف۱۳۸) کہ وہ انہیں زور دیں (ف۱۳۹)'),
 (93,19,82,'ہرگز نہیں (ف۱۴۰) کوئی دم جاتا ہے کہ وہ (ف۱۴۱) ان کی بندگی سے منکر ہوں گے اور ان کے مخالفت ہوجائیں گے (ف۱۴۲)'),
 (93,19,83,'کیا تم نے نہ دیکھا کہ ہم نے کافروں پر شیطان بھیجے (ف۱۴۳) کہ وہ انہیں خوب اچھالتے ہیں (ف۱۴۴)'),
 (93,19,84,'تو تم ان پر جلدی نہ کرو، ہم تو ان کی گنتی پوری کرتے ہیں (ف۱۴۵)'),
 (93,19,85,'جس دن ہم پرہیزگاروں کو رحمن کی طرف لے جائیں گے مہمان بناکر (ف۱۴۶)'),
 (93,19,86,'اور مجرموں کو جہنم کی طرف ہانکیں گے پیاسے (ف۱۴۷)'),
 (93,19,87,'لوگ شفاعت کے مالک نہیں مگر وہی جنہوں نے رحمن کے پاس قرار رکھا ہے (ف۱۴۸)'),
 (93,19,88,'اور کافر بولے (ف۱۴۹) رحمن نے اولاد اختیار کی،'),
 (93,19,89,'بیشک تم حد کی بھاری بات لائے (ف۱۵۰)'),
 (93,19,90,'قریب ہے کہ آسمان اس سے پھٹ پڑیں اور زمین شق ہوجائے اور پہاڑ گر جائیں ڈھ کر (مسمار ہوکر) (ف۱۵۱)'),
 (93,19,91,'اس پر کہ انہوں نے رحمن کے لیے اولاد بتائی،'),
 (93,19,92,'اور رحمن کے لائق نہیں کہ اولاد اختیار کرے (ف۱۵۲)'),
 (93,19,93,'آسمانوں اور زمین میں جتنے ہیں سب اس کے حضور بندے ہو کر حاضر ہوں گے، (ف۱۵۳)'),
 (93,19,94,'بیشک وہ ان کا شمار جانتا ہے اور ان کو ایک ایک کرکے گن رکھا ہے (ف۱۵۴)'),
 (93,19,95,'اور ان میں ہر ایک روز قیامت اس کے حضور اکیلا حاضر ہوگا (ف۱۵۵)'),
 (93,19,96,'بیشک وہ جو ایمان لائے اور اچھے کام کیے عنقریب ان کے لیے رحمن محبت کردے گا (ف۱۵۶)'),
 (93,19,97,'تو ہم نے یہ قرآن تمہاری زبان میں یونہی آسان فرمایا کہ تم اس سے ڈر والوں کو خوشخبری دو اور جھگڑالو لوگوں کو اس سے ڈر سناؤ،'),
 (93,19,98,'اور ہم نے ان سے پہلے کتنی سنگتیں کھپائیں (قومیں ہلاک کیں) (ف۱۵۷) کیا تم ان میں کسی کو دیکھتے ہو یا ان کی بھنک (ذرا بھی آواز) سنتے ہو (ف۱۵۸)'),
 (93,20,1,'طٰهٰ'),
 (93,20,2,'اے محبوب! ہم نے تم پر یہ قرآن اس لیے نہ اتارا کہ مشقت میں پڑو (ف۲)'),
 (93,20,3,'ہاں اس کو نصیحت جو ڈر رکھتا ہو (ف۳)'),
 (93,20,4,'اس کا اتارا ہوا جس نے زمین اور اونچے آسمان بنائے،'),
 (93,20,5,'وہ بڑی مہر والا، اس نے عرش پر استواء فرمایا جیسا اس کی شان کے لائق ہے،'),
 (93,20,6,'اس کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں اور جو کچھ ان کے بیچ میں اور جو کچھ اس گیلی مٹی کے نیچے ہے (ف۴)'),
 (93,20,7,'اور اگر تو بات پکار کر کہے تو وہ تو بھید کو جانتا ہے اور اسے جو اس سے بھی زیادہ چھپا ہے (ف۵)'),
 (93,20,8,'اللہ کہ اس کے سوا کسی کی بندگی نہیں، اسی کے ہیں سب اچھے نام (ف۶)'),
 (93,20,9,'اور کچھ تمہیں موسیٰ کی خبر آئی (ف۷)'),
 (93,20,10,'جب اس نے ایک آگ دیکھی تو اپنی بی بی سے کہا ٹھہرو مجھے ایک آگ نظر پڑی ہے شاید میں تمہارے لیے اس میں سے کوئی چنگاری لاؤں یا آ گ پر راستہ پاؤں،'),
 (93,20,11,'پھر جب آگ کے پاس آیا (ف۸) ندا فرمائی گئی کہ اے موسیٰ،'),
 (93,20,12,'بیشک میں تیرا رب ہوں تو تو اپنے جوتے اتار ڈال (ف۹) بیشک تو پاک جنگل طویٰ میں ہے (ف۱۰)'),
 (93,20,13,'اور میں نے تجھے پسند کیا (ف۱۱) اب کان لگا کر سن جو تجھے وحی ہوتی ہے،'),
 (93,20,14,'بیشک میں ہی ہوں اللہ کہ میرے سوا کوئی معبود نہیں تو میری بندگی کر اور میری یاد کے لیے نماز قائم رکھ (ف۱۲)'),
 (93,20,15,'بیشک قیامت آنے والی ہے قریب تھا کہ میں اسے سب سے چھپاؤں (ف۱۳) کہ ہر جان اپنی کوشش کا بدلہ پائے (ف۱۴)'),
 (93,20,16,'تو ہرگز تجھے (ف۱۵) اس کے ماننے سے وہ باز نہ رکھے جو اس پر ایمان نہیں لاتا اور اپنی خواہش کےم پیچھے چلا (ف۱۶) پھر تو ہلاک ہوجائے،'),
 (93,20,17,'اور یہ تیرے داہنے ہاتھ میں کیا ہے اے موسیٰ (ف۱۷)'),
 (93,20,18,'عرض کی یہ میرا عصا ہے (ف۱۸) میں اس پر تکیہ لگاتا ہوں اور اس سے اپنی بکریوں پر پتے جھاڑتا ہوں اور میرے اس میں اور کام ہیں (ف۱۹)'),
 (93,20,19,'فرمایا اسے ڈال دے اے موسیٰ،'),
 (93,20,20,'تو موسیٰ نے ڈال دیا تو جبھی وہ دوڑتا ہوا سانپ ہوگیا (ف۲۰)'),
 (93,20,21,'فرمایا اسے اٹھالے اور ڈر نہیں، اب ہم اسے پھر پہلی طرح کردیں گے (ف۲۱)'),
 (93,20,22,'اور اپنا ہاتھ اپنے بازو سے ملا (ف۲۲) خوب سپید نکلے گا بے کسی مرض کے (ف۲۳) ایک اور نشانی (ف۲۴)'),
 (93,20,23,'کہ ہم تجھے اپنی بڑی بڑی نشانیاں دکھائیں،'),
 (93,20,24,'فرعون کے پاس جا (ف۲۵) اس نے سر اٹھایا (ف۲۶)'),
 (93,20,25,'عرض کی اے میرے رب میرے لیے میرا سینہ کھول دے (ف۲۷)'),
 (93,20,26,'اور میرے لیے میرا کام آسان کر،'),
 (93,20,27,'اور میری زبان کی گرہ کھول دے، (ف۲۸)'),
 (93,20,28,'کہ وہ میری بات سمجھیں،'),
 (93,20,29,'اور میرے لیے میرے گھر والوں میں سے ایک وزیر کردے، (ف۲۹)'),
 (93,20,30,'وہ کون میرا بھائی ہارون،'),
 (93,20,31,'اس سے میری کمر مضبوط کر،'),
 (93,20,32,'اور اسے میرے کام میں شریک کر (ف۳۰)'),
 (93,20,33,'کہ ہم بکثرت تیری پاکی بولیں،'),
 (93,20,34,'اور بکثرت تیری یاد کریں (ف۳۱)'),
 (93,20,35,'بیشک تو ہمیں دیکھ رہا ہے (ف۳۲)'),
 (93,20,36,'فرمایا اے موسیٰ تیری مانگ تجھے عطا ہوئی،'),
 (93,20,37,'اور بیشک ہم نے (ف۳۳) تجھ پر ایک بار اور احسان فرمایا'),
 (93,20,38,'جب ہم نے تیری ماں کو الہام کیا جو الہام کرنا تھا (ف۳۴)'),
 (93,20,39,'کہ اس بچے کو صندوق میں رکھ کر دریا میں (ف۳۵) ڈال دے، و دریا اسے کنارے پر ڈالے کہ اسے وہ اٹھالے جو میرا دشمن اور اس کا دشمن (ف۳۶) اور میں نے تجھ پر اپنی طرف کی محبت ڈالی (ف۳۷) اور اس لیے کہ تو میری نگاہ کے سامنے تیار ہو (ف۳۸)'),
 (93,20,40,'تیری بہن چلی (ف۳۹) پھر کہا کیا میں تمہیں وہ لوگ بتادوں جو اس بچہ کی پرورش کریں (ف۴۰) تو ہم تجھے تیری ماں کے پاس پھیر لائے کہ اس کی آنکھ (ف۴۱) ٹھنڈی ہو اور غم نہ کرے (ف۴۲) اور تو نے ایک جان کو قتل کیا (ف۴۳) تو ہم نے تجھے غم سے نجات دی اور تجھے خوب جانچ لیا (ف۴۴) تُو تو کئی برس مدین والوں میں رہا (ف۴۵) پھر تو ایک ٹھہرائے وعدہ پر حاضر ہوا اے موسیٰ! (ف۴۶)'),
 (93,20,41,'اور میں نے تجھے خاص اپنے لیے بنایا (ف۴۷)'),
 (93,20,42,'تو اور تیرا بھائی دونوں میری نشانیاں (ف۴۸) لے کر جاؤ اور میری یاد میں سستی نہ کرنا،'),
 (93,20,43,'دونوں فرعون کے پاس جاؤ بیشک اس نے سر اٹھایا،'),
 (93,20,44,'تو اس سے نرم بات کہنا (ف۴۹) اس امید پر کہ وہ دھیان کرے یا کچھ ڈرے (ف۵۰)'),
 (93,20,45,'دونوں نے عرض کیا، اے ہمارے رب! بیشک ہم ڈرتے ہیں کہ وہ ہم پر زیادتی کرے یا شرارت سے پیش آئے،'),
 (93,20,46,'فرمایا ڈرو نہیں میں تمہارے ساتھ ہوں (ف۵۱) سنتا اور دیکھتا (ف۵۲)'),
 (93,20,47,'تو اس کے پاس جاؤ اور اس سے کہو کہ ہم تیرے رب کے بھیجے ہوئے ہیں تو اولاد یعقوب کو ہمارے ساتھ چھوڑ دے (ف۵۳) اور انہیں تکلیف نہ دے (ف۵۴) بیشک ہم تیرے رب کی طرف سے نشانی لائے ہیں (ف۵۵) اور سلامتی اسے جو ہدایت کی پیروی کرے (ف۵۶)'),
 (93,20,48,'بیشک ہماری طرف وحی ہوتی ہے کہ عذاب اس پر ہے جو جھٹلائے (ف۵۷) اور منہ پھیرے (ف۵۸)'),
 (93,20,49,'بولا تو تم دونوں کا خدا کون ہے اے موسیٰ،'),
 (93,20,50,'کہا ہمارا رب وہ ہے جس نے ہر چیز کو اس کے لائق صورت دی (ف۵۹) پھر راہ دکھائی (ف۶۰)'),
 (93,20,51,'بولا (ف۶۱) اگلی سنگتوں (قوموں) کا کیا حال ہے (ف۶۲)'),
 (93,20,52,'کہا ان کا علم میرے رب کے پاس ایک کتاب میں ہے (ف۶۳) میرا رب نہ بہکے نہ بھولے،'),
 (93,20,53,'وہ جس نے تمہارے لیے زمین کو بچھونا کیا اور تمہارے لیے اس میں چلتی راہیں رکھیں اور آسمان سے پانی اتارا (ف۶۴) تو ہم نے اس سے طرح طرح کے سبزے کے جوڑے نکالے (ف۶۵)'),
 (93,20,54,'تم کھاؤ اور اپنے مویشیوں کو چَراؤ (ف۶۶) بیشک اس میں نشانیاں ہیں عقل والوں کو،'),
 (93,20,55,'ہم نے زمین ہی سے تمہیں بنایا (ف۲۷) اور اسی میں تمہیں پھر لے جائیں گے (ف۶۸) اور اسی سے تمہیں دوبارہ نکالیں گے (ف۶۹)'),
 (93,20,56,'اور بیشک ہم نے اسے (ف۷۰) اپنی سب نشانیاں (ف۷۱) دکھائیں تو اس نے جھٹلایا اور نہ مانا (ف۷۲)'),
 (93,20,57,'بولا کیا تم ہمارے پاس اس لیے آئے ہو کہ ہمیں اپنے جادو کے سبب ہماری زمین سے نکال دو اے موسیٰ (ف۷۳)'),
 (93,20,58,'تو ضرور ہم بھی تمہارے آگے ویسا ہی جادو لائیں گے (ف۷۴) تو ہم میں اور اپنے میں ایک وعدہ ٹھہرادو جس سے نہ ہم بدلہ لیں نہ تم ہموار جگہ ہو،'),
 (93,20,59,'موسیٰ نے کہا تمہارا وعدہ میلے کا دن ہے (ف۷۵) اور یہ کہ لوگ دن چڑھے جمع کیے جائیں (ف۷۶)'),
 (93,20,60,'تو فرعون پھرا اور اپنے داؤں (فریب) اکٹھے کیے (ف۷۷) پھر آیا (ف۷۸)'),
 (93,20,61,'ان سے موسیٰ نے کہا تمہیں خرابی ہو اللہ پر جھوٹ نہ باندھو (ف۷۹) کہ وہ تمہیں عذاب سے ہلاک کردے اور بیشک نامراد رہا جس نے جھوٹ باندھا (ف۸۰)'),
 (93,20,62,'تو اپنے معاملہ میں باہم مختلف ہوگئے (ف۸۱) اور چھپ کر مشاورت کی،'),
 (93,20,63,'بولے بیشک یہ دونوں (ف۸۲) ضرور جادوگر ہیں چاہتے ہیں کہ تمہیں تمہاری زمین زمین سے اپنے جادو کے زور سے نکال دیں اور تمہارا اچھا دین لے جائیں،'),
 (93,20,64,'تو اپنا داؤ (فریب) پکا کرلو پھر پرا باندھ (صف باندھ) کر آ ؤ آج مراد کو پہنچا جو غالب رہا،'),
 (93,20,65,'بولے (ف۸۳) اے موسیٰ یا تو تم ڈالو (ف۸۴) یا ہم پہلے ڈالیں (ف۸۵)'),
 (93,20,66,'موسیٰ نے کہا بلکہ تمہیں ڈالو (ف۸۶) جبھی ان کی رسیاں اور لاٹھیاں ان کے جادو کے زور سے ان کے خیال میں دوڑتی معلوم ہوئیں (ف۸۷)'),
 (93,20,67,'تو اپنے جی میں موسیٰ نے خوف پایا،'),
 (93,20,68,'ہم نے فرمایا ڈر نہیں بیشک تو ہی غالب ہے،'),
 (93,20,69,'اور ڈال تو دے جو تیرے داہنے ہاتھ میں ہے (ف۸۸) اور ان کی بناوٹوں کو نگل جائے گا، وہ جو بناکر لائے ہیں وہ تو جادوگر کا فریب ہے، اور جادوگر کا بھلا نہیں ہوتا کہیں آوے (ف۸۹)'),
 (93,20,70,'تو سب جادوگر سجدے میں گرالیے گئے بولے ہم اس پر ایمان لائے جو ہارون اور موسیٰ کا رب ہے (ف۹۰)'),
 (93,20,71,'فرعون بولا کیا تم اس پر ایمان لائے قبل اس کے کہ میں تمہیں اجازت دوں، بیشک وہ تمہارا بڑا ہے جس نے تم سب کو جادو سکھایا (ف۹۱) تو مجھے قسم ہے ضرور میں تمہارے ایک طرف کے ہاتھ اور دوسری طرف کے پاؤں کاٹوں گا (ف۹۲) اور تمہیں کھجور کے ڈھنڈ (تنے) پر سُولی چڑھاؤں گا، اور ضرور تم جان جاؤ گے کہ ہم میں کس کا عذاب سخت اور دیرپا ہے (ف۹۳)'),
 (93,20,72,'بولے ہم ہرگز تجھے ترجیح نہ دیں گے ان روشن دلیلوں پر جو ہمارے پاس آئیں (ف۹۴) ہمیں اپنے پیدا کرنے والے والے کی قسم تو تُو کر چُک جو تجھے کرنا ہے (ف۹۵) تو اس دنیا ہی کی زندگی میں تو کرے گا (ف۹۶)'),
 (93,20,73,'بیشک ہم اپنے رب پر ایمان لائے کہ وہ ہماری خطائیں بخش دے اور وہ جو تو نے ہمیں مجبور کیا جادو پر (ف۹۷) اور ا لله بہتر ہے (ف۹۸) اور سب سے زیادہ باقی رہنے والا (ف۹۹)'),
 (93,20,74,'بیشک جو اپنے رب کے حضور مجرم (ف۱۰۰) ہوکر آئے تو ضرور اس کے لیے جہنم ہے جس میں نہ مرے (ف۱۰۱) نہ جئے (ف۱۰۲)'),
 (93,20,75,'اور جو اس کے حضور ایمان کے ساتھ آئے کہ اچھے کام کیے ہوں (ف۱۰۳) تو انہیں کے درجے اونچے،'),
 (93,20,76,'بسنے کے باغ جن کے نیچے نہریں بہیں ہمیشہ ان میں رہیں، اور یہ صلہ ہے اس کا جو پاک ہوا (ف۱۰۴)'),
 (93,20,77,'اور بیشک ہم نے موسیٰ کو وحی کی (ف۱۰۵) کہ راتوں رات میرے بندوں کو لے چل (ف۱۰۶) اور ان کے لیے دریا میں سوکھا راستہ نکال دے (ف۱۰۷) تجھے ڈر نہ ہوگا کہ فرعون آلے اور نہ خطرہ (ف۱۰۸)'),
 (93,20,78,'تو ان کے پیچھے فرعون پڑا اپنے لشکر لے کر (ف۱۰۹) تو انہیں دریا نے ڈھانپ لیا جیسا ڈھانپ لیا، (ف۱۱۰)'),
 (93,20,79,'اور فرعون نے اپنی قوم کو گمراہ کیا اور راہ نہ دکھائی (ف۱۱۱)'),
 (93,20,80,'اے بنی اسرائیل بیشک ہم نے تم کو تمہارے دشمن (ف۱۱۲) سے نجات دی اور تمہیں طور کی داہنی طرف کا وعدہ دیا (ف۱۱۳) اور تم پر من اور سلوی ٰ اتارا (ف۱۱۴)'),
 (93,20,81,'کھاؤ جو پاک چیزیں ہم نے تمہیں روزی دیں اور اس میں زیادتی نہ کرو (ف۱۱۵) کہ تم پر میرا غضب اترے اور جس پر میرا غضب اترا بیشک وہ گرا (ف۱۱۶)'),
 (93,20,82,'اور بیشک میں بہت بخشنے والا ہوں اسے جس نے توبہ کی (ف۱۱۷) اور ایمان لایا اور اچھا کام کیا پھر ہدایت پر رہا (ف۱۱۸)'),
 (93,20,83,'اور تو نے اپنی قوم سے کیوں جلدی کی اے موسیٰ (ف۱۱۹)'),
 (93,20,84,'عرض کی کہ وہ یہ ہیں میرے پیچھے اور اے میرے رب تیری طرف میں جلدی کرکے حاضر ہوا کہ تو راضی ہو، (ف۱۲۰)'),
 (93,20,85,'فرمایا، تو ہم نے تیرے آنے کے بعد تیری قوم (ف۱۲۱) بلا میں ڈالا اور انہیں سامری نے گمراہ کردیا، (ف۱۲۲)'),
 (93,20,86,'تو موسیٰ اپنی قوم کی طرف پلٹا (ف۱۲۳) غصہ میں بھرا افسوس کرتا (ف۱۲۴) کہا اے میری قوم کیا تم سے تمہارے رب نے اچھا وعدہ نہ تھا (ف۱۲۵) کیا تم پر مدت لمبی گزری یا تم نے چاہا کہ تم پر تمہارے رب کا غضب اترے تو تم نے میرا وعدہ خلاف کیا (ف۱۲۶)'),
 (93,20,87,'بولے ہم نے آپ کا وعدہ اپنے اختیار سے خلاف نہ کیا لیکن ہم سے کچھ بوجھ اٹھوائے گئے اس قوم کے گہنے کے (ف۱۲۷) تو ہم نے انہیں (ف۱۲۸) ڈال دیا پھر اسی طرح سامری نے ڈالا (ف۱۲۹)'),
 (93,20,88,'تو اس نے ان کے لیے ایک بچھڑا نکالا بے جان کا دھڑ گائے کی طرح بولتا (ف۱۳۰) یہ ہے تمہارا معبود اور موسیٰ کا معبود تو بھول گئے (ف۱۳۲)'),
 (93,20,89,'تو کیا نہیں دیکھتے کہ وہ (ف۱۳۳) انہیں کسی بات کا جواب نہیں دیتا اور ان کے سوا کسی برے بھلے کا اختیار نہیں رکھتا (ف۱۳۴)'),
 (93,20,90,'اور بیشک ان سے ہارون نے اس سے پہلے کہا تھا کہ اے میری قوم یونہی ہے کہ تم اس کے سبب فتنے میں پڑے (ف۱۳۵) اور بیشک تمہارا رب رحمن ہے تو میری پیروی کرو اور میرا حکم مانو،'),
 (93,20,91,'بولے ہم تو اس پر آسن مارے جمے (پوجا کے لیے بیٹھے) رہیں گے (ف۱۳۶) جب تک ہمارے پاس موسیٰ لوٹ کے آئیں (ف۱۳۷)'),
 (93,20,92,'موسیٰ نے کہا، اے ہارون! تمہیں کس بات نے روکا تھا جب تم نے انہیں گمراہ ہوتے دیکھا تھا کہ میرے پیچھے آتے (ف۱۳۸)'),
 (93,20,93,'تو کیا تم نے میرا حکم نہ مانا،'),
 (93,20,94,'کہا اے میرے ماں جائے! نہ میری ڈاڑھی پکڑو اور نہ میرے سر کے بال مجھے یہ ڈر ہوا کہ تم کہو گے تم نے بنی اسرائیل میں تفرقہ ڈال دیا اور تم نے میری بات کا انتظار نہ کیا (ف۱۳۹)'),
 (93,20,95,'موسیٰ نے کہا اب تیرا کیا حال ہے اے سامری! (ف۱۴۰)'),
 (93,20,96,'بولا میں نے وہ دیکھا جو لوگوں نے نہ دیکھا (ف۱۴۱) تو ایک مٹھی بھر لی فرشتے کے نشان سے پھر اسے ڈال دیا (ف۱۴۲) اور میرے جی کو یہی بھلا لگا (ف۱۴۳)'),
 (93,20,97,'کہا تو چلتا بن (ف۱۴۴) کہ دنیا کی زندگی میں تیری سزا یہ ہے کہ (ف۱۴۵) تو کہے چھو نہ جا (ف۱۴۶) اور بیشک تیرے لیے ایک وعدہ کا وقت ہے (ف۱۴۷) جو تجھ سے خلاف نہ ہوگا اور اپنے اس معبود کو دیکھ جس کے سامنے تو دن بھر آسن مارے (پوجا کے لیے بیٹھا) رہا (ف۱۴۸) قسم ہے ہم ضرور اسے جلائیں گے پھر ریزہ ریزہ کرکے دریا میں بہائیں گے (ف۱۴۹)'),
 (93,20,98,'تمہارا معبود تو وہی اللہ ہے جس کے سوا کسی کی بندگی نہیں ہر چیز کو اس کا علم محیط ہے،'),
 (93,20,99,'ہم ایسا ہی تمہارے سامنے اگلی خبریں بیان فرماتے ہیں اور ہم نے تم کو اپنے پاس سے ایک ذکر عطا فرمایا (ف۱۵۰)'),
 (93,20,100,'جو اس سے منہ پھیرے (ف۱۵۱) تو بیشک وہ قیامت کے دن ایک بوجھ اٹھائے گا (ف۱۵۲)'),
 (93,20,101,'وہ ہمیشہ اس میں رہیں گے (ف۱۵۳) اور وہ قیامت کے دن ان کے حق میں کیا ہی بڑا بوجھ ہوگا،'),
 (93,20,102,'جس دن صُور پھونکا جائے گا (ف۱۵۴) اور ہم اس دن مجرموں کو (ف۱۵۵) اٹھائیں گے نیلی آنکھیں (ف۱۵۶)'),
 (93,20,103,'آپس میں چپکے چپکے کہتے ہوں گے کہ تم دنیا میں نہ رہے مگر دس رات (ف۱۵۷)'),
 (93,20,104,'ہم خوب جانتے ہیں جو وہ (ف۱۵۸) کہیں گے جبکہ ان میں سب سے بہتر رائے والا کہے گا کہ تم صرف ایک ہی دن رہے تھے (ف۱۵۹)'),
 (93,20,105,'اور تم سے پہاڑوں کو پوچھتے ہیں (ف۱۶۰) تم فرماؤ انہیں میرا رب ریزہ ریزہ کرکے اڑا دے گا،'),
 (93,20,106,'تو زمین کو پٹ پر (چٹیل میدان) ہموار کر چھوڑے گا'),
 (93,20,107,'کہ تو اس میں نیچا اونچا کچھ نہ دیکھے،'),
 (93,20,108,'اس دن پکارنے والے کے پیچھے دوڑیں گے (ف۱۶۱) اس میں کجی نہ ہوگی (ف۱۶۲) اور سب آوازیں رحمن کے حضو ر (ف۱۶۳) پست ہوکر رہ جائیں گی تو تُو نہ سنے گا مگر بہت آہستہ آواز (ف۱۶۴)'),
 (93,20,109,'اس دن کسی کی شفاعت کام نہ دے گی، مگر اس کی جسے رحمن نے (ف۱۶۵) اذن دے دیا ہے اور اس کی بات پسند فرمائی،'),
 (93,20,110,'وہ جانتا ہے جو کچھ ان کے آگے ہے اور جو کچھ ان کے پیچھے (ف۱۶۶) اور ان کا علم اسے نہیں گھیر سکتا (ف۱۶۷)'),
 (93,20,111,'اور سب منہ جھک جائیں گے اس زندہ قائم رکھنے والے کے حضور (ف۱۶۸) اور بیشک نامراد رہا جس نے ظلم کا بوجھ لیا (ف۱۶۹)'),
 (93,20,112,'اور جو کچھ نیک کام کرے اور ہو مسلمان تو اسے نہ زیادتی کا خوف ہوگا اور نہ نقصان کا (ف۱۷۰)'),
 (93,20,113,'اور یونہی ہم نے اسے عربی قرآن اتارا اور اس میں طرح طرح سے عذاب کے وعدے دیے (ف۱۷۱) کہ کہیں انہیں ڈر ہو یا ان کے دل میں کچھ سوچ پیدا کرے (ف۱۷۲)'),
 (93,20,114,'تو سب سے بلند ہے ا لله سچا بادشاہ (ف۱۷۳) اور قرآن میں جلدی نہ کرو جب تک اس کی وحی تمہیں پوری نہ ہولے (ف۱۷۴) اور عرض کرو کہ اے میرے رب! مجھے علم زیادہ دے،'),
 (93,20,115,'اور بیشک ہم نے آدم کو اس سے پہلے ایک تاکیدی حکم دیا تھا (ف۱۷۵) تو وہ بھول گیا اور ہم نے اس کا قصد نہ پایا،'),
 (93,20,116,'اور جب ہم نے فرشتوں سے فرمایا کہ آدم کو سجدہ کرو تو سب سجدہ میں گرے مگر ابلیس، اس نے نہ مانا،'),
 (93,20,117,'تو ہم نے فرمایا، اے آدم! بیشک یہ تیرا اور تیری بی بی کا دشمن ہے (ف۱۷۶) تو ایسا نہ ہو کہ وہ تم دونوں کو جنت سے نکال دے پھر تو مشقت میں پڑے (ف۱۷۷)'),
 (93,20,118,'بیشک تیرے لیے جنت میں یہ ہے کہ نہ تو بھوکا ہو اور نہ ننگا ہو،'),
 (93,20,119,'اور یہ کہ تجھے نہ اس میں پیاس لگے نہ دھوپ (ف۱۷۸)'),
 (93,20,120,'تو شیطان نے اسے وسوسہ دیا بولا، اے آدم! کیا میں تمہیں بتادوں ہمیشہ جینے کا پیڑ (ف۱۷۹) اور وہ بادشاہی کہ پرانی نہ پڑے (ف۱۸۰)'),
 (93,20,121,'تو ان دونوں نے اس میں سے کھالیا اب ان پر ان کی شرم کی چیزیں ظاہر ہوئیں (ف۱۸۱) اور جنت کے پتے اپنے اوپر چپکانے لگے (ف۱۸۲) اور آدم سے اپنے رب کے حکم میں لغزش واقع ہوئی تو جو مطلب چاہا تھا اس کی راہ نہ پائی (ف۱۸۶)'),
 (93,20,122,'پھر اس کے رب نے چن لیا تو اس پر اپنی رحمت سے رجوع فرمائی اور اپنے قرب خاص کی راہ دکھائی،'),
 (93,20,123,'فرمایا تم دونوں مل کر جنت سے اترو تم میں ایک دوسرے کا دشمن ہے، پھر اگر تم سب کو میری طرف سے ہدایت آئے، (ف۱۸۴) تو جو میری ہدایت کا پیرو ہو ا وہ نہ بہکے (ف۱۸۵) نہ بدبخت ہو (ف۱۸۶)'),
 (93,20,124,'اور جس نے میری یاد سے منہ پھیرا (ف۱۸۷) تو بیشک اس کے لیے تنگ زندگانی ہے (ف۱۸۸) اور ہم اسے قیامت کے دن اندھا اٹھائیں گے،'),
 (93,20,125,'کہے گا اے رب میرے! مجھے تو نے کیوں اندھا اٹھایا میں تو انکھیارا (بینا) تھا (ف۱۸۹)'),
 (93,20,126,'فرمائے گا یونہی تیرے پاس ہماری آیتیں آئیں تھیں (ف۱۹۰) تو نے انہیں بھلادیا اور ایسے ہی آج تیری کوئی نہ لے گا (ف۱۹۱)'),
 (93,20,127,'اور ہم ایسا ہی بدلہ دیتے ہیں جو حد سے بڑھے اور اپنے رب کی آیتوں پر ایمان نہ لائے، اور بیشک آخرت کا عذاب سب سے سخت تر اور سب سے دیرپا ہے،'),
 (93,20,128,'تو کیا انہیں اس سے راہ نہ ملی کہ ہم نے ان سے پہلے کتنی سنگتیں (قومیں) ہلاک کردیں (ف۱۹۲) کہ یہ ان کے بسنے کی جگہ چلتے پھرتے ہیں (ف۱۹۳) بیشک اس میں نشانیاں ہیں عقل والوں کو (ف۱۹۴)'),
 (93,20,129,'اور اگر تمہارے رب کی ایک بات نہ گزر چکی ہوتی (ف۱۹۵) تو ضرور عذاب انھیں (ف۱۹۶) لپٹ جاتا اور اگر نہ ہوتا ایک وعدہ ٹھہرایا ہوا (ف۱۹۷)'),
 (93,20,130,'تو ان کی باتوں پر صبر کرو اور اپنے رب کو سراہتے ہوئے اس کی پاکی بولو سورج چمکنے سے پہلے (ف۱۹۸) اور اس کے ڈوبنے سے پہلے (ف۱۹۹) اور رات کی گھڑیوں میں اس کی پاکی بولو (ف۲۰۰) اور دن کے کناروں پر (ف۲۰۱) اس امید پر کہ تم راضی ہو (ف۲۰۲)'),
 (93,20,131,'اور اے سننے والے اپنی آنکھیں نہ پھیلا اس کی طرف جو ہم نے کافروں کے جوڑوں کو برتنے کے لیے دی ہے جتنی دنیا کی تازگی (ف۲۰۳) کہ ہم انہیں اس کے سبب فتنہ میں ڈالیں (ف۲۰۴) اور تیرے رب کا رزق (ف۲۰۵) سب سے اچھا اور سب سے دیرپا ہے،'),
 (93,20,132,'اور اپنے گھر والوں کو نماز کا حکم دے اور خود اس پر ثابت رہ، کچھ ہم تجھ سے روزی نہیں مانگتے (ف۲۰۶) ہم تجھے روزی دیں گے (ف۲۰۷) اور انجام کا بھلا پرہیزگاری کے لیے،'),
 (93,20,133,'اور کافر بولے یہ (ف۲۰۸) اپنے رب کے پاس سے کوئی نشانی کیوں نہیں لاتے (ف۲۰۹) اور کیا انہیں اس کا بیان نہ آیا جو اگلے صحیفوں میں ہے (ف۲۱۰)'),
 (93,20,134,'اور اگر ہم انہیں کسی عذاب سے ہلاک کردیتے رسول کے آنے سے پہلے تو (ف۲۱۱) ضرور کہتے اے ہمارے رب! تو نے ہماری طرف کوئی رسول کیوں نہ بھیجا کہ ہم تیری آیتوں پر چلتے قبل اس کے کہ ذلیل و رسوا ہوتے،'),
 (93,20,135,'تم فرماؤ سب راہ دیکھ رہے ہیں (ف۲۱۲) تو تم بھی راہ دیکھو تو اب جان جاؤ گے (ف۲۱۳) کہ کون ہیں سیدھی راہ والے اور کس نے ہدایت پائی،'),
 (93,21,1,'لوگوں کا حساب نزدیک اور وہ غفلت میں منہ پھیرے ہیں (ف۲)'),
 (93,21,2,'جب ان کے رب کے پاس سے انہیں کوئی نئی نصیحت آتی ہے تو اسے نہیں سنتے مگر کھیلتے ہوئے، (ف۳)'),
 (93,21,3,'ان کے دل کھیل میں پڑے ہیں (ف۴) اور ظالموں نے آپس میں خفیہ مشورت کی (ف۵) کہ یہ کون ہیں ایک تم ہی جیسے آدمی تو ہیں (ف۶) کیا جادو کے پاس جاتے ہو دیکھ بھال کر،'),
 (93,21,4,'نبی نے فرمایا میرا رب جانتا ہے آسمانوں اور زمین میں ہر بات کو، اور وہی ہے سنتا جانتا (ف۷)'),
 (93,21,5,'بلکہ بولے پریشان خوابیں ہیں (ف۸) بلکہ ان کی گڑھت (گھڑی ہوئی چیز) ہے (ف۹) بلکہ یہ شاعر ہیں (ف۱۰) تو ہمارے پاس کوئی نشانی لائیں جیسے اگلے بھیجے گئے تھے (ف۱۱)'),
 (93,21,6,'ان سے پہلے کوئی بستی ایمان نہ لائی جسے ہم نے ہلاک کیا، تو کیا یہ ایمان لائیں گے (ف۱۲)'),
 (93,21,7,'اور ہم نے تم سے پہلے نہ بھیجے مگر مرد جنہیں ہم وحی کرتے (ف۱۳) تو اے لوگو! علم والوں سے پوچھو اگر تمہیں علم نہ ہو (ف۱۴)'),
 (93,21,8,'اور ہم نے انہیں (ف۱۵) خالی بدن نہ بنایا کہ کھانا نہ کھائیں (ف۱۶) اور نہ وہ دنیا میں ہمیشہ رہیں،'),
 (93,21,9,'پھر ہم نے اپنا وعدہ انہیں سچا کر دکھایا (ف۱۷) تو انہیں نجات دی اور جن کو چاہی (ف۱۸) اور حد سے بڑھنے والوں کو (ف۱۹) ہلاک کردیا'),
 (93,21,10,'بیشک ہم سے تمہاری طرف (ف۲۰) ایک کتاب اتاری جس میں تمہاری ناموری ہے (ف۲۱) تو کیا تمہیں عقل نہیں (ف۲۲)'),
 (93,21,11,'اور کتنی ہی بستیاں ہم نے تباہ کردیں کہ وہ ستمگار تھیں (ف۲۳) اور ان کے بعد اور قوم پیدا کی،'),
 (93,21,12,'تو جب انہوں نے (ف۲۴) ہمارا عذاب پایا جبھی وہ اس سے بھاگنے لگے (ف۲۵)'),
 (93,21,13,'نہ بھاگو اور لوٹ کے جاؤ ان آسائشوں کی طرف جو تم کو دی گئیں تھیں اور اپنے مکانوں کی طرف شاید تم سے پوچھنا ہو (ف۲۶)'),
 (93,21,14,'بولے ہائے خرابی ہماری بیشک ہم ظالم تھے (ف۲۷)'),
 (93,21,15,'تو وہ یہی پکارتے رہے یہاں تک کہ ہم نے انہیں کردیا کاٹے ہوئے (ف۲۸) بجھے ہوئے،'),
 (93,21,16,'اور ہم نے آسمان اور زمین اور جو کچھ ان کے درمیان ہے عبث نہ بنائے (ف۲۹)'),
 (93,21,17,'اگر ہم کوئی بہلاوا اختیار کرنا چاہتے (ف۳۰) تو اپنے پاس سے اختیار کرتے اگر ہمیں کرنا ہوتا (ف۳۱)'),
 (93,21,18,'بلکہ ہم حق کو باطل پر پھینک مارتے ہیں تو وہ اس کا بھیجہ نکال دیتا ہے تو جبھی وہ مٹ کر رہ جاتا ہے (ف۳۲) اور تمہاری خرابی ہے (ف۳۳) ان باتوں سے جو بناتے ہو (ف۳۴)'),
 (93,21,19,'اور اسی کے ہیں جتنے آسمانوں اور زمین میں ہیں (ف۳۵) اور اس کے پاس والے (ف۳۶) اس کی عبادت سے تکبر نہیں کرتے اور نہ تھکیں،'),
 (93,21,20,'رات دن اس کی پاکی بولتے ہیں اور سستی نہیں کرتے،'),
 (93,21,21,'کیا انہوں نے زمین میں سے کچھ ایسے خدا بنالیے ہیں (ف۳۸) کہ وہ کچھ پیدا کرتے ہیں (ف۳۹)'),
 (93,21,22,'اگر آسمان و زمین میں اللہ کے سوا اور خدا ہوتے تو ضرور وہ (ف۴۰) تباہ ہوجاتے (ف۴۱) تو پاکی ہے اللہ عرش کے مالک کو ان باتوں سے جو یہ بناتے ہیں (ف۴۲)'),
 (93,21,23,'اس سے نہیں پوچھا جاتا جو وہ کرے (ف۴۳) اور ان سب سے سوال ہوگا (ف۴۴)'),
 (93,21,24,'کیا اللہ کے سوا اور خدا بنا رکھے ہیں، تم فرماؤ (ف۴۵) اپنی دلیل لاؤ (ف۴۶) یہ قرآن میرے ساتھ والوں کا ذکر ہے (ف۴۷) اور مجھ سے اگلوں کا تذکرہ (ف۴۸) بلکہ ان میں اکثر حق کو نہیں جانتے تو وہ رو گرداں، ہیں (ف۴۹)'),
 (93,21,25,'اور ہم نے تم سے پہلے کوئی رسول نہ بھیجا مگر یہ کہ ہم اس کی طرف وحی فرماتے کہ میرے سوا کوئی معبود نہیں تو مجھی کو پوجو،'),
 (93,21,26,'اور بولے رحمن نے بیٹا اختیار کیا (ف۵۰) پاک ہے وہ (ف۵۱) بلکہ بندے ہیں عزت والے (ف۵۲)'),
 (93,21,27,'بات میں اس سے سبقت نہیں کرتے اور وہ اسی کے حکم پر کاربند ہوتے ہیں،'),
 (93,21,28,'وہ جانتا ہے جو ان کے آگے ہے اور جو ان کے پیچھے ہے (ف۵۳) اور شفاعت نہیں کرتے مگر اس کے لیے جسے وہ پسند فرمائے (ف۵۴) اور وہ اس کے خوف سے ڈر رہے ہیں،'),
 (93,21,29,'اور ان میں جو کوئی کہے کہ میں اللہ کے سوا معبود ہوں (ف۵۵) تو اسے ہم جہنم کی جزا دیں گے، ہم ایسی ہی سزا دیتے ہیں ستمگاروں کو،'),
 (93,21,30,'کیا کافروں نے یہ خیال نہ کیا کہ آسمان اور زمین بند تھے تو ہم نے انہیں کھولا (ف۵۶) اور ہم نے ہر جاندار چیز پانی سے بنائی (ف۵۷) تو کیا وہ ایمان لائیں گے،'),
 (93,21,31,'اور زمین میں ہم نے لنگر ڈالے (ف۵۸) کہ انھیں لے کر نہ کانپے اور ہم نے اس میں کشادہ راہیں رکھیں کہ کہیں وہ راہ پائیں (ف۵۹)'),
 (93,21,32,'اور ہم نے آسمان کو چھت بنایا نگاہ رکھی گئی (ف۶۰) اور وہ (ف۶۱) اس کی نشانیوں سے روگرداں ہیں (ف۶۲)'),
 (93,21,33,'اور وہی ہے جس نے بنائے رات (ف۶۳) اور دن (ف۶۴) اور سورج اور چاند ہر ایک ایک گھیرے میں پیر رہا ہے (ف۶۵)'),
 (93,21,34,'اور ہم نے تم سے پہلے کسی آدمی کے لیے دنیا میں ہمیشگی نہ بنائی (ف۶۶) تو کیا اگر تم انتقال فرماؤ تو یہ ہمیشہ رہیں گے (ف۶۷)'),
 (93,21,35,'ہر جان کو موت کا مزہ چکھنا ہے، اور ہم تمہاری آزمائش کرتے ہیں برائی اور بھلائی سے (ف۶۸) جانچنے کو (ف۶۹) اور ہماری ہی طرف تمہیں لوٹ کر آنا ہے (ف۷۰)'),
 (93,21,36,'اور جب کافر تمہیں دیکھتے ہیں تو تمہیں نہیں ٹھہراتے مگر ٹھٹھا (ف۷۱) کیا یہ ہیں وہ جو تمہارے خداؤں کو برا کہتے ہیں اور وہ (ف۷۲) رحمن ہی کی یاد سے منکر ہیں (ف۷۳)'),
 (93,21,37,'آدمی جلد باز بنایا گیا، اب میں تمہیں اپنی نشانیاں دکھاؤں گا مجھ سے جلدی نہ کرو (ف۷۴)'),
 (93,21,38,'اور کہتے ہیں کب ہوگا یہ وعدہ (ف۷۵) اگر تم سچے ہو،'),
 (93,21,39,'کسی طرح جانتے کافر اس وقت کو جب نہ روک سکیں گے اپنے مونہوں سے آگے (ف۷۶) اور نہ اپنی پیٹھوں سے اور نہ ان کی مدد ہو (ف۷۷)'),
 (93,21,40,'بلکہ وہ ان پر اچانک آپڑے گی (ف۷۸) تو انہیں بے حواس کردے گی پھر نہ وہ اسے پھیرسکیں گے اور نہ انہیں مہلت دی جائے گی (ف۷۹)'),
 (93,21,41,'اور بیشک تم سے اگلے رسولوں کے ساتھ ٹھٹھا کیا گیا (ف۸۰) تو مسخرگی کرنے والوں کا ٹھٹھا انہیں کو لے بیٹھا (ف۸۱)'),
 (93,21,42,'تم فرماؤ شبانہ روز تمہاری کون نگہبانی کرتا ہے رحمان سے (ف۸۲) بلکہ وہ اپنے رب کی یاد سے منہ پھیرے ہیں (ف۸۳)'),
 (93,21,43,'کیا ان کے کچھ خدا ہیں (ف۸۴) جو ان کو ہم سے بچاتے ہیں (ف۸۵) وہ اپنی ہی جانوں کو نہیں بچاسکتے (ف۸۶) اور نہ ہماری طرف سے ان کی یاری ہو،'),
 (93,21,44,'بلکہ ہم نے ان کو (ف۸۷) اور ان کے باپ دادا کو برتاوا دیا (ف۸۸) یہاں تک کہ زندگی ان پر دراز ہوئی (ف۸۹) تو کیا نہیں دیکھتے کہ ہم (ف۹۰) زمین کو اس کے کناروں سے گھٹاتے آرہے ہیں (ف۹۱) تو کیا یہ غالب ہوں گے (ف۹۲)'),
 (93,21,45,'تم فرماؤ کہ میں تم کو صرف وحی سے ڈراتا ہوں (ف۹۳) اور بہرے پکارنا نہیں سنتے جب ڈرائے جائیں، (ف۹۴)'),
 (93,21,46,'اور اگر انہیں تمہارے رب کے عذاب کی ہوا چھو جائے تو ضرور کہیں گے ہائے خرابی ہماری بیشک ہم ظالم تھے (ف۹۵)'),
 (93,21,47,'اور ہم عدل کی ترازوئیں رکھیں گے قیامت کے دن تو کسی جان پر کچھ ظلم نہ ہوگا، اور اگر کوئی چیز (ف۹۶) رائی کے دانہ کے برابر ہو تو ہم اسے لے آئیں گے، اور ہم کافی ہیں حساب کو،'),
 (93,21,48,'اور بیشک ہم نے موسیٰ اور ہارون کو فیصلہ دیا (ف۹۷) اور اجالا (ف۹۸) اور پرہیزگاروں کو نصیحت (ف۹۹)'),
 (93,21,49,'وہ جو بے دیکھے اپنے رب سے ڈرتے ہیں اور انہیں قیامت کا اندیشہ لگا ہوا ہے،'),
 (93,21,50,'اور یہ ہے برکت والا ذکر کہ ہم نے اتارا (ف۱۰۰) تو کیا تم اس کے منکر ہو،'),
 (93,21,51,'اور بیشک ہم نے ابراہیم کو (ف۱۰۱) پہلے ہی سے اس کی نیک راہ عطا کردی اور ہم اس سے خبردار تھے، (ف۱۰۲)'),
 (93,21,52,'جب اس نے اپنے باپ اور قوم سے کہا یہ مورتیں کیا ہیں (ف۱۰۳) جن کے آگے تم آسن مارے (پوجا کے لیے بیٹھے) ہو (ف۱۰۴)'),
 (93,21,53,'بولے ہم نے اپنے دادا کو ان کی پوجا کرتے پایا (ف۱۰۴)'),
 (93,21,54,'کہا بے شک تم اور تمہارے باپ دادا سب کھلی گمراہی میں ہو،'),
 (93,21,55,'بولے کیا تم ہمارے پاس حق لائے ہو یا یونہی کھیلتے ہو (ف۱۰۶)'),
 (93,21,56,'کہا بلکہ تمہارا رب وہ ہے جو رب ہے آسمان اور زمین کا جس نے انہیں پیدا کیا، اور میں اس پر گواہوں میں سے ہوں،'),
 (93,21,57,'اور مجھے اللہ کی قسم ہے میں تمہارے بتوں کا برا چاہوں گا بعد اس کے کہ تم پھر جاؤ پیٹھ دے کر (ف۱۰۷)'),
 (93,21,58,'تو ان سب کو (ف۱۰۸) چورا کردیا مگر ایک کو جو ان کا سب سے بڑا تھا (ف۱۰۹) کہ شاید وہ اس سے کچھ پوچھیں (ف۱۱۰)'),
 (93,21,59,'بولے کس نے ہمارے خداؤں کے ساتھ یہ کام کیا بیشک وہ ظالم ہے،'),
 (93,21,60,'ان میں کے کچھ بولے ہم نے ایک جوان کو انہیں برا کہتے سنا جسے ابراہیم کہتے ہیں (ف۱۱۱)'),
 (93,21,61,'بولے تو اسے لوگوں کے سامنے لاؤ شاید وہ گواہی دیں (ف۱۱۲)'),
 (93,21,62,'بولے کیا تم نے ہمارے خداؤں کے ساتھ یہ کام کیا اے ابراہیم (ف۱۱۳)'),
 (93,21,63,'فرمایا بلکہ ان کے اس بڑے نے کیا ہوگا (ف۱۱۴) تو ان سے پوچھو اگر بولتے ہوں (ف۱۱۵)'),
 (93,21,64,'تو اپنے جی کی طرف پلٹے (ف۱۱۶) اور بولے بیشک تمہیں ستمگار ہو (ف۱۱۷)'),
 (93,21,65,'پھر اپنے سروں کے بل اوندھائے گئے (ف۱۱۸) کہ تمہیں خوب معلوم ہے یہ بولتے نہیں (ف۱۱۹)'),
 (93,21,66,'کہا تو کیا اللہ کے سوا ایسے کو پوجتے ہو جو نہ تمہیں نفع دے (ف۱۲۰) اور نہ نقصان پہنچائے (ف۱۲۱)'),
 (93,21,67,'تف ہے تم پر اور ان بتوں پر جن کو اللہ کے سوا پوجتے ہو، تو کیا تمہیں عقل نہیں (ف۱۲۲)'),
 (93,21,68,'بولے ان کو جلادو اور اپنے خداؤں کی مدد کروں اگر تمہیں کرنا ہے (ف۱۲۳)'),
 (93,21,69,'ہم نے فرمایا اے آگ ہو جا ٹھنڈی اور سلامتی ابراہیم پر (ف۱۲۴)'),
 (93,21,70,'اور انہوں نے اس کا برا چاہا تو ہم نے انہیں سب سے بڑھ کر زیاں کار کردیا (ف۱۲۵)'),
 (93,21,71,'اور ہم اسے اور لوط کو (ف۱۲۶) نجات بخشی (ف۱۲۷) اس زمین کی طرف (ف۱۲۸) جس میں ہم نے جہاں والوں کے لیے برکت رکھی (ف۱۲۹)'),
 (93,21,72,'اور ہم نے اسے اسحاق عطا فرمایا (ف۱۳۰) اور یعقوب پوتا، اور ہم نے ان سب کو اپنے قرب خاص کا سزاوار کیا،'),
 (93,21,73,'اور ہم نے انہیں امام کیا کہ (ف۱۳۱) ہمارے حکم سے بلاتے ہیں اور ہم نے انہیں وحی بھیجی اچھے کام کرنے اور نماز برپا رکھنے اور زکوٰة دینے کی اور وہ ہماری بندگی کرتے تھے،'),
 (93,21,74,'اور لوط کو ہم نے حکومت اور علم دیا اور اسے اس بستی سے نجات بخشی جو گندے کام کرتی تھی (ف۱۳۲) بیشک وہ برُے لوگ بے حکم تھے،'),
 (93,21,75,'اور ہم نے اسے (ف۱۳۳) اپنی رحمت میں داخل کیا، بیشک وہ ہمارے قرب خاص سزاواروں میں ہے،'),
 (93,21,76,'اور نوح کو جب اس سے پہلے اس نے ہمیں پکارا تو ہم نے اس کی دعا قبول کی اور اسے اور اس کے گھر والوں کو بڑی سختی سے نجات دی (ف۱۳۴)'),
 (93,21,77,'اور ہم نے ان لوگوں پر اس کو مدد دی جنہوں نے ہماری آیتیں جھٹلائیں، بیشک وہ برے لوگ تھے تو ہم نے ان سب کو ڈبو دیا،'),
 (93,21,78,'اور داؤد اور سلیمان کو یاد کرو جب کھیتی کا ایک جھگڑا چکاتے تھے، جب رات کو اس میں کچھ لوگوں کی بکریاں چھوٹیں (ف۱۳۵) اور ہم ان کے حکم کے وقت حاضر تھے،'),
 (93,21,79,'ہم نے وہ معاملہ سلیمان کو سمجھادیا (ف۱۳۶) اور دونوں کو حکومت اور علم عطا کیا (ف۱۳۷) اور داؤد کے ساتھ پہاڑ مسخر فرمادیے کہ تسبیح کرتے اور پرندے (ف۱۳۸) اور یہ ہمارے کام تھے،'),
 (93,21,80,'اور ہم نے اسے تمہارا ایک پہناوا بنانا سکھایا کہ تمہیں تمہاری آنچ سے (زخمی ہونے سے) بچائے (ف۱۳۹) تو کیا تم شکر کروگے،'),
 (93,21,81,'اور سلیمان کے لیے تیز ہوا مسخر کردی کہ اس کے حکم سے چلتی اس زمین کی طرف جس میں ہم نے برکت رکھی (ف۱۴۰) اور ہم کو ہر چیز معلوم ہے،'),
 (93,21,82,'اور شیطانوں میں سے جو اس کے لیے غوطہ لگاتے (ف۱۴۱) اور اس کے سوا اور کام کرتے (ف۱۴۲) اور ہم انہیں روکے ہوئے تھے (ف۱۴۳)'),
 (93,21,83,'اور ایوب کو (یاد کرو) جب اس نے اپنے رب کو پکارا (ف۱۴۴) کہ مجھے تکلیف پہنچی اور تو سب مہر والوں سے بڑھ کر مہر والا ہے،'),
 (93,21,84,'تو ہم نے اس کی دعا سن لی تو ہم نے دور کردی جو تکلیف اسے تھی (ف۱۴۵) اور ہم نے اسے اس کے گھر والے اور ان کے ساتھ اتنے ہی اور عطا کیے (ف۱۴۶) اپنے پاس سے رحمت فرما کر اور بندی والوں کے لیے نصیحت (ف۱۴۷)'),
 (93,21,85,'اور اسماعیل اور ادریس اور ذوالکفل کو (یاد کرو)، وہ سب صبر والے تھے (ف۱۴۸)'),
 (93,21,86,'اور انہیں ہم نے اپنی رحمت میں داخل کیا، بیشک وہ ہمارے قربِ خاص کے سزاواروں میں ہیں،'),
 (93,21,87,'اور ذوالنون، کو (یاد کرو) (ف۱۴۹) جب چلا غصہ میں بھرا (ف۱۵۰) تو گمان کیا کہ ہم اس پر تنگی نہ کریں گے (ف۱۵۱) تو اندھیریوں میں پکارا (ف۱۵۲) کوئی معبود نہیں سوا تیرے پاکی ہے تجھ کو، بیشک مجھ سے بے جا ہوا (ف۱۵۳)'),
 (93,21,88,'تو ہم نے اس کی پکار سن لی اور سے غم سے نجات بخشی (ف۱۵۴) اور ایسی ہی نجات دیں گے مسلمانوں کو (ف۱۵۵)'),
 (93,21,89,'اور زکریا کو جب اس نے اپنے رب کو پکارا، اے میرے رب مجھے اکیلا نہ چھوڑ (ف۱۵۶) اور تو سب سے بہتر اور وارث (ف۱۵۷)'),
 (93,21,90,'تو ہم نے اس کی دعا قبول کی اور اسے (ف۱۵۸) یحییٰ عطا فرمایا اور اس کے لیے اس کی بی بی سنواری (ف۱۵۹) بیشک وہ (ف۱۶۰) بھلے کاموں میں جلدی کرتے تھے اور ہمیں پکارتے تھے امید اور خوف سے، اور ہمارے حضور گڑگڑاتے ہیں،'),
 (93,21,91,'اور اس عورت کو اس نے اپنی پارسائی نگاہ رکھی (ف۱۶۱) تو ہم نے اس میں اپنی روح پھونکی (ف۱۶۲) اور اسے اور اس کے بیٹے کو سارے جہاں کے لیے نشانی بنایا (ف۱۶۳)'),
 (93,21,92,'بیشک تمہارا یہ دین ایک ہی دین ہے (ف۱۶۴) اور میں تمہارا رب ہوں (ف۱۶۵) تو میری عبادت کرو،'),
 (93,21,93,'اور اَوروں نے اپنے کام آپس میں ٹکڑے ٹکڑے کرلیے (ف۱۶۶) سب کو ہماری طرف پھرنا ہے، (ف۱۶۷)'),
 (93,21,94,'تو جو کچھ بھلے کام کرے اور ہو ایمان والا تو اس کی کوشش کی بے قدری نہیں، اور ہم اسے لکھ رہے ہیں،'),
 (93,21,95,'اور حرام ہے اس بستی پر جسے ہم نے ہلاک کردیا کہ پھر لوٹ کر آئیں (ف۱۶۸)'),
 (93,21,96,'یہاں تک کہ جب کھولے جائیں گے یاجوج و ماجوج (ف۱۶۹) اور وہ ہر بلندی سے ڈھلکتے ہوں گے،'),
 (93,21,97,'اور قریب آیا سچا وعدہ (ف۱۷۰) تو جبھی آنکھیں پھٹ کر رہ جائیں گی کافروں کی (ف۱۷۱) کہ ہائے ہماری خرابی بیشک ہم (ف۱۷۲) اس سے غفلت میں تھے بلکہ ہم ظالم تھے (ف۱۷۳)'),
 (93,21,98,'بیشک تم (ف۱۷۴) اور جو کچھ اللہ کے سوا تم پوجتے ہو (ف۱۷۵) سب جہنم کے ایندھن ہو، تمہیں اس میں جانا،'),
 (93,21,99,'اگر یہ (ف۱۷۶) خدا ہوتے جہنم میں نہ جاتے، اور ان سب کو ہمیشہ اس میں رہنا (ف۱۷۷)'),
 (93,21,100,'وہ اس میں رینکیں گے (ف۱۷۸) اور وہ اس میں کچھ نہ سنیں گے (ف۱۷۹)'),
 (93,21,101,'بیشک وہ جن کے لیے ہمارا وعدہ بھلائی کا ہوچکا وہ جنہم سے دور رکھے گئے ہیں (ف۱۸۰)'),
 (93,21,102,'وہ اس کی بھنک (ہلکی سی آواز بھی) نہ سنیں گے (ف۱۸۱) اور وہ اپنی من مانتی خواہشوں میں (ف۱۸۲) ہمیشہ رہیں گے،'),
 (93,21,103,'انہیں غم میں نہ ڈالے گی وہ سب سے بڑی گھبراہٹ (ف۱۸۳) اور فرشتے ان کی پیشوائی کو آئیں گے (ف۱۸۴) کہ یہ ہے تمہارا وہ دن جس کا تم سے وعدہ تھا،'),
 (93,21,104,'جس دن ہم آسمان کو لپیٹیں گے جیسے سجل فرشتہ (ف۱۸۵) نامہٴ اعمال کو لپیٹتا ہے، جیسے پہلے اسے بنایا تھا ویسے ہی پھر کردیں گے (ف۱۸۶) یہ وعدہ ہے ہمارے ذمہ، ہم کو اس کا ضرور کرنا،'),
 (93,21,105,'اور بیشک ہم نے زبور میں نصیحت کے بعد لکھ دیا کہ اس زمین کے وارث میرے نیک بندے ہوں گے (ف۱۸۷)'),
 (93,21,106,'بیشک یہ قرآن کافی ہے عبادت والوں کو (ف۱۸۸)'),
 (93,21,107,'اور ہم نے تمہیں نہ بھیجا مگر رحمت سارے جہان کے لیے (ف۱۸۹)'),
 (93,21,108,'تم فرماؤ مجھے تو یہی وحی ہوتی ہے کہ تمہارا خدا نہیں مگر ایک اللہ تو کیا تم مسلمان ہوتے ہو،'),
 (93,21,109,'پھر اگر وہ منہ پھیریں (ف۱۹۰) تو فرمادو میں نے تمہیں لڑائی کا اعلان کردیا، برابری پر اور میں کیا جانوں (ف۱۹۱) کہ پاس ہے یا دور ہے وہ جو تمہیں وعدہ دیا جاتا ہے (ف۱۹۲)'),
 (93,21,110,'بیشک اللہ جانتا ہے آواز کی بات (ف۱۹۳) اور جانتا ہے جو تم چھپاتے ہو (ف۱۹۴)'),
 (93,21,111,'اور میں کیا جانوں شاید وہ (ف۱۹۵) تمہاری جانچ ہو (ف۱۹۶) اور ایک وقت تک برتوانا (ف۱۹۷)'),
 (93,21,112,'نبی نے عرض کی کہ اے میرے رب حق فیصلہ فرمادے (ف۱۹۸) اور ہمارے رب رحمنٰ ہی کی مدد درکار ہے ان باتوں پر جو تم بتاتے ہو، (ف۱۹۹)'),
 (93,22,1,'اے لوگو! اپنے رب سے ڈرو (ف۲) بیشک قیامت کا زلزلہ (ف۳) بڑی سخت چیز ہے،'),
 (93,22,2,'جس دن تم اسے دیکھو گے ہر دودھ پلانے والی (ف۴) اپنے دودھ پیتے کو بھول جائے گی اور ہر گابھ (ف۵) اپنا گابھ ڈال دے گی (ف۶) اور تو لوگوں کو دیکھے گا جیسے نشہ میں ہیں اور نشہ میں نہ ہوں گے (ف۷) مگر ہے یہ کہ اللہ کی مار کڑی ہے،'),
 (93,22,3,'اور کچھ لوگ وہ ہیں کہ اللہ کے معاملہ میں جھگڑتے ہیں بے جانے بوجھے، اور ہر سرکش شیطان کے پیچھے ہو لیتے ہیں (ف۸)'),
 (93,22,4,'جس پر لکھ دیا گیا ہے کہ جو اس کی دوستی کرے گا تو یہ ضرور اسے گمراہ کردے گا اور اسے عذاب دوزخ کی راہ بتائے گا (ف۹)'),
 (93,22,5,'اے لوگو! اگر تمہیں قیامت کے دن جینے میں کچھ شک ہو تو یہ غور کرو کہ ہم نے تمہیں پیدا کیا مٹی سے (ف۱۰) پھر پانی کی بوند سے (ف۱۱) پھر خون کی پھٹک سے (ف۹۱۲ پھر گوشت کی بوٹی سے نقشہ بنی اور بے بنی (ف۱۳) تاکہ ہم تمہارے لیے اپنی نشانیاں ظاہر فرمائیں (ف۱۴) اور ہم ٹھہرائے رکھتے ہیں ماؤں کے پیٹ میں جسے چاہیں ایک مقرر میعاد تک (ف۱۵) پھر تمہیں نکالتے ہیں بچہ پھر (ف۱۶) اس لیے کہ تم اپنی جوانی کو پہنچو (ف ۱۷) اور تم میں کوئی پہلے ہی مرجاتا ہے اور کوئی سب میں نکمی عمر تک ڈالا جاتا ہے (ف۱۸) کہ جاننے کے بعد کچھ نہ جانے (ف۱۹) اور تو زمین کو دیکھے مرجھائی ہوئی (ف۲۰) پھر جب ہم نے اس پر پانی اتارا تر و تازہ ہوئی اور ابھر آئی اور ہر رونق دار جوڑا (ف۲۱) اُگا لائی (ف۲۲)'),
 (93,22,6,'یہ اس لیے ہے کہ اللہ ہی حق ہے (ف۲۳) اور یہ کہ وہ مردے جِلائے گا اور یہ کہ وہ سب کچھ کرسکتا ہے،'),
 (93,22,7,'اور اس لیے کہ قیامت آنے والی اس میں کچھ شک نہیں، اور یہ کہ اللہ اٹھائے گا انہیں جو قبروں میں ہیں،'),
 (93,22,8,'اور کوئی آدمی وہ ہے کہ اللہ کے بارے میں یوں جھگڑتا ہے کہ نہ تو علم نہ کوئی دلیل اور نہ کوئی روشن نوشتہ (تحریر) (ف۲۴)'),
 (93,22,9,'حق سے اپنی گردن موڑے ہوئے تاکہ اللہ کی راہ سے بہکادے (ف۲۵) اس کے لیے دنیا میں رسوائی ہے (ف۲۶) اور قیامت کے دن ہم اسے آگ کا عذاب چکھائیں گے (ف۲۷)'),
 (93,22,10,'یہ اس کا بدلہ ہے جو تیرے ہاتھوں نے آگے بھیجا (ف۲۸) اور اللہ بندوں پر ظلم نہیں کرتا (ف۲۹)'),
 (93,22,11,'اور کچھ آدمی اللہ کی بندگی ایک کنارہ پر کرتے ہیں (ف۳۰) پھر اگر انہیں کوئی بھلائی پہنچ گئی جب تو چین سے ہیں اور جب کوئی جانچ آکر پڑی (ف۳۱) منہ کے بل پلٹ گئے، ف۳۲) دنیا اور آخرت دونوں کا گھاٹا (ف۳۳) یہی ہے صر یح نقصان (ف۳۴)'),
 (93,22,12,'اللہ کے سوا ایسے کو پوجتے ہیں جو ان کا برا بھلا کچھ نہ کرے (ف۳۵) یہی ہے دور کی گمراہی،'),
 (93,22,13,'ایسے کو پوجتے نہیں جس کے نفع سے (ف۳۶) نقصان کی توقع زیادہ ہے (ف۳۷) بیشک (ف۳۸) کیا ہی برا مولیٰ اور بیشک کیا ہی برا رفیق،'),
 (93,22,14,'بیشک اللہ داخل کرے گا انہیں جو ایمان لائے اور بھلے کام کیے باغوں میں جن کے نیچے نہریں رواں، بیشک اللہ کرتا ہے جو چاہے (ف۳۹)'),
 (93,22,15,'جو یہ خیال کرتا ہو کہ اللہ اپنے نبی (ف۴۰) کی مدد نہ فرمائے گا دنیا (ف۴۱) اور آخرت میں (ف۴۲) تو اسے چاہیے کہ اوپر کو ایک رسی تانے پھر اپنے آپ کو پھانسی دے لے پھر دیکھے کہ اس کا یہ داؤں کچھ لے گیا اس بات کو جس کی اسے جلن ہے (ف۴۳)'),
 (93,22,16,'اور بات یہی ہے کہ ہم نے یہ قرآن اتارا روشن آیتیں اور یہ کہ اللہ راہ دیتا ہے جسے چاہے،'),
 (93,22,17,'بیشک مسلمان اور یہودی اور ستارہ پرست اور نصرانی اور آتش پرست اور مشرک، بیشک اللہ ان سب میں قیامت کے دن فیصلہ کردے گا (ف۴۴) بیشک ہر چیز اللہ کے سامنے ہے،'),
 (93,22,18,'کیا تم نے نہ دیکھا (ف۴۵) کہ اللہ کے لیے سجدہ کرتے ہیں وہ جو آسمانوں اور زمین میں ہیں اور سورج اور چاند اور تارے اور پہاڑ اور درخت اور چوپائے (ف۴۶) اور بہت آدمی (ف۴۷) اور بہت وہ ہیں جن پر عذاب مقرر ہوچکا (ف۴۸) اور جسے اللہ ذلیل کرے (ف۴۹) اسے کوئی عزت دینے والا نہیں، بیشک اللہ جو چاہے کرے، (السجدة)۶'),
 (93,22,19,'یہ دو فریق ہیں (ف۵۰) کہ اپنے رب میں جھگڑے (ف۵۱) تو جو کافر ہوئے ان کے لیے آگ کے کپڑے بیونتے (کاٹے) گئے ہیں (ف۵۲) اور ان کے سروں پر کھولتا پانی ڈالا جائے گا (ف۵۳)'),
 (93,22,20,'جس سے گل جائے گا جو کچھ ان کے پیٹوں میں ہے اور ان کی کھالیں (ف۵۴)'),
 (93,22,21,'اور ان کے لیے لوہے کے گرز ہیں (ف۵۵)'),
 (93,22,22,'جب گھٹن کے سبب اس میں سے نکلنا چاہیں گے (ف۵۶) اور پھر اسی میں لوٹا دیے جائیں گے، اور حکم ہوگا کہ چکھو آگ کا عذاب،'),
 (93,22,23,'بیشک اللہ داخل کرے گا انہیں جو ایمان لائے اور اچھے کام کیے بہشتوں میں جن کے نیچے نہریں بہیں اس میں پہنائے جائیں گے سونے کے کنگن اور موتی (ف۵۷) اور وہاں ان کی پوشاک ریشم ہے (ف۵۸)'),
 (93,22,24,'اور انہیں پاکیزہ بات کی ہدایت کی گئی (ف۵۹) اور سب خوبیوں سراہے کی راہ بتائی گئی (ف۶۰)'),
 (93,22,25,'بیشک وہ جنہوں نے کفر کیا اور روکتے ہیں اللہ کی راہ (ف۶۱) اور اس ادب والی مسجد سے (ف۶۲) جسے ہم نے سب لوگوں کے لیے مقرر کیا کہ اس میں ایک سا حق ہے وہاں کے رہنے والے اور پردیسی کا، اور جو اس میں کسی زیادتی کا ناحق ارادہ کرے ہم اسے دردناک عذاب چکھائیں گے (ف۶۳)'),
 (93,22,26,'اور جب کہ ہم نے ابراہیم کو اس گھر کا ٹھکانا ٹھیک بتادیا (ف۶۴) اور حکم دیا کہ میرا کوئی شریک نہ کر اور میرا گھر ستھرا رکھ (ف۶۵) طواف والوں اور اعتکاف والوں اور رکوع سجدے والوں کے لیے (ف۶۶)'),
 (93,22,27,'اور لوگوں میں حج کی عام ندا کردے (ف۶۷) وہ تیرے پاس حاضر ہوں گے پیادہ اور ہر دبلی اونٹنی پر کہ ہر دور کی راہ سے آتی ہیں (ف۶۸)'),
 (93,22,28,'تاکہ وہ اپنا فائدہ پائیں (ف۶۹) اور اللہ کا نام لیں (ف۷۰) جانے ہوئے دنوں میں (ف۷۱) اس پر کہ انہیں روزی دی بے زبان چوپائے (ف۷۲) تو ان میں سے خود کھاؤ اور مصیبت زدہ محتاج کو کھلاؤ (ف۷۳)'),
 (93,22,29,'پھر اپنا میل کچیل اتاریں (ف۷۴) اور اپنی منتیں پوری کریں (ف۷۵) اور اس آزاد گھر کا طواف کریں (ف۷۶)'),
 (93,22,30,'بات یہ ہے اور جو اللہ کی حرمتوں کی تعظیم کرے (ف۷۷) تو وہ اس کے لیے اس کے رب کے یہاں بھلا ہے، اور تمہارے لیے حلال کیے گئے بے زبان چوپائے (ف۷۸) سوا ان کے جن کی ممانعت تم پر پڑھی جاتی ہے (ف۷۹) تو دور ہو بتوں کی گندگی سے (ف۸۰) اور بچو جھوٹی بات سے،'),
 (93,22,31,'ایک اللہ کے ہوکر کہ اس کا ساجھی کسی کو نہ کرو، اور جو اللہ کا شریک کرے وہ گویا گرا آسمان سے کہ پرندے اسے اچک لے جاتے ہیں (ف۸۱) یا ہوا اسے کسی دور جگہ پھینکتی ہے (ف۸۲)'),
 (93,22,32,'بات یہ ہے، اور جو اللہ کے نشانوں کی تعظیم کرے تو یہ دلوں کی پرہیزگاری سے ہے (ف۸۳)'),
 (93,22,33,'تمہارے لیے چوپایوں میں فائدے ہیں (ف۸۴) ایک مقررہ میعاد تک (ف۸۵) پھر ان کا پہنچنا ہے اس آزاد گھر تک (ف۸۶)'),
 (93,22,34,'اور ہر امت کے لیے (ف۸۷) ہم نے ایک قربانی مقرر فرمائی کہ اللہ کا نام لیں اس کے دیے ہوئے بے زبان چوپایوں پر (ف۸۸) تو تمہارا معبود ایک معبود ہے (ف۸۹) تو اسی کے حضور گردن رکھو (ف۹۰) اور اے محبوب خوشی سنادو ان تواضع والوں کو،'),
 (93,22,35,'کہ جب اللہ کا ذکر ہوتا ہے ان کے دل ڈرنے لگتے ہیں (ف۹۱) اور جو افتاد پڑے اس کے سنے والے اور نماز برپا رکھنے والے اور ہمارے دیے سے خرچ کرتے ہیں (ف۹۲)'),
 (93,22,36,'اور قربانی کے ڈیل دار جانور اور اونٹ اور گائے ہم نے تمہارے لیے اللہ کی نشانیوں سے کیے (ف۹۳) تمہارے لیے ان میں بھلائی ہے (ف۹۴) تو ان پر اللہ کا نام لو (ف۹۵) ایک پاؤں بندھے تین پاؤں سے کھڑے (ف۹۶) پھر جب ان کی کروٹیں گرجائیں (ف۹۷) تو ان میں سے خود کھاؤ (ف۹۸) اور صبر سے بیٹھنے والے اور بھیک مانگنے والے کو کھلاؤ، ہم نے یونہی ان کو تمہارے بس میں دے دیا کہ تم احسان مانو،'),
 (93,22,37,'اللہ کو ہرگز نہ ان کے گوشت پہنچتے ہیں نہ ان کے خون ہاں تمہاری پرہیزگاری اس تک باریاب ہوتی ہے (ف۹۹) یونہی ان کو تمہارے پس میں کردیا کہ تم اللہ کی بڑائی بولو اس پر کہ تم کو ہدایت فرمائی، اور اے محبوب! خوشخبری سناؤ نیکی والوں کو (ف۱۰۰)'),
 (93,22,38,'بیشک اللہ بلائیں ٹالتا ہے، مسلمانوں کی (ف۱۰۱) بیشک اللہ دوست نہیں رکھتا ہر بڑے دغا باز ناشکرے کو (ف۱۰۲)'),
 (93,22,39,'پروانگی (اجازت) عطا ہوئی انہیں جن سے کافر لڑتے ہیں (ف۱۰۳) اس بناء پر کہ ان پر ظلم ہوا (ف۱۰۴) اور بیشک اللہ ان کی مدد کرنے پر ضرور قادر ہے،'),
 (93,22,40,'وہ جو اپنے گھروں سے ناحق نکالے گئے (ف۱۰۵) صرف اتنی بات پر کہ انہوں نے کہا ہمارا رب اللہ ہے (ف۱۰۶) اور اللہ اگر آدمیوں میں ایک کو دوسرے سے دفع نہ فرماتا (ف۱۰۷) تو ضرور ڈھادی جاتیں خانقاہیں (ف۱۰۸) اور گرجا (ف۱۰۹) اور کلیسے (ف۱۱۰) اور مسجدیں (ف۱۱۱) جن میں اللہ کا بکثرت نام لیا جاتا ہے، اور بیشک اللہ ضرور مدد فرمائے گا اس کی جو اس کے دین کی مدد کرے گا بیشک ضرور اللہ قدرت والا غالب ہے (ف۱۰۹)،'),
 (93,22,41,'وہ لوگ کہ اگر ہم انہیں زمین میں قابو دیں (ف۱۱۲) تو نماز برپا رکھیں اور زکوٰة اور بھلائی کا حکم کریں اور برائی سے روکیں (ف۱۱۳) اور اللہ ہی کے لیے سب کاموں کا انجام،'),
 (93,22,42,'اور اگر یہ تمہاری تکذیب کرتے ہیں (ف۱۱۴) تو بیشک ان سے پہلے جھٹلا چکی ہے نوح کی قوم اور عاد (ف۱۱۵) اور ثمود (ف۱۱۶)'),
 (93,22,43,'اور ابراہیم کی قوم اور لوط کی قوم،'),
 (93,22,44,'اور مدین والے (ف۱۱۷) اور موسیٰ کی تکذیب ہوئی (ف۱۱۸) تو میں نے کافرو ں کو ڈھیل دی (ف۱۱۹) پھر انہیں پکڑا (ف۱۲۰) تو کیسا ہوا میرا عذاب (ف۱۲۱)'),
 (93,22,45,'اور کتنی ہی بستیاں ہم نے کھپادیں (ہلاک کردیں) (ف۱۲۲) کہ وہ ستمگار تھیں (ف۱۲۳) تو اب وہ اپنی چھتوں پر ڈہی (گری) پڑی ہیں اور کتنے کنویں بیکار پڑے (ف۱۲۴) اور کتنے محل گچ کیے ہوئے (ف۱۲۵)'),
 (93,22,46,'تو کیا زمین میں نہ چلے (ف۱۲۶) کہ ان کے دل ہوں جن سے سمجھیں (ف۱۲۷) یا کان ہوں جن سے سنیں (ف۱۲۸) تو یہ کہ آنکھیں اندھی نہیں ہوتیں (ف۱۲۹) بلکہ وہ دل اندھے ہوتے ہیں جو سینو ں میں ہیں، (ف۱۳۰)'),
 (93,22,47,'اور یہ تم سے عذاب مانگنے میں جلدی کرتے ہیں (ف۱۳۱) اور اللہ ہرگز اپنا وعدہ جھوٹا نہ کرے گا (ف۱۳۲) اور بیشک تمہارے رب کے یہاں (ف۱۳۳) ایک دن ایسا ہے جیسے تم لوگوں کی گنتی میں ہزار برس (ف۱۳۴)'),
 (93,22,48,'اور کتنی بستیاں کہ ہم نے ان کو ڈھیل دی اس حال پر کہ وہ ستمگار تھیں پھر میں نے انہیں پکڑا (ف۱۳۵) اور میری ہی طرف پلٹ کر آتا ہے (ف۱۳۶)'),
 (93,22,49,'تم فرمادو کہ اے لوگو! میں تو یہی تمہارے لیے صریح ڈر سنانے والا ہوں،'),
 (93,22,50,'تو جو ایمان لائے اور اچھے کام کیے ان کے لیے بخشش ہے اور عزت کی روزی (ف۱۳۷)'),
 (93,22,51,'اور وہ جو کوشش کرتے ہیں ہماری آیتوں میں ہار جیت کے ارادہ سے (ف۱۳۸) وہ جہنمی ہیں،'),
 (93,22,52,'اور ہم نے تم سے پہلے جتنے رسول یا نبی بھیجے (ف۱۳۹) سب پر کبھی یہ واقعہ گزرا ہے کہ جب انہوں نے پڑھا تو شیطان نے ان کے پڑھنے میں لوگوں پر کچھ اپنی طرف سے ملادیا تو مٹا دیتا ہے اللہ اس شیطان کے ڈالے ہوئے کو پھر اللہ اپنی آیتیں پکی کردیتا ہے (ف۱۴۰) اور اللہ علم و حکمت والا ہے،'),
 (93,22,53,'تاکہ شیطان کے ڈالے ہوئے کو فتنہ کردے (ف۱۴۱) ان کے لیے جن کے دلوں میں بیماری ہے (ف۱۴۲) اور جن کے دل سخت ہیں (ف۱۴۳) اور بیشک ستمگار (ف۱۴۴) دُھرکے (پرلے درجے کے) جھگڑالو ہیں،'),
 (93,22,54,'اور اس لیے کہ جان لیں وہ جن کو علم ملا ہے (ف۱۴۵) کہ وہ (ف۱۴۶) تمہارے رب کے پاس سے حق ہے تو اس پر ایمان لائیں تو جھک جائیں اس کے لیے ان کے دل، اور بیشک اللہ ایمان والوں کو سیدھی راہ چلانے والا ہے،'),
 (93,22,55,'اور کافر اس سے (ف۱۴۷) ہمیشہ شک میں رہیں گے یہاں تک کہ ان پر قیامت آجائے اچانک (ف۱۴۸) یا ان پر ایسے دن کا عذاب آئے جس کا پھل ان کے لیے کچھ اچھا نہ ہو (ف۱۴۹)'),
 (93,22,56,'بادشاہی اس دن (ف۱۵۰) اللہ ہی کی ہے، وہ ان میں فیصلہ کردے گا، تو جو ایمان لائے اور (ف۱۵۱) اچھے کام کیے وہ چین کے باغوں میں ہیں،'),
 (93,22,57,'اور جنہوں نے کفر کیا اور ہماری آیتیں جھٹلائیں ان کے لیے ذلت کا عذاب ہے،'),
 (93,22,58,'اور وہ جنہوں نے اللہ کی راہ میں اپنے گھر بار چھوڑے (ف۱۵۲) پھر مارے گئے یا مرگئے تواللہ ضرور انہیں اچھی روزی دے گا (ف۱۵۳) اور بیشک اللہ کی روزی سب سے بہتر ہے،'),
 (93,22,59,'ضرور انہیں ایسی جگہ لے جائے گا جسے وہ پسند کریں گے (ف۱۵۴) اور بیشک اللہ علم اور حلم والا ہے،'),
 (93,22,60,'بات یہ ہے اور جو بدلہ لے (ف۱۵۵) جیسی تکلیف پہنچائی گئی تھی پھر اس پر زیادتی کی جائے (ف۱۵۶) تو بیشک اللہ اس کی مدد فرمائے گا (ف۱۵۷) بیشک اللہ معاف کرنے والا بخشنے والا ہے،'),
 (93,22,61,'یہ (ف۱۵۸) اس لیے کہ اللہ تعالیٰ رات کو ڈالتا ہے دن کے حصہ میں اور دن کو لاتا ہے رات کے حصہ میں (ف۱۵۹) اور اس لیے کہ اللہ سنتا دیکھتا ہے،'),
 (93,22,62,'یہ اس لیے (ف۱۶۰) کہ اللہ ہی حق ہے اور اس کے سوا جسے پوجتے ہیں (ف۱۶۱) وہی باطل ہے اور اس لیے کہ اللہ ہی بلندی بڑائی والا ہے،'),
 (93,22,63,'کیا تو نے نہ دیکھا کہ اللہ نے آسمان سے پانی اتارا تو صبح کو زمین (ف۱۶۲) ہریالی ہوگئی، بیشک اللہ پاک خبردار ہے،'),
 (93,22,64,'اسی کا مال ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے، اور بیشک اللہ ہی بے نیاز سب خوبیوں سراہا ہے،'),
 (93,22,65,'کیا تو نے نہ دیکھا کہ اللہ نے تمہارے بس میں کردیا جو کچھ زمین میں ہے (ف۱۶۳) اور کشتی کہ دریا میں اس کے حکم سے چلتی ہے (ف۱۶۴) اور وہ روکے ہوئے ہے آسمان کو کہ زمین پر نہ گر پڑے مگر اس کے حکم سے، بیشک اللہ آدمیوں پر بڑی مہر والا مہربان ہے (ف۱۶۵)'),
 (93,22,66,'اور وہی ہے جس نے تمہیں زندہ کیا (ف۱۶۶) اور پھر تمہیں مارے گا (ف۱۶۷) پھر تمہیں جِلائے گا (ف۱۶۸) بیشک آدمی بڑا ناشکرا ہے (ف۱۶۹)'),
 (93,22,67,'ہر امت کے لیے (ف۱۷۰) ہم نے عبادت کے قاعدے بنادیے کہ وہ ان پر چلے (ف۱۷۱) تو ہرگز وہ تم سے اس معاملہ میں جھگڑا نہ کریں (ف۱۷۲) اور اپنے رب کی طرف بلاؤ (ف۱۷۳) بیشک تم سیدھی راہ پر ہو،'),
 (93,22,68,'اور اگر وہ (ف۱۷۴) تم سے جھگڑیں تو فرمادو کہ اللہ خوب جانتا ہے تمہارے کوتک (تمہاری کرتوت)'),
 (93,22,69,'اللہ تم پر فیصلہ کردے گا قیامت کے دن جس بات میں اختلاف کرتے ہو (ف۱۷۵)'),
 (93,22,70,'کیا تو نے نہ جانا کہ اللہ جانتا ہے جو کچھ آسمانوں اور زمین میں ہے، بیشک یہ سب ایک کتاب میں ہے (ف۱۷۶) بیشک یہ (ف۱۷۷) اللہ پر آسان ہے (ف۱۷۸)'),
 (93,22,71,'اور اللہ کے سوا ایسوں کو پوجتے ہیں (ف۱۷۹) جن کی کوئی سند اس نے نہ اتاری اور ایسوں کو جن کا خود انہیں کچھ علم نہیں (ف۱۸۰) اور ستمگاروں کا (ف۱۸۱) کوئی مددگار نہیں (ف۱۸۲)'),
 (93,22,72,'اور جب ان پر ہماری روشن آیتیں پڑھی جائیں (ف۱۸۳) تو تم ان کے چہروں پر بگڑنے کے آثار دیکھو گے جنہوں نے کفر کیا، قریب ہے کہ لپٹ پڑیں ان کو جو ہماری آیتیں ان پر پڑھتے ہیں، تم فرمادو کیا میں تمہیں بتادوں جو تمہارے اس حال سے بھی (ف۱۸۴) بدتر ہے وہ آگ ہے، اللہ نے اس کا وعدہ دیا ہے کافروں کو، اور کیا ہی بری پلٹنے کی جگہ،'),
 (93,22,73,'اے لوگو! ایک کہاوت فرمائی جاتی ہے اسے کان لگا کر سنو (ف۱۸۵) وہ جنہیں اللہ کے سوا تم پوجتے ہو (ف۱۸۶) ایک مکھی نہ بناسکیں گے اگرچہ سب اس پر اکٹھے ہوجائیں (ف۱۸۷) اور اگر مکھی ان سے کچھ چھین کرلے جائے (ف۱۸۸) تو اس سے چھڑا نہ سکیں (ف۱۸۹) کتنا کمزور چاہنے والا اور وہ جس کو چاہا (ف۱۹۰)'),
 (93,22,74,'اللہ کی قدر نہ جانی جیسی چاہیے تھی (ف۱۹۱) بیشک اللہ قوت والا غالب ہے،'),
 (93,22,75,'اللہ چن لیتا ہے فرشتوں میں سے رسول (ف۱۹۲) اور آدمیوں میں سے (ف۱۹۳) بیشک اللہ سنتا دیکھتا ہے،'),
 (93,22,76,'جانتا ہے جو ان کے آگے ہے اور جو ان کے پیچھے ہے (ف۱۹۴) اور سب کاموں کی رجوع اللہ کی طرف ہے،'),
 (93,22,77,'اے ایمان والو! رکوع اور سجدہ کرو (ف۱۹۵) اور اپنے رب کی بندگی کرو (ف۱۹۶) اور بھلے کام کرو (ف۱۹۷) اس امید پر کہ تمہیں چھٹکارا ہو، (السجدة) عندالشافعیؒ،'),
 (93,22,78,'اور اللہ کی راہ میں جہاد کرو جیسا حق ہے جہاد کرنے کا (ف۱۹۸) اس نے تمہیں پسند کیا (ف۱۹۹) اور تم پر دین میں کچھ تنگی نہ رکھی (ف۲۰۰) تمہارے باپ ابراہیم کا دین (ف۲۰۱) اللہ نے تمہارا نام مسلمان رکھا ہے اگلی کتابوں میں اور اس قرآن میں تاکہ رسول تمہارا نگہبان و گواہ ہو (ف۲۰۲) اور تم اور لوگوں پر گواہی دو (ف۲۰۳) تو نماز برپا رکھو (ف۲۰۴) اور زکوٰة دو اور اللہ کی رسی مضبوط تھام لو (ف۲۰۵) وہ تمہارا مولیٰ ہے تو کیا ہی اچھا مولیٰ اور کیا ہی اچھا مددگار،'),
 (93,23,1,'بیشک مراد کو پہنچے ایمان والے'),
 (93,23,2,'جو اپنی نماز میں گڑگڑاتے ہیں (ف۲)'),
 (93,23,3,'اور وہ جو کسی بیہودہ بات کی طرف التفات نہیں کرتے (ف۳)'),
 (93,23,4,'اور وہ کہ زکوٰة دینے کا کام کرتے ہیں (ف۴)'),
 (93,23,5,'اور وہ جو اپنی شرمگاہوں کی حفاظت کرتے ہیں،'),
 (93,23,6,'مگر اپنی بیبیوں یا شرعی باندیوں پر جو ان کے ہاتھ کی مِلک ہیں کہ ان پر کوئی ملامت نہیں (ف۵)'),
 (93,23,7,'تو جو ان دو کے سوا کچھ اور چاہے وہی حد سے بڑھنے والے ہیں(ف۶)'),
 (93,23,8,'اور وہ جو اپنی امانتوں اور اپنے عہد کی رعایت کرتے ہیں (ف۷)'),
 (93,23,9,'اور وہ جو اپنی نمازوں کی نگہبانی کرتے ہیں (ف۸)'),
 (93,23,10,'یہی لوگ وارث ہیں،'),
 (93,23,11,'کہ فردوس کی میراث پائیں گے، وہ اس میں ہمیشہ رہیں گے،'),
 (93,23,12,'اور بیشک ہم نے آدمی کو چنی ہوئی (انتخاب کی) مٹی سے بنایا، (ف۹)'),
 (93,23,13,'پھر اسے (ف۱۰) پانی کی بوند کیا ایک مضبوط ٹھہراؤ میں (ف۱۱)'),
 (93,23,14,'پھر ہم نے اس پانی کی بوند کو خون کی پھٹک کیا پھر خون کی پھٹک کو گوشت کی بوٹی پھر گوشت کی بوٹی کو ہڈیاں پھر ان ہڈیوں پر گوشت پہنایا، پھر اسے اور صورت میں اٹھان دی (ف۱۲) تو بڑی برکت والا ہے اللہ سب سے بہتر بتانے والا،'),
 (93,23,15,'پھر اس کے بعد تم ضرور (ف۱۳) مرنے والے ہو،'),
 (93,23,16,'پھر تم سب قیامت کے دن (ف۱۴) اٹھائے جاؤ گے،'),
 (93,23,17,'اور بیشک ہم نے تمہارے اوپر سات راہیں بنائیں (ف۱۵) اور ہم خلق سے بے خبر نہیں (ف۱۶)'),
 (93,23,18,'اور ہم نے آسمان سے پانی اتارا (ف۱۷) ایک اندازہ پر (ف۱۸) پھر اسے زمین میں ٹھہرایا اور بیشک ہم اس کے لے جانے پر قادر ہیں (ف۱۹)'),
 (93,23,19,'تو اس سے ہم نے تمہارے باغ پیدا کیے کھجوروں اور انگوروں کے تمہارے لیے ان میں بہت سے میوے ہیں (ف۲۰) اور ان میں سے کھاتے ہو (ف۲۱)'),
 (93,23,20,'اور وہ پیڑ پیدا کیا کہ طور سینا سے نکلتا ہے (ف۲۲) لے کر اگتا ہے تیل اور کھانے والوں کے لیے سالن (ف۲۳)'),
 (93,23,21,'اور بیشک تمہارے لیے چوپایوں میں سمجھنے کا مقام ہے، ہم تمہیں پلاتے ہیں اس میں سے جو ان کے پیٹ میں ہے (ف۲۴) اور تمہارے لیے ان میں بہت فائدے ہیں (ف۲۵) اور ان سے تمہاری خوراک ہے (ف۲۶)'),
 (93,23,22,'اور ان پر (ف۲۷) اور کشتی پر (ف۲۸) سوار کیے جاتے ہو،'),
 (93,23,23,'اور بیشک ہم نے نوح کو اس کی قوم کی طرف بھیجا تو اس نے کہا اے میری قوم اللہ کو پوجو اس کے سوا تمہارا کوئی خدا نہیں، تو کیا تمہیں ڈر نہیں (ف۲۹)'),
 (93,23,24,'تو اس کی قوم کے جن سرداروں نے کفر کیا بولے (ف۳۰) یہ تو نہیں مگر تم جیسا آدمی چاہتا ہے کہ تمہارا بڑا بنے (ف۳۱) اور اللہ چاہتا (ف۳۲) تو فرشتے اتارتا ہم نے تو یہ اگلے باپ داداؤں میں نہ سنا (ف۳۳)'),
 (93,23,25,'وہ تو نہیں مگر ایک دیوانہ مرد تو کچھ زمانہ تک اس کا انتظار کیے رہو (ف۳۴)'),
 (93,23,26,'نوح نے عرض کی اے میرے رب! میری مدد فرما (ف۳۵) اس پر کہ انہوں نے مجھے جھٹلایا،'),
 (93,23,27,'تو ہم نے اسے وحی بھیجی کہ ہماری نگاہ کے سامنے (ف۳۶) اور ہمارے حکم سے کشتی بنا پھر جب ہمارا حکم آئے (ف۳۷) اور تنور ابلے (ف۳۸) تو اس میں بٹھالے (ف۳۹) ہر جوڑے میں سے دو (ف۴۰) اور اپنے گھر والے (ف۴۱) مگر ان میں سے وہ جن پر بات پہلے پڑچکی (ف۴۲) اور ان ظالموں کے معاملہ میں مجھ سے بات نہ کرنا (ف۴۳) یہ ضرور ڈبوئے جائیں گے،'),
 (93,23,28,'پھر جب ٹھیک بیٹھ لے کشتی پر تُو اور تیرے ساتھ والے تو کہہ سب خوبیاں اللہ کو جس نے ہمیں ان ظالموں سے نجات دی،'),
 (93,23,29,'اور عرض کر (ف۴۴) کہ اے میرے رب مجھے برکت والی جگہ اتار اور تو سب سے بہتر اتارنے والا ہے،'),
 (93,23,30,'بیشک اس میں (ف۴۵) ضرو ر نشانیاں (ف۴۶) اور بیشک ضرور ہم جانچنے والے تھے (ف۴۷)'),
 (93,23,31,'پھر ان کے (ف۴۸) بعد ہم نے اور سنگت (قوم) پیدا کی (ف۴۹)'),
 (93,23,32,'تو ان میں ایک رسول انہیں میں سے بھیجا (ف۵۰) کہ اللہ کی بندگی کرو اس کے سوا تمہارا کوئی خدا نہیں، تو کیا تمہیں ڈر نہیں (ف۵۱)'),
 (93,23,33,'اور بولے اس قوم کے سردار جنہوں نے کفر کیا اور آخرت کی حاضری (ف۵۲) کو جھٹلایا اور ہم نے انہیں دنیا کی زندگی میں چین دیا (ف۵۳) کہ یہ تو نہیں مگر جیسا آدمی جو تم کھاتے ہو اسی میں سے کھاتا ہے اور جو تم پیتے ہو اسی میں سے پیتا ہے (ف۵۴)'),
 (93,23,34,'اور اگر تم کسی اپنے جیسے آدمی کی اطاعت کرو جب تو تم ضرور گھاٹے میں ہو،'),
 (93,23,35,'کیا تمہیں یہ وعدہ دیتا ہے کہ تم جب مرجاؤ گے اور مٹی اور ہڈیاں ہوجاؤ گے اس کے بعد پھر (ف۵۵) نکالے جاؤ گے،'),
 (93,23,36,'کتنی دور ہے کتنی دور ہے جو تمہیں وعدہ دیا جاتا ہے (ف۵۶)'),
 (93,23,37,'وہ تو نہیں مگر ہماری دنیا کی زندگی (ف۵۷) کہ ہم مرتے جیتے ہیں (ف۵۸) اور ہمیں اٹھنا نہیں (ف۵۹)'),
 (93,23,38,'وہ تو نہیں مگر ایک مرد جس نے اللہ پر جھوٹ باندھا (ف۶۰) اور ہم اسے ماننے کے نہیں (ف۶۱)'),
 (93,23,39,'عرض کی کہ اے میرے رب میری مدد فرما اس پر کہ انہوں نے مجھے جھٹلایا،'),
 (93,23,40,'اللہ نے فرمایا کچھ دیر جاتی ہے کہ یہ صبح کریں گے پچھتاتے ہوئے (ف۶۲)'),
 (93,23,41,'تو انہیں آلیا سچی چنگھاڑ نے (ف۶۳) تو ہم نے انہیں گھاس کوڑا کردیا (ف۶۴) تو دور ہوں (ف۶۵) ظالم لوگ،'),
 (93,23,42,'پھر ان کے بعد ہم نے اور سنگتیں (قومیں) پیدا کیں (ف۶۶)'),
 (93,23,43,'کوئی امت اپنی میعاد سے نہ پہلے جائے نہ پیچھے رہے (ف۶۷)'),
 (93,23,44,'پھر ہم نے اپنے رسول بھیجے ایک پیچے دوسرا جب کسی امت کے پاس اس کا رسول آیا انہوں نے اسے جھٹلایا (ف۶۸) تو ہم نے اگلوں سے پچھلے ملادیے (ف۶۹) اور انہیں کہانیاں کر ڈالا (ف۷۰) تو دور ہوں وہ لوگ کہ ایمان نہیں لاتے،'),
 (93,23,45,'پھر ہم نے موسیٰ اور اس کے بھائی ہارون کو اپنی آیتوں اور روشن سند (ف۷۱) کے ساتھ بھیجا،'),
 (93,23,46,'فرعون اور اس کے درباریوں کی طرف تو انہوں نے غرور کیا (ف۷۲) اور وہ لوگ غلبہ پائے ہوئے تھے، (ف۷۳)'),
 (93,23,47,'تو بولے کیا ہم ایمان لے آئیں اپنے جیسے دو آدمیوں پر (ف۷۴) اور ان کی قوم ہماری بندگی کررہی ہے، (ف۷۵)'),
 (93,23,48,'تو انہوں نے ان دونوں کو جھٹلایا تو ہلاک کیے ہوؤں میں ہوگئے (ف۷۶)'),
 (93,23,49,'اور بیشک ہم نے موسیٰ کو کتاب عطا فرمائی (ف۷۷) کہ ان کو (ف۷۸) ہدایت ہو،'),
 (93,23,50,'اور ہم نے مریم اور اس کے بیٹے کو (ف۷۹) نشانی کیا اور انہیں ٹھکانا دیا ایک بلند زمین (ف۸۰) جہاں بسنے کا مقام (ف۸۱) اور نگاہ کے سامنے بہتا پانی،'),
 (93,23,51,'اے پیغمبرو! پاکیزہ چیزیں کھاؤ (ف۸۲) اور اچھا کام کرو، میں تمہارے کاموں کو جانتا ہوں (ف۸۳)'),
 (93,23,52,'اور بیشک یہ تمہارا دین ایک ہی دین ہے (ف۸۴) اور میں تمہارا رب ہوں تو مجھ سے ڈرو،'),
 (93,23,53,'تو ان کی امتوں نے اپنا کام آپس میں ٹکڑے ٹکڑے کرلیا (ف۸۵) ہر گروہ جو اس کے پاس ہے اس پر خوش ہے، (ف۸۶)'),
 (93,23,54,'تو تم ان کو چھوڑ دو ان کے نشہ میں (ف۸۷) ایک وقت تک (ف۸۸)'),
 (93,23,55,'کیا یہ خیال کررہے ہیں کہ وہ جو ہم ان کی مدد کررہے ہیں مال اور بیٹوں سے (ف۸۹)'),
 (93,23,56,'یہ جلد جلد ان کو بھلائیاں دیتے ہیں (ف۹۰) بلکہ انہیں خبر نہیں (ف۹۱)'),
 (93,23,57,'بیشک وہ جو اپنے رب کے ڈر سے سہمے ہوئے ہیں (ف۹۲)'),
 (93,23,58,'اور وہ جو اپنے رب کی آیتوں پر ایمان لاتے ہیں (ف۹۳)'),
 (93,23,59,'اور وہ جو اپنے رب کا کوئی شریک نہیں کرتے،'),
 (93,23,60,'اور وہ جو دیتے ہیں جو کچھ دیں (ف۹۴) اور ان کے دل ڈر رہے ہیں یوں کہ ان کو اپنے رب کی طرف پھرنا ہے، (ف۹۵)'),
 (93,23,61,'یہ لوگ بھلائیوں میں جلدی کرتے ہیں اور یہی سب سے پہلے انہیں پہنچے (ف۹۶)'),
 (93,23,62,'اور ہم کسی جان پر بوجھ نہیں رکھتے مگر اس کی طاقت بھر اور ہمارے پاس ایک کتاب ہے کہ حق بولتی ہے (ف۹۷) اور ان پر ظلم نہ ہوگا، ف۹۸)'),
 (93,23,63,'بلکہ ان کے دل اس سے (ف۹۹) غفلت میں ہیں اور ان کے کام ان کاموں سے جدا ہیں (ف۱۰۰) جنہیں وہ کررہے ہیں،'),
 (93,23,64,'یہاں تک کہ جب ہم نے ان کے امیروں کو عذاب میں پکڑا (ف۱۰۱) تو جبھی وہ فریاد کرنے لگے، (ف۱۰۲)'),
 (93,23,65,'آج فریاد نہ کرو، ہماری طرف سے تمہاری مدد نہ ہوگی،'),
 (93,23,66,'بیشک میری آیتیں (ف۱۰۳) تم پر پڑھی جاتی تھیں تو تم اپنی ایڑیوں کے بل الٹے پلٹتے تھے (ف۱۰۴)'),
 (93,23,67,'خدمت حرم پر بڑائی مارتے ہو (ف۱۰۵) رات کو وہاں بیہودہ کہانیاں بکتے (ف۱۰۶)'),
 (93,23,68,'حق کو چھوڑے ہوئے (ف۱۰۷) کیا انہوں نے بات کو سوچا نہیں (ف۱۰۸) یا ان کے پاس وہ آیا جو ان کے باپ دادا کے پاس نہ آیا تھا (ف۱۰۹)'),
 (93,23,69,'یا انہوں نے اپنے رسول کو نہ پہچانا (ف۱۱۰) تو وہ اسے بیگانہ سمجھ رہے ہیں (ف۱۱۱)'),
 (93,23,70,'یا کہتے ہیں اسے سودا ہے (ف۱۱۲) بلکہ وہ تو ان کے پاس حق لائے (ف۱۱۳) اور ان میں اکثر حق برا لگتا ہے (ف۱۱۴)'),
 (93,23,71,'اور اگر حق (ف۱۱۵) ان کی خواہشوں کی پیروی کرتا (ف۱۱۶) تو ضرور آسمان اور زمین اور جو کوئی ان میں ہیں سب تباہ ہوجاتے (ف۱۱۷) بلکہ ہم تو ان کے پاس وہ چیز لائے (ف۱۱۸) جس میں ان کی ناموری تھی تو وہ اپنی عزت سے ہی منہ پھیرے ہوئے ہیں،'),
 (93,23,72,'کیا تم ان سے کچھ اجرت مانگتے ہو (ف۱۱۹) تو تمہارے رب کا اجر سب سے بھلا اور وہ سب سے بہتر روزی دینے والا (ف۱۲۰)'),
 (93,23,73,'اور بیشک تم انہیں سیدھی راہ کی طرف بلاتے ہو (ف۱۲۱)'),
 (93,23,74,'اور بیشک جو آخرت پر ایما ن نہیں لاتے ضرور سیدھی راہ سے (ف۱۲۲) کترائے ہوئے ہیں،'),
 (93,23,75,'اور اگر ہم ان پر رحم کریں اور جو مصیبت (ف۱۲۳) ان پر پڑی ہے ٹال دیں تو ضرور بھٹ پنا (احسان فراموشی) کریں گے اپنی سرکشی میں بہکتے ہوئے (ف۱۲۴)'),
 (93,23,76,'اور بیشک ہم نے انہیں عذاب میں پکڑا (ف۱۲۵) تو نہ وہ اپنے رب کے حضور میں جھکے اور نہ گڑگڑاتے ہیں (ف۱۲۶)'),
 (93,23,77,'یہاں تک کہ جب ہم نے ان پر کھولا کسی سخت عذاب کا دروازہ (ف۱۲۷) تو وہ اب اس میں ناامید پڑے ہیں،'),
 (93,23,78,'اور وہی ہے جس نے بنائے تمہارے لیے کان اور آنکھیں اور دل (ف۱۲۸) تم بہت ہی کم حق مانتے ہو (ف۱۲۹)'),
 (93,23,79,'اور وہی ہے جس نے تمہیں زمین میں پھیلایا اور اسی کی طرف اٹھنا ہے (ف۱۳۰)'),
 (93,23,80,'اور وہی جٕلائے اور مارے اور اسی کے لیے ہیں رات اور دن کی تبدیلیاں (ف۱۳۱) تو کیا تمہیں سمجھ نہیں (ف۱۳۲)'),
 (93,23,81,'بلکہ انہوں نے وہی کہی جو اگلے (ف۱۳۳) کہتے تھے،'),
 (93,23,82,'بولے کیا جب ہم مرجائیں اور مٹی اور ہڈیاں ہوجائیں کیا پھر نکالے جائیں گے،'),
 (93,23,83,'بیشک یہ وعدہ ہم کو اور ہم سے پہلے ہمارے باپ دادا کو دیا گیا یہ تو نہیں مگر وہی اگلی داستانیں (ف۱۳۴)'),
 (93,23,84,'تم فرماؤ کس کا مال ہے زمین اور جو کچھ اس میں ہے اگر تم جانتے ہو (ف۱۳۵)'),
 (93,23,85,'اب کہیں گے کہ اللہ کا (ف۱۳۶) تم فرماؤ پھر کیوں نہیں سوچتے (ف۱۳۷)'),
 (93,23,86,'تم فرماؤ کون ہے مالک سوتوں آسمانوں کا اور مالک بڑے عرش کا،'),
 (93,23,87,'اب کہیں گے یہ اللہ ہی کی شان ہے، تم فرماؤ پھر کیوں نہیں ڈرتے (ف۱۳۸)'),
 (93,23,88,'تم فرماؤ کس کے ہاتھ ہے ہر چیز کا قابو (ف۱۳۹) اور وہ پناہ دیتا ہے اور اس کے خلاف کوئی پناہ نہیں دے سکتا اگر تمہیں علم ہو (ف۱۴۰)'),
 (93,23,89,'اب کہیں گے یہ اللہ ہی کی شان ہے، تم فرماؤ پھر کس جادو کے فریب میں پڑے ہو (ف۱۴۱)'),
 (93,23,90,'بلکہ ہم ان کے پاس حق لائے (ف۱۴۲) اور وہ بیشک جھوٹے ہیں (ف۱۴۳)'),
 (93,23,91,'اللہ نے کوئی بچہ اختیار نہ کیا (ف۱۴۴) اور نہ اس کے ساتھ کوئی دوسرا خدا (ف۱۴۵) یوں ہوتا تو ہر خدا اپنی مخلوق لے جاتا (ف۱۴۶) اور ضرور ایک دوسرے پر اپنی تعلی چاہتا (ف۱۴۷) پاکی ہے اللہ کو ان باتوں سے جو یہ بناتے ہیں (ف۱۴۸)'),
 (93,23,92,'جاننے والا ہر نہاں و عیاں کا تو اسے بلندی ہے ان کے شرک سے،'),
 (93,23,93,'تم عرض کرو کہ اے میرے رب! اگر تو مجھے دکھائے (ف۱۴۹) جو انہیں وعدہ دیا جاتا ہے،'),
 (93,23,94,'تو اے میرے رب! مجھے ان ظالموں کے ساتھ نہ کرنا (ف۱۵۰)'),
 (93,23,95,'اور بیشک ہم قادر ہیں کہ تمہیں دکھادیں جو انہیں وعدہ دے رہے ہیں (ف۱۵۱)'),
 (93,23,96,'سب سے اچھی بھلائی سے برائی کو دفع کرو (ف۱۵۲) ہم خوب جانتے ہیں جو باتیں یہ بناتے ہیں (ف۱۵۳)'),
 (93,23,97,'اور تم عرض کرو کہ اے میرے رب تیری پناہ شیاطین کے وسوسو ں سے (ف۱۵۴)'),
 (93,23,98,'اور اے میرے رب تیری پناہ کہ وہ میرے پاس آئیں،'),
 (93,23,99,'یہاں تک کہ جب ان میں کسی کو موت آئے (ف۱۵۵) تو کہتا ہے کہ اے میرے رب مجھے واپس پھر دیجئے، (ف۱۵۶)'),
 (93,23,100,'شاید اب میں کچھ بھلائی کماؤں اس میں جو چھوڑ آیا ہوں (ف۱۵۷) ہشت یہ تو ایک بات ہے جو وہ اپنے منہ سے کہتا ہے (ف۱۵۸) اور ان کے آگے ایک آڑ ہے (ف۱۵۹) اس دن تک جس دن اٹھائے جائیں گے،'),
 (93,23,101,'تو جب صُور پھونکا جائے گا (ف۱۶۰) تو نہ ان میں رشتے رہیں گے (ف۱۶۱) اور نہ ایک دوسرے کی بات پوچھے (ف۱۶۲)'),
 (93,23,102,'تو جن کی تولیں (ف۱۶۳) بھاری ہولیں وہی مراد کچھ پہنچے،'),
 (93,23,103,'اور جن کی تولیں ہلکی پڑیں (ف۱۶۴) وہی ہیں جنہوں نے اپنی جانیں گھاٹے میں ڈالیں ہمیشہ دوزخ میں رہیں گے،'),
 (93,23,104,'ان کے منہ پر آگ لپیٹ مارے گی اور وہ اس میں منہ چڑائے ہوں گے (ف۱۶۵)'),
 (93,23,105,'کیا تم پر میری آیتیں نہ پڑھی جاتی تھیں (ف۱۶۶) تو تم انہیں جھٹلاتے تھے،'),
 (93,23,106,'کہیں گے اے ہمارے رب ہم پر ہماری بدبختی غالب آئی اور ہم گمراہ لوگ تھے،'),
 (93,23,107,'اے رب ہمارے ہم کو دوزخ سے نکال دے پھر اگر ہم ویسے ہی کریں تو ہم ظالم ہیں (ف۱۶۷)'),
 (93,23,108,'رب فرمائے گا دھتکارے (خائب و خاسر) پڑے رہو اس میں اور مجھ سے بات نہ کرو (ف۱۶۸)'),
 (93,23,109,'بیشک میرے بندوں کا ایک گروہ کہتا تھا اے ہمارے رب! ہم ایمان لائے تو ہمیں بخش دے اور ہم پر رحم کر اور تو سب سے بہتر رحم کرنے والا ہے،'),
 (93,23,110,'تو تم نے انہیں ٹھٹھا بنالیا (ف۱۶۹) یہاں تک کہ انہیں بنانے کے شغل میں (ف۱۷۰) میری یاد بھول گئے اور تم ان سے ہنسا کرتے،'),
 (93,23,111,'بیشک آج میں نے ان کے صبر کا انہیں یہ بدلہ دیا کہ وہی کامیاب ہیں،'),
 (93,23,112,'فرمایا (ف۱۷۱) تم زمین میں کتنا ٹھہرے (ف۱۷۲) برسوں کی گنتی سے'),
 (93,23,113,'، بولے ہم ایک دن رہے یا دن کا حصہ (ف۱۷۳) تو گننے والوں سے دریافت فرما (ف۱۷۴)'),
 (93,23,114,'فرمایا تم نہ ٹھہرے مگر تھوڑا (ف۱۷۵) اگر تمہیں علم ہوتا،'),
 (93,23,115,'تو کیا یہ سمجھتے ہو کہ ہم نے تمہیں بیکار بنایا اور تمہیں ہماری طرف پھرنا نہیں (ف۱۷۶)'),
 (93,23,116,'تو بہت بلندی والا ہے اللہ سچا بادشاہ کوئی معبود نہیں سوا اس کے عزت والے عرش کا مالک،'),
 (93,23,117,'اور جو اللہ کے ساتھ کسی دوسرے خدا کو پوجے جس کی اس کے پاس کوئی سند نہیں (ف۱۷۷) تو اس کا حساب اس کے رب کے یہاں ہے، بیشک کافروں کا چھٹکارا نہیں،'),
 (93,23,118,'اور تم عرض کرو، اے میرے رب بخش دے (ف۱۷۸) اور رحم فرما اور تو سب سے برتر رحم کرنے والا،'),
 (93,24,1,'یہ ایک سورة ہے کہ ہم نے اتاری اور ہم نے اس کے احکام فرض کیے (ف۲) اور ہم نے اس میں روشن آیتیں نازل فرمائیں کہ تم دھیان کرو،'),
 (93,24,2,'جو عورت بدکار ہو اور جو مرد تو ان میں ہر ایک کو سو کوڑے لگاؤ (ف۳) اور تمہیں ان پر ترس نہ آئے اللہ کے دین میں (ف۴) اگر تم ایمان لاتے ہو اللہ اور پچھلے دن پر اور چاہیے کہ ان کی سزا کے وقت مسلمانوں کا ایک گروہ حاضر ہو (ف۵)'),
 (93,24,3,'بدکار مرد نکاح نہ کرے مگر بدکار عورت یا شرک والی سے، اور بدکار عورت سے نکاح نہ کرے مگر بدکار مرد یا مشرک (ف۶) اور یہ کام (ف۷) ایمان والوں پر حرام ہے (ف۸)'),
 (93,24,4,'اور جو پارسا عورتوں کو عیب لگائیں پھر چار گواہ معائنہ کے نہ لائیں تو انہیں اسی کوڑے لگاؤ اور ان کی گواہی کبھی نہ مانو (ف۹) اور وہی فاسق ہیں،'),
 (93,24,5,'مگر جو اس کے بعد توبہ کرلیں اور سنور جائیں (ف۱۰) تو بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,24,6,'اور وہ جو اپنی عورتوں کو عیب لگائیں (ف۱۱) اور ان کے پاس اپنے بیان کے سوا گواہ نہ ہوں تو ایسے کسی کی گواہی یہ ہے کہ چار بار گواہی دے اللہ کے نام سے کہ وہ سچا ہے (ف۱۲)'),
 (93,24,7,'اور پانچویں یہ کہ اللہ کی لعنت ہو اس پر اگر جھوٹا ہو،'),
 (93,24,8,'اور عورت سے یوں سزا ٹل جائے گی کہ وہ اللہ کا نام لے کر چار بار گواہی دے کہ مرد جھوٹا ہے (ف۱۳)'),
 (93,24,9,'اور پانچویں یوں کہ عورت پر غضب اللہ کا اگر مرد جھوٹا ہے (ف۱۳) اور پانچویں یوں کہ عورت پر غضب اللہ کا اگر مرد سچا ہو (ف۱۴)'),
 (93,24,10,'اور اگر اللہ کا فضل اور اس کی رحمت تم پر نہ ہوتی اور یہ کہ اللہ توبہ قبول فرماتا حکمت والا ہے،'),
 (93,24,11,'تو تمہارا پردہ کھول دیتا بیشک وہ کہ یہ بڑا بہتان لائے ہیں تمہیں میں کی ایک جماعت ہے (ف۱۵) اسے اپنے لیے برا نہ سمجھو، بلکہ وہ تمہارے لیے بہتر ہے (ف۱۶) ان میں ہر شخص کے لیے وہ گناہ ہے جو اس نے کمایا (ف۱۷) اور ان میں وہ جس نے سب سے بڑا حصہ لیا (ف۱۸) اس کے لیے بڑا عذاب ہے (ف۱۹)'),
 (93,24,12,'کیوں نہ ہوا ہوا جب تم نے اسے سنا تھا کہ مسلمان مردوں اور مسلمان عورتوں نے اپنوں پر نیک گمان کیا ہوتا (ف۲۰) اور کہتے یہ کھلا بہتان ہے (ف۲۱)'),
 (93,24,13,'اس پر چار گواہ کیوں نہ لائے، تو جب گواہ نہ لائے تو وہی اللہ کے نزدیک جھوٹے ہیں،'),
 (93,24,14,'اور اگر اللہ کا فضل اور اس کی رحمت تم پر دنیا اور آخرت میں نہ ہو تی (ف۲۲) تو جس چرچے میں تم پڑے اس پر تمہیں بڑا عذاب پہنچتا،'),
 (93,24,15,'جب تم ایسی بات اپنی زبانوں پر ایک دوسرے سے سن کر لاتے تھے اور اپنے منہ سے وہ نکالتے تھے جس کا تمہیں علم نہیں اور اسے سہل سمجھتے تھے (ف۲۳) اور وہ اللہ کے نزدیک بڑی بات ہے (ف۲۴)'),
 (93,24,16,'اور کیوں نہ ہوا جب تم نے سنا تھا کہا ہوتا کہ ہمیں نہیں پہنچتا کہ ایسی بات کہیں (ف۲۵) الہٰی پاکی ہے تجھے (ف۲۶) یہ بڑا بہتان ہے،'),
 (93,24,17,'اللہ تمہیں نصیحت فرماتا ہے کہ اب کبھی ایسا نہ کہنا اگر ایمان رکھتے ہو،'),
 (93,24,18,'اور اللہ تمہارے لیے آیتیں صاف بیان فرماتا ہے، اور اللہ علم و حکمت والا ہے،'),
 (93,24,19,'وہ لوگ جو چاہتے ہیں کہ مسلمانوں میں برا چرچا پھیلے ان کے لیے دردناک عذاب ہے دنیا (ف۲۷) اور آخرت میں (ف۲۸) اور اللہ جانتا ہے (ف۲۹) اور تم نہیں جانتے،'),
 (93,24,20,'اور اگر اللہ کا فضل اور اس کی رحمت تم پر نہ ہوتی اور یہ کہ اللہ تم پر نہایت مہربان مہروالا ہے،'),
 (93,24,21,'تو تم اس کا مزہ چکھتے (ف۳۰) اے ایمان والو! شیطان کے قدموں پر نہ چلو، اور جو شیطان کے قدموں پر چلے تو وہ تو بے حیائی اور بری ہی بات بتائے گا (ف۳۱) اور اگر اللہ کا فضل اور اس کی رحمت تم پر نہ ہوتی تو تم میں کوئی بھی کبھی ستھرا نہ ہوسکتا (ف۳۲) ہاں اللہ ستھرا کردیتا ہے جسے چاہے (ف۳۳) اور اللہ سنتا جانتا ہے،'),
 (93,24,22,'اور قسم نہ کھائیں وہ جو تم میں فضیلت والے (ف۳۴) اور گنجائش والے ہیں (ف۳۵) قرابت والوں اور مسکینوں اور اللہ کی راہ میں ہجرت کرنے والوں کو دینے کی، اور چاہیے کہ معاف کریں اور درگزریں، کیا تم اسے دوست نہیں رکھتے کہ اللہ تمہاری بخشش کرے، اور اللہ بخشنے والا مہربان ہے (ف۳۶)'),
 (93,24,23,'بیشک وہ جو عیب لگاتے ہیں انجان (ف۳۷) پارسا ایمان والیوں کو (ف۳۸) ان پر لعنت ہے دنیا اور آخرت میں اور ان کے لیے بڑا عذاب ہے (ف۳۹)'),
 (93,24,24,'جس دن (ف۴۰) ان پر گواہی دیں گے ان کی زبانیں (ف۴۱) اور ان کے ہاتھ اور ان کے پاؤں جو کچھ کرتے تھے،'),
 (93,24,25,'اس دن اللہ انہیں ان کی سچی سزا پوری دے گا (ف۴۲) اور جان لیں گے کہ اللہ ہی صریح حق ہے،'),
 (93,24,26,'(ف۴۳) گندیاں گندوں کے لیے اور گندے گندیوں کے لیے (ف۴۴) اور ستھریاں ستھروں کے لیے اور ستھرے ستھریوں کے لیے وہ (ف۴۵) پاک ہیں ان باتوں سے جو یہ (ف۴۶) کہہ رہے ہیں، ان کے لیے بخشش اور عزت کی روزی ہے (ف۴۷)'),
 (93,24,27,'اے ایمان والو! اپنے گھروں کے سوا اور گھروں میں نہ جاؤ جب تک اجازت نہ لے لو (ف۴۸) اور ان کے ساکنوں پر سلام نہ کرلو (ف۴۹) یہ تمہارے لیے بہتر ہے کہ تم دھیان کرو،'),
 (93,24,28,'پھر اگر ان میں کسی کو نہ پاؤ (ف۵۰) جب بھی بے ما لکوں کی اجازت کے ان میں نہ جاؤ (ف۵۱) اور اگر تم سے کہا جائے واپس جاؤ تو واپس ہو (ف۵۲) یہ تمہارے لیے بہت ستھرا ہے، اللہ تمہارے کاموں کو جانتا ہے،'),
 (93,24,29,'اس میں تم پر کچھ گناہ نہیں کہ ان گھروں میں جاؤ جو خاص کسی کی سکونت کے نہیں (ف۵۳) اور ان کے برتنے کا تمہیں اختیار ہے، اور اللہ جانتا ہے جوتم ظاہر کرتے ہو، اور جو تم چھپاتے ہو،'),
 (93,24,30,'مسلمان مردوں کو حکم دو اپنی نگاہیں کچھ نیچی رکھیں (ف۵۴) اور اپنی شرمگاہوں کی حفاظت کریں (ف۵۵) یہ ان کے لیے بہت ستھرا ہے، بیشک اللہ کو ان کے کاموں کی خبر ہے،'),
 (93,24,31,'اور مسلمان عورتوں کو حکم دو اپنی نگاہیں کچھ نیچی رکھیں (ف۵۶) اور اپنی پارسائی کی حفاظت کریں اور اپنا بناؤ نہ دکھائیں (ف۵۷) مگر جتنا خود ہی ظاہر ہے اور وہ دوپٹے اپنے گریبانوں پر ڈالے رہیں، اور اپنا سنگھار ظاہر نہ کریں مگر اپنے شوہروں پر یا اپنے باپ (ف۵۸) یا شوہروں کے باپ (ف۵۹) یا اپنے بیٹوں (ف۶۰) یا شوہروں کے بیٹے (ف۶۱) یا اپنے بھائی یا اپنے بھتیجے یا اپنے بھانجے (ف۶۲) یا اپنے دین کی عورتیں یا اپنی کنیزیں جو اپنے ہاتھ کی ملک ہوں (ف۶۳) یا نوکر بشرطیکہ شہوت والے مرد نہ ہوں (ف۶۴) یا وہ بچے جنہیں عورتوں کی شرم کی چیزوں کی خبر نہیں (ف۶۵) اور زمین پر پاؤں زور سے نہ رکھیں کہ جانا جائے ان کا چھپا ہوا سنگھار (ف۶۶) اور اللہ کی طرف توبہ کرو اے مسلمانو! سب کے سب اس امید پر کہ تم فلاح پاؤ،'),
 (93,24,32,'اور نکاح کردو اپنوں میں ان کا جو بے نکاح ہوں (ف۶۷) اور اپنے لائق بندوں اور کنیزوں کا اگر وہ فقیر ہوں تو اللہ انہیں غنی کردے گا اپنے فضل کے سبب (ف۶۸) اور اللہ وسعت والا علم والا ہے،'),
 (93,24,33,'اور چاہیے کہ بچے رہیں (ف۶۹) وہ جو نکاح کا مقدور نہیں رکھتے (ف۷۰) یہاں تک کہ اللہ مقدور والا کردے اپنے فضل سے (ف۷۱) اور تمہارے ہاتھ کی مِلک باندی غلاموں میں سے جو یہ چاہیں کہ کچھ مال کمانے کی شرط پر انہیں آزادی لکھ دو تو لکھ دو (ف۷۲) اگر ان میں کچھ بھلائی جانو (ف۷۳) اور اس پر ان کی مدد کرو اللہ کے مال سے جو تم کو دیا (ف۷۴) اور مجبور نہ کرو اپنی کنیزوں کو بدکاری پر جب کہ وہ بچنا چاہیں تاکہ تم دنیوی زندگی کا کچھ مال چاہو (ف۷۵) اور جو انہیں مجبور کرے گا تو بیشک اللہ بعد اس کے کہ وہ مجبوری ہی کی حالت پر رہیں بخشنے والا مہربان ہے (ف۷۶)'),
 (93,24,34,'اور بیشک ہم نے اتاریں تمہاری طرف روشن آیتیں (ف۷۷) اور کچھ ان لوگوں کا بیان جو تم سے پہلے ہو گزرے اور ڈر والوں کے لیے نصیحت،'),
 (93,24,35,'اللہ نور ہے (ف۷۸) آسمانوں اور زمینوں کا، اس کے نور کی (ف۷۹) مثال ایسی جیسے ایک طاق کہ اس میں چراغ ہے وہ چراغ ایک فانوس میں ہے وہ فانوس گویا ایک ستارہ ہے موتی سا چمکتا روشن ہوتا ہے برکت والے پیڑ زیتون سے (ف۸۰) جو نہ پورب کا نہ پچھم کا (ف۸۱) قریب ہے کہ اس کا تیل (ف۸۲) بھڑک اٹھے اگرچہ اسے آگ نہ چھوئے نور پر نور ہے (ف۸۳) اللہ اپنے نور کی راہ بتاتا ہے جسے چاہتا ہے، اور اللہ مثالیں بیان فرماتا ہے لوگوں کے لیے، اور اللہ سب کچھ جانتا ہے،'),
 (93,24,36,'ان گھروں میں جنہیں بلند کرنے کا اللہ نے حکم دیا ہے (ف۸۴) اور ان میں اس کا نام لیا جاتا ہے، اللہ کی تسبیح کرتے ہیں ان میں صبح اور شام (ف۸۵)'),
 (93,24,37,'وہ مرد جنہیں غافل نہیں کرتا کوئی سودا اور نہ خرید و فروخت اللہ کی یاد (ف۸۶) اور نماز برپا رکھنے (ف۸۷) اور زکوٰة دینے سے (ف۸۸) ڈرتے ہیں اس دن سے جس میں الٹ جائیں گے دل اور آنکھیں (ف۸۹)'),
 (93,24,38,'تاکہ اللہ انہیں بدلہ دے ان کے سب سے بہتر کام کام اور اپنے فضل سے انہیں انعام زیادہ دے، اور اللہ روزی دیتا ہے جسے چاہے بے گنتی،'),
 (93,24,39,'اور جو کافر ہوئے ان کے کام ایسے ہیں جیسے دھوپ میں چمکتا ریتا کسی جنگل میں کہ پیاسا اسے پانی سمجھے، یہاں تک جب اس کے پاس آیا تو اسے کچھ نہ پایا (ف۹۰) اور اللہ کو اپنے قریب پایا تو اس نے اس کا حساب پورا بھردیا، اور اللہ جلد حساب کرلیتا ہے (ف۹۱)'),
 (93,24,40,'یا جیسے اندھیریاں کسی کنڈے کے (گہرائی والے) دریا میں (ف۹۲) اس کے اوپر موج مو ج کے اوپر اور موج اس کے اوپر بادل، اندھیرے ہیں ایک پر ایک (ف۹۳) جب اپنا ہاتھ نکالے تو سوجھائی دیتا معلوم نہ ہو (ف۹۴) اور جسے اللہ نور نہ دے اس کے لیے کہیں نور نہیں (ف۹۵)'),
 (93,24,41,'کیا تم نے نہ دیکھا کہ اللہ کی تسبیح کرتے ہیں جو کوئی آسمانوں اور زمین میں ہیں اور پرندے (ف۹۶) پر پھیلائے سب نے جان رکھی ہے اپنی نماز اور اپنی تسبیح، اور اللہ ان کے کاموں کو جانتا ہے،'),
 (93,24,42,'اور اللہ ہی کے لیے ہے سلطنت آسمانوں اور زمین کی اور اللہ ہی کی طرف پھر جانا،'),
 (93,24,43,'کیا تو نے نہ دیکھا کہ اللہ نرم نرم چلاتا ہے بادل کو (ف۹۷) پھر انہیں آپس میں مِلاتا ہے (ف۹۸) پھر انہیں تہہ پر تہہ کردیتا ہے تو تُو دیکھے کہ اس کے بیچ میں سے مینہ نکلتا ہے اور اتارتا ہے آسمان سے اس میں جو برف کے پہاڑ ہیں ان میں سے کچھ اولے (ف۹۹) پھر ڈالنا ہے انہیں جس پر چاہے (ف۱۰۰) اور پھیردیتا ہے انہیں جس سے چاہے (ف۱۰۱) قریب ہے کہ اس کی بجلی کی چمک آنکھ لے جائے (ف۱۰۲)'),
 (93,24,44,'اللہ بدلی کرتا ہے رات اور دن کی (ف۱۰۳) بیشک اس میں سمجھنے کا مقام ہے نگاہ والوں کو،'),
 (93,24,45,'اور اللہ نے زمین پر ہر چلنے والا پانی سے بنایا (ف۱۰۴) تو ان میں کوئی اپنے پیٹ پر چلتا ہے (ف۱۰۵) اور ان میں کوئی دو پاؤں پر چلتا ہے (ف۱۰۶) اور ان میں کوئی چار پاؤں پر چلتا ہے (ف۱۰۷) اللہ بناتا ہے جو چاہے، بیشک اللہ سب کچھ کرسکتا ہے،'),
 (93,24,46,'بیشک ہم نے اتاریں صاف بیان کرنے والی آیتیں (ف۱۰۸) اور اللہ جسے چاہے سیدھی راہ دکھائے (ف۱۰۹)'),
 (93,24,47,'اور کہتے ہیں ہم ایمان لائے اللہ اور رسول پر اور حکم مانا پھر کچھ ان میں کے اس کے بعد پھر جاتے ہیں (ف۱۱۰) اور وہ مسلمان نہیں (ف۱۱۱)'),
 (93,24,48,'اور جب بلائے جائیں اللہ اور اس کے رسول کی طرف کہ رسول ان میں فیصلہ فرمائے تو جبھی ان کا ایک فریق منہ پھیر جاتا ہے،'),
 (93,24,49,'اور اگر ان میں ڈگری ہو (ان کے حق میں فیصلہ ہو) تو اس کی طرف آئیں مانتے ہوئے (ف۱۱۲)'),
 (93,24,50,'کیا ان کے دلوں میں بیماری ہے (ف۱۱۳) یا شک رکھتے ہیں (ف۱۱۴) کیا یہ ڈرتے ہیں کہ اللہ و رسول ان پر ظلم کریں گے (ف۱۱۵) بلکہ خود ہی ظالم ہیں،'),
 (93,24,51,'مسلمانوں کی بات تو یہی ہے (ف۱۱۶) جب اللہ اور رسول کی طرف بلائے جائیں کہ رسول ان میں فیصلہ فرمائے کہ عرض کریں ہم نے سنا اور حکم مانا او ریہی لوگ مراد کو پہنچے،'),
 (93,24,52,'اور جو حکم مانے اللہ اور اس کے رسول کا اور اللہ سے ڈرے اور پرہیزگاری کرے تو یہی لوگ کامیاب ہیں،'),
 (93,24,53,'اور انہوں نے (ف۱۱۷) اللہ کی قسم کھائی اپنے حلف میں حد کی کوشش سے کہ اگر تم انہیں حکم دو گے تو وہ ضرور جہاد کو نکلیں گے تم فرماؤ قسمیں نہ کھاؤ (ف۱۱۸) موافق شرع حکم برداری چاہیے، اللہ جانتا ہے جو تم کرتے ہو (ف۱۱۹)'),
 (93,24,54,'تم فرماؤ حکم مانو اللہ کا اور حکم مانو رسول کا (ف۱۲۰) پھر اگر تم منہ پھیرو (ف۱۲۱) تو رسول کے ذمہ وہی ہے جس اس پر لازم کیا گیا (ف۱۲۲) اور تم پر وہ ہے جس کا بوجھ تم پر رکھا گیا (ف۱۲۳) اور اگر رسول کی فرمانبرداری کرو گے راہ پاؤ گے، اور رسول کے ذمہ نہیں مگر صاف پہنچا دینا (ف۱۲۴)'),
 (93,24,55,'اللہ نے وعدہ دیا ان کو جو تم میں سے ایمان لائے اور اچھے کام کیے (ف۱۲۵) کہ ضرور انہیں زمین میں خلافت دے گا (ف۱۲۶) جیسی ان سے پہلوں کو دی (ف۱۲۷) اور ضرور ان کے لیے جمادے گا ان کا وہ دین جو ان کے لیے پسند فرمایا ہے (ف۱۲۸) اور ضرور ان کے اگلے خوف کو امن سے بدل دے گا (ف۱۲۹) میری عبادت کریں میرا شریک کسی کو نہ ٹھہرائیں، اور جو اس کے بعد ناشکری کرے تو وہی لوگ بے حکم ہیں،'),
 (93,24,56,'اور نماز برپا رکھو اور زکوٰة دو اور رسول کی فرمانبرداری کرو اس امید پر کہ تم پر رحم ہو،'),
 (93,24,57,'ہرگز کافروں کو خیال نہ کرنا کہ وہ کہیں ہمارے قابو سے نکل جائیں زمین میں اور ان کا ٹھکانا آ گ ہے، اور ضرور کیا ہی برا انجام،'),
 (93,24,58,'اے ایمان والو! چاہیے کہ تم سے اذن لیں تمہارے ہاتھ کے مال غلام (ف۱۳۰) اور جو تم میں ابھی جوانی کو نہ پہنچے (ف۱۳۱) تین وقت (ف۱۳۲) نمازِ صبح سے پہلے (ف۱۳۳) اور جب تم اپنے کپڑے اتار رکھتے ہو دوپہر کو (ف۱۳۴) اور نماز عشاء کے بعد (ف۱۳۵) یہ تین وقت تمہاری شرم کے ہیں (ف۱۳۶) ان تین کے بعد کچھ گناہ نہیں تم پر نہ ان پر (ف۱۳۷) آمدورفت رکھتے ہیں تمہارے یہاں ایک دوسرے کے پاس (ف۱۳۸) اللہ یونہی بیان کرتا ہے تمہارے لیے آیتیں، اور اللہ علم و حکمت والا ہے،'),
 (93,24,59,'اور جب تم میں لڑکے (ف۱۳۹) جوانی کو پہنچ جائیں تو وہ بھی اذن مانگیں (ف۱۴۰) جیسے ان کے اگلوں (ف۱۴۱) نے اذن مانگا، اللہ یونہی بیان فرماتا ہے تم سے اپنی آیتیں، اور اللہ علم و حکمت والا ہے،'),
 (93,24,60,'اور بوڑھی خانہ نشین عورتیں (ف۱۴۲) جنہیں نکاح کی آرزو نہیں ان پر کچھ گناہ نہیں کہ اپنے بالائی کپڑے اتار رکھیں جب کہ سنگھار نہ چمکائیں (ف۱۴۳) اور ان سے بھی بچنا (ف۱۴۴) ان کے لیے اور بہتر ہے، ور اللہ سنتا جانتا ہے،'),
 (93,24,61,'نہ اندھے پر تنگی اور نہ لنگڑے پر مضائقہ اور نہ بیمار پر روک اور نہ تم میں کسی پر کہ کھاؤ اپنی اولاد کے گھر (ف۱۴۶) یا اپنے باپ کے گھر یا اپنی ماں کے گھر یا اپنے بھائیوں کے یہاں یا اپنی بہنوں کے گھر ے یا اپنے چچاؤں کے یہاں یا اپنی پھپیوں کے گھر یا اپنے ماموؤں کے یہاں یا اپنی خالاؤں کے گھر یا جہاں کی کنجیاں تمہارے قبضہ میں ہیں (ف۱۴۷) یا اپنے دوست کے یہاں تم پر کوئی الزام نہیں کہ مل کر کھاؤ یا الگ الگ (ف۱۴۰) پھر جب کسی گھر میں جاؤ تو اپنوں کو سلام کرو (ف۱۵۰) ملتے وقت کی اچھی دعا اللہ کے پاس سے مبارک پاکیزہ، اللہ یونہی بیان فرماتا ہے تم سے آیتیں کہ تمہیں سمجھ ہو،'),
 (93,24,62,'ایمان والے تو وہی ہیں جو اللہ اور اس کے رسول پر یقین لائے اور جب رسول کے پاس کسی ایسے کام میں حاضر ہوئے ہوں جس کے لیے جمع کیے گئے ہوں (ف۱۵۱) تو نہ جائیں جب تک ان سے اجازت نہ لے لیں وہ جو تم سے اجازت مانگتے ہیں وہی ہیں جو اللہ اور اس کے رسول پر ایمان لاتے ہیں (ف۱۵۲) پھر جب وہ تم سے اجازت مانگیں اپنے کسی کام کے لیے تو ان میں جسے تم چاہو اجازت دے دو اور ان کے لیے اللہ سے معافی مانگو (ف۱۵۳) بیشک اللہ بخشنے والا مہربان ہے،'),
 (93,24,63,'رسول کے پکارنے کو آپس میں ایسا نہ ٹھہرالو جیسا تم میں ایک دوسرے کو پکارتا ہے (ف۱۵۴) بیشک اللہ جانتا ہے جو تم میں چپکے نکل جاتے ہیں کسی چیز کی آڑ لے کر (ف۱۵۵) تو ڈریں وہ جو رسول کے حکم کے خلاف کرتے ہیں کہ انہیں کوئی فتنہ پہنچے (ف۱۵۶) یا ان پر دردناک عذاب پڑے (ف۱۵۷)'),
 (93,24,64,'سن لو ! بیشک اللہ ہی کا ہے جو کچھ آسمانوں اور زمین میں ہے، بیشک وہ جانتا ہے جس حال پر تم ہو (ف۱۵۸) اور اس دن کو جس میں اس کی طرف پھیرے جائیں گے (ف۱۵۹) تو وہ انہیں بتادے گا جو کچھ انہوں نے کیا، اور اللہ سب کچھ جانتا ہے، (ف۱۶۰)'),
 (93,25,1,'بڑی برکت والا ہے وہ کہ جس نے اتارا قرآن اپنے بندہ پر (ف۲) جو سارے جہان کو ڈر سنانے والا ہو (ف۳)'),
 (93,25,2,'وہ جس کے لیے ہے آسمانوں اور زمین کی بادشاہت اور اس نے نہ اختیار فرمایا بچہ (ف۴) اور اس کی سلطنت میں کوئی ساجھی نہیں (ف۵) اس نے ہر چیز پیدا کرکے ٹھیک اندازہ پر رکھی،'),
 (93,25,3,'اور لوگوں نے اس کے سوا اور خدا ٹھہرالیے (ف۶) کہ وہ کچھ نہیں بناتے اور خود پیدا کیے گئے ہیں اور خود اپنی جانوں کے برے بھلے کے مالک نہیں اور نہ مرنے کا اختیار نہ جینے کا نہ اٹھنے کا،'),
 (93,25,4,'اور کافر بولے (ف۷) یہ تو نہیں مگر ایک بہتان جو انہوں نے بنالیا ہے (ف۸) اور اس پر اور لوگوں نے (ف۹) انہیں مدد دی ہے بیشک وہ (ف۱۰) ظلم اور جھوٹ پر آئے،'),
 (93,25,5,'اور بولے (ف۱۱) اگلوں کی کہانیاں ہیں جو انہوں نے (ف۱۲) لکھ لی ہیں تو وہ ان پر صبح و شام پڑھی جاتی ہیں،'),
 (93,25,6,'تم فرماؤ اسے تو اس نے اتارا ہے جو آسمانوں اور زمین کی ہر بات جانتا ہے (ف۱۳) بیشک وہ بخشنے والا مہربان ہے (ف۱۴)'),
 (93,25,7,'اور بولے (ف۱۵) اور رسول کو کیا ہوا کھانا کھاتا ہے اور بازاروں میں چلتا ہے (ف۹۱۶ کیوں نہ اتارا گیا ان کے ساتھ کوئی فرشتہ کہ ان کے ساتھ ڈر سناتا (ف۱۷)'),
 (93,25,8,'یا غیب سے انہیں کوئی خزانہ مل جاتا یا ان کا کوئی باغ ہوتا جس میں سے کھاتے (ف۱۸) اور ظالم بولے (ف۱۹) تم تو پیروی نہیں کرتے مگر ایک ایسے مرد کی جس پر جادو ہوا (ف۲۰)'),
 (93,25,9,'اے محبوب دیکھو کیسی کہاوتیں تمہارے لیے بنارہے ہیں تو گمراہ ہوئے کہ اب کوئی راہ نہیں پاتے،'),
 (93,25,10,'بڑی برکت والا ہے وہ کہ اگر چاہے تو تمہارے لیے بہت بہتر اس سے کردے (ف۲۱) جنتیں جن کے نیچے نہریں بہیں اور کرے گا تمہارے لیے اونچے اونچے محل،'),
 (93,25,11,'بلکہ یہ تو قیامت کو جھٹلاتے ہیں، اور جو قیامت کو جھٹلائے ہم نے اس کے لیے تیار کر رکھی ہے بھڑکتی ہوئی آگ،'),
 (93,25,12,'جب وہ انہیں دور جگہ سے دیکھے گی (ف۲۲) تو سنیں گے اس کا جوش مارنا اور چنگھاڑنا،'),
 (93,25,13,'اور جب اس کی کسی تنگ جگہ میں ڈالے جائیں گے (ف۲۳) زنجیروں میں جکڑے ہوئے (ف۲۴) تو وہاں موت مانگیں گے (ف۲۵)'),
 (93,25,14,'فرمایا جائے گا آج ایک موت نہ مانگو اور بہت سی موتیں مانگو (ف۲۶)'),
 (93,25,15,'تم فرماؤ کیا یہ (ف۲۷) بھلا یا وہ ہمیشگی کے باغ جس کا وعدہ ڈر والوں کو ہے، وہ ان کا صلہ اور انجام ہے،'),
 (93,25,16,'ان کے لیے وہاں من مانی مرادیں ہیں جن میں ہمیشہ رہیں گے، تمہارے رب کے ذمہ وعدہ ہے مانگا ہوا، ف۲۸)'),
 (93,25,17,'اور جس دن اکٹھا کرے گا انہیں (ف۲۹) اور جن کوا لله کے سوا پوجتے ہیں (ف۳۰) پھر ان معبودو ں سے فرمائے گا کیا تم نے گمراہ کردیے یہ میرے بندے یا یہ خود ہی راہ بھولے (ف۳۱)'),
 (93,25,18,'وہ عرض کریں گے پاکی ہے تجھ کو (ف۳۲) ہمیں سزاوار (حق) نہ تھا کہ تیرے سوا کسی اور کو مولیٰ بنائیں (ف۳۳) لیکن تو نے انہیں اور ان کے باپ داداؤں کو برتنے دیا (ف۳۴) یہاں تک کہ وہ تیری یاد بھول گئے اور یہ لوگ تھے ہی ہلاک ہونے والے (ف۳۵)'),
 (93,25,19,'تو اب معبودوں نے تمہاری بات جھٹلادی تو اب تم نہ عذاب پھیرسکو نہ اپنی مدد کرسکو اور تم میں جو ظالم ہے ہم اسے بڑا عذاب چکھائیں گے،'),
 (93,25,20,'اور ہم نے تم سے پہلے جتنے رسول بھیجے سب ایسے ہی تھے کھانا کھاتے اور بازاروں میں چلتے (ف۳۶) اور ہم نے تم میں ایک کو دوسرے کی جانچ کیا ہے (ف۳۷) اور اے لوگو! کیا تم صبر کرو گے (ف۳۸) اور اے محبوب! تمہارا رب دیکھتا ہے (ف۲۹)'),
 (93,25,21,'اور بولے وہ جو (ف۴۰) ہمارے ملنے کی امید نہیں رکھتے ہم پر فرشتے کیوں نہ اتارے (ف۴۱) یا ہم اپنے رب کو دیکھتے (ف۴۲) بیشک اپنے جی میں بہت ہی اونچی کھینچی (سرکشی کی) اور بڑی سرکشی پر آئے (ف۴۳)'),
 (93,25,22,'جس دن فرشتوں کو دیکھیں گے (ف۴۴) وہ دن مجرموں کی کوئی خوشی کا نہ ہوگا (ف۴۵) اور کہیں گے الٰہی ہم میں ان میں کوئی آڑ کردے رکی ہوئی (ف۴۶)'),
 (93,25,23,'اور جو کچھ انہوں نے کام کیے تھے (ف۴۷) ہم نے قصد فرماکر انہیں باریک باریک غبار، کے بکھرے ہوئے ذرے کردیا کہ روزن کی دھوپ میں نظر آتے ہیں (ف۴۸)'),
 (93,25,24,'جنت والوں کا اس دن اچھا ٹھکانا (ف۴۹) اور حساب کے دوپہر کے بعد اچھی آرام کی جگہ،'),
 (93,25,25,'اور جس دن پھٹ جائے گا آسمان بادلوں سے اور فرشتے اتارے جائیں گے پوری طرح (ف۵۰)'),
 (93,25,26,'اس دن سچی بادشاہی رحمن کی ہے، اور وہ دن کافروں پر سخت ہے (ف۵۱)'),
 (93,25,27,'اور جس دن ظالم اپنے ہاتھ چبا چبا لے گا (ف۵۲) کہ ہائے کسی طرح سے میں نے رسول کے ساتھ راہ لی ہوتی، (ف۵۳)'),
 (93,25,28,'وائے خرابی میری ہائے کسی طرح میں نے فلانے کو دوست نہ بنایا ہوتا،'),
 (93,25,29,'بیشک اس نے مجھے بہکادیا میرے پاس آئی ہوئی نصیحت سے (ف۵۴) اور شیطان آدمی کو بے مدد چھوڑ دیتا ہے (ف۵۵)'),
 (93,25,30,'اور رسول نے عرض کی کہ اے میرے رب! میری قوم نے اس قرآن کو چھوڑنے کے قابل ٹھہرایا (ف۵۶)'),
 (93,25,31,'اور اسی طرح ہم نے ہر نبی کے لیے دشمن بنادیے تھے مجرم لوگ (ف۵۷) اور تمہارا رب کافی ہے ہدایت کرنے اور مدد دینے کو،'),
 (93,25,32,'اور کافر بولے قرآن ان پر ایک ساتھ کیوں نہ اتار دیا (ف۵۸) ہم نے یونہی بتدریج سے اتارا ہے کہ اس سے تمہارا دل مضبوط کریں (ف۵۹) اور ہم نے اسے ٹھہر ٹھہر کر پڑھا (ف۶۰)'),
 (93,25,33,'اور وہ کوئی کہاوت تمہارے پاس نہ لائیں گے (ف۶۱) مگر ہم حق اور اس سے بہتر بیان لے آئیں گے،'),
 (93,25,34,'وہ جو جہنم کی طرف ہانکے جائیں گے اپنے منہ کے بل ان کا ٹھکانا سب سے برا (ف۶۲) اور وہ سب سے گمراہ،'),
 (93,25,35,'اور بیشک ہم نے موسیٰ کو کتاب عطا فرمائی اور اس کے بھائی ہارون کو وزیر کیا،'),
 (93,25,36,'تو ہم نے فرمایا تم دونوں جاؤ اس قوم کی طرف جس نے ہماری آیتیں جھٹلائیں (ف۶۳) پھر ہم نے انہیں تباہ کرکے ہلاک کردیا،'),
 (93,25,37,'اور نوح کی قوم کو (ف۶۴) جب انہوں نے رسولوں کو جھٹلایا (ف۶۵) ہم نے ان کو ڈبو دیا اور انہیں لوگوں کے لیے نشانی کردیا (ف۶۶) اور ہم نے ظالموں کے لیے دردناک عذاب تیار کر رکھا ہے،'),
 (93,25,38,'اور عاد اور ثمود (ف۶۷) اور کنوئیں والوں کو (ف۶۸) اور ان کے بیچ میں بہت سی سنگتیں (قومیں) (ف۶۹)'),
 (93,25,39,'اور ہم نے سب سے مثالیں بیان فرمائیں (ف۷۰) اور سب کو تباہ کرکے مٹادیا،'),
 (93,25,40,'اور ضرور یہ (ف۷۱) ہو آئے ہیں اس بستی پر جس پر برا برساؤ برسا تھا (ف۷۲) تو کیا یہ اسے دیکھتے نہ تھے (ف۷۳) بلکہ انہیں جی اٹھنے کی امید تھی ہی نہیں (ف۷۴)'),
 (93,25,41,'اور جب تمہیں دیکھتے ہیں تو تمہیں نہیں ٹھہراتے مگر ٹھٹھا (ف۷۵) کیا یہ ہیں جن کو اللہ نے رسول بناکر بھیجا،'),
 (93,25,42,'قریب تھا کہ یہ ہمیں ہمارے خداؤں سے بہکادیں اگر ہم ان پر صبر نہ کرتے (ف۷۶) اور اب جانا چاہتے ہیں جس دن عذاب دیکھیں گے (ف۷۷) کہ کون گمراہ تھا (ف۷۸)'),
 (93,25,43,'کیا تم نے اسے دیکھا جس نے اپنی جی کی خواہش کو اپنا خدا بنالیا (ف۷۹) تو کیا تم اس کی نگہبانی کا ذمہ لو گے (ف۸۰)'),
 (93,25,44,'یا یہ سمجھتے ہو کہ ان میں بہت کچھ سنتے یا سمجھتے ہیں (ف۸۱) وہ تو نہیں مگر جیسے چوپائے بلکہ ان سے بھی بدتر گمراہ (ف۸۲)'),
 (93,25,45,'اے محبوب! کیا تم نے اپنے رب کو نہ دیکھا (ف۸۳) کہ کیسا پھیلا سایہ (ف۸۴) اور اگر چاہتا تو اسے ٹھہرایا ہوا کردیتا (ف۸۵) پھر ہم نے سورج کو اس پر دلیل کیا،'),
 (93,25,46,'پھر ہم نے آہستہ آہستہ اسے اپنی طرف سمیٹا (ف۸۶)'),
 (93,25,47,'اور وہی ہے جس نے رات کو تمہارے لیے پردہ کیا اور نیند کو آرام اور دن بنایا اٹھنے کے لیے (ف۸۷)'),
 (93,25,48,'اور وہی ہے جس نے ہوائیں بھیجیں اپنی رحمت کے آگے مژدہ سنائی ہوئی (ف۸۸) اور ہم نے آسمان سے پانی اتارا پاک کرنے والا،'),
 (93,25,49,'تاکہ ہم ا سسے زندہ کریں کسی مردہ شہر کو (ف۸۹) اور اسے پلائیں اپنے بنائے ہوئے بہت سے چوپائے اور آدمیوں کو،'),
 (93,25,50,'اور بیشک ہم نے ان میں پانی کے پھیرے رکھے (ف۹۰) کہ وہ دھیان کریں (ف۹۱) تو بہت لوگوں نے نہ مانا مگر ناشکری کرنا،'),
 (93,25,51,'اور ہم چاہتے تو ہر بستی میں ایک ڈر سنانے والا بھیجتے (ف۹۲)'),
 (93,25,52,'تو کافروں کا کہا نہ مان اور اس قرآن سے ان پر جہاد کر بڑا جہاد،'),
 (93,25,53,'اور وہی ہے جس نے ملے ہوئے رواں کیے دو سمندر یہ میٹھا ہے نہایت شیریں اور یہ کھاری ہے نہایت تلخ اور ان کے بیچ میں پردہ رکھا اور روکی ہوئی آڑ (ف۹۳)'),
 (93,25,54,'اور وہی ہے جس نے پانی سے (ف۹۴) بنایا آدمی پھر اس کے رشتے اور سسرال مقرر کی (ف۹۵) اور تمہارا رب قدرت والا ہے (ف۹۶)'),
 (93,25,55,'اور اللہ کے سوا ایسوں کو پوجتے ہیں (ف۹۷) جو ان کا بھلا برا کچھ نہ کریں اور کافر اپنے رب کے مقابل شیطان کو مدد دیتا ہے (ف۹۸)'),
 (93,25,56,'اور ہم نے تمہیں نہ بھیجا مگر (ف۹۹) خوشی اور (ف۱۰۰) ڈر سناتا،'),
 (93,25,57,'تم فرماؤ میں اس (ف۱۰۱) پر تم سے کچھ اجرت نہیں مانگتا مگر جو چاہے کہ اپنے رب کی طرف راہ لے، (ف۱۰۲)'),
 (93,25,58,'اور بھروسہ کرو اس زندہ پر جو کبھی نہ مرے گا (ف۱۰۳) اور اسے سراہتے ہوئے اس کی پاکی بولو (ف۱۰۴) اور وہی کافی ہے اپنے بندوں کے گناہوں پر خبردار (ف۱۰۵)'),
 (93,25,59,'جس نے آسمان اور زمین اور جو کچھ ان کے درمیان ہے چھ دن میں بنائے (ف۱۰۶) پھر عرش پر استواء فرمایا جیسا کہ اس کی شان کے لائق ہے (ف۱۰۷) وہ بڑی مہر والا تو کسی جاننے والے سے اس کی تعریف پوچھ (ف۱۰۸)'),
 (93,25,60,'اور جب ان سے کہا جائے (ف۱۰۹) رحمن کو سجدہ کرو کہتے ہیں رحمن کیا ہے، کیا ہم سجدہ کرلیں جسے تم کہو (ف۱۱۰) اور اس حکم نے انہیں اور بدکنا بڑھایا (ف۱۱۱) السجدة ۔۷'),
 (93,25,61,'بڑی برکت والا ہے وہ جس نے آسمان میں برج بنائے (ف۱۱۲) اور ان میں چراغ رکھا (ف۱۱۳) اور چمکتا چاند،'),
 (93,25,62,'اور وہی ہے جس نے رات اور دن کی بدلی رکھی (ف۱۱۴) اس کے لیے جو دھیان کرنا چاہے یا شکر کا ارادہ کرے،'),
 (93,25,63,'اور رحمن کے وہ بندے کہ زمین پر آہستہ چلتے ہیں (ف۱۱۵) اور جب جاہل ان سے بات کرتے ہیں (ف۱۱۶) تو کہتے ہیں بس سلام (ف۱۱۷)'),
 (93,25,64,'اور وہ جو رات کاٹتے ہیں اپنے رب کے لیے سجدے اور قیام میں (ف۱۱۸)'),
 (93,25,65,'اور وہ جو عرض کرتے ہیں اے ہمارے رب! ہم سے پھیر دے جہنم کا عذاب، بیشک اس کا عذاب گلے کا غل (پھندا) ہے (ف۱۱۹)'),
 (93,25,66,'بیشک وہ بہت ہی بری ٹھہرنے کی جگہ ہے،'),
 (93,25,67,'اور وہ کہ جب خرچ کرتے ہیں نہ حد سے بڑھیں اور نہ تنگی کریں (ف۱۲۰) اور ان دونوں کے بیچ اعتدال پر رہیں (ف۱۲۱)'),
 (93,25,68,'اور وہ جو اللہ کے ساتھ کسی دوسرے معبود کو نہیں پوجتے (ف۱۲۲) اور اس جان کو جس کی اللہ نے حرمت رکھی (ف۱۲۳) ناحق نہیں مارتے اور بدکاری نہیں کرتے (ف۱۲۴) اور جو یہ کام کرے وہ سزا پائے گا،'),
 (93,25,69,'بڑھایا جائے گا اس پر عذابِ قیامت کے دن (ف۱۲۵) اور ہمیشہ اس میں ذلت سے رہے گا،'),
 (93,25,70,'مگر جو توبہ کرے (ف۱۲۶) اور ایمان لائے (ف۱۲۷) اور اچھا کام کرے (ف۱۲۷) اور اچھا کام کرے (ف۱۲۸) تو ایسوں کی برائیوں کو اللہ بھلائیوں سے بدل دے گا (ف۱۲۹) اور اللہ بخشنے والا مہربان ہے،'),
 (93,25,71,'اور جو توبہ کرے اور اچھا کام کرے تو وہ اللہ کی طرف رجوع لایا جیسی چاہیے تھی،'),
 (93,25,72,'اور جو جھوٹی گواہی نہیں دیتے (ف۱۳۰) اور جب بیہودہ پر گذرتے ہیں اپنی عزت سنبھالے گزر جاتے ہیں، (ف۱۳۱)'),
 (93,25,73,'اور وہ کہ جب کہ انہیں ان کے رب کی آیتیں یاد د لائی جائیں تو ان پر (ف۱۳۲) بہرے اندھے ہوکر نہیں گرتے (ف۱۳۳)'),
 (93,25,74,'اور وہ جو عرض کرتے ہیں، اے ہمارے رب! ہمیں دے ہماری بیبیوں اور اولاد سے آنکھوں کی ٹھنڈک (ف۱۳۴) اور ہمیں پرہیزگاروں کا پیشوا بنا (ف۱۳۵)'),
 (93,25,75,'ان کو جنت کا سب سے اونچا بالا خانہ انعام ملے گا بدلہ ان کے صبر کا اور وہاں مجرے اور سلام کے ساتھ ان کی پیشوائی ہوگی (ف۱۳۶)'),
 (93,25,76,'ہمیشہ اس میں رہیں گے، کیا ہی اچھی ٹھہرنے اور بسنے کی جگہ،'),
 (93,25,77,'تم فرماؤ (ف۱۳۷) تمہاری کچھ قدر نہیں میرے رب کے یہاں اگر تم اسے نہ پوجو تو تم نے تو جھٹلایا (ف۱۳۸) تو اب ہوگا وہ عذاب کہ لپٹ رہے گا (ف۱۳۹)'),
 (93,26,1,'طٰسم'),
 (93,26,2,'یہ آیتیں ہیں روشن کتا ب کی (ف۲)'),
 (93,26,3,'کہیں تم اپنی جان پر کھیل جاؤ گے ان کے غم میں کہ وہ ایمان نہیں لائے (ف۳)'),
 (93,26,4,'اگر ہم چاہیں تو آسمان سے ان پر کوئی نشانی اتاریں کہ ان کے اونچے اونچے اس کے حضور جھکے رہ جائیں (ف۴)'),
 (93,26,5,'اور نہیں آتی ان کے پاس رحمٰان کی طرف سے کوئی نئی نصیحت مگر اس سے منہ پھیر لیتے ہیں (ف۵)'),
 (93,26,6,'تو بیشک انہوں نے جھٹلایا تو اب ان پر آیا چاہتی ہیں خبریں ان کے ٹھٹھے کی (ف۶)'),
 (93,26,7,'کیا انہوں نے زمین کو نہ دیکھا ہم نے اس میں کتنے عزت والے جوڑے اگائے (ف۷)'),
 (93,26,8,'بیشک اس میں ضرور نشانی ہے (ف۸) اور ان کے اکثر ایمان لانے والے نہیں،'),
 (93,26,9,'اور بیشک تمہارا رب ضرور وہی عزت والا مہربان ہے (ف۹)'),
 (93,26,10,'اور یاد کرو جب تمہارے رب نے موسیٰ کو ندا فرمائی کہ ظالم لوگوں کے پاس جا،'),
 (93,26,11,'جو فرعون کی قوم ہے (ف۱۰) کیا وہ نہ ڈریں گے (ف۱۱)'),
 (93,26,12,'عرض کی کہ اے میرے رب میں ڈرتا ہوں کہ مجھے جھٹلا ئیں گے،'),
 (93,26,13,'اور میرا سینہ تنگی کرتا ہے (ف۱۲) اور میری زبان نہیں چلتی (ف۱۳) تو توُ ہا رون کو بھی رسول کر، (ف۱۴)'),
 (93,26,14,'اور ان کا مجھ پر ایک الزام ہے (ف۱۵) تو میں ڈرتا ہو ں کہیں مجھے (ف۱۶) کر دیں،'),
 (93,26,15,'فرما یا یوں نہیں (ف ۱۷) تم دو نوں میری آئتیں لے کر جا ؤ ہم تمھا رے ساتھ سنتے ہیں (ف۱۸)'),
 (93,26,16,'تو فرعون کے پاس جاؤ پھر اس سے کہو ہم دونو ں اسکے رسل ہیں جو رب ہے سارے جہا ں کا،'),
 (93,26,17,'کہ تو ہما رے ساتھ بنی اسرائیل کو چھوڑ دے (ف۱۹)'),
 (93,26,18,'بو لا کیا ہم نے تمھیں اپنے یہاں بچپن میں نہ پالا اور تم نے ہما رے یہا ں اپنی عمر کے کئی برس گزارے، ف۲۰)'),
 (93,26,19,'اور تم نے کیا اپنا وہ کام جو تم نے کیا (ف۲۱) اور تم نا شکر تھے (ف۲۲)'),
 (93,26,20,'موسٰی نے فر ما یا میں نے وہ کام کیا جب کہ مجھے راہ کی خبر نہ تھی (ف۲۳)'),
 (93,26,21,'تو میں تمھا رے یہا ں سے نکل گیا جب کے تم سے ڈرا (ف۲۴) تو میرے رب نے مجھے حکم عطا فرمایا (ف۲۵) اور مجھے پیغمبروں سے کیا،'),
 (93,26,22,'اور یہ کوئی نعمت ہے جس کا تو مجھ پر احسان جتاتا ہے کہ تو نے غَلام بناکر رکھے بنی اسرائیل (ف۲۶)'),
 (93,26,23,'فرعون بولا اور سارے جہان کا رب کیا ہے (ف۲۷)'),
 (93,26,24,'موسیٰ نے فرمایا رب آسمانوں اور زمین کا اور جو کچھ ان کے درمیان میں ہے، اگر تمہیں یقین ہو (ف۲۸)'),
 (93,26,25,'اپنے آس پاس والوں سے بولا کیا تم غور سے سنتے نہیں (ف۲۹)'),
 (93,26,26,'موسیٰ نے فرمایا رب تمہارا اور تمہارے اگلے باپ داداؤں کا (ف۳۰)'),
 (93,26,27,'بولا تمہارے یہ رسول جو تمہاری طرف بھیجے گئے ہیں ضرور عقل نہیں رکھتے (ف۳۱)'),
 (93,26,28,'موسیٰ نے فرمایا رب پورب (مشرق) اور پچھم(مغرب) کا اور جو کچھ ان کے درمیان ہے (ف۳۲) اگر تمہیں عقل ہو (ف۳۳)'),
 (93,26,29,'بولا اگر تم نے میرے سوا کسی اور کو خدا ٹھہرایا تو میں ضرور تمہیں قید کردوں گا (ف۳۴)'),
 (93,26,30,'فرمایا کیا اگرچہ میں تیرے پاس کوئی روشن چیز لاؤں (ف۳۵)'),
 (93,26,31,'کہا تو لاؤ اگر سچے ہو،'),
 (93,26,32,'تو موسیٰ نے اپنا عصا ڈال دیا جبھی وہ صریح اژدہا ہوگیا (ف۳۶)'),
 (93,26,33,'اور اپنا ہاتھ (ف۳۷) نکالا تو جبھی وہ دیکھنے والوں کی نگاہ میں جگمگانے لگا (ف۳۸)'),
 (93,26,34,'بولا اپنے گرد کے سرداروں سے کہ بیشک یہ دانا جادوگر ہیں،'),
 (93,26,35,'چاہتے ہیں، کہ تمہیں تمہارے ملک سے نکال دیں اپنے جادو کے زور سے، تب تمہارا کیا مشورہ ہے (ف۳۹)'),
 (93,26,36,'وہ بولے انہیں ان کے بھائی کو ٹھہرائے رہو اور شہروں میں جمع کرنے والے بھیجو،'),
 (93,26,37,'کہ وہ تیرے پاس لے آئیں ہر بڑے جادوگر دانا کو (ف۴۰)'),
 (93,26,38,'تو جمع کیے گئے جادوگر ایک مقرر دن کے وعدے پر (ف۴۱)'),
 (93,26,39,'اور لوگوں سے کہا گیا کیا تم جمع ہوگئے (ف۴۲)'),
 (93,26,40,'شاید ہم ان جادوگروں ہی کی پیروی کریں اگر یہ غالب آئیں (ف۴۳)'),
 (93,26,41,'پھر جب جادوگر آئے فرعون سے بولے کیا ہمیں کچھ مزدوری ملے گی اگر ہم غالب آئے،'),
 (93,26,42,'بولا ہاں اور اس وقت تم میرے مقرب ہوجاؤ گے (ف۴۴)'),
 (93,26,43,'موسیٰ نے ان سے فرمایا ڈالو جو تمہیں ڈالنا ہے (ف۴۵)'),
 (93,26,44,'تو انہوں نے اپنی رسیاں اور لاٹھیاں ڈالیں اور بولے فرعون کی عزت کی قسم بیشک ہماری ہی جیت ہے، (ف۴۶)'),
 (93,26,45,'تو موسیٰ نے اپنا عصا ڈالا جبھی وہ ان کی بناوٹوں کو نگلنے لگا (ف۴۷)'),
 (93,26,46,'اب سجدہ میں گرے،'),
 (93,26,47,'جادوگر، بولے ہم ایمان لائے اس پر جو سارے جہان کا رب ہے،'),
 (93,26,48,'جو موسیٰ اور ہارون کا رب ہے،'),
 (93,26,49,'فرعون بولا کیا تم اس پر ایمان لائے قبل اس کے کہ میں تمہیں اجازت دوں، بیشک وہ تمہارا بڑا ہے جس نے تمہیں جادو سکھایا (ف۴۸) تو اب جاننا چاہتے ہو (ف۴۹) مجھے قسم ہے! بیشک میں تمہارے ہاتھ اور دوسری طرف کے پاؤں کاٹوں گا اور تم سب کو سولی دوں گا (ف۵۰)'),
 (93,26,50,'وہ بولے کچھ نقصان نہیں (ف۵۱) ہم اپنے رب کی طرف پلٹنے والے ہیں (ف۵۲)'),
 (93,26,51,'ہمیں طمع ہے کہ ہمارا رب ہماری خطائیں بخش دے اس پر کہ سب سے پہلے ایمان لائے (ف۵۳)'),
 (93,26,52,'اور ہم نے موسٰی کو وحی بھیجی کہ راتوں را ت میرے بندو ں کو (ف ۵۴) لے نکل بیشک تمھارا پیچھا ہو نا ہے، ف۵۵)'),
 (93,26,53,'اب فرعون نے شہروں میں جمع کرنے والے بھیجے (ف۵۶)'),
